-- 0289 naturaleza (inventario_naturaleza_pdf) — entidades + puntuaciones
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50001','espacio','Humedal de Ullíbarri-Gamboa (zona de cola) y riberas del río Alegría','Espacio lacustre modesto de gran interés ornitológico que funciona como corredor ecológico llanense. Destaca por sus saucedas riparias y carrizales que sirven de refugio estacional a avifauna migratoria.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50002','espacio','Cañón de Delika y Salto del Nervión (límite municipal)','Imponente cañón geológico excavado en roca caliza con paredes verticales de más de 200 metros de altura. Aloja el nacimiento del río Nervión, que genera una caída libre espectacular visible en épocas de deshielo o fuertes lluvias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01049','espacio','Diapiro de Salinas de Añana y Valle Salado','Fenómeno geológico excepcional provocado por la ascensión de materiales salinos antiguos hasta la superficie terrestre. El entorno natural destaca por sus manantiales hipersalinos y la singular flora halófila adaptada a este sustrato mineral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90263','espacio','Macizo de Anboto y Parque Natural de Urkiola','Entorno abrupto caracterizado por imponentes crestas calizas jurásicas y profundos valles atlánticos. Cuenta con densos bosques de hayas y encinares cantábricos que tapizan laderas de pendientes pronunciadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90264','espacio','Riberas del río Zadorra y Meandro de Armiñón','Tramo fluvial de aguas tranquilas encajado suavemente entre colinas margosas de la Rioja Alavesa. Su interés radica en la vegetación de ribera bien conservada, compuesta por chopos, sauces y fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50004','espacio','Parque Natural de Izki y Barranco de Izki','Impresionante cubeta geológica que alberga una de las mayores extensiones de robledal de marojo de toda Europa. El barranco excavado por el río muestra escarpes areniscos donde anidan valiosas rapaces rupícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50005','espacio','Embalse de Ullíbarri-Gamboa y Parque Provincial de Garaio','Vasto humedal artificial integrado perfectamente en el ecosistema de la Llanada Alavesa. Posee lenguas de agua, islas y orillas someras que acogen colonias permanentes de somormujos, garzas y ánades reales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50006','espacio','Encinar de Artziniega y laderas del monte Peñalba','Bosque relictual de encina cantábrica adaptado a los sustratos calizos expuestos de la vertiente cantábrica alavesa. El relieve es quebrado y ofrece una fisonomía de densa cobertura vegetal perennifolia atlántica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50007','espacio','Macizo de Aizkorri-Aratz y Cueva de Leze','Espectacular relieve kárstico que destaca por una gigantesca sima natural que atraviesa transversalmente la roca caliza de la montaña. Sus bosques asociados incluyen hayedos umbríos y canchales de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50009','espacio','Cola del Embalse de Ullibarri-Gamboa y Sierra de Elgea','Zona húmeda de transición con amplios carrizales y llanuras fangosas de gran importancia biológica. La sierra norteña aporta perfiles alomados con matorrales de brezales y repoblaciones forestales de coníferas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90939','espacio','Riberas del río Ayuda','Pequeño corredor fluvial mediterráneo encajonado entre campos agrícolas y pequeños cerros testigo. Conserva arbolado de ribera autóctono y pequeñas pozas estacionales de interés exclusivamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50011','espacio','Parque Natural de Izki y Sierra de Cantabria (Peña Karria)','Espacio de fuerte contraste entre el frondoso robledal del norte y los paredones calizos verticales del sur. Las crestas de la sierra actúan como frontera climática, exhibiendo una geomorfología escarpada soberbia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50012','espacio','Desfiladero del río Ega y Sierra de Codes','Cañón calizo labrado por el agua que separa crestas escarpadas con una transición vegetal abrupta. Coexisten encinares de carácter mediterráneo con hayedos de carácter atlántico en laderas umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50013','espacio','Humedal de Argómaniz','Modesta cubeta endorreica estacional situada en plena llanada agrícola. Posee un interés meramente local centrado en la observación puntual de aves acuáticas durante los pasos migratorios invernales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01022','espacio','Meandro del río Ebro en Elciego','Curvatura pronunciada del cauce fluvial que genera terrazas aluviales suaves y depósitos sedimentarios.   Destaca visualmente por el contraste entre el agua corriente y el relieve circundante de los escarpes yesosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50015','espacio','Desfiladero del río Bayas y Sierra de Arkamo','Cañón kárstico de dimensiones moderadas donde el río erosiona calizas mesozoicas. La sierra anexa es una gran plataforma elevada con lapiaces, dolinas y una cubierta vegetal de encinar y pastos secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01027','espacio','Montes de Iturrieta y nacedero del río Alegría','Meseta kárstica elevada caliza cubierta por pastizales y manchas dispersas de hayedos forestales. Destaca la fractura geológica de la plataforma calcárea, donde el agua se infiltra y genera pequeñas surgencias basales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50019','espacio','Puerto de Bernedo y Crestas de la Sierra de Cantabria','Paredón calizo imponente que sirve de divisoria climática neta entre el ambiente atlántico y el mediterráneo. Destaca por sus canchales, simas de montaña y comunidades vegetales rupícolas de gran interés botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50020','espacio','Cañón del río Bayas y Sierra de Badaia','Amplio valle kárstico flanqueado por dos murallas calcáreas horizontales erosionadas. El lecho del río Bayas corre encajado entre cortados calizos que albergan cuevas naturales y densos quejigares bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','espacio','Complejo Lagunar de Laguardia (Carralogroño, Carravalseca y Prao de la Paul)','Tres lagunas de origen endorreico y carácter salino estacional ubicadas en una cubeta geológica. Su biotipo alberga vegetación halófila e insectos singulares, siendo un enclave crucial para aves migratorias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01902','espacio','Lago de Caicedo-Yuso y desfiladero de Sobrón','El único lago natural permanente del País Vasco, originado por un colapso kárstico salino (diapiro). Su profundidad y entorno de encinar mediterráneo albergan comunidades acuáticas únicas en la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90940','espacio','Embalse de Urrunaga y laderas del monte Albertia','Paisaje hídrico rodeado de relieve boscoso de robledales y hayedos acidófilos cantábricos. Las bahías del embalse forman entrantes umbríos donde nidifican diversas especies de aves limícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01034','espacio','Puerto de Herrera y Balcón de la Rioja (entorno natural)','Escarpe rocoso vertical de la Sierra de Cantabria con densos bosques colgados de hayas y tejos solitarios. Destaca por los fenómenos de inversión térmica observables en su masa forestal de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01041','espacio','Lagunas estacionales de Navaridas','Pequeñas depresiones del terreno que acumulan agua de escorrentía superficial de forma intermitente. Albergan carrizales modestos y anfibios comunes, ofreciendo un valor ecológico estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50030','espacio','Valle del río Izalde y laderas del monte Ganekogorta','Entorno netamente cantábrico caracterizado por laderas boscosas empinadas y pequeños arroyos encajados. Cuenta con retazos bien conservados de bosque mixto atlántico con castaños, robles y alisos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50031','espacio','Riberas del río Grande y cerros yesosos','Paisaje semiárido de cerros erosionados por la escorrentía pluvial con presencia de yesificaciones. Alberga una rala vegetación esteparia y arbustiva adaptada a la escasez hídrica estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01044','espacio','Desfiladero del río Ayuda y hayedo de Loza','Cañón fluvial calizo estrecho con paredes verticales cubiertas de hiedra y vegetación rupícola. El hayedo umbrío adyacente madura sobre suelos calcáreos, salpicado de cuevas kársticas no acondicionadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01052','espacio','Crestas del monte Toloño','Formación geológica caliza de la Sierra de Cantabria que presenta crestas afiladas azotadas por el viento. Aloja comunidades florísticas alpinas relictas y formaciones de matorral almohadillado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50036','espacio','Cascada de Gujuli / Goiuri y Parque Natural de Gorbeia','Impresionante salto de agua vertical de más de 100 metros de altura provocado por el arroyo Oiardo al precipitarse sobre un escarpe calizo. El entorno forestal incluye hayedos maduros y ecosistemas kársticos profundos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50037','espacio','Parque Natural de Valderejo y Desfiladero del río Purón','Joya natural constituida por un estrecho desfiladero calizo horadado por el río Purón con saltos de agua y pozas turquesas. Las paredes rocosas albergan la colonia de buitre leonado más densa de la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50039','espacio','Humedales de Salburua y Montes de Vitoria','Magnífico complejo de lagunas eutróficas recuperadas sobre un antiguo acuífero de la llanada. Acoge   poblaciones importantes de visón europeo y una avifauna acuática diversa, complementado por los bosques meridionales de quejigos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01062','espacio','Desfiladero de Ocio (río Inglares)','Garganta caliza angosta jalonada por crestas rocosas singulares donde nidifican rapaces. El río Inglares mantiene una banda estrecha de vegetación riparia bien conservada en un entorno de transición climática.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50041','espacio','Parque Natural de Gorbeia (vertiente sur) y cuevas de Mairuelegorreta','Extenso macizo kárstico cubierto por densos hayedos y pastizales montanos. Alberga un sistema subterráneo de galerías naturales e importantes simas con formaciones de estalagmitas vivas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50042','espacio','Macizo de Gorbeia y Valle de Altube','Territorio de alta densidad forestal dominado por el hayedo de Altube, uno de los bosques atlánticos más bellos   de la región. El relieve presenta profundas laderas excavadas por ríos cristalinos con pequeños saltos de agua cascada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90820','espacio','Valle del río Júcar (zona de ribera) y paraje de los Pinos','Entorno semiárido roto por una modesta llanura aluvial con depósitos de gravas y arenas. Destaca visualmente por el contraste entre los cultivos de secano y la vegetación riparia de chopos y álamos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90337','espacio','Barranco del Agua y cerro de la Virgen','Estructura de erosión excavada en relieves calcáreos y margosos típicos de la transición a la meseta. Presenta formaciones de cárcavas y matorrales mediterráneos adaptados a la escasez hídrica estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02001','espacio','Paraje natural de la Pulgosa y riberas del Canal de María Cristina','Extensa llanura manchega rota por pinadas de pino carrasco asentadas sobre suelos limosos. Su interés radica en el ecosistema estepario circundante y la vegetación acuática asociada al canal de drenaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90338','espacio','Paraje del Molino de Arriba y cerros de yesos','Depresión endorreica con afloramientos subdesérticos de yesos y arcillas triásicas. Posee una rala cubierta vegetal halófila y matorrales gipsícolas de alto valor botánico pero bajo impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02002','espacio','Sabinar de Alcadozo y cañón del río Mundo (límite)','Densas agrupaciones relictas de sabina albar integradas en relieves calcáreos alomados. El relieve quebrado ofrece un paisaje vegetal perennifolio adaptado a inviernos extremos y veranos secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02003','espacio','Hoz del río Júcar y cuevas naturales del Tragaluz y del Diablo','Espectacular y profundo cañón fluvial meandriforme excavado en rocas calizas del Cretácico. Sus imponentes paredes verticales albergan cuevas de origen kárstico colgadas sobre las aguas turquesas del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02004','espacio','Sierra de Alcaraz, Microrreserva de la Estrecha y nacedero del río del Jándula','Relieve montañoso abrupto con calizas jurásicas, profundos valles e imponentes calares calcáreos. Alberga frondosos bosques mixtos con robles, acebos y tejos relictos de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02005','espacio','Pantano de Almansa y Sierra de Almansa','Histórico embalse encajonado entre cerros calizos con relieves de transición hacia el levante. El entorno forestal destaca por sus pinares xerófilos y escarpes rocosos donde anidan rapaces menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90821','espacio','Sierra de Alpera y paraje de la Fuente de la Carrasca','Formaciones montañosas de altitud moderada cubiertas de encinar maduro y manchas de pino laricio. Presenta pequeños lapiaces superficiales y dolinas kársticas dispersas en las zonas más elevadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02006','espacio','Cañón del río Mundo y Cueva del Niño','Imponente garganta kárstica con paredes verticales de roca caliza que superan los 300 metros de altura. El fondo del desfiladero alberga una frondosa vegetación de ribera que contrasta con los farallones áridos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02007','espacio','Riberas del río Balazote (o Don Juan) y cerro del Cuco','Valle aluvial encajado entre terrazas cuaternarias de sedimentación arcillosa. La banda fluvial conserva formaciones densas de enea, carrizos y sauces que actúan como corredor biológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90340','espacio','Cañón del río Cabriel (Reserva de la Biosfera de los Valles de Cabriel)','Profunda incisión fluvial con impresionantes cortados rocosos y meandros encajonados en calizas cenozoicas. Sus aguas transparentes corren flanqueadas por una vegetación riparia virgen de gran valor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90341','espacio','Humedal estacional de la Ojos de la Nava','Modesta cubeta endorreica estepa que acumula agua de escorrentía superficial de forma intermitente. Alberga carrizales menores de interés local para el refugio estacional de avifauna limícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90342','espacio','Sierra de Alcaraz y paraje del Nacimiento del río de la Mesta','Vertientes montañosas escarpadas cubiertas de densos pinares de pino negral y encinares de montaña. Cuenta con nacimientos de agua cristalina bajo los escarpes calizos de la cuerda de la Almenara.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90343','espacio','Cañón del río Bogarra (o Madera) y el Batán','Estrecha hoz fluvial flanqueada por verticales de caliza con abundantes saltos de agua y pozas naturales. Destaca por sus bosques de ladera con pinos laricios y quejigos en las umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90344','espacio','Sabinar degradado de Bonete y cerros testigos','Meseta caliza de carácter continental árido con ejemplares dispersos de sabina albar centenaria. El paisaje muestra llanuras deforestadas y pequeñas lomas calcáreas de interés geobotánico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90345','espacio','Muela de Carcelén y barranco del Agua','Altiplanicie caliza o muela con impresionantes cortados perimetrales fruto de la erosión diferencial. Las laderas albergan pedrizas, canchales y densas masas forestales de pino negral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90346','espacio','Barranco de la Cueva y llanuras del Júcar','Relieve quebrado por cárcavas de erosión pluvial sobre arcillas, margas y yesos blandos. Presenta matorrales mediterráneos xerófilos y sotos fluviales en regresión de valor puramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90347','espacio','Valle del río Montemayor y Sierra de Alcaraz (estribaciones)','Curso fluvial de montaña media encajonado entre lomas cubiertas de encinar y pinar de repoblación. Sus aguas limpias sustentan comunidades óptimas de trucha común y vegetación riparia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90348','espacio','Cañón del río Júcar (embalse de Molinar)','Imponente tajo fluvial donde el río se encajona entre paredes calcáreas de gran verticalidad. El paisaje destaca por el contraste tectónico de la meseta rota y el cauce hídrico encajado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02008','espacio','Riberas del río Cabriel (paraje de la Terrera)','Taludes arcillosos y escarpes calizos labrados por el río Cabriel en el límite provincial. Ofrece amplias   panorámicas visuales de formaciones de erosión y masas boscosas de pino carrasco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02009','espacio','Sierra de Santa Bárbara y microrreserva de los Arenales de Caudete','Relieve subárido con formaciones dunares continentales eólicas de gran rareza geológica en la región. Alberga comunidades botánicas psammófilas adaptadas a vivir sobre sustratos de arena móvil.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90349','espacio','Barranco del Salobral','Pequeña incisión torrencial sobre el llano de la Manchuela con afloramientos margosos menores. Cuenta con matorrales áridos de romero y tomillo con un valor paisajístico estrictamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02010','espacio','Sierra de Chinchilla y Lagunas de la Felipa','Elevación caliza escarpada que domina la llanura manchega junto a pequeñas lagunas endorreicas de aguas salobres. Sus masas forestales son pinares xerófilos que coronan los cerros testigo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90350','espacio','Complejo Lagunar de Corral-Rubio','Excepcional conjunto de lagunas endorreicas e hipersalinas de carácter estacional. Sus cuencas albergan costras de sal veraniegas y una flora halófila de altísimo interés botánico y paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90351','espacio','Sierra de las Villas y nacedero del río Cotillas','Paisaje de alta montaña mediterránea integrado en las estribaciones de Cazorla y Segura. Abundan los nacimientos de agua cristalina, torrenteras y densos bosques de pino laricio sobre calizas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90352','espacio','Navas de El Bonillo y Sabinar de las Navas','Humedales calizos estacionales (navas) integrados en una inmensa llanura adehesada de sabina albar. Es un ecosistema único por la pureza de sus masas arbóreas perennifolias continentales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90822','espacio','Lagunillas de El Ballestero y dehesa de encinas','Pequeñas depresiones kársticas inundables que retienen el agua durante los deshielos primaverales. El paisaje está dominado por encinares adehesados maduros asentados sobre calizas horizontales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02013','espacio','Cañón del río Segura (embalse del Cenajo)','Desfiladero rocoso de gran envergadura excavado por el Segura entre peñas y escarpes calcáreos. Las laderas presentan una densa cobertura de matorral mediterráneo y pinares colgados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02032','espacio','Riberas del río Júcar','Tramo de aguas tranquilas que divaga por la llanura formando meandros llanos y playas de gravas. Conserva una franja modesta de bosque de galería con chopos, sauces y mimbreras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02033','espacio','Sierra del Cerrón y lagunas endorreicas menores','Cerros calizos redondeados cubiertos de espartizales y romerales típicos del ombroclima seco. Posee pequeñas cubetas de escorrentía superficial de valor ecológico centrado en la biodiversidad local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02034','espacio','Paraje del Galayo y rambla de la Cañada','Depresión erosiva con afloramientos salinos y yesíferos de origen triásico (Keuper). Su interés radica en las formaciones geológicas de arcillas de colores y vegetación halófila asociada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02036','espacio','Cañada de Golosalvo','Llano cerealista surcado por una vaguada de escorrentía estacional sin relieve destacable. Cuenta con rodales muy dispersos de encinas encajadas de interés puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02014','espacio','Cañón de los Almadenes (río Mundo) y pitón volcánico de Cancarix','Espectacular pitón volcánico de roca ultrapotásica (lamproíta) declarado monumento natural por su singularidad geológica. Se complementa con el profundo desfiladero calcáreo del río Mundo antes de su desembocadura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02038','espacio','Laguna de la Herrera','Humedal endorreico de aguas someras que constituye una reserva ornitológica de gran valor en la provincia. Acoge comunidades de aves palustres y flora acuática adaptada a la estacionalidad hídrica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02039','espacio','Sierra de Higueruela y balsa de la Higuera','Relieve alomado dominado por aerogeneradores con masas de encinar termófilo y pino carrasco. Presenta pequeñas surgencias de agua estacionales de interés exclusivamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02040','espacio','Cerros de la Hoya y barranco de la Losa','Paisaje de transición caliza con relieves tabulares suaves sometidos a intensa erosión eólica. Alberga   matorrales áridos calcícolas y romerales de baja cobertura vegetal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02041','espacio','Meandros encajonados del río Júcar','Impresionante garganta fluvial donde el Júcar dibuja curvas cerradísimas cortando la plataforma calcárea. El relieve ofrece impresionantes paredes verticales y taludes margosos de gran plasticidad visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02066','espacio','Valle del Júcar y barranco de la Virgen','Cañón fluvial jalonado por huertas tradicionales e imponentes escarpes de roca caliza blanquecina. El río mantiene un caudal constante flanqueado por densas choperas de gran belleza otoñal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02016','espacio','Garganta del río Segura, cascada del Charco Pataco y Sierra del Calar del Mundo','Escarpado relieve kárstico donde abundan las pozas naturales, cascadas cristalinas y profundos barrancos calcáreos. La vegetación incluye bosques de ribera vírgenes colgados sobre la roca caliza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02043','espacio','Nacimiento del río Lezuza y laderas calizas','Valle de cabecera fluvial con surgencias de agua someras entre formaciones calcáreas mesozoicas. El entorno cuenta con pequeños sotos de sauces y álamos flanqueados por cultivos de secano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02044','espacio','Hoz del río Mundo y escarpes calizos de Liétor','Espectacular encajonamiento del río Mundo que labra cortados calizos verticales de gran audacia geomorfológica. Las laderas están cubiertas de densos olivares antiguos, pinares y matorral rupícola mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02045','espacio','Paraje de la Cañada e hilera fluvial del río Júcar (límite)','Llanura aluvial degradada con cultivos intensivos que limitan con los taludes del valle del Júcar. Su interés natural es bajo y de rango estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02046','espacio','Barranco del Júcar y paraje de la Fuente del Espino','Cortados calizos menores en el margen del cañón del Júcar con presencia de fuentes kársticas estacionales. Muestra pinares de pino carrasco adaptados a suelos rocosos de solana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02048','espacio','Llanura estepa de Minaya','Paisaje horizontal manchego absoluto con ausencia de relieve o cursos de agua permanentes. Posee interés biológico únicamente por la presencia estacional de avifauna esteparia (avutardas).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02049','espacio','Parque Natural de los Calares del Mundo y de la Sima, y valle del río Mundo','Impresionante relieve montañoso kárstico con calares escarpados, dolinas de colapso y profundos barrancos forestales. Alberga magníficos bosques de pino laricio y encinares de alta montaña mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02050','espacio','Riberas del río Júcar (límite municipal)','Tramo fluvial llano donde el río discurre sin encajonarse por la llanura manchega. Presenta sotos riparios muy antropizados de interés exclusivamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02017','espacio','Sierra del Arabí (estribaciones) y Llano de la Consolación','Relieve calizo con formaciones de erosión eólica alveolares (taffonis) y abrigos rocosos. La vegetación está compuesta por pinares ralos de pino carrasco y espartizales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02052','espacio','Cuchillos del río Júcar (límite)','Formaciones geológicas de erosión lineal que generan crestas afiladas en las calizas marginales del Júcar. El cauce fluvial aporta un corredor verde visible desde la llanura superior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02053','espacio','Nacimiento del río Córcoles y riberas del Ojuelo','Humedal de cabecera fluvial típico de la meseta con turberas y tablas de agua someras. Acoge comunidades vegetales palustres y avifauna acuática de forma estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02054','espacio','Navas de Jorquera (depresiones inundables)','Pequeñas cubetas arcillosas de drenaje endorreico que acumulan agua de lluvia de manera intermitente. Carecen de relieve y su interés es puramente agrícola y ecológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02018','espacio','Cañón del río Taibilla, Sierra de las Cabras y nogal gigantesco del Plantón del Covacho','Territorio de alta montaña subbética con picos que rozan los 2.000 metros de altitud y profundas gargantas.   Alberga el Monumento Natural del Plantón del Covacho y masas forestales relictas de alta biodiversidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02056','espacio','Sierra del Madroño y embalse de Ontur','Alineación montañosa caliza cubierta por pinares de pino carrasco y matorrales termófilos. El pequeño embalse artificial actúa como punto de concentración de avifauna en un entorno árido.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02019','espacio','Parque Natural de las Lagunas de Ruidera (Lagunas Tomilla, Tinaja, San Pedro, Redondilla y Lengua) y Cueva de Montesinos','Extraordinario complejo lagunar cárstico único en Europa por sus barreras de toba o travertinos que embalsan el agua en cascadas sucesivas. La cueva de Montesinos es una cavidad natural excavada en calizas magnas del Jurásico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02020','espacio','Sierra de Alcaraz, valles de los ríos Madera y Endrinales, y Calar de la Osera','Excepcional entorno forestal alpino dominado por inmensas masas de pino laricio y acebedas umbrías. Sus ríos cristalinos corren encajados entre escarpes calizos y formaciones de toba caliza vivas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02060','espacio','Peña de San Pedro y Sierra del Sahúco','Impresionante cerro testigo o inselberg calizo con paredes verticales que se eleva abruptamente sobre el llano. La sierra adyacente presenta valles sinclinales colgados cubiertos de encinares maduros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02021','espacio','Sierra de Alcaraz, Pino del Toril y río Arquillo','Paisaje forestal de alta montaña donde destaca el Pino del Toril, ejemplar monumental de pino laricio de proporciones gigantescas. El río Arquillo genera lagunas kársticas y estrechos desfiladeros calizos calcáreos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02061','espacio','Laguna Salada de Pétrola','Gran laguna endorreica hipersalina que constituye uno de los humedales más importantes de la Península para la reproducción del flamenco rosa. Sus orillas exhiben costras salinas y comunidades halófilas raras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02062','espacio','Dehesas de Povedilla y estribaciones de Sierra Morena','Suave relieve alomado silíceo cubierto por magníficas dehesas de encina y quejigo que enlazan con el entorno andaluz. Es un hábitat óptimo para fauna mediterránea mayor y aves rapaces ibéricas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02901','espacio','Laguna de la Sierrezuela y cerros calizos menores','Pequeña balsa endorreica de carácter estacional en un entorno dominado por cerros de matorral degradado. Su interés es de rango local y centrado en los pasos migratorios de aves acuáticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02064','espacio','Valle de Pozo-Lorente y pinares de la Manchuela','Depresión topográfica suave rodeada por extensas masas compactas de pino carrasco de repoblación. Ofrece una fisonomía forestal homogénea sobre suelos calcáreos llanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02022','espacio','Complejo endorreico de Pozohondo (Laguna Navajuelo)','Cuencas endorreicas estacionales situadas en una llanura elevada de naturaleza caliza. Presentan periodos de desecación estival absoluta que exponen suelos arcillosos agrietados de valor ecológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02065','espacio','Cañada del Pozuelo y encinares dispersos','Paisaje llano manchego con suaves ondulaciones del terreno cubiertas por rodales relictos de encina centenaria. Su valor natural es de rango comarcal como refugio de avifauna estepa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02023','espacio','Parque Natural de los Calares del Mundo y de la Sima, Nacimiento del Río Mundo (Los Chorros) y Cueva de los Chorros','Una de las joyas biológicas y geológicas de España; el río brota de una colosal cueva en un farallón vertical de 200 metros, cayendo en cascadas espectaculares. La cueva posee kilómetros de galerías subterráneas activas y el calar presenta un modelado kárstico alpino insuperable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02068','espacio','Microrreserva de la Laguna de Ojos de Villaverde y río Arquillo','Humedal de origen kárstico alimentado por aguas subterráneas con un excelente cinturón de vegetación palustre (carrizos, eneas, juncos). Es un enclave crucial para la nidificación de aves acuáticas y conservación de odonatos.   Ródenas (Socovos - ver Socovos más abajo).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02070','espacio','Estrecho del río Salobre y laderas forestales','Desfiladero angosto excavado por el río Salobre entre peñascos calizos escarpados de la Sierra de Alcaraz. El curso fluvial está flanqueada por una densa vegetación de alisos, sauces y fresnos hidrófilos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02071','espacio','Nacimiento del río Quéjola y Sierra de la Quéjola','Cabecera fluvial de aguas limpias rodeada de relieves alomados cubiertos de encinares y pinares de pino negral. El valle ofrece una fisonomía de media montaña de transición bien conservada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02024','espacio','Sierra de la Muela, arroyo de Benizar y embalse de Taibilla','Paisaje abrupto subbético caracterizado por extensas masas boscosas de pinos y profundas ramblas mediterráneas de agua intermitente. Los escarpes calcáreos de la Muela ofrecen nidos naturales para grandes águilas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02073','espacio','Valle del río Valdemembra y riberas del Júcar','Desembocadura del río Valdemembra en el Júcar formando llanuras aluviales suaves y taludes de erosión limosa. Mantiene choperas densas de gran desarrollo lineal en un entorno intensamente agrícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02025','espacio','Laguna de Alboraj y microrreserva de los Saladares de Cordovilla','Laguna kárstica permanente de aguas salobres y gran profundidad flanqueada por escarpes yesosos. Los saladares adyacentes albergan comunidades vegetales halófilas endémicas extremedamente raras en Europa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02075','espacio','Hoz del río Júcar en Valdeganga','Tramo donde el Júcar comienza su profundo encajonamiento en la plataforma caliza de la Manchuela. El relieve muestra taludes escarpados verticales de toba con abundantes surgencias de agua y fuentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02076','espacio','Calar de Vianos (Parque Natural de los Calares del Mundo y de la Sima)','Inmensa plataforma caliza elevada a más de 1.500 metros de altitud que exhibe un paisaje lunar de lapiaces, dolinas y uvalas kársticas. Sus bordes caen en picado formando imponentes farallones rocosos sobre los valles forestales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02077','espacio','Cañón del río Júcar y Embalse de Villa de Ves','Garganta fluvial de sobrecogedora verticalidad con paredes calizas que encierran las aguas verdosas del embalse. El relieve kárstico es abrupto y agreste, dominado por buitreras y pinos colgados de las rocas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02078','espacio','Sotos del río Júcar y pinar de San Isidro','Valle fluvial ancho con vegas aluviales cubiertas de densos bosques de galería compuestos por chopos negros y sauces. Ofrece una fisonomía verde y fresca contrastada con el secano manchego.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02026','espacio','Cañón del río Cabriel, paraje de los Cárceles y cola del embalse de Contreras','Impresionante límite provincial marcado por los cortados de roca del río Cabriel, uno de los cursos más limpios de Europa. El relieve quebrado presenta formaciones de erosión singulares y frondosos pinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02080','espacio','Sierra de Alcaraz y cuenca del río Guadalmena','Relieve de media montaña caliza con profundos barrancos cubiertos de densos bosques mediterráneos de encinas, quejigos y madroños. El río Guadalmena corre limpio formando pozas naturales entre rocas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02027','espacio','Riberas del río Córcoles y paraje de la Pasadilla','Humedales riparios someros integrados en la gran llanura vitivinícola de la Mancha. El río mantiene tablas de agua con carrizales densos que sirven de refugio a avifauna estepa y acuática.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02082','espacio','Balneario de Fuente Podrida (entorno natural del río Cabriel)','Frondoso valle fluvial donde el río Cabriel corre limpio entre laderas calizas cubiertas de espeso bosque mediterráneo. Destaca por sus fuentes termales sulfurosas y la excelente conservación de su bosque ripario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02028','espacio','Vallejo del río Júcar (límite) y lomas calizas','Terreno alomado cubierto de matorral esclerófilo bajo que desciende suavemente hacia la cuenca del Júcar. Su interés geomorfológico y botánico es modesto, de carácter puramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02030','espacio','Parque Natural de los Calares del Mundo y de la Sima, Valle del río Segura, Calar de la Sima y Monte Ardal','Uno de los epicentros de la naturaleza albaceteña; destaca por el majestuoso Calar de la Sima, un altiplano kárstico alpino imponente. El Segura y el Tus labran cañones colosales entre bosques vírgenes de pinos laricios, tejos y acebedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03001','espacio','Cárcavas del Keuper y escarpes de la Sierra del Ventós','Impresionante paisaje de cárcavas de colores arcillosos y yesíferos erosionados por lluvias torrenciales. Los cortados áridos de la sierra ofrecen una fisonomía subdesértica de gran nitidez geológica.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90378','espacio','Parque Natural de la Sierra de Mariola y Barranc de l''Asutxe','Ladera umbría montañosa calcárea tapizada por una de las mayores densidades de plantas medicinales de Europa. Alberga frondosos bosques de tejos relictos y fresnos de flor en un relieve quebrado escarpado.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90852','espacio','Sierra de Cabeçó d''Or (vertiente este) y barranco del Paisano','Relieve calizo árido con matorrales xerófilos mediterráneos termófilos dominados por el esparto y el   romero. Muestra procesos de erosión lineal torrencial de interés paisajístico comarcal. Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90379','espacio','Rambla Salada y Sierra de Albatera','Profundo cañón desértico con formaciones geológicas de sal gema y costras salinas relucientes. Paredes rocosas verticales y escarpadas cobijan comunidades de aves rapaces adaptadas a la extrema aridez.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90380','espacio','Coll de Rates (estribaciones) y riberas del río Gorgos','Valle prepirenaico modelado por un curso fluvial de carácter torrencial intermitente sobre lecho calcáreo. Las laderas muestran una vegetación rala de matorral noble mediterráneo con algarrobos antiguos.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90853','espacio','Riberas del río Serpis y barranco del Sofre','Tramo aluvial encajado suavemente entre colinas margosas del interior de la provincia. Mantiene una banda modesta de vegetación riparia con cañaverales y sauces blancos de interés local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90406','espacio','Barranco de Alcolea y estribaciones de Sierra Nevada','Relieve alpujarreño quebrado por profundos tajos excavados sobre terrazas de conglomerados y arcillas. Las laderas expuestas muestran una rala vegetación mediterránea, matorrales xerófilos y olivares antiguos integrados en el paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','espacio','Parque Natural del Carrascal de la Font Roja y Barranc del Cint','Uno de los bosques de encina (carrascal) mejor conservados y más espectaculares de la Comunidad Valenciana. El Barranc del Cint es una imponente e inverosímil fractura geológica con paredes verticales calizas colosales.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46022','espacio','Sierra de Mariola (vertiente norte) y Barranc de l''Alpadull','Paisaje forestal umbrío calcáreo con cuevas naturales excavadas por la erosión kárstica en la roca. Destaca por la riqueza botánica de sus laderas y las surgencias de agua cristalina estacionales.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90009','espacio','Parque Natural de la Serra Gelada (Punta de l''Albir) y acantilados marinos','Colosales acantilados fósiles que superan los 400 metros de altura sobre el mar Mediterráneo. Muestra una geomorfología de dunas colgadas doliíticas y una vegetación adaptada a la salinidad extrema.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90854','espacio','Cerros del l''Escorrat y llanura del río Segura','Suaves ondulaciones margosas muy antropizadas lindando con la llanura de inundación aluvial baja del Segura. Su vegetación es escasa y residual, poseyendo un interés estrictamente local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90381','espacio','Sierra de la Peña de la Zafra','Alineación caliza árida que marca la transición paisajística hacia las estepas de la Región de Murcia. Alberga matorrales xerófilos ralos, espartizales y pinos carrascos solitarios sobre suelos esqueléticos.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','espacio','Isla de Tabarca (Reserva Marina), Cabo de la Huerta y Monte Orgegia','Primera reserva marina declarada en España, con praderas sumergidas de Posidonia oceanica excepcionales. El Cabo de la Huerta muestra calas rocosas de abrasión marina fosilífera de gran interés geológico.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90382','espacio','Meandros del río Segura (tramo bajo)','Cauce fluvial totalmente canalizado e integrado en la huerta tradicional de la Vega Baja. Presenta un valor natural relictual limitado a las comunidades de caña común palustre.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90383','espacio','Sierra de la Solana y barranco de Mas de la Penya','Crestas calcáreas expuestas al sol con matorrales mediterráneos heliófilos como el tomillo y la aliaga. El relieve quebrado ofrece panorámicas estructurales de los valles del Comtat.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90855','espacio','Riberas del río Serpis','Pequeño tramo fluvial muy aprovechado históricamente por la industria y la agricultura. Mantiene comunidades vegetales aluviales comunes de sauces y chopos de rango puramente local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03004','espacio','Desembocadura del río Algar y acantilados de la Isla de Altea','Humedal costero de gran valor ornitológico donde el río Algar forma un estuario de gravas. Los islotes rocosos adyacentes muestran formaciones de erosión marina marina notables.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03005','espacio','Paraje Natural Municipal de los Algezares (río Tarafa)','Paisaje árido surcado por el río Tarafa con espectaculares afloramientos de yesos (algezares) del Triásico. La vegetación está especializada en suelos salinos y gipsícolas de alto valor ecológico regional.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90384','espacio','Els Els Caixers (formaciones rocosas) y barranco de Bella','Singulares agujas y callejones rocosos calizos esculpidos por la erosión kárstica y el viento. Ofrece una fisonomía geológica ruiniforme a pequeña escala rodeada de olivos.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90385','espacio','Nacimiento del río Frainos y laderas de la Sierra de Aitana','Fuentes de montaña de aguas frías rodeadas de una masa forestal dispersa de encinas. El relieve asciende en vertientes de fuerte pendiente cubiertas de pedrizas calizas finas.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90856','espacio','Sierra de Beneixama (o de la Solana)','Extensa masa boscosa forestal dominada por el pino carrasco y un denso sotobosque mediterráneo de lentiscos. Su relieve alomado actúa como regulador hídrico de la cabecera del río Vinalopó.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90386','espacio','Sierra de Benejúzar (Pilar de la pinada)','Pequeño relieve testimonial calcáreo-arenoso cubierto por una pinada de repoblación en medio de la llanura. Ofrece un pulmón verde con suelos erosionados de interés estrictamente local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90387','espacio','Barranco del Infierno (tramo bajo) y cerros áridos','Paisaje árido de lomas bajas arcillosas desprovistas de cobertura forestal significativa. Su interés estriba en las formas de erosión pluvial torrencial de rango meramente comarcal.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90388','espacio','Riberas del río Girona','Cauce fluvial mediterráneo ancho y pedregoso que permanece seco la mayor parte del año. Conserva sotos degradados y adelfares adaptados a las avenidas torrenciales estacionales.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90389','espacio','Embalse de Guadalest y vertientes de la Sierra de la Solana','Espectacular lámina hídrica de color turquesa encajonada entre los imponentes relieves calizos de Aitana y Serrella. Las laderas forestales presentan cortados calizos calcáreos de gran valor estético.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90390','espacio','Embalse de Beniarrés y desfiladero del río Serpis','Vasto cañón fluvial donde el río Serpis corta las estructuras montañosas calcáreas con fuerza erosiva. El embalse recoge las aguas rodeado de relieves de pinadas densas y matorrales.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90391','espacio','Cueva de las Calaveras (entorno natural)','Cavidad kárstica natural de gran desarrollo horizontal abierta en calizas del Cretácico. Presenta interés geológico por sus formas de disolución y depósitos sedimentarios interiores fósiles.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03007','espacio','Isla de Benidorm y vertiente sur del Parque Natural de la Serra Gelada','El islote rocoso es un icónico relieve emergido con escarpes colonizados por aves marinas raras como el paíño común. La Serra Gelada muestra dunas fósiles trepadoras de altísima singularidad geomorfológica.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90392','espacio','Sierra de Rontonar','Prolongación caliza del carrascal de la Font Roja con relieves abruptos cubiertos de encinares y quejigares. Cuenta con simas naturales profundas y lapiaces de disolución superficial.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90393','espacio','Sierra de Aitana (Font de la Forata) y Els Clots','Sector culminal de la provincia con espectaculares simas de colapso y fuentes calcáreas alpinas.   Alberga comunidades botánicas de alta montaña relictas y farallones rocosos inaccesibles. Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90394','espacio','Sierra de la Serrella y Barranc de l''Infern (cabecera)','Paisaje agreste dominado por imponentes crestas calizas bautizadas como los "Pirineos alicantinos". Sus barrancos albergan microrreservas de flora con endemismos rupícolas únicos en el mundo.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90395','espacio','Meandro del río Segura y Soto de Benijófar','Llanura de inundación fluvial baja muy modificada por encauzamientos artificiales contemporáneos. Mantiene un interés ecológico residual limitado a la avifauna palustre común.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90396','espacio','Farga del río Frainos y salto de agua natural','Pequeño cañón fluvial excavado sobre sustratos margosos donde el río genera saltos de agua y pozas de disolución. Entorno umbrío de interés geobotánico local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90397','espacio','Barranc de Caraita','Profunda incisión erosiva en materiales arcillosos y margosos que crea un paisaje de cárcavas inestables. Su valor es geomorfológico a escala comarcal, destacando su extrema aridez visual.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90398','espacio','Sierra de Aitana (vertiente norte) y barranco de Mela','Vertientes abruptas con grandes desniveles y canchales de piedras calizas sueltas. El barranco de Mela ofrece estrechos estrechos calizos de erosión hídrica esculpidos con plasticidad visual.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90399','espacio','Barranc del Sofre y fuentes termales naturales','Pequeño curso torrencial caracterizado por emanaciones de aguas sulfurosas naturales en un entorno agrícola. Su vegetación es carrizal y matorral mediterráneo de valor local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03008','espacio','Sierra de la Serrella y paraje de Les Formigues','Espectaculares monolitos calizos exentos y agujas rocosas que se elevan verticalmente como vigías del valle. El entorno presenta una gran pureza paisajística de montaña caliza mediterránea.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90400','espacio','Sierra de Segària (vertiente norte)','Cresta caliza lineal que emerge de forma abrupta de la llanura aluvial costera. Presenta matorral noble mediterráneo xerófilo y oquedades kársticas menores de rango comarcal.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03009','espacio','Acantilados de la costa de Benissa y Cabo d''Or (límite)','Costa escarpada no-playa con impresionantes perfiles rocosos tallados por el oleaje marino. Alberga microrreservas de flora marina rupícola con endemismos costeros valiosos.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03043','espacio','Sierra de Biar y paraje de la Fontanella','Vasta masa forestal umbría dominada por pinos laricios y encinas bien estructuradas. El relieve presenta lapiaces, pequeñas cuevas y fuentes tradicionales que surten al acuífero local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03044','espacio','Paraje Natural Municipal de la Pedrera','Relieve alomado calizo residual cubierto por pinares de pino carrasco de repoblación junto a un pequeño embalse regularizador. Su valor es recreativo y de conservación estrictamente comarcal.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03045','espacio','Barranc de l''Estret y nacimiento del río Bolulla','Angostísimo desfiladero calizo con paredes verticales pulidas por el flujo de aguas limpias y permanentes. Forma pozas naturales profundas y saltos de agua encajados de gran espectacularidad.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03046','espacio','Sierra de Cabeçó d''Or y Cuevas de Canelobre (entorno)','Imponente mole caliza jurásica que alberga en su interior una de las cavidades kársticas con las bóvedas   más altas de España. El relieve exterior destaca por crestas afiladas e inhóspitas. Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03048','espacio','Fuentes del Algar (Les Fonts de l''Algar)','Espectacular monumento natural hídrico donde el río Algar brota en potentes manantiales kársticos. Genera una sucesión de saltos de agua, canales rocosos y pozas profundas de aguas cristalinas calizas.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03049','espacio','Sierra de Callosa (Paraje Natural Municipal)','Macizo calizo escarpado que surge de forma vertical y tectónica de la llanura de la huerta. Posee paredes rocosas abruptas desprovistas de bosque pero ricas en fauna rupícola menor.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03010','espacio','Parque Natural del Peñón de Ifach y Salinas de Calpe','Colosal mole calcárea de 332 metros de altura unida a tierra por un tómbolo arenoso, icono de la costa. Las salinas adyacentes son una antigua laguna marina que acoge densas colonias de flamencos.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03015','espacio','Illeta dels Banyets (entorno rocoso) y acantilados de Coveta Fumà','Plataforma costera rocosa de abrasión marina que muestra los efectos del oleaje sobre areniscas calcáreas. Conserva una escasa pero valiosa vegetación litoral halófila mediterránea.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03052','espacio','Pinar de la Sierra de la Villa (límite)','Pequeña estribación forestal dominada por pinares de pino carrasco sobre sustratos calizos degradados. Ofrece un paisaje vegetal homogéneo de valor paisajístico meramente comarcal.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03011','espacio','Sierra del Catí y hondo de Formiga','Vasto espacio forestal de montaña media con densas masas de pino carrasco, encinas y robles dispersos. El relieve kárstico incluye simas y pequeñas depresiones endorreicas boscosas de valor biológico.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03054','espacio','Els Arcs (Monumento Natural), Peña de Altea y Serrella','Formación geológica monumental consistente en gigantescos arcos de piedra caliza esculpidos por disolución kárstica. El entorno montañoso es salvaje, jalonado de profundos barrancos y canchales alpinos.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03055','espacio','Parque Natural de El Hondo (vertiente sur)','Humedal de importancia internacional (RAMSAR) constituido por grandes lagunas someras de aguas salobres. Es un paraíso ornitológico con inmensos carrizales donde anidan aves acuáticas en peligro de extinción.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03012','espacio','Sierra de Mariola (pico Montcabrer) y Barranc de la Boronassa','Macizo calcáreo imponente que constituye el techo de Mariola, con grandes paredes de roca caliza expuestas. Alberga tejos solitarios, fresnedas de ladera y fuentes kársticas perpetuas de gran caudal.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03057','espacio','Sierra de la Aitana (pico Aitana - 1558m) y nacedero del río Guadalest','Techo de la provincia de Alicante, caracterizado por una imponente cordillera caliza con farallones verticales de falla tectónica. Las umbrías albergan microbosques de arces, fresnos y espectaculares fuentes alpinas.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03058','espacio','Sierra de Callosa (vertiente este)','Escarpe calizo desprovisto de cubierta arbórea noble debido a la orientación y aridez extrema. Presenta comunidades rupícolas menores y formas de erosión mecánicas de rango comarcal.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03013','espacio','Sierra de Crevillent y Parque Natural de El Hondo (límite)','Relieve subbético quebrado y árido con barrancos profundos e intrincados labrados en calizas y yesos. Contrasta con la llanura palustre de El Hondo, configurando un ecotono de gran biodiversidad.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03061','espacio','Llanura aluvial del bajo Segura','Territorio plano y deltaico dedicado enteramente a la agricultura intensiva de regadío. No presenta atractivos naturales puros, poseyendo un valor ambiental puramente relictual local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03062','espacio','Tierras bajas aluviales','Paisaje idéntico al municipio limítrofe, plano y antropizado por el parcelario agrícola secular de la Vega Baja. Sin hitos geomorfológicos ni botánicos destacables.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03014','espacio','Parque Natural del Montgó y Reserva Marina del Cabo de San Antonio','Colosal mole caliza que emerge junto al mar alcanzando los 753 metros de altura, albergando más de 650 especies vegetales. Sus acantilados marinos basales caen verticales sobre aguas protegidas de alta biodiversidad.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03064','espacio','Marjal de Dolores (periferia de El Hondo)','Zonas bajas inundables salobres compuestas por suelos limosos y saladares degradados. Alberga avifauna limícola de forma estacional durante los periodos de encharcamiento pluvial.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03016','espacio','Parque Natural de las Salinas de Santa Pola (límite), El Hondo y Clot de Galvany','Excepcional conjunto de humedales costeros y de interior. El Clot de Galvany es una charca natural interconectada con dunas fósiles y pinares litorales de pino carrasco de gran valor biológico.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03017','espacio','Sierra de Camara y riberas del río Vinalopó','Relieve calizo alomado con lapiaces y oquedades menores rodeado de matorral xerófilo mediterráneo. El río Vinalopó fluye encajado mostrando terrazas aluviales sometidas a intensa erosión.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03067','espacio','Sierra de la Serrella y barranco del Moro','Escarpados riscos calizos horizontales que forman una barrera natural imponente sobre el valle. Cuenta con dehesas matorralizadas de gran valor botánico por la abundancia de endemismos rupícolas.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03068','espacio','Cueva de la Font de la Jove y crestas de la Serrella','Paisaje calcáreo abrupto caracterizado por imponentes formaciones de disolución y canchales de ladera activos. La cavidad kárstica natural mantiene aportes hídricos subterráneos limpios de montaña.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03018','espacio','Macizo del Puig Campana','Una de las cumbres más icónicas y colosales de la provincia, con una pared caliza vertical mítica y una gran fractura cumminal (El Portell). Ofrece un relieve alpino imponente pegado al litoral mediterráneo.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03070','espacio','Sotos del río Segura (tramo inferior)','Espacio fluvial encauzado con presencia de matorral palustre heliófilo y sauces dispersos. Su interés natural está mermado por la antropización de la Vega Baja.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03071','espacio','Garganta del río Gorgos y Sierra de la Solana','El río excava un cauce pedregoso encajonado flanqueado por terrazas calcáreas antiguas de interés geomorfológico. Las laderas de la sierra albergan palmitos y matorral termófilo denso.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03073','espacio','Confluencia de los ríos Sella y Penàguila','Encuentro de dos cursos fluviales torrenciales de montaña en un entorno de lomas margosas erosionadas. Presenta sotos riparios discontinuos de interés comarcal.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03020','espacio','Dunas de Guardamar y desembocadura del río Segura (gola)','Extraordinario sistema dunar litoral móvil que se extiende a lo largo de kilómetros, fijado parcialmente por una   masa forestal piñonera antigua. La desembocadura del Segura forma un estuario con humedales litorales valiosos. Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03078','espacio','Sierra de los Frailes','Depresión tectónica rodeada de relieves calizos cubiertos de matorral xerófilo de carácter semiárido. El paraje muestra lapiaces menores y formas de disolución superficiales de rango local.   Alicante) Hondón de las Nieves/El Fondó de les Neus - Puntuación: 48/100 • Paraje: Sierra de Crevillent (vertiente norte) y barranco de la Canalosa.     Descripción: Relieve quebrado calcáreo con laderas de fuertes pendientes colonizadas por pinares ralos de pino carrasco y espartizales. Muestra cárcavas de erosión nítidas en los fondos de valle.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03021','espacio','Paraje Natural Municipal de San Pascual-Torretes y Sierra de Menacha','Espacio montañoso calcáreo de gran valor botánico que alberga una estación biológica con gran diversidad de flora mediterránea. Cuenta con barrancos umbríos y formaciones rocosas singulares.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03080','espacio','Riberas del río Segura (límite)','Tramo plano aluvial del curso bajo del Segura muy antropizado. Conserva pequeñas bandas de carrizos de nulo relieve paisajístico, poseyendo un interés estrictamente local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90860','espacio','Sierra de Bèrnia (vertiente norte) y curso del río Gorgos','Impresionante cresta caliza alpina que domina el valle vitícola. El río discurre encajado entre terrazas rocosas cuaternarias de gran interés para el estudio de avenidas mediterráneas.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03022','espacio','Cabo de la Nao, Cabo de San Antonio, Isla del Portitxol y cueva marina de Llop Marí','Uno de los tramos costeros no-playa más grandiosos de España, con acantilados verticales calizos de más de 100 metros sobre el mar. Alberga cuevas marinas colosales accesibles por mar e islotes escarpados de altísimo valor biológico.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03085','espacio','Sierra de la Solana de Llíber','Crestas calcáreas de solana sometidas a una intensa insolación con matorrales heliófilos y palmitos dispersos. Su interés radica en la continuidad estructural de la morfología de la Marina Alta.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03086','espacio','Barranc de Malafí y laderas de la Sierra de Almudaina','Incisión fluvial torrencial en materiales calcáreos con desprendimientos de bloques rocosos antiguos. Cuenta con vegetación arbustiva mediterránea común de interés comarcal.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03088','espacio','Sierra del Cid (estribaciones) y lomas de Orito','Relieves tabulares calcáreos de perfiles suaves integrados en el corredor del Vinalopó. Presenta yeseras triásicas expuestas con vegetación gipsícola de valor local.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03903','espacio','Parque Natural de las Lagunas de La Mata y Torrevieja (vertiente oeste)','Vasta cuenca endorreica ocupada por la laguna salada de Torrevieja. Sus orillas salinas albergan una flora halófila protegida de gran rareza botánica internacional en un entorno horizontal.   Alicante).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03091','espacio','Sierra de Seguili','Pequeña estribación caliza exenta que se eleva sobre el fondo plano del valle del Pop. Alberga matorral noble mediterráneo y posee un interés paisajístico estructural comarcal.   Alicante) **Muro de Alcoy - Puntuación: 64/.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03024','espacio','Parque Natural de la Sierra de Mariola (vertiente norte) y curso alto del río Serpis','Laderas calcáreas umbrías tapizadas por frondosas masas de pino carrasco y un sotobosque excepcionalmente rico en plantas aromáticas y medicinales. El río Serpis aporta un pequeño corredor ripario de chopos y sauces que corta los relieves prebéticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03025','espacio','Cauce del río Monnegre y lomas del Calvari','Paisaje árido mediterráneo caracterizado por un ancho lecho fluvial de carácter torrencial jalonado por gravas y terrazas aluviales. Presenta escarpados taludes de tierras arcillosas y una escasa cobertura vegetal de matorral xerófilo de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03026','espacio','Paraje natural del río Vinalopó (els Clots) y cerro de la Mola','Tramo fluvial semiárido donde afloran aguas salobres estacionales que sustentan comunidades de tarayales y vegetación halófila. Los cerros circundantes muestran una fuerte erosión pluvial en forma de cárcavas y badlands arcillosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03094','espacio','Captación de agua de la Font de la Favara y laderas del Puig Campana (estribaciones)','Espacio forestal dominado por un relieve quebrado calcáreo tapizado de pinares de pino carrasco bien conservados. Alberga pequeñas surgencias de agua subterránea que generan un ambiente fresco y húmedo en contraste con el entorno litoral seco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03095','espacio','Segaria (vertiente baja) y llanura aluvial del río Girona','Modesto relieve de transición donde las estribaciones rocosas de la sierra dan paso a los depósitos cuaternarios de la llanura prelitoral. Su cobertura natural original está muy modificada, manteniendo interés únicamente a nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03096','espacio','Sierra de Onil (marquesado) y paraje de la Furia','Imponente alineación montañosa caliza que forma parte del sistema bético, caracterizada por verticales paredones rocosos y densas umbrías forestales. Aloja encinares relictos bien conservados y abundantes fuentes naturales que manan de la roca caliza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03097','espacio','Sierra de la Solana y cauce del río Girona','Cresta rocosa alargada de calizas mesozoicas orientada al sol que exhibe un modelado kárstico superficial con abundantes lapiaces. El lecho del río Girona aporta un contraste morfológico con sus depósitos de grandes bloques pétreos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03027','espacio','Sierra de Orihuela, Palmeral de San Antón y Paisaje Protegido de Sierra Escalona','Impresionante macizo calizo de abruptas paredes verticales y crestas afiladas de aspecto desértico que contrasta con el oasis del palmeral histórico. Sierra Escalona aporta colinas cubiertas por uno de los pinares más densos de la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90858','espacio','Valle del río Sella y desfiladero del Estret d''Orxeta','Angosta garganta natural labrada por la acción fluvial sobre las estribaciones calcáreas de la Sierra de Aitana. El relieve es abrupto y encajonado, manteniendo un cauce de aguas limpias rodeado de pinares y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03100','espacio','Sierra del Carrascal de Parcent','Relieve prebético escarpado coronado por crestas rocosas calizas donde perviven valiosos rodales de encina o carrasca mediterránea. El paraje destaca por sus   impresionantes canchales de ladera y una rica flora rupícola adaptada a los paredones verticales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03101','espacio','Muntanya Gran de Pedreguer','Macizo calcáreo redondeado por la erosión kárstica superficial que conserva formaciones de matorral esclerófilo denso y pino carrasco. Presenta oquedades naturales menores y ofrece amplias panorámicas visuales de la costa de la Marina Alta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03028','espacio','Parque Natural del Marjal de Pego-Oliva','Excepcional espacio palustre y humedal costero rodeado por una corona de montañas calcáreas. El paraje está constituido por una red de canales navegables, lagunas someras de aguas cristalinas de origen kárstico y extensas praderas de vegetación subacuática.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03103','espacio','Paraje Natural Municipal de la Font Roja (sector este) y jardín botánico del Santos','Escarpada ladera umbría orientada al norte que alberga uno de los bosques de carrasca y caducifolios mejor conservados de la Comunidad Valenciana. El relieve kárstico genera fuentes cristalinas permanentes bajo los cortados calizos superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03029','espacio','Paisaje Protegido de las Sierras de Maigmó y Sit','Espectacular anfiteatro montañoso con imponentes crestas calizas que rozan los 1.300 metros de altitud. Destaca la vertiginosa cara norte del Cid y los densos bosques de pino carrasco que tapizan los valles encajados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03902','espacio','Paisaje Protegido de Sierra Escalona y Dehesa de Campoamor (sector sur), y río Seco','Relieve suavemente ondulado surcado por profundos barrancos encajados en arenas calcáreas cuaternarias que simulan pequeños cañones. Alberga densas masas forestales que sirven de hábitat al búho real y al gato montés.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03030','espacio','Barranco de la Encantada y Salt de Planes','Profundo barranco calcáreo excavado por la erosión hídrica que cuenta con un espectacular salto de agua perenne y sucesivas pozas de aguas turquesas talladas en la roca. El entorno es agreste, combinando paredes de piedra con vegetación de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03901','espacio','Desembocadura del río Girona','Tramo final del curso fluvial donde se encuentra con el mar de forma llana, constituyendo una zona de gravas y depósitos aluviales. El entorno está muy antropizado y posee un interés ecológico meramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03031','espacio','Macizo de Ponotx (el León Dormido) y barranco del Salt','Colosal mole de roca caliza jurásica con paredes totalmente verticales de más de 400 metros de desnivel que dominan el paisaje visual. Cuenta con profundas pedrizas basales y canales de erosión torrencial de gran fuerza estética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03060','espacio','Els Frares de la Sierra de Serrella','Extraordinaria formación geológica constituida por un conjunto de gigantescos monolitos o agujas de roca caliza exentas creadas por la erosión diferencial y el colapso kárstico de la ladera. El paisaje es de una singularidad visual y geomorfológica soberbia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03109','espacio','Entorno fluvial del río Segura (tramo canalizado)','Terreno completamente llano integrado en la llanura de inundación de la Vega Baja, sin relieves naturales destacables. El interés geográfico es mínimo debido a la intensa ocupación agrícola e hidráulica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03111','espacio','Sierra de Redován (Peña de la Cruz)','Vertiente sur de la sierra oriolana caracterizada por un escarpe calcáreo extremadamente árido, escarpado y vertical. Alberga una rala vegetación rupícola nitrófila y oquedades naturales que sirven de refugio a aves rapaces de climas secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03032','espacio','Cañón del río Amadorio y embalse antiguo de Relleu','Espectacular estrechamiento fluvial o desfiladero con paredes calizas verticales apenas separadas por unos metros, donde se ubica una presa histórica del siglo XVII. El relieve circundante es abarrancado y muy agreste.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03033','espacio','Cerros de las Cuevas y meandros del río Segura','Relieve alomado de areniscas y margas neógenas sometido a procesos de erosión eólica y antrópica. El río Segura discurre formando amplias curvas sobre depósitos aluviales cuaternarios de carácter típicamente prelitoral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03114','espacio','Sierra del Reclot y barranco de la Cueva','Alineación montañosa caliza de carácter subárido con laderas cubiertas de matorral bajo mediterráneo, espartizales y romerales. El paisaje está muy marcado por afloramientos rocosos blanquecinos bajo una intensa insolación solar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03115','espacio','Sierra de Fontilles (vertiente norte)','Lomas calcáreas cubiertas de pino carrasco y densas formaciones de maquia mediterránea prebética. Cuenta con pequeñas surgencias de agua de carácter estacional asociadas a las fracturas tectónicas de la sierra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03118','espacio','Lomas calcarenitas de San Fulgencio y vegas del Segura','Pequeños promontorios fósiles cuaternarios que emergen escasamente sobre la planicie aluvial de la Vega Baja. Tienen interés para comprender la evolución de la antigua línea de costa pero escaso relieve visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03904','espacio','Saladares de San Isidro (perímetro)','Zona llana marginal de antiguas marismas secas donde afloran suelos con alta concentración salina. Presenta vegetación halófila rala (almarjos) de interés ecológico local pero muy escaso relieve geográfico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03120','espacio','Sierra de Escalona (vertiente norte) y barranco de las Estacas','Relieve suave de lomas margosas tapizadas por densas masas de pino carrasco que enlazan con el complejo forestal del sur provincial. Los barrancos muestran curiosas formas de erosión sobre los materiales blandos sedimentarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03117','espacio','Sierra de Segaria (estribaciones meridionales)','Vertiente de pendientes moderadas constituida por rocas calizas del Cretácico cubiertas por matorral xerófilo. Su interés estriba en la transición paisajística hacia la vega del río Girona a nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03035','espacio','Parque Natural de las Salinas de Santa Pola y Cabo de Santa Pola','Excepcional complejo de lagunas litorales, salinas y dunas playeras que acoge colonias permanentes de miles de flamencos. El Cabo es un arrecife de coral fósil de época mesiniense único en Europa, configurando un acantilado marino espectacular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03123','espacio','Paraje Natural Municipal de la Sierra de Cabrera','Macizo calizo aislado que emerge con fuerza en el corredor del Vinalopó, exhibiendo escarpes rocosos y crestas desnudas. Sus faldas albergan pinares de pino carrasco adaptados a condiciones de acusada aridez estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03036','espacio','Sierra de Aitana (vertiente sur), barranco del Arc y Font de l''Alcàntera','Impresionante relieve de alta montaña prebética dominado por los vertiginosos contrafuertes calizos de Aitana. El barranco del Arc es un cañón de colosales paredes de roca caliza verticales muy valorado por su espectacularidad geológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03125','espacio','Sierra de la Solana (sector oriental)','Crestas calcáreas de formas suaves y redondeadas cubiertas por matorrales xerófilos y espartizales mediterráneos. Ofrece una fisonomía de paisaje rústico expuesto con lapiaces menores de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03127','espacio','Sierra de Ferrer, Sa Creu y nacimiento del río Algar','Entorno montañoso quebrado de gran belleza visual donde confluyen escarpes calizos y profundos valles de montaña. Cuenta con valiosas fuentes kársticas que alimentan la cuenca del Algar y densas formaciones de matorral noble mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03037','espacio','Acantilados de la punta de Moraira y cabo de d''Or','Tramo de costa rocosa escarpada con acantilados calizos que se desploman verticalmente sobre el mar Mediterráneo. El Cabo de d''Or es un imponente promontorio rocoso que ofrece una excelente sección geológica visible desde el mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03129','espacio','Embalse de Tibi (río Monnegre) y Sierra de la Penya Roja','Impresionante garganta rocosa calcárea donde se encaja el embalse más antiguo en funcionamiento de Europa occidental (siglo XVI). El relieve circundante es abrupto, jalonado por fallas y escarpes calizos de gran envergadura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03130','espacio','Valle de la Gallinera (cabecera) y Sierra de Alfaro','Relieve prepirenaico de montaña media con vertientes calizas muy empinadas sometidas a una intensa erosión pluvial. Presenta matorrales de montaña bien conservados y una gran tranquilidad paisajística comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03131','espacio','Sierra de la Solana (sector central) y cueva del Calvari','Ladera caliza de fuerte pendiente orientada al mediodía con afloramientos rocosos lapiácicos y cubiertas de romerales. Posee pequeñas cavidades kársticas de desarrollo vertical de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03038','espacio','Parque Natural de las Lagunas de La Mata y Torrevieja','Colosal complejo lagunar e hipersalino donde la laguna de Torrevieja destaca mundialmente por su característico color rosa, provocado por bacterias halófilas. Es un humedal de primer orden internacional para la nidificación y paso de avifauna acuática.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03134','espacio','Depresión kárstica de la Vall d''Alcalà y la Foradada (límite)','Impresionante valle cerrado de origen kárstico (poljé) rodeado de abruptas montañas calizas. Presenta notables simas naturales de gran profundidad y sumideros por donde se infiltran las aguas de escorrentía superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03135','espacio','Barranco del Infierno (río Girona) y Cova del Rull','Espectacular y angosto cañón calcáreo con paredes verticales de piedra caliza pulida por las avenidas   torrenciales. La Cova del Rull es una cavidad natural excepcional que alberga abundantes formaciones de estalactitas y estalagmitas vivas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03137','espacio','Barranco del Infierno (sector norte) y fuentes de la Foia','Relieve de sobrecogedora fractura geológica dominado por el cañón excavado por el río Girona. Las laderas calizas presentan impresionantes escarpes, abrigos rocosos naturales y surgencias kársticas de gran pureza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03136','espacio','Peña Foradada y Sierra del Almirante','Valle alargado encajonado entre imponentes alineaciones montañosas calcáreas donde destaca la Peña Foradada, un arco de roca natural colosal tallado por la erosión eólica y pluvial que atraviesa la cresta de la sierra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90859','espacio','Llanura aluvial del río Girona (tramo bajo)','Espacio plano constituido por limos y arcillas de sedimentación fluvial cuaternaria en las proximidades de la costa. Carece de relieves significativos y muestra un paisaje agrario intensivo de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03039','espacio','Desembocadura del río Amadorio y acantilados del Malladeta','El río Amadorio forma un pequeño estuario fluvial antes de encontrarse con el mar, flanqueado al sur por tramos de costa rocosa caliza de altura moderada y calas de cantos rodados de interés paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03040','espacio','Paraje Natural Municipal de la Sierra de Salinas y salero de Villena','Extenso macizo boscoso cubierto por densas masas de pino carrasco y encinares que constituye la mayor reserva forestal del interior provincial. Los saleros son lagunas endorreicas salinas con comunidades halófilas relictas de gran valor botánico.   Xaló (ver Jalón más arriba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04001','espacio','Parque Nacional de Sierra Nevada (vertiente norte) y barranco de Sierra','Impresionante relieve de alta montaña caracterizado por profundos barrancos y desniveles acusados sobre sustratos de esquistos. Alberga densos bosques de encinas, pinares de alta montaña y una rica vegetación alpina adaptada a inviernos rigurosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90403','espacio','Parque Natural de Sierra Nevada, paraje de El Serbal y alta montaña del Chullo','Impresionante relieve alpino que asciende hacia las cumbres béticas con profundos valles de modelado periglacial. Sus umbrías albergan sotos de castaños monumentales, acebedas relictas y arroyos cristalinos alimentados por el deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04002','espacio','Reserva Natural de las Albuferas de Adra','Extraordinario complejo palustre costero compuesto por lagunas someras de aguas salobres rodeadas de una densa masa de carrizos. Es un enclave de relevancia internacional para la avifauna acuática, sirviendo de refugio a especies amenazadas como la malvasía cabeciblanca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90404','espacio','Rambla del Saliente (curso alto) y cerro de la Atalaya','Paisaje semiárido esculpido por la erosión torrencial sobre margas y calizas de la Sierra de los Filabres. Presenta taludes abarrancados cubiertos de espartizales y matorral xerófilo de interés predominantemente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90405','espacio','Cañón de Alboloduy (Rambla de los Santos) y Parque Natural de Sierra Nevada','Espectacular desfiladero geológico excavado en areniscas y conglomerados que muestra paredes verticales de tonos rojizos erosionadas por el viento. Su lecho seco exhibe la flora típica de rambla subdesértica en una transición morfológica abrupta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04003','espacio','Rambla de Albox y peñón de la Moheda','Ancho cauce torrencial de gravas arenosas flanqueado por terrazas aluviales sometidas a una intensa dinámica erosiva. El peñón aporta un relieve calcáreo aislado que destaca visualmente sobre el paisaje desértico circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90407','espacio','Nacimiento del río Almanzora y Sierra de los Filabres','Valle de cabecera fluvial donde afloran las aguas subterráneas de la sierra en un entorno de pinos laricios. Ofrece una fisonomía fresca y forestal que contrasta con la aridez característica del resto de la cuenca media.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90408','espacio','Sierra de los Filabres (sector central)','Paisaje de muelas calcáreas y laderas de pizarra situadas a gran altitud, cubiertas por matorrales almohadillados de montaña. Muestra un modelado de erosión severo con amplias panorámicas hacia la cuenca de Sorbas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90409','espacio','Confluencia de los ríos Nacimiento y Andarax','Amplia llanura aluvial torrencial caracterizada por la unión de dos grandes ramblas almerienses. Presenta taludes margosos erosionados y rodales dispersos de tarayales adaptados a la alta insolación estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90410','espacio','Sierra de Gádor (vertiente oriental) y barranco de la Fuente','Macizo calcáreo escarpado que presenta un modelado kárstico con abundantes fracturas tectónicas de donde brotan aguas termales. Las laderas exhiben una vegetación rala mediterránea y cortados rocosos frecuentados por aves rapaces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90411','espacio','Rambla de Alicún y laderas de Sierra de Gádor','Pequeña incisión fluvial sobre calizas y dolomías que desciende hacia el río Andarax. Cuenta con formaciones arbustivas áridas de romero y tomillo en laderas sometidas a una intensa radiación solar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','espacio','Monumento Natural Arrecife Barrera de Posidonia, Isla de Alborán (jurisdicción marítima) y paraje de El Alquián','Excepcional espacio marino que alberga una de las pocas praderas de Posidonia oceanica con arrecife de barrera remanentes en el litoral español. La Isla de Alborán constituye un enclave volcánico virgen de altísimo valor biogeográfico en el Mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90734','espacio','Barranco de la Ragua (curso bajo) y Parque Natural de Sierra Nevada','Profunda garganta rocosa excavada en pizarras y esquistos por las aguas procedentes de las cumbres de Sierra Nevada. El lecho del barranco mantiene un caudal permanente con vegetación hidrófila que contrasta con las laderas desnudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90412','espacio','Rambla de Alsodux y entorno del río Andarax','Paisaje abarrancado de media montaña mediterránea con laderas de esquistos degradados y cárcavas pluviales. Alberga matorrales áridos de transición con un valor paisajístico de nivel netamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90413','espacio','Cabezo de María y riberas del río Antas','Promontorio volcánico aislado que constituye un hito morfológico singular en la llanura prelitoral. El río Antas aporta una banda de vegetación palustre somera y tarayales entre los cultivos de regadío.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90414','espacio','Garganta del río Almanzora y escarpes de yeso','El río Almanzora labra terrazas cuaternarias flanqueadas por cerros yesosos erosionados con formaciones de lapiaces menores. Muestra una vegetación gipsícola singular de gran interés botánico a nivel local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90415','espacio','Vega aluvial del Almanzora y lomas margosas','Valle llano constituido por depósitos sedimentarios fluviales encajado entre colinas de erosión suave. Carece de relieves abruptos y su cobertura natural original se limita a pequeños sotos degradados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90416','espacio','Sierra de los Filabres, barranco del Barrancón y calar de Velefique (límite)','Paisaje abrupto de alta montaña dominado por inmensas muelas calizas o calares que coronan las laderas de pizarra. Alberga densas masas de pino laricio de repoblación y una flora endémica rupícola excepcional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04904','espacio','Litoral bajo y ramblas intermitentes','Franja costera llana dominada por depósitos marinos cuaternarios muy antropizados por la agricultura intensiva de invernadero. Posee valor ecológico únicamente a nivel de playas de cantos y escorrentías locales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90417','espacio','Parque Nacional de Sierra Nevada, Puerto de la Ragua y río Bayárcal','El municipio más alto de la provincia, caracterizado por un relieve de alta montaña alpina con densos bosques de pino silvestre, robledales y espectaculares cascadas de deshielo. El río corre encajado en un tajo de pizarras oscuras de gran pureza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90418','espacio','Sierra de los Filabres (vertiente norte) y arroyo de Bayarque','Laderas boscosas de pendientes pronunciadas pobladas de pinos negrales que descienden hacia la cuenca del Almanzora. Cuenta con pequeñas surgencias de agua cristalina y formaciones de roca erosionada singulares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04005','espacio','Sierra de Bédar y barranco de Baeza','Relieve quebrado calcáreo de la Sierra de los Filabres orientada al mar con presencia de antiguas mineralizaciones que afloran en superficie. Muestra matorrales esclerófilos densos y escarpes rocosos menores de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90419','espacio','Llanura aluvial del bajo Andarax y cerros de yesos','Depósitos aluviales llanos rodeados de pequeñas colinas yesosas fuertemente erosionadas por la escorrentía pluvial. Su cobertura vegetal es escasa y se compone de matorral degradado de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90420','espacio','Sierra de los Filabres (vertiente sur) y barranco del Infierno','Territorio de pronunciadas laderas pizarrosas azotadas por la erosión con escasa cubierta arbórea y predominio de espartizales. Ofrece una fisonomía de paisaje desnudo y agreste de carácter puramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90421','espacio','Sierra de los Filabres y monte de la Santa','Elevación montañosa caliza que destaca sobre los relieves alomados circundantes, exhibiendo escarpes calcáreos y lapiaces superficiales. La vegetación predominante es el matorral aromático mediterráneo seco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90422','espacio','Rambla de Bentarique y entorno del Andarax','Incisión torrencial que corta los materiales blandos de la depresión de Alpujarra Almeriense. Cuenta con vegetación xerófila y pequeños sotos de tarayales expuestos a una intensa insolación estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90423','espacio','Sierra de Gádor, fuentes de Marbella y Minas de Berja (entorno geológico)','Majestuoso macizo calizo dolomítico que presenta espectaculares escarpes y un relieve kárstico de montaña con profundas simas. Destaca por albergar importantes surgencias de agua subterránea que manan al pie de la sierra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90736','espacio','Parque Natural de Sierra Nevada y canal de San Pedro','Vertiente meridional de Sierra Nevada caracterizada por un relieve quebrado de pizarras cubierto de encinares y repoblaciones forestales de coníferas. Ofrece notables vistas de las terrazas aluviales encajadas del río Andarax.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04031','espacio','Rambla de Albanchez y cauce del río Almanzora','Tramo medio del río Almanzora donde se ensancha formando un lecho de gravas arenosas sujeto a avenidas torrenciales periódicas. El relieve perimetral es alomado margoso con escasa cobertura arbórea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04006','espacio','Parque Natural de Cabo de Gata-Níjar, Isla de Andrés y acantilados de la Mesa Roldán','Espectacular tramo de costa volcánica con imponentes acantilados calizos y domos basálticos que se hunden en el mar Mediterráneo. La Mesa Roldán es un antiguo arrecife coralino fósil amesetado que ofrece una sección geológica excepcional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04033','espacio','Sierra de los Filabres (vertiente sur) y barranco del Río','Paisaje de media montaña dominado por pizarras oscuras dispuestas en laderas de fuertes pendientes escalonadas de forma natural. La vegetación original está muy degradada, predominando pastizales secos y jarales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04036','espacio','Desfiladero de Chercos Viejo y laderas de pizarra','Estrecho tajo excavado por la erosión hídrica en rocas metamórficas de la Sierra de los Filabres. El relieve es   abrupto en el entorno del cauce seco, mostrando curiosas formas de desprendimientos pétreos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04037','espacio','Parque Natural de la Sierra de María-Los Vélez y sabinar de Chirivel','Extensa llanura elevada flanqueada al norte por las imponentes paredes calizas de la Sierra de María. Alberga valiosos ejemplares de sabina albar centenaria perfectamente adaptados al riguroso clima continental de la zona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04034','espacio','La Peza de Cóbdar (Peñón de Cóbdar) y río Los Molinos','Impresionante mole de mármol blanco de más de 200 metros de altura vertical que emerge de manera espectacular en el paisaje. El río Los Molinos corre encajado en su base, manteniendo pequeñas pozas de aguas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04035','espacio','Embalse de Cuevas del Almanzora, acantilados de Villaricos y canal de El Calguerín','Paisaje hídrico artificial encajonado entre cerros de margas y yesos que contrasta con el tramo costero de acantilados bajos de origen minero. Presenta formaciones de erosión singulares y cuevas naturales en taludes arcillosos.   Darrícal (Alcolea - integrado en Alcolea, ver arriba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04038','espacio','Sierra de Gádor (vertiente sur) y arroyo de Celín','Inmensa ladera caliza dolomítica con fuertes pendientes que vierten hacia el Poniente Almeriense. El arroyo de Celín constituye una de las pocas surgencias permanentes de agua de la sierra, rodeada de sauces y tarajes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04008','espacio','Reserva Natural de Punta Entinas-Sabinar','Extraordinario ecosistema dunar litoral y complejo palustre asociado compuesto por charcas salobres y dunas móviles. Alberga comunidades de sabina suave y tarayales, siendo un área clave para la reproducción del pato colorado y la gaviota audouin.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04041','espacio','Sierra de Gádor (sector oriental) y acantilados de El Cañarete (límite)','Altiplanicie caliza elevada que desciende bruscamente hacia el mar formando impresionantes acantilados calcáreos. Muestra un modelado kárstico con lapiaces y simas, rodeado de matorral mediterráneo xerófilo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04043','espacio','Sierra de Gádor, nacimiento del agua de Felix y cerro de la Matanza','Relieve montañoso calizo muy abrupto caracterizado por imponentes farallones rocosos y un paisaje kárstico de montaña. Destaca por sus manantiales naturales de aguas cristalinas que emergen de los materiales carbonatados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04044','espacio','Rambla de Fines y lecho del río Almanzora','Valle aluvial llano con depósitos de gravas y arenas situado en la cuenca media del Almanzora. Presenta una escasa cobertura vegetal natural debido a la intensa actividad industrial del mármol.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04009','espacio','Parque Nacional de Sierra Nevada y dehesa de Fiñana','Vertiente septentrional del macizo que presenta densos bosques de encinas bien conservados y pinares alpinos en las cotas superiores. El relieve es accidentado, jalonado por barrancos de montaña con aguas limpias de deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04010','espacio','Parque Natural de Sierra Nevada, río Andarax (curso alto) y garganta de la Presa','Magnífico entorno alpujarreño donde el río Andarax corre encajado entre las laderas de pizarra de Sierra Nevada y las calizas de Gádor. Cuenta con frondosos bosques de galería, saltos de agua y encinares de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04047','espacio','Rambla de Tabernas (desembocadura) y lomas de yeso de Gádor','Relieve de lomas margosas y yesíferas bajas sometidas a una intensa erosión subdesértica en el límite del desierto de Tabernas. Presenta matorrales xerófilos ralos y formaciones de cárcavas de interés geológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04048','espacio','Rambla de Alfaix y cerros arcillosos','Paisaje alomado mediterráneo seco surcado por surcos de escorrentía estacional sobre materiales neógenos blandos. Alberga romerales y espartizales aclarados de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04011','espacio','Franja marina litoral de Garrucha','Término municipal extremadamente reducido y costero, dominado por la trama urbana y portuaria. Su interés en cuanto a naturaleza pura es mínimo, restringiéndose al medio marino abierto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04012','espacio','Sierra de los Filabres, laderas de Calar Alto (sector sur) y barranco del Almendral','Impresionante relieve que asciende hacia las mayores cotas de los Filabres, dominado por vertientes pizarrosas cubiertas de pinares. El paisaje ofrece una gran amplitud visual y una geomorfología de alta montaña mediterránea seca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04051','espacio','Barranco del Infierno y estribaciones de Sierra de Gádor','Estrecha incisión torrencial sobre materiales calcáreos que genera cortados rocosos menores de aspecto   árido. Cuenta con espartizales y matorral xerófilo adaptado a condiciones de acusada sequía estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04052','espacio','Rambla de Huércal y llanura del bajo Andarax','Paisaje llano cuaternario de sedimentación fluvial muy próximo a la capital provincial. Carece de accidentes geográficos puros notables, manteniendo un interés natural estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04013','espacio','Sierra de Almagro y rambla de Urá','Alineación montañoso de carácter semiárido compuesta por calizas y filitas que alberga notables formaciones de matorral mediterráneo seco. La rambla muestra escarpes arcillosos de erosión lineal interesantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04054','espacio','Cerro de la Cruz y entorno del río Andarax','Ladera pizarrosa de fuerte pendiente perteneciente a las estribaciones meridionales de Sierra Nevada. Su cobertura vegetal está compuesta por matorral mediterráneo xerófilo y espartizales de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04055','espacio','Parque Natural de Sierra Nevada (vertiente sur) y barranco de los Gatos','Terreno quebrado de media montaña alpujarreña con laderas de pizarra cubiertas de encinares degradados y jarales. El barranco aporta frescura estacional con pequeñas pozas intermitentes entre rocas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04056','espacio','Sierra de los Filabres interior y barranco de Laroya','Pequeño y recóndito valle de montaña media esculpido sobre pizarras y esquistos oscuros. Conserva pequeñas fuentes de agua y una fisonomía de terrazas   agrícolas tradicionales perfectamente integradas en el relieve natural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04014','espacio','Parque Nacional de Sierra Nevada, Nacimiento del Río Andarax y barranco de El Horcajo','Uno de los enclaves naturales más bellos de la Alpujarra; el río Andarax brota en un paraje de alta montaña rodeado de gigantescos álamos, sauces y densos pinares. El relieve presenta colosales tajos de pizarra y cumbres que rozan los 2.000 metros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04058','espacio','Sierra de Líjar y canteras de mármol (entorno geológico)','Crestas calcáreas y de mármol pertenecientes al macizo de los Filabres que muestran escarpes rocosos desnudados por la erosión. La vegetación predominante se compone de matorral aromático seco y esparto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04059','espacio','Sierra de los Filabres (sector oriental) y rambla de Lubrín','Paisaje alomado caracterizado por una compleja geología de esquistos, calizas y filitas que genera relieves redondeados. Alberga comunidades de encinar termófilo disperso y matorral mediterráneo seco comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04060','espacio','Sierra de Alhamilla (vertiente norte) y rambla de Lucainena','Imponente barrera montañosa caliza que se eleva sobre el desierto, ofreciendo laderas escarpadas cubiertas de encinares relictos en las zonas umbrías. La rambla muestra depósitos de bloques y una flora subdesértica singular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04015','espacio','Sierra de los Filabres (estribaciones) y barranco de Macael','Relieve montañoso pizarroso intensamente marcado a nivel geológico por los afloramientos de mármol blanco explotados desde la antigüedad. Conserva retazos de pinar de repoblación y matorral seco en sus zonas no mineras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04063','espacio','Parque Natural de la Sierra de María-Los Vélez y umbría de la Virgen','Impresionante y majestuoso macizo calizo escarpado que se eleva de forma imponente en el norte provincial. Alberga uno de los bosques de pino laricio y encinar montano más densos e importantes del sureste español, con cumbres nivales periódicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04016','espacio','Sierra de Cabrera (vertiente marítima) y acantilados de Mojácar','Impresionante alineación montañosa de origen volcánico y metamórfico que muere directamente en el mar formando acantilados bajos y calas de cantos rodados. Las laderas albergan comunidades de flora iberoafricana extremedamente raras en Europa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04903','espacio','Llanura aluvial del Poniente y rambla de El Carcau','Territorio llano cuaternario profundamente transformado por la agricultura intensiva de invernaderos. Presenta una modesta rambla seca de interés exclusivamente local para la escorrentía superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04065','espacio','Curso alto del río Nacimiento y laderas de Filabres','Valle fluvial torrencial encajonado entre los relieves pizarrosos de los Filabres y las estribaciones de Sierra Nevada. El río mantiene un hilo de agua estacional flanqueado por adelfares y tarayales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04017','espacio','Parque Natural de Cabo de Gata-Níjar, Salinas de Cabo de Gata, Arrecife de las Sirenas, Cabo de Gata y caldera volcánica de Rodalquilar','Uno de los espacios naturales más valiosos de Europa; un desierto volcánico litoral con colosales acantilados, bufaderos, dunas fósiles y calderas volcánicas perfectas. Las salinas acogen miles de aves acuáticas y el Arrecife de las Sirenas muestra formaciones de pitones volcánicos espectaculares sumergidos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04018','espacio','Parque Nacional de Sierra Nevada, barranco de Ohanes y el Santuario','Escarpado relieve alpujarreño dispuesto en vertiginosas laderas de pizarra labradas en terrazas tradicionales que ascienden hacia las altas cumbres. Cuenta con densos encinares de montaña, fuentes naturales y un paisaje de una gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04068','espacio','Sierra de los Filabres (vertiente meridional)','Paisaje áspero de media montaña caracterizado por laderas homogéneas de pizarras oscuras cubiertas de espartizales y jarales desnudados por la erosión. Ofrece amplias vistas hacia la hoya de Tabernas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04019','espacio','Estrecho del río Almanzora y lomas marginales','El río Almanzora corre encajado en un pequeño estrechamiento calcáreo antes de abrirse hacia la cuenca   baja. Presenta una vegetación riparia degradada y cerros erosionados de nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04070','espacio','Sierra de las Estancias, rambla de Oria y peñón de la Virgen','Alineación montañosa caliza de altitud considerable que define el paisaje del norte provincial.   Presenta relieves quebrados con pinos carrascos dispersos, espartizales y notables formaciones de erosión eólica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04071','espacio','Las Canales de Padules (río Andarax)','Espectacular y estrecho desfiladero geológico donde el río Andarax ha excavado las rocas calizas, creando un cañón de paredes verticales pulidas que apenas distan unos metros entre sí. Cuenta con pozas profundas y saltos de agua cristalina perennes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04072','espacio','Los Derrumbaderos de Partaloa','Extraordinaria formación geomorfológica constituida por colosales bloques de conglomerados amarillentos desprendidos y erosionados por el viento en formas caprichosas (taffonis). El paisaje simula una ciudad de piedra de un alto impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04020','espacio','Parque Nacional de Sierra Nevada, río Paterna y castañar de Paterna','Excepcional entorno de alta montaña alpujarreña que alberga uno de los pocos y más valiosos castañares monumentales de la provincia de Almería. El relieve presenta profundos barrancos de pizarra e impresionantes acequias de careo tradicionales que distribuyen el agua de deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04074','espacio','Sierra de Alhamilla, paraje de Baños de Alhamilla y rambla de Pechina','Macizo calizo escarpado que surge con fuerza sobre la depresión del Andarax, albergando en sus umbrías un frondoso encinar relicto bien conservado. Destaca por sus surgencias de aguas termales que brotan de las fracturas basales de la sierra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04021','espacio','Geoda de Pulpí (Mina Rica), acantilados de San Juan de los Terreros e Isla de Terreros','Alberga la geoda gigante visitable más grande del mundo, un fenómeno geológico excepcional de cristales de yeso transparentes de un valor internacional absoluto. Su costa presenta acantilados bajos calizos e islas volcánicas protegidas como monumentos naturales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04022','espacio','Sierra de los Filabres, barranco de la Gitana y tiro de Pichón (entorno natural)','Vertientes forestales de montaña media cubiertas por pinares de pino carrasco bien adaptados a los sustratos de pizarras y calizas. El barranco presenta formaciones de erosión lineal de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04077','espacio','Parque Natural de Sierra Nevada y barranco de El Clavel','Relieve quebrado alpujarreño con pronunciadas pendientes de pizarras que albergan comunidades vegetales mediterráneas de ladera. El barranco aporta un curso intermitente de agua rodeado de matorral noble esclerófilo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04078','espacio','Rambla de Rioja y entorno del bajo Andarax','Paisaje subdesértico de lomas margosas y arcillosas sometidas a abarrancamientos pluviales (cárcavas). Cuenta con una escasa cubierta vegetal compuesta de plantas xerófilas e iberoafricanas menores a nivel local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04023','espacio','Paraje Natural de Punta Entinas-Sabinar (sector oriental) y arrecife de Posidonia de Aguadulce','Destaca por sus fondos marinos someros poblados por densas praderas de Posidonia oceanica de gran valor biológico. En tierra, el espacio protegido aporta dunas litorales fijadas por sabinas y charcas palustres con flamencos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04080','espacio','Rambla de Santa Cruz y riberas del Andarax','Pequeño tajo fluvial torrencial labrado en los materiales metamórficos de la llanura de Alpujarra. Conserva comunidades modestas de tarajes y adelfares adaptados a las fuertes avenidas primaverales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04081','espacio','Rambla de Huechar y escarpes de conglomerados del Andarax','Impresionantes farallones de conglomerados cuaternarios erosionados en paredes verticales que flanquean el curso del río Andarax. El paisaje es árido, mostrando una fisonomía de badlands de interés geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04082','espacio','Sierra de los Filabres (vertiente sur) y barranco de Senés','Paisaje característico de pizarras relucientes dispuestas en vertientes homogéneas desnudas de vegetación arbórea grande. Destaca por la severidad del modelado erosivo y la amplitud de sus horizontes serranos comarcales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04025','espacio','Sierra de los Filabres, Calar de Almería (límite) y encina monumental de la Peana','Extenso término que asciende hacia las cumbres de los Filabres entre frondosos pinares y laderas pizarrosas antiguas. Alberga la Encina de la Peana,   monumento natural y el ejemplar de encina más gigantesco de toda Andalucía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04084','espacio','Sierra de los Filabres y barranco de Sierro','Municipio encajonado en un profundo y estrecho valle pizarroso rodeado de imponentes montañas cubiertas de pinares. El arroyo local mantiene un caudal de montaña permanente con pequeños saltos de agua entre rocas.   Almería).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04085','espacio','Rambla de Somontín y laderas de la Sierra de los Filabres','Relieve abrupto caracterizado por laderas abarrancadas de esquistos y pizarras con escasa cobertura vegetal. La rambla presenta depósitos de gravas y formas de erosión torrencial típicas del Valle del Almanzora.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04026','espacio','Paraje Natural Karst en Yesos de Sorbas y cañón del río Aguas (Los Molinos)','Uno de los complejos kársticos en yesos más importantes del mundo, con más de mil cavidades, cuevas y simas subterráneas repletas de estalactitas de yeso cristalino. El río Aguas genera en Los Molinos un oasis de agua permanente con humedales y cascadas calcáreas singulares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04087','espacio','Cerro de los Loberos y riberas del río Sierro (tramo bajo)','Lomas margosas con vegetación xerófila rala y matorral mediterráneo de degradación. El curso fluvial aporta una estrecha franja verde de sauces y cañaverales de interés exclusivamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04088','espacio','Paraje Natural Desierto de Tabernas y ramblas de Lanújar y de Tabernas','El único desierto propiamente dicho de Europa; un colosal paisaje geomorfológico de badlands, cárcavas, cañones áridos y chimeneas de hadas labrados sobre margas y arcillas blandas por la erosión torrencial. Su flora xerófila y fauna estepa albergan endemismos ibero-africanos exclusivos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04061','espacio','Monumento Natural Monumento Natural de las Fuentes de Lúcar (Balsa de Lúcar) y Sierra de Lúcar','Extraordinario manantial minero-medicinal termal que brota a temperatura constante durante todo el año, formando una balsa natural rodeada de centenarios árboles de sombra. La sierra anexa presenta imponentes escarpes calizos dolomíticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04089','espacio','Desfiladero de las Moletas y Rambla de Taberno','Estructura quebrada de rocas calizas y margas con crestas apuntadas que sufren una fuerte insolación.   Alberga comunidades de espartizales y tomillares adaptadas a la extrema aridez estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04027','espacio','Sierra de los Filabres (sector central) y cerro del Mojón','Relieve alomado de media montaña cubierto por extensas masas boscosas de pino carrasco y pino laricio de repoblación. Presenta afloramientos de mármol y pizarras oscuras que definen el perfil de sus cumbres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04091','espacio','Confluencia de los ríos Andarax y Nacimiento','Amplio lecho aluvial pedregoso donde se unen de forma estacional dos de las arterias hídricas de la provincia. El paisaje destaca por los impresionantes taludes de conglomerados que flanquean la vega.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04092','espacio','Cerrá de Tíjola (río Bacares) y balsa de Cela (manantial natural)','Estrecha y profunda garganta caliza o "cerrá" con paredes verticales labradas por la acción del agua de montaña. La balsa de Cela es un gran manantial termal de aguas cristalinas que brota de forma constante a unos 22°C.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04901','espacio','Rambla de Doña María y vertiente norte de Sierra Nevada','Corredor geológico flanqueado por los relieves béticos cubiertos de encinares de montaña y pinares. La rambla principal muestra un ancho cauce de piedras y una fisonomía de fuerte contraste tectónico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04028','espacio','Sierra Cabrera (vertiente oriental) y cañón del río Alímar','Macizo montañoso abrupto de origen volcánico y metamórfico con profundos barrancos y crestas afiladas. Aloja relictos de alcornocales, madroñales y fuentes kársticas escondidas de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04094','espacio','Mirador de las Estrellas (entorno natural) y ladera norte de Sierra Alhamilla','Escarpada ladera de materiales calizos y esquistos orientada al desierto de Tabernas, lo que le confiere una aridez visual extrema. Cuenta con bosquetes muy dispersos de encinas y matorral noble mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04095','espacio','Cerro de Monteagud y garganta de la Umbría','Elevación cónica caliza exenta que destaca de forma imponente sobre el paisaje alomado de los Filabres orientales. Sus laderas albergan encinares xerófilos y matorrales espinosos de interés biológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04096','espacio','Estrecho de Urrácal y lomas del Almanzora','Pequeño encajonamiento fluvial excavado sobre materiales blandos arcillosos con paredes de pendiente pronunciada. Presenta formaciones de matorral árido y espartizales de valor netamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04097','espacio','Alto de Velefique y barrancos pizarrosos de Filabres','Paisaje de alta montaña caracterizado por descomunales desniveles y vertientes desnudas formadas por lajas de pizarra negra. El relieve es quebrado, salvaje y ofrece una de las panorámicas geológicas más potentes de la cordillera penibética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04098','espacio','Parque Natural de Sierra de María-Los Vélez y Cueva de los Letreros','Macizo calcáreo colosal con impresionantes muelas y farallones rocosos blanquecinos tallados por el modelado kárstico. Alberga uno de los bosques de pino carrasco y encinares de montaña más densos y mejor conservados del sureste peninsular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04099','espacio','Sierra de la Muela, barranco del Infierno y llanuras del Chirivel','Imponente muela caliza de paredes escarpadas perimetrales que emerge sobre corredores llanos de sedimentación cuaternaria. Cuenta con ramblas encajadas llenas de adelfares salvajes y pinares dispersos de pino laricio.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04029','espacio','Desembocadura del río Antas y laguna de Vera','Humedal costero somero constituido por cañaverales y carrizales densos que sirve de refugio a la amenazada malvasía cabeciblanca. El entorno litoral presenta suaves dunas de arena en regresión.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04101','espacio','Rambla de Viator y terrazas del río Andarax','Paisaje semiárido llano erosionado por avenidas torrenciales con presencia de cárcavas menores sobre margas grisáceas. Su cobertura natural es escasa y posee un interés estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04030','espacio','Peñón de Bernal y barranco de Carcauz','Colosal aguja de roca caliza o peñón que emerge con fuerza tectónica en la ladera sur de la Sierra de Gádor. El barranco adyacente muestra formaciones geológicas angostas y una vegetación xerófila adaptada a la solana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04103','espacio','Rambla de Albox (tramo bajo) y cerros de Zurgena','Amplio cauce de sedimentos arenosos rodeado de colinas de yesos y margas sometidas a una intensa erosión eólica y pluvial. Su cubierta vegetal está degradada a matorral ralo de interés comarcal.   He finalizado exhaustivamente todos los municipios de la provincia de Almería. Propón el siguiente paso para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90682','espacio','Sierra del Palo, alcornocal de Salcedo y valle del río Oro','Paisaje montañoso de la Cordillera Cantábrica caracterizado por profundos valles de litología pizarrosa y crestas cuarcíticas. Alberga el alcornocal de Salcedo, una rareza botánica mediterránea relictual en plena cornisa atlántica húmeda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','espacio','Monumento Natural de las Foces del Pino, Puerto de San Isidro y cascada de Xurbeo','Impresionante desfiladero de caliza de montaña labrado por el río Valerones, con paredes verticales de un angosto absoluto. El relieve alpino se completa con el hayedo del gumial y saltos de agua cristalina entre formaciones kársticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05001','espacio','Parque Nacional de los Picos de Europa (Macizo Occidental) y Desfiladero de los Beyos','Territorio de alta montaña caliza caracterizado por el descomunal desfiladero del río Sella, con cortados rocosos verticales que superan los 500 metros de desnivel. Exhibe una orografía salvaje de canales, canchales y hayedos colgados de la roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05002','espacio','Ría de Avilés (charca de Zeluán) y ensenada de Llodero','Espacio intermareal estuarino compuesto por llanuras de fango y depósitos de arenas en el margen de la ría. Funciona como un humedal relicto de gran valor ecológico local para el descanso de aves limícolas migratorias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05003','espacio','Parque Natural de Somiedo (sector norte) y valle del río Pigüeña','Relieve abrupto cubierto por densas masas de bosque atlántico mixto, hayedos y robledales bien conservados. El río Pigüeña discurre encajado entre gargantas calizas formando pozas naturales de aguas frías y cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90638','espacio','Sierra de Peñamayor y nacimiento del río Pra','Relieve alomado de media montaña caliza con praderías alpinas y dolinas kársticas superficiales. El paisaje destaca por sus bosques mixtos de castaño, roble y avellano que tapizan las cuencas de recepción torrencial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90639','espacio','Embalse de Doiras (río Navia) y Sierra de Penouta','Vasto cañón fluvial inundado por el embalse, encajonado entre laderas pizarrosas de vertiginosa pendiente cubiertas de pinos y eucaliptos. La Sierra de Penouta aporta crestas cuarcíticas con formaciones de brezales y turberas atlánticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','espacio','Parque Nacional de los Picos de Europa, Garganta del Cares y Naranjo de Bulnes (Picu Urriellu)','Uno de los epicentros de la alta montaña europea; la garganta del Cares es un cañón calcáreo colosal de 1.500 metros de profundidad. El Picu Urriellu destaca como un imponente monolito de caliza paleozóica con una pared vertical pura de 500 metros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90640','espacio','Vega del río Nalón y desfiladero de la Peña','Amplio valle fluvial con llanuras aluviales cuaternarias que contrasta con pequeños estrechamientos calcáreos. El río Nalón mantiene un cauce caudaloso bordeado por vegetación de ribera y bosques de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05005','espacio','Parque Nacional de los Picos de Europa, Lagos de Covadonga (Enol y Ercina) y Cueva del Buxu','Entorno kárstico de alta montaña internacional donde los lagos de origen glaciar se asientan sobre cubetas de erosión caliza. El paisaje es soberbio, rodeado de neveros permanentes, lapiaces colosales, simas profundas y hayedos subalpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','espacio','Reserva Natural Integral de Muniellos y Parque Natural de las Fuentes del Narcea, Degaña e Ibias','Alberga el mayor y mejor conservado robledal de España (Muniellos), un bosque primigenio atlántico asentado sobre sustratos silíceos antiguos. El relieve presenta circos y lagunas de origen glaciar rodeados de picos escarpados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90010','espacio','Sierra del Sueve (vertiente norte) y acantilados de la Espasa','Impresionante cordal calizo costero que se eleva abruptamente desde el nivel del mar hasta superar los 1.000 metros de altitud. Sus laderas combinan pastizales alpinos azotados por la niebla con cortados rocosos litorales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90011','espacio','Cabo Torres (sector oeste) y acantilados de Perán','Tramo litoral constituido por acantilados de rasas costeras formados por areniscas y calizas devónicas. El relieve marino muestra plataformas de abrasión y formas de erosión costera azotadas por el mar Cantábrico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90641','espacio','Parque Natural de Redes, Monumento Natural de la Cueva Deboyu y nacedero del río Nalón (Tarna)','Reserva de la Biosfera caracterizada por inmensos bosques de hayas y el espectacular desfiladero kárstico de la Cueva Deboyu, donde el río Nalón se subterraniza por completo. Presenta picos calizos imponentes y circos glaciares bien definidos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90012','espacio','Monumento Natural de la Playa de El Espartal (sistema dunar) y acantilados de la Isla de Deva','Destaca el mayor sistema dunar de Asturias, una formación eólica costera con comunidades botánicas psammófilas singulares. La Isla de Deva es un gran islote rocoso que conforma un acantilado marino escarpado protector de avifauna.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90013','espacio','Reserva Natural Parcial de la Ría del Eo y cascada de Cioyo','Gran estuario atlántico con amplias llanuras intermareales de fangos y arenas ricas en comunidades de macrófitos marinos. En el interior, la cascada de Cioyo es un espectacular salto de agua oculto en un frondoso bosque de galería.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90014','espacio','Desembocadura del río Navia y acantilados de Ortiguera','Estuario fluvial encajado en materiales pizarrosos que se abre al Cantábrico flanqueado por altos acantilados oscuros. La costa no-playa presenta una   fisonomía abrupta con entrantes rocosos y bufaderos menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90015','espacio','Sierra del Sueve, acantilados de Lastres y yacimientos icnológicos','Paisaje de fuerte contraste donde la Sierra del Sueve (con sus bosques relictos de tejos) vierte sus aguas directamente hacia acantilados jurásicos verticales donde se aprecian estratos geológicos con huellas de dinosaurio.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90642','espacio','Embalse de Trasona y lomas de Solís','Humedal artificial de aguas tranquilas rodeado de colinas atlánticas suaves de baja altitud. Sirve como refugio local para pequeñas colonias de aves acuáticas y vegetación palustre nitrófila en un entorno industrializado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','espacio','Paisaje Protegido de la Costa Occidental de Asturias y Cabo Vidio','Impresionante tramo costero de acantilados pizarrosos verticales que superan los 80 metros de altura sobre el mar. El Cabo Vidio es un promontorio colosal con cavidades marinas inferiores (iglesias) esculpidas por el oleaje cantábrico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33022','espacio','Parque Natural de las Fuentes del Narcea, Degaña e Ibias y Laguna de Chanos','Territorio de alta montaña silícea dominado por el bosque de robles y abedules de la cabecera del río Ibias. Destaca por sus modelados glaciares con lagunas de montaña de aguas oscuras e清 transparentes rodeadas de canchales pizarrosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33023','espacio','Monumento Natural de las Cuevas de Andina y acantilados de Viavélez','Excepcional relieve kárstico desarrollado sobre mármoles cambrianos, donde la erosión ha creado un paisaje de agujas calcáreas cubiertas de vegetación mediterránea y cuevas semihundidas. La costa es rocosa y escarpada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','espacio','Cabo San Lorenzo, acantilados de la Providencia y monte Deva','Promontorio rocoso costero que constituye una perfecta rasa marina elevada con taludes verticales expuestos a la erosión marina. El monte Deva aporta un relieve forestal interior con arroyos torrenciales menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33025','espacio','Paisaje Protegido del Cabo de Peñas','El punto más septentrional de Asturias; un imponente cabo de acantilados cuarcíticos verticales que caen más de 100 metros sobre el océano. Presenta una rasa litoral de morfología llana azotada por fuertes vientos con brezales atlánticos únicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33026','espacio','Valle del río Cubia y desfiladero de Peñaflor','Cuenca fluvial cantábrica encajonada en su cabecera por relieves calizos y pizarrados que generan pequeñas foces o estrechamientos. Cuenta con un excelente bosque de ribera y masas forestales mixtas de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33027','espacio','Embalse de Salime (río Navia) y cascada de la Seimeira de Murias','Impresionante garganta fluvial inundada donde el río Navia corta las estructuras paleozoicas occidentales formando un cañón de laderas escarpadas. La Seimeira es un hermoso salto de agua de montaña rodeado de densas masas de castaños.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33028','espacio','Parque Natural de las Fuentes del Narcea, Degaña e Ibias y cañón del río Ibias','Paisaje indómito de aislamiento geográfico caracterizado por profundos barrancos y montañas de naturaleza silícea. Alberga densos alcornocales relictos y alisedas riparias vírgenes asentadas sobre laderas de pendiente extrema.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33029','espacio','Estrecho del río Navia y Sierra de la Bobia (estribaciones)','Tramo fluvial fuertemente encajonado donde el Navia erosiona las pizarras paleozoicas formando un relieve quebrado y abrupto. Las laderas están cubiertas de monte bajo atlántico, brezales y robledales autóctonos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33030','espacio','Pico Gorfolí y nacimiento del río d''Illas','Elevación alomada cuarcítica que destaca sobre el relieve costero de la comarca de Avilés. Su cumbre está cubierta por brezales y formaciones arbustivas atlánticas, con pequeños arroyos de cabecera de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33031','espacio','Paisaje Protegido de las Cuencas Mineras (sector Nalón) y pico Fario','Relieve montañoso de media altitud intensamente explotado por el ser humano pero que conserva laderas boscosas de castaños y llanuras fluviales recuperadas ecológicamente a orillas del Nalón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33032','espacio','Peña Mea y alta cuenca del río Nalón','Impresionante mole caliza que destaca por poseer un gigantesco ojo de roca o arco natural de erosión kárstica en su cumbre (El Güeyu de la Peña). Las vertientes presentan profundos canales de canchales y praderas subalpinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33033','espacio','Parque Natural de Las Ubiñas-La Mesa and Macizo de Ubiña','Espectacular territorio de alta montaña caliza con cumbres que superan los 2.400 metros de altitud, modeladas por la acción glaciar y kárstica. Presenta valles en U, simas profundas de alta montaña y frondosos hayedos de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33035','espacio','Curso alto del río Nora y lomas de Ables','Llanura central asturiana caracterizada por un relieve suavemente ondulado y lomas margosas. El río Nora discurre de forma sinuosa manteniendo pequeños sotos riparios antropizados de interés estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33036','espacio','Paisaje Protegido de la Costa Oriental de Asturias, Monumento Natural de los Bufones de Pría, Arenillas y Santiuste, y playa interior de Gulpiyuri','Uno de los litorales kársticos más espectaculares del planeta; los bufones son chimeneas naturales conectadas con cuevas marinas por donde el mar pulverizado sale eyectado a decenas de metros de altura. Gulpiyuri es una dolina inundada que forma una playa interior sin salida directa al mar.   He finalizado la primera parte de los municipios de la provincia de Asturias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33037','espacio','Valle de Turón y cumbre del pico Llosorio','Entorno de media montaña central asturiana configurado sobre relieves de pizarras y calizas carboníferas. Presenta laderas cubiertas de densos castañares y bosques mixtos atlánticos que se recuperan en los antiguos entornos mineros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33038','espacio','Monsacro (Monte Sagrado) y embalse de Alfilorios','Imponente macizo calizo aislado que emerge con paredes escarpadas y lapiaces kársticos de gran valor geomorfológico. A sus pies, la masa de agua artificial queda encajonada entre lomas boscosas atlánticas de gran belleza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33039','espacio','Desembocadura del río Nalón y acantilados del Espíritu Santo','Estuario fluvial de grandes dimensiones donde el río Nalón se encuentra con el Cantábrico, flanqueado por altos cortados de rasas costeras. Los acantilados muestran espectaculares secciones geológicas de areniscas y materiales paleozoicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33040','espacio','Sierra de Peñamayor y gargantas del río Pendón','Relieve calizo caracterizado por profundas entalladuras fluviales y desfiladeros estrechos rodeados de vegetación rupícola. La sierra presenta praderas alpinas altas salpicadas de dolinas y densos hayedos en sus vertientes umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33041','espacio','Estuario del río Navia, Cabo Agustín y acantilados de El Moro','Amplio estuario mareal encajonado en pizarras que genera llanuras de fango y una notable barra arenosa en su boca. La línea de costa destaca por sus acantilados oscuros y escarpados azotados por el mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33042','espacio','Riberas del río Noreña','Reducido término municipal plano en la zona central asturiana sin relieves significativos. El curso fluvial mantiene una modesta franja de vegetación riparia muy antropizada y de interés puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33043','espacio','Parque Nacional de los Picos de Europa (Macizo Occidental) y ría de Cares (zona alta)','Territorio de alta montaña kárstica con espectaculares lapiaces, grandes simas de rango mundial y majadas alpinas. Sus bosques están dominados por densos   hayedos subalpinos asentados sobre desniveles calcáreos vertiginosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','espacio','Monte Naranco y meandros del río Nora','El Monte Naranco constituye un anticlinal cuarcítico que domina la depresión ovetense con brezales y masas forestales mixtas. Al norte, el río Nora labra unos meandros encajonados excepcionales en rocas calizas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33045','espacio','Sierra del Sueve (vertiente sur) y confluencia de los ríos Sella y Piloña','Gran nudo hidrológico fluvial rodeado por la imponente presencia de la cordillera caliza del Sueve. Las laderas presentan densos bosques mixtos atlánticos, pastizales de montaña y canales de desmantelamiento torrencial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33046','espacio','Paisaje Protegido de la Sierra de Cuera y desfiladero del río Cares','Espectacular geografía de montaña donde la mole caliza de la Sierra de Cuera corta el paisaje con sus cumbres afiladas. El río Cares corre encajado formando profundas gargantas calizas con vegetación rupícola óptima.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33047','espacio','Desfiladero de La Hermida (sector asturiano) y río Deva','Imponente garganta kárstica con formaciones de paredes verticales calizas colosales erosionadas por el río Deva. Coexisten encinares cantábricos atesorados en las solanas rocosas con hayedos y sotos riparios en las umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33048','espacio','Valle del río Agüeira y cañón del Navia (cola del embalse)','Territorio abrupto del occidente asturiano caracterizado por laderas pizarrosas de pendientes extremas. El río Agüeira discurre limpio encajonado entre densos bosques de castaños, robles y alisedas de galería.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33049','espacio','Sierra del Sueve (vertiente occidental), cueva del Sidrón y río Piloña','Amplio valle fluvial flanqueado por la colosal masa caliza del Sueve y sus bosques de tejos relictos. La cueva del Sidrón es una importante cavidad kárstica de desarrollo horizontal en un entorno boscoso mixto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33050','espacio','Parque Natural de Ponga, Desfiladero de los Beyos y Bosque de Peloño','Territorio de montaña indómito que alberga el Bosque de Peloño, uno de los hayedos más extensos, puros y espectaculares de España. El desfiladero de los Beyos corta calizas colosales formando paredes verticales de varios cientos de metros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33051','espacio','Confluencia de los ríos Nalón y Narcea, y estrecho de Peñaullán','Gran llanura aluvial y delta interior donde se unen los dos ríos más caudalosos de la región. El entorno presenta sotos fluviales maduros e imponentes escarpes cuarcíticos que flanquean la vega.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33052','espacio','Monumento Natural del Desfiladero de las Xanas y Peña de Proaza','Espectacular y estrecho cañón kárstico labrado por el arroyo de las Xanas en la roca caliza, con túneles naturales y paredes verticales. El entorno boscoso umbrío presenta una biodiversidad botánica atlántica sobresaliente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','espacio','Parque Natural de Las Ubiñas-La Mesa, macizo de peña Rueda y caldas de Bárzana','Impresionante paisaje alpino dominado por la imponente mole caliza simétrica de Peña Rueda. Cuenta con circos glaciares, extensos hayedos de ladera y profundos valles en U modelados por el hielo cuaternario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33054','espacio','Meandros del río Nalón (zona central) y lomas de Santullano','Relieve alomado atlántico surcado por el curso bajo del Nalón, que forma suaves curvas e islotes de grava. Conserva retazos de bosque mixto y vegetación riparia de alisos de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33055','espacio','Paisaje Protegido de la Costa Oriental, Cabo de San Emeterio y cueva de El Pindal','Majestuosa rasa costera caliza que termina en acantilados verticales colgados sobre el mar Cantábrico. La cueva de El Pindal es una espectacular galería kárstica natural abierta directamente sobre el acantilado marino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33056','espacio','Estuario del río Sella, Monumento Natural de los Cuevas del Agua y acantilados de Guadamía','Extraordinario conjunto natural donde destaca Cuevas del Agua, un túnel kárstico natural por el que discurre un arroyo y la carretera. Los acantilados de Guadamía presentan espectaculares bufaderos e islotes rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33057','espacio','Confluencia del río Caudal con el Nalón y laderas del monte Monsacro (estribaciones)','Cuenca fluvial encajada entre colinas calizas y margosas con una importante llanura aluvial. Mantiene un corredor verde de sauces y chopos en un entorno geográfico de transición asturiana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33058','espacio','Sierra del Aramo and Alto de L''Angliru (entorno natural)','Impresionante murallón calizo que conforma la Sierra del Aramo, caracterizado por un paisaje kárstico de alta montaña. Presenta dolinas de colapso, canchales de ladera extremos y pastizales subalpinos azotados por la erosión.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33059','espacio','Valle del río Nonaya, cascada del Nonaya y Sierra de Bodenaya','El río Nonaya corre por un valle encajonado de pizarras y areniscas, generando una hermosa cascada escondida entre densos bosques de carbayos y castaños. La sierra aporta relieves alomados cuarcíticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33061','espacio','Valle del río Sotuelo y laderas de la Sierra de la Bobia','Paisaje indómito del occidente asturiano con valles profundos labrados en pizarras paleozoicas. Alberga frondosos bosques de robles, castaños y abedules en un relieve de alta tranquilidad ambiental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33060','espacio','Valle de Santa Bárbara y riberas del río Nalón','Relieve de media montaña integrado en las cuencas mineras, con valles secundarios bien conservados. Las laderas muestran densas masas de castaños que contrastan con el fondo de valle aluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33063','espacio','Valle aluvial del río Eo (límite provincial)','El río Eo forma aquí una vega fluvial ancha y meandriforme de aguas cristalinas de gran valor salmonícola. El paisaje boscoso de las laderas está dominado por robledales y densas alisedas de galería.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33062','espacio','Reserva de la Biosfera del Río Eo, Oscos e Terras de Burón, y cascada de Seimeira','Espectacular salto de agua o seimeira de más de 30 metros de caída libre en el río Agüeira. El entorno es un espeso bosque atlántico virgen y cerrado de robles, avellanos, musgos y helechos relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33064','espacio','Desfiladero de Proaza (río Trubia) y desfiladero de las Xanas (sector bajo)','Estrecho y colosal tajo fluvial excavado en calizas de montaña que configura paredes verticales de gran altitud. Alberga densos bosques mixtos de ladera y encinares cantábricos asentados sobre la roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33065','espacio','Valle de Sariego y nacimiento del río Nora','Pequeña depresión topográfica suave rodeada de colinas atlánticas que conforma la cabecera del río Nora. Presenta un paisaje pratense con pequeños rodales forestales mixtos de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33066','espacio','Riberas del río Nora, meandros de Lugones y peña de Celles','Llanura central asturiana rota por pequeños afloramientos calizos y el cauce sinuoso del río Nora. Ofrece sotos riparios y pequeños humedales asociados a las antiguas llanuras de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33067','espacio','Parque Natural de Redes, Desfiladero de los Arrudos y embalse de Tanes','Impresionante cañón kárstico de paredes verticales calcáreas excavado por el río de los Arrudos. Aloja hayedos majestuosos, crestas rocosas alpinas y el espejo de agua del embalse encajado en la montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33068','espacio','Parque Natural de Somiedo, Conjunto Lagunar de Somiedo (Lago del Valle, lagunas de Saliencia) y circos glaciares','Uno de los paisajes glaciares y de alta montaña más espectaculares de la Península. El Lago del Valle es el mayor lago de Asturias, encajado en un colosal circo glaciar rodeado de cumbres calizas, hayedos densos y valles en U.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33069','espacio','Desembocadura del río Nalón (rías de San Esteban y San Juan)','Amplia y majestuosa ría fluvial asturiana donde el Nalón entrega sus aguas al mar Cantábrico. El paisaje destaca por los intermareales de fangos, dunas relictas y los altos escarpes boscosos que flanquean la ría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33070','espacio','Acantilados de Tapia, islote de El Franco y lagunas de Salave','Costa rocosa de pizarras y areniscas intensamente erosionada por el mar, formando islotes, arcos de piedra y bufaderos menores. Las lagunas de Salave son antiguas excavaciones romanas integradas hoy como lagos forestales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33071','espacio','Cuenca del río Turía y cascada de la Salgueira','Territorio montañoso occidental de relieve quebrado y valles profundos tapizados de densos bosques mixtos atlánticos. La cascada de la Salgueira es un hermoso salto de agua escondido en un entorno de alta humedad y helechos monumentales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33072','espacio','Parque Natural de Las Ubiñas-La Mesa, Cueva de Huerta y desfiladero de Estrechura','Espectacular relieve de alta montaña caliza con el desfiladero de Estrechura y la colosal Cueva de Huerta, una de las mayores cavidades kársticas de Asturias con kilómetros de galerías. Alberga imponentes hayedos de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33073','espacio','Monumento Natural de las Hoces del Esva (límite) y Carbayón de Valentín','El Carbayón de Valentín es un roble monumental centenario de proporciones colosales. Las hoces del Esva forman un cañón cuarcítico estrecho y profundo cubierto de madroñales y carrascales cantábricos de gran valor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33034','espacio','Paisaje Protegido de la Cuenca del Esva, Monumento Natural de las Hoces del Esva y Cabo Busto','El río Esva excava un impresionante y angosto desfiladero cuarcítico con paredes verticales cubiertas de vegetación. Cabo Busto constituye una de las rasas costeras más perfectas de Asturias, con acantilados pizarrosos rectilíneos de gran altura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33074','espacio','Reserva Natural Parcial de la Ría del Eo y valle del río Suarón','Extensa llanura intermareal y marisma estuarina en el límite occidental de Asturias, de altísimo valor ornitológico y botánico palustre. El río Suarón aporta un valle de montaña encajonado con densas masas forestales de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33075','espacio','Sierra de la Bobia y nacimiento del río Pasarón','Paisaje indómito de lomas paleozoicas elevadas cubiertas de extensos brezales, turberas altas y densas manchas de robledal atlántico. El relieve es quebrado y ofrece una fisonomía de aislamiento geográfico puro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33076','espacio','Reserva Natural Parcial de la Ría de Villaviciosa y acantilados de Tazones','Uno de los estuarios mejor conservados de la cornisa cantábrica, con amplias llanuras de fango, dunas arenosas y comunidades de aves acuáticas invernantes. Los acantilados de Tazones muestran estratos jurásicos verticales de alto valor geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33078','espacio','Puerto de Marabio (sector norte) y turberas de Cuevallagar','Paisaje kárstico de media montaña caracterizado por la presencia de dolinas, lapiaces y praderas alpinas de pastoreo. Cuenta con pequeñas cavidades kársticas y sumideros naturales donde desaparecen los arroyos de montaña.   He completado de forma masiva y exhaustiva todos los municipios de la provincia de Asturias. Propón el siguiente paso para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90074','espacio','Lagunas estacionales de la Moraña y pinares de Adanero','Pequeñas depresiones endorreicas sobre la llanura sedimentaria arenosa del norte provincial. Acumulan agua de forma intermitente durante el invierno, sirviendo de refugio temporal a avifauna esteparia y anfibios locales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51015','espacio','Garganta de Santa María, pinar de las Cruces y garganta de la Pinosa','Escarpado relieve en la vertiente sur de la Sierra de Gredos cubierto por frondosos bosques de pino resinero y castañares monumentales. El arroyo de montaña desciende con gran fuerza formando pozas de aguas cristalinas y saltos entre bloques graníticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90075','espacio','Encinares de Albornos y arroyo de Berlanas','Relieve horizontal de la penillanura abulense salpicado por pequeños afloramientos graníticos aislados. Cuenta con rodales muy dispersos de encina mediterránea de interés estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90076','espacio','Vertiente norte de la Sierra de Villafranca y arroyo de los Cabreros','Ladera montañosa granítica con fuertes pendientes orientadas al valle del Tormes. El relieve presenta formaciones de canchales rústicos y vegetación de piornal y matorral de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90077','espacio','Cárcavas del arroyo del Regajal','Pequeñas incisiones torrenciales provocadas por la erosión pluvial sobre depósitos arcillosos de la cuenca del Duero. Su cobertura natural es escasa y posee un valor visual puramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90280','espacio','Tierras Altas de Soria, cañón del río Cidacos y dehesa de Los Campos','Paisaje descarnado y abrupto de alta montaña caliza, caracterizado por una fuerte erosión que expone los estratos sedimentarios del Cretácico. El curso alto del Cidacos desciende encajonado entre canchales rocosos y matorrales de cambroneras y sabinas rústicas de gran valor visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90078','espacio','Valle del río Adaja y laderas de la Sierra de Ávila','Tramo alto del río Adaja donde discurre encajonado entre lomas graníticas cubiertas de encinar y matorral esclerófilo. Presenta acumulaciones de bolos graníticos en el cauce que generan pequeñas corrientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51008','espacio','Parque Regional de la Sierra de Gredos (vertiente sur) y cabecera de la garganta de las Elías','Impresionante anfiteatro montañoso caracterizado por vertiginosas pendientes alpinas que culminan en crestas granitoides desnudas. Alberga frondosos bosques mixtos de pinos, castaños y robles melojos regados por torrenteras de agua pura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','espacio','Parque Regional de la Sierra de Gredos, Garganta de Lóbrega, Charco de la Pelá y cuevas del Águila (límite)','Extraordinario conjunto natural donde destacan las Cuevas del Águila, una joya kárstica subterránea en calizas cristalinas con colosales formaciones de estalactitas. Las gargantas de Gredos aportan un relieve de pozas cristalinas profundas esculpidas en granito.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90079','espacio','Riberas del río Arevalillo y encinares de solana','Curso de agua modesto encajado suavemente sobre materiales sueltos cuaternarios. Mantiene un cinturón verde de sauces y chopos que contrasta con la aridez cerealista de la comarca circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','espacio','Confluencia de los ríos Adaja y Arevalillo, y pinares de la Lugareja','Impresionante corte geológico provocado por el encajamiento de ambos ríos en los sedimentos de la submeseta norte, formando altos taludes arcillosos. Los pinares piñoneros del entorno asientan sobre extensas llanuras arenosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90080','espacio','Arroyo de Aveinte y lomas de cultivo','Paisaje predominantemente llano y desarbolado característico de la comarca de la Moraña Alta. Cuenta con   pequeñas lomas erosionadas y escorrentías estacionales de nulo relieve paisajístico exterior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90081','espacio','Ribera alta del río Tormes y dehesa boyal de Avellaneda','Paisaje de media montaña granítica donde el Tormes empieza a ensanchar su cauce sobre depósitos de cantos rodados. El entorno forestal destaca por quejigares y robledales bien conservados de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','espacio','Valle del río Adaja, encinar de la Colilla y dehesas de la Alamedilla','El río Adaja labra una pequeña hoz granítica a los pies de la ciudad con formaciones de berrocal notables. El entorno cuenta con dehesas maduras de encina asentadas sobre suelos silíceos ásperos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51003','espacio','Garganta de los Caballeros (desembocadura), río Tormes y riberas del Aravalle','Majestuoso nudo hidrológico donde las frías aguas de las cumbres de Gredos confluyen en un amplio cauce granítico lleno de islas fluviales y llanuras aluviales de cantos. Los sotos de alisos y sauces presentan una madurez excepcional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90082','espacio','Valle de Iruelas (Reserva Natural), Embalse de El Burguillo y río Alberche','Extraordinario entorno natural que destaca por albergar una de las colonias de buitre negro más importantes de Europa en sus laderas repletas de pinos laricios y pinos negrales centenarios. El embalse aporta una gran masa láctica encajada entre montañas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90083','espacio','Arroyo de Barromán y llanura cerealista','Paisaje agrícola de la Moraña sin accidentes geográficos significativos. El arroyo presenta un carácter marcadamente torrencial e intermitente con pequeñas cubetas de carrizal de interés puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90084','espacio','Sierra de Béjar (vertiente abulense) y río Cuerpo de Hombre','Relieve de alta montaña silícea caracterizado por abruptas laderas cubiertas de densos bosques de roble melojo y castaños monumentales. Los arroyos de cabecera corren limpios entre bloques graníticos y praderías de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05025','espacio','Nacimiento del río Gamo y lomas graníticas','Zona de transición entre la penillanura y la sierra con relieves ondulados de granito desmantelado. Las pequeñas fuentes dan origen al río Gamo en un entorno de pastizales y matorral bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05026','espacio','Río Zapardiel (tramo alto)','Cauce fluvial intensamente modificado y de escaso caudal enclavado en la llanura sedimentaria del Duero. Su interés biológico es muy bajo y restringido al ámbito agrícola comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05027','espacio','Arroyo de las Berlanas y pinares de repoblación menores','Paisaje llano caracterizado por suelos arenosos del cuaternario donde se asientan rodales dispersos de pino resinero de valor ambiental estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05030','espacio','Berrocal de Aragona y río Adaja (límite)','Excepcional ejemplo de modelado granítico superficial o berrocal con abundantes piedras caballeras, bolos gigantescos y formas de alteración meteorológica en las rocas. El Adaja corre encajado en un tajo granítico menor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05033','espacio','Arroyo de Blascomillán y encinar residual','Suaves ondulaciones de la penillanura granítica con presencia de encinar degradado a matorral y pastos secos. Alberga pequeños afloramientos rocosos planos de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05034','espacio','Arroyo de Matacabras','Modesta vaguada que recoge las escorrentías superficiales de la planicie cerealista del norte abulense. Presenta carrizales menores y una fisonomía desprovista de relieve visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05037','espacio','Parque Regional de la Sierra de Gredos, Garganta de Bohoyo y praderas del nacedero del río Tormes','Impresionante y largo valle de origen glaciar en forma de U encajonado entre colosales picos graníticos que superan los 2.300 metros de altitud. La garganta desciende de forma torrencial con espectaculares cascadas, pozas de roca pulida y canchales de ladera puros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05038','espacio','Valle del Corneja (límite norte) y cerro de San Miguel','Relieve alomado de naturaleza granítica y metamórfica que domina el valle del Corneja. Presenta encinares de montaña en las solanas y pastizales desarbolados en las zonas más elevadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05039','espacio','Dehesa de Brabos y arroyo de Chamartín','Paisaje llanense granítico salpicado de encinas solitarias y afloramientos rocosos aislados. Funciona como zona de pastizal mediterráneo con un valor paisajístico bajo y de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05040','espacio','Encinar de Bularros y riberas del río Voltoya','Espacio forestal dominado por encinas y enebros asentados sobre terrenos arenosos y graníticos de transición. El río Voltoya aporta una pequeña línea verde de vegetación riparia bien conservada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05041','espacio','Valle del río Alberche, Garganta del Puerto y puente de la Nueva (pozas naturales)','Amplio valle fluvial granítico excavado por el río Alberche entre las sierras de Gredos y la Paramera. El río forma un espectacular rosario de pozas de arena limpia y grandes bloques de piedra pulida rodeados de densos bosques de ribera.   He finalizado la primera sección de los municipios de la provincia de Ávila en estricto orden alfabético nacional. Propón el siguiente tramo para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05042','espacio','Pinares de Cabezas y llanura de la Moraña','Paisaje horizontal sobre arenas limosas cuaternarias dominado por un monocultivo de cereal y pino resinero disperso. Su valor radica en el interés ecológico local como corredor de avifauna esteparia menor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05043','espacio','Arroyo del Pozo y campos de la Moraña','Depresión topográfica muy suave que recoge aguas pluviales en un entorno deforestado de la submeseta norte. Posee comunidades de carrizal y enea de carácter temporal y rango estrictamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05044','espacio','Dehesas de Cabezas del Villar y río Almar','Extensa llanura granítica adehesada con encinas centenarias y afloramientos de lanchas pétreas horizontales. El río Almar cruza el término formando un cauce somero de arenas y bolos graníticos redondeados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05046','espacio','Arroyo de Canales y pinares de repoblación','Relieve plano de la comarca de la Moraña Alta con suelos arenosos estériles colonizados por pequeñas masas de pino piñonero. Su atractivo es bajo, limitándose al interés forestal local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05047','espacio','Parque Regional de la Sierra de Gredos, Garganta de Santa María, Garganta de Alardos y embalse de Rosarito','Impresionante desplome tectónico con desniveles de más de 2.000 metros desde las cumbres de granito hasta el valle del Tiétar. Aloja colosales pozas naturales de aguas turquesas y masas forestales relictas de robledales, castañares y enebros de la miera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05048','espacio','Vaguada del río Zapardiel','Tramo de la cuenca del Zapardiel caracterizado por una fuerte degradación fluvial en un entorno plano de cultivos extensivos. Su interés geográfico es mínimo y restringido al ámbito local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05049','espacio','Berrocal de Cardeñosa y dehesa del campo','Espectacular paisaje de modelado granítico o berrocal jalonado por piedras caballeras, torcas y bloques agrietados por la meteorización. La vegetación se reduce a encinas encajadas entre las grietas de la roca viva.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05052','espacio','Puerto de Villatoro y nacimiento del río Gamo','Paso montañoso granítico que sirve de divisoria de aguas entre las cuencas del Duero y del Tajo. Las laderas están cubiertas por densas formaciones de piornal y robledales de montaña baja de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05053','espacio','Hoz del río Chico y encinar de Casasola','Pequeño desfiladero excavado por el río Chico sobre los materiales graníticos de la Sierra de Ávila. Cuenta con laderas de pendientes moderadas cubiertas de encinar termófilo y matorral de solana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05054','espacio','Sierra de Gredos (vertiente sur), garganta de la Fuente Helecha y pinar de Casavieja','Excepcional ladera boscosa atlántica enclavada en el Valle del Tiétar, dominada por densas masas de pino negral y castaños monumentales. El arroyo desciende por un lecho de bloques de granito generando cascadas y fuentes de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05055','espacio','Valle de Iruelas (estribaciones), Alto de la Mirlo y castañar de Casillas','Impresionante relieve montañoso donde se asienta uno de los bosques de castaños (Castanea sativa) más extensos, densos y longevos del Sistema Central. El paisaje cambia drásticamente en otoño, ofreciendo una policromía visual soberbia bajo las crestas graníticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05056','espacio','Riberas del río Zapardiel (límite provincial)','Llanura aluvial cuaternaria donde el cauce del río discurre encajado artificialmente entre cultivos de secano. Cuenta con rodales aislados de chopos y álamos de valor paisajístico puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05057','espacio','Valle del río Alberche, garganta de la balsa y cerro de la Guija','Relieve quebrado y abarrancado de naturaleza granítica y pizarrosa moldeado por el río Alberche y el embalse de San Juan. Las laderas albergan densos pinares de pino piñonero y carrascales adaptados a veranos térmicos mediterráneos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05058','espacio','Sierra de la Paramera, alta cuenca del río Alberche y garganta de la balsa','Paisaje de alta montaña caracterizado por un amplio valle elevado de origen periglaciar cubierto de   pastizales y piornales. El río Alberche discurre serpenteante formando praderas húmedas o trampales de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05067','espacio','Sierra de Ávila (sector oriental) y dehesa de Chamartín','Vertiente escarpada granítica con canchales y acumulaciones de bolos rocosos redondos de gran fuerza geomorfológica. La vegetación dominante es el encinar mediterráneo degradado a matorral xerófilo de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05059','espacio','Vertiente norte de la Sierra de Ávila y arroyo de Cillán','Lomas de material granítico desmantelado que descienden hacia la penillanura central. El arroyo local mantiene pequeños sotos de sauces y fresnos encajonados de interés ecológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05060','espacio','Arroyo de Cisla y llanura cerealista','Relieve plano sin accidentes geográficos notables en el norte de la provincia. Muestra un entorno intensamente humanizado dedicado al cultivo con escorrentías intermitentes de rango estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05061','espacio','Canteras históricas (entorno natural) y lomas del Adaja','Afloramientos de areniscas y granitos de tonos amarillentos y rojizos sometidos a la erosión eólica. Presenta pequeños matorrales esclerófilos de baja cobertura en un relieve alomado menor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05062','espacio','Monte de pino resinero y campos de la Moraña','Suave ondulación del terreno sobre depósitos arenosos de la cuenca sedimentaria del Duero. Alberga un   rodal forestal de coníferas explotado tradicionalmente, con un valor natural de nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05063','espacio','Sierra de Ávila (sector occidental) y alto de la dehesa','Relieve montañoso de altitud media que actúa como nudo geográfico entre el valle del Corneja y las llanuras salmantinas. El paisaje está desprovisto de árboles altos, dominado por matorral de piornos y peñascales expuestos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05064','espacio','Llanuras arenosas de Constanzana','Espacio plano absoluto de la comarca de la Moraña sin cursos de agua permanentes ni accidentes topográficos. Su único valor natural se centra en las colonias estacionales de aves esteparias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05065','espacio','Lagunas estacionales de Crespos y pinares de Chaherrero','Pequeñas depresiones arcillosas endorreicas que retienen agua en épocas de lluvias abundantes. El paisaje está flanqueado por pequeños rodales de pino piñonero sobre arenas compactas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05066','espacio','Parque Regional de la Sierra de Gredos, Puerto del Pico y nacimiento del río Tiétar','Espectacular anfiteatro granítico de alta montaña que conforma la cabecera del Valle del Tiétar. El relieve presenta profundos barrancos, colosales canchales de ladera e imponentes saltos de agua cristalina rodeados de pinares y castañares.   He completado este bloque de los municipios de la provincia de Ávila en estricto orden alfabético. Indícame cómo prefieres que.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05903','espacio','Riberas del río Gamo y dehesas graníticas de Diego del Carpio','Relieve alomado de la penillanura abulense donde el río Gamo discurre someramente entre bolos graníticos y arenas de sedimentación. El entorno forestal conserva rodales dispersos de encinas y fresnedas de uso ganadero tradicional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05070','espacio','Arroyo de Donvidas y campos de la Moraña','Paisaje horizontal absoluto de la submeseta norte dedicado al monocultivo de cereal de secano. El arroyo presenta un régimen marcadamente intermitente con nulo interés visual exterior y rango estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05072','espacio','Vaguada del río Adaja (límite oriental)','Pequeña franja de sedimentos cuaternarios en el margen del río Adaja, sin relieves escarpados ni accidentes geológicos notables. Alberga una modesta línea de vegetación riparia de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05073','espacio','Riberas del río Trabancos y pinares de Flores','Curso fluvial de carácter torrencial que discurre encajado entre terrazas aluviales de arenas y limos. El entorno cuenta con pequeñas masas de pino piñonero adaptadas a la acusada sequedad estival del suelo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05074','espacio','Humedal de la Laguna de la Berlanilla y campos de la Moraña','Modesta depresión endorreica que acumulates aguas superficiales durante los inviernos lluviosos en plena llanura cerealista. Carece de relieve y posee interés ecológico local para el descanso de aves de paso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05075','espacio','Vertiente norte de la Sierra de San Vicente y dehesas de Fresnedilla','Suaves elevaciones de origen granítico que enlazan con el valle del Tiétar bajo una influencia climática mediterránea templada. El paisaje destaca por sus dehesas mixtas de encina y alcornoque bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05076','espacio','Confluencia de los ríos Adaja y Corneja (Valle Amblés) y fresnedas del Fresno','Amplia llanura aluvial cuaternaria de inundación sedimentaria en el centro de la fosa tectónica del Valle Amblés. Alberga fresnedas adehesadas maduras que aprovechan el nivel freático elevado de los cursos de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05077','espacio','Arroyo del Saúz y llanuras cerealistas','Territorio plano de carácter agrícola intensivo sin formaciones geológicas ni masas forestales originales. Las pequeñas escorrentías temporales presentan carrizales degradados de valor únicamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05078','espacio','Pinares de Fuentes de Año y arroyo de Arevalillo','Zonas llanas de arenas sueltas eólicas colonizadas por repoblaciones forestales homogéneas de pino piñonero. Sirve como hábitat comarcal para pequeñas rapaces y avifauna común forestal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05079','espacio','Sierra de Ávila (sector central) y dehesa de Altamiros','Relieve de media montaña granítica con abundantes pedrizas y afloramientos rocosos fisurados por la meteorización termoclástica. Presenta matorrales de ladera compuestos por escobas, piornos y encinas enanas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05080','espacio','Nacimiento del río Zamprón y lomas graníticas','Ondulaciones suaves de la penillanura occidental abulense que configuran la cabecera de pequeñas redes de drenaje fluvial. Su cubierta vegetal dominante está constituida por pastos secos y romerales locales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05081','espacio','Alta cuenca del río Alberche, Sierra de la Paramera y nacedero del río Alberche','Impresionante valle elevado de montaña donde el río Alberche serpentea dibujando meandros sobre una llanura de turberas y pastizales húmedos (cervunales). El entorno está flanqueado por peñascales graníticos y piornales subalpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05082','espacio','Parque Regional de la Sierra de Gredos (vertiente sur), Garganta del Chorro y castañar de Gavilanes','Vertiginoso relieve granítico que desciende hacia el Valle del Tiétar, caracterizado por sus profundos barrancos y saltos de agua cristalina de gran envergadura. Las umbrías boscosas albergan masas excepcionales de castaños longevos y pinares de pino resinero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05083','espacio','Riberas del río Adaja inferior y cerros del Valle Amblés','Tramo fluvial rodeado por una llanura sedimentaria con pequeños cerros testigo de materiales graníticos meteorizados. Mantiene sotos de sauces y chopos negros de interés ecológico y paisajístico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05085','espacio','Parque Regional de la Sierra de Gredos, Garganta de Gualix y alta cuenca del río Aravalle','Paisaje indómito de alta montaña granítica modelado por la acción glaciar cuaternaria con circos y canchales extremos. La garganta desciende de forma torrencial entre bloques colosales de roca formando pozas y cascadas vírgenes de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05086','espacio','Arroyo de Gimialcón y dehesa residual','Terreno suavemente ondulado de la penillanura arcillo-arenosa noroccidental con cultivos de secano. Cuenta con rodales muy dispersos de encina mediterránea aislada de interés puramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05087','espacio','Arroyo de la Dehesa y lagunas estacionales de Gotarrendura','Pequeñas depresiones del terreno que retienen las aguas de lluvia invernales sobre los suelos limosos del norte provincial. Albergan carrizales modestos y sirven de abrevadero estacional para avifauna de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05088','espacio','Riberas del río Almar y lomas de la penillanura','Paisaje granítico desarbolado caracterizado por suaves ondulaciones del terreno y afloramientos de lanchas de piedra horizontales. El río Almar aporta un curso de agua estacional con pequeños depósitos de arenas limpias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05089','espacio','Parque Regional de la Sierra de Gredos, Los Galayos, Cabeza de Víbora y Garganta de los Pelayos','Uno de los paisajes geomorfológicos más espectaculares de España; Los Galayos constituyen un imponente conjunto de agujas y crestas afiladas de roca granítica exenta que se elevan verticalmente de forma colosal. El entorno cuenta con profundos cañones rocosos, pozas turquesas y densos pinares de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05090','espacio','Llanura arenosa de Gutiérrez-Muñoz','Espacio plano absoluto integrado en la comarca de la Moraña Alta sin accidentes orográficos ni redes hidrográficas estables. Posee un valor natural relicto centrado en las especies de avifauna esteparia de paso local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05092','espacio','Pinares de Hernansancho y arroyo del Estepar','Terreno llano de arenas eólicas cuaternarias cubierto por una masa forestal homogénea de pino resinero explotado tradicionalmente para el miera. Funciona como un pulmón verde de interés netamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05093','espacio','Sierra de la Paramera (sector oriental), cuenca del río Gaznata y pinar del Hoyo','Escarpado relieve de montaña granítica caracterizado por el encajamiento de la cuenca fluvial que genera profundos valles de erosión lineal. Alberga densos pinares de pino resinero y canchales rocosos donde anidan grandes rapaces ibéricas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05094','espacio','Riberas del río Arevalillo (curso alto) y encinares de Suso','Pequeño valle fluvial granítico con relieves alomados suaves cubiertos por manchas dispersas de encinar mediterráneo y pastizales rústicos. Su interés es modesto, restringido al ámbito local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05095','espacio','Valle del Alberche (sector sur) y laderas de la Sierra de la Higuera','Territorio de transición granítica hacia la vertiente del Tajo con un relieve quebrado y abarrancado cubierto de denso matorral esclerófilo. Coexisten encinares maduros con enebros de la miera y alcornocales dispersos de interés geobotánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05096','espacio','Vertiente sur de la Sierra de Ávila y arroyo de la Hija','Laderas de pendiente moderada constituidas por materiales graníticos meteorizados que vierten hacia el   Valle Amblés. Presenta formaciones de berrocal menor y matorrales espinosos de escobas de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05103','espacio','Valle del Corneja (cabecera) y dehesa de Hoyorredondo','Depresión tectónica con suelos de alteración granítica que sustentan un paisaje adehesado de encinas y quejigos de gran valor ecológico. Los márgenes muestran colinas redondeadas y pequeños afloramientos de bolos rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05106','espacio','Sierra de la Paramera, cerro de la Camocha y alta cuenca del Alberche','El municipio más alto de la provincia, caracterizado por un paisaje de alta montaña desarbolada sometido a intensos procesos periglaciares. Destaca por sus inmensas extensiones de piornales (Cytisus oromediterraneus) y roquedos graníticos expuestos al viento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05104','espacio','Parque Regional de la Sierra de Gredos, río Tormes y garganta del Chorro (límite)','Entorno alpino de gran fuerza visual donde el río Tormes corre encajado en un cauce de grandes bloques graníticos pulidos. Las laderas muestran densas masas de pino silvestre o albar y piornales altos que ascienden hacia los circos glaciares superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05105','espacio','Parque Regional de la Sierra de Gredos, Plataforma de Gredos (entorno natural), Garganta de Gredos y río Tormes','Uno de los principales portales de la alta montaña de Gredos; destaca por el modelado glacial del valle con morrenas, valles en U y colosales canchales graníticos. El río y las gargantas forman pozas de aguas heladas turquesas rodeadas de bosques de pino albar primigenios.   He completado este tramo masivo de municipios de la provincia de Ávila en estricto orden alfabético. Indícame cómo prefieres que.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05107','espacio','Riberas del río Zamprón y dehesa de Hurtumpascual','Paisaje granítico de la penillanura central abulense caracterizado por suaves ondulaciones del terreno y afloramientos de lanchas pétreas. El río mantiene un modesto corredor de sauces y fresnedas adehesadas de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05108','espacio','Valle del río Aravalle y estribaciones de la Sierra de Béjar','Relieve de media montaña silícea con laderas de fuerte pendiente cubiertas de robledales de melojo. El río Aravalle discurre limpio por un lecho de cantos rodados y grandes bloques graníticos esculpidos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05109','espacio','Pinares de Langa y arroyo de Regajal','Extensa planicie arenosa cuaternaria de la comarca de la Moraña cubierta por masas forestales homogéneas de pino piñonero. Su atractivo radica en el ecosistema forestal y su fauna asociada de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05110','espacio','Parque Regional de la Sierra de Gredos (vertiente sur), Garganta de la Eliz y riberas del río Tiétar','Impresionante rampa tectónica granítica que desciende con fuerza hacia el Valle del Tiétar bajo un microclima marcadamente mediterráneo. La garganta excava profundas pozas de aguas cristalinas rodeadas de densos enebrales y robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05113','espacio','Valle del río Tormes y garganta de Gredos (desembocadura)','Amplia llanura aluvial de montaña rodeada de imponentes moles graníticas del macizo central de Gredos. El río Tormes se ensancha aquí formando islas fluviales de cantos rodados, rodeadas de frondosos bosques de alisos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05114','espacio','Humedal de la Laguna de Madrigal y cuenca del río Trabancos','Gran llanura sedimentaria donde destaca una laguna de origen endorreico que actúa como ecosistema estacional crucial para la avifauna. El Trabancos labra un cauce arenoso somero en un entorno estepario mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05122','espacio','Lomas graníticas de Martínez y arroyo de la balsa','Relieve ondulado de la penillanura occidental con afloramientos rocosos menores y cubiertas de matorral xerófilo. Presenta pastizales secos mediterráneos de uso ganadero tradicional y valor puramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05123','espacio','Cañón del río Voltoya y embalse de Voltoya','Modesto pero abrupto desfiladero excavado por el río sobre materiales graníticos y gneises en el límite provincial. Las laderas están cubiertas de densos encinares y pinares resineros adaptados al relieve quebrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05125','espacio','Puerto de Mengamuñoz, Sierra de la Paramera y nacimiento del río Adaja','Paisaje de alta montaña granítica caracterizado por un relieve abrupto de canchales y bloques rocosos sometidos a meteorización. Las cumbres están tapizadas por inmensas extensiones de piornales y praderas alpinas altas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05126','espacio','Riberas del río Corneja y dehesa de Mesegar','Fondo de valle fértil constituido por sedimentos cuaternarios de la fosa del Corneja. El paraje destaca por sus fresnedas adehesadas y sotos de sauces que marcan de forma lineal el cauce fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05127','espacio','Parque Regional de la Sierra de Gredos, Puerto de Mijares y garganta de las Torres','Vertiginoso anfiteatro granítico de la vertiente sur del Sistema Central con desniveles colosales cubiertos de vegetación. Aloja frondosos bosques de pino resinero y castañares monumentales regados por torrenteras de alta montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05128','espacio','Berrocal de Mingorría y cañón del río Adaja','Extraordinario paisaje geomorfológico constituido por un inmenso berrocal granítico repleto de piedras caballeras y bolos gigantes. El río Adaja corre encajado en los márgenes formando rápidos entre las rocas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05129','espacio','Sierra de Ávila (extremo occidental) y alto del castillo (entorno natural)','Promontorio granítico elevado que domina de forma absoluta la transición hacia el valle del Corneja. El relieve es escarpado, desarbolado y dominado por peñascales azotados por el viento y matorrales de escobas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05132','espacio','Parque Regional de la Sierra de Gredos, Barranco de las Cinco Villas y garganta de la Ramacasta','Profunda depresión tectónica flanqueada por las cumbres graníticas de Gredos bajo una marcada influencia climática atlántico-mediterránea. Cuenta con frondosas masas boscosas de pinos, castaños y dehesas de encina bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05133','espacio','Lomas de Monsalupe y encinar menor','Suaves ondulaciones graníticas de la penillanura norteña que marcan la transición hacia los suelos arenosos de la Moraña. Alberga matorrales esclerófilos ralos y pequeños afloramientos rocosos locales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05134','espacio','Vaguada del arroyo de Matacabras','Paisaje horizontal agrícola de la submeseta norte sin formas de relieve escarpadas ni masas forestales. Presenta pequeñas escorrentías estacionales rodeadas de cultivos con un valor natural estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05135','espacio','Valle Amblés (sector occidental) y dehesa de Muñana','Fosa tectónica rellenada por sedimentos arenosos graníticos del cuaternario flanqueada por la Sierra de Ávila. Mantiene dehesas maduras de encina y fresnos que aprovechan las aguas subsuperficiales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05136','espacio','Riberas del río Almar y encinares de Muñico','Paisaje adehesado sobre suelos graníticos donde el río Almar discurre de forma somera formando depósitos de arenas limpias. La cubierta vegetal se compone de encinas dispersas y matorrales de solana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05138','espacio','Dehesa de Muñogalindo, berrocal del Amblés y arroyo de las Navas','Destaca por su notable modelado granítico superficial con abundantes bolos y piedras caballeras integrados en un bosque adehesado de encinas centenarias. El relieve marca de forma nítida el borde norte del Valle Amblés.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05139','espacio','Riberas del río Adaja (tramo central) y campos de cultivo','Llanura aluvial llana donde el río Adaja discurre de manera pausada abriendo meandros suaves sobre limos. Cuenta con una modesta banda de vegetación riparia de sauces de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05140','espacio','Arroyo del Peco y llanura cerealista','Espacio llanense absoluto de la comarca de la Moraña dedicado a la agricultura intensiva. Carece de relieve geográfico o cubiertas arbóreas originales, poseyendo un valor ecológico estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05141','espacio','Berrocal de Muñopepe y laderas de la Sierra de Ávila','Escarpada ladera granítica que limita el Valle Amblés, caracterizada por la presencia de colosales bloques rocosos y lanchares agrietados por la erosión. La vegetación se reduce a encinas encajadas entre los roquedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05142','espacio','Pinares de Muñosancho y vaguada del río Adaja','Suols de arenas eólicas cuaternarias que sustentan masas forestales compactas de pino piñonero explotadas tradicionalmente. El paisaje es plano y ofrece un valor como refugio de fauna comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05143','espacio','Sierra de Ávila (vertiente sur) and Peña del Sombrero (formación geológica)','Ladera granítica de fuerte pendiente con caprichosas formas de erosión lineal y meteorización que generan bolos rocosos singulares como la Peña del Sombrero. Aloja encinares de montaña y matorrales de escobas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05144','espacio','Lomas graníticas de Narrillos y arroyo del Álamo','Relieve alomado de la penillanura abulense occidental con suelos silíceos pobres cubiertos de pastos ganaderos. Cuenta con pequeños afloramientos de lanchas de piedra horizontales de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05145','espacio','Sierra de Ávila (sector oriental) y rebollares de Narrillos','Relieve de media montaña granítica que destaca por conservar rodales valiosos de rebollo o roble melojo (Quercus pyrenaica) adaptados a la altitud. El paisaje muestra berrocales escarpados y canchales menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05149','espacio','Arroyo de Saldueña y pinares menores','Llanura de sedimentación arenosa en la Moraña Alta con presencia de pequeños rodales aislados de pino resinero. El entorno está intensamente modificado por el ser humano con un valor natural local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05147','espacio','Riberas del río Zapardiel (curso alto)','Curso de agua marcadamente intermitente que fluye por la llanura cerealista del norte de la provincia. Mantiene pequeños carrizales y espadañales estacionales de interés exclusivamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05148','espacio','Sierra de la Paramera (vertiente norte) and río Aulaque','Escarpado relieve granítico que forma las estribaciones septentrionales de la sierra hacia el Valle Amblés. El río Aulaque desciende con fuerza entre bloques rocosos rodeado de piornales y pastizales altos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05151','espacio','Sierra de Villafranca, Puerto de Chía y cabecera del río Corneja','Impresionante paisaje de alta montaña caracterizado por un relieve de origen periglaciar con valles encajados de fuerte pendiente. Alberga extensas áreas de piornales, pastizales de montaña y cascadas estacionales de agua pura.   He finalizado este bloque de los municipios de la provincia de Ávila. Indícame cómo prefieres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05152','espacio','Lagunas estacionales de Magazos y pinares de Nava','Pequeñas depresiones endorreicas sobre cubetas arcillo-arenosas que retienen agua en invierno. El entorno está cubierto por extensiones de pino piñonero explotado sobre llanuras sedimentarias de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05153','espacio','Parque Regional de la Sierra de Gredos, Garganta de la Nava y Laguna de la Nava','Espectacular valle de modelado glaciar en forma de U jalonado por colosales morrenas y canchales de granito. En su cabecera se asienta una gran laguna alpina de origen glaciar rodeada de picos que superan los 2.200 metros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05154','espacio','Alta cuenca del río Alberche and Sierra de la Paramera','Paisaje de alta montaña caracterizado por una penillanura elevada y deforestada cubierta por extensas masas de piornos. El río Alberche fluye de forma sinuosa por praderas húmedas de pastizales de cervuno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05157','espacio','Sierra de la Paramera (vertiente sur) y garganta de Navalacruz','Abrupto relieve montañoso granítico con laderas de fuertes pendientes que vierten hacia el río Alberche. Presenta un relieve desarbolado dominado por grandes bloques rocosos, canchales y matorral subalpino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05158','espacio','Puerto de Navalmoral, Sierra de la Paramera y nacedero del río de la ría','Paso natural de montaña de litología granítica sometido a una intensa meteorización física y eólica. El paisaje destaca por sus formaciones de peñascales desnudos y extensas áreas de piornal de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05159','espacio','Parque Regional de la Sierra de Gredos, Garganta de los Caballeros y garganta de Bohoyo (límite)','Impresionante valle glaciar que alberga una de las gargantas más caudalosas y puras de Gredos. El curso fluvial labra el granito formando profundas pozas turquesas y saltos de agua espectaculares bajo circos glaciares alpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05163','espacio','Valle del río Alberche, Reserva Natural del Valle de Iruelas (límite) y garganta de la ría','Magnífico entorno fluvial donde el río Alberche se ensancha en un lecho granítico formando piscinas naturales de arena limpia. Las laderas montañosas norteñas de Gredos están cubiertas por densos bosques de robles melojos y pinadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05164','espacio','Vertiente sur de la Sierra de la Paramera y arroyo de Navacalera','Paisaje de media-alta montaña granítica caracterizado por su relieve áspero e indómito desprovisto de masas arbóreas altas. Cuenta con acumulaciones de bolos rocosos redondos y matorral escobón de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05165','espacio','Parque Regional de la Sierra de Gredos, Pinar de Navarredonda y nacimiento del río Tormes','Alberga uno de los bosques de pino silvestre (Pinus sylvestris) más antiguos y mejor conservados del Sistema Central. El río Tormes nace bajo las cumbres graníticas fluyendo por llanuras de turberas de alto valor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05167','espacio','Sierra de la Paramera (estribaciones occidentales) y garganta de Fernandina','Escarpado territorio de montaña granítica surcado por arroyos de cabecera de aguas cristalinas que salvan fuertes desniveles. El paisaje está dominado por formaciones de matorral alpino y canchales expuestos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05168','espacio','Pinar de las Navas, Sierra de Malagón y risco de la ría','Vasta extensión forestal constituida por densos pinares de pino resinero y pino albar que asientan sobre relieves de gneis y granito. El paisaje es quebrado, de montaña media, salpicado por riscos rocosos singulares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05169','espacio','Valle del río Alberche y garganta de Navatalgordo','Relieve alomado y quebrado granítico que desciende de forma abrupta hacia el cauce del Alberche. Cuenta con terrazas aluviales arenosas menores y laderas cubiertas de matorral mediterráneo de solana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05170','espacio','Ribera alta del río Tormes, garganta de la ría y laderas del monte','Entorno fluvial de montaña media donde el Tormes corre encajado entre escarpes graníticos y depósitos de grandes cantos. El paisaje forestal cuenta con rebollares bien conservados en las umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05171','espacio','Sierra de Béjar (vertiente oriental) y arroyo de Neila','Ladera montañosa granítica con pendientes pronunciadas orientadas al oeste que presenta una fisonomía alpina. Alberga pastizales de alta montaña y formaciones de canchales de piedra labrados por heladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05172','espacio','Riberas del río Adaja (Valle Amblés)','Llanura aluvial llana en el fondo de la fosa tectónica central de la provincia. Mantiene una banda modesta de vegetación riparia compuesta por sauces y chopos negros de rango puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05173','espacio','Sierra de Ojos-Albos y peña de la ría','Alineación montañosa de gneis y granito que constituye el extremo oriental de la Sierra de Ávila. Muestra un relieve alomado azotado por el viento con matorrales de brezales y peñascos erosionados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05174','espacio','Vaguada del río Voltoya (tramo bajo)','Terreno horizontal modificado por la actividad agrícola intensiva en la comarca de la Moraña Baja. El curso fluvial presenta un soto degradado de sauces y eneas de interés estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05175','espacio','Laguna de El Oso','Destacado humedal de origen endorreico sobre arenas y arcillas de la Moraña que constituye una reserva ornitológica crucial. Acoge importantes colonias estacionales de grullas, gansos y aves limícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05176','espacio','Sierra de Ávila (vertiente sur) y dehesa de Padiernos','Escarpada vertiente granítica que delimita el Valle Amblés por el norte, caracterizada por la presencia de berrocales y piedras caballeras. Aloja encinares mediterráneos y matorrales espinosos de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05177','espacio','Cañón del río Adaja en Pajares','Modesto desfiladero excavado por el río Adaja al cortar los materiales arcillo-arenosos de la meseta norte.   Las laderas muestran taludes escarpados con vegetación de ribera y pinares carrascos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05178','espacio','Arroyo de la ría y campos de la Moraña','Espacio plano de la cuenca sedimentaria del Duero dedicado enteramente al cultivo de secano. Las escorrentías intermitentes presentan carrizales menores de valor estrictamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05179','espacio','Llanuras arenosas de Papatrigo','Paisaje horizontal absoluto sin accidentes geográficos notables ni redes hidrográficas permanentes. Su valor natural es relicto y centrado en la avifauna esteparia menor de paso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05180','espacio','Lomas de El Parral y encinar menor','Suaves ondulaciones graníticas de la penillanura norteña cubiertas por retazos dispersos de encinar mediterráneo degradado a matorral. Su interés es de rango local y ganadero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05181','espacio','Dehesas de Pascualcobo y afloramientos graníticos','Terreno alomado de la penillanura occidental abulense que conserva un bosque adehesado de encinas sobre suelos silíceos. Presenta lanchares rocosos horizontales y pequeños bolos de granito.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05182','espacio','Parque Regional de la Sierra de Gredos (vertiente sur), risco de la ría y garganta de la ría','Impresionante rampa tectónica apodada "el balcón de Tiétar" debido a sus vertiginosos desniveles graníticos orientados al sur. Alberga inmensas masas de pino   resinero, alcornocales relictos y castañares regados por torrenteras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05183','espacio','Arroyo de Pedro-Rodríguez y campos de la Moraña','Territorio plano cuaternario sin formaciones rocosas ni masas forestales originales remarcables. Su fisonomía está dominada por el uso agrícola con escorrentías temporales de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05184','espacio','Pinar de Peguerinos, Sierra de Guadarrama (límite occidental) y embalse de la ría','Paisaje de alta montaña caracterizado por frondosos bosques de pino albar asentados sobre valles de gneis y granito. Cuenta con praderas húmedas alpinas, arroyos torrenciales y riscos escarpados de gran belleza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05185','espacio','Cerros de Peñalba y riberas del río Adaja','Relieve alomado con pequeños cerros testigo de materiales graníticos erosionados que flanquean la vega del Adaja. Aloja matorrales xerófilos y sotos de sauces de valor puramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05186','espacio','Sierra de Villafranca, monte de la ría y dehesas de Piedrahíta','Escarpada ladera montañosa granítica que corona el amplio valle del Corneja. Las vertientes presentan densos robledales de melojo, piornales subalpinos y espectaculares canchales de piedras labradas por el hielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05187','espacio','Parque Regional de la Sierra de Gredos, Garganta de Piedralaves y Charco de la ría','Vertiginoso relieve de montaña granítica enclavado en el Valle del Tiétar con profundos barrancos y   escarpes rocosos. La garganta excava colosales pozas naturales de aguas cristalinas rodeadas de densos pinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05188','espacio','Sierra de Ávila (sector alto) y nacimiento del río Amblés','Territorio de media-alta montaña granítica caracterizado por un relieve de lomas redondeadas y canchales menores. La cubierta vegetal se compone de piornales y pastizales rústicos de uso ganadero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05189','espacio','Parque Regional de la Sierra de Gredos (vertiente sur) y garganta de la ría','Ladera montañosa granítica con un marcado microclima mediterráneo templado que favorece una vegetación exuberante. El arroyo desciende encajado entre bloques rocosos formando saltos de agua y pozas turquesas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05190','espacio','Arroyo de Pozanco y lomas de cultivo','Paisaje cerealista de la transición a la Moraña sin accidentes geográficos significativos. El arroyo presenta un régimen torrencial intermitente con un valor ecológico estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05191','espacio','Vertiente norte de la Sierra de la Paramera y arroyo de la ría','Rampa granítica de fuertes pendientes que desciende hacia el Valle Amblés cubierta por masas de piornos y escobas. Cuenta con afloramientos rocosos fisurados y pequeñas fuentes de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05192','espacio','Parque Regional de la Sierra de Gredos, Puerto de Tornavacas and Laguna de la ría','Territorio alpino de gran fuerza geomorfológica situado en el límite provincial con el Valle del Jerte. Destaca por sus circos glaciares, lagunas altas de montaña y colosales canchales graníticos desprovistos de arbolado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05193','espacio','Valle del río Trabancos (tramo medio)','El río Trabancos labra una llanura aluvial somera entre terrazas arenosas cuaternarias de la submeseta norte. Mantiene pequeños sotos de sauces y álamos visibles en la distancia llanera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05194','espacio','Arroyo de Riocabado y pinares menores','Suave ondulación del terreno sobre suelos arenosos eólicos colonizados por pequeñas masas de pino resinero. Su interés biológico es de rango comarcal y vinculado a la fauna forestal menor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05195','espacio','Sierra de la Paramera (vertiente norte) y dehesa de Riofrío','Escarpado relieve granítico con abundantes pedrizas y bloques rocosos que vierten sus aguas hacia el Valle Amblés. Aloja encinares de montaña en las zonas bajas y piornales en las cumbres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05196','espacio','Riberas del río Zapardiel y campos cerealistas','Curso de agua de régimen irregular que surca de forma pausada la llanura norteña de la provincia. Mantiene modestas comunidades palustres de carrizos de interés estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05197','espacio','Riberas del río Adaja (Valle Amblés central)','Llanura sedimentaria llana constituida por limos y arenas de inundación fluvial. Conserva rodales dispersos de   fresnedas y sotos de sauces que aprovechan la humedad subsuperficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05198','espacio','Llanura de Salvadiós y escorrentías estacionales','Paisaje horizontal agrícola de la Moraña sin formas de relieve escarpadas ni masas forestales originales. Su valor es mínimo y restringido al ámbito estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05199','espacio','Sierra de Béjar (estribaciones abulenses) y dehesa del monte','Relieve de montaña silícea con fuertes pendientes cubiertas de densos bosques de roble melojo. Los arroyos corren limpios entre bloques graníticos y praderas rústicas de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05200','espacio','Riberas del río Corneja y dehesa de San Bartolomé','Fondo de valle fértil constituido por depósitos cuaternarios donde el río Corneja dibuja meandros suaves. Aloja fresnedas adehesadas y sotos riparios de interés ecológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05201','espacio','Sierra de San Bartolomé, pinares de la ría y cuenca del río Gaznata','Escarpado relieve de montaña granítica caracterizado por extensas masas forestales de pino resinero y piñonero. El paisaje presenta riscos rocosos apuntados y profundos valles de erosión fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05206','espacio','Lomas de los Patos y arroyo de la ría','Suaves ondulaciones graníticas de la penillanura que marcan la transición hacia el norte provincial. Alberga matorrales esclerófilos de baja cobertura y pastos secos mediterráneos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05208','espacio','Vaguada del río Zapardiel (límite norte)','Tramo plano de la cuenca del Zapardiel intensamente antropizado por cultivos agrícolas intensivos. Su interés geográfico natural es mínimo y restringido al ámbito local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05207','espacio','Parque Regional de la Sierra de Gredos, Barranco de las Cinco Villas y garganta de Estebandilla','Impresionante anfiteatro granítico de la vertiente sur de Gredos con desniveles colosales cubiertos de densa vegetación. Aloja frondosos bosques de pinos, castañares monumentales y olivares antiguos de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05209','espacio','Sierra de Ávila (extremo occidental) y dehesa de Ingelmos','Relieve alomado sobre suelos graníticos ásperos cubiertos por manchas dispersas de encinar mediterráneo. Presenta lanchares rocosos y pequeños bolos de granito de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05901','espacio','Parque Regional de la Sierra de Gredos, Garganta de Navamediana y río Tormes','Espectacular valle glaciar en forma de U flanqueado por imponentes crestas graníticas desnudas. La garganta desciende de forma torrencial formando pozas de roca pulida y cascadas de aguas heladas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05210','espacio','Arroyo de la Encinilla y llanuras cerealistas','Paisaje horizontal agrícola de la Moraña Alta sin accidentes orográficos notables. Presenta pequeñas escorrentías temporales rodeadas de cultivos con un valor natural estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05211','espacio','Sierra de la Paramera (vertiente sur) y lomas del Alberche','Escarpado relieve granítico con abundantes pedrizas y bloques rocosos que descienden hacia el valle del Alberche. Aloja encinares de montaña, pinares resineros y matorrales de escobas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05213','espacio','Sierra de Ávila (sector alto) y nacedero del río Almar','Territorio de alta montaña granítica caracterizado por un relieve de lomas redondeadas y piornales altos. El río Almar nace en sus cumbres fluyendo por praderas húmedas de gran valor ecológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05214','espacio','Ribera del río Tormes y dehesas graníticas de San Lorenzo','Magnífico tramo fluvial donde el río Tormes corre encajado entre bloques graníticos formando islas y llanuras aluviales de cantos. Las laderas albergan quejigares y robledales de melojo bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05215','espacio','Alta cuenca del río Alberche, Sierra de la Paramera y puerto de la ría','Impresionante valle elevado de montaña donde el río Alberche dibuja meandros sobre una llanura de turberas y pastizales húmedos. El entorno está flanqueado por peñascales graníticos y piornales subalpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05216','espacio','Parque Regional de la Sierra de Gredos, Garganta de Gredos (cabecera) y río Arenillas','Entorno alpino de gran fuerza visual con morrenas glaciares, valles en U y colosales canchales graníticos. Aloja frondosos bosques de pino silvestre y piornales altos que ascienden hacia las cumbres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05217','espacio','Riberas del río Corneja y lomas graníticas','Fondo de valle fértil constituido por sedimentos cuaternarios de la fosa del Corneja. El paraje destaca por sus fresnedas adehesadas y sotos de sauces de valor ecológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05218','espacio','Sierra de la Serrezuela y peñascos de San Miguel','Alineación montañosa caliza y metamórfica aislada que emerge con fuerza en la penillanura occidental. El relieve presenta escarpes rocosos desprovistos de árboles altos, dominados por piornos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05219','espacio','Llanura de San Pascual y campos cerealistas','Paisaje horizontal absoluto de la comarca de la Moraña sin accidentes geográficos significativos. Su único valor natural se centra en las colonias estacionales de aves esteparias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05220','espacio','Arroyo de San Pedro y pinares menores','Suave ondulación del terreno sobre suelos arenosos eólicos de la cuenca sedimentaria. Alberga pequeños rodales aislados de pino resinero de valor ambiental de nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05231','espacio','Pinares de San Vicente y llanura cerealista','Zonas llanas de arenas sueltas eólicas cuaternarias cubiertas por repoblaciones forestales homogéneas de pino piñonero de rango estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05204','espacio','Riberas del río Voltoya y dehesa de Sanchidrián','El río Voltoya aporta una pequeña línea verde de vegetación riparia bien conservada en un entorno de   transición. Las zonas llanas albergan dehesas mixtas de encina de uso ganadero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05205','espacio','Sierra de Ávila (sector central), Castro de la ría (entorno natural) y berrocales de Sanchorreja','Impresionante paisaje de modelado granítico o berrocal jalonado por piedras caballeras, torcas y bloques agrietados. Las laderas albergan piornales y encinas enanas encajadas entre las grietas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05222','espacio','Sierra de San Bartolomé, pinares de Santa Cruz y río Gaznata','Escarpado relieve de montaña granítica caracterizado por extensas masas forestales de pino resinero. El paisaje presenta riscos rocosos apuntados y profundos valles de erosión de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05221','espacio','Parque Regional de la Sierra de Gredos, Barranco de las Cinco Villas y garganta de la ría','Impresionante anfiteatro granítico de la vertiente sur de Gredos con desniveles colosales cubiertos de vegetación. Aloja frondosos bosques de pinos, castañares monumentales y dehesas bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05226','espacio','Valle del río Tormes, dehesas graníticas y riberas del Alberche (tramo alto)','Entorno de media montaña granítica donde el río discurre formando depósitos de cantos rodados y arenas limpias. El paisaje forestal destaca por quejigares y robledales bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05224','espacio','Riberas del río Adaja (Valle Amblés occidental) y lomas graníticas','Valle fluvial granítico con relieves alomados suaves cubiertos por manchas dispersas de encinar mediterráneo. Su interés es modesto, restringido al ámbito comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05225','espacio','Berrocal de Santa María, río Corneja and dehesas de la ría','Excepcional ejemplo de modelado granítico superficial o berrocal con abundantes piedras caballeras y bolos gigantescos. El río Corneja corre por su margen formando sotos riparios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05227','espacio','Valle del río Tiétar, pinar de Santa María y garganta de la ría','Relieve quebrado y abarrancado de naturaleza granítica moldeado por el río Tiétar. Las laderas albergan densos pinares de pino piñonero y carrascales adaptados a veranos térmicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05228','espacio','Sierra de Piedrahíta, puerto de la ría y cabecera del río Corneja','Escarpada ladera montañosa granítica con fuertes pendientes orientadas al valle del Corneja. Presenta formaciones de canchales rústicos y vegetación de piornal de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05904','espacio','Parque Regional de la Sierra de Gredos, Garganta de la ría y río Tormes','Impresionante valle de origen glaciar en forma de U encajonado entre colosales picos graníticos. La garganta desciende de forma torrencial con espectaculares cascadas y pozas de roca pulida.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05229','espacio','Arroyo de las Posadas y llanura cerealista','Paisaje agrícola de la transición a la Moraña sin accidentes geográficos significativos de valor estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05230','espacio','Riberas del río Zapardiel and pinares de Zabarcos','Curso de agua de régimen irregular que surca la llanura norteña de la provincia. Mantiene modestas comunidades palustres de carrizos de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05232','espacio','Lomas de La Serrada y valle del Adaja','Suaves ondulaciones graníticas de la penillanura que marcan la transición hacia el Valle Amblés de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05233','espacio','Puerto de Serranillos, Sierra de Gredos (sector oriental) y garganta de la ría','Espectacular e imponente paso de montaña granítico caracterizado por vertiginosas pendientes alpinas que culminan en crestas desnudas. Alberga piornales de alta montaña y canchales puros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05234','espacio','Arroyo de Sigeres y encinar residual','Suaves ondulaciones de la penillanura granítica con presencia de encinar degradado a matorral de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05235','espacio','Llanura cerealista de Sinlabajos','Espacio plano de la cuenca sedimentaria del Duero dedicado enteramente al cultivo de secano de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05236','espacio','Parque Regional de la Sierra de Gredos, Sierra de Béjar, Laguna del Trampal y río Aravalle','Extraordinario conjunto alpino de origen glaciar con lagunas altas de montaña encajadas entre circos graníticos colosales. Alberga frondosos bosques de roble melojo y cascadas de aguas heladas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05237','espacio','Riberas del río Almar y dehesa de Solana','Paisaje granítico caracterizado por suaves ondulaciones del terreno y dehesas mixtas de encina de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05238','espacio','Castro de Ulaca (entorno natural), Berrocal de Solosancho y río Adaja','Destaca por su notable modelado granítico superficial con colosales piedras caballeras y bloques agrietados integrados en la ladera de la Sierra de Ávila. El río Adaja aporta frescura a la vega baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05239','espacio','Sierra de la Paramera, Castillo de Aunon (entorno natural) y garganta de la ría','Escarpado relieve granítico de alta montaña caracterizado por un relieve de canchales y bloques rocosos. Las cumbres están tapizadas por inmensas extensiones de piornales de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05244','espacio','Valle del río Aravalle, Sierra de Gredos (extremo occidental) y garganta de la ría','Magnífico relieve de montaña silícea con laderas de fuerte pendiente cubiertas de robledales de melojo. El río Aravalle discurre limpio por un lecho de cantos rodados de gran valor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05245','espacio','Berrocal de Tornadizos y lomas del Adaja','Espectacular paisaje de modelado granítico o berrocal jalonado por piedras caballeras y bloques agrietados por la meteorización de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05247','espacio','Valle Amblés (sector central) y dehesa de La Torre','Fosa tectónica rellenada por sedimentos arenosos graníticos del cuaternario flanqueada por la Sierra de Ávila de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90085','espacio','Sierra de Ávila (sector occidental) and dehesa de Tórtoles','Relieve alomado sobre suelos graníticos ásperos cubiertos por manchas dispersas de encinar mediterráneo de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05249','espacio','Valle del río Aravalle, dehesas graníticas y riberas del Alberche (tramo alto)','Entorno de media montaña granítica donde el río discurre formando depósitos de cantos rodados y sotos de alisos de valor comarcal.   Vadillo de la Guija (San Juan del Olmo - ver arriba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05252','espacio','Sierra de Ávila (sector central) and berrocales de Valdecasa','Ladera granítica de fuerte pendiente con caprichosas formas de erosión lineal y meteorización que generan bolos rocosos de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05253','espacio','Arroyo de Santa María y llanura cerealista','Paisaje agrícola de la transición a la Moraña sin accidentes geográficos significativos de valor estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05254','espacio','Arroyo de Velayos y dehesa residual','Suaves ondulaciones de la penillanura granítica con presencia de encinar degradado a matorral de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05256','espacio','Sierra de Ávila (sector oriental) y dehesa de Villaflor','Vertiente escarpada granítica con canchales y acumulaciones de bolos rocosos redondos de gran fuerza geomorfológica. La vegetación dominante es el encinar mediterráneo degradado a matorral xerófilo de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05905','espacio','Valle del río Alberche, Garganta de los Hornos y laderas de la Sierra de la Paramera','Escarpado paisaje de media y alta montaña granítica en la vertiente sur de la Paramera. La garganta desciende de forma torrencial abriéndose paso entre colosales bloques de piedra y formando pozas de aguas frías rodeadas de robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05259','espacio','Arroyo de la Dehesa y llanura de la Moraña','Paisaje horizontal absoluto de la submeseta norte dedicado al cultivo intensivo de cereal. El arroyo presenta un carácter efímero e intermitente, con nulo interés visual exterior y rango estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05260','espacio','Sierra de Ávila (cumbres occidentales), nacimiento del río Garganta y berrocales de la sierra','Territorio de alta montaña granítica desarbolada, caracterizado por una penillanura elevada y sometida a intensa meteorización. Destacan sus inmensos berrocales con piedras caballeras y extensas superficies tapizadas de piornales altos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05261','espacio','Desembocadura del río Corneja en el río Tormes','Punto de confluencia fluvial donde el Corneja entrega sus aguas al cauce principal del Tormes sobre depósitos de cantos rodados cuaternarios. El entorno mantiene una banda de sauces y alisos de gran interés biológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05262','espacio','Parque Regional de la Sierra de Gredos, Barranco de las Cinco Villas, Garganta de los Caballeros y riscos del Torozo','Espectacular anfiteatro granítico de alta montaña dominado por las imponentes paredes verticales de El Torozo. El relieve presenta profundos barrancos, colosales canchales de ladera e imponentes saltos de agua cristalina rodeados de pinares y castañares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05263','espacio','Puerto de Villatoro, Sierra de Ávila (sector sur) y nacimiento del río Adaja','Paso montañoso granítico que sirve de divisoria de aguas entre las cuencas del Duero y del Tajo. Las laderas están cubiertas por densas formaciones de piornal y robledales de montaña baja de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05264','espacio','Arroyo de Viñegra y campos de la Moraña','Espacio plano absoluto integrado en la comarca de la Moraña sin accidentes orográficos ni redes hidrográficas estables. Posee un valor natural relicto centrado en las especies de avifauna esteparia de paso local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05265','espacio','Arroyo de Vita y encinares de la penillanura','Suaves ondulaciones graníticas de la penillanura norteña que marcan la transición hacia los suelos arenosos de la Moraña. Alberga matorrales esclerófilos ralos y pequeños afloramientos rocosos locales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05266','espacio','Rivera alta del río Zapardiel y lomas de la Sierra de Ávila','Valle de cabecera fluvial con surgencias de agua someras entre formaciones graníticas mesozoicas. El entorno cuenta con pequeños sotos de sauces y álamos flanqueados por pastizales rústicos de uso ganadero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05267','espacio','Parque Regional de la Sierra de Gredos (vertiente norte), río Tormes y garganta de la Navamediana','Entorno alpino de gran fuerza visual donde la garganta desciende de forma torrencial entre bloques colosales de roca formando pozas y cascadas vírgenes. Las laderas muestran densas masas de pino silvestre y piornales altos.   He.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90471','espacio','Riberas del río Gargáligas y llanuras del Guadiana','Espacio plano de sedimentación fluvial cuaternaria con presencia de pastizales mediterráneos de carácter seco. El cauce mantiene un cinturón verde modesto de sauces y tamujos con interés ecológico de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90472','espacio','Arroyo de Albuera y lomas arcillosas de Tierra de Barros','Paisaje suavemente ondulado sobre suelos arcillosos profundos muy modificados por la agricultura intensiva. Cuenta con pequeñas escorrentías intermitentes y sotos riparios degradados de interés puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90473','espacio','Campiña de Ahillones y arroyo de la ría','Relieve alomado de la penillanura meridional pacense cubierto por encinares muy dispersos y pastos de secano. Sirve como hábitat de paso comarcal para comunidades de avifauna esteparia menor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90474','espacio','Embalse de Alange, Sierra de Alange y peñón de las Juntas','Espectacular crestón cuarcítico de origen paleozoico que emerge de forma abrupta configurando farallones rocosos verticales de gran impacto visual. El paraje   alberga una colonia excepcional de vencejo real y rapaces rupícolas sobre la vasta lámina de agua artificial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90837','espacio','Complejo Lagunar de La Albuera (Lagunas Grande, Chica y del Carril)','Uno de los complejos de humedales endorreicos de carácter salino y estacional más valiosos del suroeste ibérico. Sus cubetas someras sobre arenas arcillosas acogen comunidades florísticas halófilas raras y una altísima densidad de aves acuáticas invernantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06001','espacio','Sierra de San Pedro, cañón del río Gévora y dehesas de Alburquerque','Excepcional paisaje integrado en una de las mejores reservas mundiales de bosque mediterráneo y dehesas densas de alcornoque y encina. El relieve presenta crestones cuarcíticos escarpados y profundos encajonamientos fluviales habitados por el águila imperial ibérica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06002','espacio','Sierra de la Miraflores y riberas del río Táliga','Relieve quebrado cubierto de denso matorral esclerófilo con madroños, jaras y acebuches salvajes. El río Táliga discurre limpio por un cauce somero salpicado de adelfares autóctonos bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90475','espacio','Sierra de Alconera y afloramientos calizos','Pequeña alineación montañosa paleozoica donde destacan antiguas formaciones kársticas con lapiaces menores y canteras de mármol integradas. Su cubierta vegetal dominante está compuesta por matorral mediterráneo de solana de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90476','espacio','Parque Natural de Cornalvo (sector occidental) y río Aljucén','Frondoso paisaje adehesado de encinas centenarias que flanquea el cauce del río Aljucén. El río mantiene tramos vírgenes con espectaculares tablas de agua estivales cubiertas de tamujos, sauces y una rica fauna anfibia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37028','espacio','Cañón del río Tormes / Presa de Almendra (Márgenes rocosos)','Impresionante tajo geológico excavado sobre rocas graníticas antes de la confluencia con el Duero. El relieve está caracterizado por gigantescos escarpes de piedra desnuda y lapiaces que se hunden de forma vertical hacia el lecho encajonado de las aguas mansas embalsadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06004','espacio','Arroyo de San Roque y llanuras de Tierra de Barros','Territorio plano de litología arcillosa dedicado casi por completo al monocultivo de vid y olivo. Carece de relieves geográficos escarpados o masas forestales autóctonas, poseyendo un valor natural estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90477','espacio','Sierra de Arroyo (pico de San Serván)','Imponente mole cuarcítica aislada que rompe la horizontalidad de las vegas del Guadiana con laderas escarpadas de gran inclinación. Alberga densos matorrales de solana ricos en acebuches, así como formaciones de canchales puros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37037','espacio','Sierra de Gata / Estribaciones del pico Espinazo / Arroyo de la Atalaya','Vertiente de pendientes moderadas constituida por pizarras que desciende hacia la cuenca del Águeda en el extremo sudoccidental. Las zonas altas albergan melojares jóvenes y brezales húmedos que tapizan un relieve quebrado por pequeñas escorrentías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06005','espacio','Campiña de Azuaga, dehesa del Coto y cuenca alta del río Bembézar','Extenso territorio de media montaña silícea integrado en las estribaciones de Sierra Morena con magníficas dehesas de encina. Los arroyos encajados forman valles someros que sirven de corredor ecológico para grandes rapaces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06006','espacio','Corredor fluvial del río Guadiana (ZEPA Azud de Badajoz) y riberas del río Gévora','Uno de los tramos fluviales urbanos y periurbanos más ricos ecológicamente de Europa Occidental, constituido por islas fluviales de sedimentos y densos sotos de sauces y eneas. Acoge colonias colosales de nidificación de garzas, águilas pescadoras y avifauna palustre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90838','espacio','Dehesas de Barcarrota y embalse de Ahigal','Extraordinario ecosistema de dehesa de encina y alcornoque que destaca por su frondosidad y excelente grado de conservación biológica. El paisaje alomado está surcado por pequeños regatos cristalinos que nutren la cuenca del Guadiana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90478','espacio','Sierra de Baterno y río Guadalemar','Relieve abrupto integrado en la comarca de La Siberia caracterizado por crestas cuarcíticas que albergan canchales de ladera extremos. El río discurre encajado entre densas masas de pino y matorral noble mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90479','espacio','Sierras de Benquerencia y puerto del Viñazo','Estructura de crestones paleozoicos alineados que cortan de forma vertical el paisaje horizontal de La Serena. Sus escarpes rocosos desnudados albergan   comunidades botánicas rupícolas singulares y nidos de buitre leonado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90480','espacio','Parque Natural de Las Quinientas (entorno natural) y dehesa de Berlanga','Paisaje adehesado suave con lagunas artificiales integradas ecológicamente que sirven de zona de nidificación acuática. Cuenta con rodales de pino piñonero mezclados con el encinar mediterráneo autóctono.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90481','espacio','Llanura de Bienvenida y arroyo de las Ventas','Terreno llano de pastizales y cultivos de secano con baja densidad arbórea original. Las pequeñas corrientes fluviales de carácter estacional albergan cañaverales y adelfas dispersas de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90482','espacio','Sierra de Tentudía (vertiente norte) y dehesa de Bodonal','Relieve de media montaña con frondosos bosques de encinas y alcornoques salpicados de castaños en las vaguadas más húmedas. El paisaje destaca por sus laderas de fuertes pendientes que enlazan con Sierra Morena.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90483','espacio','Berrocal de Burguillos y riberas del arroyo de la Vid','Destacable paisaje de modelado granítico superficial caracterizado por la acumulación de bolos rocosos redondos y piedras caballeras integradas en una dehesa mixta. El arroyo aporta una banda lineal verde muy regular de fresnos y sauces.   He finalizado este primer bloque de municipios de la provincia de Badajoz en estricto orden alfabético. Indícame cómo prefieres que.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06007','espacio','Sierra del Pedregoso, crestones cuarcíticos de Almorchón y dehesas de la Serena','Impresionante relieve apalachense con riscos y farallones verticales de cuarcita que emergen de forma abrupta sobre la penillanura. Las rocas desnudas albergan   importantes colonias de buitre leonado y cigüeña negra, flanqueadas por extensas dehesas mediterráneas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90484','espacio','Sierra de Tentudía (vertiente occidental) y valles del encinar húmedo','El municipio más alto de la provincia de Badajoz, caracterizado por un relieve quebrado de alta montaña mediterránea. Alberga frondosos bosques de castaños, robles melojos y densos alcornocales que se nutren de una elevada pluviometría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06025','espacio','Sierra de Arroyo (estribaciones occidentales) y arroyo Cabrera','Relieve de lomas cuarcíticas de pendiente moderada con una cubierta degradada de matorral esclerófilo y romerales. El cauce torrencial mantiene pequeñas pozas estacionales de interés meramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06026','espacio','Sierra de Tentudía, Pico de Tentudía y embalse de Tentudía','Culminación topográfica de la provincia de Badajoz con laderas abruptas cubiertas de pinares de repoblación, densos melojares y castañares. El embalse de montaña queda encajonado en un entorno de umbrías forestales de una belleza visual excepcional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06027','espacio','Rivera de Atarja y lomas de la penillanura','Suaves ondulaciones de la campiña baja pacense cubiertas por pastizales y dehesas muy aclaradas de encina. El curso de agua mantiene una modesta hilera de vegetación riparia de rango estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06028','espacio','Embalse de Orellana (margen sur), río Zújar y la siberia extremeña (límite)','Vasta lámina de agua integrada en la Red Natura 2000 que inunda las penillanuras de pizarra y granito. Sus orillas e islas someras albergan carrizales y espadañales con una enorme densidad de aves palustres y acuáticas migratorias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06029','espacio','Dehesa Boyal de Campillo y cuenca alta del río Guadiato','Paisaje homogéneo y bien conservado de dehesas de encina asentadas sobre suelos de pizarras paleozoicas. El río Guadiato forma en su cabecera un corredor ecológico de matorral noble mediterráneo de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06030','espacio','Peñón de Capilla, embalse de la Serena y garganta del Zújar','Imponente peñasco cuarcítico vertical que domina la confluencia fluvial de los ríos Zújar y Esteras, hoy inundados por el embalse. Ofrece espectaculares farallones rocosos donde nidifican rapaces rupícolas mayores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06031','espacio','Sierra de San Pedro (extremo oriental) y riberas del río Aljucén','Relieve alomado silíceo cubierto de densos jarales y formaciones de alcornoques de gran valor protector. El río Aljucén discurre limpio por el límite municipal manteniendo sotos riparios húmedos bien estructurados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06032','espacio','Dehesas de El Carrascalejo y arroyo del Pez','Paisaje llano prelitoral con suelos arenosos cuaternarios que sustentan manchas compactas de encinar ganadero. Funciona como zona de transición ecológica hacia el Parque Natural de Cornalvo a escala local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06033','espacio','Reserva Nacional de Caza de Cíjara (sector oeste) y embalse de Orellana','Privilegiado entorno natural de La Siberia cubierto por inmensas masas forestales de pino, encina y tupido monte bajo mediterráneo. El relieve presenta crestones cuarcíticos paralelos de gran fuerza estética que caen sobre las aguas del Guadiana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06034','espacio','Sierra de Casas de Reina y cerro del Castillo (entorno natural)','Alineación montañosa caliza y calcoesquistosa aislada que destaca de forma imponente sobre la campiña meridional. Sus laderas albergan matorrales nobles mediterráneos de acebuche, jara y romero adaptados a la solana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06035','espacio','Reserva de la Biosfera de La Siberia, embalse de García de Sola y estrecho de Peña el Águila','Espectacular desfiladero fluvial cuarcítico donde el río Guadiana corta las estructuras montañosas paleozoicas. El paisaje es quebrado, agreste y salvaje, combinando paredes rocosas de gran verticalidad con extensas masas forestales autóctonas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06036','espacio','Estepa de La Serena y sierras de Castuera (crestones)','Uno de los paisajes esteparios continentales más extensos de España, constituido por una llanura absoluta rota por alineaciones de dientes de cuarcita verticales. Aloja comunidades internacionales de aves esteparias como la avutarda y el sisón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06008','espacio','Gran Lago de Alqueva (río Guadiana) y dehesas costeras de Cheles','Vasto mar interior artificial originado por el embalsamiento del Guadiana en la frontera con Portugal. El paisaje destaca por el contraste de las lenguas de agua azul introducidas entre suaves colinas adehesadas de encinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06037','espacio','Corredor Ecológico y Biodiversidad del Río Gévora, y Sierra de la Lamparona','El río Gévora conforma aquí uno de los cursos fluviales mejor conservados y más limpios de la Península, flanqueado por alisedas y sotos hidrófilos espectaculares. La sierra aporta crestas cuarcíticas cubiertas de densas masas de alcornoque.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06038','espacio','Sierra de San Pedro (sector sur), embalse de Horno Tejajero y dehesas de Lácara','Magnífico entorno de dehesas densas y perennifolias de encina y alcornoque integradas en relieves alomados silíceos. Las masas de agua artificiales quedan perfectamente encajadas entre colinas boscosas de alto valor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06040','espacio','Arroyo de Peleas y campos agrícolas','Territorio plano de la cuenca sedimentaria del Guadiana intensamente transformado por cultivos de cereal de secano y olivar. El arroyo local es marcadamente intermitente con nulo relieve geográfico exterior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06041','espacio','Arroyo de la Guajira y lomas de la campiña','Paisaje agrícola horizontal sin accidentes geográficos notables. Cuenta con pequeñas escorrentías temporales bordeadas por matorral degradado e higueras dispersas de valor estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06043','espacio','Meandro del río Guadiana en Don Álvaro y Sierra de la Calderita','Espectacular curvatura encajada del curso del Guadiana flanqueada por una alineación montañosa cuarcítica con abrigos rocosos. El soto fluvial mantiene choperas y saucedas densas de gran plasticidad paisajística.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06009','espacio','Paraje Natural de la Sierra de Ortiga y riberas del río Ortigas','Alineación de cerros de granito desmantelado y pizarras que emergen con fuerza en las vegas altas del Guadiana. El río Ortigas discurre encajonado entre bolos pétreos albergando una valiosa población de tamujos y fauna anfibia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06045','espacio','Vaguada del río Entrín','Curso de agua modesto y de régimen torrencial intermitente asentado sobre la llanura arcillosa de Tierra de Barros. Su interés paisajístico es muy bajo y de rango netamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06046','espacio','Laguna de Esparragalejo y charca romana (entorno natural)','Humedal natural somero de carácter endorreico que acumula aguas pluviales sobre sustratos impermeables arcillosos. Funciona como ecosistema para la cría de anfibios y avifauna limícola a nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06047','espacio','Embalse de Zújar (cola) y dehesas de la Serena','Llanura pizarrosa ondulada que limita con las colas de la gran infraestructura hidráulica del Zújar. El paraje destaca por el contraste invernal entre los pastizales rasos de oveja merina y las extensas láminas de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06048','espacio','Reserva de la Biosfera de La Siberia, cerro de Masatrigo y embalse de la Serena','Alberga el Cerro de Masatrigo, una formación geológica excepcional considerada una de las "rotondas naturales" más perfectas del mundo, emergida de forma piramidal cónica sobre las aguas del embalse. El relieve quebrado circundante muestra impresionantes farallones de cuarcita.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06049','espacio','Sierra de Feria y pico del Mirrio','Imponente crestería calcárea y silícea que se eleva abruptamente sobre el suroeste provincial, actuando como magnífico mirador geomorfológico natural. Las laderas presentan pedrizas, canchales y dehesas de encina empinadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06010','espacio','Sierras de Fregenal, dehesas del giraldo y cuenca alta del río Ardila','Espectacular y denso ecosistema de dehesa húmeda serrana de encina y alcornoque asentado sobre relieves alomados silíceos de Sierra Morena. El río Ardila corre limpio flanqueado por densas choperas y fresnedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06051','espacio','Reserva de la Biosfera de La Siberia, Sierra de la Umbría y riberas del río Guadarranque','Territorio quebrado de alta densidad forestal caracterizado por sus inmensos jarales, pinares y dehesas de alcornoque. El río Guadarranque labra un profundo cañón rocoso con vegetación riparia virgen de gran valor ecológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06011','espacio','Campiña de Fuente de Cantos y arroyo de Bodión','Suaves colinas arcillo-limosas cubiertas de cultivos de secano y pastos desarbolados de la baja Extremadura. El arroyo Bodión mantiene una franja modesta de sauces y cañaverales de valor local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06053','espacio','Monumento Natural Mina La Jayona y Sierra de la Calera','Antigua explotación minera a cielo abierto integrada de forma excepcional por la naturaleza, creando un profundo cañón con microclima húmedo, helechos gigantescos y paredes de roca caliza colonizadas por avifauna rupícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06054','espacio','Arroyo de la Fuente y dehesas aclaradas de la nava','Terreno de Tierra de Barros modelado por la agricultura tradicional de olivar y vid sobre suelos arcillosos. Las pequeñas corrientes fluviales de carácter estacional tienen un interés exclusivamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06055','espacio','Monumento Natural Cuevas de Fuentes de León (Cueva del Agua, de los Postes, de los Caballos) y riberas del río Ardila','Excepcional complejo kárstico subterráneo desarrollado sobre calizas cambrianas, donde la Cueva del Agua alberga un gran lago interior con colonias de murciélagos. El relieve exterior presenta escarpados encajonamientos fluviales cubiertos de frondosa dehesa bética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06056','espacio','Reserva de la Biosfera de La Siberia, tabla del río Guadalemar y Sierra de los Villares','Impresionante relieve apalachense con crestones de cuarcita que flanquean el limpio cauce del río Guadalemar. El río forma profundas tablas de agua permanentes en verano rodeadas de grandes bloques pétreos y densos sotos de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06057','espacio','Reserva de la Biosfera de La Siberia, embalse de la Serena (sector este) y Sierra de la Dehesilla','Relieve quebrado y agreste caracterizado por el encuentro de las colinas forestales con las aguas encajadas del embalse. Cuenta con importantes cortados rocosos cuarcíticos donde anidan cigüeñas negras y grandes rapaces.   Gévora (Pedanía de Badajoz, ver Badajoz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06058','espacio','Riberas del río Aljucén (desembocadura) y lagunas menores de las vegas','Tramo final del río Aljucén antes de entregar sus aguas al Guadiana, formando una llanura aluvial de limos cuaternarios de interés biológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06059','espacio','Campiña de la Granja y arroyo de la huelga','Relieve predominantemente plano y desarbolado característico de la comarca de la Campiña Sur en el límite andaluz. Posee interés biológico por la presencia estacional de aves esteparias (avutardas).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06012','espacio','Riberas del río Guadámez y tablas del río Guadiana','Tramo fluvial de aguas tranquilas que divaga por la llanura formando meandros llanos y playones de gravas. Conserva una franja modesta de bosque de galería con chopos, sauces y mimbreras de valor ecológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06062','espacio','Reserva de la Biosfera de La Siberia, Reserva Nacional de Caza de Cíjara, embalse de Cíjara y Foces del río Estena','Uno de los enclaves naturales más salvajes y puros de la provincia, caracterizado por inmensos bosques de pinos, encinas y alcornocales vírgenes. El río Estena excava   profundas foces cuarcíticas de una espectacularidad geológica de rango internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06013','espacio','Reserva de la Biosfera de La Siberia, embalse de García de Sola, garganta de Puerto Consuelo y Sierra de Chamorro','Espectacular geografía de montaña media caracterizada por profundas hoces cuarcíticas de paredes rocosas verticales blanquecinas. El entorno forestal destaca por alcornocales puros y sotos riparios fluviales de aguas cristalinas muy bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06064','espacio','Río Guadámez y penillanura de La Serena (sector oeste)','Paisaje horizontal de pastizales naturales y dehesas muy aclaradas surcado por el río Guadámez. El cauce fluvial mantiene pozas profundas permanentes durante el estiaje veraniego de valor ecológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06065','espacio','Riberas del río Matachel y dehesa del alcornocal','Suaves colinas cubiertas de encinar y alcornocal que vierten sus escorrentías hacia la cuenca del río Matachel. El río conserva sotos de sauces y tamujares de interés biológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06066','espacio','Riberas del río Olivenza y dehesas de la frontera','Extensa llanura silícea adehesada con encinas centenarias y afloramientos de lanchas pétreas horizontales. El río Olivenza cruza el término formando un cauce somero de arenas y bolos graníticos redondeados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06067','espacio','Sierras de Higuera, dehesa del coto y cuenca alta del río Ardila','Espectacular paisaje de dehesas húmedas y cerradas de encina y alcornoque integradas en las estribaciones de Sierra Morena. Los valles fluviales presentan una gran frondosidad y excelente conservación de suelo vegetal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06068','espacio','Arroyo de la hinojosa y lomas arcillosas','Terreno suavemente ondulado de Tierra de Barros dedicado intensamente al viñedo y olivar de secano. Las corrientes efímeras albergan carrizales modestos de rango puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06069','espacio','Zona de Especial Protección para las Aves (ZEPA) Sierra de Hornachos','Impresionante e imponente macizo cuarcítico paleozoico que emerge de forma vertical como una isla montañosa en medio de la llanura de Tierra de Barros. Alberga una de las mayores densidades de rapaces rupícolas de España, rodeada de un monte mediterráneo umbrío virgen y cerrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','espacio','Cuenca del río Ardila, dehesas de Jerez (Valuengo, Brovales) y Sierra de la lapa','El mayor y más continuo ecosistema de dehesa de la península ibérica, constituyendo un bosque adehesado de encinas y alcornoques de proporciones gigantescas. El río Ardila corre encajado formando profundas tablas de agua bordeadas de sotos vírgenes de alisos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06071','espacio','Sierra de la lapa y arroyo de Alconchel','Relieve quebrado serrano integrado en el complejo montañoso del sur provincial. Las laderas presentan fuertes pendientes cubiertas de denso matorral esclerófilo con abundantes jarales de gran interés paisajístico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06073','espacio','Sierra de Llera y nacimiento del arroyo de la guijarra','Pequeña alineación cuarcítica con peñascales expuestos que cortan la llanura de la campiña. Aloja manchas dispersas de encinar mediterráneo de solana y comunidades de matorral árido de nivel local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06015','espacio','Campiña alta de Llerena y arroyo de los bueyes','Paisaje predominantemente llano y desarbolado característico de la campiña sur de Badajoz. Cuenta con pequeñas lomas arcillosas erosionadas y escorrentías estacionales de nulo relieve paisajístico exterior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06072','espacio','Escarpes del río Guadiana en Lobón','Impresionante corte geológico en forma de altos taludes arcillosos y areniscos que caen de forma abrupta sobre la vega del río Guadiana. Ofrece una fisonomía de erosión lineal muy plástica visible desde la llanura aluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06075','espacio','Crestón cuarcítico de Magacela y estepa de la Serena','Espectacular cerro testigo cuarcítico escarpado que emerge de forma totalmente vertical sobre el llano absoluto de La Serena. Sus paredes rocosas albergan nidos de rapaces menores y comunidades vegetales rupícolas raras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06076','espacio','Arroyo de la huelga y llanuras cerealistas','Territorio plano de carácter agrícola intensivo sin formaciones geológicas ni masas forestales originales. Las pequeñas escorrentías temporales presentan carrizales degradados de valor únicamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06077','espacio','Sierra Morena (sector pacense) y cuenca alta del río Sotillo','Relieve montañoso de media altitud caracterizado por profundos barrancos y colinas cubiertas de magníficas dehesas de encina. El río Sotillo corre limpio entre bloques graníticos de interés ecológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06078','espacio','Río Guadalefra (tramo bajo) y pastizales de la Serena','Paisaje horizontal absoluto compuesto por pastos naturales mediterráneos de secano. El río aporta charcas permanentes estivales de gran importancia biológica para la avifauna esteparia local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06079','espacio','Dehesa de Manchita y riberas del río Guadámez','Frondoso paisaje adehesado de encinas centenarias que flanquea el cauce del río Guadámez. Conserva rodales densos de monte mediterráneo marginal ricos en jaras y acebuches salvajes de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06080','espacio','Cerro de Medellín y corredor fluvial del río Guadiana','Impresionante cerro testigo de naturaleza granítica que emerge de forma aislada junto al ancho cauce del Guadiana. El río forma playas de gravas, meandros amplios e islas fluviales cubiertas de densos sotos riparios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06081','espacio','Riberas del río Bodión y dehesa de Medina','Suaves ondulaciones de la penillanura con suelos arcillo-silíceos que sustentan dehesas de encina de uso ganadero tradicional. El río Bodión mantiene un cinturón de sauces y chopos de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06082','espacio','Llanura aluvial del río Guadiana (límite sur)','Espacio plano de sedimentación limosa sin formas de relieve escarpadas, transformado por la agricultura de regadío. Mantiene pequeños regatos modificados de interés estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','espacio','Parque Natural de Cornalvo, embalse romano de Cornalvo y río Guadiana (islas de Mérida)','Destaca el Parque Natural de Cornalvo, un frondoso paisaje de dehesas de encina y alcornoque que rodea la presa romana histórica integrada en el ecosistema   láctico. El Guadiana forma amplias islas de sauces vírgenes en la ciudad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06084','espacio','Sierra de San Serván (sector norte) y dehesa de Mirandilla','Relieve alomado silíceo cubierto por magníficas dehesas de encina que enlazan con el entorno de Cornalvo. Es un hábitat óptimo para fauna mediterránea menor y aves rapaces de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06016','espacio','Sierra de Tentudía, dehesa del coto, puerto de las Marismas y nacedero del río Rivera de Huelva','Extraordinario entorno de montaña integrado en el eje de Sierra Morena con colosales dehesas de encina y alcornoque de alta densidad forestal. Los valles de montaña presentan barrancos profundos llenos de madroñales relictos de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06086','espacio','Cuenca del río Viar, Sierra de la Grana y dehesas de Montemolín','Territorio serrano de relieve quebrado donde el río Viar discurre encajado labrando pequeños cañones rocosos entre dehesas maduras. Las crestas aportan peñascales expuestos habitados por rapaces de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06087','espacio','Sierra de las Moreras y cuenca alta del río Zújar','Relieve alomado de pizarras y cuarcitas cubierto por olivares antiguos y manchas dispersas de monte mediterráneo de jaras. Las vaguadas albergan regatos estacionales de valor ecológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06017','espacio','Vegas Bajas del río Guadiana y charca de las encinas','Extensa llanura aluvial cuaternaria muy antropizada por el regadío intensivo. Conserva de forma relicta pequeñas zonas húmedas artificiales y sotos riparios aislados de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06089','espacio','Sierra de la loma y dehesa de la morera','Relieve suavemente ondulado con suelos silíceos pobres cubiertos de pastos ganaderos y rodales dispersos de encina. Su interés es modesto, restringido al ámbito netamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06090','espacio','Dehesas de la nava y arroyo de la Albuera (límite norte)','Suaves elevaciones de origen granítico y silíceo cubiertas de encinares aclarados de uso ganadero tradicional. Presenta pequeños afloramientos de bolos graníticos en un relieve alomado menor de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06091','espacio','Parque Natural de Orellana y Sierra de Pela (margen norte)','Impresionante cordillera cuarcítica de relieve apalachense cuyas vertientes norteñas caen de forma abrupta sobre el humedal protegido del embalse. Alberga densos bosques de galería mediterráneos y colonias internacionales de avifauna acuática.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06092','espacio','Sierra de Nogales y dehesa de la lapa','Pequeño macizo calizo y cuarcítico de laderas empinadas y peñascales desnudados por la erosión pluvial. Aloja encinares de montaña y matorrales espinosos de interés ecológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06093','espacio','Dehesa Internacional del río Ardila y riberas del arroyo Zaos','Magnífico espacio fronterizo constituido por una dehesa de encina y alcornoque de excelente grado de conservación ambiental. El río Ardila labra un cauce somero rodeado de adelfares vírgenes y sotos riparios hiperhúmedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06094','espacio','Sierra de la Garza y Hoz del río Aljucén (tramo bajo)','Relieve de crestones cuarcíticos desgastados rodeado de extensas dehesas mediterráneas. Las laderas escarpadas albergan comunidades de acebuches salvajes, jarales densos y escarpes rocosos menores donde anidan rapaces.   Olleros (Municipio integrado en la actualidad, no listado de forma independiente en el nomenclátor nacional actual).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','espacio','Gran Lago de Alqueva (río Guadiana), dehesas de Olivenza y Sierra de Alor','Destaca la Sierra de Alor, un islote calizo de rango internacional por su flora, albergando una variedad excepcional de orquídeas silvestres y la rosa de Alejandría relictual. Se complementa con las colosales dehesas fronterizas integradas en el lago de Alqueva.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06096','espacio','Sierra de Orellana (ZEPA) y cola del Embalse de Orellana','Relieve abrupto de rocas cuarcíticas que domina el paisaje hídrico del embalse. Sus escarpes rocosos y matorrales nobles sirven de zona de nidificación y refugio a importantes poblaciones de aves rupícolas y acuáticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06097','espacio','Embalse de Orellana (Humedal Ramsar de rango internacional)','Inmensa lámina de agua artificial rodeada de dehesas y dehesas alomadas mediterráneas. Destaca exclusivamente en este inventario por sus orillas rocosas, islas e intermareales interiores que acogen densas colonias de aves acuáticas invernantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06098','espacio','Arroyo de Palomas y llanuras agrícolas','Paisaje horizontal de arcillas dedicado al cultivo intensivo de cereal sin relieves geográficos escarpados de interés ecológico local.   Paradas (Las) (Badajoz - ver La Parra más abajo).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06099','espacio','Sierra de la Parra y dehesa del rincón','Relieve de media montaña paleozoica con vertientes calizas y cuarcíticas de pendiente moderada cubiertas de dehesas mixtas bien conservadas. Presenta pequeños canchales y oquedades naturales de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06100','espacio','Sierra de Capilla (sector oeste), río Zújar y embalse de la Serena','Entorno quebrado caracterizado por crestones cuarcíticos de gran verticalidad que caen sobre las aguas encajadas del embalse. Aloja comunidades botánicas rupícolas singulares y nidos de grandes rapaces ibéricas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06101','espacio','Cuenca alta del río Zújar y lomas mediterráneas','Territorio de penillanura con suaves ondulaciones cubiertas de pastizales y encinas muy dispersas. El río Zújar mantiene en este tramo inicial un cauce somero de arenas de interés netamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06102','espacio','Reserva de la Biosfera de La Siberia, Sierra de lares y embalse de la Serena','Colosal pliegue geológico cuarcítico de relieve apalachense con impresionantes cortados verticales que dominan la inmensa lámina de agua azul del embalse. Las paredes rocosas albergan una densidad sobresaliente de buitre leonado y cigüeña negra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06103','espacio','Vegas del río Guadiana (tramo central)','Llanura aluvial cuaternaria intensamente modificada por los regadíos agrícolas de la vega baja. Carece de relieves abruptos originales, manteniendo un interés ecológico restringido a la dinámica del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06104','espacio','Sierra de la Reina y arroyo de San Juan','Pequeña alineación montañosa paleozoica cubierta por matorral mediterráneo denso (jaras, lentiscos y romeros). Presenta pequeños afloramientos rocosos y dehesas ganaderas de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06107','espacio','Sierra de San Pedro (Puerto de Obando)','Paisaje forestal mediterráneo de alta densidad botánica, dominado por espesos bosques de alcornoques y quejigos en las umbrías húmedas. El relieve es quebrado y ofrece refugio a grandes mamíferos e importantes rapaces ibéricas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06108','espacio','Sierra de los Santos (estribaciones) y arroyo de la vega','Lomas de material calizo y cuarcítico desmantelado que marcan la transición hacia la campiña sur. Su cobertura vegetal es escasa y se limita a matorral mediterráneo de degradación comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06902','espacio','Riberas de inundación del río Guadiana (vegas bajas)','Llanura aluvial llana donde el río discurre encajado por defensas hidráulicas en un entorno intensamente modificado de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06109','espacio','Berrocal de Quintana y llanura estepa de La Serena','Interesante afloramiento granítico superficial o berrocal que rompe la monotonía esquistosa de la comarca. Presenta bolos rocosos redondeados dispersos entre pastizales secos de valor biológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06039','espacio','Riberas del río Zújar (tramo medio) y dehesa de la coronada','Llanura de inundación fluvial con depósitos de cantos y arenas que sustentan pequeños sotos de tamujos. El paisaje penillanurense es llano con uso ganadero comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06061','espacio','Berrocal de La Haba y río Ortiga','Destacable paisaje de alteración granítica o berrocal que exhibe bolos gigantescos y piedras caballeras distribuidas sobre pastizales silíceos. El río Ortiga corta el granito formando rápidos menores de valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06110','espacio','Sierra de la Alcazaba y estribaciones de Sierra Morena','Promontorio calizo y cuarcítico escarpado que se eleva de forma abrupta sobre las campiñas meridionales. Ofrece laderas de fuerte pendiente con vegetación rupícola y matorral noble mediterráneo.   Riansares (No listado como municipio independiente en la actualidad).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06113','espacio','Arroyo Valdemedel y lomas de Tierra de Barros','Valle aluvial somero con cultivos intensivos donde el arroyo mantiene un régimen marcadamente estacional. Conserva pequeños sotos de sauces y eneas de rango estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06114','espacio','Desfiladero del río Zújar y Sierra de Risco','Territorio quebrado de la comarca de La Serena caracterizado por crestones de cuarcita y profundos barrancos labrados por la escorrentía pluvial. Alberga comunidades de rapaces y densos jarales de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06115','espacio','Dehesas de la Roca y riberas del río Aljucén','Paisaje adehesado suave sobre suelos silíceos con encinas centenarias bien conservadas. El río Aljucén aporta un corredor verde estival con charcas permanentes de interés ecológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06116','espacio','Dehesa del Monte Porrino y Sierra de Monsalud','Uno de los ecosistemas de dehesa mixta de encina y alcornoque más bellos e intactos de la provincia, asentado sobre relieve alomado. Los valles albergan pequeños arroyos con vegetación de ribera bien conservada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06117','espacio','Sierra de Salvatierra y nacimiento del río Albuera','Macizo montañoso paleozoico caracterizado por laderas abruptas y umbrías frondosas repletas de alcornocales, quejigos y madroñales nobles. El paisaje presenta formaciones de canchales de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06119','espacio','Dehesas de San Pedro y riberas del Guadiana (límite)','Terreno llano de sedimentación cuaternaria con encinares de uso ganadero. Ofrece una fisonomía de paisaje rústico expuesto con pequeños sotos riparios de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06123','espacio','Sierra de San Pedro (sector noroccidental), dehesa del Alcornoque y río Mayor','Vasto espacio forestal integrado en el entorno protegido de San Pedro, dominado por el cultivo tradicional del corcho en alcornocales puros. El río Mayor labra cañones menores de gran belleza botánica ripícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06118','espacio','Embalse de La Serena (zona de colas) y Sierra de la Consolación','Espacio donde el relieve de pizarras y cuarcitas de La Serena se hunde bajo las aguas del embalse, creando entrantes y bahías interiores. Las laderas están cubiertas de matorral esclerófilo bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06120','espacio','Llanura aluvial del río Búrdalo','Terreno plano cuaternario sin accidentes geográficos notables, intensamente explotado por el regadío. El río Búrdalo aporta una modesta franja de vegetación riparia de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90839','espacio','Dehesa de Santa Marta y arroyo Limonetes','Suaves ondulaciones de la penillanura con encinares muy aclarados y pastos secos mediterráneos. Su valor natural es de rango comarcal como refugio de avifauna menor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06122','espacio','Sierra de San Jorge y valle de los Santos','Pequeño relieve calcáreo y cuarcítico que rompe la horizontalidad de la comarca, mostrando lapiaces menores y vegetación de solana. El entorno cuenta con encinas dispersas entre pastizales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06124','espacio','Sierra de Segura y dehesas de la Cuenca del Ardila','Paisaje serrano integrado en las estribaciones occidentales de Sierra Morena, caracterizado por profundos   barrancos y umbrías de alcornocal maduro. Cuenta con manantiales y regatos de aguas limpias de gran valor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06125','espacio','Dehesa de Siruela (Reserva de la Biosfera de La Siberia) y río Siruela','Impresionante paisaje adehesado continuo de encinas integrado en la reserva biológica planetaria. El relieve presenta crestones cuarcíticos y valles sinclinales donde campean grandes rapaces ibéricas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06126','espacio','Riberas del río Guadajira','Tramo fluvial de régimen mediterráneo encajado en los suelos arcillosos profundos de Tierra de Barros. Mantiene sotos de sauces y carrizales muy antropizados de interés estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06127','espacio','Reserva de la Biosfera de La Siberia, Puerto de los Carasoles y Embalse de Puerto Peña (orillas)','Paisaje espectacular dominado por colosales farallones rocosos de cuarcita que caen sobre las aguas del embalse. Es un santuario internacional para la observación de aves rupícolas como la cigüeña negra y el buitre leonado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06128','espacio','Riberas del río Guadiana y arroyo Limonetes (desembocadura)','Amplio cauce fluvial de aguas tranquilas con depósitos de islas arenosas y gravas cuaternarias. Conserva una banda modesta de bosque de galería con sauces y chopos negros de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06020','espacio','Dehesas de Táliga y cauce del río Táliga','Paisaje adehesado típicamente rayano sobre colinas suaves de pizarras, dominado por encinares densos   de uso ganadero. El río aporta una línea verde rica en adelfas salvajes de gran belleza primaveral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06130','espacio','Sierra de la Dehesilla y río Agudo (límite)','Relieve alomado de La Siberia con crestones cuarcíticos menores y valles pizarrosos cubiertos de jarales y pinares de repoblación. Ofrece una fisonomía de paisaje rústico bien conservado a nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06132','espacio','Vegas del Guadiana y arroyo de la Vega','Territorio completamente plano integrado en la vega aluvial del Guadiana, sin relieves naturales notables. El interés geográfico es mínimo debido a la intensa ocupación agrícola tradicional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06133','espacio','Lomas de Tierra de Barros (perímetro)','Paisaje horizontal absoluto de arcillas rojas dedicado al cultivo intensivo de viñedos. Carece de masas forestales o cursos de agua estables, poseyendo un valor ecológico estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06134','espacio','Sierra de Trasierra (estribaciones de Sierra Morena)','Relieve serrano de altitud moderada cubierto de encinar mediterráneo, matorral esclerófilo denso y jarales. Presenta pequeños canchales y escarpes rocosos donde habitan rapaces menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06135','espacio','Parque Natural de Cornalvo (Embalse romano de Cornalvo y dehesas)','Destaca el entorno natural del embalse histórico, rodeado de magníficas dehesas de encina y alcornoque integradas en el espacio protegido. El relieve es suave y sirve de hábitat a una rica fauna mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06137','espacio','Reserva de la Biosfera de La Siberia, Sierra de las Barbas de Oro y río Guadalupejo','Impresionante relieve montañoso de cuarcitas cubierto por espesos bosques mediterráneos y dehesas. El río Guadalupejo corre limpio y encajonado en formaciones rocosas de gran valor ecológico e impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06901','espacio','Corredor ecológico del río Guadiana (zonas marginales)','Llanura de inundación fluvial cuaternaria intensamente transformada por el Plan Badajoz para regadío intensivo. Mantiene pequeñas zonas de carrizal y sotos degradados de interés puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06138','espacio','Riberas del río Guadámez','Curso fluvial mediterráneo que divaga por la llanura formando meandros llanos y depósitos de arenas. Conserva una franja modesta de vegetación riparia con tamujos y adelfas dispersas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06139','espacio','Campiña de Valencia y riberas del río Matachel','Suaves colinas arcillo-limosas cubiertas de pastizales secos y encinas dispersas. El río Matachel aporta un corredor biológico lineal con sotos de sauces de interés netamente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06140','espacio','Riberas del río Ardila (límite rayano) y dehesas de Valencia','Territorio adehesado fronterizo con un relieve quebrado caracterizado por el encajamiento del río Ardila. Las laderas presentan densos matorrales de jara y encinares de gran tranquilidad ecológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06141','espacio','Valle del río Ardila alto y dehesas de Valencia del Ventoso','Paisaje de media montaña silícea con dehesas maduras de encina explotadas para el porcino ibérico. El río Ardila corre entre bloques rocosos formando pequeñas pozas estacionales de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06146','espacio','Valle del río Guadámez y sierras marginales de La Serena','Relieve alomado de pizarras surcado por el río Guadámez, que forma un valle somero encajonado entre cerros desnudos. La vegetación está dominada por pastizales secos y jarales menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06147','espacio','Sierra de San Giraldo y dehesas de montaña del Valle','Pintoresco relieve quebrado y escarpado integrado en las estribaciones montañosas del sur provincial. Cuenta con frondosos bosques de alcornoque, encina y huertas tradicionales regadas por manantiales de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06148','espacio','Sierra de Santa Ana y dehesas adehesadas de montaña','Territorio de relieve montañoso de altitud media cubierto por masas forestales de encinas y alcornoques bien conservados. Presenta oquedades naturales menores y pequeños barrancos de erosión pluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06142','espacio','Arroyo de Bodión y dehesas de Valverde','Suaves ondulaciones de la penillanura con encinares de uso ganadero y pastizales mediterráneos. El arroyo mantiene una estrecha línea verde de fresnos y sauces de interés biológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06143','espacio','Embalse de Piedra Aguda y dehesas de Valverde','Masa de agua artificial perfectamente integrada en un entorno de dehesas llanas de encina. Actúa como punto de concentración y alimentación de avifauna acuática y grullas durante el invierno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06144','espacio','Campiña de Valverde y arroyo de las Navas','Paisaje predominantemente llano y desarbolado característico de las campiñas del sur. Cuenta con pequeñas lomas erosionadas y escorrentías estacionales de nulo relieve paisajístico exterior.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06145','espacio','Meandro del río Guadiana en Valverde y Sierra de la Segura','Curvatura pronunciada del cauce fluvial que genera terrazas aluviales suaves flanqueadas por crestones cuaríticos menores. El entorno mantiene sotos de sauces y carrizales densos de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06149','espacio','Llanuras cerealistas y viñedos de Tierra de Barros','Espacio plano absoluto de arcillas rojas dedicado de forma monótona a la agricultura intensiva. Carece de relieves geográficos notables o cubiertas arbóreas originales, poseyendo un valor ecológico estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06150','espacio','Campiña de Villagarcía y arroyo del Retamar','Terreno llano de pastizales y cultivos de secano con baja densidad arbórea original. Las pequeñas escorrentías albergan cañaverales y matorral degradado de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06151','espacio','Sotos del río Guadiana y embalse de Villagonzalo','Tramo fluvial llano donde el río se ensancha debido a la retención hidráulica, formando islas de sedimentos y densos sotos riparios. Alberga comunidades de aves palustres de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06152','espacio','Embalse de Villalba (río Guadajira) y lomas arcillosas','Masa de agua artificial encajada entre suaves lomas dedicadas al cultivo de secano y olivar. Funciona como punto de agua local para la fauna en una comarca de acusada aridez estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06022','espacio','Confluencia de los ríos Guadiana y Zújar','Gran nudo hidrológico fluvial constituido por amplias llanuras aluvial de gravas y limos cuaternarios. Mantiene zonas de vegetación riparia bien conservadas con sauces, chopos negros y carrizales de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06154','espacio','Dehesas de Villanueva y riberas del río Alcarrache (ZEPA)','Extraordinario ecosistema de dehesa que destaca por albergar el corredor del río Alcarrache, un espacio virgen con densas masas de tamujos, adelfas y encinares donde invernan miles de grullas euroasiáticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06156','espacio','Riberas del río Ruecas','Curso de agua de régimen mediterráneo que divaga por la llanura aluvial cuaternaria. Presenta una modesta banda de vegetación riparia rodeada de cultivos agrícolas intensivos de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06155','espacio','Embalse de Peña del Águila y dehesas del río Zapatón','Relieve quebrado y abarrancado de naturaleza granítica y pizarrosa moldeado por el río Zapatón. Las laderas albergan densos pinares de repoblación y encinares adaptados al relieve quebrado de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','espacio','Sierra de Castellar y dehesas de Zafra','Pequeño relieve cuarcítico que destaca de forma aislada sobre la penillanura circundante. Presenta laderas cubiertas de matorral esclerófilo bajo y encinas dispersas de interés paisajístico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06024','espacio','Sierras de Zahínos y riberas del río Godolid','Relieve serrano integrado en la comarca de la Sierra Suroeste, caracterizado por profundos barrancos cubiertos de dehesas densas de alcornoque y encina. El río aporta un corredor biológico limpio y bien conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06160','espacio','Charca de Zalamea y estepas calcáreas de La Serena','Humedal de origen seminatural que destaca por estar integrado en las inmensas llanuras desarboladas de la comarca de la Serena. Es un enclave crucial para la concentración invernal de aves esteparias y acuáticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06162','espacio','Sierra de Peñas Blancas','Imponente crestón cuarcítico paleozoico que emerge de forma abrupta configurando farallones rocosos verticales de gran impacto visual. El paraje alberga abrigos rocosos naturales y comunidades de rapaces rupícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06161','espacio','Sierra de la Zarza y llanuras del río Zújar (perímetro)','Relieve quebrado caracterizado por crestas de cuarcitas que albergan canchales de ladera extremos. Ofrece   una fisonomía de fuerte contraste tectónico con el fondo del valle de La Serena. He.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','espacio','Riberas del río Llobregat y torrentes de Montserrat (estribaciones)','Tramo de valle fluvial rodeado por terrazas cuaternarias de arcillas y gravas. Mantiene pequeñas zonas de vegetación riparia de sauces y carrizos que actúan como corredor ecológico local bajo el perfil de la montaña de Montserrat.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90875','espacio','Riera de Segarra y altiplanicies calizas','Relieve alomado característico de la Cataluña central, dominado por plataformas calcáreas sometidas a erosión lineal. Alberga densos pinares de pino carrasco y encinares de montaña con interés paisajístico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90876','espacio','Parque Natural del Montseny (vertiente occidental) y riera de Martinet','Escarpado relieve prepirenaico que combina crestas calcáreas con profundos valles de montaña tapizados de encinares y robledales. La riera de Martinet corre limpia entre bloques pétreos, formando pozas de aguas frías y sotos riparios umbríos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08007','espacio','Cap de la Mitja Galta, acantilados de Les Torretes y encinares litorales','Tramo de costa rocosa de baja altitud donde las últimas estribaciones orientales del macizo del Montnegre entran en contacto directo con el mar. Ofrece pequeños cortados de granito agrietado y manchas reliquia de encinar costero adaptado a la salinidad marina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44020','espacio','Riera de Merlès (curso alto) y bosques del Lluçanès','Meseta elevada de naturaleza margosa y arenisca con un relieve quebrado y húmedo de media montaña. Cuenta con densos pinares de pino albar y robledales relictos, surcados por arroyos de aguas transparentes de gran valor biológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90877','espacio','Cingles de Bertí (estribaciones) y torrente del Suro','Zona de transición entre la llanura del Vallès y los imponentes riscos calizos prelitorales. Presenta pendientes moderadas cubiertas de pino carrasco y encinares termófilos con pequeños afloramientos rocosos menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08001','espacio','Riera de Arenys (desembocadura) y acantilados de la costa prelitoral','Tramo costero dominado por la desembocadura de una gran riera torrencial de arenas graníticas, flanqueada por pequeños promontorios rocosos. Posee interés morfológico litoral debido a la dinámica de transporte de sedimentos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90558','espacio','Parque del Montnegre i el Corredor (sector occidental)','Macizo montañoso prelitoral granítico cubierto por frondosas masas forestales de pino piñonero, encinares y castañares en las umbrías. El relieve es alomado y quebrado, surcado por profundos barrancos de sauló.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90559','espacio','Riera de Clariana y altiplanos de la Anoia','Relieve tabular calizo y arcilloso con valles encajados labrados por la erosión pluvial. La vegetación dominante está constituida por pinares mixtos y encinares de carácter continental seco de rango comarcal.   Arsèguel (Pertenece a Lleida, omitido.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90879','espacio','Valle de la riera de Gavarresa y cerros arcillosos de Artés','Depresión geológica del Bages caracterizada por terrazas aluviales y colinas de margas rojizas sometidas a erosión. Mantiene sotos de sauces y matorrales mediterráneos xerófilos de interés biológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90561','espacio','Prepirineo berguedano y estanys de Graugés','Espacio donde el relieve llano del prepirineo central alberga cubetas lacustres seminaturales de gran importancia biológica. El entorno forestal cuenta con robledales de hoja pequeña y pinares que enlazan con las sierras interiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90562','espacio','Riera de Relat y encinares de Avinyó','Relieve alomado y quebrado del Bages oriental surcado por el curso fluvial somero de la riera. Las laderas calizas presentan densos pinares de pino carrasco y manchas bien conservadas de bosque de galería atlánticomediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90563','espacio','Parque Natural del Garraf (sector norte) y lomas del Penedès','Paisaje kárstico inicial con colinas calizas expuestas que exhiben lapiaces superficiales y una rala vegetación de maquia mediterránea y palmitos. Contrasta fuertemente con las llanuras sedimentarias de la comarca vinícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90024','espacio','Parque de la Serralada de Marina (sector sur) y turo de l''Home (Badalona)','Vertiente costera granítica con pendientes pronunciadas cubiertas por masas forestales de pino carrasco   y encinares degradados. El relieve ofrece una importante sección geomorfológica prelitoral expuesta al viento marino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08904','espacio','Curso del río Sec (perímetro marginal)','Término municipal eminentemente urbano e industrializado asentado sobre la llanura cuaternaria del Vallès. Presenta un espacio natural relicto y antropizado en los márgenes fluviales con valor estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08002','espacio','Parque Natural del Cadí-Moixeró, Fuentes del Llobregat (proximidades) y Valle de Bastareny','Espectacular territorio alpino de alta montaña caliza con paredes verticales que superan los 500 metros de altura en los cingles del Cadí. Alberga impresionantes circos glaciares, fuentes kársticas colosales (Adou del Bastareny) y frondosos bosques de pino negro y hayas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90564','espacio','Cingles de Bertí (vertiente norte) y llanura de Vic (sector sur)','Escarpe calcáreo que delimita de forma abrupta la Plana de Vic, caracterizado por una fisonomía de riscales verticales. La vegetación se compone de robledales y pinares de pino laricio adaptados a la humedad de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90565','espacio','Río Llobregat (tramo medio) y esclusa de la Séquia','Valle fluvial encajado suavemente entre cerros margosos y calizos del Bages. El cauce mantiene una línea regular de sotos de ribera compuestos por chopos y sauces que actúan como corredor biológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08252','espacio','Riberas del río Ripoll (sector bajo)','Llanura aluvial cuaternaria de inundación fluvial con una fuerte impronta humana. El río mantiene pequeños   humedales y sotos riparios en proceso de restauración ecológica de interés puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08003','espacio','Parque Natural de la Sierra de Collserola (sector central)','Pulmón verde de litología metamórfica (pizarras y esquistos) que corona el frente marítimo barcelonés. Alberga densos bosques mixtos de pino carrasco, encinares y robledales relictos en las vaguadas umbrías con fuentes naturales menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90566','espacio','Parque Natural del Garraf, Avenc de la Ferla y lapiaces de Begues','Extraordinario altiplano kárstico de calizas mesozoicas, caracterizado por un paisaje lunar de dolinas, profundas simas o avencs de rango internacional y colosales formaciones de lapiaces. La vegetación es arbustiva baja y muy adaptada a la aridez del suelo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90567','espacio','Sierra de Queralt (sector sur) y torrentes de Bellprat','Relieve escarpado de media montaña prelitoral cubierto por pinares de pino laricio y encinares mediterráneos bien conservados. El paisaje muestra pequeñas fallas y cárcavas sobre materiales margosos de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08005','espacio','Sierra de Queralt, santuario de Queralt (entorno natural) y garganta del Llobregat','Imponente murallón calizo prepirenaico que se eleva de forma abrupta marcando el límite con la llanura central catalana. Sus laderas umbrías presentan hayedos colgados, robledales y farallones de gran fuerza estética visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90568','espacio','Cingles de Bertí, Valle de Sant Miquel del Fai y río Tenes','Espectacular desfiladero fluvial calizo donde el río Tenes rompe la cordillera prelitoral formando impresionantes cortados rocosos y travertinos calcáreos. El paisaje destaca por sus cascadas y cuevas naturales kársticas colgadas sobre la roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90569','espacio','Riera de Merlès (sector medio) y riera de Margansol','Relieve prepirenaico quebrado e indómito, surcado por la riera de Merlès, que labra en la roca caliza un rosario de pozas circulares, toboganes naturales y saltos de agua cristalina rodeados de pinares de pino albar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90880','espacio','Valls de l''Anoia, torrent de la Mare de Déu y cascadas de Cabrera','Profundos torrentes encajados sobre conglomerados y arcillas que generan espectaculares saltos de agua estacionales y saltos entre la vegetación húmeda. Ofrece un paisaje quebrado de gran exuberancia botánica local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08029','espacio','Macizo de Burriac (Parque de la Serralada de Marina)','Promontorio granítico cónico exento que emerge con fuerza tectónica cerca de la línea costera del Maresme. Las faldas están tapizadas por pinares de pino piñonero asentados sobre suelos de sauló erosionados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08030','espacio','Parque de la Serralada de Marina (sector central) y turo d''en Montgros','Paisaje alomado prelitoral con laderas de granito cubiertas de densos pinares y alcornocales relictos mediterráneos. Presenta interesantes formaciones de rocas meteorizadas en bloques redondeados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08031','espacio','Altiplano de Calaf y nacimientos fluviales menores','Elevada planicie estepa de la Cataluña central con suelos arcillosos intensamente cultivados. Cuenta con pequeños rodales aislados de robles de hoja pequeña y matorrales continentales de interés local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08034','espacio','Meandro del río Calders y paraje de la Font de les Tàpies','Impresionante meandro encajonado excavado por el río Calders en los materiales calcáreos mesozoicos de la comarca del Moianès. Las laderas muestran taludes escarpados con vegetación de ribera y encinar de solana.   He completado exhaustivamente los primeros municipios de la provincia de Barcelona aplicando los criterios rigurosos de clasificación y puntuación estricta de naturaleza pura. Propón el siguiente paso para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08033','espacio','Riera de Caldes, montaña del Farell y fuentes termales (entorno natural)','Relieve quebrado en la cordillera prelitoral dominado por fallas tectónicas profundas de donde emanan aguas hipertermales de origen meteórico. Las laderas del Farell albergan pinares de pino carrasco y encinares mediterráneos asentados sobre pizarras y calizas primitivas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90025','espacio','Riera de Caldetes y contrafuertes del Parque del Montnegre i el Corredor','Reducido territorio prelitoral donde los relieves graníticos de la Cordillera Litoral se desploman hacia la franja costera. La riera principal transporta abundantes arenas feldespáticas (sauló) procedentes de la meteorización física de los batolitos graníticos de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08036','espacio','Sierra de l''Ancosa (estribaciones) y lomas calizas de la Alta Anoia','Relieve alomado y tabular constituido por calizas, margas y yesos del Oligoceno continental en el sector noroccidental de la provincia. Su interés radica en la vegetación arbustiva xerófila calcícola y los campos de lapiaces menores de valor puramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08037','espacio','Riera de Sant Martí y lomas de margas de la Plana de Vic','Territorio plano integrado en la gran depresión central de Osona, caracterizado por suelos margosos de origen marino eoceno. Presenta pequeñas cárcavas grises   esculpidas por la erosión pluvial y sotos de sauces modificados de interés biológico local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08039','espacio','Parque Natural del Montseny, riera de Campins y laderas de la Costa de Montseny','Magnífico relieve montañoso de naturaleza silícea inserto en las faldas meridionales del macizo del Montseny. Presenta una zonación vegetal excepcional donde el encinar mediterráneo basal cede paso a densas masas umbrías de castañares, robledales e incluso hayedos relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08008','espacio','Riera de Canet y monte de la Misericordia','Paisaje granítico colinado que desciende suavemente hacia el litoral del Maresme septentrional. El paraje destaca por sus laderas de sauló erosionadas, cubiertas por pinares de pino piñonero y matorrales esclerófilos de baja cobertura vegetal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08041','espacio','Torrente de Canovelles y terrazas fluviales del Congost','Llanura aluvial y colinas suaves del Vallès Oriental modeladas por depósitos sedimentarios cuaternarios. Carece de accidentes geomorfológicos prominentes y mantiene un interés natural relicto constreñido a pequeños retazos de bosque mixto mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08043','espacio','Parque de Garraf (sector occidental), Sierra de Puig de l''Àliga y torrente de Canyelles','Relieve escarpadito calcáreo con un modelado kárstico inicial dominado por formaciones de maquia mediterránea baja con palmito. La Sierra de Puig de l''Àliga ofrece excelentes panorámicas visuales de las muelas calcáreas degradadas de la comarca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08044','espacio','Acantilado de la Cova del Toll (Abric Romaní) y riberas del río Anoia','Impresionante formación geológica de travertinos y tobas calcáreas depositadas por antiguos manantiales que formaron un gran acantilado fluvial sobre el río Anoia. Contiene numerosas oquedades y abrigos kársticos de gran relevancia a nivel geomorfológico regional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08045','espacio','Cingles de Capolat y Sierra dels Tossals','Espectacular muralla geológica prepirenaica formada por imponentes riscos horizontales de conglomerados calizos del terciario superior que caen en vertical sobre el llano. Aloja densos pinares de pino laricio, quejigares de montaña y canchales de gran fuerza paisajística.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08046','espacio','Riera de Cardedeu y lomas prelitorales del Vallès','Suaves ondulaciones cuaternarias de la fosa del Vallès que funcionan como zona de transición hacia el macizo del Montseny. Presenta pequeños rodales forestales de pino piñonero y encinas diseminadas de interés biológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08009','espacio','Valle Salino de Cardona (Diapiro de sal) y riberas del río Cardener','Excepcional monumento de la geología mundial constituido por una inmensa montaña de sal pura originada por la evaporación de un mar interior en el Eoceno y su posterior ascenso diapírico. El paisaje ofrece cárcavas salinas de vivos colores, agujas de yeso y una rarísima flora halófila adaptada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08048','espacio','Valle de la riera de Carme y fuentes del paraje de les Totes','Depresión fluvial encajonada entre relieves calizos y margosos del macizo de Miralles-Ancosa. El cauce de la riera mantiene aguas cristalinas permanentes gracias a importantes surgencias kársticas basales que sustentan sotos riparios muy densos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90572','espacio','Riera de Clarà y encinares continentales del Berguedà inferior','Relieve alomado y quebrado del prepirineo central erosionado por una densa red de torrentes estacionales. Las laderas calizas presentan pinares de pino carrasco y encinares de carácter continental seco con pequeños afloramientos de roca arenisca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08057','espacio','Sierra de Catllaràs (sector oriental) y riera de Vilada','Territorio prepirenaico indómito dominado por los relieves escarpados y calcáreos de la Sierra de Catllaràs. Cuenta con frondosos bosques de pino albar, hayedos umbríos bien conservados y cortados rocosos donde nidifican rapaces pirenaicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90881','espacio','Fuentes del Llobregat (Nacedero), Parque Natural del Cadí-Moixeró (sector este) y acantilados de la Creu de Maians','Paisaje alpino de alta montaña caliza de gran envergadura donde destaca el nacedero del río Llobregat, que brota en espectaculares cascadas directamente de las fisuras kársticas de la roca calcárea. Las cumbres presentan praderas alpinas altas y extensos bosques de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08050','espacio','Rasos de Peguera (Altiplano alpino) y nacimiento de la riera de Demunt','Impresionante altiplano de origen kárstico situado a más de 1.800 metros de altitud, modelado por dolinas y lapiaces cubiertos de pastizales de alta montaña.   Ofrece un relieve abrupto con densas masas boscosas de pino negro pirenaico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08051','espacio','Parque Natural de Sant Llorenç del Munt i l''Obac (sector oriental) y cañón del río Ripoll','Espectacular paisaje de conglomerados rojizos erosionados que forman monolitos, canales y cingles verticales característicos del macizo de Sant Llorenç. El río Ripoll discurre encajado entre terrazas fluviales y escarpes de roca sedimentaria.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08053','espacio','Parque Natural de la Montaña de Montserrat (sector norte) y meandros del río Llobregat','Punto estratégico donde el río Llobregat labra profundos meandros encajados cortando los materiales sedimentarios del prelitoral bajo el perfil de las colosales agujas de Montserrat. Las vertientes albergan encinares mediterráneos y olivares antiguos degradados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08054','espacio','Confluencia de los ríos Llobregat y Rubí, y bosques de la riera de Fontpineda','Valle fluvial y lomas arcillo-arenosas con una fuerte impronta antrópica industrial. Mantiene pequeñas zonas de vegetación riparia de sauces y álamos negros que funcionan como conector biológico a nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08055','espacio','Riera de Castellcir, la Popa (Formación geológica) y bosques del Moianès','Altiplano calizo del Moianès que destaca por la formación rocosa de "la Popa", un bloque calizo erosionado de forma diferencial que emula la popa de un buque. El término está surcado por rieras con pequeñas pozas y densos pinares de pino laricio.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08056','espacio','Parque Natural del Garraf (frente marítimo) y laderas de la Sentiu','Sector donde las faldas calcáreas meridionales del macizo del Garraf entran en contacto directo con la llanura deltaica prelitoral. Presenta pendientes escarpadas cubiertas de maquia mediterránea, palmitos y canteras calizas integradas geológicamente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08059','espacio','Sierra de Maians, altiplano del Bages meridional y torrente de Grevalosa','Paisaje tabular calcáreo y quebrado con valles encajados labrados sobre materiales margosos. La vegetación predominante está constituida por densos pinares mixtos de pino laricio y encinares de montaña de carácter continental seco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08060','espacio','Riberas del río Llobregós y cárcavas de yesificaciones','Relieve alomado continental sometido a intensos procesos de erosión pluvial que generan formaciones de badlands y cárcavas sobre margas yesíferas grises. Su cubierta vegetal es rala, de carácter estepario mediterráneo comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08061','espacio','Confluencia de los ríos Cardener y Llobregat, y lomas de Puig d''en Coll','Nudo hidrológico fluvial donde el río Cardener entrega sus aguas al Llobregat sobre terrazas aluviales de gravas cuaternarias. El entorno presenta colinas de areniscas cubiertas de pino carrasco y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08062','espacio','Serrat de la Sala y pinares de Castellnou','Relieve de colinas suaves y alineaciones montañosas menores constituidas por margas y calizas de la   Cataluña central. Alberga extensiones homogéneas de pino carrasco y encinares regenerados de uso forestal comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08063','espacio','Cingles de Castellolí (Sierra de Moncau) y riera de Castellolí','Escarpado relieve calcáreo de la cordillera prelitoral que exhibe impresionantes riscales calcáreos orientados al norte. Sus vertientes albergan una vegetación mixta con pinos y encinares de ladera bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08064','espacio','Riera de Fontscalents, cuevas del Toll (sector sur) y pinares del Moianès','Paisaje característico de altiplano calcáreo con notables dolinas y surgencias de agua como la Fontscalents, que genera tobas calcáreas vivas. Cuenta con frondosas masas boscosas de pino laricio y encinares montanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08065','espacio','Riera de Marmellar (curso medio) y cingles del Bolet','Lomas calcáreas y vertientes de pendiente moderada que cierran la fosa del Penedès por el oeste. El relieve presenta pequeños afloramientos kársticos y matorral mediterráneo termófilo de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08066','espacio','Sierra de l''Ataix y torrente de Can Sunyer','Pequeña alineación montañosa prelitoral de naturaleza paleozoica (pizarras y esquistos) con laderas cubiertas de pino carrasco. El relieve es quebrado, sufriendo una intensa sequedad estival mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08067','espacio','Cingles de Bertí (vertiente occidental) and torrente de la Lavandera','Imponente murallón de roca caliza y areniscas horizontales que se eleva verticalmente sobre el congosto del   río Congost. Las laderas presentan canchales, cuevas kársticas menores y robledales de hoja pequeña de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90573','espacio','Embalse de Baells (río Llobregat), Sierra de Ensija (estribaciones) y cingles de Vallcebre','Extraordinario entorno de transición pirenaica donde el río Llobregat queda embalsado en un cañón de laderas calcáreas vertiginosas. Los escarpes rocosos muestran estratos geológicos verticales alpinos y densas masas de pino albar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08266','espacio','Parque Natural de la Sierra de Collserola (vertiente norte) y torrente de Sant Iscle','Laderas septentrionales del macizo metamórfico de Collserola tapizadas por pinares mixtos de pino carrasco y encinares húmedos de vaguada. Funciona como un relevante conector biológico prelitoral de rango comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08068','espacio','Macizo del Ordal, cingles de Penya Roja y torrente de Santa María','Relieve kárstico de calizas mesozoicas caracterizado por sus impresionantes riscales de coloración rojiza y profundas grietas tectónicas. Aloja formaciones de maquia mediterránea noble con abundantes encinas y quejigos encajados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08069','espacio','Parque Natural de la Montaña de Montserrat (vertiente sur) y Cuevas de Montserrat (Coves del Salnitre)','Espectacular portal kárstico meridional de la montaña sagrada; las Coves del Salnitre constituyen un sistema colosal de galerías subterráneas excavadas en conglomerados calicios con formas caprichosas. En la superficie, los paredones verticales de roca pura se elevan cientos de metros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08070','espacio','Altiplano de Collsuspina (nacimiento del río Congost) y cueva de Cabrera','Meseta elevada de naturaleza caliza y margosa que funciona como divisoria climática y de aguas entre las cuencas del Besòs y Ter. Presenta un relieve de lomas verdes salpicadas de dolinas y robledales montanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08071','espacio','Valle de la riera de San Pedro (río Anoia alto) y saltos de agua estacionales','Valle de erosión fluvial encajonado en las plataformas calcáreas de la Alta Anoia, donde la riera forma pequeños desfiladeros, pozas de roca y cascadas intermitentes rodeadas de pinares mixtos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08072','espacio','Macizo de l''Ordal, Roca de la Creu y torrente de Corbera','Territorio quebrado de naturaleza calcárea y arcillosa que exhibe un relieve abrupto de cingles calcáreos rojizos e imponentes formas de erosión lineal. Sus masas forestales son pinares densos y encinares bien conservados en las umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08073','espacio','Delta del río Llobregat (tramo fluvial final)','Llanura aluvial cuaternaria sedimentaria intensamente urbanizada e industrializada en el área metropolitana. Mantiene un valor geográfico exclusivamente local centrado en la dinámica hidrológica marginal del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08074','espacio','Desembocadura del río Foix y espacio natural del Foix litoral','Humedal costero somero constituido por la llanura deltaica final del río Foix, con pequeñas lagunas perennes y carrizales densos. Funciona como un espacio de   descanso local de gran valor para la avifauna marina migratoria. He completado este bloque masivo e ininterrumpido de los municipios de la provincia de Barcelona en estricto orden alfabético. Propón el siguiente tramo para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08075','espacio','Parque del Montnegre i el Corredor y pozo de hielo de Canyamars (entorno)','Relieve alomado de la cordillera prelitoral formado por batolitos graníticos intensamente meteorizados en arenas de sauló. Alberga frondosos bosques de encinas, alcornocales maduros y densos rieroles con vegetación de ribera de gran interés botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08076','espacio','Congosto del río Llobregat y Roques Blaves','Espacio de transición geológica donde destaca el afloramiento de las Roques Blaves, una singular falla de materiales de color azulado debido a la alteración de pizarras paleozoicas. El río Llobregat discurre encajado entre altos taludes y terrazas fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08077','espacio','Torrente de d''en Farré y contrafuertes de la Sierra de Collserola','Territorio intensamente urbanizado asentado sobre el pie de monte metamórfico prelitoral. Conserva pequeños tramos de escorrentías torrenciales canalizadas y zonas de vegetación mediterránea residual de interés estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08078','espacio','Riscos de l''Espunyola y cingles de Capolat (continuación)','Impresionante barrera escarpada prepirenaica formada por extensas muelas y farallones de conglomerados que se desploman verticalmente sobre el llano del Berguedà. Aloja densos pinares de pino laricio y comunidades rupícolas de alto valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08011','espacio','Cuenca de l''Estany (antiguo lago endorreico) y mina de desagüe','Valle cerrado de origen kárstico que albergó un humedal natural desecado artificialmente mediante una obra de ingeniería del siglo XVIII. El entorno destaca por su relieve tabular calizo, prados húmedos y pinares de pino albar continentales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08134','espacio','Congosto del río Congost, Riscos de Bertí y sotos de la riera de Avencó','Estrecha fosa tectónica donde el río rompe la cordillera prelitoral entre imponentes murallones calicos verticales. La riera de Avencó aporta un corredor fluvial de aguas frías y cristalinas con alisios y robledales umbríos soberbios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08080','espacio','Garganta de Fumanya (yacimiento paleontológico y geomorfológico) y Sierra de Ensija','Espectacular relieve de alta montaña caliza que cuenta con una colosal pared vertical de sedimentación cretácica exhumada por la erosión tectónica. El paisaje presenta perfiles alpinos con praderas alpinas altas y densos bosques de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90574','espacio','Riberas del río Tordera y torrente de la Burgada','Amplia llanura aluvial en el límite norte de la provincia constituida por arenas fluviales y gravas cuaternarias. Alberga plantaciones y pequeños sotos de sauces y álamos que actúan como conector ecológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08081','espacio','Parque Natural del Montseny (Reserva de la Biosfera), Valle de Santa Fe y Turó de l''Home','Uno de los enclaves biológicos más importantes de Cataluña, coronado por las máximas cumbres silíceas de la cordillera prelitoral. El Valle de Santa Fe alberga un hayedo primigenio majestuoso y abetales relictos boreoalpinos de rango internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08084','espacio','Riera de Fonollosa y formaciones de yesos de las Torres','Valle de erosión fluvial en la cuenca del Cardener flanqueado por lomas margosas y cerros testigo calcáreos. Mantiene pinares de pino carrasco adaptados al clima continental seco y sotos de ribera bien desarrollados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08085','espacio','Balcón del Penedès (Cingles de Font-rubí) y nacimiento de la riera de Llitrà','Impresionante escarpe calcáreo que se eleva sobre la llanura vinícola, mostrando riscos verticales y cuevas kársticas menores (Avenc del Bolet). Aloja masas compactas de pino carrasco y matorral noble mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90575','espacio','Riberas del río Llobregat (tramo alto) y riera de Serrano','Relieve ondulado de la Cataluña central caracterizado por el encajamiento del Llobregat en materiales margosos. Alberga pinares de pino albar y laricio bien conservados con pequeños sotos riparios de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08087','espacio','Riscos de Gallifa y torrente de la d''en Saera','Espectacular cubeta geomorfológica rodeada por imponentes paredes verticales y riscos calcáreos rojizos de gran altitud. El paisaje forestal es muy denso, combinando encinares maduros en las umbrías con pinares xerófilos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08088','espacio','Parque Natural del Montseny (límite sur) y ribera del río Congost','Valle de transición entre la llanura vallesana y los relieves abruptos del macizo prelitoral. El río Congost mantiene terrazas aluviales fértiles flanqueadas por colinas cubiertas de pino piñonero y encinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08089','espacio','Parque Natural del Garraf, Minas Prehistóricas (entorno geológico) y dunas litorales de Gavà','Extraordinario territorio que combina un frente marino con un ecosistema dunar eólico relicto y las faldas calcáreas del Garraf. El relieve kárstico presenta lapiaces, dolinas y una vegetación de maquia con palmito de gran valor geobotánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08091','espacio','Cingles de Gelida (Sierra de l''Ataix) y torrente de Cantillepa','Vertiente septentrional del macizo del Ordal caracterizada por laderas escarpadas arcillo-calcáreas cubiertas de densos pinares de pino carrasco. Presenta   profundas canales de erosión torrencial orientadas hacia el río Anoia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08092','espacio','Curso del río Llobregat (Berguedà meridional)','Tramo fluvial de aguas constantes encajado suavemente entre cerros de margas y conglomerados. Mantiene un corredor verde maduro de sauces y chopos, históricamente modificado por el aprovechamiento textil textil.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08093','espacio','Parque Natural del Cadí-Moixeró, Fuentes del Bastareny (sector alto) y cingles de Costafreda','Uno de los municipios más indómitos y con menor densidad demográfica de Cataluña, inmerso en la alta montaña alpina. Exhibe vertiginosos cortados de roca caliza, prados subalpinos puros y frondosos bosques de pino negro y hayas relictas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08094','espacio','Llanura sedimentaria del Penedès','Territorio llano de naturaleza arcillosa y calcarenita intensamente modificado para el cultivo de la vid. Carece de relieves abruptos o masas arbóreas naturales autóctonas, poseyendo un valor de rango estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08095','espacio','Riscos de Granera y torrente de la Riera','Altiplano calizo quebrado de la comarca del Moianès con imponentes cingles y monolitos erosionados de forma diferencial. Las laderas están cubiertas por densas masas de pino laricio y encinares montanos de gran tranquilidad paisajística.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08096','espacio','Río Congost (zona periurbana) y parque fluvial','Tramo bajo de la cuenca aluvial del Congost sobre sedimentos cuaternarios del Vallès Oriental. Su interés   natural es bajo y centrado en la recuperación ecológica de las zonas húmedas riparias marginales de nivel local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08097','espacio','Parque Natural del Montseny, Riera de Gualba y cascada del Salto de Gualba','Espectacular relieve montañoso granítico y metamórfico donde la riera desciende con una violencia torrencial extrema, generando un salto de agua vertical colosal sobre rocas cristalinas. El entorno está cubierto de densos encinares, robledales y alcornocales maduros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08099','espacio','Parque Natural del Cadí-Moixeró, Confluencia de los ríos Bastareny y Llobregat, y desfiladero de Brocà','Destacable nudo hidrológico y tectónico prepirenaico rodeado de imponentes masas calizas. El Llobregat y el Bastareny labran cañones angostos con paredes verticales, rodeados de bosques mixtos de alta montaña e importantes fuentes kársticas.   He completado este tramo masivo e ininterrumpido de los municipios de la provincia de Barcelona en estricto orden alfabético. Propón el siguiente tramo para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08100','espacio','Cerro de la Creu de Gurb y torrentes de la Plana de Vic','Prominente cerro testigo de naturaleza margosa y calcárea que emerge de forma aislada sobre la llanura central de Osona. Sus laderas sufren erosión pluvial en cárcavas grises y albergan retazos de robledal y pino laricio de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08101','espacio','Márgenes terminales de la llanura del delta del Llobregat','Espacio deltaico cuaternario completamente antropizado e integrado en la trama urbana metropolitana. Carece de accidentes geográficos naturales y su interés ecosistémico original es meramente relicto a nivel puramente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08102','espacio','Lecho aluvial del río Anoia (tramo urbano-periférico)','Cuenca fluvial de sedimentación arcillosa intensamente modificada por el desarrollo industrial e histórico del municipio. Mantiene pequeños sotos de cañaverales, sauces y álamos en proceso de regeneración ambiental local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08103','espacio','Riera de Rubió y lomas calizas de Jorba','Relieve alomado constituido por materiales sedimentarios paleógenos de la cuenca central. La riera labra un valle somero flanqueado por pinares mixtos de pino carrasco y matorrales mediterráneos continentales de interés comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08104','espacio','Sierra de Ancosa, cingles de Valldeperes y altiplano de La Llacuna','Elevada planicie calcárea rodeada por imponentes riscos escarpados y fallas tectónicas de la cordillera prelitoral. Alberga valiosas masas forestales de pino albar, encinares montanos bien conservados y campos de lapiaces kársticos de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08105','espacio','Confluencia de la riera de Polinyà y el río Besòs (márgenes)','Reducido término municipal asentado sobre la llanura aluvial del Vallès, con una ocupación industrial y   residencial intensiva. Conserva zonas fluviales muy modificadas con un valor ecológico estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90576','espacio','Valle de la riera de Tenes y bosque de Can Bosquerons','Paisaje de colinas suaves labradas sobre limos y arcillas cuaternarias en el Vallès Oriental. Mantiene retazos discontinuos de bosque mixto mediterráneo y sotos de sauces de interés biológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08108','espacio','Riera de Tenes (tramo medio) y torrentes menores','Relieve ondulado de baja altitud integrado en la cuenca de sedimentación prelitoral mediterránea. Presenta una fisonomía agraria y forestal fragmentada, con pequeñas choperas y encinas aisladas de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08106','espacio','Parque del Montnegre i el Corredor (vertiente norte) y riera de Mogent','Laderas de origen granítico intensamente cubiertas por masas forestales estables de pino piñonero, encinares y alcornocales maduros. Los barrancos de sauló erosionados vierten de forma torrencial hacia la llanura aluvial del Mogent.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90577','espacio','Altiplano del Lluçanès y riera de Lluçanès','Meseta elevada de naturaleza margosa y arenisca con un relieve quebrado y frío de media montaña central. Cuenta con frondosos pinares de pino albar, robledales de quejigo y arroyos limpios de gran valor para la fauna acuática comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08012','espacio','Delta del río Tordera (desembocadura)','Amplia llanura aluvial costera constituida por depósitos de arenas graníticas y gravas aportadas por el río Tordera. El espacio mantiene pequeñas lagunas intermareales y carrizales costeros de interés local para aves migratorias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08111','espacio','Cerros testigo de margas eocenas de Malla','Llanura sedimentaria rota por pequeños promontorios cónicos grises esculpidos por los procesos de arroyada y erosión pluvial. Alberga praderas secas y matorrales mediterráneos continentales de rango estrictamente local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08013','espacio','Meandro del río Ter en Manlleu y sotos fluviales','Tramo donde el río Ter discurre formando amplias curvas sobre terrazas aluviales de gravas cuaternarias en la Plana de Vic. Conserva un corredor verde regular de sauces, chopos y álamos de gran interés ecológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08113','espacio','Confluencia de los ríos Cardener y Llobregat, y humedal de la Agulla','Importante nudo hidrológico de la Cataluña central caracterizado por las terrazas sedimentarias arcillocalcáreas labradas por ambos cursos fluviales. El entorno presenta sotos riparios modificados y pequeños cerros de margas de valor comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08242','espacio','Parque Natural de la Montaña de Montserrat (vertiente norte) y riera de Marganell','Extraordinario y abrupto paisaje configurado por el frente de erosión septentrional de Montserrat, exhibiendo colosales agujas y paredes verticales de conglomerados calizos del terciario. La riera discurre encajada en umbrías frondosas de encinares montanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08115','espacio','Congosto de Martorell (río Llobregat) y desembocadura del río Anoia','Estrecho pasillo tectónico natural donde el Llobregat corta de forma abrupta la Cordillera Litoral catalana sobre materiales paleozoicos. A pesar del fuerte impacto de infraestructuras, el relieve posee una gran relevancia morfológica y estructural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08118','espacio','Rieras de Alella y Teià (tramos litorales terminales)','Estrecha franja costera de llanura prelitoral intensamente urbanizada sobre arenas graníticas de sauló.   Carece de relieves naturales conservados de envergadura, limitándose al interés morfológico costero local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08120','espacio','Parque Natural de Sant Llorenç del Munt i l''Obac, El Montcau (cima) y cingles de la Barata','Espectacular relieve de conglomerados deltaicos del eoceno que genera un paisaje único de muelas horizontales, monolitos gigantescos y canales verticales de coloración rojiza. Alberga encinares encajados e importantes sistemas kársticos de cuevas y simas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08121','espacio','Parque del Montnegre i el Corredor (sector sur) y acantilados de las Cinc Sènies','Laderas graníticas de la cordillera prelitoral que descienden hacia el mar Mediterráneo formando terrazas de sauló. El paraje cuenta con masas forestales estables de pino piñonero y encinares litorales de nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08122','espacio','Desfiladero de Mediona (río de Bitlles) y cingles de Mediona','Angosto cañón fluvial labrado de forma vertical por el río sobre las calizas mesozoicas de la cordillera prelitoral. El relieve es abrupto, cubierto de densos encinares y pinos, con pequeñas pozas naturales y surgencias kársticas basales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90578','espacio','Cuevas del Toll (Complejo kárstico), Riera de Castellnou y altiplano del Moianès','Destacable sistema de cuevas naturales prehistóricas excavadas por la acción kárstica subterránea en calizas eocenas. El altiplano circundante muestra un relieve quebrado salpicado de dolinas, robledales montanos y frondosos pinares resineros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08123','espacio','Parque Natural de la Sierra de Collserola (sector occidental) y riera de Vallvidrera','Laderas de pizarras y esquistos paleozoicos cubiertas de densos pinares de pino carrasco y encinares mixtos. La riera de Vallvidrera mantiene un humedal lineal modesto con vegetación riparia bien conservada a nivel comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08124','espacio','Espacio Natural de Gallecs (área agrícola-forestal relicta)','Suaves ondulaciones de la fosa del Vallès que conservan una fisonomía de paisaje rústico tradicional de gran valor conectivo. Alberga pequeños encinares diseminados, balsas estacionales y humedales de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08127','espacio','Parque Natural de la Montaña de Montserrat (vertiente oriental) y desfiladero del río Llobregat','Impresionante portal de acceso al colosal macizo montañoso de Montserrat. El relieve presenta un desplome vertical absoluto de agujas calcáreas cilíndricas que se elevan más de 700 metros sobre el lecho encajonado del río Llobregat.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08128','espacio','Riera de Calders, confluencia de las rieras de San Juan y de la Golarda, y monolito de la Pedrosilla','Paisaje sumamente quebrado del Moianès meridional, caracterizado por el laberíntico encajamiento de rieras en plataformas calcáreas horizontales. Destaca por sus pozas naturales de roca, travertinos fósiles y caprichosas formas de erosión diferencial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08125','espacio','Parque Natural de la Sierra de Collserola (sector norte), Cerro de Montcada y río Besòs','Nudo tectónico y fluvial prelitoral donde el río Besòs se abre paso cortando relieves metamórficos paleozoicos. El Cerro de Montcada representa un espolón calizo intensamente explotado pero de gran relevancia geológica estructural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08130','espacio','Riera de Montclar y lomas del Berguedà inferior','Relieve alomado constituido por margas y areniscas de la Cataluña central, surcado por pequeños torrentes de régimen marcadamente estacional. Mantiene pinares de pino carrasco y pastizales secos de interés puramente comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08131','espacio','Espacio Natural Protegido de Montesquiu y desfiladero del río Ter (Bisaura)','Hermoso relieve prepirenaico donde el río Ter discurre encajado entre terrazas fluviales de gravas y vertientes escarpadas de margas azules. Las laderas están cubiertas por majestuosos robledales de hoja pequeña y pinares de pino albar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08126','espacio','Acantilados calcáreos del Turó de Montgat y costa prelitoral','Pequeño promontorio rocoso calizo jurásico que corta la línea de costa arenosa del Maresme. Constituye una singularidad geológica litoral debido a la interrupción de la playa por un escarpe rocoso expuesto directamente al oleaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08132','espacio','Riera de Navel (curso alto) y cingles de Taravil (estribaciones)','Relieve quebrado prepirenaico que combina valles de inundación fluvial con colinas calizas de pendiente moderada. La riera de Navel destaca por la excelente conservación de sus sotos de ribera y masas boscosas mixtas de pino albar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08133','espacio','Altiplano de la Segarra (sector oriental) y nacimiento del río Anoia','Elevada planicie de carácter continental y semiárido compuesta por calizas tabulares del Oligoceno. Da origen a las primeras redes de drenaje de la cuenca del Anoia en un entorno de matorral esclerófilo menor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08135','espacio','Confluencia de los ríos Congost y Mogent (Nacimiento del río Besòs)','Llanura aluvial cuaternaria sedimentaria intensamente urbanizada en la fosa prelitoral del Vallès Oriental. Su interés natural se constriñe al punto geográfico de confluencia hidrológica y sus sotos riparios marginales de rango local.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08136','espacio','Parque de la Serralada de Marina (sector nororiental) y ribera del río Mogent','Lomas graníticas de perfiles redondeados cubiertas por masas homogéneas de pino piñonero y encinares degradados. El Mogent aporta un corredor verde modesto con carrizales y sauces de interés biológico comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08137','espacio','Parque Natural del Montseny (Reserva de la Biosfera), Les Agudes, Matagalls y nacedero de la Tordera','Espectacular epicentro de la montaña prelitoral catalana; coronado por las imponentes cumbres silíceas de Les Agudes y Matagalls. Exhibe majestuosos bosques caducifolios de hayas, castañares monumentales y abetales relictos de rango planetario regados por torrentes cristalinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08129','espacio','Altiplano del Moianès (sector norte) y torrentes de Muntanyola','Paisaje tabular calizo de altitud media caracterizado por un relieve quebrado surcado por profundas canales de erosión lineal. Alberga densos pinares de pino laricio y encinares montanos de gran tranquilidad ambiental comarcal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08139','espacio','Parque Natural de Sant Llorenç del Munt i l''Obac, Riera de Mura y cuevas de Mura','Pintoresco y espectacular entorno constituido por los colosales cingles de conglomerados rojizos del macizo de Sant Llorenç. La riera labra un cañón kárstico de aguas transparentes con espectaculares pozas y surgencias basales rodeadas de densos encinares.   He finalizado este bloque de municipios de la provincia de Barcelona en estricto orden alfabético nacional, llegando con total rigor hasta la letra M. Propón el siguiente paso para.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08140','espacio','Confluencia del río Calders y el río Llobregat, y Parc de l''Anella Verda','Espacio fluvial caracterizado por una notable llanura aluvial y un denso bosque de ribera que destaca por su riqueza botánica en sauces, álamos y fresnos. La acumulación de sedimentos fluviales genera un paisaje de aguas mansas idóneo para la observación contemplativa de la fauna avícola lacustre en el entorno del Bages.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08141','espacio','Torrenteras de la riera de Merlès y acantilados de calizas','Interesante tramo de la cuenca fluvial caracterizado por lechos de roca erosionados que forman pequeñas marmitas de gigante y saltos de agua estacionales. El entorno geológico destaca por sus formaciones sedimentarias continentales rodeadas de densos pinares de pino carrasco.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08143','espacio','Cuenca de Ódena y escarpes margosos','Singular paisaje erosivo modelado sobre margas yesíferas que genera una topografía de cárcavas y cerros testigo de tonalidades blanquecinas y grisáceas. El contraste visual se intensifica con pequeñas formaciones boscosas perennifolias adaptadas a la aridez del suelo.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08145','espacio','Espacio Natural Protegido de Olèrdola (Macizo del Garraf)','Paisaje kárstico caracterizado por un relieve abrupto de riscos calcáreos, lapiaces y simas profundas originadas por procesos de disolución carbonatada. La vegetación dominante está adaptada a la sequedad, destacando los matorrales de palmito y el pinar de pino carrasco sobre roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08146','espacio','Sima del Hospital y cañón de la riera de Hospital','Una de las fracturas kársticas más profundas e icónicas del macizo del Garraf, donde la disolución de la caliza ha tallado paredes verticales de gran envergadura. Su entorno exhibe una morfología de piedra caliza expuesta, donde el agua se filtra instantáneamente hacia acuíferos subterráneos.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08147','espacio','Desfiladero del Llobregat (Congost del Cairat) y Fallas de Olesa','Estrechamiento fluvial colosal donde el río Llobregat corta de forma transversal los contrafuertes de la cordillera Prelitoral, exponiendo estratos geológicos verticales y fallas tectónicas de gran interés didáctico. El relieve es abrupto, combinando roca desnuda con comunidades vegetales de umbría.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08148','espacio','Valle de la Riera de Begues y Plana de Novella','Depresión interior rodeada por los relieves abruptos del Parque Natural del Garraf, mostrando un fuerte contraste entre los suelos aluviales y las laderas calizas   circundantes. Destaca la presencia de dolinas y la transición vegetal entre encinares litorales y matorrales calcícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08149','espacio','Riera de Garet y Pantano de Reixach','Paisaje mesetario propio de la subcomarca del Lluçanès donde los cursos de agua estacionales han labrado pequeños valles en margas y areniscas. El entorno destaca por la alternancia de robledales pubescentes y comunidades de ribera bien integradas en la matriz geomorfológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08144','espacio','Desfiladero del Llobregat y bosque de ribera de la Baells','Tramo fluvial pre-pirenaico donde el cauce fluye confinado entre terrazas fluviales estables y cortados de roca sedimentaria. Destaca por sus comunidades vegetales sumergidas y las densas masas forestales de pino rojo que trepan por las laderas del valle.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08150','espacio','Crestas margo-calcáreas del valle del Ter','Formaciones montañosas singulares moldeadas sobre margas de tonalidades azuladas que han sufrido una fuerte incisión erosiva. El relieve destaca por sus crestas afiladas y escarpes verticales que controlan visualmente el curso del río Ter.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08151','espacio','Meandros ensanchados de la Riera Gavarresa','Relieve esculpido de forma sinuosa sobre materiales sedimentarios fluviales, donde destacan los cortes geológicos verticales en los márgenes del curso de agua. La fisonomía encajonada ofrece un ecosistema de cortados arcillosos salpicados de vegetación mediterránea perennifolia de gran interés visual.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08164','espacio','Ladera oriental y pinedas de la Bleda','Entorno caracterizado por lomas suaves de margas miocénicas cubiertas de densas masas de pino carrasco bien conservadas que rompen la monotonía del llano. Geológicamente destaca por la pureza de sus suelos   arcilloso-calcáreos que configuran una transición geomorfológica sutil hacia las sierras litorales. Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08155','espacio','Delta del Tordera e llanura aluvial de ribera','Espacio lagunar y deltaico compuesto por arenas graníticas finas depositadas por el curso bajo del río Tordera. Presenta agrupaciones de vegetación palustre singulares y juncales costeros protegidos de la influencia marina directa, ideales para la contemplación botánica y geológica.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08156','espacio','Humedales de la Riera de Caldes y Bosc de Can Pavana','Pequeña cuenca sedimentaria interior que retiene láminas de agua temporales asociadas a acuíferos someros. Alberga reductos de encinar termófilo y álamos que sobreviven en un entorno de llanura prelitoral densamente erosionada de forma natural.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08157','espacio','Cingles de l''Aragall y formaciones de roca roja','Imponentes farallones rocosos compuestos por areniscas del Buntsandstein que muestran un intenso color rojizo debido a los óxidos de hierro. Sus paredes verticales contrastan cromáticamente con el manto verde de pino blanco y matorral mediterráneo esclerófilo.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08905','espacio','Riera de Rafamans y entorno de la roca de la Creu','Pequeño valle encajonado en el sector más septentrional del macizo de Garraf-Ordal, con interesantes formaciones de areniscas rojas del Bundsandstein. El agua modela pequeños saltos temporales sobre las rocas y alimenta franjas estrechas de bosque de ribera mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08158','espacio','Escletxes d''El Papiol y vertiente del Parc de Collserola','Espectaculares grietas tectónicas abiertas en bloques calcáreos del Mioceno debido a fenómenos de distensión y deslizamiento sobre arcillas basales. Esta   singularidad geomorfológica crea pasadizos naturales profundos cubiertos de musgos, helechos y hiedras umbrías de gran belleza. Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08159','espacio','Cuenca fluvial del río Tenes','Tramo aluvial encajonado de forma suave que expone terrazas fluviales cuaternarias bien definidas. Mantiene pequeños tramos de saucedas y carrizales que sirven de refugio natural para comunidades biológicas aisladas de la llanura prelitoral.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08160','espacio','Altiplano de la subcomarca del Lluçanès y riscos del torrente de Noguera','Altiplano calizo caracterizado por una alternancia de pastizales naturales y masas boscosas de roble pubescente adaptadas al clima de montaña media. Los pequeños barrancos circundantes muestran procesos de erosión diferencial sobre areniscas del Eoceno.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08161','espacio','Cárcavas del Bedorc y desfiladero de la riera de Piera','Impresionante paisaje de badlands formado por la intensa erosión hídrica sobre arcillas rojas y conglomerados miocénicos de la cuenca del Anoia. El relieve resultante es un laberinto de chimeneas de hadas, crestas afiladas y taludes verticales desprovistos de vegetación por su alta inestabilidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08016','espacio','Riscos y laderas graníticas del Parc del Montnegre i el Corredor','Vertiente marítima abrupta configurada por la erosión de macizos graníticos paleozoicos descompuestos en sauló. El paraje muestra espectaculares afloramientos de roca   madre rodeados de densos encinares litorales y alcornocales maduros que miran hacia el mediterráneo. Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08165','espacio','Desfiladero de Claramunt y riscales del río Anoia','Estrechamiento fluvial tectónico donde el río Anoia corta los relieves calizos de la cordillera Prelitoral, aislando un cerro testigo de crestas afiladas. La panorámica muestra imponentes farallones rocosos que encajonan el fondo del valle.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08166','espacio','Fuentes del río Llobregat (Sector norte), Sierra de Catllaràs y cueva de la Creu de Melgans','Joya pre-pirenaica de relieve calizo alpino, con gargantas estrechas donde el Llobregat brota y ruge con fuerza entre la roca viva. Sus bosques de hayas y pinos negros cubren laderas escarpadas de un valor estético excepcional, complementado por sistemas de cavidades subterráneas de disolución kárstica.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08167','espacio','Riera de Polinyà y lomas arcillosas','Paisaje de colinas suaves labradas sobre limos y arcillas cuaternarias donde la riera genera una modesta banda de vegetación de ribera. Su interés es de rango local, centrado en la observación de la dinámica erosiva pluvial de las lomas.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08182','espacio','Valles del río Llobregat y Riera de Mura (Sant Llorenç del Munt)','Territorio de transición geológica caracterizado por plataformas tabulares calcáreas fragmentadas por profundos cañones fluviales. Las paredes de los cañones muestran la clásica estratificación de conglomerados eocénicos con cuevas y abrigos naturales de origen cárstico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08168','espacio','Fuentes de la riera de Pontons, desfiladero de las Fonts y acantilados calcáreos','Cañón calizo abrupto esculpido por la acción continua del agua, que brota con abundancia en surgencias naturales a lo largo de la riera. Las paredes rocosas verticales   albergan cuevas, repisas colonizadas por hiedras y formaciones travertínicas de enorme belleza contemplativa. Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08170','espacio','Cabecera de la Riera de l''Anoia y llanuras margosas','Relieve ondulado propio de la Alta Segarra que expone una estratigrafía de yesos y arcillas continentales de origen lacustre. Su vegetación arbustiva esteparia destaca por   su adaptación a la extrema continentalidad térmica e hídrica de la meseta central. Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08017','espacio','Cuestas marginales del Lluçanès y formaciones margosas','Relieve de cuestas y lomas tabulares calcáreas que delimitan la meseta central catalana, mostrando una transición de formaciones de margas grises. La vegetación se compone de robledales continentales y claros de tomillares que colonizan los suelos pedregosos.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08230','espacio','Cimas de San Mateo y bloques graníticos expuestos','Crestas montañosas dominadas por procesos de meteorización esferoidal granítica que generan caos de bolos rocosos monumentales. El bosque dominante de encinas y pinos piñoneros se asienta sobre suelos de arena granítica expuestos a los vientos marinos.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08172','espacio','Frente litoral arenoso sumergido','Tramo de costa baja de acumulación arenosa granítica generada por los aportes de las rieras costeras del Maresme. Excluyendo las infraestructuras artificiales, ofrece una perspectiva nítida de la dinámica sedimentaria marina litoral.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90580','espacio','Reductos forestales de la llanura aluvial del Penedès','El municipio más pequeño de la provincia apenas conserva una loma de llanura sedimentaria con pequeños bosquetes mixtos residuales. Su valor radica en la observación geomorfológica de los suelos de la depresión prelitoral catalana y sus escorrentías estacionales.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08175','espacio','Meandros encajados y terrazas del río Llobregat','Formaciones geomorfológicas riparias donde el río Llobregat corta con fuerza estratos de conglomerados continentales y areniscas. Las orillas presentan franjas bien conservadas de bosque galería y saltos de agua naturales sobre los lechos de roca expuesta.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08176','espacio','Altiplano de la Alta Segarra y fuentes del río Sió','Paisaje de elevadas lomas calizas calcadas que marcan la divisoria de aguas entre las cuencas del Llobregat y del Segre. Ofrece un relieve desnudado de vegetación arbórea densa, donde las severas condiciones climáticas y la litología caliza generan un paisaje paramero.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08178','espacio','Valle de Rajadell y riscos de la riera','Espectacular ejemplo de valle prepirenaico excavado en estructuras tabulares horizontales de areniscas y margas rojizas del Oligoceno. Las paredes del valle presentan viseras rocosas y extraplomos de gran belleza visual, cubiertos por masas densas de pino salgareño y encinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08179','espacio','Fuentes de Rellinars y laderas occidentales de la Sierra de l''Obac','Sector montañoso con una topografía abrupta donde los bancos de conglomerados alternan con arcillas rojas, originando surgencias de agua de gran belleza estacional. Las formaciones travertínicas y los saltos de agua temporales brotan entre una densa vegetación mediterránea.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08180','espacio','Ribera aluvial del río Ripoll','Tramo de llanura de inundación cuaternaria caracterizado por depósitos de gravas y arenas gruesas de origen granítico y sedimentario. Presenta zonas de carrizal y sauces que suavizan la fuerte erosión hídrica del tramo medio de la cuenca del Besòs.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08183','espacio','Meandro del río Ter y rocas de las Tres Creus','Gran meandro encajonado donde el río Ter abraza un promontorio rocoso de margas eocénicas antes de adentrarse en la zona de los embalses. Los taludes fluviales son abruptos y muestran una interesante estratificación geológica sedimentaria y comunidades riparias asociadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08184','espacio','Torrent de dels Alous y fallas geomorfológicas menores','Pequeña cuenca de erosión con depósitos de arcillas y limos miocénicos que retienen cierta humedad freática. Conserva pequeñas formaciones vegetales riparias y masas aisladas de pinar de pino carrasco adaptadas a suelos degradados de forma natural.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08185','espacio','Sierra de Rubió y barrancos de la cabecera de la riera de Rubió','Cordillera calcárea prepirenaica que alcanza altitudes notables, mostrando vertientes abruptas cubiertas de pinares de pino salgareño y robledales continentales. Geológicamente destaca por las crestas rocosas de calizas tabulares expuestas a una intensa meteorización física.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08187','espacio','Rodal de Sabadell y torrentes de la cuenca del río Ripoll','Escarpes fluviales y terrazas cuaternarias labradas por el río Ripoll sobre los materiales arcillosos del Vallès, con taludes verticales de arcilla rojiza de notable impacto visual. Pequeños reductos boscosos de encina y pino perviven en las laderas de los torrentes.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08188','espacio','Barrancos del río Merlès y bosques de la meseta prepirenaica','Entorno prealpino estructurado sobre plataformas calcáreas horizontales cortadas por la erosión de pequeños torrentes límpidos. Presenta bosques mixtos muy densos donde destaca el roble pubescente conviviendo con pinos, en un paraje de gran pureza geomorfológica.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08190','espacio','Macizo del Pedraforca y Sierra del Cadí','Icono geológico de Cataluña consistente en un impresionante relieve calizo de estructura tectónica compleja y perfil horquillado debido a la erosión diferencial de sus cumbres dolomíticas. Las laderas presentan imponentes tarteras (pedreras de bloques sueltos), canales rocosos de gran verticalidad, bosques de pino negro y prados alpinos de valor botánico excepcional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90581','espacio','Falla de Sallent y formaciones evaporíticas del río Llobregat','Accidente tectónico de gran relevancia que expone visualmente capas sedimentarias del terciario y afloramientos de sales potásicas. El paso del río Llobregat por   este punto genera pequeños desfiladeros calcáreos y zonas de aguas bravas confinadas por la geología local. Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08194','espacio','Desembocadura del río Besòs (Frente marítimo estuarino)','Tramo final donde las aguas continentales del Besòs contactan con el mar Mediterráneo, conformando un estuario llano de depósitos arenosos y limosos. Su interés radica en la contemplación de la dinámica hidrológica litoral y el avistamiento de aves marinas coloniales.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08195','espacio','Sierra de Els Munts y fuentes del río Ter','Cresta montañosa pre-pirenaica de formas redondeadas pero con vertientes escarpadas que caen hacia la Plana de Vic, cubierta por densos hayedos calcícolas y robledales de hoja grande. Los afloramientos rocosos en las zonas altas ofrecen una nitidez paisajística excepcional.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08196','espacio','Escarpes aluviales del Llobregat y Torrent de Can Sunyer','Vertientes arcilloso-arenosas de la llanura prelitoral que sufren una fuerte erosión hídrica superficial. Muestra pequeños relictos de maquia mediterránea y bosques de pino carrasco que estabilizan las laderas de materiales cuaternarios sueltos.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08197','espacio','Rocas de Sant Magí y vertiente sur del MontnegreCorredor','Paisaje granítico costero con acusadas pendientes orientadas al mar, caracterizado por la presencia de bolos graníticos alterados por meteorización físico-química. Alberga masas forestales mixtas de encina, pino piñonero y alcornocal sobre suelos arenosos permeables (sauló).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08198','espacio','Rieras del macizo del Montseny y piedemonte aluvial','Zona de transición geológica donde los torrentes limpios procedentes del Montseny entran en la fosa del Vallès, depositando potentes conos de deyección compuestos por cantos rodados paleozoicos. La vegetación destaca por frondosas alisedas e hileras de fresnos.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08199','espacio','Riscos del Grava y cañón de la riera de Sorreigs','Espectacular escarpe marginal que delimita la meseta del Lluçanès con la Plana de Vic, formado por una potente serie estratigráfica de calizas nummulíticas del Eoceno. El cañón de Sorreigs presenta tramos sumamente estrechos con saltos de agua temporales y marmitas de gigante excavadas en el cauce pétreo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90678','espacio','Montaña de Sant Ramon y marismas iniciales del Delta','Promontorio rocoso compuesto por calizas y esquistos del paleozoico que emerge de forma abrupta junto al inicio de la llanura deltaica. Sus laderas albergan matorrales mediterráneos densos que contrastan con los depósitos limosos de las zonas húmedas basales.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08202','espacio','Vertiente sur del Macizo del Montseny y cuenca del río Tordera','Espacio protegido de alta biodiversidad donde convergen materiales metamórficos (pizarras y esquistos) con terrazas fluviales. Sus laderas muestran pisos de vegetación perfectos, transitando desde encinares mediterráneos hasta castañares y hayedos húmedos montanos de excepcional plasticidad.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08204','espacio','Valle de la riera de San Climent y montaña de las Agujas','Paisaje de colinas quebradas compuesto por esquistos y calizas devonianas que configuran una topografía de crestas agudas y valles estrechos. La vegetación es densa, destacando la presencia de encinares litorales maduros sobre laderas de fuerte pendiente.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08205','espacio','Vertiente vallesana del Parc Natural de Collserola y Torrent de la Budellera','Macizo montañoso de relieve suave compuesto por series sedimentarias detríticas y pizarras metamorfizadas del Paleozoico. Presenta una de las masas forestales densas de encinar mixto con pino blanco mejor conservadas de la   comarca, atravesada por redes de torrentes umbríos de régimen estacional. Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08210','espacio','Riscos de Bertí y torrente de la Vall de San Feliu','Imponente muralla rocosa caliza dispuesta en graderíos horizontales sobre materiales paleozoicos más antiguos, formando escarpes tectónicos de gran altitud. El relieve estructural presenta abundantes cuevas de disolución, surgencias menores y vegetación rupícola especializada en las paredes verticales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08211','espacio','Vertientes de la Sierra de Collserola y riera de la Salud','Ladera occidental del macizo de Collserola, constituida por pizarras silúricas plegadas que forman un relieve de colinas abruptas cubiertas de pino blanco y encinar. El fondo de la riera alberga afloramientos calcáreos menores y surgencias de agua estacionales.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08212','espacio','Serrat de las Brujas y cuenca de la riera de Garame','Elevación tabular calcárea situada en el extremo occidental del Lluçanès que ofrece amplias panorámicas sobre relieves erosivos modelados en materiales sedimentarios del Terciario. El dosel forestal está dominado por encinares continentales y robles pubescentes.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90584','espacio','Sierra de la Conreria y Parque de la Cordillera de Marina','Relieve abrupto de la cordillera Litoral caracterizado por crestas graníticas erosionadas y valles umbríos con presencia de pequeños manantiales. Los bosques de encina y los jarales colonizan los suelos arenosos de sauló derivados de la disgregación de la roca madre.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08213','espacio','Meandros del río Llobregat y llanura aluvial del río d''Or','Amplio valle fluvial donde el Llobregat describe amplias curvas sobre materiales sedimentarios eocénicos, delimitado por terrazas cuaternarias escalonadas. El contraste estético está marcado por la lámina de agua y los cinturones de vegetación riparia.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08020','espacio','Serrat de la Sala y escarpes margosos de la Plana de Vic','Pequeña elevación testigo compuesta por margas eocénicas grises y restos fósiles de nummúlites que ha resistido la erosión general del valle del Ter. Presenta laderas cubiertas de pastizales secos y arbustos mediterráneos de carácter continental.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08193','espacio','Valle de la riera de San Iscle y macizo del Montnegre','Profunda hendidura en la Cordillera Litoral de geología plutónica (granitos), caracterizada por un microclima de alta humedad que permite la existencia de castañares, robledales y densos helechales. La riera arrastra arenas gruesas y cuarzos limpios entre bloques rocosos redondeados.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08216','espacio','Riscos de Tubau y fuentes de la riera de Merlès','Paisaje de alta montaña prepirenaica calcárea con un relieve estructural rugoso de crestas escarpadas y valles encajonados. Los bosques dominantes son densas masas de pino negro y hayedos eurosiberianos en las umbrías, complementados por fuentes cristalinas de aguas duras calcificantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90585','espacio','Curso del río Cardener y colinas de arenisca del Bages','Tramo fluvial medio donde el Cardener corta depósitos sedimentarios horizontales continentales, formando   pequeñas terrazas. El bosque de ribera está dominado por chopos y álamos, contrastando con el entorno árido de los cerros calcáreos testigos. Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08217','espacio','Llanura aluvial y meandros del bajo Llobregat','Zona de depósito deltaico moderno constituida por limos, arcillas y arenas de origen cuaternario transportadas por el Llobregat. Los taludes y el cauce conservan comunidades vegetales palustres adaptadas al régimen fluvial mediterráneo de avenidas periódicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08903','espacio','Riscos de la Clusa y vertientes septentrionales del Parc Natural Cadí-Moixeró','Entorno de alta montaña pirenaica caracterizado por espectaculares fallas y cabalgamientos calcáreos que configuran paredes verticales de gran magnitud. Aloja praderas alpinas de gran riqueza botánica y bosques densos de pino negro que colonizan los canchales calizos basales.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08221','espacio','Valle de San Just y lomas del Parque de Collserola','Vertiente meridional del macizo de Collserola constituida por materiales metamórficos paleozoicos (pizarras cambro-ordovícicas). Presenta barrancos estrechos con   encinares litorales mixtos muy bien estructurados y pequeños manantiales carbonatados de caudal estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08222','espacio','Cárcavas de la riera de Can Ganduxer y lomas calcáreas','Paisaje que muestra los efectos de la erosión hídrica acelerada sobre arcillas continentales miocénicas de la depresión del Penedès. El relieve se compone de surcos profundos y aristas afiladas desprovistas de vegetación arbórea, idóneas para contemplar la dinámica erosiva mediterránea.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90586','espacio','Riera de Gavarresa y desfiladero de la Blava','Incisión fluvial de régimen submediterráneo sobre areniscas continentales y formaciones margosas del Terciario. El cauce forma pequeños estrechos pétreos de gran interés geomorfológico rodeados por pinares de pino salgareño y pequeños robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08224','espacio','Riscos de o cingles de San Martí y laderas del río Congost','Formidables precipicios calcáreos horizontales que marcan el límite sudoccidental del macizo de Bertí sobre la fosa tectónica del Congost. Las paredes verticales muestran una estratigrafía perfecta del Triásico y sustentan vegetación rupícola muy especializada de gran interés.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08226','espacio','Desfiladero y salto de agua de la Fou de Tous','Espectacular cañón calcáreo angosto donde la riera de Tous ha erosionado la roca caliza eocénica formando cavidades y una cascada natural de gran altura. El microclima húmedo del desfiladero favorece la proliferación de musgos, hiedras y especies higrófilas singulares.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08227','espacio','Valle de la riera de Pontons y riscos de la Roca','Escarpe rocoso calcáreo que emerge con fuerza en medio de las ondulaciones prelitorales del Penedès. El desfiladero fluvial que lo acompaña muestra paredes erosionadas por la disolución kárstica y laderas cubiertas de maquia mediterránea densa.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08229','espacio','Sierra de Castelltallat y bosques continentales de pino laricio','Extensa cordillera caliza interior con una estructura anticlinal erosionada que ofrece valles escondidos y vertientes abruptas. Destaca botánicamente por albergar extensas masas continuas de pino salgareño y robledales que componen un paisaje forestal de gran naturalidad.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90587','espacio','Macizo de Garraf occidental y valles de la Riera de Ribes','Relieve kárstico costero dominado por la disolución de calizas cretácicas que generan campos de lapiaz, dolinas y simas ocultas. La vegetación es sumamente singular, destacando el palmito (única palmera autóctona europea) y el carrascal termófilo ralo sobre roca desnuda.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08233','espacio','Sierra de Bellmunt y hayedos de la umbría de Sa Regatosa','Espectacular relieve prepirenaico que marca la transición geomorfológica hacia el macizo de las Guilleries, con crestas calizas afiladas. En sus umbrías se desarrollan hayedos maduros excepcionales y bosques mixtos caducifolios que se asientan sobre suelos ricos en humus y limos de montaña.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08234','espacio','Vertiente meridional de la Calma y macizo del Montseny','Territorio de alta montaña que asciende de forma abrupta hacia el altiplano de la Calma, compuesto por pizarras e inyecciones de dioritas. Alberga una gradación climática y botánica que pasa de densos encinares a robledales y hayedos relictos de incalculable valor contemplativo.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08235','espacio','Acantilados graníticos de la punta de San Pol y riera de Gualba (desembocadura)','Pequeño promontorio rocoso de granito meteorizado que corta la línea de costa arenosa del Maresme. Constituye una singularidad geológica litoral debido a la interrupción de la playa por un escarpe expuesto directamente al oleaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08236','espacio','Riu de Bitlles, fuentes de las dehesas y cuevas de las dehesas (les Deus)','Extraordinario entorno fluvial calizo donde destaca el paraje de les Deus, caracterizado por abundantes fuentes y surgencias kársticas que brotan de una pared de toba calcárea viva. Presenta oquedades y pozas naturales de roca pulida.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08181','espacio','Bloques graníticos de la Cordillera Litoral y pinar de Can Planes','Paisaje granítico colinado que presenta abundantes formaciones de meteorización esferoidal,   conocidos localmente como bolos o rocas singulares. La vegetación se compone de un tapiz continuo de encinar litoral mixto con pino piñonero sobre arenas graníticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90582','espacio','Riera de Sorreigs y Garganta de Les Ganyes','Estrecho desfiladero fluvial donde la riera ha perforado las capas de areniscas duras del eoceno, creando badinas y pozas profundas. La umbría del cañón mantiene comunidades de flora centroeuropea y formaciones de helechos de gran interés botánico.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90884','espacio','Valle de Vallalta y vertientes del Macizo del Montnegre','Valle interior de origen tectónico encajado en materiales plutónicos graníticos del batolito litoral catalán. Las umbrías de la sierra presentan una densa cubierta de castañares, encinares maduros y alcornocales favorecidos por la alta humedad de condensación marina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08206','espacio','Llanura sedimentaria y cuencas endorreicas menores de l''Alt Penedès','Geomorfología caracterizada por depósitos cuaternarios arcillo-limosos que configuran un relieve llano de origen lacustre. Conserva ribazos con vegetación arbustiva mediterránea que rompen la homogeneidad del relieve calcáreo circundante.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08207','espacio','Riera de Reguissol y estribaciones del macizo del Montseny','Paisaje de piedemonte formado por grandes abanicos aluviales y depósitos detríticos que bajan de las cumbres metamórficas del Montseny. El área cuenta con magníficos bosques de ribera compuestos por alisos, fresnos   y robledales húmedos que flanquean los activos cursos de agua de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90583','espacio','Torrentes de Can Llopart y cárcavas arcillosas de l''Anoia','Territorio disecado por una densa red de torrentes estacionales que han excavado profundas cárcavas en los sedimentos miocénicos continentales. El paisaje muestra laderas inestables colonizadas por cañaverales, pinos y arbustos adaptados a la sequedad edáfica.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08220','espacio','Valle de Sant Llorenç y riera de las Set Fonts','Relieve de transición entre las margas de la Plana de Vic y las areniscas eocénicas de las Guilleries, caracterizado por sus abundantes surgencias de agua subterránea. El valle presenta pequeños saltos de agua y una cobertura densa de encinar montano con robles pubescentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08223','espacio','Valle de Horta, río Ripoll y monolitos de Sant Llorenç del Munt','Espectacular relieve de conglomerados deltaicos eocénicos modelados por erosión diferencial en forma de canales, agujas aisladas y espectaculares paredes verticales escalonadas. El nacimiento del río Ripoll labra un lecho de roca caliza con pozas profundas rodeado de densos encinares montanos rupícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90679','espacio','Cabecera de la Riera de Magarola y lomas arcillosas','Paisaje llano-ondulado de la alta meseta de la Segarra formado por depósitos continentales oligocénicos ricos en carbonatos. Conserva márgenes de torrente estacionales con vegetación arbustiva xerófila y retazos aislados de encinar continental.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90885','espacio','Nacimiento de la riera de Rajadell y altiplano calcáreo','Paisaje de transición de la Alta Segarra que muestra lomas tabulares calcáreas sometidas a un clima severo continental. Los cursos fluviales estacionales albergan pequeños humedales temporales rodeados de maleza esteparia y quejigos dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08169','espacio','Espacio Natural Protegido del Delta del Llobregat (Lagunas de la Ricarda y el Remolar)','Complejo sistema lagunar costero alimentado por aguas freáticas y aluviales, flanqueado por cordones dunares y pinares litorales de pino piñonero sobre arena pura. Es un paraje contemplativo excepcional donde el agua salobre se integra con la vegetación palustre en una llanura marina perfecta.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08019','espacio','Riscos de Collsacabra, Salto de Sallent y riera de Rupit','Impresionante relieve en cuesta con formidables escarpes calcáreos verticales que se desploman cientos de metros sobre el valle del Ter. El salto de agua de Sallent constituye una cascada espectacular de más de 100 metros de caída libre sobre el abismo geológico, rodeado de hayedos y robledales maduros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90579','espacio','Espacio Natural Protegido de la Sierra de EnsijaRasos de Peguera y fuentes del Llobregat','Imponente relieve prepirenaico caracterizado por crestas calcáreas calcadas y canchales de vertiente que contrastan con densas masas de pino negro. Alberga nacientes de agua pura de alta montaña y formaciones de modelado kárstico alpino de gran pureza visual.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08152','espacio','Gargantas de la Riera de Carme','Angosto desfiladero fluvial rodeado de masas forestales mixtas de pino y encina, donde el agua fluye de manera continua sobre lechos calcáreos calcificados. La surgencia de fuentes y pequeños saltos de agua genera un microclima de umbría muy singular.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08153','espacio','Macizo de Céllecs (Serralada de Marina)','Modelado granítico caracterizado por la presencia de grandes bloques de piedra meteorizada (bolos) y formaciones de tor que emergen entre espesos encinares prelitorales. El proceso de arenización del granito crea texturas edáficas y formas de relieve únicas en la comarca.   Barcelona).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90103','espacio','Desfiladero del río Homino y laderas de La Bureba','Estrecho pasadizo fluvial tallado sobre calizas del Cretácico que marca la transición geográfica hacia la cuenca sedimentaria. Las paredes de roca caliza albergan comunidades de encinar montano y matorrales espinosos calcícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90104','espacio','Páramo del Duero y cárcavas del río Riaza','Relieve tabular característico de la meseta castellana, donde la erosión ha desmantelado las arcillas y margas dejando vertientes escarpadas bajo el nivel del páramo calcáreo. Destaca la vegetación arbustiva adaptada al clima continental extremo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90105','espacio','Valle de Caderechas y cañón del río Vadillo','Impresionante anfiteatro calcáreo protegido por escarpadas laderas montañosas que crean un microclima húmedo único. Destacan los densos bosques de pino resinero, encinas y madroñales que colonizan los cantiles y los suelos kársticos de la comarca.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90106','espacio','Cerros testigo de la Bureba oriental','Formaciones geológicas cónicas aisladas que sobresalen de la llanura sedimentaria, originadas por erosión diferencial sobre yesos y margas. La vegetación es rala, compuesta por pastizales gipsícolas y matorrales esteparios de gran interés botánico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90107','espacio','Valle aluvial del río Ausines','Llanura de inundación madura con depósitos cuaternarios de gravas y arenas que configuran un relieve llano. Conserva pequeñas alisedas y choperas naturales que marcan el curso del agua sobre el sustrato arcilloso.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90108','espacio','Estribaciones de la Sierra de Oca','Zona de contacto entre la llanura de la Bureba y los primeros relieves paleozoicos, caracterizada por lomas cubiertas de encinar aclarado. El sustrato alternado de calizas y conglomerados genera perfiles topográficos suaves pero definidos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90109','espacio','El Desfiladero de los Hocinos y las Campas de Bricia','Espectacular relieve de la cordillera Cantábrica con grandiosos farallones calizos e imponentes cañones excavados por el agua. Alberga formaciones botánicas atlánticas excepcionales como hayedos húmedos, acebedas y tejos centenarios que crecen en las grietas de la roca.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09907','espacio','Páramo de Masa (vertiente meridional) y cañón del río Ubierna','Comienzo de la gran plataforma caliza del páramo, rota por la incisión fluvial del río Ubierna que expone perfiles rocosos calcáreos abruptos. La vegetación está integrada por tomillares, aliagares y comunidades rupícolas resistentes al viento.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90110','espacio','Monte Hijedo y riberas del embalse del Ebro','Alberga una de las masas forestales de roble albar (Quercus petraea) más extensas y puras del norte de España, asentada sobre un relieve de colinas de arenisca. El   paisaje vegetal destaca por su carácter atlántico relicto, con abundantes acebos, brezales densos y un sotobosque de musgo húmedo. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90111','espacio','Montes Obarenes (Pancorbo oriental)','Vertientes calcáreas abruptas integradas en el sistema montañoso de los Obarenes, con crestas afiladas resultantes de intensos empujes tectónicos. La vegetación cuenta con encinares de montaña y comunidades vegetales adaptadas a pedregales calizos (canchales).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90112','espacio','Desfiladero de Pancorbo y Montes Obarenes','Impresionantes farallones y agujas calizas modeladas por la erosión alpina en el sector occidental del municipio. Las paredes verticales del desfiladero albergan comunidades botánicas rupícolas de gran valor y encinares montanos adaptados a la roca desnuda.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90113','espacio','Terrazas del río Duero y llanura aluvial','Relieve horizontal propio de la cuenca sedimentaria del Duero, constituido por depósitos de arenas y limos cuaternarios. Conserva manchas relictas de vegetación mediterránea esclerófila e hidrofitos en los meandros abandonados del río.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09001','espacio','Confluencia de los ríos Bañuelos y Duero','Amplia llanura de inundación donde los aportes fluviales han creado un sistema de terrazas escalonadas sobre arcillas y yesos. Destacan los bosques de ribera bien desarrollados con especies como el álamo blanco, el sauce y el fresno.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90114','espacio','Cañón del río Arandilla y muelas calcáreas','Pequeño desfiladero excavado en calizas tabulares del Terciario, con paredes escarpadas y abrigos naturales de disolución kárstica. El entorno vegetal destaca por la transición entre el quejigal húmedo de fondo de valle y el encinar seco del páramo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90115','espacio','Sabinar de Arandilla y Sierra de la Demanda meridional','Extenso e impresionante bosque relicto de sabina albar (Juniperus thurifera) desarrollado sobre un relieve accidentado de calizas y dolomías. Las formaciones rocosas muestran un modelado kárstico inicial con lapiaces y pequeñas oquedades de gran valor contemplativo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09021','espacio','Vega del río Bañuelos y lomas forestales','Valle abierto flanqueado por relieves suaves de conglomerados y areniscas cubiertos por densas masas de pino resinero. El fondo de la vega presenta un humedal estacional con comunidades de juncos y pastizales húmedos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09022','espacio','Galacho del río Aranzuelo','Meandro encajado menor sobre materiales arcillo-arenosos que muestra una dinámica de erosión fluvial activa en los taludes exteriores. La vegetación está formada por choperas autóctonas y saucedas en buen estado de conservación.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31029','espacio','Balsa de Melgar / Río Odrón','Pequeña cubeta lagunar de origen tectónico rodeada de campos agrícolas, que sirve de oasis para la flora palustre. El relieve es de lomas suaves arcillosas donde el río Odrón define un estrecho corredor verde de sotos fluviales mediterráneos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09024','espacio','Riberas e islas del río Pisuerga','Tramo fluvial maduro caracterizado por la presencia de barras de grava e islas sedimentarias estables en el cauce. El ecosistema ripícola es denso, con alisedas y choperas que estabilizan las márgenes erosionables del río.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09025','espacio','Playas de interior y humedales del Embalse del Ebro','Singular paisaje costero lacustre dominado por extensas dunas de arena silícea fina generadas por la erosión eólica e hídrica en los márgenes del embalse. El entorno botánico cuenta con brezales húmedos atlánticos y comunidades de turbera de gran valor ecológico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09026','espacio','Desfiladero del río Arlanzón y vertientes de la Sierra de la Demanda','Cañón kárstico imponente labrado sobre calizas paleozoicas, rodeado de densos bosques de roble rebollo y hayas en las umbrías. Las cumbres del municipio marcan el inicio del relieve alpino con circos glaciares e ibones en las cotas más altas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09027','espacio','Montes de Oca y cabecera del río Oca','Relieve de media montaña forestal con valles angostos excavados en conglomerados y areniscas del Terciario. El paisaje visual está definido por densos quejigales y rebollares que cubren las laderas orientadas al norte.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09029','espacio','Trinchera y simas de la Sierra de Atapuerca','Anticlinal calizo aislado que destaca por su relieve colinado y un complejo sistema kárstico interior de cuevas y simas colmatadas. La vegetación del exterior es un encinar termófilo ralo adaptado a la escasez de suelo sobre la roca caliza.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09030','espacio','Cañón del río Papas y peñas calcáreas','Estrecho valle flanqueado por escarpes calizos horizontales que forman una morfología de graderío rocoso debido a la erosión diferencial. Las laderas umbrías albergan encinares montanos bien conservados y comunidades de musgos rupícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09032','espacio','Lomas del río Arlanza y cárcavas de arcilla','Paisaje erosionado de colinas bajas arcillosas que muestran incisión hídrica en forma de pequeños abarrancamientos. La vegetación se reduce a matorrales mediterráneos aclarados y tomillares xerófilos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09033','espacio','Ribera del río Esgueva y laderas del páramo','Valle disimétrico típico de la Alcarria burgalesa, donde las vertientes norte muestran escarpes calizos y las sur cuestas suaves de margas. Pequeñas alamedas y saucedas marcan el curso del riachuelo estacional.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09034','espacio','Cárcavas de San Miguel y llanuras calcáreas','Paisaje estepario definido por la erosión en cárcavas sobre laderas margosas bajo el nivel de los páramos calcáreos. Alberga comunidades vegetales gipsícolas adaptadas a suelos con alta concentración de sales y yesos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09035','espacio','Valle del río Bañuelos y monte de las encinas','Suave depresión erosiva rodeada de relieves tabulares calcáreos cubiertos por encinares centenarios de porte arbustivo. El fondo del valle está compuesto por sedimentos cuaternarios fértiles con vegetación de ribera dispersa.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09036','espacio','Nacimiento de la Riera de Bañuelos','Pequeña surgencia estacional al pie de las muelas de la Bureba, en un entorno de materiales blandos arcillosos. La vegetación es principalmente herbácea y de matorral espinoso mediterráneo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09037','espacio','Valle del río Pedroso y San Millán (Sierra de la Demanda)','Espectacular entorno de alta montaña paleozoica con modelado glaciar y periglaciar en las cumbres calcáreas y esquistosas. Cuenta con imponentes bosques mixtos de hayas, acebedas maduras y robledales que cubren valles de aguas cristalinas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09038','espacio','Gargantas del río Pedroso y vegas del Arlanza','Punto de confluencia fluvial donde el río Pedroso abre un cañón menor antes de unirse al Arlanza sobre calizas del Cretácico. Destacan las formaciones de   grandes bloques de piedra y los bosques galería de alisos y fresnos de gran porte. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09039','espacio','Cabecera del río Pedroso y Montes de Umbría','Valle de montaña cerrado caracterizado por un relieve abrupto de pizarras y cuarcitas con pendientes pronunciadas. El paisaje vegetal es dominado por un hayedo atlántico denso que tapiza las zonas umbrías de la cuenca alta.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09041','espacio','Torrente de la Vega','Cauce intermitente menor asentado sobre depósitos aluviales de la cuenca sedimentaria del Arlanzón. La vegetación natural es residual, compuesta por espinares y pastizales estacionales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09043','espacio','Humedal de Cornudilla y río Oca','Zona llana de la cuenca de la Bureba donde la proximidad del nivel freático genera pequeñas lagunas estacionales y charcas de aguas someras. El entorno cuenta con carrizales densos y saucedas adaptadas al encharcamiento prolongado.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09044','espacio','Nacimiento del río Cueva y Montes de Oca','Zona de recarga kárstica en el contacto entre las calizas de la sierra y los materiales arcillosos de la cuenca. Destaca la surgencia del río Cueva y los quejigales dispersos que colonizan el relieve ondulado.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09045','espacio','Sumidero del río Hurón y Cueva del Agua','Uno de los fenómenos kársticos más espectaculares de la península, donde el río Hurón desaparece por completo bajo un imponente farallón rocoso calizo. El entorno de las Loras presenta un relieve de parameras desoladas que contrasta con el cañón verde excavado por el río subterráneo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09051','espacio','Meandros del río Riaza y confluencia con el Duero','Llanura aluvial baja caracterizada por una dinámica de sedimentación activa que genera islas de grava y barras arenosas. Alberga alamedas densas y comunidades de eneas y carrizos en las orillas inundables.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09050','espacio','Monumento Natural del Monte Santiago y Salto del Nervión','Impresionante corte geológico vertical de más de 200 metros de altura sobre el cañón de Delika, por donde se precipita de forma intermitente el río Nervión. El paisaje está dominado por un hayedo puro de dimensiones kilométricas asentado sobre un karst activo repleto de lapiaces y dolinas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09052','espacio','Lomas del río Matapozas','Relieve ondulado sobre yesos y margas de la cuenca sedimentaria septentrional con procesos de erosión laminar. Presenta formaciones de matorral gipsícola y tomillares resistentes a la sequedad edáfica.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90515','espacio','Desfiladero del río Oca y Montes Obarenes','Estrechamiento fluvial encajado entre riscos calizos verticales del Jurásico con una fracturación tectónica muy visible. El cañón alberga encinares termófilos en las paredes orientadas al sur y pequeños retazos de bosque atlántico en el fondo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09002','espacio','Estrecho de la Brújula y gargantas del río Oca','Zona de transición geomorfológica que comunica la cuenca del Ebro con la del Duero a través de un corredor erosionado entre relieves calizos. Cuenta con formaciones forestales mixtas de encina y quejigo en las laderas expuestas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09057','espacio','Desfiladero de Pancorbo (vertiente norte) y curso del río Oroncillo','Escarpes rocosos calizos de perfiles afilados integrados en el espacio protegido de los Montes Obarenes. La humedad del norte favorece la presencia de quejigales densos y una rica flora de sotobosque con bojes y acebos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09058','espacio','Confluencia del río Arlanzón y el río Ubierna','Llanura aluvial amplia con depósitos de gravas y limos fluviales acumulados en el cuaternario. Muestra saucedas fragmentadas y comunidades macrofíticas adaptadas a corrientes lentas de agua.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','espacio','Humedales de Fuentes Blancas y curso del Arlanzón','Tramo fluvial periurbano estabilizado con amplias llanuras de inundación y depósitos arenosos. Conserva una densa masa forestal de ribera con alisos, fresnos y álamos negros de crecimiento espontáneo que protegen el cauce.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09060','espacio','Riscos de la Sierra de Frías y Obarenes occidentales','Crestones calizos verticales que marcan el límite septentrional de la llanura de la Bureba, originando un relieve abrupto de gran valor paisajístico. Alberga bosques mixtos de encina y madroño favorecidos por la insolación de los cantiles rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09061','espacio','Vaguada del río Esgueva y muelas de arcilla','Relieve de campiña ondulada modelado sobre margas y arcillas del neógeno, caracterizado por laderas de suave pendiente. En los márgenes del cauce intermitente se desarrollan pequeñas choperas autóctonas y saucedas arbustivas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09062','espacio','Manantial de aguas ferruginosas y peñas calcáreas de la Demanda','Entorno geomorfológico singular definido por afloramientos de calizas tubulares y arcillas que propician la surgencia de fuentes ricas en óxidos de hierro. Las laderas están cubiertas por densas masas de melojo y pinos silvestres adaptados a la altitud montana.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09004','espacio','Desfiladero del río Gromejón y Peña San Jorge','Relieve kárstico dominado por un farallón calizo aislado que emerge sobre la llanura y un modesto cañón fluvial excavado por la erosión hídrica. La vegetación del entorno está configurada por formaciones de sabina albar, tomillares y caméfitos calcícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09065','espacio','Páramos del arroyo de la Vega','Superficie estructural plana típica de la submeseta norte asentada sobre calizas miocénicas con procesos de deflación eólica. Alberga comunidades de tomillar-alicatado y pastizales secos continentales resistentes a la oscilación térmica estacional.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09066','espacio','Sabinar del Arlanza y peñas de Carazo','Zona de media montaña caliza caracterizada por escarpes asimétricos y lapiaces generados por procesos de disolución química. El interés botánico radica en sus formaciones abiertas de sabina albar y encinar montano que colonizan el sustrato rocoso desnudo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09067','espacio','Pino-Roble de Canicosa y paraje de Revenga','Extraordinaria masa forestal húmeda en las faldas de la Sierra de Urbión, famosa por el ejemplar botánico simbiótico donde un pino silvestre crece dentro de un roble melojo centenario. El relieve es montañoso y silíceo, con afloramientos de areniscas y abundantes turberas de montaña.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09068','espacio','Valle de Caderechas y desfiladero del río Oca','Paisaje geomorfológico protegido por grandes murallones de roca caliza que mitigan los vientos fríos del norte, originando un microclima de gran benignidad. Las laderas umbrías presentan densas masas de pino resinero, quejigos y un sotobosque de madroños y bojes.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09070','espacio','Peña de Carazo y escarpes del sondeo de la Sierra de las Mestas','Imponente muela caliza de paredes verticales y perfil tabular que se eleva de manera abrupta sobre el fondo del valle del Arlanza. El paraje destaca por su geomorfología de crestón calizo y la presencia de vegetación rupícola especializada en las grietas de los cantiles.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09071','espacio','Valle del río Homino y lomas de la Bureba occidental','Relieve ondulado sobre materiales blandos de tipo arcillo-yesífero que genera una suave topografía de colinas y pequeñas vaguadas. Cuenta con retazos de encinar mediterráneo y pastizales de carácter estepario.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09072','espacio','Modino y parameras del Arlanzón','Llanura elevada estructural constituida por depósitos detríticos y calizas lacustres del Terciario superior. Presenta una vegetación xerófila dominada por tomillos, aliagas y pequeñas encinas de porte arbustivo adaptadas al viento.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09073','espacio','Vallejo del arroyo de la Cardeña','Depresión erosiva menor labrada sobre arcillas miocénicas de la cuenca central burgalesa. El fondo del vallejo acoge comunidades vegetales hidrófilas estacionales y sauces de porte arbustivo alineados con el nivel freático.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09074','espacio','Meandros del río Arlanzón y lomas de la Cartuja','Llanura aluvial baja conformada por terrazas de gravas y limos cuaternarios depositados por la dinámica fluvial. Conserva franjas de bosque galería con álamos blancos y negros que estabilizan los taludes sedimentarios.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09075','espacio','Vertiente de la Sierra de Atapuerca y arroyo de Riopico','Suaves estribaciones calizas que enlazan la masa de Atapuerca con la depresión del Arlanzón sobre un sustrato de calizas bioclásticas. La vegetación predominante está compuesta por pastizales vivaces calcícolas y matorral bajo mediterráneo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09076','espacio','Desfiladero de Carrias y Montes Obarenes','Angosto cañón kárstico abierto por la acción erosiva lineal sobre potentes bancos de calizas del Cretácico superior. Sus escarpadas laderas albergan encinares montanos bien adaptados a la escasez de suelo y comunidades botánicas rupícolas de umbría.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09077','espacio','Riscos de la Sierra de Oña','Relieve montañoso caracterizado por crestones de caliza masiva que limitan geográficamente la fosa de la Bureba. Las laderas presentan una interesante mezcla botánica de encinas, quejigos y bojes que colonizan los canchales y pedrizas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09078','espacio','Cañón del río Arlanza y peñas de Cascajares','Estrechamiento fluvial flanqueado por altos paredones calcáreos que muestran marcas de disolución y pequeñas oquedades kársticas. La vegetación destaca por un denso sabinar de sabina albar y encinas que trepan por las laderas pedregosas del término.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09079','espacio','Vertiente del río Odra y cerros de Castro','Paisaje liso e interfluvial sobre materiales arcillosos y limosos de la cuenca sedimentaria del Pisuerga. Alberga pequeñas formaciones de matorral espinoso mediterráneo y comunidades herbáceas adaptadas a inviernos prolongados.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09083','espacio','Desfiladero del río Oca (tramo medio)','Incisión fluvial de pendientes moderadas abierta sobre conglomerados y calizas marginales de la Bureba. El cauce está acompañado por una banda continua de vegetación de ribera, flanqueada por laderas cubiertas de encinar aclarado.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09082','espacio','Valle del río Tirón y llanura riojana-burgalesa','Espacio de transición sedimentaria con depósitos aluviales y terrazas bien formadas por el arrastre del río Tirón. Presenta choperas autóctonas y comunidades macrofíticas ligadas a suelos con humedad edáfica permanente.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09084','espacio','Yacimientos de árboles fósiles y canteras de arenisca','Singular relieve de la comarca de Pinares donde la erosión ha expuesto estratos de areniscas del Cretácico que albergan troncos de árboles silicificados de gran valor geológico. El entorno forestal está dominado por densos bosques mixtos de pino silvestre y roble rebollo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09085','espacio','Meandros del río Duero y llanura aluvial','Amplia terraza fluvial cuaternaria modelada por la dinámica sedimentaria del Duero sobre arcillas del Neógeno. Conserva comunidades de sauces y álamos negros adaptadas a la oscilación estacional del nivel freático.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09088','espacio','Cárcavas del Pisuerga y escarpes margosos','Paisaje fluvial encajado donde la erosión hídrica lineal ha esculpido laderas de margas y calizas del Cretácico. La vegetación está formada por matorral mediterráneo ralo y retazos de vegetación ripícola basal.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09086','espacio','Cañón del río Arlanzón y encinar de San Pedro de Cardeña','Relieve ondulado labrado sobre terrazas de cantos rodados y calizas lacustres. El paisaje destaca por sus densas masas de encinar termófilo adaptado a suelos pedregosos y secos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09090','espacio','Lomas del río Odra y cerros testigo','Relieve de campiña ondulada sobre arcillas miocénicas con procesos de erosión laminar y formas cónicas aisladas. Alberga matorrales xerófilos y pastizales estacionales continentales de carácter estepario.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09091','espacio','Cerro testigo de Castrojeriz y valles del Odra','Espectacular ejemplo geomorfológico de cerro testigo con cumbre tabular caliza que emerge abruptamente sobre las llanuras arcillosas circundantes. Las vertientes descarnadas muestran una interesante zonación botánica con tomillares gipsícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09063','espacio','Vegas del río Arlanzón','Llanura de inundación madura constituida por sedimentos finos, limos y gravas cuaternarias. Presenta sotos fluviales fragmentados donde predomina el sauce arbustivo y el carrizal en zonas encharcadas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09093','espacio','Vallejo del río Ausines','Depresión aluvial menor de topografía llana asentada sobre materiales detríticos de la cuenca   sedimentaria central. Conserva pequeñas alamedas y espinares mediterráneos dispersos en sus márgenes. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09094','espacio','Sabinar de Tejada y muelas calizas','Paisaje de paramera calcárea que alberga una mancha relicta de sabina albar (Juniperus thurifera) de gran valor botánico. El suelo rocoso presenta campos de lapiaces incipientes y formas de disolución kárstica menor.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09095','espacio','Cerros del río Arlanzón','Lomas de erosión suave compuestas por margas y arcillas compactas que delimitan el valle fluvial. Muestra pastizales basófilos y matorral ralo adaptado a la marcada continentalidad climática.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09098','espacio','Cárcavas de San Lorenzo y cañón del Tirón','Impresionantes perfiles escarpados y badlands formados sobre materiales arcillosos y yesíferos rojizos por la acción torrencial del agua. El río Tirón corta estas formaciones generando un fuerte contraste geomorfológico y visual.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09100','espacio','Vertientes de la Sierra de Oca y rebollares','Relieve de transición montañosa con valles secos y colinas de conglomerados terciarios. Cuenta con notables masas forestales de roble rebollo (Quercus pyrenaica) que colonizan los suelos silíceos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09101','espacio','Campiña del río Cogollos','Llanura sedimentaria uniforme interrumpida únicamente por pequeños surcos erosivos estacionales. La vegetación natural es escasa, dominada por comunidades herbáceas y tomillares muy aclarados.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09102','espacio','Desfiladero de la Horadada y Parque Natural de Montes Obarenes-San Zadornil','Colosal cañón kárstico donde el río Ebro corta de forma transversal las estructuras calizas de los Montes Obarenes, creando paredes verticales de cientos de metros. El entorno es un paraíso botánico de transición con hayedos, encinares y madroñales rupícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09103','espacio','Valle del río Esgueva y lomas margosas','Relieve disimétrico de vertientes calcáreas y fondos de valle arcillosos labrados por la erosión fluvial. Las cuestas albergan tomillares y aliagares mediterráneos adaptados a la escasez de humedad.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09104','espacio','Cabecera del río Henar y páramo calcáreo','Altiplano estructural dominado por calizas miocénicas duras donde se inician pequeños valles encajados. La vegetación está integrada por encinas arbustivas y pastizales xerófilos de montaña media.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09105','espacio','Desfiladero de la Yecla (límite oriental) y Sabinar del Arlanza','Entorno calizo abrupto caracterizado por profundas entalladuras rocosas y formas kársticas espectaculares de erosión vertical. Alberga un bosque puro de   sabina albar que se asienta directamente sobre los escarpes dolomíticos. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09108','espacio','Páramo de Cogollos','Plataforma tabular caliza elevada expuesta a una intensa deflación eólica y variaciones térmicas extremas. La vegetación está especializada, compuesta por caméfitos calcícolas y tomillares adaptados al viento costoso.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09109','espacio','Desfiladero del río Ayuda y Obas de Treviño','Magnífico cañón fluvial excavado en calizas y areniscas terciarias con paredes verticales cubiertas de densa vegetación atlántica. El paisaje vegetal destaca por sus bosques mixtos de quejigo, haya y arces que tapizan el fondo umbrío del valle.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','espacio','Cañón del río Arlanza y Sabinar de las Yeclas','Majestuoso desfiladero tallado sobre calizas cretácicas con escarpes verticales, cornisas de erosión diferencial y cuevas kársticas. Los cortados rocosos y las laderas albergan una comunidad botánica excepcional de sabinas centenarias y encinares de montaña.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09114','espacio','Canteras de caliza y paramera','Superficie estructural de calizas masivas del Neógeno modificada por frentes de corte antiguos que exponen la roca desnuda. Muestra una vegetación de matorral bajo mediterráneo y pastizales basófilos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09115','espacio','Estribaciones de los Montes Obarenes y río Oroncillo','Zona de contacto tectónico entre la fosa sedimentaria y el arco calizo montañoso. Presenta lomas suaves cubiertas de encinar aclarado y matorral espinoso que retienen los suelos arcillo-limosos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09119','espacio','Peña de San Clemente y Sabinar del Arlanza','Escarpe calizo aislado que destaca morfológicamente sobre los materiales detríticos del entorno, mostrando pequeñas oquedades y abrigos de disolución. Alberga ejemplares notables de sabina albar y encinas rupícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09120','espacio','Desfiladero de Obarenes y Riscos de San Justo','Abruptas agujas y crestones calizos de origen alpino que configuran un relieve vertical e inaccesible de gran potencia visual. La influencia climática del norte permite el desarrollo de comunidades de boj y encinares montanos atlánticos en las umbrías.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09122','espacio','Anfiteatro kárstico y Sabinar de Espinosa','Depresión circular de origen kárstico flanqueada por estratos calizos escalonados de gran singularidad   morfológica. La masa forestal está dominada por sabinas albares asociadas con encinas y matorrales aromáticos calcícolas. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09006','espacio','Monumento Natural de Ojo Guareña (sector norte) y Puertos de Lunada y Estacas de Trueba','Impresionante relieve alpino de la cordillera Cantábrica con valles glaciares en forma de "U", circos rocosos colosales y laderas de pastizal subalpino. Destacan sus hayedos puros e infinitos, acebedas maduras y los sistemas kársticos subterráneos que horadan las montañas calizas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09123','espacio','Lomas del río Tirón y Montes de Oca orientales','Relieve suavemente ondulado sobre arcillas y areniscas rojizas que marcan el piedemonte de la sierra. Conserva pequeños rodales de quejigo y matorral de degradación mediterránea.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09125','espacio','Confluencia de los ríos Arlanzón y Hormazuela','Extensa llanura de inundación fluvial con terrazas escalonadas bien definidas constituidas por cantos rodados, arenas y limos. Alberga alamedas, choperas autóctonas y saucedas que tapizan el cauce trenzado del río.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09127','espacio','Sabinar del Arlanza (sector occidental) y lomas calizas','Relieve de muelas y valles secos modelado sobre calizas jurásicas donde el agua penetra rápidamente en el subsuelo. Destaca por sus formaciones abiertas de sabina albar y encina que soportan una gran aridez edáfica.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','espacio','Muela de Frías y cañón del río Ebro','Espectacular peñasco calizo de paredes totalmente verticales que emerge de manera aislada junto al amplio cauce del río Ebro. La dinámica fluvial ha creado en este punto meandros encajados y escarpes rocosos colonizados por densos bosques de ribera e higrófilos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09135','espacio','Manantiales de Fuentebureba y laderas de la Sierra de Frías','Zona de surgencias hídricas al pie de los relieves calizos calcáreos que drenan hacia la fosa arcillosa de la Bureba. Muestra matorrales espinosos y pastizales basófilos bien adaptados a la humedad estacional de las fuentes.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09136','espacio','Valle del río Riaza y cárcavas arcillosas','Vertientes de fuerte pendiente erosionadas por abarrancamientos torrenciales sobre arcillas finas de la cuenca del Duero. En las márgenes del río se desarrollan franjas estables de saucedas y alamedas maduras.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09137','espacio','Páramos del arroyo de la Nava y encinar de Fuentelcésped','Relieve tabular elevado caracterizado por suelos esqueléticos calcáreos que sustentan un encinar mediterráneo continentalizado. La erosión ha tallado pequeños valles ciegos en los bordes de la plataforma caliza.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09138','espacio','Cuestas calcáreas del Duero','Pendientes estructuradas en graderíos debido a la alternancia de estratos duros de caliza y blandos de margas. Acoge comunidades vegetales de tomillar y aliagar adaptadas a una fuerte insolación y escasez de agua.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09139','espacio','Valles secos de la cuenca del Riaza','Morfología de pequeños valles sin corriente de agua superficial permanente, modelados por procesos de disolución y arroyada difusa. La vegetación predominante está compuesta por pastizales mediterráneos y matorrales xerófilos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09140','espacio','Peña de Fuentenebro y minas de cuarzo natural','Relieve abrupto de lomas escarpadas donde afloran filones de cuarzo y arcillas especiales con llamativos contrastes cromáticos y texturas. Alberga una vegetación singular con encinares montanos y matorrales silicícolas raros en la provincia.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09141','espacio','Humedal del arroyo de la Vega y lomas arcillosas','Pequeña depresión topográfica donde se acumulan aguas someras estacionales originando un entorno de carrizal y juncales. Los relieves circundantes son colinas bajas de sedimentos terciarios finos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09143','espacio','Desfiladero del río Oca (cabecera) y lomas de la Bureba','Encajamiento inicial del río sobre calizas margosas que genera un relieve de laderas escarpadas de perfil convexo. La vegetación forestal cuenta con encinares mediterráneos mezclados con matorral espinoso.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09148','espacio','Cuenca del río Odra y vegas arcillosas','Paisaje liso de campiña sedimentaria constituido por depósitos de arcillas y limos del Mioceno. El río Odra aporta una estrecha franja de sauces y carrizales que rompe la monotonía del relieve horizontal.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09149','espacio','Desfiladero del río Oca y cárcavas de la Bureba','Tramo de incisión fluvial moderada flanqueado por taludes escarpados de materiales blandos erosionados en forma de pequeños badlands. Alberga comunidades vegetales de carácter estepario y tomillares gipsícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09151','espacio','Ribera del río Gromejón y pinares de Gumiel','Relieve suavemente ondulado interrumpido por la llanura aluvial del río Gromejón, asentada sobre arenas y arcillas. Destacan las extensas masas forestales de pino resinero (Pinus pinaster) que fijan los suelos arenosos del término.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09152','espacio','Cerros de San Lorenzo y vegas del Duero','Elevaciones cónicas aisladas constituidas por alternancia de calizas y margas erosionadas que vigilan la cuenca aluvial del Duero. Las vertientes conservan encinares de porte bajo y matorral mediterráneo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09154','espacio','Árboles fósiles de Hacinas y peñas silicícolas de la Demanda','Formidables afloramientos de areniscas del Cretácico inferior que custodian in situ troncos de árboles petrificados hace millones de años con sus estructuras celulares visibles. El relieve circundante es de colinas arenosas cubiertas por melojares y pinares mixtos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09155','espacio','Risco de Haza y desfiladero del río Riaza','Impresionante muela caliza con un frente rocoso vertical rectilíneo que domina visualmente toda la vega del río Duero. Al pie del escarpe calcáreo se disponen densas masas de quejigo y encina adaptadas a las pendientes pedregosas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09159','espacio','Vallejo del arroyo de los Garbanjos y fuentes de Hontanas','Valle kárstico estrecho excavado de forma natural en el páramo calizo, caracterizado por la abundancia de manantiales y surgencias de agua límpida. La vegetación combina pastizales húmedos de fondo de valle con tomillares en las parameras altas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09160','espacio','Cañón del río Riaza (tramo inferior)','Pequeña hoz fluvial tallada sobre calizas horizontales del Terciario superior, mostrando cornisas   calcáreas salientes. Alberga bosques galería bien estructurados con presencia de alisos, fresnos y densas saucedas. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09162','espacio','Canteras kársticas históricas y paramera de Hontoria','Paisaje modificado por la extracción milenaria de piedra caliza que ha dejado expuestas grandes paredes de roca blanca y cavidades de disolución natural. La vegetación dominante está constituida por tomillares, encinas bajas y aliagares calcícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09164','espacio','Valle del río Arandilla y lomas forestales','Suave sinclinal relleno de sedimentos fluviales terciarios flanqueado por relieves calizos bajos. Cuenta con masas boscosas mixtas de sabina albar y pino resinero que tapizan los terrenos escarpados.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09163','espacio','Parque Natural del Cañón del Río Lobos (nacimiento)','Espectacular inicio del cañón kárstico con formaciones rocosas colosales, simas, cuevas y farallones calizos esculpidos por la erosión lineal del río Lobos. El entorno botánico es excepcional, destacando un imponente bosque de pino laricio o salgareño (Pinus nigra) y sabinas albares sobre roca viva.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09166','espacio','Valles de los arroyos Hormazuela y San Juan','Paisaje de la plataforma de los páramos occidentales disecado por una red de valles paralelos de fondo plano y laderas suaves arcillosas. Presenta pequeñas manchas de encinar y comunidades arbustivas mediterráneas continentales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09167','espacio','Valle del río Hormazuela y paramera caliza','Depresión erosiva de perfil transversal en "V" abierta en el Páramo de Masa, con abundantes cantos calizos sueltos en las vertientes. Acoge pastizales secos basófilos y matorrales espinosos resistentes al viento.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09176','espacio','Valle del río Morquillas y lomas arcillosas','Suave relieve de campiña sobre arcillas y limos cuaternarios en las cercanías de la capital burgalesa. El curso de agua sostiene una modesta banda de sauces arbustivos y carrizales estacionales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09177','espacio','Sierra de Atapuerca (vertiente sur) y riberas del río Arlanzón','Territorio kárstico complejo caracterizado por colinas calcáreas que albergan conductos subterráneos colmatados de sedimentos de un valor geológico extraordinario. En las zonas llanas el río Arlanzón despliega un bosque de ribera maduro con alisos y chopos centenarios.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09178','espacio','Valle del río Tirón y lomas de la Riojilla','Relieve suave de colinas arcillosas de coloración rojiza típicas de la cuenca sedimentaria del Tirón. Conserva comunidades vegetales hidrófilas en los márgenes de los arroyos intermitentes.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09179','espacio','Lomas del río Arlanza y campiña arcillosa','Paisaje de topografía casi llana interrumpido por suaves vaguadas labradas sobre margas miocénicas. La vegetación natural consiste en tomillares y pastizales estacionales de carácter continental extremo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09180','espacio','Valle del río Hormazuela y escarpes calizos','Incisión fluvial menor en el sector occidental de la provincia, mostrando laderas con afloramientos de caliza lacustre. Alberga pequeñas masas de encinar aclarado y matorral mediterráneo esclerófilo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09181','espacio','Valle del río Hormazuela y riberas de Isar','Depresión aluvial madura encajonada entre los páramos occidentales, con terrazas de gravas bien conservadas. El ecosistema ripícola cuenta con saucedas puras y alamedas que siguen el curso del agua.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09182','espacio','Riberas e islas del río Pisuerga (límite palentino)','Tramo fluvial de gran anchura caracterizado por una activa dinámica sedimentaria que genera barras de grava y brazos muertos de agua. El bosque galería está bien constituido por chopos, alisos y sauces de gran porte.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09183','espacio','Vertientes del San Millán y dehesa de robles de Jaramillo','Relieve de media montaña paleozoica perteneciente a la Sierra de la Demanda, con laderas de areniscas y pizarras de pendientes acusadas. Alberga una magnífica dehesa boyal de roble rebollo con árboles monumentales y un sotobosque de brezales atlánticos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09184','espacio','Cañón del río Arlanza y monte de encinas','Estrechamiento fluvial flanqueado por cantiles de calizas cretácicas con formas de erosión alveolar y abrigos rocosos. La vegetación está compuesta por un encinar montano muy denso y manchas dispersas de sabina albar.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09189','espacio','Valles de Traslaloma y hayedos de la Merindad de Cuesta Urria','Paisaje montañoso atlántico modelado sobre calizas e intensamente fracturado por la tectónica alpina. Cuenta con imponentes bosques de haya (Fagus sylvatica) en las laderas de umbría, acebedas y brezales húmedos de gran riqueza botánica.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09190','espacio','Monumento Natural del Monte Santiago (sector occidental) y Sierra de Sálvada','Espectacular murallón calizo de caída vertical absoluta de más de 300 metros que forma el límite tectónico de la meseta con el valle de Arrastaria. La paramera superior caliza presenta un extraordinario karst con dolinas, sumideros y un hayedo denso milenario.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09191','espacio','Peñas de Lara y relieve de las Mestas','Impresionantes crestones calizos alineados de origen tectónico que emergen de forma abrupta en el paisaje con paredes verticales y agujas rocosas. La vegetación destaca por encinares montanos rupícolas y sabinas albares aclimatadas a los canchales pedregosos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09192','espacio','Parque Natural de Montes Obarenes-San Zadornil (bosques de San Zadornil)','Considerada la "Metrópoli Verde" de Burgos por su excepcional diversidad forestal donde confluyen de forma pura el hayedo, el castañar centenario, el pinar silvestre y el encinar mediterráneo. El relieve es un laberinto kárstico de callejones de piedra, sumideros y lapiaces gigantescos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','espacio','Vegas del río Arlanza y encinar de Lerma','Amplia vega aluvial cuaternaria donde el Arlanza deposita gravas y arenas gruesas configurando terrazas estables. Cuenta con notables masas de encinar mediterráneo de llanura y alamedas bien estructuradas en los márgenes fluviales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09195','espacio','Llanura sedimentaria del río Oca','Relieve completamente llano constituido por la acumulación de sedimentos arcillo-limosos finos de la cuenca de la Bureba. Conserva pequeñas formaciones de matorral mediterráneo esclerófilo adaptado a la continentalidad.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09196','espacio','Monte de las Sabinas y lomas del Arlanza','Relieve colinado sobre calizas margosas terciarias que sirve de transición al valle del Arlanza. Alberga formaciones abiertas de sabina albar asociadas con encinares y tomillares gipsícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09197','espacio','Arroyo de la Vega y páramo de Madrigalejo','Plataforma caliza miocénica incidida por pequeños valles de régimen torrencial estacional. La   vegetación está dominada por caméfitos basófilos, tomillares y pequeñas encinas de porte achaparrado. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09198','espacio','Campiña arcillosa del bajo Arlanza','Paisaje geomorfológico horizontal propio de la submeseta norte, compuesto por arcillas y yesos sedimentarios del terciario. Presenta una vegetación rala de pastizales estanos e ibéricos y tomillares degradados.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09200','espacio','Yacimiento paleozoico de las peñas de Lara y encinares montanos','Crestones de caliza cretácica levantados por la tectónica alpina que forman una silueta escarpada asimétrica de gran valor contemplativo. En las bases pedregosas de los riscos se desarrollan sabinares y encinares densos bien conservados.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09199','espacio','Cuestas del río Duero y lomas margosas','Laderas de pendiente pronunciada que descienden desde el páramo calcáreo hacia la vega aluvial del Duero, mostrando procesos de erosión laminar. Alberga matorrales mediterráneos xerófilos y tomillares basófilos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09202','espacio','Vallejo del río Brullés y lomas calizas','Pequeña incisión fluvial en las calizas de los páramos occidentales burgaleses, con laderas calcáreas desnudas. Acoge pastizales secos de montaña media y tomillares resistentes a heladas prolongadas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09206','espacio','Campiña del río Hormazuela','Topografía de llanura sedimentaria uniforme con depósitos cuaternarios finos de origen aluvial y coluvial. Presenta comunidades herbáceas estacionales y pequeños espinares mediterráneos dispersos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09208','espacio','Sabinar del Arlanza (sector norte) y lomas arcilloarenosas','Zona de contacto geológico entre las arcillas rojizas de la cuenca y las calizas de la sierra, que propicia una variada respuesta botánica. Destacan sus sabinas albares centenarias asociadas con encinas y matorrales silicícolas de gran interés.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09009','espacio','Riberas del río Nela y salinas de Medina','Amplia fosa tectónica sedimentaria rodeada de relieves calizos donde confluyen los ríos Nela y Trueba, depositando ricas terrazas aluviales. Presenta notables afloramientos evaporíticos de yesos y un denso bosque galería con chopos, sauces y fresnos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09211','espacio','Riberas e islas del río Pisuerga y Canal de Castilla (entorno natural)','Gran llanura aluvial fluvial con una activa dinámica de barras de grava e islas sedimentarias estables pobladas por densas alisedas. La presencia de agua permanente favorece un microclima húmedo que contrasta con la aridez de la meseta circundante.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09213','espacio','Sierra de la Tesla y desfiladero de la Horadada (sector norte)','Colosal murallón calizo de la Sierra de la Tesla que se eleva de manera imponente con estratos casi verticales de gran interés estructural y visual. Las umbrías de la sierra están cubiertas por hayedos puros magníficos, tejos y densos quejigales atlánticos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09214','espacio','Kársticos de la Peña de la Complacera y riberas del río Trueba','Paisaje montañoso de la Cordillera Cantábrica caracterizado por impresionantes lapiaces exokársticos y dolinas de disolución sobre calizas cretácicas. Las laderas umbrías exhiben densos hayedos húmedos y prados calcícolas atlánticos de gran valor botánico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09906','espacio','Desfiladero de Peñahorada y cañón del río Ubierna','Espectacular tajo fluvial de paredes calizas verticales y formas caprichosas esculpidas por la erosión kárstica en el Páramo de Masa. El microclima del cañón   permite la convivencia de encinares mediterráneos en las solanas con quejigales y bojedales en las umbrías. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09216','espacio','Monumento Natural de Ojo Guareña y Túnel de la Engaña','Uno de los complejos kársticos de cuevas y galerías subterráneas más grandes de Europa, donde el río Guareña se sumerge de forma monumental en la roca calcárea. En la superficie dominan valles ciegos, sumideros y una transición botánica exuberante de hayedos y robledales atlánticos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09217','espacio','Desfiladero de los Hocinos y hoces del río Ebro','Imponente cañón excavado por el Ebro que corta transversalmente las estructuras calizas de la Cordillera Prelitoral Cantábrica, generando paredones de más de un centenar de metros de caída vertical. Acoge masas forestales vírgenes de tejos relictos, encinas, madroños y acebos de extraordinaria densidad.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09218','espacio','Hoz del río Riaza (tramo bajo)','Valle encajonado de perfil asimétrico donde el río corta los últimos estratos de calizas lacustres de la Meseta Central. El fondo de la cuenca destaca por una franja boscosa madura de álamos, fresnos y sauces que contrasta fuertemente con los llanos superiores.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09010','espacio','Desfiladero de Conchas de Haro y Montes de San Juan','Canal geológico angosto labrado por el río Ebro al abrirse paso entre los Montes Obarenes y la Sierra de   Cantabria mediante erosión lineal severa. Las escarpaduras calizas muestran pliegues e inclinaciones tectónicas de alto interés visual, acompañadas de encinares montanos. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09220','espacio','Crestones de la Sierra de Pancorbo y Montes Obarenes','Relieve abrupto de montaña media caracterizado por líneas de cumbres calizas afiladas que dominan el paisaje de la Bureba norte. La roca desnuda y los pedregales calcícolas albergan comunidades botánicas rupícolas especializadas y matorrales de boj espinoso.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09221','espacio','Vallejo del río Ausines y lomas margosas','Suave incisión fluvial sobre sedimentos terciarios arcillosos y de margas yesíferas, configurando un paisaje de colinas redondeadas. Pequeñas formaciones estacionales de matorral esclerófilo y juncales colonizan las zonas de mayor humedad edáfica.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09223','espacio','Sierra de la Demanda meridional y dehesa de robles','Entorno de montaña silícea compuesto por conglomerados y areniscas, donde se asienta una de las dehesas de roble rebollo (Quercus pyrenaica) con los ejemplares más longevos y monumentales de la provincia. El paisaje visual está marcado por arroyos de aguas cristalinas e intensos verdes primaverales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09224','espacio','Puerto de la Brújula y cabecera del río Oca','Encrucijada geomorfológica que actúa como divisoria de aguas continental entre las cuencas del Duero y del Ebro. El relieve se compone de páramos erosionados y   laderas de caliza calva cubiertas de pastizales esteparios y aulagares. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09225','espacio','Desfiladero del río Arlanza y monte de las tenadas','Paisaje accidentado con pliegues anticlinales y sinclinales colgados de naturaleza caliza en las estribaciones de la Sierra de la Demanda. Los escarpes rocosos están salpicados de sabina albar y encinares de montaña que sobreviven en grietas de disolución kárstica.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09226','espacio','Macizo de San Lorenzo y cabecera del río San Bain','Relieve alpino de alta montaña dominado por pizarras, cuarcitas y areniscas paleozoicas con huellas periglaciares visibles en las laderas superiores. Alberga espectaculares bosques mixtos de hayas y acebos, regados por torrenteras nivales continuas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09227','espacio','Nacimiento del río Úrbel y parameras calcáreas','Surgencia kárstica intermitente a los pies de las muelas calizas que delimitan el Páramo de Masa. El paisaje está dominado por la desnudez de la roca caliza y campos de lapiaces suavizados por matorrales xerófilos y tomillares.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09228','espacio','Cerros testigo del páramo del Duero','Relieve residual que sobresale de la llanura aluvial por erosión diferencial, conformado por capas alternas de arcillas y calizas lacustres. La escasez de suelo en las cuestas propicia una flora esteparia adaptada a la insolación extrema.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09229','espacio','Terrazas fluviales del Duero y cárcavas del arroyo de la Vega','Amplio valle sedimentario cuaternario labrado sobre arenas y limos sueltos que genera taludes erosionados en cárcavas en las zonas de mayor pendiente. La vegetación se compone de sauces y alamedas fragmentadas en el eje fluvial.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09230','espacio','Parque Natural de Montes Obarenes-San Zadornil','Escarpe de falla calizo monumental que se alza sobre la fosa tectónica de la Bureba, ofreciendo una espectacular pared rocosa continua. La vegetación destaca por un quejigal montano denso con intrusiones de hayas en las vaguadas más umbrías.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09231','espacio','Sabinar del Arlanza y desfiladero del arroyo del Cock','Relieve quebrado calcáreo perteneciente al espacio protegido de los Sabinares del Arlanza, con afloramientos rocosos moldeados por karstificación. Cuenta con una cubierta vegetal excepcional de sabina albar de lento crecimiento adaptada al clima continental.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09232','espacio','Parque Natural de las Lagunas Glaciares de Neila','Extraordinario conjunto de circos y lagunas glaciares de alta montaña (Laguna Larga, Negra y de la Cascada) esculpidas sobre conglomerados silíceos de la Sierra de la Demanda. El paisaje vegetal subalpino incluye pinares albares densos, pastizales de alta montaña y formaciones de turbera con flora relíctica de la era glaciar.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09235','espacio','Campiña ondulada del río Esgueva','Morfología suave de lomas y colinas sedimentarias bajas del Mioceno compuestas por arcillas finas y arenas. La vegetación natural es arbustiva y rala, integrada por tomillares, retamares y pastizales anuales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09236','espacio','Vegas del río Arlanzón y llanuras aluviales','Topografía plana y de baja energía geológica constituida por depósitos detríticos recientes del eje fluvial principal de la provincia. Muestra pequeñas manchas de saucedas y alamedas que marcan el curso del agua.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','espacio','Desfiladero de la Horadada y hoces del río Oca','Monumental cañón fluvial donde el río Oca corta de forma abrupta e impresionante los Montes Obarenes mediante paredes verticales calizas de centenares de metros de altura. La biodiversidad botánica es sobresaliente, combinando bosques mediterráneos de encina y madroño con hayedos y quejigales atlánticos en íntimo contacto.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09239','espacio','Valle del río Gromejón y muelas calcáreas','Depresión erosiva encajada entre relieves de páramo donde los procesos de vertiente han suavizado las laderas calizas. Presenta encinares achaparrados de porte arbustivo y matorrales mediterráneos en las orientaciones de solana.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09241','espacio','Complejo kárstico de la Sierra de Atapuerca (vertiente oeste)','Relieve colinado de roca caliza jurásica con abundantes dolinas ocultas y procesos de disolución superficial que generan suelos pedregosos. La vegetación está formada por encinares termófilos aclarados y comunidades de tomillar rústico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09242','espacio','Llanura aluvial del río Odra','Relieve llano característico de la cuenca sedimentaria del Pisuerga, constituido por arcillas y terrazas cuaternarias de cantos rodados. Conserva pequeñas alisedas y choperas naturales que jalonan los márgenes del cauce fluvial.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09243','espacio','Interfluvio de los ríos Odra y Pisuerga','Amplia plataforma aluvial de topografía horizontal generada por depósitos sedimentarios finos arrastrados por las cuencas fluviales. Muestra una vegetación arbustiva xerófila marginal y pastizales resistentes a heladas prolongadas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09244','espacio','Cañón del río Padrones y valles colgados de Caderechas','Escondido y abrupto desfiladero calizo horadado por la erosión lineal del agua en el contacto kárstico de la Bureba septentrional. El paraje destaca por una densa cobertura de pino silvestre, quejigos majestuosos y un sotobosque húmedo de bojes gigantes.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09246','espacio','Cañón del río Arlanza y dehesa del comunero de Revenga','Entorno de montaña prelitoral asentado sobre potentes bancos de areniscas del Cretácico que forman grandes bloques y roquedos erosionados por el viento. Alberga imponentes y extensos bosques de pino silvestre (Pinus sylvestris) y robledales de melojo con un sotobosque de brezales y helechales atlánticos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09247','espacio','Cortados y meandros del río Pisuerga','Escarpados taludes de erosión fluvial formados en la margen cóncava del río Pisuerga sobre arcillas y conglomerados terciarios. El paisaje muestra un dinámico bosque galería con alisos, fresnos y abundantes sauces mimbreros.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09248','espacio','Vertientes de la Sierra de la Demanda y cabecera del río Cueva','Paisaje de media montaña compuesto por pizarras y cuarcitas con pendientes acusadas cubiertas de canchales periglaciares. Destacan las extensas masas boscosas de roble rebollo y brezales montanos que visten un relieve de aguas limpias y rápidas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09249','espacio','Vega del río Arlanzón (tramo bajo)','Llanura sedimentaria horizontal formada por depósitos de aluvión finos del cuaternario donde la energía del relieve es mínima. Conserva sauces arbustivos y carrizales dispersos asociados al nivel freático superficial de la vega.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09250','espacio','Confluencia del río Arlanzón con el río Hormazuela y cortados de arcilla','Punto de articulación fluvial donde el río Arlanzón labra profundos escarpes y terrazas colgadas sobre los materiales arcillo-arenosos de la campiña. El ecosistema ripario es notable por la densidad de sus choperas, alamedas y alisedas autóctonas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09012','espacio','Desfiladero de Pancorbo y canchales de la Peña del Mazo','Colosal e impresionante hendidura tectónica y fluvial que corta de arriba abajo los Montes Obarenes, con paredes verticales de caliza Jurásica que superan los 250 metros de altura. Su interés botánico y contemplativo radica en sus agujas pétreas, lapiaces colgados y encinares de montaña que trepan por riscos imposibles.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09253','espacio','Páramo del Duero meridional y lomas calcáreas','Altiplano calizo horizontal roto en sus márgenes por procesos de erosión de vertiente y arroyadas estacionales. Alberga una vegetación esclerófila compuesta por encinares aclarados densos y tomillares aptos para suelos secos y pedregosos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09255','espacio','Hoz de Sobrón y riscos de la Sierra de Arcena','Vertiginoso y grandioso cañón fluvial labrado por el río Ebro sobre calizas mesozoicas, flanqueado por crestas rocosas de afilados perfiles. Presenta una magnífica masa de bosques mixtos atlántico-mediterráneos con densos encinares, madroños, hayas y tejos rupícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09256','espacio','Llanuras tabulares e interfluvios del Duero','Relieve llano característico de la cuenca sedimentaria del Duero, constituido por depósitos de arenas, limos y costras calcáreas cuaternarias. Cuenta con retazos de matorral mediterráneo xerófilo adaptado a inviernos gélidos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09259','espacio','Valle del río Úrbel y taludes margosos','Cuenca erosiva labrada sobre yesos y margas blandas de la submeseta norte con perfiles topográficos suaves y colinas redondeadas. La vegetación riparia del río Úrbel se alterna con tomillares gipsícolas en las laderas más secas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09257','espacio','Plataforma estructural del Páramo de Sasamón','Vasta altiplanicie tabular horizontal asentada sobre potentes bancos de calizas pontienses azotada por vientos continentales. La vegetación es rala y esteparia, constituida por pastizales vivaces y pequeños caméfitos calcícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09258','espacio','Riberas e islas del río Pisuerga (límite provincial)','Tramo de llanura aluvial madura con una intensa dinámica sedimentaria que forma barras de grava y depósitos arenosos móviles. El ecosistema ripario cuenta con espléndidas alisedas y saucedas que tapizan el cauce ancho del río.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09013','espacio','Peña de Peñaranda y vega del río Arandilla','Prominente y aislado cerro testigo de caliza masiva que emerge sobre la terraza fluvial terciaria del río Arandilla. El entorno botánico destaca por las comunidades   rupícolas de la peña y un denso sotobosque de matorral mediterráneo termófilo. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09262','espacio','Meandros encajados y cortados del río Arlanza','Sector donde el río Arlanza dibuja curvas sinuosas excavando escarpes verticales sobre materiales arcillosos y conglomerados terciarios. El paisaje muestra un denso corredor forestal de ribera con chopos, sauces y álamos negros.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09265','espacio','Vaguada del arroyo de la Salceda y colinas de la Bureba','Relieve ondulado modelado sobre yesos e intercalaciones arcillosas que genera un terreno de suaves pendientes propensas a la erosión hídrica superficial. Acoge tomillares y pastizales mediterráneos continentales de carácter seco.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09266','espacio','Sierra del Mencilla, nacimiento del río Arlanzón y Valle del Sol','Imponente paisaje de alta montaña paleozoica con modelado glaciar en la cara norte del Mencilla, exhibiendo nichos de nicho de aludes y canchales cuarcíticos. Cuenta con extraordinarias masas forestales de acebos centenarios, hayedos puros y robledales de melojo que cubren valles prístinos de aguas de deshielo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09267','espacio','Cabecera del río Esgueva y lomas forestales','Relieve de transición entre las muelas calcáreas y la cuenca sedimentaria del Esgueva con valles poco profundos. Las vertientes conservan encinares de montaña de   porte arbustivo mixtos con quejigos adaptados a los suelos calizos. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09268','espacio','Formaciones rocosas de Los Barruecos y pinares de la Demanda','Paisaje geomorfológico espectacular de grandes bloques de areniscas cretácicas esculpidas por meteorización mecánica y eólica en formas caprichosas. Las formaciones rocosas emergen entre densísimos bosques de pino silvestre y sabinas de montaña en un marco visual sobrecogedor.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09269','espacio','Cañón del río Pedroso y laderas del robledal','Estrecho tajo fluvial abierto por el río Pedroso sobre calizas secundarias con presencia de escarpes y marmitas de gigante en el lecho del río. Alberga masas densas de roble rebollo y quejigos que tapizan las pendientes vertientes del término.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09270','espacio','Ribera del río Esgueva superior y cerros calizos','Valle fluvial joven tallado sobre materiales terciarios alternos de calizas y margas finas. Las orillas presentan sauces arbustivos y alisedas fragmentadas, mientras que las crestas exhiben tomillares xerófilos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','espacio','Diapiro de Poza de la Sal y cañón del río Altotero','Uno de los diapiros salinos más perfectos del mundo; un colosal cráter de colapso geológico de varios kilómetros de diámetro donde afloran yesos, sales y rocas volcánicas (ofitas) multicolores. El borde exterior está coronado por imponentes murallones calizos horizontales que   dan cobijo a encinares de montaña de valor botánico excepcional. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09273','espacio','Llanura aluvial del río Oca (tramo de la Bureba)','Valle plano de colmatación sedimentaria cuaternaria compuesto por limos y arcillas fértiles acumulados por la dinámica del río Oca. Muestra una estrecha e ininterrumpida banda de vegetación ripícola con sauces y chopos negros.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09274','espacio','Cañón del río Oropesa y hayedo de Garganchón','Profundo y umbrío valle encajonado en el corazón de la Sierra de la Demanda, labrado sobre pizarras y materiales silíceos del Paleozoico. Destaca por albergar un hayedo atlántico puro e idílico con monumentales ejemplares que conviven con helechos gigantescos y fuentes de aguas alpinas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09275','espacio','Cuenca del río Cogollos y llanuras arcillosas','Topografía casi horizontal propia de la campiña del Arlanza, modelada sobre arcillas del Neógeno sometidas a procesos de erosión laminar. Cuenta con pequeñas comunidades vegetales de matorral mediterráneo seco en los linderos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09276','espacio','Desfiladero de la Puebla y Montes de Vitoria (vertiente burgalesa)','Desfiladero fluvial excavado por el río Zadorra al seccionar las estructuras calizas occidentales de los Montes de Vitoria, mostrando impresionantes estratificaciones   geológicas. Alberga masas mixtas de quejigal y encinar cantábrico bien preservadas en sus vertientes abruptas. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09281','espacio','Valle del río Gromejón y lomas de arenas silíceas','Relieve suavemente ondulado constituido por arenas y arcillas de la cuenca del Duero con procesos de lixiviación edáfica. Presenta encinares aclarados de carácter mediterráneo y matorrales de jara blanca de notable interés botánico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09280','espacio','Cerros de margas yesíferas de la Bureba central','Paisaje de colinas erosionadas de pendientes suaves labradas sobre materiales evaporíticos y margas grisáceas terciarias. Desarrolla comunidades vegetales gipsícolas altamente especializadas y pastizales esteparios continentales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09283','espacio','Riscos de la Sierra de Oña y Montes Obarenes occidentales','Vertiginosas murallas calizas verticales de gran espectacularidad visual que marcan el frente de cabalgamiento de la sierra sobre la fosa burgalesa. Las pedrizas e inclinadas vertientes están densamente pobladas por encinares, bojes y madroños.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09287','espacio','Vega aluvial del río Ubierna (tramo medio)','Llanura de inundación de topografía horizontal constituida por arenas y gravas fluviales del cuaternario. El cauce mantiene una densa sauceda arbustiva y choperas autóctonas bien adaptadas a las avenidas fluviales estacionales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09288','espacio','Cabecera de la cuenca del Arlanzón y lomas de arcilla','Relieve de transición colinado compuesto por arcillas y areniscas terciarias que marcan los primeros desniveles hacia la Sierra de Atapuerca. Cuenta con pequeños rodales de encinar mediterráneo achaparrado y quejigales dispersos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09289','espacio','Lagunas de Neila (vertiente sur) y cañón del río Arlanza alto','Espectacular entorno forestal y geológico de alta montaña silícea en las estribaciones de los Picos de Urbión, caracterizado por formaciones de areniscas esculpidas por meteorización helada. Acoge gigantescos e interminables bosques de pino silvestre de calidad maderera excepcional y formaciones de acebedas, tejos y turberas subalpinas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09292','espacio','Vaguada del río Oca y lomas de la Brújula','Valle abierto labrado en materiales arcillosedimentarios de la cuenca de Briviesca que muestra una topografía de vertientes suaves. Los márgenes del arroyo conservan formaciones ripícolas de sauces y carrizales densos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09294','espacio','Páramo de la Sandra y lomas marginales','Superficie estructural elevada y tabular compuesta por bancos de calizas lacustres sometidos a intensa deflación por el viento. Presenta tomillares y pastizales   xerófilos ralos adaptados a las condiciones de heladas extremas de la meseta. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09901','espacio','Riberas, islas de grava y meandros del río Arlanza','Amplia llanura fluvial donde el río Arlanza divaga formando un tren de meandros activos con barras de gravas e islas sedimentarias dinámicas. El bosque de ribera es de una calidad visual excelsa, poblado por colosales chopos negros, sauces y fresnales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09298','espacio','Páramo de San García y lomas de la Bureba oriental','Altiplano calizo que marca el límite oriental de la comarca burebana, definido por pendientes erosionadas que exponen estratos margo-yesíferos. Alberga pastizales continentales ibéricos y matorrales espinosos calcícolas de porte bajo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09301','espacio','Riberas del río Ubierna y cerros de Vivar','Valle fluvial plano compuesto por depósitos aluviales finos rodeado de colinas bajas de margas y arenas terciarias. Cuenta con una banda de bosque galería integrada por sauces, álamos blancos y carrizales densos en los remansos del río.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09309','espacio','Formaciones de arenisca cretácica y pinares de Regumiel','Impresionante paisaje de montaña prelitoral dominado por afloramientos de areniscas del Cretácico que forman colosales muros rocosos pulidos por erosión periglacial. Está cubierto por un soberbio y húmedo bosque de   pino silvestre centenario, helechales atlánticos y comunidades de musgos rupícolas raras. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09310','espacio','Lomas calcáreas de la Bureba central','Relieve ondulado labrado sobre calizas margosas del Mioceno sometidas a procesos de meteorización química y física moderada. La vegetación se limita a pastizales continentales secos y pequeños rodales de matorral espinoso mediterráneo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09311','espacio','Cañón del río Arlanza y Sabinar de Retuerta','Magnífico estrechamiento fluvial donde el río Arlanza excava un profundo cañón de paredes calizas escarpadas repletas de cuevas y covachas de disolución kárstica. Las laderas y parameras albergan un sabinar de sabina albar (Juniperus thurifera) de valor botánico relicto excepcional mundial.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09314','espacio','Humedales del río Ausines y dehesa de Revilla','Llanura ondulada de transición a la Sierra de la Demanda con suelos silíceos donde proliferan pastizales húmedos estacionales. Destacan los rodales bien conservados de roble quejigo y rebollo que forman una cubierta arbórea aclarada y madura.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09316','espacio','Confluencia de los ríos Arlanza y Pisuerga','Impresionante nudo hidrográfico de la cuenca del Duero caracterizado por una llanura de inundación inmensa compuesta por arenas y gravas cuaternarias. Alberga un ecosistema de ribera maduro de gran porte con alisedas, fresnedas y choperas naturales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09315','espacio','Vaguada del río Ausines superior y muelas calizas','Relieve colinado labrado sobre calizas y arcillas rojas terciarias que generan perfiles asimétricos en el paisaje de la comarca. La vegetación predominante se compone de encinares achaparrados de montaña y tomillares xerófilos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09317','espacio','Riberas e islas del río Pisuerga (tramo norte)','Valle aluvial maduro donde el río Pisuerga discurre encajado entre terrazas cuaternarias estables, formando pequeñas islas sedimentarias con vegetación espontánea. Cuenta con un bosque galería de alisos y sauces mimbreros de gran valor estético.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09016','espacio','Balcón del Duero y terrazas fluviales miocénicas','Espectacular escarpe geológico y cerro testigo que se eleva de forma abrupta a más de 50 metros sobre la inmensa vega aluvial del río Duero. La base del cortado muestra estratos arcillosos erosionados por la dinámica del río, el cual está flanqueado por densas alamedas y saucedas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09323','espacio','Estribaciones de los Montes Obarenes y arroyo de Rojas','Zona de contacto tectónico caracterizada por relieves calizos quebrados que dan paso a la fosa sedimentaria de la Bureba. Las vertientes de solana presentan encinares mediterráneos xerófilos mixtos con matorral de aulaga.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09325','espacio','Ribera del río Franco y monte de quejigos','Valle fluvial encajado de forma somera sobre el páramo calizo del sudoeste provincial, con suelos ricos en materia orgánica en el fondo. Las laderas están pobladas por masas forestales de roble quejigo y encinas de porte medio.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09327','espacio','Valle del río Homino y lomas de la Bureba occidental','Relieve ondulado modelado sobre yesos y arcillas que da lugar a una topografía de suaves laderas y pequeñas depresiones erosivas. La vegetación se compone de matorrales gipsícolas, tomillares continentales y retazos de encinar arbustivo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09328','espacio','Valle de Caderechas y desfiladero del río Vadillo','Impresionante anfiteatro calcáreo protegido por escarpadas laderas de roca que configuran un microclima húmedo y aislado de los vientos del norte. Las laderas umbrías están cubiertas por densos bosques de pino silvestre, quejigos y rodales de madroños centenarios.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09017','espacio','Formaciones de areniscas de la meseta del Arlanza y riberas del río Ciruelos','Paisaje de transición serrana caracterizado por estratos de areniscas del Cretácico fuertemente modelados por la erosión diferencial. El entorno fluvial destaca por sus alisedas bien conservadas que serpentean entre relieves cubiertos por rebollares y pinos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09329','espacio','Vertientes de la Sierra de Oña y cañón del río Oca','Imponentes crestones y farallones calizos verticales que delimitan de forma abrupta el norte de la cuenca de la Bureba. Las repisas rocosas y taludes albergan una rica comunidad botánica rupícola y masas mixtas de encina y boj.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09332','espacio','Vega del río Ausines','Relieve horizontal propio de la campiña burgalesa sobre sedimentos arcillosos del Mioceno. El curso fluvial aporta una franja estrecha de fresnedas y saucedas que rompe visualmente la homogeneidad de la llanura cerealista.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09334','espacio','Diapiro de Poza de la Sal (borde oriental) y peñas calizas','Singularidad geológica caracterizada por el contacto tectónico entre los materiales salinos del diapiro y los escarpes calizos de los Montes Obarenes. El paisaje es abrupto, con vegetación adaptada a la salinidad edáfica y tomillares xerófilos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09335','espacio','Cabecera del río Milanos y laderas de la Sierra de la Demanda','Relieve de media montaña forestal constituido por conglomerados y areniscas terciarias con valles encajados   de aguas limpias. Cuenta con extensas masas boscosas de roble rebollo (Quercus pyrenaica) y brezales que tapizan las umbrías. San Vicente del Valle (Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09360','espacio','Valle del río Tirón y estribaciones del monte San Lorenzo','Entorno de montaña atlántica con pendientes acusadas sobre un sustrato de pizarras y cuarcitas paleozoicas. El paisaje visual está dominado por frondosos hayedos y pastizales húmedos de altura que tapizan las cabeceras de los torrentes.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09347','espacio','Desfiladero de Techa y Montes Obarenes nororientales','Impresionante garganta rocosa excavada por la acción fluvial sobre potentes bancos de calizas jurásicas que muestran una fuerte inclinación tectónica. Las paredes verticales acogen encinares montanos y una valiosa flora rupícola adaptada a la escasez de suelo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09348','espacio','Terrazas del río Arlanza','Llanura aluvial baja constituida por depósitos cuaternarios de gravas y arenas acumulados por la dinámica del río Arlanza. Conserva pequeños rodales de vegetación riparia con álamos negros y sauces arbustivos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09350','espacio','Confluencia de los ríos Arlanza y Mahamud','Amplio valle aluvial sedimentario con un relieve liso interrumpido únicamente por suaves cerros testigo de arcillas. Los cauces fluviales presentan bandas continuas de alamedas y saucedas en buen estado ecológico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09351','espacio','Vallejo del arroyo de la Pradera y Montes de Oca','Relieve ondulado de transición forestal donde la erosión ha esculpido pequeñas vaguadas sobre conglomerados del Terciario. El paisaje vegetal destaca por quejigales aclarados y matorrales espinosos mixtos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09352','espacio','Sabinar del Arandilla','Paisaje de paramera calcárea elevada que alberga formaciones abiertas y relictas de sabina albar (Juniperus thurifera). El relieve muestra formas kársticas incipientes con lapiaces y suelos pedregosos expuestos a condiciones climáticas extremas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09354','espacio','Corredor de la Brújula y lomas calcáreas','Zona de divisoria de aguas de relieve suave constituida por calizas lacustres y margas del neógeno. La vegetación está formada por pastizales ibéricos secos, aliagares y comunidades de caméfitos calcícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09355','espacio','Páramos del río Esgueva','Relieve tabular característico de la cuenca del Duero con vertientes escarpadas que caen hacia el fondo aluvial del valle. Los bordes calizos del páramo albergan encinares de porte arbustivo y tomillares muy integrados.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09356','espacio','Desfiladero del río Mataviejas y peñas del Desfiladero de la Yecla (límite)','Angosto cañón calizo de paredes verticales esculpido por la disolución kárstica y la erosión lineal del agua. En las profundidades umbrías del desfiladero prospera un microclima que permite el crecimiento de musgos, helechos singulares y densos quejigales en las zonas altas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09018','espacio','Espacio Natural de los Sabinares del Arlanza y Desfiladero de La Yecla','Espectacular y angosta garganta kárstica con paredes verticales calcáreas que casi se tocan, modelada de forma colosal por el arroyo El Cauce. El entorno alberga uno de los sabinares de sabina albar más extensos, puros y mejor conservados del planeta, asentado sobre un relieve de lapiaces y dolinas estructurales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09361','espacio','Geoparque Mundial de la UNESCO Las Loras y cañón del río Rudrón','Paisaje geomorfológico espectacular definido por grandes mesetas calizas tabulares (loras) que destacan de forma aislada sobre profundos valles excavados. El borde de la lora ofrece impresionantes cantiles calizos desnudas que contrasten con quejigales y brezales de montaña.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09362','espacio','Curso del río Ausines y lomas de Cojóbar','Relieve llano de la cuenca sedimentaria del Arlanzón compuesto por materiales finos arcillosos. Cuenta con pequeñas alineaciones de sauces, carrizales y vegetación macrofítica en los márgenes del modesto cauce hídrico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09363','espacio','Vega del río Brullés y cerros testigos de arcilla','Paisaje llano de campiña sedimentaria interrumpido por elevaciones cónicas aisladas fruto de la erosión diferencial sobre margas. El río aporta un cordón vegetal de choperas autóctonas que contrasta fuertemente con la llanura continental.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09369','espacio','Páramo de Roa y laderas arcillo-yesíferas','Cuestas y vertientes escarpadas formadas bajo el nivel del páramo calcáreo por la acción erosiva de los torrentes estacionales. Alberga masas dispersas de encina y matorral mediterráneo adaptado a suelos con presencia de yesos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09372','espacio','Riberas del río Ubierna','Llanura de inundación fluvial con depósitos cuaternarios de arenas y limos finos. Muestra pequeñas olmedas residuales y saucedas arbustivas asociadas a la humedad edáfica continua del fondo de valle.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09373','espacio','Peña Amaya (vertiente occidental) y parameras calcáreas','Imponente masa caliza de perfil tabular y paredes verticales colosales que emerge como un bastión defensivo natural en el paisaje de las Loras. La vegetación del entorno combina pastizales calcícolas de montaña, brezales secos y comunidades rupícolas en las grietas de la roca.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42175','espacio','Sierra de la Alcarama (vertiente sur) y nacimiento del río Alhama','Paisaje premontano áspero y elevado donde brotan las fuentes que dan origen al río Alhama en un entorno kárstico modesto. Las laderas están cubiertas por matorrales de cambroneras y encinares de montaña de crecimiento lento adaptados al viento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09374','espacio','Páramo de las Loras meridional','Altiplano calizo horizontal sometido a una intensa deflación eólica y procesos de helada (crioclastia). La vegetación es rala, caracterizada por pastizales vivaces calcícolas, tomillares y caméfitos espinosos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09375','espacio','Valles fluviales del río Sambol','Suave depresión erosiva en los materiales terciarios de la cuenca central burgalesa. El entorno presenta formaciones herbáceas estacionales y pequeños matorrales mediterráneos en las vertientes más secas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09377','espacio','Confluencia de los ríos Arlanzón y Urbel','Amplia llanura aluvial caracterizada por la acumulación de sedimentos finos e inundaciones estacionales que mantienen alto el nivel freático. Destaca la presencia de saucedas y alamedas maduras que protegen los márgenes fluviales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09378','espacio','Sierra de Carazo y desfiladero del río Mataviejas','Relieve de pliegues calizos alpinos que configuran escarpes asimétricos y pendientes abruptas de gran potencia visual. Alberga una vegetación mixta con sabinas albares, encinas montanas y quejigales que ocupan las umbrías.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09380','espacio','Laderas calcáreas del valle del Esgueva','Relieve de cuestas modelado sobre alternancias de margas y calizas que genera perfiles escalonados en el terreno. La vegetación está integrada por tomillares-alicatados y pequeñas manchas de encinar aclarado.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09381','espacio','Vertientes del Mencilla y cabecera del río Pedroso','Paisaje de alta montaña paleozoica constituido por pizarras, esquistos y areniscas con huellas de modelado periglaciar en las cumbres. Cuenta con excelentes formaciones de robledal melojo y acebedas que cubren las laderas más húmedas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09382','espacio','Humedales estacionales del río Hormazuela','Pequeña cuenca hidrográfica menor asentada sobre materiales arcillo-limosos que propicia el encharcamiento temporal en invierno. Presenta pastizales húmedos y comunidades de juncos bien adaptadas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09384','espacio','Meandros del río Arlanza e islas sedimentarias','Tramo medio-bajo del río Arlanza donde la corriente esculpe amplias curvas y deposita barras de grava estables en el cauce. Las orillas están densamente pobladas por bosques galería de alisos, sauces y chopos negros.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09386','espacio','Sabinar de Lerma (borde septentrional)','Relieve suavemente ondulado sobre calizas terciarias que sustenta una población dispersa pero madura   de sabina albar. Las condiciones de aridez edáfica determinan un sotobosque ralo de tomillo y aliaga. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09387','espacio','Cañón del río Riaza (tramo bajo) y cerros escarpados','Valle encajado en los materiales blandos de la cuenca del Duero, mostrando perfiles asimétricos por la erosión lateral del río. Cuenta con vegetación ripícola densa flanqueada por laderas cubiertas de matorral mediterráneo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09388','espacio','Piedemonte de la Sierra de la Demanda y formaciones de arenisca','Zona de contacto geomorfológico con relieves suaves cubiertos de depósitos detríticos y canchaleras antiguas. Alberga masas de roble rebollo y pastizales secos continentales de notable extensión.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09389','espacio','Vega del río Escatón y riberas del Arlanza','Llanura aluvial estable compuesta por aportes de limos y arenas cuaternarias de gran espesor. Presenta comunidades vegetales hidrófilas, carrizales en las zonas de aguas lentas y saucedas arbustivas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09390','espacio','Valle del río Esgueva y monte de encinas','Disimetría de vertientes bien marcada donde destacan los escarpes calizos del norte frente a las pendientes suaves del sur. El término conserva un encinar denso de encina carrasca adaptado al clima continental severo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09391','espacio','Meandros del río Esgueva y humedales de ribera','Tramo final del río Esgueva en la provincia, caracterizado por una llanura de inundación madura con curvas muy pronunciadas. Las márgenes albergan alamedas y saucedas que estabilizan los depósitos de limos fluviales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09392','espacio','Cueva de San Tirso y paredones arcilloconglomeráticos','Singular relieve escarpado constituido por potentes bancos de conglomerados del Terciario que muestran formas de erosión en visera y oquedades naturales. La vegetación del entorno es de carácter quejigal aclarado y matorral de umbría.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09019','espacio','Desfiladero de la Horadada y confluencia del río Nela con el Ebro','Impresionante garganta kárstica abierta por el río Ebro al cortar de forma transversal las estructuras calizas de los Montes Obarenes. El cañón presenta imponentes paredes verticales cubiertas de encinares, madroños, bojes y una variada flora de afinidad atlántica en el fondo húmedo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09395','espacio','Cascadas del río Hornillo y cañón del río Rudrón','Espectacular relieve kárstica donde el río Hornillo salva el desnivel del cañón mediante una sucesión de saltos de agua y espectaculares formaciones de toba calcárea (travertinos) de gran belleza visual. El cañón está densamente cubierto por quejigales, musgos hidrófilos y vegetación rupícola exuberante.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09396','espacio','Cañón del río Gromejón y surgencias kársticas','Pequeño desfiladero excavado sobre la plataforma caliza del páramo que cuenta con manantiales naturales de agua limpia en el fondo del valle. Alberga comunidades botánicas de quejigar y formaciones arbustivas calcícolas bien conservadas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09398','espacio','Nacimiento del río Úrbel y farallones calizos de las Loras','Paisaje kárstico colosal presidido por un anfiteatro de rocas calizas verticales que delimitan un estrecho valle de cabecera. La surgencia del río da vida a un entorno de gran verdor, flanqueado por lapiaces y cubierto por hayas dispersas y quejigales de montaña.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09403','espacio','Valle del río Esgueva alto y lomas de arcilla','Relieve de media ladera sobre materiales arcillosos del Terciario que configuran una topografía de suaves ondulaciones. Cuenta con pequeñas masas de encinar mediterráneo y pastizales xerófilos continentales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09405','espacio','Páramo de la Morera y cárcavas calcáreas','Relieve tabular calizo que sufre procesos de incisión hídrica en sus vertientes, originando pequeños barrancos escarpados. Alberga comunidades vegetales de tomillar, aliagar y algunas encinas de porte arbustivo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09406','espacio','Paramera de la meseta central y arroyo de San Pedro','Plataforma estructural horizontal constituida por calizas bioclásticas del neógeno con escasa cobertura vegetal arbórea. El paisaje visual está dominado por caméfitos calcícolas y pastizales resistentes a la oscilación térmica.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09408','espacio','Llanura aluvial del río Vallarta','Cuenca sedimentaria rellena de arcillas y limos finos cuaternarios con relieve predominantemente llano. Los márgenes del arroyo conservan pequeñas saucedas arbustivas y juncales que marcan la línea del agua.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09904','espacio','Hoya kárstica de Rioseras y cortados calizos','Depresión kárstica de grandes dimensiones (poljé) rodeada de relieves calizos escarpados que drenan de forma subterránea. El entorno vegetal cuenta con encinares montanos bien adaptados a la sequedad de la roca caliza superficial.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09908','espacio','Monumento Natural del Ojo Guareña (límite meridional) y Sierra de Salvada','Espectacular murallón calizo de más de 20 kilómetros de longitud que se eleva verticalmente sobre el valle, mostrando impresionantes formas de erosión kárstica y modelado alpino. Las laderas y cumbres albergan densos hayedos atlánticos, encinares relictos y valiosas comunidades vegetales rupícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09409','espacio','Desfiladero de los Hocinos y cañón del alto Ebro','Colosal cañón fluvial excavado por el río Ebro sobre potentes masas calcáreas de la Cordillera Cantábrica, con paredes de roca verticales cubiertas de vegetación. El ecosistema es de un altísimo valor botánico, mezclando hayedos húmedos, quejigales, tejos relictos y madroños de gran porte.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09410','espacio','Nacimiento del río Cadagua y Montes de Ordunte','Paisaje puramente atlántico definido por un gran valle semicircular rodeado de altas cumbres de areniscas y calizas con densos hayedos y robledales de roble albar. El nacimiento del Cadagua es una espectacular surgencia kárstica rodeada de un entorno vegetal exuberante de musgos y helechos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09411','espacio','Gargantas del río Oca (tramo bajo) y Montes de Oca','Valle encajonado que corta los materiales sedimentarios marginales de la Bureba, formando vertientes escarpadas de gran interés visual. El cauce está escoltado por un magnífico bosque galería compuesto por alisos, sauces y fresnos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09902','espacio','Cañón del río Urbel y peñas calcáreas de Santibáñez','Tramo fluvial encajado donde el río Urbel rompe la continuidad del páramo calizo mediante un estrecho cañón de pendientes acusadas. Las laderas umbrías conservan encinares montanos bien estructurados y matorrales calcícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09905','espacio','Cañón del río Ebro y gargantas del río Moradillo','Uno de los cañones calcáreos más espectaculares de Europa, con profundidades que superan los 200 metros y paredes verticales escalonadas de gran valor geomorfológico. Alberga una biodiversidad botánica extraordinaria, destacando el hayedo de umbría, encinares termófilos y bosques galería maduros.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09412','espacio','Desfiladero de Sobrón y cascada de Pedrosa de Tobalina','Impresionante entorno fluvial que cuenta con una colosal cascada donde el río Jerea vierte sus aguas en una caída de más de 10 metros sobre un lecho calizo horizontal. El desfiladero de Sobrón muestra espectaculares estratos calizos verticales y un denso bosque mixto mediterráneo-atlántico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09413','espacio','Desfiladero de las Palancas y cascada de las Pisas','Paisaje de montaña atlántica caracterizado por un recóndito e impresionante cañón kárstico y una bellísima cascada escalonada oculta en un bosque húmedo. La vegetación destaca por hayedos puros, acebedas maduras y comunidades de helechos gigantes de gran valor contemplativo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09415','espacio','Espacio Natural de las Loras y paramera de Valdelucio','Altiplano estructural elevado que forma parte del relieve de las Loras, delimitado por imponentes escarpes de roca caliza desnuda. La paramera presenta una vegetación esteparia alpina muy singular con caméfitos espinosos y pastizales calcícolas resistentes al hielo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09414','espacio','Lagunas glaciares de Neila (límite meridional) y dehesa de Tolbaños','Paisaje de alta montaña silícea integrado en el Sistema Ibérico, con valles modelados por lenguas glaciares cuaternarias y circos rocosos de gran magnitud. Alberga impresionantes bosques de pino silvestre alba y melojos centenarios rodeados de humedales de turbera.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09416','espacio','Cañón del río Ebro y hoces de Zamanzas','Tramo del cañón del Ebro de extraordinaria belleza visual, donde el río discurre encajado de forma sinuosa entre altísimos paredones calizos escalonados. La vegetación de umbría está dominada por hayedos relictos, tejos silvestres y madroñales que colonizan los cantiles rocosos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09417','espacio','Lomas del río Odra y llanuras cerealistas','Relieve de campiña suave constituido por arcillas y limos de la cuenca sedimentaria occidental burgalesa. Cuenta con matorrales mediterráneos aclarados y tomillares xerófilos adaptados a las heladas invernales prolongadas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09418','espacio','Confluencia del río Arlanzón y el río Pisuerga','Amplia llanura de inundación sedimentaria con terrazas fluviales de gravas y arenas bien estructuradas en el cuaternario. Alberga franjas de bosque galería con álamos, sauces y fresnos que aprovechan el nivel freático.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09419','espacio','Lomas de la Bureba oriental y arroyo de San Juan','Relieve colinado de suaves pendientes labrado sobre arcillas y yesos terciarios de la fosa sedimentaria. Presenta comunidades de matorral gipsícola y caméfitos adaptados a suelos con alto contenido en sales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09407','espacio','Vertientes de la Sierra de la Demanda y cabecera del río Oca','Paisaje forestal de media montaña abrupta constituido por pizarras y cuarcitas paleozoicas con profundos valles encajados. Las laderas septentrionales están tapizadas por frondosos bosques de roble rebollo y hayedos atlánticos relictos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09421','espacio','Meandros del río Duero y llanura aluvial de la Vid','Tramo fluvial maduro donde el río Duero describe amplias curvas sobre materiales arenosos cuaternarios, generando islas sedimentarias estables. Las orillas acogen una excelente representación de bosque galería con chopos negros, sauces y eneas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09423','espacio','Cerro testigo de Vileña y llanura de la Bureba','Formación geológica cónica aislada que destaca notablemente sobre el relieve plano de la cuenca de la Bureba debido a la erosión diferencial. La vegetación es principalmente herbácea y de matorral bajo mediterráneo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09427','espacio','Peña Amaya e imponentes farallones de las Loras occidentales','Colosal muela caliza exenta que se eleva de manera majestuosa más de 200 metros sobre la llanura arcillosa, mostrando cantiles rocosos totalmente verticales y   un perfil de mesa tabular perfecto. Alberga pastizales alpinos calcícolas en su plataforma superior y comunidades de aves rupícolas en sus paredes. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09428','espacio','Páramo de Roa y escarpes de arcilla roja','Vertientes montañosas escarpadas que caen hacia la cuenca del Duero, formadas por arcillas miocénicas intensamente erosionadas que muestran tonos rojizos llamativos. La vegetación cuenta con encinares aclarados y matorral xerófilo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09429','espacio','Montes de Oca y umbrías de Villaescusa','Pequeño valle de montaña cerrado y umbrío labrado sobre conglomerados y areniscas del Terciario superior. El paisaje destaca por sus densos bosques de quejigo (Quercus faginea) y un sotobosque húmedo de bojes y brezos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09431','espacio','Garganta del río Oca y acebedas de los Montes de Oca','Angosto paso fluvial encajonado entre relieves de conglomerados y calizas que marca la transición a la alta montaña. El entorno forestal destaca por sus frondosos bosques de roble melojo y la presencia de manchas relictas de acebos (Ilex aquifolium) de gran porte.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09433','espacio','Sierra de la Demanda nororiental y cañón del río Urbión (Burgos)','Paisaje de media-alta montaña paleozoica con pendientes muy pronunciadas sobre pizarras y cuarcitas. Las zonas de umbría albergan densas masas de hayedos   atlánticos y robledales que flanquean torrentes de aguas cristalinas. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09434','espacio','Arroyo de las Fuentes y llanura del Arlanzón','Relieve llano y monótono propio de la cuenca sedimentaria del Arlanzón sobre materiales arcillosos miocénicos. Cuenta con pequeñas formaciones herbáceas estacionales y saucedas arbustivas aisladas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09437','espacio','Vega del río Arlanza y terrazas de grava','Amplia llanura aluvial constituida por depósitos de cantos rodados, gravas y arenas acumulados durante el cuaternario. Los márgenes del cauce albergan rodales de alamedas y comunidades de macrofitas acuáticas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09438','espacio','Riberas del río Duero e islas de grava','Tramo aluvial maduro con una dinámica fluvial de sedimentación activa que origina barras arenosas cambiantes en el lecho del río. Cuenta con un bosque galería continuo compuesto por sauces blancos, álamos y fresnos de buena talla.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09439','espacio','Confluencia del río Arlanzón y el río Ubierna','Espacio aluvial maduro caracterizado por amplias terrazas de gravas y limos del Cuaternario [Burgos]. La llanura de inundación mantiene comunidades de sauces y álamos negros que estabilizan los márgenes arcillosos del cauce.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09440','espacio','Cañón del río Bañuelos y monte de pinos','Pequeño desfiladero fluvial excavado sobre arenas y arcillas consolidadas del Terciario, flanqueado por relieves suaves. Las laderas están cubiertas por extensas masas puras de pino resinero (Pinus pinaster) de regeneración espontánea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09441','espacio','Vallejo del río Arlanzón y lomas arcillosas','Relieve de campiña suave modelado sobre sedimentos finos miocénicos en el sector occidental de la provincia. La vegetación natural es dispersa, destacando matorrales espinosos y pastizales continentales estacionales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09442','espacio','Ribera del río Arlanza y cárcavas de yeso','Ladera escarpada que desciende de la paramera hacia la vega fluvial, mostrando procesos de erosión hídrica sobre yesos y margas. Acoge comunidades de matorral gipsícola y tomillares adaptados a suelos con alto contenido salino.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09443','espacio','Monte de la Virgen y quejigales del río Cogollos','Cubierta forestal de gran interés botánico constituida por un quejigal (Quercus faginea) maduro sobre terrenos llanos arcillo-arenosos. Las zonas bajas presentan pequeños humedales estacionales asociados a la dinámica del riachuelo local.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09444','espacio','Río Odra y escarpes margosos','Paisaje fluvial encajonado de forma suave entre cerros de margas y arcillas de la cuenca del Pisuerga. El cauce conserva una banda de vegetación hidrófila con juncales y carrizales bien estructurados.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09446','espacio','Arroyo de Fuenteperal','Pequeña cuenca hidrográfica de carácter torrencial asentada sobre sedimentos sueltos cuaternarios. Presenta formaciones herbáceas ralas y espinares mediterráneos adaptados a la sequedad estival.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09448','espacio','Arroyo de San Miguel y campiña meridional','Superficie horizontal sedimentaria interrumpida por la modesta incisión de un arroyo estacional. Cuenta con retazos de matorral mediterráneo esclerófilo en los taludes de mayor pendiente.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09449','espacio','Valle del río Hormazuela y terrazas fluviales','Llanura de inundación de relieve plano constituida por depósitos detríticos del Terciario superior. El curso del agua genera un microambiente húmedo propicio para saucedas y alamedas residuales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09450','espacio','Vertiente norte de la Peña de Carazo','Imponente murallón calizo de morfología tabular cuyas laderas de umbría acumulan potentes canchales de ladera por gelifracción. El dosel vegetal destaca por un sabinar maduro mezclado con encinar montano de gran valor botánico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09451','espacio','Pinar del río Bañuelos y afloramientos de arenas','Paisaje forestal sobre dunas fósiles y arenas continentales donde prospera una masa pura de pino resinero (Pinus pinaster). El sustrato poroso favorece un sotobosque especializado de brezales secos y tomillares.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09454','espacio','Desfiladero de Pancorbo (vertiente occidental) y Montes Obarenes','Relieve escarpado con crestones de caliza cretácica repleto de diaclasas y formas de erosión eólica en las cumbres. Las canales umbrías albergan quejigales densos con presencia de bojes y pequeños acebos rupícolas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09455','espacio','Ribera del río Arlanzón (tramo bajo)','Terreno llano de aluvión con sedimentos arenosos y limosos depositados por la dinámica fluvial del Arlanzón. Conserva comunidades macrofíticas y saucedas arbustivas adaptadas al encharcamiento temporal.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09456','espacio','Lomas del río Cogollos y depósitos detríticos','Suaves elevaciones del terreno compuestas por conglomerados cementados y arcillas de la cuenca sedimentaria central. La vegetación se compone de pastizales vivaces calcícolas y matorral bajo espinoso.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09903','espacio','Meandros encajados del río Nela y kársticos de Tubilla','Amplia llanura aluvial e intra-montana rota por la espectacular dinámica sinuosa del río Nela sobre calizas del   Cretácico. Sus riberas muestran formaciones maduras de alisedas y quejigales hidrófilos de excepcional calidad botánica y paisajística. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09458','espacio','Curso del río Ausines y campiña arcillosa','Valle de fondo plano constituido por limos cuaternarios en un relieve generalizado de penillanura erosionada. El río aporta una estrecha franja verde de vegetación riparia en un entorno predominantemente desarbolado.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09460','espacio','Riberas e islas del río Odra','Tramo de llanura fluvial donde el río Odra se ramifica creando pequeñas islas de grava y barras de sedimentos arenosos. Las márgenes albergan masas densas de sauces (Salix alba) y choperas autóctonas bien conservadas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09463','espacio','Embalse de Úzquiza y estribaciones del San Millán (Sierra de la Demanda)','Espectacular entorno de media y alta montaña modelado sobre pizarras, cuarcitas y calizas paleozoicas, donde destaca la gran lámina de agua rodeada de relieves abruptos. Alberga frondosos bosques de roble rebollo, hayedos en las umbrías y turberas de montaña de altísimo interés botánico.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09464','espacio','Valle del río Esgueva y laderas calcáreas','Valle disimétrico tallado en el páramo burgalés que expone escarpes de calizas lacustres en su vertiente expuesta al norte. Cuenta con formaciones de matorral   mediterráneo xerófilo y tomillares densos que fijan el suelo calcáreo. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09466','espacio','Sabinar de Villaverde y encinares de la cuenca del Arlanza','Paisaje forestal caracterizado por la presencia de sabina albar (Juniperus thurifera) mezclada con encinares sobre relieves de colinas suaves y calizas. El terreno presenta formas suaves de disolución kárstica superficial.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09467','espacio','Meandros del río Arlanza y terrazas de grava','Tramo bajo fluvial donde el río describe amplias curvas sobre una llanura de inundación de materiales cuaternarios sueltos. Destaca la preservación de bosques de ribera compuestos por chopos, sauces y fresnos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09471','espacio','Cañón del río Morquillas y lomas calizas','Incisión fluvial menor labrada sobre el páramo calcáreo del Ubierna que genera pequeños cantiles de roca expuesta. La vegetación está integrada por pastizales mediterráneos de montaña y tomillares heliófilos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09472','espacio','Arroyo de las Vegas y llanura cerealista','Geomorfología monótona de la cuenca sedimentaria occidental sobre arcillas del Neógeno. Alberga pequeñas comunidades herbáceas nitrófilas e hidrófilas ligadas a las depresiones húmedas estacionales del terreno.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09473','espacio','Cuestas del río Brullés y cerros testigo','Paisaje de erosión diferencial dominado por cerros aislados de cima plana protegidos por estratos de calizas miocénicas sobre vertientes de margas. Cuenta con comunidades vegetales esteparias y pastizales secos.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09476','espacio','Sabinar de Mazuelo y estribaciones de la Sierra de la Demanda','Zona de transición geológica con afloramientos calizos jurásicos que sustentan formaciones abiertas de sabina albar de notable valor relicto. El relieve es ondulado y se eleva hacia las primeras rampas boscosas de la sierra.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09425','espacio','Peñas de Vilviestre y pinares del alto Arlanza','Extraordinario paisaje de la comarca de Pinares con formaciones de grandes bloques de areniscas esculpidos por erosión alveolar y eólica, que emergen entre masas arbóreas continuas. El bosque está compuesto por pino silvestre (Pinus sylvestris) centenario con un sotobosque de brezales húmedos y helechales.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09478','espacio','Valle del río Pedroso y dehesa de melojos','Relieve montañoso de la Sierra de la Demanda asentado sobre materiales silíceos paleozoicos que configuran vertientes redondeadas pero abruptas. El paraje destaca por una magnífica dehesa de roble rebollo (Quercus pyrenaica) con ejemplares monumentales y un sotobosque atlántico muy húmedo.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09480','espacio','Arroyo de San Tomé y llanura de arcillas','Depresión erosiva suave sobre materiales finos miocénicos en el centro de la cuenca sedimentaria del   Arlanza. Presenta retazos residuales de matorral espinoso mediterráneo y pastizales estacionales. Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09482','espacio','Desfiladero del río Pisuerga y Peña Amaya (estribaciones)','Estrechamiento fluvial colosal donde el río Pisuerga corta los relieves calcáreos de las Loras orientales, generando escarpes verticales de gran belleza geológica. Las paredes rocosas dan cobijo a una rica vegetación rupícola y encinares de montaña en las repisas.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09483','espacio','Cañón del río Arandilla y muelas de Zazuar','Incisión fluvial de paredes calizas verticales tallada sobre la plataforma estructural del páramo de la Ribera del Duero. La transición botánica es abrupta, variando desde el encinar seco de la paramera superior hasta la alameda húmeda del fondo del valle.   Burgos).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09485','espacio','Cuestas de la Bureba y arroyo de San Paio','Relieve de transición entre el páramo calizo de Masa y la fosa tectónica de la Bureba, modelado por procesos de ladera sobre margas. Muestra una vegetación arbustiva mediterránea dominada por aliagas y tomillares basófilos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90086','espacio','Riberas del río Ambroz y Piscina Natural de Abadía','Espacio de amortiguación fluvial caracterizado por un denso bosque de galería con alisos, fresnos y sauces que tapizan los depósitos aluviales de gravas y arenas. Geomorfofológicamente destaca por sus terrazas fluviales y el encajamiento del río proveniente de la Sierra de Béjar.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90092','espacio','Berrocal del Ayuela y charcas graníticas','Paisaje penillanurero modelado sobre un batolito granítico donde abundan los bolos, piedras caballeras y lanchares pulidos por meteorización química. Las pequeñas depresiones del terreno acumulan agua estacional generando humedales temporales con comunidades de juncos y ranúnculos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90094','espacio','Sierra de Cruces y alcornocales de la Centinela','Relieve de crestón cuarcítico correspondiente a la orogenia hercínica que rompe la monotonía de la penillanura cacereña. Su vertiente norte acoge un alcornocal denso y húmedo con madroños de porte arbóreo asentados sobre suelos pardos silíceos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90095','espacio','Charca de Abajo y dehesas de la penillanura','Depresión endorreica menor sobre materiales graníticos degradados que da lugar a una laguna somera estacional. El entorno visual está definido por dehesas de encina aclaradas con afloramientos de lanchas pétreas horizontales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90840','espacio','Garganta de Santa Lucía y dehesas del rillón','Valle encajonado excavado por la red hidrográfica sobre pizarras, mostrando llamativos perfiles asimétricos y afloramientos rocosos agudos. Destaca botánicamente por albergar manchas densas de monte mediterráneo con densos jarales y encinares maduros.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90841','espacio','Garganta de San Gregorio y Chorrera de la Ventera','Impresionante desfiladero de alta montaña labrado en el granito de la Sierra de Gredos, con saltos de agua verticales que salvan desniveles colosales. Las laderas están cubiertas por robledales de rebollo (Quercus pyrenaica) y castañares centenarios en régimen de umbría húmeda.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90096','espacio','Valle del Ambroz y garganta de la Buitrera','Fosa tectónica flanqueada por las cumbres graníticas de la Sierra de Francia y Béjar, donde los ríos bajan con fuerte gradiente excavando cauces pedregosos de gran valor visual. La vegetación destaca por densos bosques mixtos de castaño, rebollo y alisos en el lecho fluvial.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90097','espacio','Vegas bajas del río Jerte','Amplia llanura aluvial constituida por arenas gruesas y cantos rodados de origen granítico depositados por la dinámica divagante del Jerte. Conserva una franja madura de bosque de ribera con alisos y fresnos que protegen los márgenes de la erosión.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90098','espacio','Estrecho de la Peña Amarilla (Río Guadalupejo) y sinclinal de Alía','Imponente cañón de relieve apalachense donde el río corta de forma transversal las duras crestas de cuarcita armoricana del Geoparque Villuercas-Ibores-Jara. Las paredes verticales muestran pliegues geológicos espectaculares y albergan flora rupícola protegida junto a densos lorales (Prunus lusitanica) relictos en las umbrías.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90099','espacio','Sierra de San Pedro y Garganta del Alcor','Formación montañosa paleozoica caracterizada por crestones de cuarcita alineados y valles paralelos rellenos de pizarras. Su valor contemplativo reside en la exuberante densidad de sus bosques mediterráneos de umbría, repletos de madroños, durillos, alcornoques y quejigos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90100','espacio','Embalse de Arrocampo y cerros calizos','Zona húmeda artificial que destaca por su temperatura constante, lo que favorece una vegetación palustre hiperdesarrollada con inmensos carrizales y eneas. Al norte, los raros afloramientos de calizas de la zona sustentan una singularidad botánica única: una alta concentración de orquídeas silvestres endémicas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90101','espacio','Sierra de Montánchez (vertiente sur) y canchales graníticos','Escarpada ladera montañosa granítica que desciende hacia la penillanura extremeña, fracturada en grandes bloques y depósitos de ladera (canchales). Alberga comunidades arbustivas mediterráneas adaptadas a suelos esqueléticos, dominadas por la jara pringosa y el cantueso.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10021','espacio','Dehesa de la Luz y charca de la Albuera','Llanura suavemente ondulada sobre pizarras y areniscas del Complejo Esquisto-Quarcítico donde se asienta una dehesa de encinas con ejemplares centenarios. La lámina de agua de la charca naturalizada aporta contraste cromático e hidrófilo al entorno estepario.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10023','espacio','Garganta de los Molinos y vertientes del batolito de Montánchez','Profunda hendidura fluvial excavada sobre granito donde el agua desciende encajonada entre grandes rocas y lanchares lisos. El microclima húmedo del fondo del valle sustenta un frondoso bosque de galería complementado por higueras y robles de gran porte.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10022','espacio','Garganta de la Ventera y riscos graníticos','Fractura tectónica de fuerte pendiente en la vertiente meridional de Gredos por donde bajan aguas de deshielo torrenciales, esculpiendo saltos y pozas profundas de roca pulida. El paisaje vegetal está dominado por densos rebollares y bosques galería de alisos hiperhúmedos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10024','espacio','Surgencias termales y castañar de la Solana','Valle de montaña cerrado sobre el plano de falla que separa la Sierra de Béjar de la de Francia, caracterizado por sus aguas cargadas de minerales. Destacan sus laderas cubiertas por un impresionante castañar (Castanea sativa) de carácter atlántico y notables masas de roble melojo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10025','espacio','Garganta del Obispo y colinas de la Sierra de Tormantos','Relieve abrupto de montaña media granítica que marca la transición entre el Valle del Jerte y la comarca de la Vera. El paisaje visual ofrece un mosaico de bosques de roble rebollo, brezales densos y gargantas estrechas con cascadas estacionales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10026','espacio','Escarpes del río Tajo y dehesas graníticas','Margen escarpada del Tajo donde la erosión ha labrado taludes profundos sobre pizarras y granitos antes de   su encajamiento. La vegetación se compone de masas densas de encina, acebuches y matorral mediterráneo esclerófilo adaptado a la solana. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10027','espacio','Sierra de Montánchez oriental','Vertientes de fuerte pendiente compuestas por granitos fuertemente meteorizados que dan origen a suelos arenosos de sauló y formas redondeadas en las rocas. Cuenta con un encinar mixto con presencia de quejigos en las vaguadas más húmedas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10028','espacio','Cañón del río Tajo (Embalse de Valdecañas) y berrocal de la Peña','Paisaje granítico colosal que ha quedado parcialmente inundado, donde enormes masas rocosas redondeadas asoman en los márgenes de la gran masa de agua. La vegetación rupícola y los matorrales xerófilos colonizan las diaclasas y repisas de la roca desnuda.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10029','espacio','Riscos de la Peña de Francia y Cancho de la Sábana','Espectaculares crestones de cuarcita armoricana que emergen verticalmente como murallas naturales en el corazón del Geoparque Villuercas. Las laderas de umbría albergan un bosque mediterráneo de excepcional estado de conservación con alcornocales, quejigales y densas formaciones de madroños.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10030','espacio','Garganta de las Gualesas y desembocadura del río Ibor','Valle fluvial muy encajonado sobre pizarras y areniscas terciarias con laderas cubiertas de una densa   cubierta de monte mediterráneo puro. El tramo final muestra un paisaje de aguas tranquilas flanqueado por cantiles rocosos donde destacan las comunidades de helechos ripícolas. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10031','espacio','Riberas del río Tamuja y encinares adehesados','Incisión fluvial de pendiente moderada sobre la penillanura de pizarras, donde el río Tamuja ha excavado un lecho rocoso sinuoso. En los márgenes aparecen saucedas de carácter termófilo y tamujos (Flueggea tinctoria) adaptados al estiaje severo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10032','espacio','Greña de Brozas y Charca de la Fontanina','Llanura endorreica y penillanura de pizarras con pequeños humedales someros que rompen la aridez estival. Destaca por sus formaciones de dehesa mixta de encina y alcornoque asentadas sobre suelos esqueléticos arcillosos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10033','espacio','Sinclinal de Cabañas y Peña del Castillo','Uno de los ejemplos de relieve apalachense más perfectos y espectaculares de Europa, donde una cresta cuarcítica vertical y estrecha domina de forma absoluta el paisaje. Las fracturas de la roca y los canchales albergan comunidades botánicas rupícolas especializadas y brezales de alta montaña mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10034','espacio','Robledal de la Resbaladera y escarpes de la Sierra de El Torno','Relieve de alta montaña granítica fracturado por la tectónica del Ambroz, caracterizado por laderas vertiginosas de roca desnuda. Alberga formaciones botánicas puras de roble rebollo y matorral de piornal atlántico en las zonas culminales expuestas al viento.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10035','espacio','Reserva Natural de la Garganta de los Infiernos y garganta de la Puria','Espectacular entorno subalpino granítico donde la dinámica fluvial de torrentera ha labrado colosales marmitas de gigante y saltos de agua cristalina sobre fracturas tectónicas. Las umbrías profundas cobijan formaciones climácicas de melojares, tejos dispersos y acebedas hiperhúmedas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10036','espacio','Garganta de la Sierra y riscos graníticos de Tormantos','Relieve de ladera abrupta esculpido sobre el batolito del Jerte, caracterizado por una densa red de escorrentía superficial de alta energía geomorfológica. Cuenta con extensas masas de roble rebollo que tapizan un accidentado perfil topográfico de gran belleza visual.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10037','espacio','Llanos de Cáceres y Sierra de la Mosca','Extensa penillanura monótona modelada sobre pizarras y calizas que conforma un paisaje estepario único de   lomas suaves y lanchares horizontales. Rompe este relieve el crestón cuarcítico de la Sierra de la Mosca, cubierto por una densa umbría de encinar y jaral silíceo. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10038','espacio','Canchos de Ramiro (Río Alagón)','Imponentes farallones verticales de cuarcita armoricana que encajonan de forma salvaje el curso fluvial del río Alagón, creando una espectacular morfología de desfiladero ciego. Las grietas de la roca albergan comunidades rupícolas raras y las laderas presentan monte mediterráneo termófilo virgen.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10039','espacio','Valles de la Sierra de Gata y río Árrago','Paisaje forestal encajonado en una cubeta tectónica rodeada de relieves graníticos y pizarrosos con pendientes pronunciadas. El lecho del río muestra un bosque galería continuo de alisos y sauces de gran porte botánico que suavizan el relieve abrupto.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10040','espacio','Dehesa boyal y vegas del arroyo de la Carpa','Relieve plano ondulado propio de la cuenca sedimentaria del Alagón, constituido por depósitos de arenas, arcillas y cantos rodados cuaternarios. Conserva manchas relictas de encinar denso y pastizales hidrófilos de carácter estacional.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10041','espacio','Garganta de la Alavea y Chorrero del Tajo','Paisaje abrupto característico del relieve jurásico-hurdano con profundos valles encajados en pizarras y esquistos paleozoicos de acusada inclinación. Destaca el gran   salto de agua intermitente que se desliza por un corte vertical rodeado de madroñales puros y brezales. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10042','espacio','Cañón del río Ibor y Cueva de los Postes','Estrechamiento fluvial colosal excavado sobre calizas eocénicas y dolomías, que expone espectaculares perfiles escarpados y fenómenos de disolución kárstica en forma de cuevas colgadas. Las umbrías profundas albergan una vegetación higrófila mixta de gran singularidad.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10043','espacio','Estepas arcillosas del río Alcollarín','Llanura sedimentaria abierta originada por el desmantelamiento erosivo de materiales finos del Mioceno, creando una topografía casi horizontal. Presenta asociaciones vegetales xerófilas e ibéricas adaptadas a condiciones de aridez edáfica extrema estival.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10044','espacio','Desfiladero del río Ruecas y Cancho del Fresno','Majestuoso cañón apalachense flanqueado por paredes verticales de cuarcita armoricana que muestran un plegamiento tectónico de gran interés didáctico. El fondo de la garganta es un refugio botánico hiperhúmedo que acoge loros (Prunus lusitanica) y helechos relictos del Terciario.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10045','espacio','Puerto de los Castaños y Sierra de Archidona','Alineación montañosa de dirección hercínica definida por crestones cuarcíticos abruptos que se elevan sobre la penillanura pizarrosa. Destaca la exuberante cubierta vegetal de sus umbrías, compuestas por alcornocales maduros, madroños y quejigales densos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10046','espacio','Sierra de Carbajo y Parque Natural Tajo Internacional','Relieve quebrado paleozoico con laderas escarpadas de pizarras y cuarcitas orientadas hacia la cuenca del Tajo. Su gran valor contempla reside en la pureza de sus formaciones forestales mediterráneas de alcornocal y umbrías de madroñal virgen.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10047','espacio','Vegas del río Jerte (tramo bajo)','Llanura aluvial madura caracterizada por depósitos de cantos gruesos y terrazas fluviales estables generadas por la pérdida de gradiente del río Jerte. Las orillas están colonizadas por saucedas y alamedas de gran desarrollo lineal.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10048','espacio','Garganta de San Blas y Sierra de Altamira','Vertiente montañosa fronteriza constituida por potentes estratos de cuarcitas que forman un relieve escarpado de dientes de sierra. La ladera está tapizada por inmensos jarales pringosos y encinares montanos que colonizan los canchales de piedras sueltas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10049','espacio','Charca del Casar y dehesas graníticas','Superficie de erosión horizontal interrumpida por pequeñas depresiones endorreicas sobre materiales detríticos finos. La lámina de agua de la charca aporta diversidad visual a un entorno de pastizales secos y encinas dispersas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10050','espacio','Sierra de Santa Bárbara y valles del río Ángeles','Paisaje accidentado de transición hurdana con un relieve de lomas afiladas compuestas por pizarras fuertemente plegadas y meteorizadas. Las laderas orientadas al norte conservan manchas de rebollar e importantes brezales arborescentes de gran densidad.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10051','espacio','Cabecera del río Hurdano y saltos de agua de la Huetre','Imponente anfiteatro montañoso de la cordillera Cantábrico-Central, donde el relieve pizarroso se fractura en pendientes casi verticales de extrema fragilidad erosiva. El paisaje visual está definido por profundos valles en V con cascadas de agua pura sobre la roca desnuda.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10058','espacio','Dehesa de Arañuelo y arroyo de Tejadilla','Llanura ondulada de la fosa del Tiétar asentada sobre sedimentos arenoso-arcillosos terciarios bien estabilizados. Cuenta con formaciones forestales abiertas de encina y alcornoque con un estrato herbáceo adaptado a suelos silíceos de ladera.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10059','espacio','Riberas del arroyo de la Macquilla','Relieve de penillanura baja arcillosa rota de forma suave por la incisión de arroyos estacionales de caudal irregular. La vegetación natural es arbustiva mediterránea, destacando jarales menores y tamujares en el cauce de la corriente.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10060','espacio','Cueva del Castañar y Camocho (Sierra de los Ibores)','Fenómeno geológico subterráneo excepcional consistente en una cueva kárstica en dolomías que alberga   las agujas y excéntricas de aragonito más puras de la península. En el exterior, el relieve apalachense presenta escarpes majestuosos cubiertos de castañares centenarios y quejigales de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10061','espacio','Canchos de la Barca y cañón del río Alagón','Imponente encajamiento fluvial donde el río corta de forma transversal las estructuras pizarrosas de la penillanura antes de su unión con el Tajo. Las laderas presentan paredes escarpadas recubiertas de monte mediterráneo puro, acebuches y grandes extensiones de jara pringosa.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10062','espacio','Parque Natural Tajo Internacional y desembocadura del río Sever','Último tramo del cañón fluvial del Tajo en territorio español, caracterizado por profundos desfiladeros de pizarras paleozoicas fuertemente fracturadas. Las umbrías albergan una riquísima flora de carácter termófilo con densos madroñales, alcornoques y comunidades botánicas rupícolas singulares.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10063','espacio','Dehesas del río Palomero y lomas pizarrosas','Relieve ondulado labrado sobre el complejo esquisto-quarcítico que define el paisaje de la comarca de Tierras de Granadilla. Presenta formaciones de dehesa de encina bien conservadas con un sotobosque dominado por cantuesos y jaras.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10064','espacio','Sierra de Trevejo (vertiente sur) y dehesas de alcornoque','Suaves rampas montañosas que descienden desde la Sierra de Gata orientadas a mediodía, constituidas por sustratos graníticos meteorizados. Alberga masas   forestales densas de alcornoque (Quercus suber) de gran porte botánico combinadas con brezales arborescentes. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10066','espacio','Garganta de Conquista y dehesas del batolito de Trujillo','Paisaje de penillanura granítica interrumpido por una modesta fractura tectónica que genera una pequeña garganta con bloques redondeados. La vegetación está constituida por un encinar aclarado y pastizales mediterráneos que cubren los suelos arenosos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10067','espacio','Riberas e islas del río Alagón y llanura aluvial','Amplia vega cuaternaria donde la dinámica divagante del río Alagón ha generado un sistema de terrazas de arenas y cantos rodados. Conserva magníficas alamedas y saucedas que tapizan los meandros y los márgenes fluviales inundables.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10068','espacio','Garganta de Cuacos y paraje de las Ollas','Desfiladero granítico en la ladera meridional de la Sierra de Gredos, donde la erosión fluvial ha excavado ollas y marmitas de gigante de roca pulida. El microclima húmedo de la zona sustenta un denso bosque de roble rebollo, castaños y fresnedas de ribera.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10069','espacio','Berrocal de La Cumbre y dehesas de pizarra','Llanura suavemente ondulada caracterizada por la transición litológica entre las pizarras y pequeños afloramientos graníticos aislados. Muestra una topografía de bolos pétreos dispersos rodeados de pastizales secos mediterráneos de carácter estacional.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10070','espacio','Brechas de Deleitosa y Sierra de la Calderana (Geoparque Villuercas)','Espectaculares formaciones geológicas de relieve apalachense con crestones de cuarcita armoricana que surcan el territorio como murallas paralelas. Las laderas umbrías acogen una densa mancha de monte mediterráneo húmedo rica en madroños, quejigos y brezales de montaña.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10071','espacio','Valle alto del río Árrago y Chorrito de los Ángeles','Angosto valle de montaña en la Sierra de Gata con laderas pizarrosas de pendientes vertiginosas que sufren una fuerte erosión hídrica. Destaca el gran salto de agua intermitente que se precipita sobre la roca desnuda, rodeado de melojares y densos brezales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10072','espacio','Valle de Jálama y riscos de las Eljas','Majestuoso anfiteatro montañoso coronado por el pico Jálama, compuesto por granitos y pizarras que generan un relieve abrupto y accidentado. El paraje destaca por sus frondosos bosques de castaños y robles melojos favorecidos por una alta pluviometría de influencia atlántica.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10073','espacio','Riberas del río Alcollarín y dehesas arcillosas','Relieve plano ondulado propio de la cuenca sedimentaria del Guadiana, constituido por depósitos arcilloarenosos miocénicos. Cuenta con formaciones forestales aclaradas de encina y comunidades vegetales hidrófilas en los márgenes de los arroyos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10075','espacio','Desfiladero del río Ibor y Cueva del Alcaide','Estrechamiento fluvial flanqueado por cantiles de calizas y dolomías que muestran fenómenos de disolución kárstica superficial. Las laderas escarpadas están colonizadas por masas densas de monte mediterráneo, acebuches y matorrales calcícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10076','espacio','Meandros y terrazas del río Jerte','Amplia llanura de inundación fluvial constituida por arenas gruesas y cantos rodados cuaternarios depositados al perder gradiente el río Jerte. En sus márgenes se desarrollan franjas estables de bosque de ribera dominadas por alisos, sauces y grandes alamedas naturales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10077','espacio','Sierra de Garciaz y Venero de la Presa','Relieve de media montaña integrado en el macizo de las Villuercas, caracterizado por crestones cuarcíticos y valles sinclinales paralelos. Sus laderas de umbría están cubiertas por frondosos e imponentes bosques de roble rebollo (Quercus pyrenaica) y castañares protegidos de gran valor botánico.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10079','espacio','Garganta Mayor y pilonas de las Calderas','Espectacular desfiladero de alta montaña labrado sobre el batolito granítico de la Sierra de Tormantos, donde la dinámica torrencial ha esculpido pilonas gigantes y marmitas de erosión circular profunda. El entorno es un denso refugio forestal umbrío compuesto por melojares climácicos y alisedas hiperhúmedas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10080','espacio','Garganta de Honduras y castañares de la umbría','Profundo valle encajado de origen tectónico que comunica las cuencas del Ambroz y del Jerte sobre un relieve abrupto de pizarras y granitos. Destaca por albergar masas boscosas puras y densas de castaño (Castanea sativa) y roble melojo que tapizan laderas de vertiginosa pendiente.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10084','espacio','Sierra de Gata (Pico Jálama) y garganta de la Presa','Majestuoso anfiteatro montañoso caracterizado por un relieve de fuertes desniveles, fallas tectónicas y fracturas sobre rocas plutónicas. La influencia climática atlántica favorece la proliferación de frondosos bosques mixtos de roble rebollo, castaños maduros y una densa vegetación criptogámica de musgos y helechos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10085','espacio','Dehesas colonizadas e islas del Embalse de Valdecañas','Paisaje penillanurero compuesto por materiales arenoso-arcillosos sedimentarios que ha quedado parcialmente sumergido, aislando colinas graníticas en forma de islas. Cuenta con dehesas maduras de encina y alcornoque adaptadas a suelos silíceos ligeros que bordean la gran masa de agua.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10086','espacio','Península del Embalse de Gabriel y Galán y vegas del río Alagón','Relieve de penillanura pizarrosa fuertemente erosionada y lobulada por la sobreelevación de las aguas de la cuenca fluvial del Alagón. Presenta dehesas abiertas de encina e interesantes formaciones de matorral esclerófilo mediterráneo (jara y cantueso) adaptadas a la escasez hídrica estival.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10087','espacio','Pico de la Villuerca y garganta del río Guadalupejo','Máxima elevación del Geoparque VilluercasIbores-Jara, constituida por un imponente crestón de cuarcita armoricana erosionado bajo un modelo morfológico apalachense. Las laderas y fondos de valle albergan bosques relictos del Terciario, con presencia de loros (Prunus lusitanica), quejigales húmedos y densos helechales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10088','espacio','Lomas del río Alagón y dehesa boyal','Superficie horizontal suavemente ondulada labrada sobre el complejo esquisto-quarcítico que define la penillanura noroccidental. Alberga formaciones forestales   aclaradas de encina y pastizales secos continentales que tapizan suelos esqueléticos. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10089','espacio','Arroyo de la Canaleja y dehesas de alcornoque','Relieve ondulado sobre depósitos detríticos y pizarras paleozoicas en la transición hacia la cuenca del Alagón. La vegetación predominante está constituida por pequeños rodales de alcornoques bien estructurados y jarales mixtos mediterráneos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10090','espacio','Pantano de Gabriel y Galán y meandro del río Alagón','Paisaje geomorfológico abrupto donde el río Alagón se encajona de manera sinuosa sobre materiales pizarrosos antes de la llanura sedimentaria. Los márgenes del cauce exponen perfiles de roca desnuda flanqueados por densos jarales pringosos y encinares de monte mediterráneo virgen.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10091','espacio','Garganta de Jaranda y Portilla de Jaranda','Desfiladero de alta montaña de pendientes alpinas modelado sobre granitos de la Sierra de Gredos, con fracturas verticales por donde bajan aguas cristalinas de deshielo. Alberga comunidades botánicas de piornal, pastizales de cumbre y bosques umbríos de roble rebollo excelentemente conservados.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10092','espacio','Berrocal de Herguijuela y dehesas del batolito de Trujillo','Relieve de penillanura granítica caracterizado por la presencia de bolos redondeados, piedras caballeras y lanchares horizontales expuestos a la meteorización física. La   cubierta vegetal se limita a encinares aclarados y matorral bajo de cantueso. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10093','espacio','Sierra de las Mesas y cuenca del río Árrago','Lomas de pizarras fuertemente plegadas y fracturadas que configuran el relieve premontano de la Sierra de Gata. Muestra una densa cubierta arbustiva mediterránea dominada por la jara pringosa, el brezo blanco y pequeñas agrupaciones de encinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10094','espacio','Cañón del río Tajo e interior del Parque Natural Tajo Internacional','Imponente corte fluvial excavado de manera salvaje sobre pizarras paleozoicas con laderas que superan los 150 metros de desnivel. El microclima luso-extremeño favorece una cobertura densa y virgen de acebuches, alcornoques, densos madroñales y enebros de gran porte.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10095','espacio','Sierra de San Pedro y riberas del río Salor','Relieve de herradura compuesto por crestones de cuarcita armoricana y valles paralelos rellenos de pizarras meteorizadas. Destaca por sus umbrías de bosque mediterráneo climácico con alcornocales hiperdensos, madroños de porte arbóreo y brezales arborescentes.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10096','espacio','Castañar de la Amorosa, monte de El Pinajarro y nacimiento del río Ambroz','Uno de los bosques de castaño (Castanea sativa) más extensos, densos y puros de la Europa meridional, asentado sobre la ladera granítica y húmeda de la Sierra de Béjar [Hervás]. El relieve alpino incluye pedrizas, circos glaciares relictos en las cumbres y un bosque galería alpino excelente.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12069','espacio','Garganta de los Frailes y Parque Nacional de Monfragüe','Estrechamiento geomorfológico espectacular de la cuarcita donde la erosión lineal ha labrado cantiles rocosos totalmente verticales. La vegetación está dominada por masas densas de monte mediterráneo de umbría, con quejigos, alcornoques, madroños y vegetación rupícola especializada.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10098','espacio','Vegas del río Almonte y escarpes pizarrosos','Tramo donde el encajamiento del río Almonte secciona la penillanura pizarrosa cacereña originando profundas pendientes abruptas. Muestra una vegetación xerófila dominada por cantuesares, jarales de jara pringosa y tamujares adaptados a la dinámica torrencial del cauce.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10099','espacio','Vegas del río Alagón y lomas arcillosas','Paisaje horizontal ondulado constituido por terrazas aluviales de cantos rodados y arenas miocénicas de la cuenca baja del Alagón. Conserva formaciones aclaradas de encina y pastizales estacionales mediterráneos adaptados a la sequedad estival.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10100','espacio','Sierra de Dios Padre y fuentes del arroyo de la Cochina','Paisaje forestal premontano en el corazón de la Sierra de Gata, modelado sobre granitos fracturados con un fuerte gradiente de escorrentía superficial. Sus laderas de umbría albergan densas masas mixtas de roble rebollo, castaños maduros y una rica cobertura de helechales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10101','espacio','Confluencia del río Árrago con el arroyo de Patana','Llanura aluvial de inundación caracterizada por depósitos detríticos cuaternarios finos en un relieve suavemente plano. Los márgenes fluviales sostienen un denso pasillo vegetal con saucedas arbustivas, alamedas y juncales palustres de buena conservación.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10102','espacio','Berrocal de Ibahernando y lanchares del río Tamuja','Llanura de erosión granítica caracterizada por la abundancia de bolos redondeados, piedras caballeras y extensas superficies de roca lisa expuestas al sol. La vegetación es un encinar adehesado ralo complementado por pastizales secos continentales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10103','espacio','Puerto de Miravete y gargantas del río Almonte','Espectacular relieve quebrado donde las cuarcitas armoricanas forman crestones afilados de dirección hercínica. La bajada hacia el río Almonte ofrece un impresionante dosel vegetal mediterráneo con densas manchas de alcornoque, madroñales puros y quejigales en las vaguadas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10104','espacio','Garganta de Pedro Chate y paraje de las Pilas','Cañón granítico profundo en la vertiente meridional de Gredos, donde el agua del deshielo ha pulido grandes bloques y labrado pozas profundas y marmitas de gigante. Cuenta con frondosos bosques de galería con alisos, fresnos de gran porte y laderas cubiertas de rebollares.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10105','espacio','Garganta de Jaranda y riscos del Guijo','Angosto y vertiginoso desfiladero de alta montaña excavado sobre granito, por donde bajan aguas gélidas de gran energía fluvial. El entorno botánico presenta un magnífico estado de conservación, dominado por quejigales, robledales de melojo y piornales en las zonas más elevadas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10107','espacio','Garganta de los Infiernos (acceso norte) y Reserva Natural del Valle del Jerte','Espectacular modelado glaciar y de torrentera fluvial granítica, célebre por el paraje de Los Pilones y sus marmitas de gigante perfectamente cilíndricas. Alberga bosques climácicos de roble rebollo, acebedas espesas, tejos residuales y un denso bosque galería alpino de aliso hiperhúmedo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10108','espacio','Valles del río Ladrillar, Meandro del Melero (límite oriental) y cascadas de las Mestas','El relieve pizarroso más abrupto y espectacular de las Hurdes, caracterizado por profundos cañones en V y laderas de pendientes imposibles de esquistos brillantes. La dinámica hídrica genera espectaculares saltos de agua y el majestuoso estrangulamiento fluvial que bordea la sierra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10109','espacio','Cerro de San Cristóbal y batolito granítico de Logrosán','Relieve de domo o "isla geológica" granítica que emerge con fuerza sobre la penillanura pizarrosa circundante, rico en filones de fosfatos. La meteorización genera grandes bloques redondeados rodeados de dehesas mixtas de encina y un estrato arbustivo de jara pringosa.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10110','espacio','Garganta de Cuartos y garganta de Vadillo','Impresionante desfiladero de alta montaña granítica donde las aguas de deshielo de Gredos caen con gran energía geomorfológica, labrando pozas de roca pulida y grandes depósitos de cantería aluvial. Alberga frondosos melojares en las umbrías y un bosque de ribera hiperhúmedo dominado por alisos monumentales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10111','espacio','Garganta de Alardos y laderas meridionales de Gredos','Angosto y profundo tajo fluvial esculpido sobre el batolito granítico que marca el límite oriental de la comarca, caracterizado por sus colosales cantos rodados pulidos y grandes badenes de agua. La vegetación destaca por brezales arborescentes altos, madroñales y robledales de roble melojo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10113','espacio','Berrocal de Madroñera y dehesas del río Magasca','Paisaje penillanurero dominado por la alteración química del granito, que genera formaciones de bolos y tors rocosos esparcidos entre la llanura. Cuenta con dehesas maduras de encina y alcornoque bien conservadas que se encajan hacia las vertientes del río Magasca.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10115','espacio','Monumento Natural de Los Barruecos','Paisaje geológico espectacular y único de relieves graníticos globulares, donde la erosión ha esculpido grandes domos, bolos basales y cavidades alveolares (taffoni) que bordean charcas naturalizadas. Botánicamente destaca por su flora de líquenes crustáceos rupícolas y pastizales mediterráneos adaptados al lanchar pétreo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10116','espacio','Umbría de Barbaón y dehesas de Monfragüe','Extensas dehesas de alcornoque y encina asentadas sobre relieves suaves pizarrosos que sirven de antesala al espacio protegido de Monfragüe. El paraje destaca por la densidad y pureza de su monte mediterráneo de transición, enriquecido con jarales y brezales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10117','espacio','Sierra de Santa Bárbara y olivares de montaña pizarrosa','Vertientes premontanas escarpadas constituidas por materiales pizarrosos fragmentados que generan relieves de crestas suaves pero continuas. Conserva retazos de rebollares y densos matorrales de ladera dominados por brezos de escobas y madroñales relictos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10118','espacio','Dehesa Boyal de la Mata y riberas del arroyo de la Jarda','Relieve ondulado de la penillanura pizarrosa cacereña caracterizado por un encinar y alcornocal maduro en régimen de explotación adehesada tradicional. El arroyo local genera una pequeña incisión con afloramientos de esquistos y comunidades de tamujos resistentes a la sequía estival.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10119','espacio','Sierra de Membrío y riberas del río Salor (Tajo Internacional)','Alineaciones de lomas paleozoicas compuestas por cuarcitas y pizarras que dan lugar a valles encajados menores. Las zonas de umbría están cubiertas por una densa mancha de monte mediterráneo denso con madroños arbóreos, alcornoques e importantes brezales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10120','espacio','Garganta de los Ibores y riscos de la Mesa','Estrechamiento geológico colosal flanqueado por altos paredones de calizas y dolomías que marcan el curso encajonado del río Ibor. La disolución kárstica genera oquedades y relieves escarpados cubiertos por un dosel denso de encinas, quejigos y comunidades rupícolas basófilas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10121','espacio','Vegas del río Búrdalo y llanuras arenosas','Relieve predominantemente llano constituido por depósitos de arenas, arcillas y terrazas cuaternarias en el límite sur de la provincia. Muestra formaciones de matorral mediterráneo degradado y pequeñas bandas de vegetación riparia con sauces en el eje fluvial.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10122','espacio','Dehesa de Millanes y vegas del arroyo de la Canaleja','Llanura sedimentaria ondulada de la fosa del Tiétar compuesta por arenas arcillosas de origen terciario. Alberga dehesas de encina aclaradas con un estrato herbáceo adaptado a suelos silíceos ligeros y zonas de escorrentía estacional.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10123','espacio','Sierra de Mirabel y umbría del Castillo','Estructura montañosa de dirección hercínica con crestones de cuarcita armoricana que rompen el relieve penillanurero. Destaca por albergar un alcornocal y quejigal de umbría excepcionalmente denso, húmedo y bien conservado, con ejemplares monumentales de madroños.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10124','espacio','Dehesas del río Palomero y lomas de Granadilla','Suaves ondulaciones labradas sobre el Complejo Esquisto-Quarcítico que definen el paisaje premontano septentrional. El territorio está cubierto por formaciones forestales adehesadas de encina y extensos jarales de jara pringosa que colonizan los suelos esqueléticos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10125','espacio','Confluencia del río Almonte con el río Tamuja y escarpes de Monroy','Impresionante encajamiento fluvial de pendientes abruptas sobre la penillanura pizarrosa cacereña, donde los ríos cortan la roca de forma sinuosa. Las laderas expuestas a la solana albergan acebuches, encinares y tamujares adaptados a la escorrentía torrencial.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10126','espacio','Canchales de la Sierra de Montánchez y nacimiento del río Salor','Batolito granítico de gran altitud relativa que emerge como un gigantesco espigón rocoso sobre la penillanura cacereña, fracturado en grandes bloques y pedrizas de ladera. Sus umbrías acogen bosques mixtos de castaño, quejigos y melojares favorecidos por las nieblas orográficas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10127','espacio','Dehesa Boyal de Montehermoso y charcas graníticas','Relieve de penillanura suavemente ondulada modelado sobre granitos degradados y pizarras terciarias, donde existen pequeñas cubetas endorreicas estacionales. Cuenta con un encinar adehesado maduro excelentemente estructurado con comunidades de pastizales vivaces.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10128','espacio','Riberas e islas del río Árrago y vegas del Alagón','Amplia llanura aluvial cuaternaria baja compuesta por limos y arenas arrastrados desde la Sierra de Gata. El cauce fluvial presenta un excelente ecosistema ripícola con alisedas densas, alamedas y saucedas que estabilizan las barras sedimentarias del río.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10129','espacio','Vegas del río Alagón y lomas de arcilla','Paisaje horizontal ondulado de la cuenca sedimentaria del Alagón, constituido por depósitos de terrazas aluviales con cantos rodados. Conserva manchas relictas de encinar aclarado y pastizales estacionales adaptados a la acusada sequedad estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10130','espacio','Garganta de las Nogaledas y curso alto del río Jerte','Impresionante desfiladero granítico caracterizado por una sucesión vertical de cascadas caudalosas encajadas en una fractura tectónica de fuerte gradiente. El microclima umbrío da lugar a un frondoso bosque galería subatlántico con alisos, fresnos de gran porte y abundantes helechales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10131','espacio','Dehesas de Campo Arañuelo y charcas arcillosas','Llanura sedimentaria ondulada constituida por depósitos detríticos del Terciario donde el agua de escorrentía genera pequeñas lagunas estacionales. Acoge un encinar adehesado ralo adaptado a los suelos silíceos profundos de la cuenca.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10132','espacio','Chorrera de Mojón Blanco y desfiladero del río Ibor','Espectacular salto de agua que se desliza de forma encajada sobre las verticales crestas de cuarcita armoricana de las Villuercas. La umbría de la ladera destaca por una mancha climácica de monte mediterráneo con madroños arbóreos, loros y castañares.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10133','espacio','Berrocal de las Navas y charca de las Dehesillas','Topografía penillanurera interrumpida por afloramientos de granito erosionado en forma de bolos, lanchares pulidos y piedras caballeras. Presenta comunidades arbustivas de jara pringosa y cantueso junto a cubetas endorreicas estacionales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10134','espacio','Nacimiento del río Almonte y escarpes de las Villuercas','Cabecera de valle de montaña de relieve apalachense con grandiosos farallones de cuarcita y laderas cubiertas de potentes pedrizas o canchales de coluvión. El paraje alberga bosques de galería hiperhúmedos con acebedas, melojos y comunidades rupícolas raras.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10136','espacio','Dehesas del arroyo de la Oliva y colinas graníticas','Relieve ondulado premontano labrado sobre materiales plutónicos degradados en la antesala de las tierras altas de Traslasierra. La cubierta forestal está constituida por un encinar mixto de gran espesor y matorral mediterráneo esclerófilo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10137','espacio','Sierra de la Cruz y valles de pizarra','Relieve accidentado de colinas quebradas compuestas por pizarras paleozoicas fuertemente plegadas en el límite norte provincial. Las vertientes umbrías conservan pequeños bosquetes de roble rebollo y densas masas de brezo de escobas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10138','espacio','Garganta de Pasarón y vertientes del pico Pitolero','Abrupta ladera montañosa granítica con acusados desniveles morfológicos e intensa fracturación tectónica en el sector occidental de la Vera. El paisaje visual está definido por frondosos e imponentes castañares mixtos y quejigales de umbría.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10139','espacio','Sierra de la Concha y umbría de El Palancar','Angosto pliegue cuarcítico que emerge de la penillanura pizarrosa generando laderas umbrías resguardadas de fuertes vientos. Alberga una de las manchas de monte mediterráneo mixto más densas de Extremadura, rica en alcornoques, madroños y durillos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10140','espacio','Vegas del Tajo y berrocal de Valparaíso','Paisaje granítico parcialmente anegado por el embalse de Valdecañas, donde enormes bloques redondeados asoman en la orilla de la masa de agua. Cuenta con vegetación esclerófila mediterránea y pastizales heliófilos sobre arenas de descomposición granítica.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10141','espacio','Desfiladero del río Gualija y canchales del Tajo','Profunda incisión lineal excavada por el río Gualija sobre pizarras y areniscas terciarias antes de su desembocadura. Presenta paredes escarpadas cubiertas por   una masa virgen de monte mediterráneo con acebuches, enebros y jarales densos. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10142','espacio','Sierra de Gata y cañón del río Acebo','Estrechamiento fluvial encajado de manera sinuosa sobre materiales graníticos con un relieve de vertientes de fuerte gradiente. Los márgenes del cauce exponen perfiles de roca desnuda flanqueados por melojares y densos matorrales atlánticos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10146','espacio','Garganta de los Ángeles y Chorrera de Ovejuela','Uno de los paisajes más salvajes y escarpados de las Hurdes, con valles profundos en V excavados en pizarras lustrosas y espectaculares cascadas de gran altura. Destaca el aislamiento geográfico de sus laderas tapizadas por madroñales puros y brezales gigantes.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10147','espacio','Garganta de Bohonal y lanchares del altiplano','Situado en la cota más elevada de Extremadura sobre un altiplano granítico, presenta una morfología de rocas desnudas fracturadas por procesos periglaciares relictos. La vegetación está dominada por piornales alpinos, piornos y pastizales de cumbre resistentes a heladas severas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10148','espacio','Garganta de Valcorchero y cañón del río Jerte','Paisaje granítico colosal caracterizado por un relieve de lanchares asimétricos, bolos y tors que flanquean el estrechamiento fluvial del Jerte. Alberga un alcornocal de ladera excepcional desarrollado directamente sobre suelos arenosos esqueléticos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10149','espacio','Riberas del río Tamuja y lomas de pizarra','Relieve de penillanura baja arcillosa rota de forma suave por la incisión de arroyos estacionales de caudal irregular. La vegetación natural es arbustiva mediterránea, destacando jarales menores y tamujares en el cauce de la corriente.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10150','espacio','Rivera de Gata y vaso del embalse de Portaje','Depresión erosiva suave sobre materiales finos miocénicos en el centro de la cuenca sedimentaria del Alagón. Presenta retazos residuales de matorral espinoso mediterráneo y humedales someros de gran interés palustre.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10151','espacio','Crestones de la Sierra del Arquillo','Relieve de agudos dientes de sierra formados por cuarcitas armoricanas alineadas por empujes hercínicos tectónicos. Las umbrías de la sierra están cubiertas por densos alcornocales maduros y jarales de jara pringosa que colonizan los canchales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10152','espacio','Lomas del arroyo de las Herrerías y dehesas','Superficie de erosión horizontal suavemente ondulada labrada sobre el complejo esquisto-quarcítico que define la penillanura noroccidental. Alberga formaciones forestales aclaradas de encina y pastizales secos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10153','espacio','Sierra de Santa Cruz (vertiente norte) y pedrizas','Prominente muela de cuarcita que se eleva de manera abrupta como un relieve testigo sobre la penillanura arcillosa de Trujillo. Las laderas acumulan importantes coluviones de piedras sueltas colonizados por encinas y matorrales heliófilos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10154','espacio','Garganta de la Puria y laderas graníticas del Jerte','Paisaje forestal de vertiente abrupta esculpido sobre el batolito del Jerte, caracterizado por una densa red de escorrentía superficial de alta energía geomorfológica. Cuenta con extensas masas de roble rebollo que tapizan un accidentado perfil topográfico de gran belleza visual.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10155','espacio','Terrazas del río Alagón y llanura arcillosa','Paisaje de campiña ondulada modelado sobre margas y arcillas del neógeno, caracterizado por laderas de suave pendiente. En los márgenes del cauce intermitente se desarrollan pequeñas choperas de crecimiento espontáneo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10159','espacio','Sinclinal de Robledollano y desfiladero del río Ibor','Relieve estructural de valle colgado o sinclinal flanqueado por crestones de cuarcitas armoricanas del Geoparque Villuercas. Sus vertientes albergan masas boscosas densas de roble rebollo, alcornocales y quejigales de transición de gran valor botánico.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10156','espacio','Valle alto del río Árrago y saltos del Chorrillo','Angosto y vertiginoso desfiladero de montaña en la Sierra de Gata con laderas pizarrosas de pendientes vertiginosas que sufren una fuerte erosión hídrica. Destaca el paisaje fluvial encajonado rodeado de melojares y densos brezales de montaña.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10157','espacio','Garganta de la dehesa y laderas de Gredos','Relieve de media montaña forestal con valles angostos excavados en materiales graníticos en la ladera sur de la sierra. El paisaje visual está definido por densos quejigales y rebollares que cubren las laderas orientadas al norte.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10158','espacio','Lomas del río Magasca y dehesas pizarrosas','Suaves ondulaciones del terreno que marcan la divisoria de aguas sobre el sustrato esquistoso de la penillanura trujillana. Destacan las formaciones de encinar aclarado con pastizales mediterráneos que fijan el suelo esquelético.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10160','espacio','Garganta de la Canaleja y escarpes del río Tajo (Monfragüe oriental)','Imponentes farallones de cuarcita y laderas pizarrosas que encajonan el curso fluvial del Tajo, creando una espectacular morfología de desfiladero abrupto. Las umbrías profundas albergan un bosque mediterráneo de excepcional estado de conservación con madroñales puros.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10901','espacio','Riberas del río Tiétar y llanura aluvial','Llanura de inundación cuaternaria baja compuesta por sedimentos finos, limos y arenas de la fosa del Tiétar. Presenta formaciones estables de sauces arbustivos y pastizales hidrófilos adaptados al régimen estacional del río.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10161','espacio','Penillanura del arroyo de Santa Ana','Suave depresión erosiva menor labrada sobre arcillas miocénicas de la cuenca central burgalesa-cacereña. El fondo del vallejo acoge comunidades vegetales hidrófilas estacionales y sauces de porte arbustivo alineados con el nivel freático.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10162','espacio','Sierra de Torrico y alcornocales de la Sierra de San Pedro','Formación montañosa paleozoica caracterizada por crestones de cuarcita alineados y valles paralelos rellenos de pizarras. Su valor contemplativo reside en la exuberante densidad de sus bosques mediterráneos de umbría, repletos de madroños y alcornoques.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10163','espacio','Berrocal de Salvatierra y dehesas de la penillanura','Paisaje penillanurero modelado sobre un batolito granítico donde abundan los bolos, piedras caballeras y lanchares pulidos por meteorización química. Cuenta con dehesas de encina aclaradas con un estrato arbustivo de cantueso.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10164','espacio','Castañar de los Ojestos y vertientes del Pico Jálama','Majestuoso anfiteatro montañoso que alberga uno de los bosques de castaño (Castanea sativa) más puros y húmedos de la vertiente atlántica extremeña. El relieve es accidentado y granítico, con abundantes arroyos de aguas gélidas cristalinas y vegetación criptogámica densa.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10165','espacio','Sierra de Santa Ana y dehesas de pizarra','Relieve de crestón cuarcítico correspondiente a la orogenia hercínica que rompe la monotonía de la penillanura cacereña. Su vertiente norte acoge un encinar denso con madroños y jarales asentados sobre suelos pardos silíceos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10166','espacio','Sierra de Santa Cruz y canchales de la umbría','Imponente cerro testigo calizo y cuarcítico que se eleva de forma abrupta sobre la llanura trujillana, fracturado en grandes bloques y depósitos de ladera (canchales). Alberga comunidades arbustivas mediterráneas adaptadas a suelos esqueléticos, dominadas por la jara y el cantueso.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10167','espacio','Sierra de Dios Padre (vertiente norte) y dehesas del rillón','Valle encajonado excavado por la red hidrográfica sobre pizarras, mostrando llamativos perfiles asimétricos y afloramientos rocosos agudos. Destaca botánicamente por albergar manchas densas de monte mediterráneo con encinares maduros.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10168','espacio','Cañón del río Magasca y escarpes pizarrosos','Impresionante encajamiento fluvial de pendientes abruptas sobre la penillanura pizarrosa cacereña,   donde el río corta la roca de forma sinuosa. Las laderas expuestas albergan acebuches, encinares y tamujares adaptados a la escorrentía torrencial. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10169','espacio','Berrocal de las Candelas y Parque Natural Tajo Internacional','Paisaje granítico y pizarroso colosal caracterizado por profundos desfiladeros de pizarras paleozoicas fuertemente fracturadas en las márgenes del Tajo. Las umbrías albergan una riquísima flora de carácter termófilo con densos madroñales y alcornoques.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10170','espacio','Llanos de Santiago y riberas del río Almonte','Extensa penillanura monótona modelada sobre pizarras que conforma un paisaje estepario único de lomas suaves y lanchares horizontales. El río genera una pequeña banda de vegetación hidrófila que contrasta estacionalmente con la aridez.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10171','espacio','Sierra de Gata y escarpes del embalse de Borbollón','Prominente elevación granítica que domina la cuenca baja del Alagón, con vertientes de fuerte pendiente erosionadas por la red fluvial. Las laderas de umbría están tapizadas por inmensos jarales y encinares montanos que colonizan la roca.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10172','espacio','Lomas del río Ahigal y dehesas arcillosa','Relieve ondulado sobre materiales blandos de tipo arcillo-yesífero que genera una suave topografía de colinas y pequeñas vaguadas. Cuenta con retazos de encinar mediterráneo y pastizales de carácter estepario.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10173','espacio','Parque Ornitológico de Arrocampo y humedales palustres','Zona húmeda artificial de vital importancia conformada por lagunas someras, inmensos carrizales y eneas favorecidas por la temperatura constante del agua. La vegetación palustre constituye un ecosistema de altísima singularidad botánica en la comarca.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10174','espacio','Garganta de Segura y castañares de la umbría de la sierra','Escarpada ladera montañosa granítica de la Sierra de Béjar, fracturada en grandes bloques y depósitos de ladera (canchales) con un fuerte gradiente hídrico. Alberga masas forestales densas de castaño de gran porte botánico combinadas con rebollares.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10175','espacio','Salto del Gitano (Peña Falcón) y Parque Nacional de Monfragüe','Uno de los fenómenos geomorfológicos y paisajísticos más impactantes de la península, donde una descomunal masa vertical de cuarcita armoricana corta transversalmente el río Tajo. Las grietas de las paredes rocosas desnudas albergan comunidades rupícolas especializadas únicas del monte mediterráneo climácico.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10176','espacio','Dehesa de Serrejón y contrafuertes de Monfragüe','Extensas dehesas de alcornoque y encina asentadas sobre relieves suaves pizarrosos con un sotobosque dominado por jarales de jara pringosa. El paisaje   destaca por la pureza de sus formaciones forestales mediterráneas de transición. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10177','espacio','Crestón de la Sierra de Fuentes y lanchares graníticos','Alineación montañosa de dirección hercínica definida por crestones cuarcíticos abruptos que emergen de forma aislada en los Llanos de Cáceres. Cuenta con un encinar mediterráneo mixto y matorrales xerófilos adaptados a suelos esqueléticos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10178','espacio','Dehesas del río Almonte y escarpes del Tajo','Margen escarpada de la cuenca fluvial donde la erosión ha labrado taludes profundos sobre pizarras antes de su encajamiento lineal. La vegetación se compone de masas densas de encina, acebuches y matorral mediterráneo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10179','espacio','Garganta de Guijo de Santa Bárbara y riscos de Gredos','Desfiladero granítico profundo en la vertiente meridional de la sierra, donde el agua de deshielo ha pulido grandes bloques de piedra. Cuenta con frondosos bosques de galería con alisos, fresnos de gran porte y laderas cubiertas de rebollares.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10180','espacio','Pinar de Talayuela y humedales del Tiétar','Amplia llanura aluvial sedimentaria en la fosa del Tiétar caracterizada por un excepcional bosque relicto de pino piñonero asentado sobre arenas areno-arcillosas. Las zonas bajas presentan pequeñas depresiones con encharcamiento estacional y comunidades de vegetación palustre.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10181','espacio','Dehesas del río Tiétar y garganta de Tejedilla','Relieve ondulado de transición en la fosa del Tiétar compuesto por arenas arcillosas de origen terciario bien estabilizadas. Alberga dehesas de encina y alcornoque con un estrato herbáceo adaptado a suelos silíceos ligeros.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10182','espacio','Reserva de la Biosfera de Monfragüe y dehesa de la Herguijuela','Considerado uno de los alcornocales adehesados más puros, densos y monumentales de la península ibérica, asentado sobre llanuras sedimentarias del Tiétar. El dosel arbóreo cuenta con ejemplares centenarios colosales rodeados de espesas masas de jara y lentisco.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10183','espacio','Cabecera del río Jerte y garganta de los Infiernos (vertiente oriental)','Espectacular entorno de alta montaña granítica con modelado glaciar y periglaciar en las cumbres calcáreas y esquistosas de Gredos. Cuenta con imponentes bosques mixtos de hayas, acebedas maduras y robledales que cubren valles de aguas cristalinas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10184','espacio','Garganta de la Puria y escarpes graníticos de Traslasierra','Relieve abrupto de montaña media granítica que marca la vertiente occidental del Valle del Jerte, caracterizado por sus grandes bolos y canchales. Las laderas orientadas a la umbría albergan densas masas de roble rebollo y piornales de cumbre.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10187','espacio','Sierra de Gata y garganta de los Molinos','Valle de montaña cerrado caracterizado por un relieve abrupto de pizarras y cuarcitas con pendientes pronunciadas en el norte cacereño. El paisaje vegetal está dominado por un melojar denso que tapiza las zonas umbrías de la cuenca alta.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10188','espacio','Berrocal de Torre de Santa María y dehesas','Suaves ondulaciones del terreno que marcan la divisoria de aguas sobre el sustrato esquistoso-granítico de la penillanura. Destacan las formaciones de encinar aclarado con pastizales mediterráneos que fijan el suelo esquelético.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10185','espacio','Sierra de los Ángeles y valles del río d''Ángeles','Paisaje accidentado de transición hurdana con un relieve de lomas afiladas compuestas por pizarras fuertemente plegadas y meteorizadas. Las laderas orientadas al norte conservan rebollares e importantes brezales arborescentes de gran densidad.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10189','espacio','Dehesa boyal y vegas de la rivera de Fresnedosa','Relieve plano ondulado constituido por depósitos de arenas, arcillas y cantos rodados cuaternarios de la cuenca baja del Alagón. Conserva manchas relictas de encinar aclarado y pastizales estacionales adaptados a la sequedad estival.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10193','espacio','Penillanura del río Salor y dehesas pizarrosas','Llanura suavemente ondulada sobre pizarras y areniscas del Complejo Esquisto-Quarcítico donde se asienta una dehesa de encinas con ejemplares centenarios. La topografía presenta lanchares pétreos horizontales expuestos a la meteorización.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10194','espacio','Dehesa de Torrequemada y valles del río Salor','Depresión erosiva menor sobre materiales graníticos degradados y esquistos que da lugar a pequeños abarrancamientos fluviales. El entorno visual está definido por dehesas de encina aclaradas con afloramientos de lanchas pétreas horizontales.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','espacio','Berrocal de Trujillo y dehesas del batolito granítico','Paisaje penillanurero dominado por la alteración química del granito, que genera formaciones de bolos, piedras caballeras y tors rocosos esparcidos entre la llanura. Cuenta con dehesas maduras de encina bien conservadas que colonizan los suelos arenosos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10196','espacio','Garganta de Marta y cascada del Caozo','Cañón granítico profundo en la vertiente meridional de Gredos, donde el agua de deshielo cae verticalmente sobre un imponente tajo de roca pulida. El microclima húmedo de la zona sustenta un denso bosque de roble rebollo, castaños y fresnedas de ribera.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10197','espacio','Cañón del río Tajo y escarpes de la presa de Valdecañas','Margen escarpada del Tajo donde la erosión ha labrado taludes profundos sobre pizarras y granitos antes de   su encajamiento lineal. La vegetación se compone de masas densas de encina, acebuches y matorral mediterráneo esclerófilo. Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10198','espacio','Lomas del río Salor y dehesas de arcilla','Relieve ondulado sobre materiales blandos de tipo arcillo-yesífero que genera una suave topografía de colinas y pequeñas vaguadas. Cuenta con retazos de encinar mediterráneo y pastizales de carácter estepario.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10199','espacio','Dehesas de Valdehúncar y vegas del Tajo','Llanura sedimentaria ondulada de la fosa del Tiétar compuesta por arenas arcillosas de origen terciario bien deprimidas. Alberga dehesas de encina y alcornoque con un estrato herbáceo adaptado a suelos silíceos de ladera.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10200','espacio','Cañón del río Tajo (límite oriental) y dehesas de pizarra','Profunda incisión lineal excavada por el río Tajo sobre el complejo esquisto-quarcítico del Geoparque Villuercas. Presenta laderas de vertiginosa pendiente cubiertas por monte mediterráneo termófilo virgen rico en jarales y acebuchares.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10201','espacio','Sierra de Montánchez (vertiente oriental) y valles graníticos','Vertientes de fuerte pendiente compuestas por granitos fuertemente meteorizados que dan origen a suelos arenosos de sauló y formas redondeadas en las rocas. Cuenta con un encinar mixto con presencia de quejigos en las vaguadas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10202','espacio','Meandros del río Alagón y escarpes pizarrosos de la presa','Estrechamiento fluvial encajado de manera sinuosa sobre materiales pizarrosos antes de la llanura sedimentaria del Alagón. Los márgenes del cauce exponen perfiles de roca desnuda flanqueados por densos jarales pringosos y monte mediterráneo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10203','espacio','Berrocal de Valencia de Alcántara y Sierra de San Pedro','Impresionante paisaje granítico y cuarcítico caracterizado por la presencia de colosales bolos, piedras caballeras y valles paralelos de gran valor contemplativo. Alberga masas forestales densas de alcornoque de gran porte botánico combinadas con brezales arborescentes.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10204','espacio','Garganta de Naval y riscos graníticos de Gredos','Fractura tectónica de fuerte pendiente en la vertiente meridional de la sierra por donde bajan aguas de deshielo torrenciales, esculpiendo saltos y pozas. El paisaje vegetal está dominado por densos rebollares y bosques galería de alisos hiperhúmedos.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10205','espacio','Valle de Jálama y dehesas de alcornoque de la frontera','Majestuoso anfiteatro montañoso coronado por el pico Jálama, compuesto por granitos y pizarras que generan un relieve abrupto e influenciado por el clima atlántico. El paraje destaca por sus frondosos bosques de castaños y robles melojos de alto porte.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10206','espacio','Garganta de Río Moro y vertientes de Gredos','Valle de montaña cerrado caracterizado por un relieve abrupto de granitos con pendientes pronunciadas y saltos de agua torrenciales de roca pulida. El paisaje vegetal es dominado por un melojar denso que tapiza las zonas umbrías de la cuenca alta.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10207','espacio','Dehesas de Villa del Campo y vegas del arroyo de la Vega','Relieve plano ondulado de la cuenca sedimentaria del Alagón, constituido por depósitos de arenas, arcillas y cantos rodados cuaternarios. Conserva manchas relictas de encinar denso y pastizales hidrófilos de carácter estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10208','espacio','Riberas del río Salor y dehesas pizarrosas','Relieve ondulado labrado sobre el complejo esquisto-quarcítico que define la penillanura occidental. El encajamiento suave del río Salor expone lanchares de pizarra y sustenta comunidades estables de tamujos y saucedas adaptadas al severo estiaje mediterráneo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10210','espacio','Sierra de Trevejo y crestas graníticas de Jálama','Paisaje de alta montaña media caracterizado por imponentes afloramientos y fallas graníticas que coronan el horizonte de la Sierra de Gata. Las laderas orientadas a la umbría reciben una alta influencia atlántica, albergando frondosos bosques de roble rebollo y densas masas de castaño centenario.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10212','espacio','Garganta de Gualtaminos y Cascada del Diablo','Espectacular desfiladero labrado sobre el batolito granítico de la vertiente sur de Gredos, donde el río salva el desnivel en una sucesión de saltos verticales y marmitas de gigante pulidas. El entorno es un frondoso refugio botánico hiperhúmedo compuesto por melojares y alisedas galería.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10214','espacio','Vertientes de la Sierra de la Granja y dehesas de la penillanura','Zona de transición geomorfológica con fuertes pendientes de granito y pizarra que descienden hacia el valle del Ambroz. La cubierta vegetal destaca por la transición entre el matorral heliófilo de jara de las cumbres y encinares adehesados bien estructurados en la base.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10213','espacio','Garganta del madero, cañón del Tajo y azas del Geoparque Villuercas','Relieve apalachense abrupto con formaciones de cuarcita armoricana que encajonan de forma salvaje los cursos fluviales en su camino hacia el Tajo. Cuenta con valles umbríos y estrechos que dan cobijo a los singulares lorales relictos y a masas densas de madroño de porte arbóreo.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10215','espacio','Riberas del río Rivera de Gata y dehesas de alcornoque','Relieve premontano de colinas suaves compuesto por materiales pizarrosos y graníticos meteorizados. Alberga masas forestales densas de alcornoque mezcladas con formaciones arbustivas de brezo blanco y jarales que tapizan suelos silíceos ligeros.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10216','espacio','Tierras de Granadilla y recodos del Embalse de Gabriel y Galán','Paisaje penillanurero pizarroso fuertemente lobulado por la inundación de la cuenca fluvial del Alagón, generando una morfología de penínsulas y ensenadas interiores. El entorno destaca por la continuidad visual de sus jarales pringosos y encinares mediterráneos adaptados a la roca esquelética.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10217','espacio','Encina Terrona y lomas del batolito de Montánchez','Superficie penillanurera granítica con formas de relieve redondeadas por meteorización física y química. Acoge la célebre Encina Terrona, un ejemplar botánico monumental y milenario de Quercus ilex que destaca en un paisaje de dehesas mixtas bien conservadas.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10218','espacio','Canchos de Peñafiel y Parque Natural Tajo Internacional','Crestones de cuarcita verticales e imponentes escarpes pizarrosos que marcan la frontera fluvial y geológica con Portugal. Las laderas y grietas rocosas albergan comunidades rupícolas muy singulares junto a un monte mediterráneo xerófilo dominado por el acebuche y el lentisco.   Cáceres).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10219','espacio','Sierra de la Peña y dehesas del río Alcollarín','Relieve de crestón paleozoico aislado que rompe de forma abrupta la penillanura sedimentaria del Guadiana. La umbría de la sierra conserva una mancha densa de monte mediterráneo con alcornoques, encinas y un sotobosque denso de madroños y durillos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16001','espacio','Parque Natural de los Alcornocales, Garganta de Puerto Oscuro y pico Picacho','Impresionante relieve calizo y de areniscas del Aljibe caracterizado por profundos valles fluviales encajados llamados "canutos". El microclima hiperhúmedo de origen atlántico permite la supervivencia de una selva relicta de la era terciaria, destacando el ojaranzo (Rhododendron ponticum), los helechos gigantes y densos alcornocales que tapizan las laderas nubladas.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90467','espacio','Arroyo de Almoratín y escarpes calcáreos de la Serranía','Relieve de transición meseteña dominado por afloramientos calizos y margosos que configuran un paisaje de suaves lomas y pequeños desfiladeros fluviales. En los márgenes del cauce se desarrollan saucedas y alamedas maduras enmarcadas en un entorno de vegetación xerófila mediterránea.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90468','espacio','Garganta de la dehesa de la Sierra y riberas del río Majaceite','Entorno premontano modelado sobre arcillas y calizas triásicas del complejo de la Serranía de Ronda, donde la erosión hídrica ha esculpido pequeños relieves abruptos. Destaca por albergar formaciones de acebuches, densos algarrobos y un denso sotobosque de lentisco y aladierna.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16002','espacio','Canuto de la Garganta del Capitán y litorales de Punta Carnero','Espectacular tajo fluvial sobre las areniscas del frente tectónico bético que desciende hacia el Estrecho de Gibraltar. Alberga bosques galería de alisos y avellanillos relictos con una alta densidad de plantas epífitas, contrastando con una costa no-playa de flysch y acantilados estratificados azotados por el viento.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16003','espacio','Sierra de Líjar y nacimiento de las Fuentes de Algodonales','Imponente macizo calizo de laderas escarpadas, karstificado superficialmente con presencia de lapiaces y campos de dolinas. Las paredes rocosas verticales presentan comunidades botánicas rupícolas exclusivas y la base de la sierra cuenta con una gran surgencia de agua perenne rodeada de olmedas naturales.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16004','espacio','Peña de Arcos y meandro encajado del río Guadalete','Colosal paredón calizo y calcarenítico de más de 100 metros de altura labrado por la erosión lineal del río Guadalete en su tramo medio. La pared vertical constituye un ecosistema rupícola termófilo de primer orden con acebuches colgados y comunidades de alcaparras silvestres y líquenes.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90031','espacio','Acantilado de la Breña y Tajo de Barbate (Parque Natural)','Impresionante paredón costero calcáreo que se eleva más de 100 metros sobre el nivel del mar, mostrando procesos activos de erosión marina y desprendimientos.   Sobre el borde del acantilado se asienta una masa pura de pino piñonero (Pinus pinea) adaptada a los vientos cargados de sal y al sustrato arenoso fósil. Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16016','espacio','Canuto de la Riera de la Pasada y dehesas del Charco Redondo','Paisaje forestal de colinas suaves a abruptas sobre areniscas silíceas integradas en los Alcornocales. Los fondos de valle albergan los característicos "canutos" hiperhúmedos con bosques de galería repletos de laurisilva europea, acebos y helechos tropicales que requieren humedad atmosférica constante.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90469','espacio','Parque Natural Sierra de Grazalema, Manga de Villaluenga y Salto del Cabrero','Modelado kárstico de primer nivel con un espectacular desfiladero de paredes calizas paralelas que simula una fractura colosal en la montaña. El entorno presenta dolinas de disolución, campos de lapiaces afilados y una de las cubiertas vegetales más densas de encinar montano y quejigo andaluz.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90470','espacio','Ribera del Embalse de Bornos y cañón del Guadalete','Espacio lacustre delimitado por cerros de margas y calizas eocénicas donde el agua inunda los antiguos escarpes fluviales. Conserva una de las masas de tarajes (Tamarix) y carrizales palustres más densas de la cuenca baja, sirviendo de pantalla natural frente a la erosión.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16006','espacio','Garganta de la Almoraima y Parque Natural de los Alcornocales','Extensa selva mediterránea de llanura y montaña baja asentada sobre areniscas del Aljibe. Sus profundas vaguadas resguardan "canutos" fluviales con presencia de helechos gigantes paleotropicales, acebos y rododendros relictos de gran valor botánico.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16007','espacio','Acantilados de Sancti Petri, pinares de la Barrosa y marismas asociadas','Costa baja de abrasión marina caracterizada por perfiles de roca arenisca y calcarenita expuesta a las mareas. En el sector interior se conservan dunas fósiles estabilizadas por frondosas masas de pino piñonero y sabina costera.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16008','espacio','Acantilados de Roche y Calas de Conil','Impresionante línea de costa no-playa definida por perfiles verticales de arenas rojizas y calcarenitas miocénicas erosionadas por el oleaje. El borde superior de los cantiles está colonizado por el tomillo sarnoso (Thymus carnosus), un endemismo botánico adaptado a la extrema salinidad del viento.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90737','espacio','Garganta de las Graves y tajo del Algarrobal','Estrechamiento calizo imponente ubicado bajo la sombra de la Sierra de Grazalema, donde la disolución kárstica ha labrado paredes verticales y diaclasas profundas. Cuenta con una vegetación rupícola muy singular y un monte mediterráneo dominado por el acebuche de montaña.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11019','espacio','El Pinsapar de Grazalema, Garganta Verde y Salto del Cabrero','Uno de los enclaves geomorfológicos y botánicos más colosales del sur de Europa, caracterizado por un relieve kárstico de cañones kilométricos y lapiaces afilados. Su umbría húmeda alberga el bosque primario más extenso y denso de pinsapo (Abies pinsapo), una joya botánica relicta de las glaciaciones cuaternarias.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11021','espacio','Río Hozgarganta y garganta del Murciélago','Último río virgen de la provincia de Cádiz que fluye encajonado de forma salvaje sobre gargantas de arenisca y depósitos de cantos rodados. El agua perenne permite la supervivencia de pasillos tupidos de laurisilva atlántica con alisos y ojaranzo.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','espacio','Macizo de Medina y gargantas de la dehesa del Carbonero','Promontorio elevado de areniscas que destaca visualmente sobre la llanura prelitoral gaditana, tallado por pequeños barrancos fluviales húmedos. Alberga fragmentos bien conservados de alcornocal termófilo con abundancia de lentisco, acebuche y jarales densos.   Cádiiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11024','espacio','Reserva Natural del Peñón de Zaframagón (límite municipal)','Colosal mole caliza de paredes verticales y perfil prominente que emerge de manera abrupta entre colinas olivareras arcillosas. Destaca por su cañón fluvial excavado por el río Guadalporcún, llamado el "Estrecho", que muestra un plegamiento y fractura tectónica únicos.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11026','espacio','Cerro de Verdugo y fuentes del pozo salado','Relieve ondulado de la comarca prelitoral constituido por yesos, margas y arcillas triásicas policromas. La presencia de manantiales salinos genera un entorno edáfico particular con comunidades herbáceas halófilas relictas de gran interés.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11028','espacio','Complejo endorreico de Puerto Real (Lagunas de San Antonio y Taraje)','Cubetas lagunares de origen natural asentadas sobre arcillas y margas impermeables que recogen el agua de escorrentía superficial. Su entorno botánico cuenta con densas orlas de tarajes, carrizos y vegetación palustre adaptada a la oscilación estacional de la lámina de agua.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11031','espacio','Marismas de Sancti Petri y caños intermareales','Complejo laberinto de sedimentos limosos litorales modelado de manera continua por la dinámica de las mareas atlánticas. Alberga comunidades botánicas halófilas extremas, tales como la sapina, el esparto marítimo y praderas de fanerógamas marinas bentónicas en sus fondos arenosos.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11902','espacio','Sierra de las Cabras y manantial de Tempul','Macizo calizo abrupto integrado en las estribaciones béticas occidentales con lapiaces desarrollados y surgencias de agua subterránea caudalosas. La vegetación está compuesta por encinares montanos mezclados con acebuches de gran porte.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11033','espacio','Estuario del río Guadiaro y Pinar del Rey','Zona húmeda costera no-playa constituida por marismas limosas y barras de arena granítica en la desembocadura fluvial. El sector forestal adyacente alberga una masa madura de pino piñonero asentada sobre dunas fósiles del cuaternario.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11032','espacio','Marismas de Bonanza y Algaida','Entorno lacustre y llanura de inundación mareal salobre integrada en el margen izquierdo de Doñana, compuesta por arenas finas y limos aluviales. El pinar costero y los almajos salinos constituyen un ecosistema botánico costero de máxima singularidad contemplativa.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','espacio','Acantilados de la punta del Camorro, isla de las Palomas y Sierras de Fates','Impresionante tramo costero de flysch caracterizado por la alternancia rítmica de capas horizontales de areniscas y margas erosionadas por el oleaje del Estrecho. Las laderas de las sierras interiores albergan los "canutos" más meridionales de Europa con un denso bosque de alcornoque sumergido en las nieblas marítimas.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11037','espacio','Marismas de Trebujena y esteros del Guadalquivir','Paisaje horizontal de llanuras de fango arcilloso formadas por la sedimentación fluvial y la dinámica de mareas del río Guadalquivir. Cuenta con comunidades halófilas perennes y vegetación palustre que delimita los brazos antiguos del río.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11038','espacio','Garganta de Ubrique y desfiladero del Salto de la Mora','Estrechamiento fluvial espectacular encajado entre colosales paredes calizas que se elevan verticales sobre el núcleo urbano. El modelado kárstico incluye cuevas, surgencias cántabras y un denso bosque de quejigos y encinas rupícolas en las laderas de umbría.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','espacio','Marismas del río Barbate y acantilados de la Barca','Cuenca aluvial baja inundable donde la dinámica fluvial confluye con las mareas atlánticas creando un paisaje de meandros limosos y caños. En las zonas elevadas, las calcarenitas expuestas sustentan dehesas de acebuche salvaje de gran valor paisajístico.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11040','espacio','Sima de Villaluenga y Poljé de la Manga','El poljé kárstico más espectacular y perfecto de Andalucía, consistente en un inmenso valle cerrado rodeado de escarpes calizas donde las aguas se sumergen en una fosa tectónica vertical. La vegetación destaca por encinares montanos adaptados al lanchar calcáreo y flora rupícola de altitud.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11041','espacio','Junta de los Ríos (Guadalete y Majaceite) y cañón de los Tollos','Llanura aluvial prelitoral donde la confluencia hídrica genera amplias terrazas de gravas y arenas sedimentarias. El entorno de los Tollos destaca por sus formaciones de margas yesíferas con vegetación gipsícola especializada y retazos de monte mediterráneo esclerófilo.   Cádiz).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90739','espacio','Garganta Seca, Garganta Verde y Garganta de la Ermita','Impresionantes cañones kársticos de hasta 400 metros de profundidad con paredes verticales calizas colosales que casi se unen en su parte superior. El fondo umbrío e inaccesible cobija un microclima hiperhúmedo donde crecen laureles silvestres, helechos rupícolas e higueras que trepan por la roca viva.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90861','espacio','Barranco de la Caridad y alcornocales de la Sierra de Espadán','Profundo valle fluvial encajado sobre rocas de arenisca triásica roja (rodeno) que retienen una humedad ambiental excepcional. Sus umbrías albergan densas masas de alcornoque (Quercus suber) de gran porte mezclados con madroños y un sotobosque de helechales relictos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90353','espacio','Barranco de la Valltorta y muelas calcáreas','Cañón kárstico de paredes verticales labrado por la erosión lineal sobre potentes bancos de calizas del Maestrazgo. Las cornisas de la roca exponen formaciones de disolución y abrigos naturales, rodeados de una vegetación arbustiva xerófila con lentiscos y acebuches.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11001','espacio','Parque Natural de la Sierra de Irta y acantilados de Almedrava','Tramo de costa no-playa virgen caracterizado por escarpados acantilados de piedra caliza que caen directamente sobre el mar Mediterráneo. La vegetación está dominada por una densa maquia litoral compuesta por palmitos (Chamaerops humilis), hinojo marino y sabinas de duna adaptadas al viento salino.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12005','espacio','Barranco del Amador y embalse de l''Alcora','Relieve quebrado en la transición hacia la media montaña, caracterizado por afloramientos de calizas y arcillas que generan taludes de fuerte pendiente. Cuenta con masas boscosas de pino carrasco y matorrales mediterráneos mixtos con abundancia de romero y coscoja.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12007','espacio','Desfiladero del río Belcaire y puntal de la Llosada','Estrechamiento fluvial colosal encajonado entre altas paredes de areniscas y dolomías calizas en la vertiente oriental de Espadán. Las laderas presentan perfiles escarpados y canchales colonizados por encinares de montaña y densos brezales arborescentes.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12010','espacio','Barranco de Almansor y alcornocal de la Mosquera','Valle angosto modelado sobre sustratos silíceos de rodeno rojo que sustentan uno de los alcornocales más puros y mejor conservados de la Comunidad Valenciana. El fondo del barranco resguarda un microclima húmedo con presencia de hiedras monumentales y helechos rupícolas.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12011','espacio','Els Estanys de Almenara','Tres lagunas de agua dulce alimentadas por surgencias subterráneas (ullals) integradas en el cordón litoral de la llanura prelitoral. La lámina de agua permanente está rodeada de extensos carrizales, eneas y comunidades macrofíticas de gran valor contemplativo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12012','espacio','Barranco de las Albebras y cañón de la TorrecillaPuntal','Relieve escarpado integrado en las estribaciones de la Sierra Calderona, con formaciones de cantiles calizos esculpidos por procesos kársticos. Las zonas de umbría conservan rodales de quejigo andaluz y masas forestales densas de pino resinero sobre suelos silíceos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12013','espacio','Estrecho de Chillapájaros y curso del río Mijares','Imponente cañón fluvial flanqueado por paredes de caliza masiva que superan los 100 metros de altura vertical, mostrando pliegues tectónicos. El cauce de aguas rápidas se encajona de manera salvaje entre cantos rodados y comunidades vegetales de ribera.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11002','espacio','Muela de Ares y Barranco de los Molinos','Colosal plataforma estructural caliza de perfil tabular y flancos casi verticales que domina de forma absoluta el paisaje del Alto Maestrazgo. La disolución kárstica genera lapiaces en su cima y la umbría alberga quejigares montanos y sabinas rastreras de altitud.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12015','espacio','Cañón del río Villahermosa y peña de los Órganos','Desfiladero fluvial excavado sobre potentes bancos calizos eocénicos con perfiles verticales angulosos que simulan tubos de órgano. La vegetación rupícola coloniza las diaclasas y repisas rocosas, combinada con pinares de pino carrasco en la base.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12016','espacio','Valle de Artana y crestas de rodeno de la Sierra de Espadán','Fosa tectónica delimitada por escarpadas laderas de areniscas triásicas de color rojizo intenso que contrastan con los fondos calizos del valle. El entorno forestal cuenta con alcornocales de montaña y densos jarales que fijan los suelos silíceos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90354','espacio','Macizo de Penyagolosa (vertiente oriental) y Barranco de las Alforjas','Relieve de alta montaña caliza que asciende de forma abrupta con canales de desprendimiento y taludes de ladera bien definidos. La vegetación destaca por la presencia de bosques mixtos de pino negral, melojos relictos y una rica flora montana subatlántica.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12017','espacio','Barranco de la Foz y pozas del río Chico','Angosto tajo fluvial excavado sobre areniscas rodenas y calizas triásicas donde el río forma pequeñas cascadas estacionales y ollas de roca pulida. El paisaje visual ofrece un mosaico de pinares densos y matorral mediterráneo perennifolio muy denso.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12018','espacio','Barranco de la Peña Ajafuera y alcornocal de Azuébar','Escarpados relieves de areniscas triásicas integrados en el Parque Natural de la Sierra de Espadán. Alberga una magnífica masa de alcornoques orientada a la umbría con presencia de madroños y una densa orla de brezo blanco de gran porte botánico.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12020','espacio','Altiplano de Barracas y pinares de la Saborite','Elevada planicie de carácter estructural asentada a más de 1000 metros de altitud sobre calizas cretácicas con incipientes campos de dolinas. La vegetación está integrada por sabinares albares abiertos y pastizales de montaña resistentes al clima continental extremo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90355','espacio','Vertientes de la Sierra de Espadán (Puntal de la Penya)','Estribaciones montañosas terminales compuestas por arcillas rojas y calizas marginales que descienden hacia la plana aluvial. Presenta matorrales mediterráneos xerófilos dominados por el romero, el tomillo y pinos carrascos dispersos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12026','espacio','Paraje Natural Municipal de El Rivet y Barranco de la Font d''en Segures','Impresionante microbosque relicto de quejigos (Quercus faginea) monumentales asentado sobre una ladera caliza húmeda del Maestrazgo. El relieve es quebrado con abundantes fuentes de montaña y lapiaces formados por disolución kárstica activa.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12027','espacio','Desembocadura de la Rambla de Alcalà','Llanura litoral sedimentaria constituida por depósitos de cantos gruesos y gravas cuaternarias de carácter torrencial. Conserva pequeñas formaciones vegetales halófilas y de marisma alta en el tramo final del cauce intermitente.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12029','espacio','Plana de l''Arc y barranco de la dehesa','Depresión interior de relieve llano a suavemente ondulado sobre arcillas y limos cuaternarios estabilizados. Presenta pequeñas formaciones de encinar aclarado y matorral mediterráneo con coscoja y espinares menores.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12031','espacio','Barranco de Borriol y peñas de la loma de la Pólvora','Valle encajonado labrado sobre calizas miocénicas con laderas escarpadas que exponen estratos horizontales fracturados por la falla de la Plana. La vegetación   está dominada por masas densas de pino carrasco y un estrato arbustivo mediterráneo termófilo. Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12033','espacio','Parque Natural del Prat de Cabanes-Torreblanca y escarpes de la cordillera Litoral','Extensa llanura palustre costera separada del mar por un cordón de gravas y arenas, que conforma un humedal turbero único en la región. La vegetación está compuesta por comunidades de macrófitos, carrizales densos y plantas halófilas de altísima singularidad botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12034','espacio','Barranco del Socorro y lomas arcillo-calcáreas','Paisaje de lomas suaves sobre materiales sedimentarios terciarios, donde el encajamiento del arroyo genera pequeños taludes de erosión hídrica. La vegetación predominante está constituida por un estrato de matorral mediterráneo esclerófilo con coscoja y algarrobos silvestres dispersos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12036','espacio','Olivares milenarios del Baix Maestrat y lomas de caliza','Relieve ondulado de la comarca prelitoral caracterizado por un suelo de costra calcárea donde se asientan majestuosos ejemplares botánicos milenarios de Olea europaea. La fisonomía muestra suaves pendientes erosionadas que alternan con manchas de pino carrasco y matorral basófilo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12037','espacio','Parque Natural de la Tinença de Benifassà y muelas de Castell de Cabres','Espectacular relieve prepirenaico de alta montaña media dominado por muelas calizas de vertientes vertiginosas y escarpes asimétricos por empuje tectónico. Alberga masas forestales densas e intactas de pino negral, pinares de pino albar y bosquetes umbríos de roble pubescente.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12038','espacio','Muela de Castellfort y barranco de la Parra','Imponente altiplano tabular calizo cortado de forma abrupta por la erosión lineal, configurando profundos   barrancos y farallones rocosos dolomíticos. Presenta una vegetación kárstica especializada de ladera con sabina rastrera, tomillares montanos y comunidades rupícolas de altitud. Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12039','espacio','Barranco de la Falaguera y curso alto del río Palancia','Relieve de transición montañosa con afloramientos de margas yesíferas triásicas y terrazas fluviales estables de cantos rodados. Cuenta con una cubierta forestal mixta de pino carrasco y un bosque de galería lineal compuesto por sauces y adelfas silvestres.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12041','espacio','Cañón del río Villahermosa y peña del Buitre','Angosto desfiladero fluvial excavado de manera salvaje sobre potentes bancos calizos eocénicos con perfiles verticales que superan los 100 metros. Sus laderas umbrías dan cobijo a una vegetación densa de quejigos, pino laricio y comunidades rupícolas de gran pureza.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12042','espacio','Valle de Catí, Avellà y microreserva botánica del Tossal de la Nevera','Cuenca kárstica cerrada u óvalo tectónico rodeado de cumbres calizas que superan los 1200 metros de altitud con lapiaces bien desarrollados. Destaca botánicamente por albergar carrascales montanos maduros, quejigales relictos y fuentes de agua minero-medicinal surgidas del karst.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12043','espacio','Sierra de Javalambre (estribaciones), Mas de Noguera y barranco del Juncar','Relieve de alta montaña media asentado sobre calizas jurásicas y dolomías, caracterizado por una topografía quebrada de fuertes pendientes. En sus umbrías prosperan densas masas forestales de pino albar, encinares montanos y matorrales espinosos calcícolas.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12044','espacio','Rambla de Cervera y lomas del Molinar','Cauce fluvial de carácter torrencial intermitente cubierto por potentes depósitos de gravas y cantos rodados calizos en un relieve prelitoral. Las laderas circundantes muestran una vegetación arbustiva mediterránea rala dominada por el romero y la coscoja.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12056','espacio','Barranco de Ajuez y alcornocales del pico de la Nevera','Valle angosto labrado sobre areniscas triásicas de color rodeno rojizo intenso que contrastan drásticamente con los relieves calizos adyacentes. Alberga una de las masas de alcornoque (Quercus suber) más frondosas de Espadán, acompañada de helechos e hiedras de umbría.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12046','espacio','Barranco de las Salinas, río Mijares y pozo Negro','Cañón fluvial profundo labrado sobre calizas cretácicas donde la acción erosiva del agua ha creado pozas circulares de roca pulida y saltos de agua estacionales. El entorno presenta densos pinares de pino carrasco y comunidades de helechos rupícolas.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12048','espacio','Nacimiento del río Carbo y pinares de San Vicente','Relieve de alta montaña caliza que sirve de antesala al macizo de Penyagolosa, con surgencias de agua subterránea que brotan directamente de la roca calcárea. Alberga formaciones boscosas puras de pino albar (Pinus sylvestris), tejos dispersos y acebedas montanas.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12051','espacio','Cañón del río Montlleó y muela de Culla','Espectacular y colosal corte geológico vertical de más de 300 metros de profundidad excavado sobre calizas cretácicas en el corazón del Maestrazgo. La umbría inaccesible del cañón resguarda un ecosistema botánico puro con quejigales, tejos residuales y arces de Montpellier.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12057','espacio','Barranco de Castro y alcornocal del Puntal de l''Aljub','Corazón silíceo de la Sierra de Espadán con desniveles muy acusados esculpidos sobre areniscas rodenas de gran permeabilidad. Destaca botánicamente por su frondosa e impenetrable cobertura de alcornoques (Quercus suber), brezales de montaña y helechales gigantes.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12058','espacio','Peñas de Espadilla y curso del río Mijares','Formidables paredones calizos totalmente verticales que flanquean el valle del Mijares, mostrando marcas de erosión eólica e hídrica. La base de los escarpes está tapizada por densos pinares de pino carrasco y matorral mediterráneo esclerófilo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12059','espacio','Estrechos del río Mijares y barranco de la Maimona (desembocadura)','Relieve calizo kárstico caracterizado por un encajamiento fluvial de perfiles angulosos y bloques rocosos desprendidos de los cantiles superiores. Cuenta con comunidades rupícolas raras y un dosel vegetal dominado por pinos y maquia de lentisco.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12060','espacio','Rambla de las Alforjas y lomas calcáreas del Alcalatén','Relieve premontano quebrado constituido por calizas y arcillas del terciario medio que originan taludes estacionales de erosión. Presenta pinares mediterráneos y matorrales esclerófilos que colonizan los suelos pedregosos de la cuenca.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12061','espacio','Confluencia de los ríos Caldes, Cantavieja y Bergantes, y muela de la Garumba','Espectacular nudo geomorfológico donde tres cursos fluviales convergen rompiendo relieves tabulares de calizas y arcillas rojas. La imponente muela de la Garumba preside el territorio con farallones verticales y una vegetación submediterránea de altitud.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12063','espacio','Barranco de la Maimona y fuentes del río Serrano','Desfiladero angosto y salvaje tallado en calizas jurásicas con paredes rocosas verticales cubiertas de una rica flora rupícola criptogámica. El fondo del barranco es un refugio hiperhúmedo con un bosque galería continuo de sauces, alisos y fresnos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12064','espacio','Pozo Negro y curso alto del río Chico','Singular rincón kárstico de la Sierra de Espadán donde el agua ha excavado una poza circular profunda de   aguas cristalinas sobre roca madre caliza pulida. El entorno forestal combina encinares montanos con masas de pino resinero sobre suelos descalcificados. Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12065','espacio','Barranco de la Fuensanta y río Regajo','Relieve de media montaña con fallas tectónicas que exponen calizas y dolomías triásicas de tonalidades grisáceas. Cuenta con abundantes surgencias de agua estacionales y masas boscosas densas de pino carrasco mezcladas con quejigos en las vaguadas.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12067','espacio','Riberas del río Palancia (tramo medio)','Llanura aluvial estrecha constituida por depósitos detríticos cuaternarios de gravas y limos fluviales. El cauce mantiene un pasillo verde residual de vegetación riparia con sauces, adelfas y cañaverales mediterráneos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12068','espacio','Barranco del Escalona y bosques de la Tinença de Benifassà','Paisaje pirenaico-bético de alta montaña con valles en V profundamente encajados sobre calizas jurásicas fracturadas. Destaca botánicamente por sus frondosos robledales de roble pubescente, pinares de pino albar y comunidades vegetales eurosiberianas relictas.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12070','espacio','Lomas del Barranco de Santa Ana','Terreno suavemente ondulado sobre materiales calizos eocénicos en la transición hacia la llanura prelitoral. Alberga olivos monumentales dispersos integrados con matorral bajo mediterráneo de carácter xerófilo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12071','espacio','Vuelta de la Hoz (Río Palancia)','Impresionante meandro encajonado donde el río Palancia ha cortado un farallón calizo de más de 50 metros de altura, aislando un peñón rocoso central. Las paredes verticales muestran marcas de disolución y acogen una singular vegetación rupícola.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12074','espacio','Marjal de Almenara-La Llosa y ullals de agua dulce','Llanura litoral baja inundable constituida por sedimentos cuaternarios finos enriquecidos por aportes de surgencias freáticas calcáreas (ullals). Alberga carrizales densos y praderas sumergidas de macrófitos hidrófilos de gran valor ecológico.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12073','espacio','Desfiladero del río Villahermosa y pozo de la Selva','Estrechamiento fluvial colosal encajonado de forma sinuosa entre altas paredes calizas cretácicas que exponen estratos geológicos horizontales. El cauce forma pozas de roca pulida y está flanqueado por un bosque de galería bien estructurado con sauces y chopos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12076','espacio','Barranco de la Carroja y estribaciones del pico Espadán','Topografía de fuertes desniveles sobre areniscas triásicas y calizas jurásicas que marcan la divisoria hidrográfica del parque natural. Sus laderas umbrías conservan pequeños retazos de alcornocal mezclados con densos pinares de pino resinero y brezales.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12077','espacio','Estany de Moncofa y marjal costera','Humedal litoral menor constituido por una pequeña laguna somera de aguas salobres separada del mar por una restinga de gravas. La vegetación está integrada por almajajares, carrizos y plantas halófilas adaptadas a suelos salinos fluctuantes.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12078','espacio','Barranco de la Maimona (tramo alto) y fuentes de Montán','Impresionante tajo kárstico de paredes verticales calizas calcinadas por el sol que contrastan con los fondos umbríos repletos de vegetación hiperhúmeda. Alberga cuevas de disolución y un denso bosque de quejigos y tejos residuales en los canchales de ladera.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12079','espacio','Estrecho de Chillapájaros, Fuente de los Baños y cañón del río Mijares','Uno de los cañones fluviales más colosales de la región, con imponentes paredes calizas verticales de más   de 100 metros que aprisionan el curso de aguas termales cristalinas. El paraje destaca por su morfología kárstica pura, con cuevas colgadas (Cueva Negra) y flora rupícola protegida. Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12080','espacio','Muela de Morella, barranco de la Teulería y cantera de los dinosaurios','Majestuosa e imponente muela caliza de perfil tabular y flancos escarpados que emerge de forma absoluta en el paisaje del Alto Maestrazgo. Sus formaciones geomorfológicas albergan lapiaces, abrigos rocosos y un entorno vegetal dominado por carrascales montanos y sabinas rastreras.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12081','espacio','Salto de la Novia y cascada del Brazal (Río Palancia)','Espectacular salto de agua de más de 30 metros de altura vertical que se precipita sobre un estrechamiento calizo del río Palancia, modelando paredes de toba calcárea de gran interés geológico. El entorno cuenta con una densa vegetación hidrófila de ribera con chopos y sauces monumentales.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12082','espacio','Marjal de Nules','Zona húmeda litoral de llanura constituida por depósitos arcillosos sedimentarios que retienen el agua freática. Cuenta con comunidades vegetales palustres dominadas por el carrizo (Phragmites australis) y eneas que forman una barrera biológica estable.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12083','espacio','Barranco de la Cuba y lomas calizas de Javalambre','Paisaje de alta montaña media continental con relieves tabulares y pendientes calcáreas abruptas sometidas a una intensa gelifracción. Alberga formaciones botánicas de   sabina albar, tomillares xerófilos y pastizales secos de gran valor ecológico. Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12084','espacio','Estribaciones de la Sierra de Espadán y río Sonella','Zona de contacto geomorfológico entre las calizas del Maestrazgo y las areniscas rodenas de la sierra, que genera relieves de lomas disimétricas. Cuenta con pinares mediterráneos y un estrato arbustivo dominado por el romero, el tomillo y la coscoja.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12087','espacio','Desfiladero del río Bergantes y riscos de Palanques','Angosto cañón excavado por el río Bergantes sobre materiales calizos del Maestrazgo, caracterizado por sus estratos rocosos fuertemente plegados y erosionados de forma alveolar. Las márgenes fluviales conservan saucedas y alamedas que contrastan con los cantiles desnudos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12088','espacio','Barranco del Carrascal y peñas de la Umbría','Topografía quebrada de media montaña caliza en las estribaciones orientales de la Sierra de Espadán. Conserva manchas relictas de encinar montano bien estructurado con quejigos en las vaguadas y un sotobosque denso de durillos y cornicabras.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12090','espacio','Pico de Pina y pinares de la Sierra de Pina','Elevado macizo calizo jurásico que roza los 1400 metros de altitud, caracterizado por vertientes escarpadas y fenómenos periglaciares en las cumbres. Da cobijo a frondosas masas forestales de pino albar (Pinus sylvestris) y encinares montanos adaptados al frío continental.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12093','espacio','Salt de Robert, Barranco de la Fou y hayedo del Retaule (límite provincial)','Paisaje pirenaico-bético colosal integrado en la Tinença, célebre por albergar el hayedo (Fagus sylvatica) más meridional de la península ibérica asentado en un karst umbrío hiperhúmedo. El relieve cuenta con desfiladeros de caliza masiva, cascadas verticales y tejos milenarios de excepcional valor botánico.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12091','espacio','Barranco de la Font de l''Horta y muelas calizas de Portell','Paisaje de muelas y altiplanos estructurales calizos cortados por profundos barrancos en V de fuerte incisión hídrica. Las laderas y repisas rocosas están colonizadas por comunidades de sabina albar y quejigales submediterráneos resistentes al frío.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12092','espacio','Los Estrechos del río Mijares (cabecera) y pozo de las Palomas','Imponente estrechamiento fluvial donde el río Mijares corta transversalmente los relieves calizos jurásicos de la frontera aragonesa, generando un desfiladero vertical salvaje. Las umbrías resguardan pinares de pino laricio y comunidades rupícolas especializadas.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12095','espacio','Yacimiento paleontológico y escarpes del río Mijares','Relieve ondulado sobre calizas lacustres y arcillas del Mioceno que flanquea el curso del río Mijares en su tramo medio. La erosión ha expuesto estratos sedimentarios ricos en materia orgánica fósil, rodeados de masas arbustivas de romero y pino carrasco.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12096','espacio','Riscos de la Tinença y barranco de las dehesas','Puerta de entrada meridional a la Tinença de Benifassà, caracterizada por imponentes crestones calizos verticales y pendientes de margas erosionadas en cárcavas. Alberga encinares montanos maduros mezclados con pinares de pino negral y brezales arborescentes.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11014','espacio','Valle de Sant Mateu y colinas de la Sierra de la Vall d''Àngel','Amplia depresión tectónica flanqueada por relieves calizos cretácicos de vertientes escarpadas y formas kársticas superficiales. La cubierta vegetal está integrada por encinares aclarados, pinares de pino carrasco y matorrales basófilos densos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12101','espacio','Riberas e islas del río Cenia (límite provincial)','Tramo de llanura fluvial donde el río Cenia se encajona de forma suave sobre depósitos de gravas y cantos rodados cuaternarios. Las orillas albergan franjas estables de bosque de ribera con sauces, adelfares y cañaverales autóctonos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12102','espacio','Barranco de la Vall d''Atall y vertientes de la Sierra de Irta','Valle interior enclavado en la Sierra de Irta compuesto por calizas masivas con un modelado kárstico superficial bien desarrollado. La vegetación destaca por una densa maquia mediterránea rica en palmitos, lentiscos y coscojas de porte arbustivo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12104','espacio','Paraje Natural Municipal del Manantial de la Esperanza y río Palancia','Espectacular surgencia kárstica perenne de gran caudal que brota directamente al pie de un cerro calizo de la Sierra Calderona. Las márgenes fluviales del Palancia a su paso muestran amplias terrazas aluviales con un denso y maduro bosque de galería de chopos y sauces.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12105','espacio','Sierra de la Engarcerán y fuentes del riachuelo de la Roca','Bloque tectónico elevado (horst) constituido por calizas masivas que definen un relieve escarpado con amplias vistas hacia la Plana alta. Alberga carrascales de montaña bien conservados y matorrales espinosos calcícolas que colonizan los canchales de ladera.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12106','espacio','Paraje Natural Municipal de la Dehesa y lagunas salobres de Soneja','Singular meseta arcilloso-arenosa del Triásico que alberga una pequeña laguna endorreica temporal sobre arcillas impermeables, fenómeno muy raro en la zona. Cuenta con un alcornocal relicto sobre suelos descalcificados y una densa orla de matorral silícola.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12107','espacio','Desfiladero del río Palancia y peña del azud','Estrechamiento fluvial menor abierto sobre materiales calizos eocénicos donde el río corta de forma transversal las estructuras prelitorales. El cauce está acompañado por una banda continua de vegetación de ribera con chopos y sauces arbustivos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12109','espacio','Órganos de Benitandús y barranco de la Vega','Impresionantes formaciones geológicas de erosión diferencial sobre calizas triásicas que generan agujas rocosas verticales que asemejan los tubos de un órgano monumental. La vegetación del paraje combina pinares densos con maquia mediterránea esclerófila.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12110','espacio','Curso alto del río Palancia y barranco de la Hoz','Valle fluvial fuertemente encajonado sobre calizas jurásicas, donde el río discurre entre paredes rocosas abruptas formando pequeños saltos de agua y pozas de roca pulida. El ecosistema ripícola cuenta con alisedas y choperas naturales de notable interés paisajístico.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12111','espacio','Barranco de la Valltorta (tramo superior) y muelas calizas','Cañón kárstico de paredes verticales labrado por la erosión lineal sobre potentes bancos de calizas del Maestrazgo, con abrigos rocosos de disolución química. El entorno arbustivo mediterráneo está dominado por la coscoja, el lentisco y el romero silvestre.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12112','espacio','Barranco de la Maza y muelas calcáreas del Bergantes','Paisaje accidentado del Alto Maestrazgo caracterizado por relieves tabulares de caliza con laderas escarpadas sometidas a una intensa gelifracción. Alberga encinares montanos bien estructurados y pastizales continentales secos de gran valor botánico.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12113','espacio','Cañón del río Mijares y fuentes de Toga','Estrechamiento fluvial colosal encajonado entre altas paredes de caliza masiva cretácica con diaclasas verticales bien definidas. El lecho del río cuenta con pozas de agua limpia y un pasillo verde continuo de vegetación riparia con sauces y adelfas de gran porte.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12115','espacio','Paraje Natural Municipal de El Rebollar, Peña Salada y nacimiento del río Palancia','Espectacular entorno de alta montaña caliza que supera los 1500 metros de altitud, con un modelado periglaciar e incipientes campos de dolinas estructurales. Alberga el único bosque puro de roble melojo (Quercus pyrenaica) de la provincia junto a imponentes sabinares de montaña de gran valor botánico.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12116','espacio','Barranco del Agua Mala y pinares de la Sierra de Espadán','Relieve abrupto y quebrado modelado sobre el complejo de rodenos triásicos de la Sierra de Espadán, que genera un microclima húmedo de montaña. Sus laderas albergan un alcornocal continuo y denso mezclado con quejigos en las vaguadas y una rica cobertura de helechales.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12117','espacio','Parque Natural del Prat de Cabanes-Torreblanca (sector norte)','Extensa llanura palustre costera constituida por depósitos de fangos limo-arcillosos cuaternarios inundados estacionalmente por el nivel freático. Conserva franjas de carrizales, eneas y comunidades halófilas adaptadas a suelos con salinidad variable de altísima singularidad.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90356','espacio','Barranco de la Esperanza y lomas de caliza','Paisaje ondulado del Maestrazgo bajo con suelos calcáreos del Cretácico donde la erosión lineal ha labrado pequeños taludes rocosos. Cuenta con formaciones de matorral mediterráneo esclerófilo con abundancia de lentisco, coscoja y pinares aclarados.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12120','espacio','Barranco de la Parra y lomas prelitorales','Elevaciones calizas marginales de la llanura prelitoral, fracturadas por la tectónica regional que expone perfiles de roca caliza erosionada. Alberga masas de pino carrasco y matorrales xerófilos termo-mediterráneos adaptados a la escasez de suelo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12118','espacio','Estrecho de Torrechiva y curso del río Mijares','Imponente cañón fluvial flanqueado por paredes de caliza masiva que superan los 100 metros de altura vertical, mostrando marcas de erosión lineal y alveolar. El cauce de aguas rápidas se encajona de manera salvaje entre cantos rodados y comunidades vegetales de ribera.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12121','espacio','Lomas de la Sierra de San Pedro y llanura del Baix Maestrat','Relieve colinado labrado sobre calizas miocénicas con una topografía de vertientes de pendiente moderada. Presenta comunidades vegetales ralas de carácter estepario y matorral bajo mediterráneo con coscoja y espinares menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12075','espacio','Riberas del río Cantavieja y muelas del Maestrazgo','Relieve tabular calizo erosionado por la dinámica fluvial del río Cantavieja, que genera terrazas escalonadas y laderas escarpadas de margas. Acoge   formaciones de bosque mediterráneo montano con encinares maduros y pastizales secos continentales. Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12097','espacio','Ventisqueros de la Sierra de El Toro y lomas calizas','Paisaje de alta montaña media continentalizado, con relieves calizos erosionados por el hielo y el viento que albergan antiguas construcciones de ventisqueros naturales. La vegetación está dominada por tomillares montanos y comunidades de sabina rastrera.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12098','espacio','Barranco de la Mezquita y lomas del Maestrazgo bajo','Relieve colinado labrado sobre calizas y arcillas del Cretácico con una topografía de vertientes de pendiente moderada. Cuenta con formaciones de matorral mediterráneo esclerófilo con abundancia de lentisco, coscoja y pino carrasco disperso.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12902','espacio','Tossal de la Foia y barranco de la Parra','Elevaciones calizas marginales de la llanura de la Plana, fracturadas por la tectónica regional que expone perfiles de roca caliza meteorizada. Alberga masas de pino carrasco y matorrales xerófilos termo-mediterráneos adaptados a la escasez de suelo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12114','espacio','Barranco de las Palomas y pinares de la Sierra de El Toro','Relieve de alta montaña media asentado sobre calizas jurásicas fracturadas, caracterizado por una topografía de pendientes pronunciadas. En sus umbrías prosperan frondosas masas forestales de pino albar, encinares montanos y matorrales espinosos calcícolas.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12123','espacio','Meandro del río Villahermosa','Impresionante garganta fluvial donde el río describe una curva cerrada y profunda sobre calizas eocénicas del Alto Mijares. Las escarpadas paredes rocosas de umbría albergan vegetación rupícola especializada y un dosel de pino blanco.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12124','espacio','Rambla de Alba y llanuras del Pla de l''Arc','Depresión tectónica interior cuaternaria con un relieve llano roto por la incisión de corrientes torrenciales intermitentes. Presenta retazos de encinar mediterráneo aclarado y comunidades herbáceas de carácter estepario.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12125','espacio','Barranco de la Fuensanta y Parque Natural de la Sierra de Espadán','Valle angosto delimitado por laderas de areniscas rodenas que dan paso a cumbres calizas en las cotas superiores. Las zonas silíceas albergan alcornocales maduros muy densos con madroños, mientras que el fondo del barranco presenta surgencias de agua perenne.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12126','espacio','Río subterráneo de las Cuevas de San José','Excepcional fenómeno kárstico consistente en una surgencia activa que alberga el río subterráneo navegable más largo de Europa, modelado por disolución en calizas triásicas. El exterior presenta un relieve abrupto de cantiles dolomíticos cubiertos por matorral xerófilo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12127','espacio','Barranco de la Cérvol y umbrías de la Sierra del Turmell','Uno de los paisajes más salvajes y despoblados del Maestrazgo, caracterizado por un cañón fluvial kilométrico flanqueado por altos paredones calcáreos de estratos verticales. Alberga imponentes bosques de encinar montano, quejigales y sabinares en un excelente estado de conservación.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12128','espacio','El Tossal de la Vila y la Roca Grossa','Promontorio de areniscas triásicas rojas que emerge de manera prominente sobre la Plana, mostrando procesos de meteorización alveolar en sus bloques. La vegetación está dominada por una densa maquia mediterránea con palmitos y pinos piñoneros residuales.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12132','espacio','Barranco de la Fuente de la Carrasca','Relieve colinado suave sobre arcillas y calizas del Mioceno, modelado por la escorrentía superficial de carácter torrencial. Cuenta con matorrales de romero y tomillo y pequeños rodales de pino carrasco en las vertientes de umbría.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12134','espacio','Barranco de Ensegures y muelas del Alto Maestrazgo','Cañón kárstico menor labrado sobre calizas cretácicas con presencia de lapiaces superficiales y oquedades de disolución química. Las repisas rocosas cobijan comunidades rupícolas basófilas y matorrales espinosos mediterráneos.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90358','espacio','Paisaje Protegido de la Desembocadura del río Mijares (El Termet)','Tramo de llanura aluvial baja donde el río Mijares se encaja suavemente creando terrazas cuaternarias de gravas. Destaca por su bosque de ribera relicto con álamos blancos, sauces y una densa orla de cañaveral y vegetación palustre.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90357','espacio','Manantiales termales y estribaciones de la Sierra de Espadán','Punto de falla tectónica en el contacto entre las areniscas paleozoicas de la sierra y los sedimentos de la plana, originando surgencias de aguas hipertermales. Las laderas circundantes muestran un relieve abrupto cubierto de matorral esclerófilo con palmito.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12130','espacio','Nacimiento del río Carbo y macizo de Penyagolosa','Impresionante entorno de alta montaña pirenaico-bética con colosales escarpes calizos y desfiladeros fluviales de aguas cristalinas de alta energía geomorfológica. Su umbría húmeda cobija bosques relictos subatlánticos con   tejos, acebos, melojos y pinsapos de repoblación histórica exitosa. Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12131','espacio','Barranco del Tajar y alcornocales de Espadán','Relieve de fuertes pendientes y perfiles afilados labrado sobre areniscas rodenas en el corazón del parque natural. Las laderas de umbría están tapizadas por una masa continua y virgen de alcornoque mezclada con densos helechales y madroñales.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12133','espacio','Barranco de la Maimona (cabecera) y pinares del Alto Palancia','Altiplano calizo que empieza a fracturarse en profundos tajos fluviales hacia la cuenca del Mijares. El dosel vegetal está configurado por densas masas puras de pino negral y pino albar bien adaptadas al clima continentalizado de altitud.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12137','espacio','Cingles de Villores y riberas del río Bergantes','Escarpados farallones calizos que flanquean de forma abrupta el curso del río Bergantes en la comarca de Els Ports. El río presenta un lecho pedregoso con barras de grava estables rodeadas de sauces arbustivos y vegetación de ribera de montaña.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11018','espacio','Acantilados de la costa norte (Sòl de Riu) y desembocadura del río Cérvol','Costa no-playa caracterizada por pequeños acantilados de conglomerados y calcarenitas cuaternarias erosionados en formas de entrantes y salientes por el oleaje. El borde superior alberga comunidades de hinojo marino, ensaladas de mar y matorral halófilo.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12139','espacio','Parque Natural del Penyagolosa, Poljé de la Trucha y barranco de la Pegunta','Uno de los enclaves geológicos y botánicos más colosales del mediterráneo español, centrado en el poljé kárstico inundable más perfecto de la región y el barranco de la Pegunta. Es un santuario botánico hiperhúmedo que alberga bosques densos de pino albar, tejos milenarios, acebos, arces y robles pubescentes relictos de las glaciaciones.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12140','espacio','Paraje de la Floresta y cañón del río Palancia','Singular estrechamiento fluvial donde las aguas del Palancia cortan estratos calcáreos y sutiles capas de travertinos (tobas calcáreas) con cascadas y surgencias continuas. El entorno umbrío genera un microclima de gran exuberancia botánica rico en helechos y hiedras.   Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12141','espacio','Balma de Zorita y cañón del río Bergantes','Impresionante abrigo natural kárstico de dimensiones colosales excavado por erosión fluvial y disolución química sobre un farallón calizo vertical. Las   márgenes del río Bergantes exponen estratos geológicos plegados y una densa vegetación ripícola de montaña alta. Castellón).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12142','espacio','Barranco de la Tejería y pinares del Alto Mijares','Relieve de alta montaña media caliza caracterizado por profundas incisiones fluviales y una topografía de vertientes abruptas. Cuenta con magníficas masas forestales de pino negral y pino albar que colonizan los suelos calcáreos y los escarpes rocosos del término.   ¡Completada la provincia de Castellón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90823','espacio','Valle del río Tirteafuera y micro-karst de la Cueva de los Muñecos','Cuenca fluvial menor encajada entre lomas de pizarras paleozoicas donde la escorrentía ha generado escarpes lineales moderados. El afloramiento calizo aislado del término alberga pequeñas cavidades kársticas colonizadas por comunidades vegetales criptogámicas de umbría.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90323','espacio','Sierras del Alcornocal y de la Alcobilla','Alineaciones de crestones cuarcíticos de relieve apalachense que marcan el límite occidental de la provincia con Extremadura. Sus laderas de umbría resguardan manchas densas de monte mediterráneo virgen compuestas por alcornoques, quejigos y madroñales altos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90324','espacio','Valle del río Alcudia y escarpes de la Sierra de la Bienvenida','Depresión tectónica flanqueada por relieves abruptos de cuarcitas armoricanas donde la dinámica fluvial muestra taludes rocosos expuestos. La vegetación está dominada por encinares adehesados de gran valor estructural y matorrales heliófilos de jara pringosa.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90325','espacio','Lomas del río Villanueva y afloramientos arcillosos del Campo de Montiel','Relieve ondulado sobre arcillas y calizas del Mioceno que configura una topografía de suaves muelas y laderas erosionadas de perfiles rojizos. Cuenta con pequeñas formaciones arbustivas mediterráneas adaptadas a suelos calizos sueltos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13001','espacio','Complejo Lagunar de Alcázar (Lagunas de Las Yeguas, Camino de Villafranca y La Veguilla)','Humedales endorreicos de aguas hiperhalinas estacionales asentados sobre una llanura sedimentaria de costras calizas. La vegetación destaca por sus comunidades halófilas extremas de almajos (Arthrocnemum), carrizales someros y praderas subacuáticas salinas de gran valor contemplativo.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13021','espacio','Estrecho de las Hoces del río Guadiana','Colosal desfiladero fluvial donde el río Guadiana corta de forma transversal las duras sierras cuarcíticas de los Montes de Toledo meridionales, generando farallones de roca desnuda verticales de gran impacto de imagen visual. Las repisas umbrías cobijan una riquísima vegetación rupícola, enebros de gran porte y monte mediterráneo virgen.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90326','espacio','Volcán de la Cruz y laguna kárstico-volcánica de la Alberquilla','Edificio volcánico monogénico compuesto por piroclastos y coladas basálticas que genera una morfología de cerro prominente cónico en la llanura del Campo de Calatrava.   El cráter alberga una cubeta endorreica donde se acumula agua estacional rodeada de matorral esclerófilo. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90327','espacio','Vaguada del río Jabalón y cerros calizos','Suave depresión erosiva labrada sobre los sedimentos miocénicos del Campo de Montiel con escasa diferenciación vertical. El lecho del río muestra formaciones dispersas de tarajes y comunidades herbáceas adaptadas a regímenes de estiaje severo.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90328','espacio','Sacro-Convento de Calatrava la Nueva (Entorno geológico del Cerro de los Cristales)','Macizo de cuarcita armoricana de cumbres afiladas y escarpes verticales originados por la orogenia hercínica, que domina la cuenca del Jabalón. El lanchar pétreo desnudo está colonizado por líquenes crustáceos rupícolas y tomillares xerófilos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90329','espacio','Muelas calcáreas de Alhambra y cabecera del río Azuer','Elevada plataforma estructural tabular de perfiles angulosos y laderas escarpadas de calizas del Terciario superior. Su morfología de cerro testigo destaca visualmente sobre la planicie manchega y alberga comunidades vegetales gipsícolas y basófilas.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90825','espacio','Garganta del río Valdeazogues y peña del Fraile','Sinuoso cañón fluvial excavado sobre pizarras y cuarcitas ricas en cinabrio volcánico-sedimentario que expone perfiles geológicos verticales de gran interés visual. Los   márgenes fluviales sostienen un pasillo denso de saucedas y adelfares mixtos bien conservados. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90330','espacio','Dehesas del río Gargantilla','Paisaje penillanurero de relieve suavemente quebrado modelado sobre materiales paleozoicos de la cuenca minera. Presenta formaciones boscosas aclaradas de encina y un estrato arbustivo mediterráneo dominado por jarales de jara pringosa y cantueso.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90331','espacio','Cerros del Campillo y fuentes de Almedina','Relieve colinado de transición estructural compuesto por calizas mesozoicas fracturadas que propician pequeñas surgencias hídricas estacionales. Muestra comunidades vegetales de matorral bajo espinoso mediterráneo y pastizales secos continentales.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90332','espacio','Valle de Alcudia, Volcán de Los Castillejos y escarpes de la Sierra de la Alcudia','Inmensa depresión sinclinal flanqueada por crestones cuarcíticos paralelos de relieve apalachense, rota por pitones volcánicos basálticos prismáticos de gran valor contemplativo. Alberga dehesas de encina centenarias de dimensiones kilométricas con un sotobosque intacto de monte mediterráneo de umbría.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90333','espacio','Desfiladero de Despeñaperros (vertiente septentrional) y barranco de Valdeazores','Impresionante hendidura geológica vertical labrada por erosión lineal sobre cuarcitas paleozoicas que marca el límite con Andalucía. Las laderas escarpadas   albergan bosques mixtos mediterráneos muy húmedos con quejigos, alcornoques, madroños y una densa flora rupícola. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90334','espacio','Garganta del río Estena y dehesas de Anchuras','Enclave de los Montes de Toledo caracterizado por valles encajados en V sobre pizarras y areniscas con pendientes pronunciadas. El curso fluvial del Estena presenta una de las alisedas y bosques galería más puros y continuos de la comarca prelitoral central.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90335','espacio','Riberas del río Gigüela y humedales aluviales','Llanura de inundación fluvial baja caracterizada por depósitos de arenas y limos cuaternarios del acuífero de La Mancha. Muestra formaciones ripícolas relictas compuestas por densos tarajales y comunidades de eneas adaptadas al encharcamiento estacional.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90336','espacio','Maar de la Laguna de la Alberquilla y Sierra de Mestanza','Gran cráter de explosión hidrovolcánica (maar) excavado sobre el relieve calizo-pizarroso que alberga de forma intermitente una laguna somera. El entorno vegetal perimetral cuenta con encinares de montaña y matorrales mediterráneos densos de jara y lentisco.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13003','espacio','Estrecho de Peñarroya y vega alta del río Guadiana','Estrechamiento fluvial labrado por el río Guadiana sobre las calizas del Campo de Montiel antes de abrirse a la llanura manchega. El paraje muestra un relieve de cortados rocosos y un lecho fluvial flanqueado por densos carrizales y comunidades de vegetación palustre.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13022','espacio','Macizo volcánico de la Atalaya y cuenca del Jabalón','Relieve colinado de origen volcánico compuesto por coladas basálticas y piroclastos negros que rompen la llanura miocénica. La vegetación predominante está constituida por pastizales secos continentales y matorral mediterráneo esclerófilo adaptado a suelos pedregosos de alta insolación.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13023','espacio','Depresión aluvial del arroyo de Cuero','Llanura horizontal sedimentaria constituida por limos y arcillas de la cuenca media del río Guadiana. Conserva pequeñas agrupaciones relictas de tarajes y comunidades herbáceas nitrófilas que marcan los cauces de escorrentía estacional.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13024','espacio','Sierra de Alcudia y cañón del río Ojailén','Espectacular relieve de tipo apalachense con crestones de cuarcita armoricana que se elevan paralelos sobre valles de pizarras erosionadas. Sus laderas de umbría resguardan un denso y virgen monte mediterráneo compuesto   por madroñales puros, quejigos, alcornoques y una rica orla de brezales. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13025','espacio','Sierra de la Cabreja y dehesas del río Tirteafuera','Alineación montañosa de cuarcita paleozoica con crestas afiladas que domina una amplia penillanura pizarrosa adehesada. El relieve presenta canchales de piedras sueltas colonizados por líquenes crustáceos rupícolas y jarales de jara pringosa.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13026','espacio','Valle de Alcudia, Puerto de Pulido y escarpes de la Sierra Mayor','Vertiente de fuerte pendiente fracturada por la tectónica hercínica que ofrece un desnivel topográfico espectacular hacia la depresión de Alcudia. La cubierta forestal destaca por alcornocales montanos mixtos y densos matorrales de ladera ricos en madroños y durillos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13027','espacio','Hoya de Cervera (Maar volcánico) y Sierra de la Atalaya','Impresionante cráter de explosión hidrovolcánica (maar) declarado Monumento Natural, tallado sobre cuarcitas y relleno de sedimentos lacustres estacionales. Los escarpes de la sierra circundante albergan comunidades de encinar montano y un matorral esclerófilo muy denso.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13028','espacio','Sierra de los Molinos y cerros margosos de la Mancha','Relieve colinado suave constituido por afloramientos de calizas lacustres y costras calcáreas que   rompen la monotonía de la llanura sedimentaria. Presenta formaciones de matorral bajo mediterráneo y caméfitos basófilos adaptados a la escasez de suelo. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13029','espacio','Volcán de la Cornudilla y llanuras basálticas','Relieve ondulado dominado por la presencia de edificios volcánicos desmantelados por la erosión diferencial en el Campo de Calatrava. El sustrato de tierras negras y piroclastos sustenta pastizales vivaces xerófilos y comunidades herbáceas singulares.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13030','espacio','Laguna de Caracuel y escarpes del cerro de las Castillejas','Laguna endorreica estacional asentada en una fosa tectónica flanqueada por crestones cuarcíticos de perfiles angulosos. La lámina de agua variable está orlada por carrizales densos, castañuelas y vegetación palustre adaptada a la fluctuación salina.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13031','espacio','Riberas del río Guadiana y hervideros del agua amarga','Tramo fluvial de llanura baja donde destacan surgencias hidrotermales con emisión gaseosa de dióxido de carbono asociadas al vulcanismo. Las márgenes del Guadiana presentan alamedas y densos tarajales que colonizan los sedimentos aluviales.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13032','espacio','Cañón del río Azuer y muelas del Campo de Montiel','Profunda incisión fluvial excavada sobre calizas eocénicas y arcillas rojas, generando taludes de fuerte pendiente y abrigos de disolución kárstica. El fondo del valle   cuenta con un bosque galería continuo flanqueado por encinares de ladera. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13033','espacio','Sierra del Relumbrar y dehesas del arroyo de las Quebradas','Contrafuertes montañosos compuestos por cuarcitas paleozoicas orientados hacia Sierra Morena, caracterizados por un relieve abrupto de bloques fracturados. Alberga masas forestales mixtas de encina, alcornoque y extensos jarales que fijan los suelos silíceos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13038','espacio','Cañón del río Valdeazogues y Sierra de la Virgen de la Castillo','Estrechamiento fluvial espectacular donde el río corta de forma sinuosa las estructuras de pizarra y cuarcita, creando paredes verticales de roca desnuda. Las umbrías resguardan un microclima húmedo idóneo para madroñales densos y comunidades de helechos rupícolas.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13004','espacio','Maar de la Laguna de la Posadilla (Fuentillejos) y llanura del Guadiana','Colosal cráter de explosión hidrovolcánica que alberga una laguna permanente de aguas profundas encerrada por paredes calizas y basálticas. La cubeta constituye un enclave contemplativo único de transición entre el vulcanismo de Calatrava y la llanura aluvial.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13035','espacio','Volcán de la Yezosa y gargantas del río Guadiana','Edificio volcánico imponente que conserva una colada de lava basáltica de gran desarrollo longitudinal adyacente al cauce encajado del Guadiana. La vegetación   está integrada por encinares aclarados y una densa maquia mediterránea adaptada a los canchales negros volcánicos. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13036','espacio','Valles de la Sierra de los Cortijos y cabecera del río Bejarano','Paisaje accidentado de media montaña en los Montes de Toledo, configurado por valles angostos y crestones cuarcíticos paralelos. Las zonas de umbría están cubiertas por frondosos bosques mixtos de roble rebollo, quejigos y una densa orla arbustiva húmeda.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13037','espacio','Lomas del río Vega y muelas de caliza lacustre','Topografía ondulada sobre los materiales sedimentarios del Campo de Montiel con procesos de erosión laminar en las pendientes arcillosas. Conserva dehesas de encina aclaradas y pastizales estacionales continentales resistentes al frío invernal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13005','espacio','Parque Nacional de las Tablas de Daimiel y Ojos del Guadiana','Último exponente de ecosistema kárstico de tablas fluviales, originado por la confluencia del río Guadiana y su afluente Cigüela con las descargas del Acuífero 23 [Daimiel]. La lámina de agua genera una cubeta palustre colosal dominada por el mayor tarayal de la península y densas masas de masiega (Cladium mariscus) [Daimiel].   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13040','espacio','Estrecho del río Bañuelo y Embalse de Gasset','Relieve de transición donde el río Bañuelo se encaja entre cerros cuarcíticos y pizarrosos antes de unirse al Guadiana. Las márgenes de la gran masa de agua presentan alamedas maduras y matorrales esclerófilos de jara pringosa que colonizan las laderas de solana.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13041','espacio','Sierras de la Umbría y curso del río San Marcos','Paisaje forestal puro integrado en el relieve apalachense de los Montes de Toledo, caracterizado por valles paralelos encajados en pizarras. Sus umbrías albergan quejigales densos, rebollares y madroños de porte arbóreo en un excelente estado de conservación botánica.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13042','espacio','Chorrera de las Sierpes, Peña de Miranda y madroñales de la Sierra de la Aliseda','Impresionante relieve escarpado de cuarcitas en el corazón de Sierra Morena, donde la dinámica torrencial genera cascadas de gran energía sobre la roca desnuda. Cuenta con los bosques mediterráneos más húmedos de la provincia, repletos de alcornocales hiperdensos, quejigales y matorrales arborescentes.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13043','espacio','Manantiales del Campo de Montiel y cuenca del río Tortillo','Relieve suavemente ondulado sobre arcillas miocénicas y costras calizas lacustres que propician pequeñas surgencias estacionales de agua. Muestra comunidades de pastizales vivaces calcícolas y matorrales bajos mediterráneos adaptados a la escasez de suelo.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13044','espacio','Sierra de la Calderina y Puerto de Reventón','Alineación montañosa de dirección hercínica que separa las cuencas del Guadiana y el Tajo mediante crestones cuarcíticos afilados. La ladera umbría cobija un dosel forestal muy tupido compuesto por encinas, quejigos, madroños y densos brezales de montaña.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13045','espacio','Volcán-maar de la Columba y cerros de cuarcita de la Encantada','Destacado conjunto geomorfológico del Campo de Calatrava que exhibe un cráter de explosión volcánica y coladas basálticas fosilizadas. El contraste visual es elevado debido a los canchales negros y piroclastos donde proliferan matorrales esclerófilos mediterráneos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13046','espacio','Cañón del río Guadalmez y Sierra de Alcudia occidental','Estrechamiento fluvial colosal que marca el límite con Andalucía, labrado sobre pizarras y areniscas paleozoicas fuertemente fracturadas. Los márgenes del cauce presentan adelfares densos, tamujas y saucedas que tapizan un relieve abrupto de gran valor visual.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13047','espacio','Sierra de la Serna y lomas calizas del norte','Cerros testigo e inselbergs calizos aislados que emergen de forma prominente sobre la llanura sedimentaria manchega. La vegetación está integrada por tomillares basófilos, aliagares y comunidades de líquenes adaptados a la extrema insolación estival.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13048','espacio','Valle de Alcudia oriental y desfiladero del río Montoro','Majestuoso cañón fluvial encajado de manera salvaje entre altas paredes de cuarcita armoricana de perfil vertical. Las repisas rocosas de la umbría resguardan comunidades de enebros de gran porte, líquenes rupícolas y monte mediterráneo virgen de gran densidad.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13049','espacio','Parque Nacional de Cabañeros y garganta del río Rubial','Uno de los paisajes montanos más colosales de los Montes de Toledo, donde las cuarcitas y pizarras forman valles profundos en V y escarpes verticales. El paraje alberga bosques galería maduros de alisos y fresnos, rodeados de inmensos quejigales y melojares hiperhúmedos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13050','espacio','Llanura aluvial del río Gigüela','Relieve llano horizontal constituido por depósitos de limos, arcillas y arenas del cuaternario en la Mancha centro. Muestra pequeñas agrupaciones de tarajales y comunidades macrofíticas adaptadas a los flujos de agua intermitentes de carácter salobre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13904','espacio','Llanura aluvial del acuífero de La Mancha','Relieve horizontal absoluto constituido por costras calcáreas cuaternarias y depósitos limosos finos. Conserva comunidades herbáceas efímeras adaptadas a la extrema continentalidad térmica y a sutiles depresiones con humedad edáfica temporal.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13051','espacio','Confluencia del río Bullaque con el río Guadiana y escarpes de la Sierra de la Solanilla','Espectacular nudo fluvial donde los cauces se encajan entre crestones de cuarcita armoricana de relieve apalachense. Las márgenes albergan un excelentísimo y continuo bosque galería de alisos, sauces y grandes formaciones de adelfares que contrastan con los jarales de las laderas.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13008','espacio','Lagunas kárstico-volcánicas de Malagón (La Navas, Las Cunas y Grande)','Complejo lagunar de origen freatomagmático y kárstico asentado en cubetas endorreicas sobre materiales paleozoicos de los Montes de Toledo. Las láminas de agua variables están rodeadas por orlas de vegetación palustre, carrizales densos y comunidades halófilas de gran interés botánico.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13009','espacio','Vegas del río Azuer y dehesas de la dehesilla','Llanura sedimentaria donde el río Azuer pierde gradiente y deposita arenas y cantos rodados cuaternarios. Presenta retazos de encinares aclarados e interesantes   comunidades de tarajales dispersos que sobreviven al acusado estiaje veraniego. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13055','espacio','Cañón del río Montoro, Sierra Madrona y Hoz de Valdomoro','Impresionante garganta geológica de paredes verticales labrada sobre cuarcitas armoricanas de la vertiente norte de Sierra Morena. Su relieve quebrado y abrupto resguarda un dosel boscoso mediterráneo hiperhúmedo rico en alcornoques, quejigos, madroñales puros y comunidades rupícolas raras.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13011','espacio','Cerros volcánicos de Cabezo Negro y llanura de Calatrava','Pequeñas elevaciones cónicas originadas por la emisión de basaltos y piroclastos que rompen la penillanura sedimentaria manchega. La vegetación está compuesta por pastizales secos, matorrales esclerófilos y líquenes que colonizan las escorias volcánicas oscuras.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13057','espacio','Nacimiento del río Segura (Fuentes secundarias) y muelas del Campo de Montiel','Altiplano de relieves tabulares calizos donde la erosión ha esculpido escarpes angulosos y valles encajados de perfiles arcillosos rojizos. Cuenta con surgencias de agua intermitentes y formaciones botánicas basófilas compuestas por tomillares y aliagares de montaña media.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13059','espacio','Estrecho del río Guadiana y Sierra de Lesas','Profunda hendidura fluvial donde el río Guadiana se abre paso de forma sinuosa cortando las   estructuras de cuarcitas y pizarras de los Montes de Toledo. El entorno forestal destaca por su monte mediterráneo denso e intacto, con abundantes madroños arbóreos, quejigales y brezales altos. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13060','espacio','Boquerón del río Estena y Parque Nacional de Cabañeros','Uno de los cañones fluviales más colosales del macizo paleozoico central, donde la erosión ha dejado al descubierto huellas fósiles marinas y estratos verticales de cuarcita armoricana. El fondo del desfiladero es un vergel botánico umbrío compuesto por alisedas, tejos relictos, acebos y densos helechales.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13061','espacio','Complejo Lagunar de Pedro Muñoz (Lagunas de la Vega, del Retamar y de Alcahozo)','Cubetas endorreicas de aguas salobres estacionales originadas sobre el sustrato calizo de la Mancha alta. Alberga comunidades halófilas extremas dominadas por almajos (Arthrocnemum), carrizales perimetrales y praderas de ovas sumergidas de gran valor ecológico.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13063','espacio','Tabla de la Yedra (Río Bullaque) y Volcán de la Arzollosa','Espectacular tramo fluvial remansado donde el río Bullaque ensancha su cauce sobre depósitos aluviales, flanqueado por un frondoso bosque de galería de alisos y fresnos monumentales. Al norte destaca el edificio volcánico de la Arzollosa con coladas basálticas muy bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13064','espacio','Volcán de Cabezo Rey y meandros del río Guadiana','Relieve colinado de origen freatomagmático que destaca sutilmente en la vega aluvial del Guadiana. Los taludes del cauce fluvial muestran depósitos sedimentarios   cuaternarios colonizados por densos tarajales y sauces arbustivos. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13065','espacio','Volcán del Cerro de los Santos y riberas del río Bullaque','Imponente pitón volcánico basáltico que conserva una morfología de cúpula cónica de gran valor visual sobre el paisaje premontano. El eje del río Bullaque añade un pasillo de vegetación aluvial con alisos monumentales y saucedas en excelente estado de conservación.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13066','espacio','Reserva Natural de la Laguna de la Inesperada','Cráter de explosión hidrovolcánica (maar) colmatado por una cubeta endorreica salina de aguas estacionales someras. Sus márgenes albergan una flora halófila especializada de almajos y comunidades macrofíticas adaptadas a altas concentraciones de sulfatos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13067','espacio','Garganta del río Guadiana y Sierra de la Osa','Estrechamiento fluvial encajonado donde el río Guadiana secciona de forma transversal los relieves cuarcíticos hercínicos. Las laderas de umbría presentan manchas densas de monte mediterráneo mixto con madroños arbóreos y jarales silíceos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13068','espacio','Estrecho de las Hoces del río Guadiana y meandros del río Bullaque','Uno de los cañones fluviales más colosales y vírgenes del interior peninsular, donde el Guadiana corta tajos verticales de cuarcita armoricana de gran impacto visual. El   ecosistema ripícola es excepcional, albergando densos bosques de alisedas y adelfares en las repisas rocosas. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13069','espacio','Sierra de Alcaraz (estribaciones) y cabecera del río Guadalmena','Relieve de media montaña caliza en el extremo suroriental de la provincia que marca la transición hacia los sistemas béticos. Las pendientes albergan encinares montanos bien adaptados a los suelos pedregosos y pastizales secos continentales.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13070','espacio','Sierras de las Umbrías y Puerto de Puerto Lápice','Pequeña alineación montañosa de cuarcitas que ejerce como barrera natural y pasillo erosivo entre la llanura manchega y los Montes de Toledo. Las laderas están cubiertas por matorral mediterráneo esclerófilo dominado por el romero y la coscoja.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13013','espacio','Carbonífero de Puertollano y Fuente Agria','Depresión tectónica e intramontana que expone una serie estratigráfica del Carbonífero Superior de gran singularidad geológica. El subsuelo volcánico propicia la surgencia de aguas minero-medicinales de marcado carácter ferruginoso y desprendimiento gaseoso.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13072','espacio','Embalse de Torre de Abraham, río Milagro y laderas de Cabañeros','Impresionante paisaje de montaña apalachense donde el río Milagro excava un desfiladero umbrío entre crestones cuarcíticos. Alberga formaciones botánicas puras y   continuas de roble rebollo, quejigales y un denso sotobosque de brezales arborescentes de carácter atlántico relicto. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13014','espacio','Parque Natural de las Lagunas de Ruidera','Uno de los complejos kársticos y sistemas lagunares más espectaculares de Europa, formado por un rosario de quince lagunas conectadas por cascadas y saltos de agua sobre barreras de travertino (tobas calcáreas) de formación activa. La vegetación está integrada por densos carrizales, masiega, eneas y sabinares albares en las parameras superiores.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13073','espacio','Dehesas del río Esteras y lomas pizarrosas','Relieve ondulado de la penillanura occidental cacereño-manchega labrado sobre pizarras paleozoicas. Cuenta con extensos encinares en régimen de dehesa madura y jarales de jara pringosa que colonizan los suelos esqueléticos de las vertientes.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13074','espacio','Vertientes de la Sierra del Castillejo y cuenca del Azuer','Relieve colinado suave constituido por materiales detríticos y calizas lacustres eocénicas que delimitan el valle. La vegetación del entorno está dominada por tomillares, aliagares y matorral bajo mediterráneo adaptado a la aridez estival.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13075','espacio','Hoz del río Solís y escarpes de Sierra Madrona','Angosto cañón fluvial excavado sobre potentes bancos de cuarcitas en la vertiente septentrional de Sierra Morena. Su relieve quebrado resguarda un dosel de bosque   mediterráneo hiperhúmedo rico en alcornoques, quejigos y madroñales puros de gran porte botánico. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13076','espacio','Vaguada del río Tortillo y lomas del Campo de Montiel','Suaves ondulaciones topográficas sobre arcillas miocénicas con procesos de erosión laminar en las pendientes agrícolas. Conserva retazos de encinar aclarado y pastizales estacionales continentales adaptados a la oscilación térmica.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13015','espacio','Dehesas de las Virtudes y estribaciones de Sierra Morena','Zona de contacto geomorfológico entre la llanura sedimentaria de la Mancha y los primeros relieves paleozoicos del sur. Presenta encinares adehesados y matorrales heliófilos dominados por la jara pringosa y el cantueso sobre suelos silíceos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13016','espacio','Riberas del río Záncara y costras calcáreas','Relieve horizontal absoluto correspondiente a la llanura aluvial del Záncara sobre depósitos de limos y arenas cuaternarias. Muestra pequeñas formaciones dispersas de tarajes y comunidades herbáceas adaptadas al prolongado estiaje mediterráneo.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13007','espacio','Vega del río Azuer y cerros del Carbón','Llanura sedimentaria interrumpida por pequeñas elevaciones calizas miocénicas de perfil tabular bajo. Los márgenes del río Azuer conservan bandas fragmentadas de vegetación hidrófila con juncales y carrizales.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13081','espacio','Nacimiento del río Guadalhermosa y muelas de Terrinches','Elevada plataforma estructural caliza del Campo de Montiel fracturada por la disolución kárstica que propicia la aparición de surgencias hídricas estacionales. Da cobijo a comunidades de tomillar-alicatado y matorral bajo mediterráneo basófilo.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13017','espacio','Llanura endorreica y costras calizas de la Mancha','Topografía plana sin red hidrográfica superficial definida debido a la alta permeabilidad de las calizas lacustres terciarias. Alberga comunidades vegetales efímeras de carácter estepario adaptadas a suelos esqueléticos de extrema continentalidad.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13083','espacio','Humedales del río Guadiana y llanuras basálticas','Zona llana de la cuenca del Guadiana donde afloran coladas de lava y piroclastos oscuros del Campo de Calatrava. El entorno cuenta con pequeñas comunidades de tarajes y carrizales palustres en los márgenes de escorrentía estacional.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13084','espacio','Dehesas del río Serrano y estribaciones de Sierra Morena','Relieve ondulado y quebrado compuesto por pizarras y cuarcitas paleozoicas en la transición meridional. El paisaje visual ofrece un mosaico de encinares adehesados, jarales densos y matorral esclerófilo mediterráneo.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13085','espacio','Cerros de la Cabezuela y cuenca del río Jabalón','Relieve colinado de vertientes suaves labrado sobre materiales detríticos eocénicos. Cuenta con pequeñas formaciones arbustivas mediterráneas y comunidades de pastizales vivaces adaptadas a la escasez de suelo y alta insolación.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13086','espacio','Cañón del río Esteras y peñas calcáreas','Estrechamiento fluvial espectacular flanqueado por altos paredones calcáreos y pizarrosos que muestran marcas de disolución y pequeñas oquedades kársticas. La vegetación destaca por un denso monte mediterráneo con adelfares y saucedas en el cauce.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13018','espacio','Cerros del Ángel y vega del río Jabalón','Amplia llanura sedimentaria interrumpida por cerros testigo de calizas eocénicas y costras calcáreas de perfiles redondeados. Muestra una vegetación rala integrada por tomillares, aliagares y comunidades herbáceas continentales.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13088','espacio','Cerro de la Cervera (pitón volcánico)','Formación geológica cónica aislada que sobresale en la llanura, originada por la emisión de basaltos negros y escorias volcánicas. La vegetación es rala, compuesta por líquenes crustáceos rupícolas y matorrales esteparios adaptados al sustrato rocoso.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13089','espacio','Cabecera del río Azuer y lagunas de la dehesa','Altiplano calizo caracterizado por un modelado kárstico de pequeñas dolinas y valles ciegos donde el agua se infiltra con rapidez. Alberga interesantes comunidades de   sabina albar y encinares montanos bien adaptados a la rigurosidad térmica invernal. Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13090','espacio','Estrecho del río Guadalmena y dehesas de Montiel','Cañón fluvial menor labrado sobre rocas sedimentarias mesozoicas con presencia de lechos de roca madre pulidos por la corriente. Los escarpes umbríos acogen una vegetación mixta con presencia de encinas y arbustos ripícolas mediterráneos.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13091','espacio','Monumento Natural del Volcán de la Yezosa y Laguna de Caracuel (límite)','Edificio volcánico de gran relevancia geomorfológica que expone coladas de lava basáltica prismáticas y depósitos de piroclastos. El entorno edáfico oscuro sustenta pastizales vivaces y matorrales xerófilos de gran valor ecológico.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13092','espacio','Nacimiento del río Villanueva y muelas calcáreas','Gran surgencia kárstica perenne donde el agua brota directamente de las entrañas de la roca caliza del Campo de Montiel. El paraje fluvial muestra un lecho de aguas cristalinas rodeado de fresnedas y olmedas naturales de notable valor botánico.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13019','espacio','Valles del río Jabalón y dehesas de Infantes','Relieve de campiña suavemente ondulada modelado sobre margas y arcillas terciarias del neógeno. En los márgenes del cauce intermitente se desarrollan pequeñas choperas autóctonas y saucedas arbustivas mediterráneas.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13094','espacio','Volcán de la Laguna de la Alberquilla y Sierra de Mestanza (vertiente norte)','Cráter de explosión hidrovolcánica que alberga una pequeña cuenca endorreica estacional entre relieves de cuarcitas paleozoicas. Cuenta con masas de encinar montano y un matorral esclerófilo muy tupido y bien conservado.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13095','espacio','Llanura sedimentaria del Campo de Calatrava','Topografía horizontal absoluta interrumpida por sutiles ondulaciones de origen piroclástico desmanteladas por la erosión. Presenta formaciones herbáceas estacionales adaptadas a suelos arcillosos compactos de origen volcánico.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13096','espacio','Parque Nacional de las Tablas de Daimiel (vertiente norte) y Sierra de la Calderina','Espectacular punto de contacto geológico donde los escarpes cuarcíticos de los Montes de Toledo mueren de forma abrupta en la llanura palustre de las Tablas. El contraste visual es colosal, combinando densas umbrías montanas de quejigal con los inmensos carrizales del humedal.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13097','espacio','Terrazas del río Gigüela','Llanura aluvial amplia con depósitos de gravas y limos fluviales acumulados durante el Cuaternario. Muestra tarajales dispersos y comunidades de eneas adaptadas a corrientes lentas de agua de carácter salobre.   Ciudad Real).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13020','espacio','Valle de los Desunidos y Sierra de la Mudela','Relieve quebrado y abrupto integrado en las estribaciones septentrionales de Sierra Morena, compuesto por pizarras y cuarcitas. Alberga una de las masas forestales más densas y ricas de la provincia, con alcornocales, quejigales de umbría y madroñales puros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90740','espacio','Garganta del río Guadalmellato y dehesas de Sierra Morena','Relieve quebrado y abrupto labrado sobre pizarras paleozoicas y cuarcitas que configuran laderas de vertiginosa pendiente hacia el eje fluvial. El paraje destaca por albergar masas puras de monte mediterráneo luso-extremeño, con madroñales altos, alcornoques y densos jarales.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17001','espacio','Reserva Natural de la Laguna de la Zoñar','La cubeta húmeda más profunda del complejo endorreico cordobés, asentada sobre margas yesíferas miocénicas e impermeables. Su lámina de agua permanente presenta un alto grado de mineralización y está rodeada por un denso cinturón botánico de tarajes, carrizos y eneas.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90741','espacio','Salto del Caballo, garganta del río Caicena y travertinos de la Fuente del Río','Imponente cañón fluvial excavado sobre calizas mesozoicas de la Subbética, caracterizado por escarpes verticales y cascadas activas que depositan tobas calcáreas (travertinos). Las repisas húmedas de la umbría resguardan una densa vegetación rupícola, helechales y musgos.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17002','espacio','Parque Natural de la Sierra de Hornachuelos y dehesas del río Guadiato','Zona de contacto geomorfológico donde los relieves abruptos y pizarrosos de Sierra Morena mueren de forma súbita frente a la llanura aluvial del Guadalquivir. Cuenta con densos encinares montanos, acebuchar termófilo y grandes formaciones de lentisco en las laderas expuestas.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90445','espacio','Berrocal de Añora y dehesas de Los Pedroches','Paisaje penillanurero dominado por el batolito granítico del norte cordobés, donde abundan las piedras caballeras y los bloques redondeados por meteorización. La vegetación está integrada por un encinar aclarado con un estrato herbáceo adaptado a suelos arenosos ligeros.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17003','espacio','Reserva Natural de la Laguna del Rinconcillo y curso del río Guadajoz','Laguna endorreica de carácter estacional que ocupa una depresión natural sobre margas y yesos triásicos de gran plasticidad erosiva. Alberga comunidades halófilas perennes de almajos y un denso cinturón palustre periférico que frena el arrastre de sedimentos.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17004','espacio','Riberas del río Zújar y dehesas de la dehesa boyal','Llanura suavemente ondulada sobre pizarras del Carbonífero donde el río Zújar se encaja de forma sinuosa abriendo taludes de roca expuesta. Presenta un pasillo vegetal de ribera bien estructurado con tamujas (Flueggea tinctoria), saucedas y adelfares.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90447','espacio','Grieta tectónica de Benamejí y cañón del río Genil','Impresionante tajo fluvial flanqueado por escarpes inestables de arcillas y yesos miocénicos que sufren procesos de deslizamiento geológico masivo. La dinámica erosiva lineal del Genil expone taludes verticales colonizados por matorrales xerófilos y tarajes.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90742','espacio','Lomas del río Zújar y llanuras cerealistas de transición','Topografía de penillanura pizarrosa de perfiles suaves rota de forma sutil por arroyos estacionales de caudal irregular. La cubierta vegetal original es de carácter aclarado, destacando pastizales mediterráneos continentales y matorral bajo espinoso.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17005','espacio','Campiña alta y arroyo de las Culebras','Paisaje monótono de suaves colinas aluviales modeladas sobre depósitos arcillosos y limos finos de la depresión bética. Conserva comunidades herbáceas efímeras y pequeños retazos de matorral mediterráneo esclerófilo en los lindes y taludes.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17006','espacio','Geoparque de las Sierras Subbéticas, Picacho de Cabra, Lapiaz de los Lanchares y Fuente del Río','Uno de los exponentes kársticos más espectaculares de la península, célebre por un campo de lapiaces colosal tallado por disolución sobre calizas jurásicas fosilíferas. El paraje cuenta con la gran surgencia kárstica perenne de la Fuente del Río, rodeada de encinares montanos y quejigales.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90448','espacio','Vaguada del río Cañete y lomas de arcilla','Relieve ondulado de la campiña cordobesa oriental constituido por depósitos de vertiente cuaternarios y arcillas miocénicas compactas. Aloja pequeñas bandas de vegetación riparia con sauces arbustivos adaptados a severos estiajes estivales.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90449','espacio','Poljé de la Nava de Cabra (límite oriental) y cañón de las Buitreras','Espectacular cubeta kárstica cerrada (poljé) y desfiladeros calcáreos de paredes totalmente verticales que muestran un plegamiento tectónico de primer orden. Las laderas y umbrías albergan quejigales andaluces (Quercus faginea subsp. faginea), arces de Montpellier y densas masas de encinar rupícola.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26041','espacio','Parque Natural de Sierra de Cardeña y Montoro, río Yeguas y dehesas graníticas','Majestuoso e intacto paisaje forestal mediterráneo asentado sobre un batolito granítico fracturado por el que discurre encajonado el río Yeguas. Alberga el único pinar mixto de pino piñonero salvaje sobre granito de la provincia, rodeado de encinares y alcornocales maduros excelentes.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14019','espacio','Meandros y terrazas del río Guadajoz','Tramo medio fluvial encajado de manera suave sobre los materiales arcillosos y yesíferos de la campiña. El río describe amplias curvas flanqueadas por depósitos de gravas y limos aluviales donde prosperan densas alamedas y tarajales.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14020','espacio','Dehesas del río Guadalmez y lanchares graníticos','Paisaje penillanurero del extremo norte de la provincia modelado sobre granitos degradados que exponen extensas superficies de roca lisa (lanchares). Acoge dehesas de encina bien estructuradas con un estrato arbustivo dominado por el cantueso y la jara.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','espacio','Monumento Natural Sotos de la Albolafia, escarpes de Sierra Morena y Baños de Popea','Tramo del río Guadalquivir que presenta islas fluviales estables con un exuberante bosque de galería maduro en un entorno de aguas lentas. En su sector norte, el término asciende hacia los desfiladeros calizos del Guadiato y parajes kársticos de gran umbría botánica.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14022','espacio','Sierras Subbéticas, Oreja de la Mula y Laderas de la Serrezuela','Escarpados farallones de calizas y dolomías mesozoicas que se elevan de forma abrupta sobre la depresión del Guadalquivir. Las paredes rocosas verticales albergan comunidades rupícolas raras y la base cuenta con encinares montanos adaptados al lanchar calcáreo.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14023','espacio','Dehesa Boyal de Dos Torres y arroyo de Tarazona','Relieve horizontal absoluto correspondiente a la penillanura estructural de Los Pedroches sobre materiales graníticos compactos. Presenta formaciones boscosas aclaradas de encina y comunidades herbáceas estacionales adaptadas al suelo de sauló.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14024','espacio','Riberas del río Anzur y lomas de arcilla','Relieve de campiña ondulada sobre depósitos de margas miocénicas en el sur provincial. El río Anzur aporta una modesta banda de vegetación hidrófila con sauces arbustivos que contrasta con la rigidez climática estival de las laderas.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14026','espacio','Escalar de Espiel y desfiladero del río Guadiato','Impresionante farallón calizo de origen Carbonífero con paredes verticales que se elevan de forma abrupta sobre el cauce encajado del río Guadiato. Sus grietas albergan valiosas comunidades botánicas rupícolas y en la base crecen encinares montanos bien adaptados a la roca desnuda.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17010','espacio','Arroyo de la Canaleja y campiña baja','Paisaje monótono de colinas de pendiente muy suave modeladas sobre arcillas y limos finos de la cuenca del Guadalquivir. Cuenta con formaciones herbáceas estacionales adaptadas a la escasez hídrica edáfica severa del verano.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14029','espacio','Sierras de la Grana y del Alcornocal','Alineación montañosa paleozoica de dirección hercínica con crestones de cuarcita armoricana y valles paralelos rellenos de pizarras. Su vertiente umbría destaca por albergar un alcornocal denso y húmedo entremezclado con quejigos y madroñales de gran porte.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14030','espacio','Sotos del río Guadalquivir y dehesas de la Colonia','Llanura aluvial madura caracterizada por depósitos detríticos gruesos y cantos rodados del cuaternario. Conserva pequeñas franjas de bosque de ribera con álamos blancos y negros que estabilizan los taludes sedimentarios fluviales.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14034','espacio','Dehesas del río Guadarramilla y lanchares graníticos','Superficie penillanurera granítica con formas de relieve redondeadas por meteorización física y química en el   norte de Los Pedroches. Acoge dehesas de encina aclaradas con un estrato herbáceo adaptado a suelos arenosos ligeros. Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14035','espacio','Complejo endorreico de la Laguna de la Invernada','Pequeña cubeta endorreica natural asentada sobre materiales graníticos degradados que da lugar a una laguna somera estacional. Presenta un entorno visual definido por dehesas de encina con afloramientos de lanchas pétreas horizontales.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14036','espacio','Parque Natural de la Sierra de Hornachuelos, cañón del río Bembézar y Garganta del Guadalora','Uno de los paisajes de media montaña mediterránea más colosales y vírgenes del sur peninsular, donde los ríos excavan profundos cañones en pizarras calcáreas. Es un santuario botánico húmedo con la mayor masa continua de encinas, alcornoques y bosques galería de alisos de la provincia.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14037','espacio','Desfiladero del río Genil y escarpes calcáreos del embalse','Paisaje geomorfológico abrupto donde el río Genil se encaja de forma transversal sobre calizas y margas triásicas antes de la llanura. Las paredes verticales de roca desnuda flanquean la gran lámina de agua y albergan matorrales esclerófilos.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14038','espacio','Reserva Natural de la Laguna Amarga y de la Laguna de los Jarales','Cubetas lagunares de origen kárstico asentadas sobre yesos triásicos de gran plasticidad que acumulan aguas   de escorrentía de alta salinidad. Sus márgenes albergan una rica flora halófila especializada y cinturones perimetrales de tarajes y carrizales. Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14039','espacio','Sierras Subbéticas, Laguna del Conde (o Salobral) y cañón del río Bailón (límite)','Impresionante relieve kárstico de muelas calizas jurásicas con pendientes escarpadas y la presencia de una gran laguna endorreica salina estacional. Las umbrías profundas cobijan quejigares andaluces, arces de Montpellier y comunidades rupícolas muy raras.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14040','espacio','Campiña arcillosa del arroyo del Salado','Geomorfología monótona de colinas bajas arcillosas de la cuenca miocénica que muestran una fuerte erosión laminar. La vegetación natural es residual, compuesta por espinares mediterráneos y pastizales estacionales.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14041','espacio','Cerros testigo de la campiña alta','Formaciones geológicas de relieve aluvial miocénico que sobresalen ligeramente sobre la llanura sedimentaria bética. Presenta pequeñas formaciones herbáceas estacionales adaptadas a suelos francos compactos de alta insolación.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14042','espacio','Lomas del río Cabra y cerros de albarizas','Suaves ondulaciones del terreno constituidas por margas blancas (albarizas) que retienen la humedad subsuperficial de forma excelente. Alberga comunidades de matorral mediterráneo esclerófilo adaptado a la extrema aridez estival en sus taludes.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14043','espacio','Meandro del río Guadalquivir y formaciones de arenisca roja (moliz)','Espectacular y colosal estrangulamiento fluvial donde el río Guadalquivir corta las duras areniscas y gneises de Sierra Morena en un perfil sinuoso único. Los márgenes exponen perfiles de roca roja verticales flanqueados por densos acebuchares y un bosque de ribera maduro.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14044','espacio','Vertientes del río Cabra y lomas calizas','Suave elevación estructural constituida por calcarenitas del Terciario superior con una topografía de suaves vertientes. Presenta retazos de matorral bajo mediterráneo con romero y coscoja.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14047','espacio','Cañón del río Guadiato y dehesas de la Sierra de Obejo','Angosto desfiladero fluvial abierto por la acción erosiva lineal sobre materiales pizarrosos y cuarcitas paleozoicas fuertemente fracturadas. Sus laderas umbrías albergan manchas densas de monte mediterráneo lusoextremeño rico en madroños y encinas.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14048','espacio','Riberas del río Genil (tramo medio)','Tramo fluvial encajado de pendientes moderadas constituido por depósitos de terrazas aluviales arenosas. El cauce está acompañado por una banda continua de vegetación de ribera con sauces, chopos y carrizales bien estructurados.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14049','espacio','Confluencia del río Genil con el río Guadalquivir','Amplia y madura llanura aluvial cuaternaria baja caracterizada por una dinámica de sedimentación activa que genera islas de grava y barras arenosas. Alberga alamedas densas, fresnedas y comunidades macrofíticas adaptadas a corrientes lentas de agua.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14050','espacio','Meandros remansados del río Guadalquivir','Llanura de inundación de relieve plano constituida por limos y arenas fluviales del cuaternario. El curso del agua genera un microambiente húmedo propicio para saucedas, alamedas y grandes masas de eneas en las orillas.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14051','espacio','Valle del arroyo de Santa María y batolito de Los Pedroches','Centro geográfico de la gran penillanura de granito y pizarras del norte, caracterizado por una topografía suave con bolos pétreos dispersos. Cuenta con dehesas de encina bien estructuradas con comunidades de pastizales vivaces calcícolas.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14052','espacio','Peñas del Peñón de Peñarroya y cuenca del río Guadiato','Promontorio de calizas del Carbonífero de perfiles rectilíneos y verticales que emerge de forma abrupta en la cuenca minera pizarrosa. La roca desnuda está colonizada por líquenes crustáceos rupícolas y un matorral mediterráneo esclerófilo bajo.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14053','espacio','Sotos de la Albolafia (Posadas) y Parque Periurbano La Sierrezuela','Zona de contacto entre la vega del Guadalquivir y Sierra Morena, caracterizada por afloramientos de calcarenitas miocénicas y un pinar piñonero maduro. El lecho del río muestra formaciones de tarajes y vegetación palustre densa de notable interés botánico.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14054','espacio','Dehesas de Pozoblanco y lomas graníticas','Relieve horizontal propio del batolito de Los Pedroches constituido por granitos degradados (sauló) que originan pendientes suaves. Alberga un encinar adehesado tradicional bien conservado con pastizales secos continentales.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','espacio','Geoparque de las Sierras Subbéticas, Pico de la Tiñosa, La Nava y nacimiento del río Salado','Impresionante paisaje de alta montaña caliza que alberga la cumbre más elevada de la provincia (La Tiñosa) y colosales cañones kársticos. Su relieve de escarpes y poljés cuenta con quejigales, sabinares albares de montaña y surgencias de agua de gran caudal.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14056','espacio','Reserva Natural de la Laguna de Tíscar','Laguna endorreica de carácter temporal asentada sobre una cubeta de arcillas y margas yesíferas triásicas del sur provincial. La vegetación está constituida por un denso anillo periférico de tarajales (Tamarix boveana), carrizos y eneas adaptados a aguas salobres.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14057','espacio','Arroyo de la Minilla y campiña baja','Topografía de suaves colinas aluviales modeladas sobre depósitos arcillosos finos miocénicos con escasa diferenciación vertical. Presenta matorral bajo mediterráneo y comunidades herbáceas adaptadas a inviernos fríos y veranos secos.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14058','espacio','Sierra de Rute, Garganta de las Hazas y riberas del embalse de Iznájar','Imponente macizo calizo bético de laderas escarpadas y relieve kárstico que se eleva de forma vertiginosa sobre la gran lámina de agua de Iznájar. Sus umbrías albergan una riquísima cobertura boscosa mixta con encinares montanos, quejigos y flora rupícola protegida.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14059','espacio','Arroyo de los Ballesteros','Cauce intermitente menor asentado sobre sedimentos sueltos cuaternarios de la campiña baja cordobesa. La vegetación natural es residual, compuesta principalmente por espinares y pastizales estacionales mediterráneos.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14061','espacio','Sierra de Santa Eufemia y riscos del río Guadalmez','El relieve de cuarcita armoricana más septentrional de la provincia, caracterizado por crestones verticales de afilados perfiles tectónicos. Las laderas pedregosas (canchales) están colonizadas por jarales de jara pringosa, enebros y comunidades rupícolas.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14060','espacio','Lomas del río Cabra y campiña de Santaella','Paisaje monótono de lomas arcillosas y limosas bajas que marcan la divisoria de aguas de la cuenca   sedimentaria bética. Conserva pequeños retazos de matorral esclerófilo mediterráneo en los taludes de mayor pendiente. Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14062','espacio','Riberas del río Guadamora y dehesas de Los Pedroches','Relieve de penillanura pizarrosa y granítica roto de forma suave por la incisión fluvial del río Guadamora. El cauce conserva una banda de vegetación hidrófila con juncales, carrizales y tamujares adaptados al estiaje severo.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14063','espacio','Cerros del Alto del Sol','Pequeñas elevaciones de margas yesíferas triásicas que rompen la horizontalidad de la campiña cordobesa oriental. Cuenta con comunidades vegetales gipsícolas y pastizales mediterráneos continentales.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14064','espacio','Llanuras del río Zújar y lomas de pizarra','Terreno de penillanura pizarrosa de relieve suavemente quebrado modelado sobre materiales del Carbonífero. Alberga pequeñas alineaciones de sauces arbustivos y pastizales estacionales adaptados al frío invernal de Los Pedroches.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14065','espacio','Arroyo de Tocina y llanura de la campiña','Relieve predominantemente llano constituido por depósitos de arenas y arcillas miocénicas estables. Presenta pequeñas formaciones herbáceas estacionales adaptadas a suelos francos mediterráneos.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14066','espacio','Riberas e islas del río Guadalquivir (tramo alto cordobés)','Tramo aluvial donde el río Guadalquivir discurre ensanchado, depositando barras de grava e islas sedimentarias estables. Las orillas albergan masas densas de sauces (Salix alba) y choperas autóctonas bien conservadas.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14067','espacio','Dehesas de la Sierra de Villafranca y meandros del Guadalquivir','Zona de transición geológica donde las laderas pizarrosas de Sierra Morena contactan con la llanura de inundación cuaternaria del río. Presenta encinares de ladera bien estructurados y un pasillo verde de vegetación riparia en el eje fluvial.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14068','espacio','Manantiales de agua agria y monte mediterráneo del Guadiato','Entorno premontano pizarroso de Sierra Morena famoso por albergar numerosas surgencias de aguas mineromedicinales ricas en hierro y gas carbónico. Las laderas están cubiertas por densas masas de encinas, jarales de jara pringosa y cantueso.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14069','espacio','Dehesas de Villanueva y dehesa de la Concordia (Batolito granítico)','El encinar adehesado más extenso y continuo de Los Pedroches, asentado sobre una penillanura granítica con abundante presencia de bolos y formaciones de tor. El sustrato poroso favorece un tapiz herbáceo denso de pastizales vivaces mediterráneos.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14070','espacio','Dehesa Boyal de Villanueva y filones de cuarcita del Viñón','Relieve ondulado y quebrado compuesto por pizarras y cuarcitas paleozoicas de la cuenca central del norte. El paisaje visual ofrece dehesas de encina mezcladas con matorral mediterráneo esclerófilo y jarales silíceos.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14071','espacio','Dehesa de la nava de los reyes y escarpes de la Sierra de la Grana','Relieve de media montaña forestal con valles angostos y crestones cuarcíticos de dirección hercínica. Las laderas de umbría están cubiertas por densos bosques mixtos de encina, alcornoque, quejigales y matorrales arborescentes de madroño.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14072','espacio','Cuenca del río Guadmatilla y dehesas pizarrosas','Suaves ondulaciones de la penillanura septentrional labradas sobre materiales pizarrosos del Carbonífero. Cuenta con un encinar adehesado aclarado con comunidades de matorral bajo de cantueso y aliagares.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14073','espacio','Parque Natural de la Sierra de Hornachuelos (sector oriental) y cañón del río Guadiato','Impresionante y encajonado tajo fluvial excavado sobre pizarras y calizas paleozoicas, flanqueado por altos paredones de roca desnuda. El entorno es una selva mediterránea continua de encinas, alcornoques, densos madroñales y un bosque de galería hiperhúmedo de alisos.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14074','espacio','Riberas del río Guadamatilla y dehesas del norte','Relieve plano ondulado de la penillanura norte de Los Pedroches constituido por depósitos graníticos y pizarrosos degradados. Conserva dehesas de encina maduras y comunidades de tamujares en las zonas de escorrentía estacional.   Córdoba).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14075','espacio','Geoparque de las Sierras Subbéticas, Cañón del Río Bailón y Cueva de los Murciélagos','Uno de los paisajes kársticos de montaña caliza más colosales y espectaculares de la península, célebre por un cañón fluvial de paredes verticales de más de 200 metros de profundidad. Alberga un sistema de cuevas colgadas con formaciones de estalactitas activas, rodeado de quejigales y encinares rupícolas puros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90003','espacio','Ribera del río Barcés y valles del Embalse de Abegondo-Cecebre','Espacio de inundación fluvial interior asentado sobre materiales graníticos y esquistos del dominio de Órdenes. Alberga un denso bosque de galería atlántico compuesto por alisos (Alnus glutinosa), sauces y fresnos, envuelto en una constante humedad edáfica que favorece el crecimiento de helechos gigantes rupícolas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90184','espacio','Ribera del río Tambre y entorno de Tapia','Tramo fluvial de media montaña donde el río Tambre se encaja suavemente entre colinas graníticas y relieves de esquistos bien meteorizados. El paisaje destaca por sus masas boscosas de carballeiras (robledales atlánticos) que tapizan las laderas umbrías, combinadas con un sotobosque húmedo de musgos y comunidades vegetales hidrófilas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90185','espacio','Fragas del río Mandeo y garganta de Cambás','Profunda incisión fluvial de carácter torrencial labrada sobre granitos hercínicos de la Dorsal Gallega. Resguarda una densa selva atlántica de frondosas (fraga) excelentemente conservada con robles maduros, castaños y una rica variedad de flora criptogámica en los escarpes rocosos umbríos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90001','espacio','Costa acantilada de Punta Avante y ensenada de Redes','Costa no-playa caracterizada por escarpes de abrasión marina formados sobre pizarras y esquistos de la Serie de Órdenes que caen de forma abrupta hacia la ría. El borde superior de los cantiles está colonizado por brezales atlánticos litorales y comunidades halófilas expuestas al batido del oleaje.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90002','espacio','Costa rocosa de Sisalde y acantilados de Sorrizo','Tramo litoral granítico expuesto a la fuerte dinámica marina del océano Atlántico, configurando un relieve de ensenadas rocosas, plataformas de rasas y bloques fracturados. La vegetación litoral cuenta con herbazales halófilos y matorrales de tojo y brezo adaptados a la escasez hídrica edáfica y los vientos salinos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90186','espacio','Cascadas de las rieras del río Iso y valles del Ulla','Suaves ondulaciones de la penillanura gallega central donde la red hidrográfica secundaria ha excavado pequeños valles sobre esquistos del Paleozoico. Los arroyos presentan saltos de agua estacionales encajados entre masas forestales mixtas con robledales residuales de gran interés botánico.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90187','espacio','Valles del río Tambre y cuenca del río Barcala','Depresión erosiva interior flanqueada por lomas graníticas bajas de perfiles redondeados por la meteorización química. El cauce fluvial mantiene una franja continua de vegetación de ribera con alisedas y saucedas que estabilizan los sedimentos aluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01003','espacio','Canal del río Mendo, río Mandeo y sotos de la ribera','Confluencia fluvial enclavada en el fondo de la ría, donde los cursos de agua excavan terrazas aluviales sobre esquistos meteorizados. Los márgenes muestran una densa franja de bosque galería atlántico con alisos monumentales y sauces que se sumergen en las aguas salobres.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90188','espacio','Cabeceras del río Tambre y lomas de esquistos','Relieve ondulado de la meseta central gallega caracterizado por suelos delgados sobre pizarras y anfibolitas. Alberga pequeños retazos de carballeiras (robledales) y extensas zonas de matorral atlántico dominadas por el tojo y el brezo común.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01004','espacio','Estuario de la ría de Arousa y vertientes graníticas de la Sierra de Barbanza','Escarpados contrafuertes de montaña granítica que descienden de manera vertiginosa hacia la línea costera no-playa de la ría. Las laderas umbrías presentan profundas fracturas tectónicas por donde bajan torrentes de agua pura entre densas masas de robledal atlántico.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90189','espacio','Pico Sacro y gargantas del río Ulla','Singular e imponente filón de cuarzo blanco puro que emerge de forma vertical rompiendo la topografía circundante, constituyendo un hito geomorfológico único. Hacia el sur, el río Ulla se encaja con fuerza abriendo desfiladeros de paredes verticales de esquistos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90190','espacio','Valle de la Mahía y cañón del río Tambre (límite septentrional)','Depresión tectónica interior flanqueada por lomas graníticas bajas donde el río Tambre excava un lecho rocoso sinuoso. Conserva una rica cobertura forestal de carballeiras mezcladas con castaños y un dosel ripario hiperhúmedo.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90004','espacio','Estuario del río Anllóns y ensenada de Insua','Espectacular zona húmeda litoral no-playa conformada por la desembocadura del río Anllóns, con dunas trepadoras fósiles, juncales densos y bancos de arena sujetos al régimen de mareas. Un paisaje costero virgen de altísima singularidad botánica y geomorfológica.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90005','espacio','Parque Natural de las Fragas del Eume (vertiente sur) y desembocadura del Eume','Entrada meridional al desfiladero del río Eume, caracterizada por laderas escarpadas cubiertas por una densa y cerrada selva atlántica de frondosas. La humedad del Atlántico propicia un ecosistema excepcional de helechos relictos del Terciario y musgos epífitos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01005','espacio','Acantilados de Cabo Vilán y duna rampante de Monte Branco','Paisaje costero colosal y salvaje dominado por relieves graníticos fracturados y una espectacular duna de arena que trepa por la ladera rocosa. Los cantiles verticales sufren la máxima energía del oleaje, albergando una flora halófila endémica de primer orden.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90191','espacio','Humedal de Cecebre y curso del río Mero','Llanura de inundación fluvial baja caracterizada por depósitos limosos y un nivel freático superficial estable. Muestra un denso bosque de galería atlántico compuesto por alisos y fresnos que protegen un ecosistema acuático interior maduro.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22080','espacio','Parque Natural de las Fragas del Eume, cañón del Eume y barranco del Teixido','El corazón del cañón kárstico-granítico del río Eume, con pendientes verticales que superan los 200 metros de desnivel cubiertas por la fraga atlántica más pura de Europa [Capela, A]. Destaca por sus ríos interiores umbríos repletos de helechos arborescentes gigantes y maduras carballeiras relictas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01006','espacio','Espacio Natural de Baldaio (marismas y dunas fósiles) y cascada de Entrecruces','Complejo costero de alta energía marina con lagunas litorales y saladares de gran interés botánico halófilo. Hacia el interior, el relieve se vuelve accidentado con la presencia de una fractura granítica que genera un salto de agua torrencial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15901','espacio','Acantilados de Herbeira, Cabo Ortegal y Aguillóns','Los acantilados más altos de la Europa continental con caídas verticales que superan los 600 metros de altura sobre el océano. El entorno geológico presenta rocas   ultra-básicas como eclogitas de origen precámbrico y una vegetación litoral de brezales marítimos adaptada a vientos extremos. A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01007','espacio','Macizo granítico de O Pindo, cascada de Ézaro (desembocadura) y marismas de Caldebarcos','Impresionante relieve granítico costero caracterizado por caprichosas formas de meteorización (taffoni, bolos) conocidas como el Olimpo Celta. Incluye la desembocadura única en cascada del río Xallas directamente sobre la base marina de la ría en una cubeta de roca pulida.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15023','espacio','Costa acantilada de Caneliñas y ría de Corcubión','Tramo de costa no-playa con perfiles rocosos de granito hercínico muy expuestos a los temporales invernales. El borde superior de los escarpes destaca por un tapiz continuo de tojo gallego, brezo ceniciento y comunidades botánicas rupícolas halófilas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15024','espacio','Nacimiento del río Anllóns y lomas de Meirama','Cabecera fluvial interior sobre materiales de esquistos y granitos degradados que generan un relieve suavemente alomado. Cuenta con un denso sotobosque de   matorral atlántico húmedo y pasillos de vegetación hidrófila lineal a lo largo de los riachuelos. A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15025','espacio','Valle del río Cabo y fragas del río Mera','Pequeña cubeta erosiva intramontana encajada sobre relieves paleozoicos de la comarca de Ortegal. Las laderas de umbría resguardan frondosas carballeiras mezcladas con castaños y un dosel ripario con helechos gigantes.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15027','espacio','Cañón del río Mandeo y paraje de Chelo','Angosto desfiladero fluvial excavado sobre bancos graníticos donde el río fluye veloz formando rápidos y ollas de erosión. El microclima húmedo y protegido propicia una de las fragas fluviales más puras de la cuenca con alisos monumentales.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15028','espacio','Ensenada de Corcubión y puntas litorales graníticas','Costa rocosa de abrigo en la Galicia sudoccidental con pequeños perfiles escarpados modelados sobre rocas plutónicas. La vegetación se compone de matorral litoral adaptado a la influencia marina constante de las rías.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15029','espacio','Vegas del río Anllóns y humedales de Verdes','Espacio fluvial interior donde el río Anllóns se divide en pequeños brazos formando islas y canales de fondo pedregoso. Alberga un denso bosque de galería atlántico con alisos y sauces de notable desarrollo lineal y botánico.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15031','espacio','Ría de O Burgo (tramo alto) y sotos del río Mero','Llanura de inundación intermareal donde confluyen aguas fluviales y marinas depositando limos finos. Las orillas mantienen juncales marítimos y comunidades macrofíticas adaptadas a la fluctuación del nivel del agua por mareas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15032','espacio','Meseta de Curtis y cabecera del río Mandeo','Altiplano interior de la Dorsal Gallega con un relieve suave sobre materiales silíceos muy estables. Presenta formaciones de matorral atlántico húmedo dominadas por el brezo común, tojos y pequeñas turberas de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15033','espacio','Brañas de Laíño y riberas del río Ulla','Extensa llanura de inundación aluvial baja conformada por sedimentos limosos e hidrofluvisoles. La cubeta palustre destaca por sus comunidades de praderas húmedas permanentes, juncales densos y pasillos ripícolas de sauces que amortiguan las crecidas fluviales.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15034','espacio','Dehesa de Anllares, cañón del río Xallas y monte de O Ézaro (límite septentrional)','Paisaje granítico colosal esculpido por la erosión lineal del Xallas sobre el batolito hercínico. Sus profundas e inaccesibles gargantas resguardan masas de robledal atlántico virgen y una densa flora criptogámica protegida en los cantiles de roca desnuda.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15035','espacio','Costa rocosa de la ría de Ferrol y ensenada de Barallobre','Costa no-playa definida por perfiles de abrasión marina moderada sobre esquistos y pizarras de la Serie de Órdenes. El borde litoral superior acoge brezales húmedos atlánticos y pequeñas comunidades halófilas expuestas al influjo estuarino.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15036','espacio','Acantilados de Cabo Prior, costa de Doniños y estrecho de A Graña','Impresionante tramo costero de fuerte energía oceánica con farallones verticales de granito y gneis batidos por el mar. Los bordes de la meseta litoral están colonizados por brezales marinos, tojares xerófilos y comunidades rupícolas adaptadas a la extrema salinidad.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01011','espacio','Promontorio de Cabo Fisterra y acantilados de la ría de Corcubión','Colosal península de granito que se adentra de forma rectilínea en el océano Atlántico, configurando un hito geomorfológico y paisajístico único de la península ibérica. Sus cantiles verticales de roca desnuda albergan líquenes rupícolas y flora halófila adaptada al constante azote eólico.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15038','espacio','Riberas del río Tambre superior','Relieve ondulado de la penillanura gallega central donde el río Tambre discurre por canales pedregosos sobre esquistos paleozoicos. Las márgenes mantienen pequeños tramos de carballeiras y pasillos verdes de alisos y sauces de crecimiento espontáneo.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90192','espacio','Cabecera del río Mandeo y cuenca del río Zarzo','Zona de montaña media forestal integrada en la Dorsal Gallega con valles angostos y pendientes moderadas. El paraje destaca por sus masas mixtas de roble y castaño y un denso bosque galería con helechos gigantes bien conservados.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15041','espacio','Cuenca alta del río Anllóns y cañón de Gabenlle','Pequeña hendidura fluvial excavada sobre el complejo esquisto-quarcítico regional, generando un lecho de   aguas rápidas con pequeños saltos rocosos. La umbría de la garganta cobija comunidades botánicas higrófilas y relictos de bosque atlántico. A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90006','espacio','Acantilados de Punta Laxe y ensenada de Soesto','Costa rocosa de granito gris muy fracturado por diaclasas tectónicas que sufre procesos de erosión marina intensa. La vegetación litoral está compuesta por matorrales de tojo y brezo ceniciento, combinada con herbazales halófilos especializados.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15042','espacio','Minas de San Finx, valles del río San Justo y monte de San Lois','Relieve abrupto de montaña media granítica caracterizado por una densa red de escorrentía de alta energía. Cuenta con frondosas carballeiras y masas arbóreas nativas que colonizan los perfiles escarpados de los barrancos fluviales.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15043','espacio','Acantilados de Cabo San Adrián e Islas Sisargas','Espectacular frente costero con farallones graníticos verticales expuestos a la máxima energía del océano. El archipiélago rocoso y los cantiles continentales constituyen un ecosistema botánico costero puro, dominado por brezales marinos y comunidades rupícolas halófilas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15044','espacio','Estuario del río Sor y acantilados de Estaca de Bares','El punto más septentrional de la península ibérica, configurado por una imponente cresta granítica y esquistosa moldeada por el oleaje. El tramo fluvial del Sor   resguarda un microclima atlántico con una de las fragas y alisedas galería más puras de la provincia. A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15045','espacio','Fervenzas de Chacín, cuenca alta del río Xallas y monte Aro','Relieve alomado interior donde la red hidrográfica secundaria salva los desniveles del granito mediante saltos de agua (fervenzas) encajados en la roca madre. Alberga formaciones arbustivas atlánticas espesas y carballeiras en las zonas umbrías.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90842','espacio','Riberas del río Furelos y sotos de la meseta','Altiplano interior centro-gallego constituido por un sustrato de rocas ultrabásicas y anfíboles. Los márgenes fluviales presentan una alameda y sauceda continua mezclada con pequeños robledales adaptados a los suelos particulares de la zona.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15047','espacio','Nacimiento del río Tambre y valles de esquistos','Suaves ondulaciones de la meseta central con suelos delgados sobre pizarras que marcan la divisoria de aguas de la cuenca. La vegetación se compone de matorral atlántico húmedo (tojo y brezo) y pequeños pasillos de sauces arbustivos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15048','espacio','Marismas del río Baxoi y acantilados de Perbes','Zona húmeda mareal y costa de abrasión baja constituida por sedimentos limosos y afloramientos esquistosos. Aloja comunidades botánicas halófilas y juncales marítimos estables en la desembocadura fluvial.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15049','espacio','Valles del río Grande de Xuvia y afloramientos de serpentinitas','Geomorfología singular marcada por la presencia de rocas ígneas ultra-básicas de color verdoso en una topografía alomada. La vegetación cuenta con matorrales especializados y pequeñas carballeiras de transición.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15050','espacio','Parque Natural de las Fragas del Eume (vertiente meridional) y cañón de la Central','El sector más salvaje y denso del bosque atlántico del Eume, donde las laderas de umbría caen verticales hacia el lecho fluvial. Es un santuario botánico hiperhúmedo con un dosel continuo de carballos, castaños, arces y helechos tropicales paleotropicales relictos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15051','espacio','Costa acantilada de Punta Segaño y estrecho de la ría de Ferrol','Entrada escarpada de la ría caracterizada por perfiles rocosos de granito hercínico muy expuestos a las corrientes marinas. Presenta formaciones de matorral litoral adaptado a la influencia marítima constante.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15053','espacio','Monte Louro, lagunas de As Xarfas y acantilados costeros','Impresionante mole granítica cónica de dos cumbres que emerge de manera prominente junto al mar, cerrando una laguna costera protegida por dunas. Los perfiles rocosos litorales exhiben un modelado alveolar y formas de meteorización únicas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01013','espacio','Acantilados del Santuario de la Barca, Punta de la Buitra y costa del río Negro','Costa salvaje e imponente de la Costa da Morte, caracterizada por lanchares graníticos horizontales que reciben el máximo impacto de las olas del Atlántico. Su orla botánica cuenta con comunidades rupícolas halófilas especializadas de gran valor contemplativo.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15054','espacio','Riberas del río Xuvia y acantilados de O Casal','Tramo bajo fluvial y costa abierta con perfiles rocosos de abrasión marina moderada. Conserva bandas de bosque galería atlántico con alisos y fresnos, combinadas con matorrales costeros de tojo y brezo.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15055','espacio','Cascada del río Belelle y riberas del Xuvia','Espectacular salto de agua vertical esculpido sobre el batolito granítico local, que fluye con gran caudal y energía fluvial constante. El entorno umbrío genera un microclima de gran riqueza matorral, helechales y musgos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15056','espacio','Garganta del río Tambre en Cobas','Estrechamiento fluvial encajonado de forma moderada sobre materiales de granito y esquistos hercínicos. Los márgenes conservan carballeiras y bosques galería que colonizan los taludes rocosos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01014','espacio','Estuario del río Tambre y ensenada de Noia','Amplia cubeta de transición mareal donde los aportes fluviales del Tambre depositan limos y arenas   gruesas. Sostiene un denso pasillo vegetal con marismas halófilas, carrizales palustres y juncales de buena conservación. A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15058','espacio','Monumento Natural de la Costa de Dexo-Serantes','Tramo litoral protegido de excepcional belleza geológica, caracterizado por acantilados escarpados de esquistos y la presencia de "furnas" (cuevas marinas) y arcos rocosos. El borde superior está tapizado por brezales y tojares litorales puros.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90193','espacio','Valles del río Tambre superior y lomas forestales','Centro geográfico de la Serie de Órdenes con una topografía de suaves lomas pizarrosas degradadas. Cuenta con pasillos de vegetación riparia con alisos y pequeñas masas de robledal atlántico aclarado.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15060','espacio','Riberas del río Tambre y curso del río Carboeiro.     Description: Llanura de inundación fluvial de relieve plano constituida por sedimentos cuaternarios estables. El curso del agua genera un microamb','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15061','espacio','Ría de Ortigueira y Ladrido, Acantilados de Loiba y Cabo Ortegal (límite oriental)','Uno de los complejos estuarinos y paisajísticos más colosales del norte de España, célebre por albergar marismas limosas y los majestuosos acantilados fracturados de Loiba. Es un enclave botánico excepcional para comunidades halófilas y brezales marítimos de altitud.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15062','espacio','Sierra de Outes y desembocadura del río Tines','Fuertes pendientes graníticas de la cordillera Litoral que mueren en el estuario de la ría de Muros y Noia. Aloja bosques maduros de roble, castañares en las umbrías y juncales mareales en la transición acuática.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15902','espacio','Cabecera del río Mendo y fragas de Cesuras','Relieve de media montaña media forestal con valles angostos excavados sobre granitos y esquistos del Paleozoico. El paisaje visual está definido por densas carballeiras y brezales húmedos que cubren las laderas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15064','espacio','Fragas del río Mandeo (vertiente norte) y curso del río Lambre','Desfiladero de vertientes abruptas cubiertas por una densa y cerrada selva atlántica mixta de robles y avellanos. La constante humedad ambiental favorece el crecimiento de helechos gigantes y una densa flora criptogámica.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15065','espacio','Confluencia del río Sar con el río Ulla e islas fluviales de Lestrobe','Llanura aluvial madura caracterizada por depósitos detríticos finos y terrazas fluviales estables. Las orillas están colonizadas por saucedas y alamedas de gran desarrollo lineal sujetas a la dinámica mareal del tramo final del Ulla.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15066','espacio','Valles del río Tambre medio y ribera del río Mera','Relieve ondulado sobre materiales de granito y esquistos con una topografía de vertientes suaves. Presenta rodales de robledal atlántico y matorral de tojo y brezo adaptados a la humedad ambiental.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01002','espacio','Piscinas naturales del río Pedras y vertientes de la Sierra de Barbanza','Espectacular desfiladero granítico donde el río desciende salvando el desnivel en una sucesión de cascadas y pozas circulares excavadas en roca pulida. El entorno alberga melojares maduros, robledales atlánticos y matorrales de piornal en las cumbres.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90194','espacio','Estuario del río Anllóns, Monte Branco y acantilados de Corme','Impresionante conjunto morfológico que exhibe la desembocadura fluvial protegida por la gran duna rampante de Monte Branco y farallones costeros. El entorno botánico acoge comunidades halófilas extremas y brezales marítimos adaptados al viento.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','espacio','Parque Natural de las Fragas del Eume (Desembocadura) y acantilados de Centroña','El punto de apertura del desfiladero del Eume a la ría, que exhibe una colosal y cerrada selva atlántica litoral única. El fondo umbrío e inaccesible cobija un microclima hiperhúmedo donde crecen robles maduros, helechos relictos del Terciario y musgos epífitos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15070','espacio','Cabecera del río Eume y Sierra de la Faladoira','Altiplano interior y vertientes montañosas compuestas por granitos y pizarras que dan origen a valles encajados menores. Las zonas de umbría están cubiertas por manchas forestales de carballeiras y matorrales de brezo.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90007','espacio','Acantilados de Castro de Baroña, Monte Enxa y ensenada de Fonforrón','Impresionante tramo costero de granito hercínico con perfiles verticales angulosos y plataformas de rasa marina erosionadas por el oleaje. El relieve asciende rápido hacia la cumbre de O Enxa, cubierto por matorral atlántico xerófilo de tojo.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01018','espacio','Desembocadura del río Ulla y puntas de Taragoña','Espacio de transición sedimentaria fluvialmarítima en el fondo de la ría de Arousa con llanuras de fango arcilloso y marismas limosas. Cuenta con comunidades halófilas perennes y juncales que delimitan los brazos de agua.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15073','espacio','Parque Natural de Corrubedo (Duna móvil y lagunas de Vixán y Carregal)','Espectacular y colosal duna móvil de más de 1 kilómetro de largo rodeada de un complejo sistema de lagunas salobres y litorales no-playa. La vegetación de dunas costeras constituye un ecosistema botánico de máxima singularidad contemplativa.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15074','espacio','Valles del río Sar y fragas de Antequeira','Relieve colinado suave de la cuenca baja del Ulla asentado sobre materiales graníticos muy meteorizados.   Conserva manchas relictas de robledales gallegos y un dosel ripario denso con sauces y alisos. A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15075','espacio','Costa rocosa de la ría de Betanzos y Punta Fontán','Costa de abrigo con perfiles escarpados moderados modelados sobre esquistos y pizarras de la Serie de Órdenes. La vegetación se compone de matorral litoral adaptado a la influencia marina constante y brezales húmedos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15076','espacio','Riberas del río Grande de Xuvia y fragas del Aceiteiro','Relieve ondulado labrado sobre el complejo esquisto-quarcítico que define el paisaje interior de la comarca de Ferrol. Cuenta con masas boscosas de carballeiras de montaña y comunidades vegetales hidrófilas en el eje fluvial.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15077','espacio','Altiplano de Jallas y cabecera del río Xallas','Penillanura interior granítica caracterizada por un relieve horizontal a suavemente ondulado con suelos silíceos ligeros. Presenta formaciones de matorral atlántico degradado dominadas por el tojo y pastizales húmedos estacionales.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15078','espacio','Riberas del río Sar, río Sarela y monte Pedroso','Entorno colinado granítico donde los cursos fluviales menores excavan valles estrechos umbríos con pequeñas cascadas estacionales. El monte Pedroso presenta formaciones boscosas perennifolias mixtas y matorrales que suavizan el relieve.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15079','espacio','Riberas del río Ulla y embalse de Portodemouros','Tramo fluvial interior de media montaña donde el río se encaja suavemente entre colinas de esquistos y anfibolitas. El paisaje visual ofrece un mosaico de carballeiras residuales y vegetación riparia en el eje del embalse.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15080','espacio','Laguna de Sobrado y nacimiento del río Mandeo','Singular humedal interior naturalizado de origen medieval asentado sobre arcillas e hidrofluvisoles de la meseta interior. La cubeta acoge comunidades de macrófitos, densos carrizales y una orla forestal con alisos y sauces bien conservados.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15081','espacio','Valles del río Mera superior y lomas pizarrosas','Suaves ondulaciones de la media montaña pizarrosa noroccidental con procesos de escorrentía superficial continuos. Alberga pequeños rodales de robledal atlántico y extensos pastizales con comunidades higrófilas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15082','espacio','Estrecho de la ría de Ulla y fragas de Calo','Incisión fluvial de pendientes moderadas abierta sobre conglomerados y granitos hercínicos en la transición hacia Santiago. El curso del agua genera un microambiente de gran exuberancia botánica rico en robles y alisedas galería.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15083','espacio','Fervenza de Brañas, Sierra de Careón y cabecera del río Furelos','Espectacular salto de agua vertical del río Furelos sobre afloramientos de rocas ultrabásicas y esquistos   metamórficos en un relieve abrupto. Alberga una rica y exclusiva flora endémica de matorral metalícola y densas carballeiras de montaña. A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90843','espacio','Cabecera del río Lengualles y lomas de la penillanura','Topografía de meseta interior de relieves suaves constituida por materiales graníticos meteorizados de la Serie de Órdenes. Presenta pequeñas formaciones herbáceas estacionales y matorrales atlánticos hidrófilos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15085','espacio','Cañón del río Ulla en Basebe y cascada de Salto do Coro','Estrechamiento fluvial encajonado donde el río Ulla secciona de forma transversal los relieves esquistosos, creando pequeños saltos y torrentes secundarios. Las laderas están cubiertas por densas masas boscosas mixtas y bosques galería de alisos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15086','espacio','Valles del río Tambre medio y lomas graníticas','Relieve colinado de vertientes suaves labrado sobre el batolito central de la cuenca hidrográfica. Cuenta con pequeñas carballeiras y comunidades vegetales ripícolas que marcan las zonas de escorrentía permanente.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90195','espacio','Valle aluvial del río Dubra y fragas asociadas','Fondo de valle de relieve llano constituido por limos cuaternarios en un entorno general de penillanura erosionada. El río aporta una densa franja verde de vegetación riparia con alisos y sauces que protegen el cauce.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15087','espacio','Laguna de A Frouxeira, acantilados de Punta Frouxeira y acantilados de Meirás','Espectacular y gran laguna costera de aguas salobres separada del océano por una imponente barrera dunar, flanqueada por farallones graníticos verticales. Alberga comunidades halófilas de gran interés botánico y extensas orlas de carrizales perimetrales.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15089','espacio','Gargantas del río Ulla en San Xoán de Cova y penedos de Pascuais','Impresionante tajo fluvial encajonado de forma vertical sobre rocas metamórficas del complejo de Santiago, con grandes bloques redondeados ("penedos") en el cauce. Las umbrías resguardan un dosel de bosque de galería atlántico muy rico en helechos rupícolas.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90844','espacio','Valles del río Lambre y fragas de Vilamourelle','Relieve accidentado premontano con valles angostos y vertientes compuestas por esquistos paleozoicos bien cubiertos de vegetación forestal. Conserva manchas relictas de carballeiras y matorral denso de tojo y brezo arborescente.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15090','espacio','Riberas del río Tambre superior y fragas del río de las Lajas','Suaves ondulaciones de la Dorsal Gallega con presencia de vegetación espontánea de ribera y pequeños robledales. Su geomorfología responde a una llanura de montaña media estabilizada sobre esquistos.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15092','espacio','Acantilados de Sabadelle, valles del río Grande y penedos de Pasarela','Impresionante paisaje interior y costero donde destacan colosales bloques graníticos ("penedos") esculpidos por la meteorización química y eólica. La vegetación forestal está dominada por carballeiras atlánticas y matorrales densos de ladera.   A Coruña).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15093','espacio','Pico de Páteo y cabecera del río Grande','Relieve de media montaña con vertientes graníticas suaves que marcan la divisoria de aguas de la comarca de Soneira. Alberga masas boscosas mixtas de roble gallego y castaño en las umbrías, complementadas por brezales de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90304','espacio','Relieve de Los Castillejos y nacimiento del río Moscas','Entorno caracterizado por crestas calcáreas erosionadas que forman pequeños escarpes de roca caliza y   cárcavas arcillosas. Destaca por la contemplación de sus formaciones de piedemonte y la vegetación de ribera mediterránea en sus cursos estacionales primarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90322','espacio','Riberas del río Bedija y dehesas arcillosas','Relieve plano ondulado propio de la cuenca sedimentaria de la Mancha alta, constituido por depósitos arcillo-arenosos miocénicos. Cuenta con formaciones forestales aclaradas de encina y comunidades vegetales hidrófilas en los márgenes de los arroyos.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14001','espacio','Hoces del río Júcar y cañón de Alarcón','Espectacular y profundo meandro encajado donde el río Júcar corta de manera transversal potentes bancos de calizas del Cretácico superior [Alarcón]. Sus   escarpadas paredes verticales albergan una riquísima flora rupícola de umbría y un denso bosque de ribera con chopos y sauces. Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90305','espacio','Valle fluvial del río Júcar y llanuras arcillosas','Espacio de transición geológica donde el cauce del río se ensancha creando llanuras de sedimentación aluviales. Ofrece una estampa contemplativa de contrastes cromáticos entre el verde de los chopos de ribera y los tonos rojizos del terreno circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90306','espacio','Cañón del río Albalate y hoces del río Trabaque','Angosto desfiladero fluvial excavado sobre calizas jurásicas y dolomías, que expone espectaculares perfiles escarpados y fenómenos de disolución kárstica. Las laderas umbrías albergan una densa masa forestal mixta con quejigos, encinas y sauces en el fondo del valle.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90307','espacio','Riberas del río Guadiela y lomas de la Alcarria','Paisaje de colinas suaves modelado sobre arcillas, margas y costras calcáreas de la cuenca sedimentaria del Guadiela. El cauce fluvial mantiene una franja continua de vegetación de ribera con alisedas y saucedas que estabilizan los sedimentos aluviales.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90827','espacio','Hoces del río Cabriel y muelas calcáreas','Relieve de alta montaña caliza caracterizado por profundos desfiladeros fluviales y abundantes surgencias de agua subterránea. Las paredes rocosas verticales albergan   comunidades botánicas raras adaptadas a la escasez de suelo y a las umbrías extremas. Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90308','espacio','Hoz de Alcantud y Estrecho del Guadiela','Desfiladero rocoso de paredes totalmente verticales que aprisionan el curso de agua cristalina entre paredones de piedra caliza. Presenta una geomorfología kárstica espectacular, con formaciones de tobas y una densa vegetación de umbría propicia para la observación botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90309','espacio','Lomas de la llanura manchega y crestas arcillosas','Paisaje geomorfológico horizontal interrumpido por sutiles elevaciones margosas y procesos de erosión laminar. Su interés radica en la contemplación de la inmensidad cromática estacional y las formaciones de cárcavas en las laderas expuestas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90310','espacio','Relieves de la Alcarria conquense y cárcavas de yeso','Paisaje semiárido moldeado sobre depósitos arcillosos y yesíferos que generan un relieve quebrado y lomas redondeadas. El interés estético se centra en los fuertes contrastes de luz sobre la roca erosionada y la vegetación xerófila adaptada al sustrato.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90311','espacio','Cerros testigo del llano y charcas estacionales','Elevaciones del terreno de cumbre plana compuestas por calizas lacustres que resistieron la erosión sobre los materiales blandos de la cuenca. Permite contemplar la llanura infinita de la Mancha Alta desde una perspectiva geomorfológica singular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90312','espacio','Serranía Alta de Cuenca y picos de la Sierra de Algarra','Espectacular entorno de alta montaña paleozoica con modelado glaciar y periglaciar en las cumbres calcáreas y esquistosas. Cuenta con imponentes bosques mixtos de hayas, acebedas maduras y robledales que cubren valles de aguas cristalinas.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90828','espacio','Sierra de Aliaguilla y formaciones de areniscas','Relieve montañoso caracterizado por la presencia de rocas detríticas ecorrodadas de color rojizo (rodeno) que rompen la monotonía caliza de la provincia. Destaca por sus formaciones de bolos graníticos y los densos bosques de pino resinero que tapizan las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90829','espacio','Manantiales de la Almarcha y cuenca del río Córcoles','Relieve suavemente ondulado sobre arcillas miocénicas y costras calizas lacustres que propician pequeñas surgencias estacionales de agua. Muestra comunidades de pastizales vivaces calcícolas y matorrales bajos mediterráneos adaptados a la escasez de suelo.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90743','espacio','Llanura endorreica y costras calizas de la Mancha','Topografía plana sin red hidrográfica superficial definida debido a la alta permeabilidad de las calizas lacustres terciarias. Alberga comunidades vegetales efímeras de carácter estepario adaptadas a suelos esqueléticos de extrema continentalidad.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90313','espacio','Pinares de la Serranía Media y lomas dolomíticas','Extensa masa forestal continua asentada sobre un relieve ondulado de arenas y costras calizas. El paisaje destaca por la pureza atmosférica y visual del denso dosel arbóreo de Pinus pinaster que cubre la totalidad de la línea del horizonte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90314','espacio','Laguna de Almonacid y lomas calizas','Relieve colinado suave constituido por materiales detríticos y calizas lacustres eocénicas que delimitan la cuenca. La vegetación del entorno está dominada por tomillares, aliagares y matorral bajo mediterráneo adaptado a la aridez estival.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90315','espacio','Valles del río Altarejos y monte de la Virgen','Cubierta forestal de gran interés botánico constituida por un quejigal (Quercus faginea) maduro sobre terrenos llanos arcillo-arenosos. Las zonas bajas presentan pequeños humedales estacionales asociados a la dinámica del riachuelo local.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90316','espacio','Cañón del río Vindel y hoces del río Arandilla','Pequeño desfiladero excavado en calizas tabulares del Terciario, con paredes escarpadas y abrigos naturales de disolución kárstica. El entorno vegetal destaca por la transición entre el quejigal húmedo de fondo de valle y el encinar seco del páramo.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16905','espacio','Complejo Lagunar de Arcas','Espacio protegido compuesto por lagunas de origen kárstico originadas por el colapso de acuíferos subterráneos (torcas). Sus aguas permanentes albergan comunidades vegetales hidrófilas singulares y praderas subacuáticas de carófitos observables por su transparencia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90830','espacio','Serranía de Cuenca, cañón del río Trabaque y Peña del Reloj','Impresionante relieve montañoso calizo con paredes verticales de gran valor geomorfológico y paisajístico que se elevan sobre bosques submediterráneos. Sus escarpes albergan comunidades botánicas rupícolas singulares y fuentes naturales de montaña calcárea.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90317','espacio','Formaciones calcáreas de las Arguisuelas y pinares de rodeno','Paisaje de badlands y espectaculares formaciones de erosión hídrica sobre arcillas y conglomerados de color rojizo encajados en la Serranía Baja. Las crestas afiladas y paredes verticales ofrecen una perspectiva morfológica desértica e impactante.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90318','espacio','Vaguada del arroyo de Arrancacepas','Depresión erosiva menor labrada sobre arcillas miocénicas de la cuenca central alcarreña. El fondo del vallejo acoge comunidades vegetales hidrófilas estacionales y sauces de porte arbustivo alineados con el nivel freático.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90319','espacio','Cerros de la Atalaya y llanura del Cañavate','Suaves ondulaciones de la campiña manchega meridional constituida por depósitos detríticos y calizas lacustres del Terciario superior. Presenta una vegetación xerófila dominada por tomillos, aliagas y pequeñas encinas de porte arbustivo.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90320','espacio','Vega del río Calvache y escarpes de arcilla','Relieve de campiña ondulada modelado sobre margas y arcillas del neógeno, caracterizado por laderas de suave pendiente. En los márgenes del cauce intermitente se desarrollan pequeñas choperas autóctonas y saucedas arbustivas.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16029','espacio','Paraje de la Hoya y masas forestales de encinar','Gran depresión geológica rodeada de suaves elevaciones cubiertas por una masa continua de encinar centenario. Su interés radica en el modelado kárstico inicial del terreno y en el tapiz vegetal mediterráneo perfectamente conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16030','espacio','Cingles de San Pedro y hoces del río Mayor','Estrechamiento fluvial colosal donde el río corta de forma transversal los contrafuertes de la Serranía Media, exponiendo estratos geológicos verticales y fallas tectónicas de gran interés didáctico. El relieve es abrupto, combinando roca desnuda con comunidades vegetales de umbría.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16031','espacio','Laguna de Beamud y hoces del río de la Ciudad','Espectacular entorno de alta montaña calcárea del Maestrazgo-Cuenca, dominado por una geomorfología estructural de muelas y lapiaces hiperdesarrollados. Alberga una cubeta lagunares kárstica con comunidades de macrófitos y carrizales densos.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16032','espacio','Manantiales salinos de Belinchón y cerros de yeso','Relieve ondulado sobre yesos, margas y arcillas triásicas policromas del complejo alcarreño. La presencia de manantiales salinos genera un entorno edáfico particular con comunidades herbáceas halófilas relictas de gran interés botánico.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16033','espacio','Cerros del Castillo y muelas calizas de Belmonte','Superficie estructural plana típica de la submeseta sur asentada sobre calizas miocénicas con procesos de deflación eólica. Alberga comunidades de tomillar-alicatado y pastizales secos continentales resistentes a la oscilación térmica estacional.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16034','espacio','Embalse de Alarcón y gargantas del río Júcar','Cañón fluvial donde las aguas del Júcar penetran en formaciones calizas estrechas antes de   remansarse en el embalse. Ofrece una panorámica de amplias láminas de agua encajonadas entre laderas de matorral mediterráneo y pinos de repoblación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16035','espacio','Hoz de Beteta, Sumidero de Mata Asnos y Fuente de los Tilos','Uno de los cañones kársticos más colosales y espectaculares de España, con paredes calizas verticales que superan los 250 metros de profundidad. El fondo umbrío e inaccesible cobija un microclima hiperhúmedo donde crecen tilos (Tilia platyphyllos), tejos milenarios, acebos y densos helechales.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16036','espacio','El Cabriel, las Torcas de Boniches y el Peñón del Cuervo','Impresionante relieve de areniscas rodenas rojas y calizas mesozoicas caracterizado por profundas gargantas, callejones rocosos y torcas de colapso de dimensiones colosales. Las umbrías profundas albergan bosques mixtos de pino resinero, quejigales húmedos y densos helechales.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16038','espacio','Arroyo de Buciegas y cerros de la Alcarria','Suaves ondulaciones constituidas por sedimentos detríticos miocénicos con escasa diferenciación topográfica. Presenta pequeñas formaciones herbáceas estacionales adaptadas a suelos francos mediterráneos.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16040','espacio','Tierra Muerta, Torcas de Buenache y el Majal','Espectacular altiplano kárstico que constituye el mayor conjunto de torcas (dolinas de colapso vertical) de la península ibérica. El paisaje es una paramera caliza desolada tapizada de sabina albar y pinos negrales adaptados a suelos crioturbados extremos.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16039','espacio','Riberas del río Júcar y cola del embalse de Alarcón','Amplia llanura aluvial e intra-montana rota por la espectacular dinámica sinuosa del río Júcar sobre calizas del Cretácico. Sus riberas muestran formaciones maduras de alisedas y quejigales hidrófilos de notable interés botánico.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16041','espacio','Cañón del río Guadiela y hoces de Buendía','Colosal desfiladero fluvial donde el río Guadiela corta de forma transversal las duras sierras calizas de la Alcarria meridional, generando farallones de roca desnuda verticales de gran impacto visual. El ecosistema ripícola es excepcional, albergando densos bosques de alisedas en las repisas rocosas.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16042','espacio','Pinar de Campillo y lomas de Altobuey','Paisaje forestal sobre dunas fósiles y arenas continentales donde prospera una masa pura de pino resinero (Pinus pinaster). El sustrato poroso favorece un sotobosque especializado de brezales secos y tomillares.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16043','espacio','Torcas de Paravientos y Sierra de las Cuerdas','Paisaje geomorfológico abrupto en el corazón de la Serranía Baja, caracterizado por profundas dolinas de colapso sobre calizas cretácicas. El dosel vegetal está configurado por densas masas puras de pino negral y pino albar bien adaptadas al clima continentalizado de altitud.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16044','espacio','Valle del río Tejadillos y muelas calcáreas','Relieve de alta montaña caliza que asciende de forma abrupta con canales de desprendimiento y taludes de ladera bien definidos. La vegetación destaca por la presencia de bosques mixtos de pino negral, quejigos relictos y una rica flora montana subatlántica.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16901','espacio','Valles del río Valdejudíos y lomas arcillosas','Relieve de campiña suave modelado sobre sedimentos finos miocénicos en el sector occidental de la   provincia. La vegetación natural es dispersa, destacando matorrales espinosos y pastizales continentales estacionales. Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16046','espacio','Monumento Natural de las Lagunas de Cañada del Hoyo y las Torcas','Impresionante conjunto geológico excepcional consistente en siete lagunas circulares perfectas formadas por colapso kárstico (dolinas) de gran profundidad, célebres por cambiar el color de sus aguas estacionalmente debido a microorganismos carbonatados. El entorno presenta un dosel de sabina albar y pinos negrales maduros.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16047','espacio','Arroyo de la Cañada y costras calizas','Relieve horizontal absoluto correspondiente a la llanura manchega sobre depósitos de limos y arenas cuaternarias. Muestra pequeñas formaciones de matorral bajo mediterráneo y caméfitos basófilos adaptados a la escasez de suelo.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16045','espacio','Cañón del arroyo de Canalejas','Paisaje fluvial encajonado de forma suave entre cerros de margas y arcillas de la cuenca alcarreña. El cauce conserva una banda de vegetación hidrófila con juncales y carrizales bien estructurados.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16048','espacio','Estrecho de Cañamares y hoces del río Escabas','Estrechamiento fluvial colosal donde el río Escabas corta los relieves calcáreos de la Serranía, generando escarpes verticales de gran belleza geológica. Las paredes rocosas dan cobijo a una rica vegetación rupícola y encinares de montaña en las repisas.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16049','espacio','Cerros del Cañavate y lomas de arcilla','Paisaje de erosión diferencial dominado por cerros aislados de cima plana protegidos por estratos de calizas miocénicas sobre vertientes de margas. Cuenta con comunidades vegetales esteparias y pastizales secos.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16050','espacio','Riberas del río Merdancho y lomas de la Alcarria','Relieve colinado suave sobre arcillas y calizas del Mioceno, modelado por la escorrentía superficial de carácter torrencial. Cuenta con matorrales de romero y tomillo y pequeños rodales de pino carrasco en las vertientes de umbría.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16051','espacio','Riberas del Embalse de Buendía y cerros de Ercávica','Espacio lacustre delimitado por cerros de margas y calizas eocénicas donde el agua inunda los antiguos escarpes fluviales del río Guadiela. Conserva una de las masas de tarajes (Tamarix) y carrizales palustres más densas de la cuenca baja.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16053','espacio','Hoz de la Solanilla, Estrecho de Cañizares y río Guadiela','Majestuoso cañón fluvial encajado de manera salvaje entre altas paredes de caliza armoricana de perfil vertical. Las repisas rocosas de la umbría resguardan comunidades de enebros de gran porte, líquenes rupícolas y monte mediterráneo virgen de gran densidad.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16055','espacio','Río Guadazaón, Cabrejas y escarpes calcáreos','Incisión fluvial de pendientes moderadas abierta por la acción erosiva lineal sobre materiales pizarrosos y calizas mesozoicas fuertemente fracturadas. Sus laderas umbrías albergan manchas densas de monte mediterráneo rico en quejigos y encinas.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16056','espacio','Cañón del río Cabriel y hoces del río Guadazaón','Impresionante tajo fluvial encajonado de forma vertical sobre rocas metamórficas y calizas eocénicas, con grandes bloques redondeados en el cauce. Las umbrías resguardan un dosel de bosque de galería muy rico en helechos rupícolas y pinos negrales.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16057','espacio','Nacimiento del río de la Hoz y muelas calcáreas de Carrascosa','Gran surgencia kárstica perenne donde el agua brota directamente de las entrañas de la roca caliza de la Serranía Alta. El paraje fluvial muestra un lecho de aguas cristalinas rodeado de fresnedas y olmedas naturales de notable valor botánico.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16058','espacio','Vaguada del río Záncara y lomas de arcilla','Relieve de campiña suavemente ondulada modelado sobre margas y arcillas terciarias del neógeno. En los márgenes del cauce intermitente se desarrollan pequeñas choperas autóctonas y saucedas arbustivas.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16060','espacio','Paraje de los Cuchillos y riberas del río Júcar','Impresionantes crestones de caliza masiva que limitan geográficamente la fosa de la cuenca sedimentaria, modelados por erosión diferencial en crestas afiladas como   cuchillos. Las laderas presentan una interesante mezcla botánica de encinas y bojes. Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16061','espacio','Llanura aluvial de la Mancha baja','Relieve horizontal absoluto constituido por costras calcáreas cuaternarias y depósitos limosos finos. Conserva comunidades herbáceas efímeras adaptadas a la extrema continentalidad térmica y a sutiles depresiones con humedad edáfica temporal.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16062','espacio','Sierra de las Cuerdas y barrancos del río Grande','Zona de media montaña caliza caracterizada por escarpes asimétricos y lapiaces generados por procesos de disolución química. El interés botánico radica en sus formaciones abiertas de sabina albar y encinar montano que colonizan el sustrato rocoso desnudo.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16063','espacio','Costras calcáreas y llanura manchega','Topografía plana sin red hidrográfica superficial definida debido a la alta permeabilidad de las calizas lacustres terciarias. Alberga comunidades vegetales efímeras de carácter estepario adaptadas a suelos esqueléticos.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16064','espacio','Lomas de Haro y llanura sedimentaria','Relieve horizontal propio de la cuenca sedimentaria de la Mancha alta, constituido por depósitos de arenas y limos cuaternarios. Conserva manchas relictas de vegetación mediterránea esclerófila e hidrofitos en las orillas inundables de los arroyos estacionales.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16065','espacio','Pinar de los Pinos y costras calcáreas','Superficie de erosión horizontal interrumpida por pequeñas depresiones endorreicas sobre materiales detríticos finos. Presenta manchas relictas de pino piñonero y encina aclarada adaptadas a la continentalidad térmica.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16066','espacio','Llanura sedimentaria del río Júcar (tramo bajo)','Terreno llano de aluvión con sedimentos arenosos y limosos depositados por la dinámica fluvial de la cuenca baja del Júcar. Conserva comunidades macrofíticas y saucedas arbustivas adaptadas al encharcamiento temporal.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16067','espacio','Lomas del río Guadiela y cerros de la Alcarria','Relieve colinado de vertientes suaves labrado sobre materiales detríticos eocénicos. Cuenta con pequeñas formaciones arbustivas mediterráneas y comunidades de pastizales vivaces adaptadas a la escasez de suelo y alta insolación.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16068','espacio','Valles del arroyo de la Vega','Suaves ondulaciones de la meseta manchegoserrana constituidas por materiales detríticos eocénicos de la cuenca central. Muestra una vegetación xerófila dominada por tomillos, aliagas y matorral bajo mediterráneo.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16070','espacio','Hoces del río Guadiela y peñas del Castillejo','Angosto desfiladero fluvial abierto por la acción erosiva lineal sobre materiales pizarrosos y cuarcitas paleozoicas fuertemente fracturadas. Sus laderas umbrías   albergan manchas densas de monte mediterráneo rico en quejigos y encinas. Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16071','espacio','Lomas de Albaráñez y cerros de la Alcarria','Paisaje de erosión diferencial dominado por cerros aislados de cima plana protegidos por estratos de calizas miocénicas sobre vertientes de margas. Cuenta con comunidades vegetales esteparias y pastizales secos.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16073','espacio','Lomas del río Záncara y cerros del Llano','Superficie horizontal sedimentaria interrumpida por la modesta incisión de un arroyo estacional. Cuenta con retazos de matorral mediterráneo esclerófilo en los taludes de mayor pendiente.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90321','espacio','Valle del río Jábaga y cerros margosos','Entorno flanqueado por colinas arcillosas y yesíferas sujetas a una intensa erosión que genera un relieve abarrancado. La contemplación destaca por los pliegues del terreno y las pequeñas alamedas que acompañan el cauce del arroyo principal.   Si estás de acuerdo con este ritmo de avance.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16081','espacio','Muelas de Chumillas y pinares de la Serranía Media','Elevada plataforma estructural tabular de perfiles angulosos y laderas escarpadas de calizas del Terciario superior. El entorno forestal destaca por una masa pura de pino resinero (Pinus pinaster).   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16074','espacio','Hoces del río de la Cierva y Tierra Muerta (límite sur)','Relieve abrupto calcáreo con un modelado de muelas y barrancos encajados típicos de la transición a la Serranía Alta. La vegetación destaca por extensos matorrales de sabina albar, romero y pinares de pino negral adaptados a suelos esqueléticos.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','espacio','Hoz del Júcar, Hoz del Huécar, la Ciudad Encantada y los Callejones de Las Majadas (límite)','Uno de los conjuntos geomorfológicos y paisajísticos más colosales del mundo, célebre por sus cañones fluviales urbanos de paredes calizas verticales de más de 100 metros de altura [Cuenca]. El término alberga el laberinto de la Ciudad Encantada, un modelado kárstico kárstico de torcas, tormos y puentes de piedra esculpidos por erosión diferencial de primer orden planetario [Cuenca].   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16079','espacio','Complejo kárstico de la Cueva del Hierro y Sierra de Cuenca','Macizo de calizas mesozoicas fracturadas por la tectónica alpina, caracterizado por un relieve de fuertes desniveles y cavidades kársticas ricas en mineralizaciones de hierro. La vegetación está integrada por un denso encinar montano y matorrales basófilos.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16082','espacio','Las Chorreras del Cabriel, Hoz del Agua y cañón del río Mirón','Impresionante conjunto fluvial de saltos de agua, pozas de roca pulida y cascadas activas que depositan tobas y travertinos calcáreos de colosal valor contemplativo sobre el río Cabriel. Las laderas escarpadas de umbría están cubiertas por una densa masa de pino negral y sabinares albares.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16084','espacio','Hoz del río Escabas, nacimiento del Escabas y muelas calcáreas','Espectacular desfiladero de alta montaña labrado en las calizas y dolomías de la Serranía Alta, con saltos de agua verticales y fuentes naturales caudalosas. Las laderas están cubiertas por masas puras de pino albar y quejigales andaluces en régimen de umbría húmeda.   Cuenca).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16083','espacio','Valles del río Altarejos y dehesas arcillosas','Suaves ondulaciones de la campiña central constituida por depósitos detríticos miocénicos con escasa diferenciación topográfica. Presenta pequeñas formaciones herbáceas estacionales adaptadas a suelos francos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16091','espacio','Hoz de Fuertescusa y El Cucurucho','Cañón kárstico flanqueado por inmensas masas de pino laricio y rocas singulares con perfiles antropomorfos debido a la erosión. Destaca por sus fuentes naturales que brotan directamente de la roca calcárea y los paredones colonizados por aves rapaces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16093','espacio','Hoz del río Ojos de Moya y Peña de la Olmeda','Cañón fluvial excavado sobre areniscas y calizas con escarpes sinuosos que cobijan un ecosistema de ribera muy bien conservado. Destaca por los contrastes de la piedra calcárea gris y los sauces, fresnos y chopos que tapizan el lecho del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16112','espacio','Cerros calizos de la Alcarria y yeseras de Borbotón','Paisaje alcarreño caracterizado por muelas erosionadas y profundos barrancos labrados en estratos de yeso cristalino y arcillas. Ofrece un gran interés visual por los destellos de los cristales de selenita bajo la luz del sol en las laderas desnudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16116','espacio','El Masegar y Poljé de Lagunaseca','Impresionante depresión kárstica de fondo plano (poljé) que se inunda de forma temporal cuando asciende el nivel freático subterráneo. Rodeado de escarpes calizos y callejones de roca, constituye un ejemplo geomorfológico monumental de alta montaña conquense.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16121','espacio','Los Callejones de las Majadas y Hoz del Júcar','Laberinto kárstico monumental compuesto por pasillos rectilíneos, arcos de piedra, monolitos y formas caprichosas talladas por la erosión diferencial en las dolomías. Supera en escala de aislamiento botánico y pureza forestal a muchos conjuntos similares del continente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16135','espacio','Muela de Moya y barrancos arcillosos','Colosal plataforma calcárea sobreelevada de cumbre totalmente llana que domina visualmente toda la Serranía Baja. Sus laderas presentan una fuerte pendiente con procesos de deslizamiento rotacional y cárcavas sobre materiales arcillosos basales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16149','espacio','Hoz del río Huécar y nacimiento del río','Estrecho cañón calizo de umbría absoluta con paredes verticales tapizadas de musgo y hiedra donde el río Huécar da sus primeros pasos. La claridad de sus pozas de agua y las agujas rocosas calizas laterales configuran un pasillo de gran potencia estética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16170','espacio','Estrecho de Priego (Río Escabas)','Desfiladero angosto donde el río Escabas fractura la roca caliza abriendo una brecha de paredes verticales y limpias. La transparencia del flujo fluvial y la vegetación hidrófila aferrada a las fisuras de los cortados rocosos componen una estampa de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16186','espacio','Riberas del río Gigüela y meandros abandonados','Tramo de la cuenca media del Gigüela caracterizado por un curso divagante sobre materiales sedimentarios con llanuras de inundación. Su valor contemplativo reside en la morfología de sus curvas fluviales y la vegetación halófila asociada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16202','espacio','Callejón de los Moros y Cañón de Talayuelas','Impresionante desfiladero y formaciones de aglomerados de arenisca roja (rodeno) modelados por el viento y el agua en formas de torreones. El contraste entre los gigantescos monolitos rojizos y los verdes pinares circundantes crea una de las vistas más singulares del este provincial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16215','espacio','Nacimiento del río Júcar y Estrecho del Infierno','Cabecera fluvial de alta montaña donde el río Júcar brota de los acuíferos calizos de la ladera de San Felipe para encajonarse en una garganta atronadora. Rodeado de   praderas alpinas, farallones de caliza gris y densos bosques mixtos de pino albar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16218','espacio','Sierra de la Muela y cárcavas margosas','Relieve alcarreño de transición con estructuras tabulares erosionadas que exponen bandas alternas de arcillas y calizas. Destaca por sus amplios horizontes visuales sobre la meseta y las geoformas labradas por la escorrentía estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16219','espacio','Laguna de Uña y El Escalerón (Hoz del Júcar)','Laguna perenne originada por el cierre kárstico de una balsa fluvial, rodeada por colosales acantilados calcáreos de más de 300 metros de altura. La lámina de agua cristalina refleja los paredones de la muela en una de las composiciones de agua y relieve más perfectas de la Península.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16224','espacio','Valle del río Valdemeca y dehesas de quejigo','Entorno montañoso de la Serranía Alta caracterizado por un valle fluvial suspendido de morfología kárstico-glaciar. Destaca por albergar formaciones boscosas mixtas excelentemente conservadas y turberas de montaña ricas en flora reliquia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16239','espacio','Nacimiento del río Cuervo y tufa calcárea','Monumental cascada de travertino y toba calcárea donde el agua del río Cuervo brota de una cueva y se desparrama en hilos transparentes sobre cortinas de musgo petrificado. El entorno de umbría forestal con pinos y acebos conforma una joya botánica y geológica de primer orden nacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16245','espacio','Ventano del Diablo y Hoz del Júcar','Impresionante mirador natural geológico formado por un arco de roca caliza colgado a cientos de metros sobre el encajonamiento absoluto del río Júcar. Las formaciones de pozas verde esmeralda en el fondo del cañón y la magnitud de la erosión kárstica vertical son sobrecogedoras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16279','espacio','Valle del río Tajo y depósitos de yesos','Límite noroccidental de la provincia donde el río Tajo discurre sobre materiales del Mioceno terminal creando pequeños escarpes yesíferos. El interés visual radica en los estratos blanquecinos de las pendientes y los meandros suaves del curso fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16280','espacio','Hoz de Zarzuela y El Portillo','Desfiladero angosto labrado en las calizas de la Serranía Media que sirve de puerta de entrada a los relieves de alta montaña. Ofrece paredes escarpadas verticales con interesantes ejemplos de estratificación geológica y vegetación rupícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90681','espacio','Macizo de la Albera y formaciones graníticas de la riera d''Agullana','Relieve prepirenaico caracterizado por un paisaje de berrocales con grandes bloques y bolos graníticos redondeados por la erosión. Las laderas están cubiertas por densos alcornocales maduros que conviven con cursos de agua de fondo rocoso y gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90063','espacio','Valle de la riera de Güell y afloramientos volcánicos menores','Zona de llanura aluvial interrumpida por sutiles elevaciones de origen basáltico vinculadas a la región volcánica de la Garrotxa. Ofrece una composición visual de transición entre pastizales húmedos y pequeños reductos de robledales de llanura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90595','espacio','Alta Garrotxa, desfiladero de la Muga y Gorgues de Albanyà','Impresionante espacio kárstico de la cordillera prepirenaica con profundas gargantas esculpidas en calizas del Eoceno por aguas fluviales hipertransparentes. Alberga imponentes acantilados verticales, pozas naturales de color   turquesa y encinares de ladera en un estado de conservación climático absoluto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90596','espacio','Macizo de Tosa d''Alp y umbrías de la Tossa','Entorno de alta montaña pirenaica en el sector oriental de la Sierra del Cadí-Moixeró, caracterizado por escarpes calcáreos y canchales. Destaca por sus circos glaciares relictos y la transición botánica vertical hacia prados alpinos y bosques de pino negro con sotobosque de rododendro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90597','espacio','Riscos de Amer y fuentes de agua minero-medicinal','Colosales paredes y fallas verticales de piedra caliza que se elevan abruptamente sobre el valle del río Brugent. El modelado tectónico genera un relieve abrupto cubierto de vegetación esclerófila y encinares que contrastan con los afloramientos rocosos desnudos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90598','espacio','Vertiente norte de las Guilleries y riera de Osor','Relieve abrupto de materiales paleozoicos y graníticos caracterizado por valles encajonados y laderas de pendientes pronunciadas. Alberga densas masas forestales de castaños y encinas junto a un curso fluvial rápido dotado de un lecho pedregoso muy estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90599','espacio','Parque Natural del Montseny y riera de Arbúcies','Entorno submediterráneo y atlántico encajado en un valle de bloques graníticos y pizarras con laderas de umbría colosales. Su valor radica en la contemplación de frondosos hayedos y castañares maduros que flanquean un ecosistema fluvial prístino de aguas frías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90600','espacio','Valle del río Fluvià y terrazas fluviales','Tramo donde el río erosiona los depósitos sedimentarios fluviales originando pequeños escarpes arcillosos y playas calcáreas de guijarros. La panorámica combina la nitidez de la corriente de agua con franjas densas de alisedas y vegetación de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90601','espacio','Meandros finales del río Fluvià y llanura deltaica','Tramo final de sedimentación donde el cauce describe curvas perezosas antes de su desembocadura sobre arenas cuaternarias. Destaca por la observación botánica de carrizales y espadañales asociados a pequeños humedales estacionales e islas fluviales de sedimentación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90602','espacio','Garrigas del Ampurdán y afloramientos calizos','Meseta baja calcárea con un relieve suavemente ondulado dominado por procesos de erosión superficial y lapiaces incipientes. Ofrece una textura paisajística ruda de matorral xerófilo mediterráneo y encinas de porte arbustivo perfectamente adaptadas a la escasez de suelo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90603','espacio','Estany de Banyoles y red de lagunas tectónicokársticas','El mayor complejo lagunar de origen kárstico de la Península Ibérica, alimentado por surgencias subterráneas provenientes de la Alta Garrotxa. Ofrece una lámina de agua perenne y transparente de valor geológico excepcional, rodeada por travertinos, sauces y praderas de carófitos sumergidos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90604','espacio','Cortados fluviales del río Fluvià','Terrazas fluviales elevadas donde el cauce ha excavado potentes estratos sedimentarios arcilloso-calcáreos de color blanquecino. Su atractivo radica en la contemplación de los perfiles erosivos verticales y el contraste cromático con la vegetación de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','espacio','Acantilados del Cabo de Begur y Reserva Marina de Ses Negres','Impresionante tramo costero de geología predominantemente granítica y metamórfica, con abruptos paredones rocosos que caen en vertical sobre el mar Mediterráneo. Destaca por el modelado de cuevas marinas naturales y la pureza visual de sus aguas rodeadas de pinares relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90033','espacio','Formación rocosa de Sa Palomera y acantilados de Cala Sant Francesc','Promontorio granítico costero que emerge de forma monumental marcando geológicamente el inicio de la Costa Brava. Hacia el norte da paso a abruptos escarpes batidos por el oleaje, tapizados por matorral mediterráneo y especies saxícolas adaptadas a la salinidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17029','espacio','Salt de la Caula y gargantas del río Muga','Impresionante cascada y escarpe de toba calcárea (travertino) de origen cuaternario con más de 30 metros de caída libre. El entorno fluvial presenta formaciones kársticas de gran interés geológico, con oquedades naturales cubiertas por una densa cortina de musgo y hiedra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17027','espacio','Rieras de Breda y laderas del Macizo del Montseny','Valle encajonado sobre granitos degradados y arenas silíceas en la falda oriental del Montseny. El interés visual radica en la limpieza de los lechos fluviales de montaña y el espeso dosel de encinares mixtos y alcornocales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17028','espacio','Valle de la riera de Santa Coloma y lomas basálticas','Relieve de suaves colinas graníticas suavizadas por sedimentos donde afloran pequeñas coladas de origen volcánico. Ofrece un paisaje armonioso caracterizado por la alternancia de robledales húmedos y masas estables de pinar mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17031','espacio','Estribaciones de la Alta Garrotxa y cuenca del río Manol','Entorno prepirenaico de relieve quebrado con presencia de calizas eocénicas y terrazas rocosas. La vista destaca por la soledad de sus valles forestales cubiertos de encinar montano y la nitidez de los pequeños barrancos de cabecera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17032','espacio','Parque Natural del Cap de Creus y Oliveras de la Mar','El punto más oriental de la península, caracterizado por una geología extrema de pizarras y esquistos negros metamórficos erosionados por la tramontana. Sus acantilados abruptos, islotes rocosos y calas puras forman un laberinto mineral y un paisaje de costa salvaje único en el mundo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17033','espacio','Falla de Caldes y fuentes termales de Els Bullidors','Depresión tectónica donde la fractura del subsuelo permite el afloramiento directo de aguas termales a altas temperaturas. Ofrece interés geomorfológico por la observación de las alteraciones minerales en la roca granítica debido al hidrotermalismo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17034','espacio','Macizo de las Gavarres y acantilados de Cap Roig','Zona costera y de interior donde el relieve granítico de las Gavarres se hunde en el mar formando puntas   rocosas de tonalidades rojizas. El bosque de pinos y encinas llega hasta la misma línea de costa, fundiéndose con los arrecifes sumergidos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18004','espacio','Confluencia del Ter y el Ritort y umbrías de Cavallera','Cabecera fluvial de alta montaña pirenaica asentada en un valle de origen tectónico y glaciar. Presenta imponentes formaciones de prados alpinos, hayedos maduros en las laderas umbrías y un curso de agua cristalino con grandes cantos rodados calcáreos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17040','espacio','Gargantas de la riera de Canet y Volcán del Puig d''Adri','Formaciones volcánicas singulares donde las coladas basálticas fueron erosionadas por el agua, labrando marmitas de gigante y pozas circulares en la roca negra. El entorno forestal combina encinares mediterráneos asentados sobre gredas y escorias volcánicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17041','espacio','Sierra de la Albera y estanques estacionales de Cantallops','Paraje caracterizado por crestas graníticas fronterizas y pequeñas depresiones endorreicas que se inundan de forma temporal en invierno. Permite la contemplación de comunidades vegetales hidrófilas muy raras y un denso bosque mediterráneo continentalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17042','espacio','Berrocal granítico de Capmany','Extraordinaria concentración de bloques y bolos graníticos de colosales dimensiones esculpidos por la meteorización química y la erosión eólica. Las caprichosas formas de la piedra se integran en un paisaje xerófilo de alcornocal y matorral bajo de jaras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17044','espacio','Vertiente occidental de las Gavarres y riera de Gotarra','Paisaje de piedemonte donde el relieve de pizarras y granitos de las Gavarres se desvanece hacia la llanura de la Selva. Destaca por el valor botánico y la uniformidad visual de sus densos bosques de alcornoque destinados históricamente al corcho.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90035','espacio','Camino de Ronda costero y S''Agaró rocoso','Frente litoral granítico caracterizado por salientes rocosos, túneles naturales excavados por el oleaje y pequeñas calas pedregosas libres de arena fina. El pinar de pino carrasco se aferra de forma inverosímil a las fisuras del roquedo batido por el mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90889','espacio','Parque Natural de los Aiguamolls de l''Empordà','Complejo de marismas, lagunas litorales y prados inundables formados en la confluencia de los ríos Muga y Fluvià. Constituye un paisaje acuático de primer orden con extensas formaciones de carrizales, salicorniales y dunas costeras móviles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17046','espacio','Risco basáltico de Castellfollit','Monumental acantilado basáltico de más de 50 metros de altura y un kilómetro de longitud, formado por la superposición de dos coladas de lava enfriadas y erosionadas por los ríos Fluvià y Toronell. La espectacular columnata prismática basáltica es un prodigio geológico de nivel internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17049','espacio','Macizo de las Gavarres septentrionales y riera de Palagret','Laderas boscosas compuestas por pizarras paleozoicas y calizas replegadas. Ofrece un entorno   contemplativo de umbría forestal densa dominado por el encinar con madroños y pequeños riachuelos estacionales de lecho rocoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17086','espacio','Paraje Natural de Interés Nacional de l''Albera','Relieve montañoso granítico axial que marca la transición biogeográfica entre el clima mediterráneo y el atlántico. Sus laderas están dominadas por inmensas masas de alcornocales en las zonas bajas y hayedos relictos en las cumbres superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90610','espacio','Cap de Ras y litoral del Cap de Creus norte','Costa rocosa abrupta configurada por la erosión de la tramontana sobre esquistos y pegmatitas. Destaca por la total ausencia de playas de arena fina, sustituidas por plataformas de abrasión marina, arrecifes y una vegetación halófila adaptada al viento salino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17095','espacio','Acantilados de Cala Banys y Jardines de Santa Clotilde (entorno natural)','Costa escarpada de roca granítica desmantelada que dibuja profundos entrantes y salientes en el litoral de la Selva. Los acantilados se presentan coronados por masas compactas de pino piñonero que contrastan con los tonos turquesa del mar profundo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17114','espacio','Volcanes del Croscat, Santa Margarida y Fageda d''en Jordà','El corazón del Parque Natural de la Zona Volcánica de la Garrotxa. Presenta conos de piroclastos con cortes geológicos de extraordinarias gradaciones cromáticas (Croscat) y un hayedo excepcional (Fageda) asentado sobre una colada de lava llana, configurando un paisaje visual de ensueño místico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17117','espacio','Cabos de San Sebastián y Cap Roig','Formidables acantilados graníticos que alcanzan los 160 metros de altura sobre el nivel del mar, formando una de las estampas más icónicas de la Costa Brava. La costa es accidentada, con escollos marinos y una masa forestal litoral virgen de gran impacto estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17118','espacio','Espacio Natural de Castell-Cap Roig y Cala Estreta','Tramo litoral completamente virgen de la Costa Brava central, libre de edificaciones. Caracterizado por formaciones graníticas de color rosáceo erosionadas en formas suaves, islotes rocosos y un denso manto forestal de pino que besa las rocas de la orilla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17124','espacio','dunas de Pals y marismas del Bajo Ter','Sistema de dunas costeras semimóviles y humedales asociados a la antigua desembocadura del río Ter. Presenta un gran interés botánico por la preservación de la vegetación psammófila (adaptada a la arena) y la fisonomía llana de sus horizontes marítimos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17138','espacio','Acantilados de Punta de l''Ocell y Coll de Belitres','Paisaje extremo de frontera pirenaicomediterránea donde las últimas estribaciones de la cordillera se hunden abruptamente en el mar. Las paredes de pizarra negra son verticales, desnudas de árboles debido a la fuerza del viento y de una belleza mineral sobrecogedora.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17043','espacio','Valle de Nuria, Gargantas del Freser y Puigmal','Paisaje de alta montaña pirenaica pirenaica con circos glaciares calizos y de esquistos que superan los 2.900 metros de altitud. Las colosales gargantas excavadas por el   río Freser presentan saltos de agua espectaculares y bosques subalpinos de pino negro de valor biológico incalculable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17145','espacio','Valle de Ribes y confluencia de los tres ríos','Depresión de montaña rodeada de gigantescos relieves Prepirenaicos y Pirenaicos, donde confluyen los ríos Freser, Rigard y Segadell. Ofrece una estampa contemplativa de profundas laderas verdes, formaciones de pizarras paleozoicas y densos robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17147','espacio','Valle del río Ter y escarpes calcáreos de Catllarí','Tramo de erosión fluvial donde el Ter labra un valle encajonado entre sedimentos del Eoceno superior. Destaca por sus bosques mixtos de pino silvestre y roble pubescente que tapizan laderas de fuertes pendientes con estratos rocosos visibles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18014','espacio','Cabo Norfeu y Parque Natural del Cap de Creus meridional','Una estrecha península rocosa de origen volcánico y metamórfico que penetra dos kilómetros en el mar, formando acantilados de más de 150 metros. Su geomorfología incluye cuevas marinas y una vegetación arbustiva xerófila modelada de forma drástica por la tramontana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08021','espacio','Valle del Ter y Gorg de la Malatosca','Entorno subpirennaico húmedo donde destaca un salto de agua que vierte sobre una poza profunda labrada en estratos sedimentarios, rodeada de leyendas locales. El paisaje forestal está compuesto por ricos bosques de ribera y robledales atlánticos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17178','espacio','Dunas litorales y desembocadura del río Fluvià','Extenso frente playero virgen integrado en el Parque Natural dels Aiguamolls de l''Empordà, caracterizado por sistemas dunares activos bien conservados. Ofrece una vista limpia y diáfana de la Bahía de Roses con vegetación adaptada a suelos salinos y arenosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18015','espacio','Circo glaciar de Ulldeter y nacimiento del río Ter','Anfiteatro de origen glaciar a más de 2.000 metros de altitud, flanqueado por cumbres escarpadas como el Gra de Fajol. Destaca por sus lagunas de origen glaciar sepultadas, canchales de piedra granítica y praderas de alta montaña repletas de flora alpina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17199','espacio','Macizo del Montgrí e Islas Medas','Singular muela de piedra caliza que emerge de forma abrupta en mitad de la llanura ampurdanesa, prolongándose en el mar a través del archipiélago de las Islas Medas. Sus acantilados costeros marinos albergan colonias de aves y formas kársticas como el túnel de la Foradada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18017','espacio','Macizo de las Cadiretes y Cala Pola (entorno rocoso)','Litoral abrupto hiperfragmentado donde el macizo granítico de Cadiretes se fractura al contacto con el mar Mediterráneo. Los acantilados verticales están cubiertos de espesos bosques de alcornoques y pinos que caen sobre aguas de una pureza y transparencia extraordinarias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17208','espacio','Valles de Bianya y crestas de la Alta Garrotxa','Conjunto de pequeños valles de fondo plano formados por sedimentación fluvial y rodeados de imponentes vertientes boscosas calizas. Destaca por su verdor perpetuo, sus prados húmedos y la densidad de sus robledales de hoja grande y encinares de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17220','espacio','Parque Natural del Montseny y Castañar de las Neulas','Vertiente septentrional del macizo del Montseny, con un relieve configurado por materiales graníticos y esquistosos en un microclima de alta pluviosidad. Alberga majestuosos bosques de castaños centenarios de dimensiones monumentales, hayedos y fuentes de agua purísima de montaña.   ¡Objetivo cumplido! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90493','espacio','Depresión de Granada y lomas del río Cacín','Paisaje semiárido labrado sobre materiales sedimentarios miocénicos donde destacan relieves de lomas redondeadas y pequeños barrancos de arcilla. El atractivo radica en la amplitud visual de sus llanuras cerealistas esteparias y el fuerte contraste cromático de sus tierras baldías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90424','espacio','El Peñón de Alamedilla y cárcavas del río Guadahortuna','Impresionante elevación de roca caliza que emerge de forma aislada sobre un entorno de badlands arcillosos profundamente erosionados. Ofrece una fisonomía desértica singular de crestas afiladas y escorrentías que cambian de coloración según la incidencia de la luz solar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90494','espacio','Pantano del Cubillas y estribaciones de Sierra Elvira','Gran masa de agua interior encajada entre lomas suaves de olivar y los escarpes calizos septentrionales de Sierra Elvira. La lámina de agua ofrece un espacio de quietud visual rodeado de vegetación perilagunar y cortados de roca grisácea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90425','espacio','Barrancos de la Contraviesa y laderas de pizarra','Relieve abrupto de la Alpujarra Baja caracterizado por laderas de pendientes extremas compuestas por esquistos y pizarras desmanteladas. Destaca por sus profundas cuencas de recepción de torrentes estacionales y los amplios horizontes visuales que alcanzan el mar Mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90426','espacio','El Marquesado y llanura aluvial del río Verde','Altiplano de alta montaña situado en la falda norte de Sierra Nevada, compuesto por una inmensa llanura de sedimentación de cantos rodados y arenas rojizas. Su valor radica en la contemplación de un llano estepario infinito custodiado por las cumbres calcáreas de la sierra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90037','espacio','Hoz de Angosturas y acantilados de la costa de la Contraviesa','Desfiladero angosto y seco excavado por las avenidas de agua en las calizas de la sierra, con paredes verticales de gran estrechez. En su fachada marítima da paso a pequeños escarpes rocosos costeros libres de arena que rompen hacia el mar abierto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90427','espacio','Garganta del río Santo y umbrías de la Sierra de Almijara','Profundo cañón fluvial calizo encajonado de forma dramática entre los relieves dolomíticos de las Sierras de Tejeda, Almijara y Alhama. El curso de agua perenne genera cascadas menores y pozas cristalinas flanqueadas por una densa vegetación de umbría y adelfares salvajes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90428','espacio','Barranco del Chorrillo y umbrías del Marquesado (Sierra Nevada)','Paisaje montañoso de alta cota integrado en el Parque Nacional de Sierra Nevada, caracterizado por profundos valles labrados sobre pizarras paleozoicas y micaesquistos. Alberga masas densas de castañares viejos, robledales y un curso fluvial alpino de aguas procedentes del deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90429','espacio','Sierra de Huétor y Fuente de las Lágrimas (Ainadamar)','Macizo kárstico prebético caracterizado por lapiaces, dolinas y una alta permeabilidad que da origen a importantes surgencias naturales de agua purísima. Destaca por la pureza visual de sus tajos calizos grises rodeados por densos encinares montanos y pinares nativos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90430','espacio','Cañón del río Pesquera y Llanos de Villalvilla','Espectacular tajo fluvial excavado en calizas jurásicas con paredes verticales cubiertas de vegetación rupícola exótica y tobas calcáreas fósiles. El lecho del río alberga pozas de aguas de color turquesa rodeadas de un frondoso bosque de galería mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19001','espacio','Tajos de Alhama y Pantano de los Bermejales','Monumentales cortados calizos calcáreos con paredes verticales de más de 50 metros de caída labrados por el río Alhama, declarados Monumento Natural de Andalucía. Las formaciones de areniscas fosilíferas moldeadas por la erosión fluvial ofrecen uno de los cañones más imponentes y estéticos de la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90431','espacio','Secanos de Alhendín y lomas de la Malahá','Terreno ondulado de la Vega Alta compuesto por limos y arcillas con presencia de depósitos salinos superficiales en las zonas bajas. Destaca por la austera contemplación de sus paisajes esteparios y las tonalidades blanquecinas que adopta el suelo en época estival.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90495','espacio','Valle del río Guadahortuna y acantilados arcillosos de Alicún','Zona de contacto entre la Hoya de Baza y el relieve bético, caracterizada por farallones sedimentarios que caen sobre el valle fluvial. El entorno ofrece una panorámica limpia de badlands blanquecinos y una llanura de inundación de gran contraste visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90496','espacio','Tajo del Diablo (Río Guadalfeo) y laderas de la Alpujarra Alta','Impresionante hendidura geológica donde el río Guadalfeo se encajona de forma radical entre paredes de calizas tectónicas y esquistos. El relieve es quebrado, salvaje y cubierto de matorral mediterráneo aromático adaptado a las pendientes vertiginosas del cañón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19002','espacio','Peñón de Cristóbal y acantilados de Maro-Cerro Gordo (sector oriental)','Promontorios rocosos de esquistos y calizas que se adentran de forma abrupta en el mar Mediterráneo. Su interés contempla la fuerza del oleaje contra los perfiles minerales de la Costa Tropical, libres de playas de arena fina, y la presencia de matorral halófilo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18018','espacio','Corta minera de Alquife (Lagos de yeso y hierro)','Inmensa depresión artificial integrada en la fisonomía del Marquesado de Zenete, donde la naturaleza ha recolonizado el espacio formando lagunas interiores permanentes. Destaca por el colosal impacto cromático de los taludes oxidados en tonos rojizos que contrastan con las aguas azuladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18020','espacio','Parque Natural de Sierras de Tejeda, Almijara y Alhama','Paisaje prebético configurado por monumentales muelas calcáreas y crestas dolomíticas de color blanco grisáceo. El entorno destaca por la nitidez visual de sus barrancos calcáreos y los extensos bosques de pino carrasco y resinero que tapizan los abruptos desniveles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18021','espacio','Vega Baja de Granada y llanura de inundación del río Monachil','Espacio sedimentario de topografía completamente plana compuesto por depósitos de limos, arcillas y arenas cuaternarias. Presenta un relieve de escasa energía geomorfológica, interesante por la nitidez de su horizonte visual hacia el macizo de Sierra Nevada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18022','espacio','Crestas calizas de Sierra Elvira y tajo de la Ermita','Anticlinal aislado constituido por calizas jurásicas que emerge de forma abrupta en mitad de la depresión de Granada. Destaca por sus paredones grises erosionados, lapiaces iniciales y la presencia de vegetación termófila adaptada a las fracturas del roquedo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18023','espacio','Parque Natural de la Sierra de Baza y Badlands de la Hoya','Contraste geológico monumental entre el macizo montañoso bético con cumbres de calizas cristalinas calizas y la cuenca semiárida basal. Ofrece una espectacular contemplación de pinares autóctonos subalpinos y laderas desérticas labradas en yesos y arcillas multicolores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18024','espacio','Cabecera del río Darro y cerros del Fraile','Entorno caracterizado por un relieve de colinas calcáreas erosionadas por arroyos de cabecera con aguas de alta transparencia. La vegetación de encinar montano y las formaciones de cárcavas arcillosas en las vertientes bajas ofrecen un paisaje quebrado de gran nitidez.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18027','espacio','Badlands de Benalúa y confluencia de los ríos Fardes y Guadix','Uno de los paisajes de erosión geomorfológica en arcilla más espectaculares de la Península, con formaciones de chimeneas de hadas y farallones rojizos. El   contraste visual entre las tierras baldías desérticas y la estrecha franja verde de ribera es absoluto y sobrecogedor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18029','espacio','Cañón del río Guardal y acantilados de yeso','El río Guardal excava un profundo pasillo fluvial sobre materiales evaporíticos miocénicos, dejando al descubierto potentes estratos de yeso cristalino. Las laderas desnudas brillan con la luz solar, ofreciendo un entorno de texturas geológicas desérticas de gran singularidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18030','espacio','Junta de los Ríos y cabecera del río Guadalfeo (Sierra Nevada)','Paisaje alpino de la Alpujarra Alta integrado en el Parque Nacional de Sierra Nevada, labrado sobre pizarras oscuras. Los valles son profundos, con fuertes pendientes cubiertas de castañares relictos, prados de alta montaña y arroyos de aguas bravas procedentes del deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18032','espacio','Barranco del Poqueira (Sierra Nevada)','Colosal desfiladero de alta montaña pirenaica con desniveles verticales que superan los 1.000 metros desde las cumbres hasta el lecho del río. Configura un paisaje mineral y botánico sublime, con terrazas naturales de micaesquistos y densos bosques de robles melojos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18033','espacio','Garganta del río Trevélez y laderas de la Alpujarra Alta','Desfiladero angosto labrado por aguas bravas del deshielo sobre un sustrato de rocas metamórficas del complejo alpujárride. Las laderas presentan una pendiente extrema cubierta de vegetación arbustiva mediterránea y formaciones de encinar relicto colgadas sobre el vacío.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18035','espacio','Valle del río Guadalfeo y lomas del Albardinar','Depresión erosiva que separa la Sierra Nevada de la Contraviesa, caracterizada por un relieve quebrado de pizarras y filitas. El lecho del río se ensancha creando amplias   llanuras de cantos rodados y sauces que contrastan con las laderas desnudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18036','espacio','Vega Alta de Granada y terrazas del río Monachil','Pequeña llanura de piedemonte constituida por depósitos aluviales cuaternarios procedentes de Sierra Nevada. Destaca por la observación del abanico aluvial del río y la transición visual entre la llanura de inundación y las primeras pendientes montañosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18114','espacio','Llanura del Marquesado y faldas de micaesquistos','Altiplano de alta cota dominado por una inmensa llanura sedimentaria de color rojizo debido a la presencia de óxidos de hierro. Ofrece una perspectiva nítida de la planicie esteparia rota únicamente por las vertientes oscuras del Parque Nacional de Sierra Nevada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18037','espacio','Barrancos del río Bermejo y lomas arcillosas','Relieve de transición a la Sierra de Huétor con laderas arcillosas sujetas a procesos de erosión laminar y abarrancamientos. El paisaje destaca por sus tonalidades ocres y los pequeños cursos estacionales flanqueados por retamas y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18044','espacio','Tajo de los Bermejales y Minas de ramiro','Escarpados cortados calcáreos y gargantas estrechas que rompen la monotonía de las pizarras alpujárridas. Destaca por sus surgencias de aguas ferruginosas que tiñen la roca caliza de colores ocres e intensos y la presencia de sabinas de montaña en los riscos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18045','espacio','Badlands del río Guardal y Cañón de la Galera','Impresionante desierto de cárcavas y altiplanos tabulares (mesas) esculpidos en sedimentos lacustres del Cuaternario. El lecho encajonado de los ríos ofrece paredes totalmente verticales de arcillas limosas blanquecinas en un entorno de belleza desolada absoluta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18046','espacio','Parque Natural de la Sierra de Castril y Cerrada de la Magdalena','Monumental cañón calcáreo donde el río Castril ha esculpido desfiladeros de paredes verticales de más de 100 metros de altura con formaciones kársticas espectaculares. Alberga saltos de agua cristalina, puentes naturales de roca, cuevas y una flora de umbría subbética de primer orden.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18047','espacio','Valle encajonado del río Genil y escarpes de la Lancha','Tramo donde el río Genil abandona la alta montaña abriéndose paso a través de conglomerados y arcillas terciarias. Ofrece una vista de laderas escarpadas cubiertas de pinares de repoblación y formaciones de ribera en el fondo del cauce.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18059','espacio','Vega Central de Granada y depósitos aluviales del Genil','Llanura de sedimentación cuaternaria perfectamente horizontal formada por los arrastres fluviales del río Genil. Su interés radica en la inmensidad del horizonte limpio de relieves cercanos y la contemplación estacional de los humedales perilagunares menores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18062','espacio','Vega Baja del Genil','Llanura de inundación de orografía llana constituida por depósitos sedimentarios fluviales recientes. El interés contemplativo reside en la limpieza de los horizontes planos y la observación de las dinámicas de suelos de vega mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18048','espacio','Ribera del río Genil y llanuras arcillosas','Tramo de llanura de inundación donde el río Genil deposita limos y arenas finas sobre un relieve sin apenas pendiente. Destaca por la observación botánica de pequeñas formaciones de tarajes y álamos blancos asociados al curso de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18049','espacio','Peñón de la Atalaya y Parque Nacional de Sierra Nevada septentrional','Colosal mole caliza caliza jurásica que marca el límite geológico entre el Marquesado y las altas cumbres de micaesquistos. Su perfil abrupto ofrece una de las vistas más nítidas de la transición litológica de la cara norte de la sierra, rodeada de encinares montanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90432','espacio','Tajo de Cogollos y estribaciones de Sierra Arana','Impresionante tajo y pared vertical de roca caliza que domina el acceso al macizo kárstico de Sierra Arana. El entorno destaca por la rugosidad de su relieve, con lapiaces profundos, canchales y una vegetación saxícola adaptada a la roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18051','espacio','Tajos de Colomera y cañón del río Colomera','Desfiladero fluvial excavado en rocas calizas con cortados verticales que flanquean el cauce del río antes de su embalse. El entorno presenta formaciones kársticas menores, oquedades y masas densas de matorral mediterráneo de gran valor paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18053','espacio','Badlands del río Castril y terrazas sedimentarias','Extensa llanura de erosión marginal de la Hoya de Baza donde los arroyos han desmantelado el terreno en un laberinto de cárcavas y lomas afiladas de arcilla gris. La fisonomía es marcadamente estepa desértica, con texturas visuales únicas al amanecer.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18054','espacio','Peñas de Graena y badlands arcillosos del río Fardes','Formidables formaciones de arcilla roja y conglomerados erosionados que dan lugar a crestas afiladas e imponentes paredes que flanquean el valle. Ofrece un paisaje desértico de gran potencia plástica debido a la intensidad de sus tonos rojizos y ocres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18912','espacio','Embalse del Negratín (Margen norte) y badlands de yesos','Gran lámina de agua de color turquesa encajada de forma espectacular entre acantilados de arcillas, margas y yesos del cuaternario. El contraste visual entre el desierto absoluto de cárcavas blanquecinas y el azul intenso del agua configura un paisaje sobregogedor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18056','espacio','Barranco del Agua y badlands de Cúllar','Extenso territorio de la cuenca de Baza caracterizado por una fisonomía de badlands áridos con crestas afiladas de margas blanquecinas. Destaca por el aislamiento visual de sus valles secos y las formaciones de erosión remontante en las laderas expuestas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18057','espacio','Vega Central y llanura del río Dílar','Paisaje horizontal de origen aluvial en la depresión de Granada, constituido por depósitos de limos muy finos. Destaca únicamente por la limpieza de sus horizontes planos y la vista diáfana hacia los macizos montañosos circundantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18063','espacio','Sierra de Arana oriental y llanos de Darro','Altiplano de alta cota flanqueado por los relieves calizos de la sierra, con afloramientos kársticos y dolinas superficiales. El paisaje destaca por la pureza de sus horizontes de paramera y el contraste entre el suelo calizo gris y las dehesas de encinar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18064','espacio','Cañón del río Guadahortuna y badlands de dehesas','Uno de los cañones arcillosos más profundos y monumentales del geoparque de Granada, con paredes verticales esculpidas de más de 80 metros de altura. El desierto de cárcavas adquiere una dimensión colosal, mostrando estratos sedimentarios de millones de años de antigüedad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18065','espacio','Lomas de la llanura de Campotéjar y encinares de piedemonte','Relieve suavemente ondulado sobre arcillas y calizas del mioceno que marca la transición hacia la cordillera subbética. Presenta pequeños reductos de encinar adehesado que sobreviven sobre suelos margosos y horizontes limpios de relieve abrupto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18066','espacio','Nacimiento del Nacimiento (Río Cubillas) y Tajo de Deifontes','Gran surgencia kárstica natural donde el agua acumulada en el interior calizo de la Sierra de Arana brota a la superficie con un caudal constante y transparente. Aguas abajo, el río se encajona en un tajo de cortados verticales calcáreos de interés visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18067','espacio','Falla de Diezma y Peña de la Cruz (Sierra de Huétor)','Espectacular mirador geológico y relieve de calizas jurásicas desgarrado por un sistema de fallas activas que expone inmensas paredes rocosas de color gris. Ofrece una de las panorámicas más nítidas de la vertiente norte de Sierra Nevada sobre el mar de badlands basales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18068','espacio','Valle del río Dílar y silletas de Almijara (Sierra Nevada)','Valle de alta montaña que se adentra en el Parque Nacional de Sierra Nevada, labrado sobre calizas dolomíticas de la vertiente occidental. Presenta impresionantes tajos, cascadas de agua de deshielo e inmensos bosques de pino silvestre y sabinas de montaña en las cumbres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18069','espacio','Umbrías de Dólar y arroyo de la Rambla (Sierra Nevada)','Paisaje montañoso alpino asentado sobre el macizo de micaesquistos del Marquesado de Zenete. Destaca por sus densos bosques de pino silvestre y pino negro en las cotas altas, sus canchales oscuros y los riachuelos de montaña de aguas hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18070','espacio','Cañón del río Aguas Blancas y cerros de conglomerados','Estrecho tajo fluvial excavado en potentes formaciones de conglomerados formados por cantos rodados cementados del terciario. Las paredes del cañón presentan texturas geológicas singulares con colores ocres, rodeadas de matorral mediterráneo de jaras y romero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18071','espacio','Cañón del río Dúrcal y cascada de los Bolos','Impresionante garganta excavada por las aguas de deshielo en las calizas y dolomías de la vertiente occidental   de Sierra Nevada. Ofrece paredes verticales de roca caliza blanca cubiertas de musgo, fuentes naturales que surgen del roquedo y saltos de agua cristalina espectaculares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18072','espacio','Parameras de Escúzar y lomas calizas lacustres','Altiplano de relieve plano calizo horizontal constituido por sedimentos miocénicos que resistieron la erosión. El valor visual radica en la limpieza diáfana de sus cielos y la inmensidad del horizonte de secano estepario de la Mancha granadina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18074','espacio','Puerto de la Ragua (Vertiente norte) y barrancos de Ferreira','Paisaje alpino de alta montaña integrado en Sierra Nevada, caracterizado por laderas de pendientes extremas compuestas por micaesquistos. El entorno está cubierto por densos bosques de pino negro de montaña y prados húmedos de alta cota (borreguiles) de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18076','espacio','Badlands de Fonelas y yacimiento paleontológico (entorno geológico)','Desierto de cárcavas colosal integrado en la Hoya de Guadix, donde la erosión hídrica ha modelado un laberinto de barrancos de arcillas y arenas multicolores. Presenta perfiles geológicos limpios de vegetación que muestran las cuencas sedimentarias del plioceno en toda su magnitud plástica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18079','espacio','Confluencia del río Cubillas con el Genil y alamedas de ribera','Espacio llano de inundación de la Vega Baja donde coinciden dos de las principales arterias fluviales de la cuenca. Destaca por la contemplación visual de la densidad de sus masas forestales de galería compuestas por chopos, álamos y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18905','espacio','Lomas de Gabia Chica y depósitos de glacis','Relieve plano inclinado o glacis formado por la acumulación de sedimentos arrastrados desde las sierras cercanas sobre la fosa granadina. Ofrece una perspectiva diáfana de la llanura de la vega baja y las texturas de los suelos arcilloso-limosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18083','espacio','Llanos de Gobernador y barrancos del Guadahortuna','Paisaje de transición caracterizado por altiplanos arcillosos que sufren el avance de la erosión remontante desde la cuenca del Guadahortuna. Destaca por las tonalidades pajizas y ocres de sus laderas desnudas y la amplitud de sus horizontes limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18084','espacio','Barranco hondo y piedemonte de la Boca de la Pescá','Faldas montañosas compuestas por conglomerados detríticos terciarios fuertemente erosionados por escorrentías superficiales. Permite contemplar los pliegues geológicos que marcan el inicio del macizo calcáreo de Sierra Nevada occidental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18085','espacio','Cañón del río Gor y laderas de la Sierra de Gor','Impresionante desfiladero fluvial de varios kilómetros de longitud excavado sobre calizas y conglomerados terciarios con paredes verticales de gran altura. El fondo del cañón alberga una frondosa ribera verde que serpentea en mitad de la aridez del entorno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18086','espacio','Parque Megalítico de Gorafe y cañón del río Gor (Badlands de Gorafe)','Uno de los paisajes desérticos de badlands más espectaculares y sobrecogedores de España, caracterizado por inmensos cañones de arcillas rojas, amarillas y blancas. El modelado de cárcavas, chimeneas de hadas y farallones verticales constituye un monumento geológico de primer orden mundial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18088','espacio','Dehesa de Guadahortuna y lomas calcáreas','Paisaje caracterizado por un relieve ondulado calizo cubierto por formaciones aclaradas de encinar mediterráneo montano. Su valor radica en la contemplación de la transición entre la sierra boscosa subbética y las llanuras cerealistas de la provincia de Jaén.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18089','espacio','Badlands de Guadix y formación geológica de las Cuevas','Paisaje geológico colosal labrado por la erosión sobre arcillas del Mioceno, caracterizado por una inmensa concentración de cerros cónicos, cárcavas y chimeneas de hadas. El contraste cromático entre la arcilla ocre y la total ausencia de vegetación genera una estética visual única.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18906','espacio','Valle del río de la Toba y Sierra de Los Guájares','Valle recóndito y encajonado flanqueado por los abruptos relieves dolomíticos calizos de las sierras prelitorales. Ofrece una fisonomía salvaje de tajos rocosos verticales, fuentes naturales y una densa vegetación de transición con adelfares y alcornocales relictos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90038','espacio','Acantilados de Castell de Ferro y Tajo de los Viejos','Frente costero escarpado calizo donde la Sierra de Lújar se desploma de forma abrupta sobre el mar Mediterráneo. Presenta cortados de roca caliza gris, cuevas marinas naturales y una total ausencia de playas llanas, configurando un paisaje mineral marítimo puro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18094','espacio','Alta montaña de Sierra Nevada, cañón del río Genil (Los Presidiarios) y colas de caballo','Territorio alpino monumental que alberga las vertientes septentrionales de los picos Mulhacén y Veleta, labradas sobre micaesquistos oscuros. Presenta circos glaciares, canchales vertiginosos, cascadas de cientos de metros de caída libre y el salvaje cañón del río Genil en su cabecera prístina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18095','espacio','Lomas del arroyo de la Alfaguara y arcillas miocénicas','Terreno quebrado por fallas menores y deslizamientos de tierras arcillosas característico del sector norte de la depresión granadina. Permite observar los efectos de la geodinámica externa sobre materiales blandos y horizontes limpios de vegetación arbórea densa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18096','espacio','Barranco de Huélago y badlands de la cuenca de Guadix','Paisaje semiárido de cárcavas labradas sobre arcillas yesíferas blanquecinas con formas de lomas afiladas y pequeños cañones secos. Ofrece una gran quietud visual y una luz limpia que resalta los estratos sedimentarios de la cuenca lacustre resecada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18097','espacio','Barranco del agua y castañares de la cara norte de Sierra Nevada','Vertiente septentrional del macizo bético donde los torrentes de alta montaña han excavado profundos barrancos sobre las pizarras oscuras. El entorno destaca por la umbría forestal densa de castaños viejos y robles que flanquean las corrientes fluviales cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18098','espacio','Sierra de la Sagra (vertiente norte) y nacimiento de Fuencaliente','Colosal macizo calizo subbético que se eleva de forma monumental exento sobre el altiplano granadino, mostrando imponentes escarpes y canchales. Cuenta con importantes surgencias kársticas naturales de aguas transparentes que brotan directamente del subsuelo calcáreo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18099','espacio','Parque Natural de la Sierra de Huétor y Nacimiento del río Darro','Espectacular complejo kárstico con formaciones de lapiaces, dolinas, cuevas y tajos calizos grises tallados en rocas del jurásico. El nacimiento del río Darro brota como una surgencia pura rodeada de frondosos bosques de pino laricio, encinas y quejigos montanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18101','espacio','Barranco de Doña Juana y piedemonte bético','Vertiente de colinas detríticas y conglomerados que marca el tránsito entre Sierra Nevada y el inicio de la fosa aluvial. Su interés visual radica en la panorámica diáfana de la vega central protegida por el frente montañoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18102','espacio','Sierra de Parapanda y Tajos de Illora','Imponente anticlinal calizo calizo jurásico que se eleva de forma monumental sobre el poniente granadino. Sus vertientes presentan escarpes verticales descarnados, grandes fracturas geológicas y encinares de montaña que colonizan las grietas de la roca viva.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18105','espacio','Cueva del Agua y Cañón del río Sotillo (Sierra Arana)','Formidable cañón fluvial calizo encajonado entre los relieves calizos de Sierra Arana, con paredes verticales de gran potencia visual. Alberga una de las mayores redes de cavidades kársticas de Andalucía, con paisajes subterráneos de estalagmitas y estalactitas colosales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18107','espacio','Río Grande (Jayena) y umbrías de la Sierra de Almijara','Curso de agua prístina que discurre encajonado en un lecho de arenas dolomíticas blancas procedentes de la erosión del macizo de Almijara. Ofrece una estampa contemplativa de aguas transparentes rodeadas de densos pinares autóctonos y cortados rocosos grises.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18108','espacio','Barranco de Alhorí y altas cumbres de Sierra Nevada norte','Espectacular valle glacial labrado sobre micaesquistos oscuros que asciende directamente hacia las mayores cumbres del macizo. Presenta canchales vertiginosos, prados alpinos húmedos (borreguiles) y el río Alhorí, que salta entre bloques de piedra en cascadas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18109','espacio','Gargantas del río Verde y Sierra de Bodíjar','Profundo cañón encajonado calizo prelitoral donde el río Verde labra paredes verticales calizas de gran estrechez. Las aguas son hipertransparentes de color verde   esmeralda, discurriendo entre una densa vegetación de umbría y adelfares monumentales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18111','espacio','Lomas arcillosas del río Juncaril','Relieve suavemente ondulado de la depresión de Granada compuesto por formaciones arcillo-arenosas miocénicas propensas a la erosión hídrica. Destaca por las texturas ocres del suelo desnudo y los pequeños barrancos formados por la escorrentía superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18112','espacio','Fuerte de Juviles y castañares de la Alpujarra Alta','Relieve abrupto de pizarras y micaesquistos situado en la vertiente sur de Sierra Nevada. Destaca por la contemplación visual de sus imponentes terrazas naturales de cultivo abandonadas, densos bosques de castaños centenarios y arroyos de deshielo de aguas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18115','espacio','Terrazas fluviales del río Genil occidentales','Llanura de sedimentación aluvial del cuaternario donde el río Genil ensancha su curso medio depositando gravas y arenas. Ofrece un horizonte diáfano y plano de vega baja con sutiles alamedas de galería en los márgenes fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18116','espacio','Valle del río Lanjarón y cumbre de Caballero','Cabecera de valle alpino de Sierra Nevada caracterizada por desniveles brutales que caen hacia la depresión de Padul. Sus aguas brotan directamente del deshielo de las pizarras de alta cota, fluyendo entre bosques de castaños monumentales, robledales y cascadas de gran potencia visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18117','espacio','Barranco del río Lanteira y picos de micaesquistos','Entorno de alta montaña en el Marquesado de Zenete, integrado en el Parque Nacional de Sierra Nevada. Ofrece un paisaje salvaje de profundas gargantas labradas en rocas metamórficas oscuras, acompañadas de encinares montanos y cascadas estacionales de gran belleza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18119','espacio','Valle de Lecrín y barranco de Chite','Depresión tectónica frondosa situada entre Sierra Nevada y las sierras prelitorales, caracterizada por un microclima húmedo y fallas activas. Presenta un relieve ondulado de arcillas y conglomerados con fallas visibles y pequeños riachuelos permanentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18028','espacio','Valle del río Guardal y escarpes calizos de la Hoya','Tramo donde el río excava pasillos estrechos entre colinas sedimentarias de composición calcáreomargosa. Ofrece un paisaje relajado de laderas cubiertas de matorral mediterráneo que vierten de forma directa hacia el curso de agua perenne.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18034','espacio','Tajos de Cacín y cañón del río','Tramo fluvial encajonado de forma abrupta entre paredes de conglomerados y areniscas terciarias modeladas por la erosión eólica y fluvial. Ofrece pasillos rocosos angostos y cuevas naturales en las paredes que albergan una rica comunidad de rapaces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18038','espacio','Cañada del río de las Juntas y cerros calizos','Relieve de transición bética compuesto por colinas calcáreas y valles suaves por donde discurren arroyos estacionales. Destaca por la presencia de pequeñas formaciones de matorral mediterráneo y la nitidez de las estructuras geológicas plegadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18039','espacio','Vertiente norte de la Sierra de Baza y badlands del río Bodurria','Espacio caracterizado por profundos barrancos y chimeneas de hadas labrados sobre arcillas que se funden con los bosques de pinos de la sierra. Ofrece un paisaje dual de gran valor estético, con transiciones bruscas entre el desierto y la montaña húmeda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18040','espacio','Puente de Palo y cabecera del río Chico (Sierra Nevada)','Entorno alpino escarpado con profundos tajos excavados en esquistos paleozoicos cubiertos de densas masas de castaños centenarios. Las fuentes y saltos de agua cristalina brotan continuamente en un paisaje dominado por la verticalidad y la umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18042','espacio','Alta montaña del Barranco del Poqueira, mulhacén occidental y lagunas glaciares','Escenario colosal de alta montaña pirenaica en pleno Parque Nacional de Sierra Nevada, flanqueado por las mayores cumbres de la Península. Presenta circos glaciares, canchales de micaesquistos oscuros, cascadas de agua de deshielo y lagunas glaciares relictas de gran pureza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18043','espacio','Barranco del río Chico y laderas de filitas','El municipio más pequeño de la Alpujarra, asentado sobre un relieve de pendientes moderadas compuesto por arcillas esquistosas. Destaca por la contemplación de sus masas estables de encinar mediterráneo y las panorámicas del valle del Guadalfeo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18061','espacio','Llanos de Chimeneas y lagunas intermitentes','Altiplano arcilloso con pequeñas depresiones endorreicas que acumulan agua de lluvia de forma estacional.   Ofrece un paisaje estepario de suaves ondulaciones del terreno y texturas arcillosas que reflejan la luz del sol de manera uniforme.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18078','espacio','Puntal de la Bahía y acantilados del embalse del Negratín','Formidables farallones de arcillas y yesos estratificados que se hunden de forma directa en las aguas del   embalse, creando una bahía interior interior. El paisaje destaca por el violento contraste entre la aridez del desierto y el azul de la lámina de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18082','espacio','Badlands de Galera y monolito del Cerro de la Virgen','Paisaje desértico excepcional caracterizado por una densa red de cárcavas y barrancos labrados sobre sedimentos lacustres arcilloso-yesíferos. Destaca por sus chimeneas de hadas, farallones multicolores y la total desnudez vegetal que resalta la geología del terreno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','espacio','Dehesa del Generalife, cerro del Sol y barranco del Abogado','Entorno natural montañoso configurado por el valle del río Darro y los conglomerados de la formación Alhambra (Alhapa). Ofrece imponentes tajos arcillosos de color rojizo, cuevas naturales y una rica vegetación mediterránea termófila que domina visualmente la depresión fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18100','espacio','Ribera del río Genil y llanura de inundación de Loja','Tramo de la vega baja del Genil constituido por una amplia llanura aluvial de sedimentos cuaternarios fértiles. Destaca por la observación botánica de sus formaciones de ribera (álamos, sauces y carrizales) que acompañan el curso lento del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18103','espacio','Sierra de Bodíjar y nacimiento del río Itrabo','Relieve abrupto de la Costa Tropical compuesto por mármoles y calizas dolomíticas fuertemente plegadas. Ofrece un paisaje quebrado de barrancos secos con una rica vegetación termófila mediterránea y una surgencia natural de agua cristalina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18120','espacio','Barranco de Lentegí y relieves dolomíticos de Almijara','Desfiladero kárstico de paredes verticales de calizas paleozoicas y dolomías blancas cristalinas. Ofrece un paisaje mineral agreste e impactante, con angostos pasillos de roca erosionada por el agua y vegetación rupícola aferrada a los escarpes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18121','espacio','Rambla de Tímar y formaciones de pizarras erosionadas','Pequeño municipio alpujarreño enclavado en un relieve de lomas desnudas formadas por materiales pizarrosos y arcillas. Su interés radica en la contemplación de cárcavas y el modelado erosivo de los torrentes estacionales sobre tierras desérticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','espacio','Monumento Natural de los Infiernos de Loja y Sierra de Loja','Espectacular tramo del río Genil que se encajona en un cañón kárstico con saltos de agua, cascadas y colosales formaciones de travertinos y tobas activas. El macizo calcáreo colindante presenta un relieve de lapiaces y dolinas de primer orden geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18123','espacio','Dehesa del Camarate (El bosque encantado)','Una de las joyas botánicas de Andalucía, situada en la vertiente norte de Sierra Nevada. Alberga el bosque mixto de hoja caduca mejor conservado del sur peninsular, con robles melojos, arces, maguillos y fresnos que crean un espectáculo cromático sin igual en otoño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18124','espacio','Sierra de Lújar y alcornocal calcícola','Imponente mole calcáreo-dolomítica que se eleva de forma abrupta junto al mar Mediterráneo. Destaca por albergar un rarísimo reducto de alcornocal asentado sobre suelos carbonatados y por sus miradores geológicos naturales hacia la costa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18126','espacio','Salinas de interior y diapiros de yeso de la cuenca bética','Depresión geomorfológica con importantes afloramientos de yesos triásicos y aguas hipersalinas debido a la disolución de sales subterráneas. Ofrece un paisaje austero y blanquecino de gran interés mineralógico y texturas salinas únicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18127','espacio','Llanura aluvial de la Vega Central','Entorno plano dominado por los depósitos cuaternarios de limo y arcilla del río Genil. Presenta un relieve estrictamente horizontal de interés visual limitado a la   contemplación de la amplitud de la cuenca sedimentaria granadina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18128','espacio','Monumento Natural de las Cárcavas de Marchal','Espectacular macizo de arcillas y margas del Mioceno erosionado por la acción del agua en forma de afiladas agujas, anfiteatros y chimeneas de hadas. El conjunto conforma un paisaje de badlands de tonos ocres y dorados de un impacto visual y geológico monumental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18132','espacio','Desfiladero del río Velillos y Tajos de la Hoz','Angosto cañón fluvial labrado por el río sobre calizas jurásicas, con imponentes cortados verticales y abrigos naturales de roca. El lecho del río corre encajonado entre una frondosa vegetación de ribera y espectaculares paredes de piedra gris.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18133','espacio','Vertiente sur de la Sierra de Los Guájares','Relieve montañoso prelitoral compuesto por laderas abruptas de calizas y esquistos. Ofrece una fisonomía de contrastes entre el monte bajo mediterráneo xerófilo de las cumbres y los pequeños valles húmedos orientados al mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18134','espacio','Desfiladero de Los Cahorros y cumbres del Mulhacén (norte)','Impresionante cañón calizo de paredes totalmente verticales que casi llegan a tocarse sobre el río Monachil. Hacia las cotas altas, el término municipal se extiende hasta las mayores cumbres de micaesquistos de Sierra Nevada, ofreciendo paisajes de alta montaña alpina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18135','espacio','Peñón de la Sabika y formaciones calizas del arroyo Milanos','Conjunto de crestas y muelas calizas jurásicas que emergen con fuerza en el paisaje del poniente granadino. Destaca por sus escarpes rocosos modelados por la erosión eólica y las pequeñas oquedades formadas por procesos kársticos superficiales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18136','espacio','Cerros de la cuenca del Guadahortuna y encinares de ladera','Relieve de lomas y cerros testigo compuestos por arcillas, calizas y yesos en el límite norte provincial. Su atractivo visual reside en la sobriedad del paisaje y en los pequeños reductos de encinar mediterráneo que resisten en las cumbres pedregosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18137','espacio','Barrancos del río Frailes y llanuras arcillosas','Paisaje quebrado de la zona subbética caracterizado por cerros de margas y limos expuestos a la erosión. Ofrece una panorámica de laderas erosionadas y pequeños cursos de agua estacionales de carácter torrencial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18138','espacio','Badlands del río Cacín y terrazas sedimentarias','Tramo donde el río Cacín corta los depósitos pliocénicos de la depresión de Granada, creando taludes arcillosos verticales y cárcavas de color rojizo. El contraste entre el fondo verde del valle y los escarpes áridos es muy fotogénico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18909','espacio','Cerros de Moreda y cañada del río Labor','Paisaje de lomas onduladas y pequeñas muelas calizas que rompen la llanura de la Hoya de Guadix. Presenta interés por sus perfiles geológicos y los contrastes lumínicos sobre los cultivos esteparios y los afloramientos margosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18140','espacio','Acantilados de Calahonda, Sacratif y Humedal de la Charca de Suárez','Frente litoral caracterizado por el Cabo Sacratif, un saliente rocoso de calizas y esquistos que rompe la línea de costa con abruptos escarpes marinos. Cuenta además con un humedal costero de gran valor con láminas de agua dulce permanentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18141','espacio','Cerros de la Contraviesa y Cerro Cerrajón','Paisaje alpujarreño de media montaña dominado por pizarras y esquistos del complejo alpujárride. Desde sus puntos más altos, formados por lomas romas y barrancos profundos, se divisan panorámicas inmensas que abarcan de Sierra Nevada al mar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18143','espacio','Monumento Natural de la Falla de Nigüelas y cañón del río Torrente','Espectacular accidente geológico visible a simple vista, formado por un plano de falla calizo totalmente liso y vertical de grandes dimensiones. El río Torrente excava a sus pies un cañón abrupto con canchales y bloques de piedra desprendidos de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18144','espacio','Sierra de la Alfaguara y Peña de la Cruz','Vertiente de la Sierra de Huétor con relieves calizos escarpados de morfología kárstica. Permite la contemplación de formaciones de lapiaces, agujas de piedra caliza gris y densos bosques de pino negral y encinas de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18145','espacio','Llanura aluvial del río Dílar','Zona llana de la Vega de Granada compuesta por arenas, limos y gravas cuaternarias transportadas por los   ríos de Sierra Nevada. Destaca únicamente por la fisonomía horizontal de sus suelos de aluvión.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18146','espacio','Barranco del Paso y humedales fósiles de la Hoya de Baza','Paisaje desértico y monumental de badlands compuestos por calizas lacustres y margas de un antiguo lago pliocénico. Sus formaciones tabulares, barrancos blanquecinos y paleocauces ofrecen una estética árida de gran valor geológico y contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18147','espacio','Valle del río Guadalfeo y la vega de olivos centenarios','Amplia cuenca aluvial encajada entre la Sierra de Lújar y Sierra Nevada, donde el río Guadalfeo ensancha su lecho de cantos rodados. Ofrece una estampa contemplativa de un oasis aluvial rodeado de escarpadas vertientes montañosas.   Ojíjares - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18150','espacio','Humedal de Padul (La Laguna de Padul)','Excepcional depresión tectónica que alberga una de las principales turberas del sur de Europa. Sus extensas láminas de agua permanente, rodeadas por inmensos carrizales y sauces, constituyen un paisaje acuático interior de extraordinario valor botánico y geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18151','espacio','Barranco del Poqueira','Impresionante desfiladero de origen tectónico y glaciar que desciende verticalmente desde las altas cumbres de Sierra Nevada. Las laderas del cañón, compuestas por pizarras oscuras, caen de forma vertiginosa sobre el río Poqueira en una de las estampas de relieve más colosales de España.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18152','espacio','Cerros de Mencal y badlands del norte','Formación geológica tabular y relieves de muelas que emergen sobre una llanura semiárida de arcillas erosionadas. Destaca por el perfil abrupto de su peñón calizo y los contrastes de luz sobre las cárcavas circundantes al atardecer.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18153','espacio','Lomas del río Juncaril y arcillas de la vega','Terreno de colinas bajas arcillo-arenosas situado en el sector norte de la depresión de Granada. Presenta formas suaves labradas por la escorrentía superficial sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18154','espacio','Embalse de Francisco Abellán y río Fardes','Cañón fluvial encajonado donde las aguas del río Fardes se remansan entre imponentes cortados calizos y montañas cubiertas de pino laricio. La panorámica de la lámina de agua turquesa entre los abruptos relieves prebéticos posee un gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18159','espacio','Cueva de las Ventanas y Tajos de Píñar','Impresionante complejo kárstico subterráneo y exterior caracterizado por colosales tajos calizos verticales. La cueva presenta un desarrollo monumental de estalagmitas, estalactitas y grandes salas de colapso geológico visibles desde sus amplias bocas naturales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18157','espacio','Desfiladero del río Genil y laderas de Sierra Nevada','Punto de salida del río Genil de las altas cumbres de Sierra Nevada, labrando un valle estrecho encajado entre conglomerados y pizarras. Presenta una frondosa vegetación de ribera con castaños y álamos que contrasta con el relieve quebrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18158','espacio','Sierra de Elvira (vertiente occidental) y Cerro de los Infantes','Promontorio calizo aislado que emerge con fuerza en mitad de la llanura de la Vega de Granada. Presenta escarpes rocosos calizos del Jurásico con interesantes fenómenos de disolución kárstica y cuevas menores en sus laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18164','espacio','Macizo de Sagra y Sierra de Guillimona','Paisaje subbético de alta montaña dominado por el imponente pico de La Sagra, una colosal mole caliza que se eleva exenta sobre el altiplano. Destaca por sus canchales de piedra, escarpes de dolomías grises y la presencia de pinares de pino laricio y sabinares subalpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18165','espacio','Cuenca del río Juncaril y lomas margosas','Relieve suave de colinas bajas compuestas por sedimentos terciarios de la depresión granadina. Ofrece una estampa puramente rural y esteparia de formas redondeadas por la erosión agrícola y laminar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18167','espacio','Badlands de Purullena y chimeneas de hadas del Fardes','Impresionante laberinto geomorfológico de cárcavas, barrancos y crestas de arcilla de tonalidades rojizas y amarillentas hipererosionadas por el agua. Constituye uno de los paisajes desérticos continentales más puros y plásticos de la Península Ibérica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18168','espacio','Pantano de Quéntar y cañón del río Aguas Blancas','Estrecho desfiladero fluvial excavado en calizas y dolomías donde las aguas cristalinas del río se remansan en un embalse de montaña. Las paredes verticales del cañón y la masa forestal de pinos circundante ofrecen un paisaje de gran pureza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18170','espacio','Barrancos de Rubite y acantilados de Casarones','Municipio de la Contraviesa que desciende verticalmente desde las cumbres de pizarra hasta el mar. Presenta un relieve de laderas vertiginosas de esquistos oscuros que terminan en pequeños acantilados marinos libres de playas urbanas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18171','espacio','Baños de Salar y arroyo de Salar','Pequeño valle fluvial donde afloran surgencias de aguas termales de carácter kárstico sobre un entorno de lomas calizas suaves. Ofrece un paisaje relajado de pequeñas pozas naturales y formaciones de toba calcárea en el lecho del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18173','espacio','Peñón de Salobreña y acantilados de La Caleta','Promontorio calizo aislado que emerge en mitad de la llanura deltaica del río Guadalfeo, flanqueado hacia el oeste por acantilados marinos de dolomías que caen sobre el mar Mediterráneo, mostrando la fuerza de la abrasión marina sobre la roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18174','espacio','Valle del río Alhama y formaciones de areniscas','Tramo de llanura aluvial encajada entre colinas de areniscas fósiles y arcillas pliocénicas. Su interés contemplativo radica en los perfiles erosivos de las laderas y los sutiles meandros que dibuja el río sobre el terreno blando.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18175','espacio','Dehesa de Santa Fe y aguas termales del paraje','Llanura horizontal de la Vega de Granada donde destaca una pequeña surgencia de aguas termales ligada a las fallas profundas de la depresión. El paisaje es llano, aluvial y rodeado de formaciones vegetales de ribera y cultivos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18176','espacio','Barranco de Chico y umbrías de la Sierra de Soportújar','Término municipal colgado en las faldas de Sierra Nevada con pendientes extremas sobre esquistos y pizarras. Destaca por sus formaciones de saltos de agua de montaña, densos encinares montanos bien conservados y canchales de alta cota.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18177','espacio','Barranco de Melicena y acantilados litorales','Relieve quebrado de la Alpujarra Baja que muere directamente en el litoral mediterráneo. Sus laderas de pizarras oscuras caen en forma de escarpes escarpados sobre el mar, creando una línea de costa salvaje y abrupta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18901','espacio','Barranco de Trevélez, Tajos de Pitres y río Guadalfeo','Espectacular conjunto geográfico que engloba profundos cañones fluviales excavados sobre pizarras y calizas tectónicas. Las vertientes son de una verticalidad colosal, tapizadas de castaños, álamos y cascadas naturales que vierten al río Trevélez.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18178','espacio','Parameras del norte y cerro de la Cardela','Altiplano estepario de la zona subbética caracterizado por relieves llanos elevados y pequeñas lomas margosas propensas a la erosión. Destaca por sus horizontes infinitos de carácter semiárido y las texturas de la roca caliza degradada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18179','espacio','Valle del río Guadalfeo y laderas de la Contraviesa','Espacio donde el río Guadalfeo discurre encajonado entre las dos grandes cadenas montañosas de la Alpujarra. Ofrece una vista imponente de laderas de fuerte pendiente compuestas por esquistos desmantelados y vegetación mediterránea termófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18180','espacio','Valle glaciar del río Trevélez, Siete Lagunas y Mulhacén (vertiente este)','El municipio más alto de la península, ubicado en pleno Parque Nacional de Sierra Nevada. Presenta una morfología glaciar colosal con circos, lagunas alpinas de alta cota sobre micaesquistos y cascadas atronadoras rodeadas de prados subalpinos de borreguiles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18181','espacio','Valle del río Turón y lomas de la Alpujarra Baja','Paisaje árido y quebrado compuesto por pizarras y formaciones carbonatadas degradadas en el límite con Almería. Su interés visual radica en el aislamiento   absoluto de sus barrancos secos y en la vegetación xerófila mediterránea perfectamente adaptada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18914','espacio','Llanuras aluviales del río Cubillas','Término municipal ubicado en el sector noroccidental de la vega, con un relieve llano de depósitos sedimentarios cuaternarios. Paisaje horizontal de interés puramente agronómico y fluvial básico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18902','espacio','Barranco de Restábal y ribera del río Ízbor','Entorno quebrado del Valle de Lecrín donde el agua ha labrado profundos barrancos sobre materiales calizos y arcillosos. Ofrece una estampa de gran frescura visual por la abundancia de fuentes y cursos de agua encajados en laderas verdes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18907','espacio','Badlands de Alcudia y Rambla de Alquife','Gran depresión sedimentaria de la Hoya de Guadix caracterizada por un paisaje laberíntico de cárcavas, chimeneas de hadas y taludes de arcilla roja y ocre. El modelado erosivo del agua sobre los materiales blandos crea una panorámica desértica espectacular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18183','espacio','Barranco de Válor y umbrías de la Sierra de Mecina','Término alpujarreño que se extiende por la ladera sur de Sierra Nevada sobre pizarras paleozoicas.   Destaca por sus cursos de agua cristalina encajonados en profundas quebradas flanqueadas por frondosos castañares y bosques de ribera reliquias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18911','espacio','Meandros del río Genil en la Vega Baja','Espacio totalmente plano de sedimentación fluvial donde el río Genil describe curvas perezosas sobre un lecho de limos. Paisaje horizontal con horizontes limpios dominados por las alamedas de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18184','espacio','Garganta del río Guadalfeo (Tajo de los Vados) y Jardín Nazarí (entorno vertical)','Impresionante desfiladero fluvial con paredes calizas verticales de varios cientos de metros de altura que aprisionan el río Guadalfeo antes de su salida al mar. El modelado kárstico incluye espectaculares formaciones de tobas calcáreas y surgencias de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18185','espacio','Parameras de Ventas de Huelma y lomas arcillosas','Paisaje llano y elevado de la meseta granadina interrumpido por suaves ondulaciones de margas y arcillas. Ofrece una panorámica esteparia y diáfana con vegetación arbustiva xerófila adaptada a la escasez de agua superficial.   Villa de Otura - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18908','espacio','Garganta del río Dúrcal y lomas de Cónchar','Espacio quebrado donde el río Dúrcal labra un profundo cañón calizo con presencia de fuentes termales y formaciones de travertinos fósiles. Las laderas presentan fuertes pendientes cubiertas de matorral mediterráneo y pinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18187','espacio','Cañón del río Fardes y Baños de Alicún de las Torres','Espectacular cañón calizo y arcilloso donde destacan las formaciones de la Acera del Fardes, una pared de toba calcárea gigantesca creada por el depósito de aguas termales. El paisaje circundante de badlands desérticos es de una belleza geológica sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18188','espacio','Confluencia del río Cacín y el río Genil','Espacio aluvial donde confluyen dos de los cursos fluviales más importantes de la depresión granadina. Ofrece una vista contemplativa de amplias terrazas de cantos rodados, islas de sedimentación fluvial y densas alamedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18189','espacio','Barranco de Víznar y Puerto de la Alfaguara (Sierra de Huétor)','Entorno kárstico prebético caracterizado por laderas calizas cubiertas de densos pinares de repoblación e 清 densos encinares autóctonos. Ofrece imponentes formaciones de tajos grises y un relieve quebrado rico en formaciones de disolución kárstica superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18192','espacio','Poljé de Zafarraya','La mayor depresión kárstica de fondo plano (poljé) de la Península Ibérica, cerrada por imponentes murallones calcáreos de las sierras béticas. El contraste visual entre el llano aluvial absoluto y las paredes de roca vertical grisácea que lo delimitan es un hito geomorfológico único.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18913','espacio','Embalse de Iznájar y escarpes del río Genil','Municipio situado en el extremo occidental de la provincia donde el río Genil se remansa en el mayor embalse de Andalucía. Ofrece panorámicas de grandes láminas de agua encajonadas entre lomas de calizas y arcillas cubiertas de monte bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18193','espacio','Barranco de Corvales y Cumbres Verdes (Sierra Nevada)','Vertiente noroccidental del Parque Natural de Sierra Nevada caracterizada por calizas dolomíticas degradadas que forman arenas blancas (arenas de dolomía). Destaca por sus formaciones de barrancos angostos y el imponente contraste de los pinares sobre el suelo blanquecino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18194','espacio','Cerro Jabalcón y Baños de Zújar','Colosal monte de roca caliza jurásica (cerro testigo) que emerge de forma totalmente aislada en mitad de la llanura de la Hoya de Baza. A sus pies, junto al embalse del Negratín, afloran surgencias de aguas termales en un entorno de badlands blanquecinos espectacular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90163','espacio','Valle del río Tajuña y escarpes calizos','Tramo fluvial donde el río Tajuña corta los estratos calizos de la Alcarria Alta, modelando un valle encajonado de vertientes pronunciadas. Ofrece una   composición visual armónica entre las formaciones rocosas de las muelas y los frondosos bosques de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90164','espacio','Cañón del río Ablanquejo e integraciones del Alto Tajo','Profundo desfiladero excavado en calizas y dolomías jurásicas con paredones verticales cubiertos de vegetación saxícola. El cauce, rodeado de extensas masas de pino laricio y sabinas albares, forma un espacio de contemplación geológica salvaje y aislado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90165','espacio','Parameras del Señorío de Molina y arroyo de Adobes','Relieve de alta paramera caracterizado por una fisonomía horizontal severa sobre materiales calcáreos sometidos a un clima extremo. Su interés radica en la pureza de sus horizontes diáfanos y las sutiles formas de erosión eólica en los cultivos esteparios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90166','espacio','Valle de la riera de Alaminos y lomas alcarreñas','Pequeña cuenca erosiva flanqueada por muelas de cumbre plana compuestas por calizas lacustres del Mioceno. Ofrece una panorámica típica de la Alcarria con fuertes contrastes entre los páramos desnudos y las laderas cubiertas de coscojar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90167','espacio','La Muela de Alarilla','Colosal e icónico cerro testigo de morfología tabular perfecta que se eleva de forma abrupta casi 300 metros sobre la llanura del río Henares. Su meseta superior caliza y sus vertiginosas laderas margosas flanquean una de las estructuras geomorfológicas más nítidas de la meseta norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90168','espacio','Sierra de Altomira y meandros del río Tajo','Cresta tectónica caliza de vertientes escarpadas que aprisiona el curso del río Tajo antes de remansarse en el embalse de Bolarque. El paisaje destaca por los farallones rocosos que caen sobre las aguas, combinando el verde de los pinares con los tonos turquesa del agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90169','espacio','Valle del arroyo de San Andrés','Depresión erosiva de formas suaves labrada sobre materiales arcillosos y margosos de la Alcarria Baja. Ofrece una estampa contemplativa dominada por la geometría de las vertientes onduladas y la vegetación arbustiva mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90831','espacio','Valle del río Bornova y Sierra de Pela','Entorno subpirenaico caracterizado por el encajonamiento del río Bornova entre estratos de calizas jurásicas y areniscas. Destaca por sus formaciones de laderas boscosas de rebollo y la pureza visual de sus cursos de agua de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90170','espacio','Hoya de Alcocer y riberas del embalse de Entrepeñas','Depresión kárstica y aluvial donde los relieves calizos se hunden.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90171','espacio','Formaciones de cárcavas y peñas calizas','Paisaje quebrado caracterizado por afloramientos rocosos erosionados que emergen como agujas aisladas sobre laderas arcillosas. Destaca por los procesos de erosión de escorrentía que generan un relieve abarrancado de gran interés cromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90172','espacio','Parameras de Alcolea y pinares de pino albar','Altiplano elevado a más de 1.200 metros de altitud que marca la divisoria de aguas entre las cuencas del Tajo y el Ebro. Presenta un paisaje forestal monótono y puro de Pinus sylvestris asentado sobre costras calizas de la alta paramera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90173','espacio','Sierra de Alcoroches y formaciones de Rodeno','Impresionante relieve montañoso compuesto por areniscas rojas del Buntsandstein que rompen el paisaje calizo dominante. Alberga colosales bloques de piedra erosionados, laberintos minerales rojizos y densos bosques de pino silvestre mezclados con rebollares de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90174','espacio','Valle del arroyo de Matayeguas','Barranco alcarreño labrado sobre arcillas y yesos con perfiles de laderas suaves sujetas a erosión laminar. Ofrece horizontes despejados donde se aprecian las distintas bandas sedimentarias del Terciario central.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90175','espacio','Hoz del río Mesa','Desfiladero fluvial angosto excavado de forma sinuosa sobre calizas jurásicas del Sistema Ibérico. Las paredes rocosas verticales albergan importantes colonias de aves rupícolas y están flanqueadas por una ribera prístina de sauces y chopos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90176','espacio','Valle del río San Andrés y muelas calizas','Paisaje típico de la Alcarria Media con laderas de fuerte pendiente que conectan los páramos con el fondo aluvial del valle. Destaca por la nitidez geológica de las muelas y la vegetación esclerófila asociada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90177','espacio','Lomas arcillosas de la Alcarria meridional','Terreno de suaves colinas arcillosas erosionadas por escorrentías temporales sin grandes accidentes geográficos. Destaca por las tonalidades cambiantes de la tierra labrada y los pequeños encinares fragmentados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90178','espacio','Cabecera del río Badiel y llanuras calcáreas','Altiplano calizo donde nacen los primeros cursos de agua que romperán el páramo hacia la cuenca del Henares. Ofrece horizontes limpios de alta meseta y vegetación esteparia arbustiva bien conservada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90179','espacio','Tajos de Almoguera (Río Tajo)','Tramo donde el río Tajo corta de forma abrupta las estructuras calizas de la Alcarria Baja, formando escarpes y cortados verticales de consideración geológica. La masa de agua discurre encajada entre encinares termófilos y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90180','espacio','Mar de Castilla y Embalse de Bolarque','Paraje de confluencia del Tajo y el Guadiela encajonado en un cañón kárstico de calizas cretácicas de gran impacto estético. Las colosales masas forestales de pino carrasco cubren las laderas verticales que mueren en aguas de un color verde esmeralda permanente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90181','espacio','Miradores naturales del embalse de Entrepeñas y pinares','Cornisa caliza natural alcarreña suspendida a gran altura sobre la lámina de agua de Entrepeñas. Las vertientes escarpadas están cubiertas por una masa forestal continua de pino carrasco y encinas que tapiza el relieve quebrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90182','espacio','Llanura aluvial del río Henares','Espacio estrictamente horizontal compuesto por terrazas fluviales cuaternarias de limos, arenas y gravas. El interés es limitado a la amplitud del horizonte de la campiña baja de Guadalajara.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90183','espacio','Sierra de Alustante y parameras de alta cota','Paisaje ibérico de alta montaña que roza los 1.400 metros de altitud, caracterizado por extensas formaciones de lapiaces, dolinas y campos de piazas kársticas. Alberga masas forestales prístinas de pino albar y sabinas rastreras adaptadas al frío extremo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19031','espacio','Valle del río Cañamares y Sierra de Pela','Valle de montaña encajonado entre lomas calizas y canchales de ladera en las estribaciones del Sistema Ibérico. Destaca por la transparencia de las aguas del río y las formaciones boscosas mixtas de quejigo y encina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19032','espacio','Hoz del río Tajuña y Torca de las Cuevas','Espectacular cañón calcáreo labrado por el Tajuña en la roca jurásica, con imponentes cortados verticales de color gris y rojizo. Presenta interesantes fenómenos kársticos como grandes dolinas de colapso y cuevas naturales en las paredes del desfiladero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19033','espacio','Pinares del Ducado y formaciones de areniscas','Extensa y compacta masa forestal de pino resinero asentada sobre un relieve ondulado de arenas y conglomerados triásicos. Destaca por la pureza del entorno forestal y las texturas arenosas rojizas del suelo subyacente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19034','espacio','Paraderas del pedregal y formaciones detríticas','Paisaje liso elevado interrumpido por acumulaciones de cantos y bloques cuarcíticos de origen aluvial y periglacial (canchales basales). Ofrece una panorámica de la llanura molinesa con texturas pedregosas singulares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19036','espacio','Vega del río Tajuña y escarpes de arcilla','Tramo final del Tajuña guadalajareño donde el valle se ensancha mostrando amplias terrazas aluviales flanqueadas por colinas arcillosas erosionadas. Destaca por el contraste cromático estacional de la vega y las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19037','espacio','Piedemonte de la Sierra de Ayllón y lomas de quejigo','Espacio de transición geológica entre las pizarras del Sistema Central y las calizas de la meseta. Presenta un relieve ondulado cubierto de densas formaciones de quejigar y encinar bien conservadas con pequeños barrancos estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19038','espacio','Hoz del río Arbeteta y formación de El Mambrú','Espectacular paisaje kárstico integrado en el Parque Natural del Alto Tajo, caracterizado por callejones de roca, monolitos calizos modelados por el viento (como la roca del Mambrú) y desfiladeros estrechos rodeados de sabinas y pinos laricios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19039','espacio','Valle del río Badiel y escarpes alcarreños','Profundo corte erosivo que rompe el páramo calizo, dejando al descubierto potentes perfiles de margas y arcillas en las laderas. Ofrece una vista nítida del retroceso de las vertientes alcarreñas por la acción del agua fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19040','espacio','Hundido de Armallones (Río Tajo)','Uno de los cañones más monumentales del Parque Natural del Alto Tajo, originado por un colosal colapso kárstico que desplomó las paredes del desfiladero sobre el lecho del río. Los gigantescos bloques de piedra caliza, los paredones verticales y las aguas turquesas forman un paisaje sobrecogedor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19041','espacio','Valle medio del Tajuña y cerros testigo','Paisaje alcarreño caracterizado por terrazas aluviales escalonadas y colinas de perfil tabular suavizadas por la erosión agrícola. Su interés radica en la contemplación de la morfología del valle fluvial desde los páramos superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19042','espacio','Sierra de Ayllón meridional y arroyo de las Fraguas','Entorno montañoso del Sistema Central compuesto por pizarras paleozoicas y gneis que generan un relieve quebrado de tonos oscuros. Destaca por sus densos jarales, masas de pino silvestre y pequeños cursos de agua cristalina de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19043','espacio','Páramo de Atanzón y barranco del río Ungría','Inmensa llanura calcárea tabular que se corta de forma abrupta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19044','espacio','Peñón de Atienza y cerros volcánicos menores','Promontorio calizo ecorrodado de laderas escarpadas que emerge con fuerza en el paisaje de transición al Sistema Ibérico, flanqueado por pequeños afloramientos de filones basálticos y andesíticos fósiles de gran interés geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19045','espacio','Cortados del río Tajo y umbrías de la Sierra de Altomira','Tramo fluvial encajado entre potentes farallones de roca caliza jurásica con pendientes cubiertas de pinares densos. La lámina de agua de la cola del embalse de Zorita se integra en un relieve abrupto de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19046','espacio','Reserva Ornitológica de las Lagunas de Azuqueca (entorno natural)','Antiguas graveras de la llanura aluvial del río Henares naturalizadas que albergan láminas de agua permanente y vegetación de ribera. Destaca por la observación botánica hidrófila asociada a los depósitos cuaternarios arenosos del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19047','espacio','Confluencia de los ríos Henares y Salado','Espacio aluvial donde convergen ambos cursos de agua, recortando lomas calcáreas y arcillosas. Destaca por sus densas alamedas y por la nítida transición geológica de los materiales sedimentarios del valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19049','espacio','Valle del río Bañuelos y laderas calcáreas','Pequeña depresión fluvial en el somontano del Sistema Ibérico flanqueada por relieves tabulares suaves. El paisaje ofrece horizontes limpios y un lecho de cantos rodados ribeteado por sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19050','espacio','Valle del río Vadillo y escarpes de la Alcarria','Angosto surco erosivo labrado en el páramo que deja al descubierto estratos arcillo-calcáreos en sus vertientes.   Permite contemplar el contraste estacional entre el páramo superior y el fondo de valle húmedo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19051','espacio','Valle del arroyo de la Golosa y muelas de Berninches','Relieve alcarreño típico con muelas calizas de cumbres llanas que delimitan un estrecho valle de laderas pronunciadas. Ofrece un paisaje armónico poblado de encinares y densos matorrales aromáticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19052','espacio','Cañón del río Cañamares y fallas mineras fósiles','Desfiladero escarpado labrado sobre pizarras y calizas jurásicas con impresionantes escarpes tectónicos. Destaca por los fuertes desniveles del terreno y la presencia de vegetación saxícola adaptada a la roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19053','espacio','Valle del río Tajuña y fuentes kársticas de la Alcarria','Amplio valle fluvial excavado de forma monumental en el páramo calcáreo, flanqueado por inmensas muelas y laderas cubiertas de encinar. Destaca por las múltiples surgencias de agua pura que brotan directamente de los acuíferos subterráneos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19054','espacio','Relieves colgados sobre el embalse de Entrepeñas','Cornisa caliza de gran altitud que se rompe en escarpes verticales hacia la fosa del río Tajo. Ofrece una espectacular panorámica contemplativa de la lámina de agua encajada entre densas masas de pino carrasco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19055','espacio','Vega del río Badiel y escarpes arcillosos','Tramo donde el río discurre encajonado entre lomas arcillosas propensas a la erosión laminar y abarrancamientos sutiles. Paisaje de texturas ocres con choperas que acompañan el curso fluvial intermitente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19057','espacio','Vertiente sur del Alto Rey y río Bornova','Entorno alpino del Sistema Central caracterizado por imponentes formaciones de gneis y pizarras que culminan en crestas aserradas. El paisaje destaca por sus brezales, rebollares y la pureza visual de sus arroyos de roca limpia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19058','espacio','Llanura aluvial de la campiña del Henares','Espacio completamente horizontal compuesto por depósitos de gravas y limos del Cuaternario. Su valor contemplativo se reduce a la inmensidad del horizonte limpio típico de la campiña baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19059','espacio','Parameras del Señorío de Molina y Laguna de Campillo','Altiplano calizo de extrema severidad climática que alberga pequeñas depresiones endorreicas estacionales. Destaca por sus texturas de piedra desnuda y la fisonomía esteparia continental de horizontes diáfanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19060','espacio','Macizo del Pico Ocejón y cascadas del aljibe','Espectacular paisaje del Sistema Central dominado por la imponente silueta cónica del Ocejón, compuesta por pizarras negras y gneis. Destaca por las profundas gargantas y saltos de agua encajonados en una umbría de densos robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19061','espacio','Sierra de Pela y nacimientos de arroyos calcáreos','Páramo liso prebético de gran altitud caracterizado por laderas calizas batidas por el viento y campos de lapiaces. Ofrece un paisaje austero y puro de alta montaña con pastizales xerófilos de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19064','espacio','Parameras de la Alcarria Alta','Planicie calcárea elevada y horizontal donde el suelo escasea, dejando al descubierto la costra caliza miocénica. Destaca por la quietud de sus horizontes y sus masas dispersas de encina montana y sabina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19065','espacio','Parque Natural del Hayedo de Tejera Negra y Cañón del río Lillas','Uno de los hayedos más meridionales de Europa, enclavado en un valle de origen glaciar sobre pizarras y areniscas. Las masas de hayas centenarias combinadas con tejos, acebos y abedules configuran una joya botánica y cromática de valor internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19066','espacio','Serra do Paradanta / Cabecera del río Deva','Relieve de media montaña con picos redondeados y vertientes abruptas sobre materiales graníticos y esquistos. Los cursos fluviales altos excavan profundas vaguadas cubiertas de densas carballeiras (robledales) de influencia atlántica pura y piornales de cumbre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19071','espacio','Rampas de la meseta y cárcavas de Valdetorres','Zona de contacto entre la campiña y la sierra caliza con terrenos ondulados de arenas y arcillas. Presenta pequeños procesos de erosión en las laderas que muestran bandas de sedimentación de tonos rojizos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19073','espacio','Valle medio del río Henares','Terrazas fluviales escalonadas que se asientan sobre arcillas miocénicas erosionadas. Paisaje plano de campiña que permite observar la amplitud de la cuenca sedimentaria central.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19074','espacio','Hoz del río Ungría','Hermoso y estrecho valle excavado en las calizas de la Alcarria, flanqueado por escarpadas vertientes cubiertas de densos encinares. El río discurre en el fondo configurando un pasillo húmedo de chopos, sauces y abundante agua cristalina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19075','espacio','Cerros de Castejón y ribera del Henares','Elevaciones margosas que rompen la horizontalidad de la vega del Henares formando lomas escarpadas. Permite contemplar la morfología fluvial de la cuenca media desde pequeños atalayas de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19076','espacio','El Somontano de la Muela e Ibérico molinés','Relieve de transición montañosa con afloramientos calizos jurásicos que generan pequeñas muelas erosionadas. Destaca por sus pastizales de alta montaña y horizontes quebrados limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19078','espacio','Hoya de Castilforte y arroyos alcarreños','Depresión geomorfológica modelada por la disolución de yesos y calizas que crea un relieve ondulado cerrado. Ofrece una interesante panorámica de laderas cubiertas de tomillares y encinas arbustivas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19079','espacio','Hoz del río Gallo y Campiña de Molina','Magnífico desfiladero fluvial donde el río Gallo taja las areniscas rojas del rodeno cregando un paisaje mineral rojizo espectacular. Los farallones rocosos verticales conviven con una densa vegetación de ribera perfectamente conservada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19082','espacio','Valle del arroyo de Centenera y lomas calizas','Pequeño barranco alcarreño labrado en el páramo miocénico con vertientes cubiertas de matorral mediterráneo. Destaca por la nitidez de la estratificación caliza visible en los cortes de la ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19086','espacio','Manantiales del río Cifuentes y muelas calizas','Gran surgencia kárstica en el casco urbano y alrededores donde el agua brota con un caudal colosal a partir de los acuíferos calizos de la Alcarria. El cauce forma cascadas de toba calcárea y balsas de agua cristalina rodeadas de sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19087','espacio','Valle del río Cañamares y lomas arcilleras','Tramo de llanura fluvial encajonado entre suaves colinas de sedimentación terciaria. Permite la contemplación de la vega y de los sutiles perfiles erosivos formados por la escorrentía en las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19088','espacio','Lomas del valle del Henares oriental','Relieve de transición entre la campiña baja y los primeros páramos alcarreños, compuesto por arcillas y cantos rodados. Paisaje abierto de amplios horizontes despejados de vegetación arbórea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19089','espacio','Pinares del Ducado y formaciones de roca caliza','Extenso bosque de pino resinero y laricio asentado sobre una paramera de calizas jurásicas. Ofrece una   estampa forestal pura y continua donde el dosel verde cubre por completo el relieve ondulado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19090','espacio','Cañón del río Arandilla y Bosque de las Sabinas de Cobeta','Paraje del Parque Natural del Alto Tajo con un desfiladero colosal labrado en areniscas rojas y calizas. Alberga uno de los sabinares de sabina albar más antiguos y mejor conservados del Sistema Ibérico, integrado en un paisaje mineral imponente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19091','espacio','Páramo de Cogollor y vertientes del Tajuña','Altiplano calcáreo desprovisto de suelo que cae en fuertes pendientes hacia el valle del Tajuña. Ofrece una panorámica nítida de la fisonomía ruda y desarbolada de los páramos de la Alcarria Alta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19092','espacio','Somontano de la Sierra de Ayllón y escarpes del río Aliendre','Relieve quebrado que marca el límite geológico entre el Sistema Central y la cuenca sedimentaria. Presenta espectaculares cortados calizos del Cretácico y laderas tapizadas de densos encinares mixtos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19095','espacio','Sierra de Alto Rey y pinares de Condemios','Magnífica masa forestal de pino silvestre de alta montaña asentada sobre un relieve de pizarras y gneis. El entorno destaca por su microclima frío, la abundancia de fuentes naturales y la gran pureza de su dosel arbóreo alpino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19096','espacio','Cabecera del río Bornova y Sierra de la Peladilla','Valle de montaña encajonado a más de 1.300 metros de altitud con impresionantes formaciones de   canchales y bloques cuarcíticos. El cauce del Bornova da sus primeros pasos en un entorno prístino de praderas alpinas y pinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19097','espacio','Cañón del río Cañamares inferior','Tramo donde el río se encaja con fuerza abriendo un desfiladero sinuoso entre calizas y areniscas del Triásico. Ofrece interesantes perspectivas de modelado fluvial con marmitas de gigante y lechos pedregosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19098','espacio','Lomas del arroyo de la Vega','Terreno de colinas suaves labradas sobre arcillas miocénicas en la campiña alta de Guadalajara. Presenta un relieve ondulado monótono dominado por procesos de erosión laminar superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19099','espacio','Barranco de la Virgen de la Hoz (Río Gallo)','Monumental desfiladero excavado en areniscas del Buntsandstein (rodeno), caracterizado por colosales monolitos, agujas, murallones de piedra roja y caprichosas formas erosivas que se elevan más de 100 metros en vertical sobre el río Gallo. Una joya geomorfológica de nivel nacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19102','espacio','Rampas de la sierra y dehesa del Cubillo','Espacio de transición compuesto por llanuras elevadas de arenas y cantos rodados cuarcíticos procedentes del desmantelamiento de la sierra. Destaca por sus horizontes limpios cubiertos de encinares aclarados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19107','espacio','Tajos del río Tajo en los límites de Madrid','Cortados arcillo-calcáreos verticales labrados por el río Tajo en el extremo meridional de la provincia. Ofrece   una vista nítida del avance erosivo del río y de las texturas yesíferas de las laderas expuestas al sur.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19108','espacio','Hoz de Durón y cola del embalse de Entrepeñas','Espectacular barranco calizo encajonado de vertientes totalmente verticales que mueren en las aguas del embalse. Presenta interesantes formas kársticas de agrietamiento y una densa cobertura de pino carrasco y romerales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19109','espacio','Sierra de Caldereros y formaciones de areniscas rojas','Cresta montañosa caracterizada por impresionantes afloramientos de areniscas del Triásico que emergen como murallones almenados sobre la paramera molinesa, ofreciendo un paisaje de texturas rugosas muy singular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19110','espacio','Muelas de Escamilla y valles kársticos ciegos','Relieve de alta plataforma caliza con abundantes torcas y depresiones kársticas superficiales que recogen el agua de lluvia. Ofrece un paisaje pétreo y forestal dominado por el quejigar y la encina montana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19112','espacio','Valle del arroyo de Escopete y muelas calizas','Pequeño corte en el páramo alcarreño con vertientes margosas suavizadas por depósitos de ladera. Destaca por sus horizontes tabulares y los parches de monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19113','espacio','Riberas del río Henares y río Aliendre','Zona de vega aluvial donde confluyen ambos cauces sobre terrazas de gravas y limos cuaternarios. Ofrece   una estampa fluvial clásica con amplias saucedas y alamedas que tapizan el lecho plano del valle.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19114','espacio','Valle del río San Andrés y laderas de quejigo','Corte erosivo en la Alcarria Alta flanqueado por muelas calizas con umbrías cubiertas de densas masas de quejigar y encinar, mostrando un paisaje vegetal y geológico muy equilibrado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19115','espacio','Valle del río Mesa y parameras de Establés','Cabecera del río Mesa labrada sobre calizas jurásicas del Sistema Ibérico, formando un valle de montaña encajonado de gran soledad visual, rodeado de sabinares albares adaptados a la alta paramera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19116','espacio','Valle del río Dulce cabecera y parameras','Tramo inicial del río Dulce donde el cauce es aún un sutil arroyo que discurre sobre los materiales calcáreos planos del altiplano, ofreciendo amplias perspectivas de horizontes diáfanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19117','espacio','Terrazas del río Henares y campiña baja','Llanura aluvial estrictamente horizontal de origen cuaternario compuesta por depósitos de arenas y gravas. Ofrece una fisonomía llana de interés contemplativo limitado a la amplitud del cielo mesetario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19118','espacio','Hoz del río Bullones e integraciones del Alto Tajo','Desfiladero kárstico de calizas jurásicas encajonado entre densos pinares de pino laricio y sabinas albares. Ofrece un relieve abrupto de paredes de roca grisácea y una total ausencia de elementos artificiales en el horizonte visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19119','espacio','Valle del río Aliendre y lomas arcilladas','Relieve suave de campiña alta caracterizado por colinas bajas arcillo-arenosas erosionadas por escorrentías temporales, mostrando horizontes rurales limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19120','espacio','Rañas de la campiña alta y encinares de llano','Plataforma elevada compuesta por depósitos de cantos de cuarcita englobados en arcillas rojizas (rañas). Ofrece una vista nítida de estos suelos antiguos colonizados por encinares aclarados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19121','espacio','Valle de la fuente de abajo y muelas de la Alcarria','Depresión erosiva que rompe el páramo miocénico, con vertientes calizas pronunciadas y surgencias de agua kárstica en la base de los estratos permeables. El entorno destaca por la armonía de sus laderas boscosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19124','espacio','Escarpes de la Alcarria meridional sobre el valle del Tajo','Cornisa de calizas lacustres que domina visualmente la cuenca baja del río Tajo, mostrando potentes perfiles geológicos de ladera y procesos de erosión remontante de los arroyos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19125','espacio','Páramo de Gajanejos y barranco del río Badiel','Altiplano calizo horizontal e inhóspito que se corta bruscamente por la acción erosiva de los torrentes que descienden hacia el Badiel, ofreciendo vistas de cortes geológicos limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19126','espacio','Cárcavas del río Torote y arcillas rojas','Terreno quebrado de la campiña de Guadalajara donde las arcillas pliocénicas aparecen intensamente erosionadas en pequeños barrancos y cárcavas de fuertes tonos rojizos y ocres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19127','espacio','Valle del río Sorbe y Sierra de Ayllón oriental','Paisaje montañoso alpino de gran belleza visual, con el río Sorbe encajonado entre laderas de pizarras y cuarcitas cubiertas de frondosos rebollares, pinares de pino silvestre y extensas praderas de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19129','espacio','Sierra de Pela y cañón del río Bornova superior','Desfiladero de montaña excavado en calizas jurásicas y areniscas con laderas escarpadas cubiertas de quejigar y encinar montano, mostrando una geomorfología de gran pureza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19132','espacio','Valle del arroyo de Henche y muelas alcarreñas','Estrecho surco erosivo labrado en el páramo calizo miocénico con vertientes cubiertas de romerales y monte bajo mediterráneo, ofreciendo una estampa paisajística muy característica de la Alcarria Media.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19133','espacio','Vega del río Henares y llanura de inundación','Llanura aluvial del Cuaternario compuesta por limos y arenas fértiles de nulo relieve topográfico, destacando únicamente por las formaciones de alamedas que jalonan el cauce del río Henares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19134','espacio','Sierra de Caldereros y dehesas de Herrería','Entorno montañoso molinés caracterizado por imponentes crestas de areniscas del Triásico y extensas   dehesas de encina centenaria asentadas sobre suelos arenosos rojizos de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19135','espacio','Cañón del río Bornova y filones de gneis','Monumental desfiladero fluvial excavado sobre rocas metamórficas del Paleozoico (gneis y pizarras) de extrema dureza. Las paredes del cañón son verticales, oscuras y ásperas, configurando un paisaje geológico de gran austeridad y fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19138','espacio','El Cerro de Hita','Espectacular cerro testigo cónico y aislado que se eleva de forma monumental sobre la llanura de la campiña. Su cima de calizas lacustres erosionadas y sus laderas margosas concéntricas ofrecen un ejemplo académico de relieve residual de la meseta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19139','espacio','Sierra de Caldereros y crestas de rodeno','Espacio natural dominado por una alineación montañosa de areniscas rojizas erosionadas en formas de torreones y murallas naturales (karst en areniscas), rodeado de sabinares albares y pastizales elevados de alta paramera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19142','espacio','Hoz del río San Andrés y muelas de Hontoba','Profundo y sinuoso encajonamiento fluvial en el páramo de la Alcarria Baja con vertientes de fuertes pendientes tapizadas de pino carrasco y encinares termófilos de gran valor contemplativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19143','espacio','Valle del río Ungría y fuentes de la cornisa caliza','Gran anfiteatro erosivo labrado por el río Ungría en el páramo calizo, mostrando potentes perfiles geológicos y   una densa vegetación de ribera que contrasta con la fisonomía horizontal y desnuda de las muelas superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19145','espacio','Valle del río Océn y pinares montanos','Pequeño valle de montaña enclavado en las parameras ibéricas con laderas calizas cubiertas de pino resinero y encinar de montaña, destacando por su ambiente forestal aislado y silencioso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19146','espacio','Sierra de Ayllón oriental y barranco del río Sorbe','Paisaje montañoso del Sistema Central con relieves escarpados de pizarras negras, canchales cuarcíticos y profundas quebradas por donde corren aguas frías y cristalinas entre robledales maduros de Quercus pyrenaica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19147','espacio','Salto de la Presa de El Atance y cañón del río Salado','Hermoso desfiladero fluvial labrado sobre calizas del Jurásico con cortados verticales donde anidan aves rapaces. El lecho del río Salado presenta formaciones salinas e interesantes perfiles geológicos de estratos replegados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19148','espacio','Cañón del río Tajo y Puente de Tagenza','Uno de los tramos más salvajes y monumentales del Parque Natural del Alto Tajo. El río corre aprisionado entre colosales paredes verticales de roca caliza jurásica de más de 150 metros de altura, con formaciones de tobas, cuevas y densas masas de pino laricio en un estado de conservación prístino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','espacio','Valle del río San Andrés y muela de Hueva','Estructura geomorfológica alcarreña de perfil tabular nítido flanqueada por laderas margosas con procesos   de erosión en cárcavas. Ofrece una vista limpia del modelado de vertientes típico de la Alcarria Baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19151','espacio','Confluencia de los ríos Sorbe y Henares','Amplia llanura aluvial cuaternaria donde confluyen ambos cauces fluviales, aportando grandes depósitos de cantos rodados cuarcíticos. Destaca por sus densas formaciones de alamedas y saucedas de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19152','espacio','Valle del río Calvache y escarpes calcáreos del Tajo','Municipio situado en el extremo sur provincial donde el valle fluvial taja las muelas calizas de la Alcarria Baja creando cortados pronunciados de yesos y calizas con vegetación mediterránea termófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19153','espacio','Pinares del Ducado y formaciones de areniscas del Buntsandstein','Gran masa forestal continua de pino resinero asentada sobre un relieve quebrado de arenas y conglomerados rojizos del Triásico inferior, ofreciendo una visual limpia de gran uniformidad forestal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19154','espacio','Valle del río San Andrés y lomas dolomíticas','Paisaje quebrado caracterizado por el encajonamiento de pequeños arroyos estacionales entre relieves de calizas jurásicas. Presenta laderas cubiertas de densos jarales y pinares que ofrecen una perspectiva íntima de aislamiento visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19155','espacio','Valle del río San Andrés y escarpes de Irueste','Estrecho y profundo barranco labrado en las calizas de la Alcarria Media con vertientes de fuertes pendientes tapizadas de encinas y quejigos en las umbrías, ofreciendo una composición visual de gran recogimiento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19156','espacio','Valle del río Henares y cerro de las Motas','Amplia llanura aluvial flanqueada por cerros testigo y muelas calizas jurásicas que emergen de forma abrupta sobre las terrazas fluviales cuaternarias de limos y gravas, ofreciendo una panorámica geológica muy didáctica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19157','espacio','Valle del río Bornova inferior y lomas arcilladas','Tramo de llanura aluvial donde el río Bornova se ensancha antes de unirse al Henares, flanqueado por colinas bajas arcillo-arenosas erosionadas por escorrentías temporales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19159','espacio','Cañón del río Badiel y escarpes de Ledanca','Hermoso tramo donde el río Badiel taja las calizas de la Alcarria Alta formando un estrecho desfiladero de laderas pronunciadas cubiertas de encinar y quejigar, con abundantes fuentes naturales en su base.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19160','espacio','Páramo de Loranca y vertientes del Tajuña','Cornisa de calizas lacustres de perfil tabular perfecto que domina el valle medio del río Tajuña, mostrando potentes perfiles geológicos de ladera con procesos de erosión en cárcavas arcillosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19161','espacio','Valle del río Matayeguas y muelas de Lupiana','Profundo encajonamiento fluvial labrado en las calizas de la Alcarria con vertientes de fuertes pendientes cubiertas de densos encinares mixtos y quejigares, mostrando un paisaje vegetal y geológico excelentemente conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19162','espacio','Hoz del río Tajuña superior y pinares de Luzaga','Precioso desfiladero fluvial labrado sobre calizas del Jurásico en el Sistema Ibérico, con paredes verticales grises cubiertas de pino silvestre y encinar de montaña, flanqueando un cauce de aguas cristalinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19163','espacio','Cañón del río Tajuña cabecera y parameras de Luzón','Tramo inicial del Tajuña donde el río excava un profundo cañón de morfología kárstica sobre las calizas jurásicas de la alta paramera, rodeado de sabinares albares y pastizales ibéricos de gran pureza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19165','espacio','Macizo del Pico Ocejón (vertiente oeste) y cañón del río Jaramilla','Espectacular paisaje montañoso del Sistema Central con relieves escarpados de pizarras negras, canchales cuarcíticos y profundas quebradas de montaña por donde corren aguas frías y cristalinas procedentes de las cumbres alpinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19166','espacio','Llanura aluvial del río Burejo y campiña baja','Espacio estrictamente horizontal compuesto por depósitos de arenas, limos y gravas cuaternarias de nulo relieve topográfico, ofreciendo horizontes limpios de la campiña de Guadalajara.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19167','espacio','Llanuras de la campiña alta y rañas de Malaguilla','Plataforma elevada compuesta por depósitos de cantos de cuarcita englobados en arcillas rojizas (rañas), ofreciendo una visual limpia de estos suelos antiguos desprovistos de relieve abrupto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19168','espacio','Parque Natural del Barranco del Río Dulce','Impresionante garganta fluvial excavada sobre calizas y dolomías jurásicas del Sistema Ibérico. Sus cortados rocosos verticales, cuevas marginales y frondosos bosques de galería con sauces y chopos componen una estampa geológica de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19169','espacio','Escarpes del embalse de Entrepeñas y barrancos de yeso','Paisaje quebrado alcarreño donde las estribaciones calizas se hunden hacia la gran masa de agua interior. Destaca por sus cárcavas excavadas sobre materiales   yesíferos y arcillosos que ofrecen fuertes contrastes cromáticos y texturas rugosas bajo el sol.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19170','espacio','Parameras de Maranchón y sabinares continentales','Altiplano calizo de alta cota sometido a un clima severo de montaña interior. Ofrece amplios horizontes visuales limpios, dominados por formaciones vegetales de sabina albar perfectamente adaptadas a los suelos pedregosos y las heladas perennes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19171','espacio','Llanura de inundación de la Campiña del Henares','Espacio estrictamente horizontal compuesto por terrazas fluviales cuaternarias de limos, arenas y arcillas. Su interés paisajístico es bajo, limitado a la contemplación de la inmensidad del llano sedimentario de la Meseta Central.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19172','espacio','Valle alto del río Tajuña y vegas de umbría','Tramo donde el río discurre encajonado entre los relieves tabulares calizos de la Alcarria Alta. Presenta una composición visual armoniosa marcada por el contraste entre los páramos rocosos desnudos y el denso dosel verde de los quejigares de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19175','espacio','Pinares del Ducado y formaciones de Rodeno','Paisaje montañoso caracterizado por potentes afloramientos de areniscas triásicas de color rojizo intenso. Alberga masas forestales prístinas de pino resinero que tapizan un relieve quebrado con bloques de piedra erosionados y canchales silíceos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19176','espacio','Riberas del río Tajo y lomas margosas','Entorno fluvial de la Alcarria Baja donde el río Tajo se abre paso entre depósitos aluviales y colinas   arcillosas. Destaca por la visual de los meandros suaves y la franja de vegetación palustre que acompaña el curso del agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19177','espacio','Valle del río Cañamares y terrazas de grava','Depresión erosiva preibérica modelada sobre depósitos detríticos y conglomerados cuaternarios. Ofrece un paisaje relajado de lomas redondeadas y pequeños cortados fluviales donde se aprecian los estratos de cantos rodados cementados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19178','espacio','Hoz del río Jándula y cañón de las Calzadas','Espectacular desfiladero kárstico integrado en el Parque Natural del Alto Tajo, con colosales murallones de roca caliza y dolomías de más de 100 metros de caída. Aloja una de las formaciones geológicas de callejones rocosos más salvajes e inaccesibles de la provincia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19179','espacio','Vega del río Bornova y terrazas de la campiña','Zona de transición entre la sierra y la cuenca sedimentaria, con extensos llanos de aluvión flanqueados por cerros margosos bajos. El interés estético se centra en los contrastes estacionales de las alamedas asociadas al cauce del agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19181','espacio','Sierra de Pela y nacimientos de arroyos estacionales','Cresta montañosa caliza que marca el límite septentrional de la provincia con pendientes fuertemente escarpadas hacia la meseta norte. Destaca por sus formaciones de canchales calizos y la vegetación de caméfitos adaptada al viento y al frío severo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19182','espacio','Valle del río Jarama y rañas cuarcíticas','Paisaje serrano de transición con imponentes plataformas elevadas de arcilla y cantos rodados de cuarcita que se cortan bruscamente sobre el encajonamiento del río Jarama, ofreciendo una panorámica limpia de la erosión fluvial profunda sobre el relieve antiguo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19184','espacio','Cola del embalse de Buendía y lomas del Guadiela','Entorno geomorfológico dominado por la inundación del valle del río Guadiela entre muelas calizas y laderas margosas. Ofrece una estampa de grandes láminas de agua turquesa encajadas entre relieves cubiertos de pino carrasco y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19183','espacio','Parameras calizas limítrofes con Aragón','Relieve horizontal sobreelevado de origen kárstico compuesto por extensas costras de calizas lacustres. Ofrece horizontes diáfanos extremos con formas singulares de erosión eólica sobre la piedra degradada y pequeños bosquetes de encina montana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19186','espacio','Miradores naturales del Tajuña y muelas calcáreas','Cornisa caliza natural situada en el borde del páramo alcarreño, suspendida sobre el profundo corte del valle del río Tajuña. Permite la contemplación nítida de los perfiles tabulares de las muelas opuestas y los densos quejigares de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19187','espacio','Confluencia de los ríos Henares y Bornova','Promontorio geológico estratégico que ofrece una panorámica espectacular del encuentro de dos valles fluviales. Las laderas muestran potentes taludes arcilloarenosos sujetos a deslizamientos menores y procesos de erosión laminar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19188','espacio','Hoz del río Mesa y cortados del cañón','Tramo del monumental desfiladero del río Mesa con paredes verticales de roca caliza jurásica que muestran líneas de estratificación perfectas. El cauce discurre encajonado en un microclima húmedo que favorece el crecimiento de densas masas de sauces y chopos de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19189','espacio','Terrazas aluviales del Henares y rañas bajas','Paisaje llano característico de la campiña central con sutiles ondulaciones debidas al desgaste de las capas sedimentarias terciarias. Ofrece amplios horizontes visuales limpios de relieve abrupto y pequeñas alamedas fluviales marginales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','espacio','Hoz del río Gallo y formaciones de arenisca roja','Desfiladero fluvial donde el río Gallo corta con meandros encajonados las areniscas triásicas del Buntsandstein. Destaca por las formaciones de torres rocosas, monolitos aislados de color rojizo (rodeno) y los cortados verticales que custodian el cauce cristalino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19191','espacio','Sierra de Ayllón meridional y barrancos de pizarra','Relieve montañoso compuesto por pizarras oscuras paleozoicas que generan laderas de fuertes pendientes y perfiles quebrados. El paisaje destaca por el espeso tapiz de jarales y brezales que colonizan el suelo silíceo y la limpieza de sus arroyos de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19192','espacio','Llanuras de la Alcarria Baja y cerros calizos','Paisaje ondulado marcado por la transición hacia la meseta sur, con muelas erosionadas y colinas de perfil calizo suavizado. Ofrece un interés visual ligado a los fuertes contrastes cromáticos estacionales de la vegetación mediterránea y los suelos arcillosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19193','espacio','Terrazas del río Bornova y campiñas arcillosas','Relieve suave de colinas bajas compuestas por sedimentos terciarios de la cuenca central. Ofrece una estampa típicamente cerealista de formas redondeadas por la erosión hídrica y laminar sin grandes accidentes rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19194','espacio','Valle de la riera de Moratilla y encinares de ladera','Profundo corte erosivo que rompe el páramo alcarreño, dejando al descubierto potentes perfiles de arcillas y calizas en las vertientes. Destaca por albergar masas estables de encinar mediterráneo con madroños en las laderas orientadas al norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','espacio','Hoz de la roca y campos de dolinas de Molina','Entorno kárstico de alta paramera caracterizado por depresiones circulares perfectas originadas por el colapso de acuíferos subterráneos. Cuenta con pequeños desfiladeros de roca caliza gris que rompen de forma abrupta la monotonía del llano elevado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19196','espacio','Valle del río Badiel y escarpes calizos','Valle encajonado de vertientes pronunciadas labrado por el río Badiel en el páramo de la Alcarria Alta. Ofrece una composición visual nítida del avance erosivo fluvial sobre los estratos sedimentarios arcilloso-calcáreos de la muela.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19199','espacio','Hoz del río Tajo y Hundido de Armallones (Acceso este)','Monumental desfiladero de paredes verticales de calizas y dolomías cretácicas que aprisionan el curso del río Tajo en el Parque Natural. Los gigantescos bloques de piedra desprendidos por colapsos geológicos antiguos y las aguas hipertransparentes forman un paisaje sobrecogedor de primer nivel nacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19200','espacio','Cornisa caliza sobre el embalse de Entrepeñas','Altiplano calizo alcarreño suspendido a gran altura que funciona como un mirador geológico natural hacia las ramificaciones del embalse. Las vertientes escarpadas están cubiertas de masas compactas de pino carrasco y encinas adaptadas a los suelos rocosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19201','espacio','Cañón del río Arandilla y Sabinar de Cobeta','Impresionante garganta fluvial labrada en calizas con escarpes verticales sinuosos que cobijan uno de los sabinares de sabina albar más monumentales y antiguos de la Península Ibérica. La combinación de las paredes de piedra gris y los árboles centenarios posee un altísimo valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19202','espacio','Valle del río Salance y lomas arcillosas','Pequeña cuenca erosiva preibérica caracterizada por taludes arcillosos de tonalidades rojizas expuestos a la erosión hídrica. Ofrece una vista nítida de los procesos de abarrancamiento y pequeñas alamedas marginales bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19203','espacio','Sierra de Alto Rey y barrancos de pizarras','Paisaje montañoso del Sistema Central compuesto por pizarras oscuras, gneis y cuarcitas que generan un relieve quebrado y crestas afiladas. Destaca por sus extensos brezales, masas de pino silvestre de montaña y cursos de agua cristalina sobre lecho rocoso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','espacio','Rondas de Orea, ríos de piedra y Peña de la Gallina','Impresionante paisaje de alta montaña ibérica que roza los 1.500 metros de altitud, caracterizado por colosales acumulaciones periglaciares de bloques de cuarcita ordenados en las laderas ("ríos de piedra") [1.3, 1.4]. Alberga densos bosques de pino albar y formaciones rocosas erosionadas de aspecto fantástico enclavadas en la Serranía de Cuenca norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19208','espacio','Embalse de Pálmaces y cañón del río Cañamares','Espacio encajonado donde las aguas del río se remansan entre imponentes cortados calizos y montañas cubiertas de matorral mediterráneo y encinas de ladera. La panorámica de la lámina de agua encajada entre los relieves de la sierra posee una gran potencia visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19209','espacio','Paraderas del Ducado y formaciones detríticas','Altiplano elevado interrumpido por pequeñas lomas de arenas y conglomerados triásicos. Ofrece una panorámica limpia de la llanura molinesa con texturas pedregosas singulares de tonos rojizos dispersos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19210','espacio','Estribaciones de la Sierra de Pela y valle de Salance','Entorno montañoso subpirenaico caracterizado por el encajonamiento de pequeños arroyos entre estratos calizos jurásicos. Destaca por sus canchales de piedra, laderas cubiertas de quejigar y la pureza visual de sus horizontes altos de paramera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','espacio','Azuda de Pareja y escarpes del embalse de Entrepeñas','Humedal artificial naturalizado y grandes cortados calizos que mueren en la lámina de agua de Entrepeñas. Las laderas presentan fuertes pendientes cubiertas de pinares y densos matorrales de romero y tomillo adaptados a los suelos calcáreos expuestos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','espacio','Valle del río Arlés y muelas de la Alcarria Baja','Paisaje caracterizado por el profundo corte erosivo del río Arlés sobre los materiales calizos y margosos de la plataforma alcarreña. Destaca por la armonía visual de sus laderas escalonadas por la erosión diferencial y cubiertas de densas masas de monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19213','espacio','Parameras del Pedregal y canchales de cuarcita','Paisaje horizontal elevado del Señorío de Molina caracterizado por acumulaciones de cantos cuarcíticos de origen periglacial en las bases de los cerros testigo. Ofrece una panorámica de horizontes limpios con texturas minerales de gran singularidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19214','espacio','Muela de Peñalén y cañón del río Tajo','Espectacular plataforma caliza tabular colgada a más de 1.200 metros de altitud con cortados verticales pavorosos de más de 200 metros de caída sobre el río Tajo. Alberga uno de los paisajes kársticos de paramera más salvajes de Europa, cubierto de pinares de pino laricio y sabinas monumentales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19215','espacio','Valle del río San Andrés y cuevas kársticas del páramo','Paisaje típico alcarreño caracterizado por muelas erosionadas y barrancos labrados en calizas y arcillas del Mioceno. Ofrece un gran interés visual por las oquedades naturales abiertas en los farallones rocosas superiores debido a la disolución kárstica superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19216','espacio','Estrecho de Taravilla, cañón del Tajo y farallones rocosos','Impresionante tramo del Parque Natural del Alto Tajo caracterizado por desfiladeros angostos de paredes de roca caliza gris totalmente verticales y monumentales que casi aprisionan al río. Sus aguas de color verde esmeralda hipertransparentes, las cascadas de toba activa y los bosques subalpinos forman un conjunto geomorfológico sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19217','espacio','Hoz del río Peralveche y callejones de roca caliza','Pequeño cañón kárstico de laderas escarpadas con espectculares formaciones de tormos (piedras hongo) y pasadizos labrados en la caliza por la erosión diferencial. El entorno destaca por el silencio visual absoluto y la densidad de sus masas de encina y sabina albar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19218','espacio','Cortados del río Cañamares y peñas calizas','Desfiladero estrecho labrado por el agua en las estribaciones de la sierra con paredes verticales de roca caliza jurásica. Presenta formaciones de tobas calcáreas fósiles y laderas cubiertas de densos jarales y quejigos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19219','espacio','Valle del río Gallo y lomas de caliza gris','Tramo fluvial donde el río Gallo corta de forma suave los estratos calcáreos de la paramera molinesa. Ofrece una estampa de gran armonía visual por la alternancia de pastizales húmedos y pequeños escarpes rocosos coronados por sabinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19220','espacio','Páramo de Pioz y llanuras calcáreas de la Alcarria occidental','Plataforma horizontal elevada compuesta por calizas lacustres neógenas sin apenas accidentes topográficos de consideración. Su interés radica únicamente en la contemplación de horizontes limpios y limpios característicos de la alta meseta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19221','espacio','Sierra de Piqueras y cañón del río Cabrillas','Paisaje montañoso ibérico caracterizado por profundos valles labrados sobre dolomías y areniscas en el límite con Teruel. Alberga masas forestales vírgenes de pino albar, escarpados verticales de gran potencia estética y pequeños arroyos de agua purísima de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19222','espacio','Sierra de Caldereros y formaciones de arenisca','Impresionante cresta montañoso-tectónica compuesta por areniscas rojas del Buntsandstein que emergen de la llanura como gigantescos torreones y agujas de piedra oxidada. El contraste visual entre la roca rojiza y los verdes pastizales basales es de gran singularidad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19223','espacio','Salto de Poveda, laguna de Taravilla y cañón del Tajo','Uno de los puntos focales del Parque Natural del Alto Tajo. Presenta una monumental cascada originada por un antiguo azud abandonado sobre plataformas de toba activa y una laguna kárstica de origen tectónico de aguas hipertransparentes rodeada de colosales cortados de caliza gris.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19224','espacio','Barranco de las fuentes y lomas arcillosas','Relieve suave de la Alcarria Baja compuesto por arenas y arcillas propensas a la erosión laminar por   escorrentía superficial. Destaca por las tonalidades de la tierra labrada y pequeños reductos de matorral mediterráneo aromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19225','espacio','Páramo alto de la campiña oriental.     Description: Meseta tabular horizontal compuesta por costras calizas degradadas que marca la divisoria de aguas con el Henares. Ofrece horizontes diáfanos sin r','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19227','espacio','Vega del río Gallo y cerros testigo de Molina','Llanura aluvial intermontana flanqueada por elevaciones tabulares calizas de cumbres llanas. Ofrece una vista nítida de la sedimentación cuaternaria y la transición hacia las parameras altas del Señorío de Molina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19226','espacio','Sierra de Alto Rey y hayedos relictos de umbría','Relieve montañoso del Sistema Central compuesto por pizarras y gneis con laderas de fuertes pendientes orientadas al norte. Alberga pequeños reductos relictos de haya y densos robledales de rebollo que forman un dosel forestal de gran interés botánico y cromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19228','espacio','Lagunas de Puebla de Beleña','Excepcional complejo lagunar endorreico compuesto por cubetas estacionales sobre la raña cuarcítica del piedemonte de Ayllón. Ofrece un paisaje acuático temporal de gran valor geológico con extensas comunidades vegetales hidrófilas y praderas de carófitos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19229','espacio','Cárcavas rojas de Puebla de Valles y río Jarama','Impresionante conjunto geomorfológico de badlands compuesto por arcillas y conglomerados triásicos de   un color rojo encendido hipererosionados por el agua. Las afiladas crestas, agujas rocosas y chimeneas de hadas contrastan vivamente con el verde de los olivares y jarales marginales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19230','espacio','Llanura cuaternaria de la Campiña Baja','Espacio horizontal monótono compuesto por terrazas sedimentarias del río Henares con suelos arcilloarenosos profundos. Su valor contemplativo es muy limitado debido a la total ausencia de accidentes topográficos significativos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19231','espacio','Sierra de Pela occidental y lomas de quejigo','Relieve montañoso suave compuesto por calizas replegadas y canchales de ladera. Destaca por albergar densas formaciones forestales de quejigar bien conservadas y pequeños barrancos secos con formas de disolución kárstica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19232','espacio','Hoz del río Recuenco y dehesas de sabina monumental','Entorno kárstico colosal integrado en los límites del Alto Tajo, caracterizado por callejones de roca, pasadizos calcáreos y profundas dolinas de colapso. Cuenta con dehesas mixtas de sabina albar y pinos laricios con ejemplares arbóreos centenarios monumentales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19233','espacio','Valle del río Arlés y escarpes de yeso','Corte erosivo en la Alcarria Baja donde el arroyo labra terrazas encajadas entre colinas de arcillas y yesos cristalinos. Ofrece interés visual por los destellos de los cristales de selenita bajo la luz solar en las vertientes desnudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19234','espacio','Hoz del río Jarama y cañón de Bonaval','Espectacular desfiladero fluvial donde el río Jarama corta los estratos calizos del Cretácico antes de adentrarse en la campiña. Presenta cortados rocosos verticales de color gris, cuevas naturales en las paredes y una frondosa ribera de sauces y alisos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19235','espacio','Valle del río Linares y cueva de los Casares (entorno calizo)','Impresionante cañón fluvial labrado sobre areniscas rojas del rodeno y calizas jurásicas que configuran escarpes sinuosos de gran impacto estético. El lecho del río alberga pozas de aguas cristalinas rodeadas de un frondoso bosque de galería.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19237','espacio','Bosque de piedra fósil y formación del rodeno del río Gallo','Paraje geológico de primer orden mundial caracterizado por afloramientos de areniscas rojas con restos vegetales e icnitas del Triásico fosilizados. Ofrece un relieve quebrado de formas de erosión caprichosas con monolitos rojizos integrados entre pinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19238','espacio','Valle del río Regacho y Sierra de Pela','Depresión de montaña encajonada entre lomas calizas y canchales de ladera en el norte provincial. Destaca por la transparencia de las aguas de sus pequeños arroyos de cabecera y las formaciones boscosas mixtas de encina y quejigo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19239','espacio','Plataforma calcárea de la campiña alta','Meseta horizontal compuesta por costras calizas terciarias degradadas que ofrece horizontes diáfanos   limpios de relieve abrupto. Destaca la visual de la vegetación esteparia arbustiva baja adaptada a suelos delgados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19240','espacio','Sierras marginales de Ayllón y barrancos de pizarras','Relieve quebrado del Sistema Central compuesto por pizarras oscuras paleozoicas que generan laderas de fuertes pendientes. El paisaje destaca por el espeso tapiz de jarales y masas estables de encina montana que cubren el relieve.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19241','espacio','Estribaciones de la Sierra de Pela y formaciones calizas','Entorno montañoso subpirenaico caracterizado por el encajonamiento de pequeños arroyos entre estratos calizos jurásicos. Destaca por sus canchales de piedra, laderas de pastizales altos y la pureza visual de sus horizontes de paramera limpia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19242','espacio','Valle del río San Andrés y muelas de Romanones','Paisaje típico alcarreño caracterizado por muelas de cumbre plana y vertientes pronunciadas labradas en arcillas y calizas del Mioceno. Ofrece una vista nítida de los procesos de erosión diferencial y franjas estables de encinar mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19243','espacio','Valle del río Piedra y parameras altas de Molina','Tramo alto del río Piedra donde el cauce discurre sobre un lecho calcáreo encajonado de forma suave entre lomas de caliza gris. Ofrece horizontes diáfanos de alta paramera sometida a intensos procesos de meteorización mecánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19244','espacio','Hoz del río Tajuña y pinares del ducado orientales','Desfiladero fluvial angosto excavado sobre calizas jurásicas con paredones verticales cubiertos de vegetación saxícola. Aloja masas forestales prístinas de pino laricio y encina montana que flanquean un curso de agua cristalino muy estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19245','espacio','Mar de Castilla, embalse de Entrepeñas y peñón de Sacedón','Paisaje dominado por la inundación de la cuenca del Tajo entre imponentes relieves calizos y muelas tabulares. El peñón calizo emerge de forma abrupta ofreciendo una panorámica de amplias láminas de agua turquesa rodeadas de densos pinares de repoblación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19246','espacio','Salinas de Saelices del río Lamader e inyección de yesos del Trias','Excepcional valle de origen diapiro donde afloran yesos rojos y aguas hipersalinas de carácter subterráneo. Ofrece un paisaje austero y blanquecino-rojizo de gran interés mineralógico y geomorfológico con formaciones salinas superficiales únicas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19247','espacio','Valle del río Guadiela y lomas arcillo-calcáreas','Espacio aluvial donde el río Guadiela ensancha su cauce creando llanuras de sedimentación flanqueadas por muelas calizas erosionadas. Ofrece una estampa contemplativa de contrastes cromáticos entre las alamedas y los tonos ocres del relieve alcarreño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19248','espacio','Congosto del río Bornova y peñas calizas','Pequeño estrecho fluvial labrado por el Bornova en la roca caliza antes de su salida a la campiña, con laderas escarpadas cubiertas de densos matorrales de ladera. El cauce ofrece una perspectiva íntima de modelado fluvial con cantos rodados cementados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19250','espacio','Valle del río Regacho y lomas de caliza jurásica','Paisaje quebrado caracterizado por el encajonamiento de pequeños arroyos de cabecera entre relieves calcáreos preibéricos. Presenta laderas cubiertas de densos jarales y encinares de ladera que ofrecen horizontes limpios de montaña baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19251','espacio','Hoz de Saúca y fuentes de la alta paramera','Desfiladero estrecho y sinuoso excavado por el arroyo sobre calizas del Jurásico con cortados verticales menores cubiertos de vegetación rupícola. El entorno destaca por la pureza de sus fuentes que brotan directamente de la roca y la presencia de quejigares de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19252','espacio','Desembocadura del río Guadiela y cañón de Bolarque','Espectacular confluencia fluvial encajonada en un cañón kárstico de calizas cretácicas de gran impacto estético. Las colosales masas forestales de pino carrasco cubren las laderas verticales que mueren de forma abrupta en aguas turquesas del embalse.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19254','espacio','Hoz de Selas y monolitos del rodeno','Espectacular conjunto de monolitos, agujas y callejones minerales de arenisca roja del Buntsandstein esculpidos de forma caprichosa por la erosión eólica y la meteorización química. El contraste cromático entre las rocas oxidadas y los densos pinares de pino resinero es monumental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19901','espacio','Sierra de Ayllón meridional y barranco del río Sorbe','Relieve montañoso del Sistema Central compuesto por pizarras paleozoicas, gneis y cuarcitas que   generan pendientes vertiginosas sobre el encajonamiento absoluto del río Sorbe. Destaca por sus extensos jarales y la espectacularidad de los procesos de erosión fluvial profunda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19255','espacio','Lagunas temporales de Setiles y Peña de la Gitana','Cuenca endorreica situada en la alta paramera que acumula agua en épocas de deshielo sobre un sustrato calcáreo y arcilloso. Ofrece un paisaje estepario severo donde destaca el afloramiento de crestas de arenisca erosionadas por el viento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19256','espacio','Nacimiento del río Salado y lomas del Triásico','Relieve de transición integrado por pequeños valles esculpidos sobre arcillas rojas y yesos que nutren de mineralización al río. La visual destaca por los fuertes contrastes cromáticos de la tierra y los escarpados calizos perimetrales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','espacio','Parque Natural del Barranco del Río Dulce','Espectacular cañón calizo excavado en estratos del Jurásico con colosales escarpes verticales, agujas rocosas y meandros encajonados profundamente. El fondo del valle alberga un bosque de ribera impecable de chopos y fresnos rodeado de cuevas kársticas aéreas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19258','espacio','Valle del arroyo de la Vega y páramos alcarreños','Profunda incisión erosiva que rompe la continuidad de la muela calcárea de la Alcarria Alta. Permite la contemplación nítida de los diferentes estratos geológicos sedimentarios y de la vegetación mediterránea de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19259','espacio','Laguna de Somolinos y Manadero del río Bornova','Laguna perenne de origen kárstico originada por el cierre de un dique de toba calcárea (travertino) a los pies de la Sierra de Pela. Sus aguas hipertransparentes brotan con fuerza directamente de la base de los acantilados de caliza grisácea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19260','espacio','Valle de la riera del Sotillo y dehesas de quejigo','Relieve ondulado de la Alcarria Alta compuesto por arenas silíceas y costras calizas superficiales. El paisaje destaca por la armonía visual de sus formaciones de quejigar y la tranquilidad de sus pequeños cursos de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19261','espacio','Pinares del Ducado y cárcavas del río Padilla','Extensa masa forestal continua de pino resinero asentada sobre un relieve de arenas rojizas y conglomerados del Buntsandstein. Ofrece una fisonomía quebrada de pequeños barrancos arcillosos y un dosel arbóreo limpio y denso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19262','espacio','Ciudad Encantada de Tamajón y cañón del río Jarama','Monumental laberinto kárstico compuesto por tormos, arcos de piedra natural, pasadizos y cuevas esculpidas en dolomías cretácicas. Flanquea el inicio de la Sierra de Ayllón con un extraordinario sabinar albar que crece directamente sobre la roca desnuda.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19263','espacio','Cerros arcillosos del río Badiel','Terreno de colinas bajas de margas y arcillas situado en la campiña alta de Guadalajara. Presenta formas suaves moldeadas por la erosión hídrica superficial con sutiles bandas de coloración ocre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19264','espacio','Laguna de Taravilla y meandros del Tajo','Laguna de alta montaña de origen kárstico alimentada por acuíferos subterráneos, integrada en el Parque Natural del Alto Tajo. La lámina de agua de color verde esmeralda contrasta vivamente con las imponentes muelas dolomíticas circundantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19265','espacio','Parameras de Concha y lapiaces superficiales','Altiplano calizo elevado a más de 1.100 metros sometido a una intensa erosión eólica y crioclástica. Destaca por sus texturas pétreas de caliza gris erosionada y sus llanuras infinitas de carácter estepario helado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19266','espacio','Valle del río Praá y escarpes de la Alcarria Baja','Valle angosto encajonado de forma longitudinal entre dos grandes muelas calizas de cumbres llanas. El relieve muestra potentes taludes arcillosos cubiertos de olivares y monte bajo mediterráneo con perfiles erosivos nítidos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19267','espacio','Sierra de Terzaga y cortados de arenisca roja','Relieve montañoso caracterizado por potentes farallones de areniscas del Triásico que rompen la monotonía caliza del Señorío de Molina. El contraste visual entre la roca oxidada y los densos pinares de pino albar es sobresaliente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19268','espacio','Salinas de Armallá y cañón del río Bullones','Valle de disolución kárstica donde afloran surgencias de agua hipersalina debido a los diapiros de yeso triásicos. Ofrece un paisaje mineral singular de costras blanquecinas que convive con un cañón fluvial calizo muy bien conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19269','espacio','Valle del río Bornova y escarpes de Alcorlo','Tramo donde el río Bornova corta las estructuras del Sistema Ibérico, formando un desfiladero rocoso de calizas jurásicas antes de ensancharse. Ofrece una composición visual de laderas abruptas cubiertas de encinares y quejigares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19271','espacio','Parameras de Molina y ramblas estacionales','Relieve horizontal de alta paramera interrumpido por pequeños cauces secos pedregosos de carácter torrencial. Destaca por la pureza atmosférica y la fisonomía austera de sus amplios horizontes esteparios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19270','espacio','Cerros de la cuenca del río Salado','Paisaje quebrado de lomas y muelas erosionadas compuestas por arcillas, yesos y margas triásicas. Su interés estético radica en las tonalidades cambiantes de la tierra desnuda bajo las diferentes luces del día.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19272','espacio','Sierra de Tordesilos y campos de dolinas','Altiplano calcáreo que presenta pequeños hundimientos circulares del terreno debido al colapso de cavidades kársticas subterráneas. Ofrece un relieve llano elevado colonizado por sabina rastrera y pastizales de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19274','espacio','Páramo de Torija y cabecera del río Badiel','Plataforma calcárea tabular perfecta que define la fisonomía de la Alcarria Alta antes de descender hacia la campiña. Destaca por la horizontalidad absoluta de su horizonte y los sutiles fenómenos de escorrentía en sus bordes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19279','espacio','Valle aluvial del río Badiel','Terreno llano compuesto por sedimentos cuaternarios finos depositados por el curso fluvial. Su interés visual radica en la regularidad horizontal del fondo de la vega y las pequeñas alamedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19278','espacio','Hoz del río Cifuentes y pinares','Pequeño cañón fluvial labrado en roca caliza con vertientes escarpadas tapizadas de pino laricio y sabinas. El cauce, de aguas muy limpias, discurre encajonado ofreciendo una perspectiva íntima de modelado kárstico.   Torrejoncillo del Rey - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19282','espacio','Hoz del río Dulce (cabecera) y parameras de Sigüenza','Tramo inicial donde el río Dulce comienza a excavar la muela caliza, formando pequeños escarpes y cortados donde se asientan encinares montanos. Destaca por la nitidez de la transición entre el páramo y el cañón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19283','espacio','Pinares del Ducado y formaciones de tormos calizos','Extensa masa forestal de pino silvestre asentada sobre relieves kársticos que presentan formaciones de piedras hongo y monolitos rocosos aislados debido a la erosión diferencial en las calizas.   Torremocha de Jiloca - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19285','espacio','Parameras del Señorío de Molina y dehesa de robles','Relieve de alta meseta caliza que alberga un interesante reducto forestal de rebollo y encina adaptado a condiciones climáticas extremas. Ofrece panorámicas de horizontes limpios y texturas pétreas descarnadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19286','espacio','Terrazas del río Henares y lomas margosas','Espacio de transición entre la campiña baja y los páramos, caracterizado por colinas arcillosas sujetas a   erosión laminar. Ofrece una visual despejada del valle medio del Henares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19287','espacio','Laguna de Tortuera y llanura calcárea','Pequeña cuenca endorreica en la alta paramera molinesa que acumula agua estacionalmente sobre un sustrato de calizas lacustres. Paisaje estepario de gran pureza atmosférica y horizontes infinitos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19288','espacio','Hoz del río Jarama y cortados calizos del cretácico','Impresionante desfiladero fluvial donde el río Jarama corta los murallones calcáreos que preceden a la Sierra de Ayllón. Sus paredes verticales de color gris albergan cuevas naturales y vegetación rupícola de gran impacto estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19289','espacio','Sierra de Traíd y pinares del Alto Tajo','Relieve montañoso del Sistema Ibérico compuesto por calizas y areniscas rojas cubiertas por una masa forestal continua de pino laricio y pino silvestre. Destaca por la pureza de sus paisajes boscosos y sus fuentes naturales de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19290','espacio','Mirador del Cid (escarpe del páramo) y muelas','Imponente cornisa caliza natural alcarreña que se interrumpe de forma abrupta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19291','espacio','Cascadas del río Cifuentes y Tetas de Viana','Espectacular tramo urbano-natural donde el río Cifuentes vierte sus aguas al Tajo en forma de monumentales   cascadas de travertino flotante. Al fondo emergen las Tetas de Viana, dos colosales cerros testigo tabulares idénticos de simetría geomorfológica perfecta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19293','espacio','Las Cárcavas de Uceda y cañón del río Jarama','Formidables paredes de arcilla roja intensamente erosionadas por el agua en forma de afiladas agujas, pirámides de tierra y profundas hendiduras. Situadas en el escarpe fluvial del río Jarama, componen un paisaje de badlands de enorme fuerza cromática.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19297','espacio','Valle del arroyo de San Andrés y lomas alcarreñas','Depresión erosiva de formas suaves labrada sobre materiales arcillo-margosos de la Alcarria Baja. Ofrece un paisaje tranquilo caracterizado por las texturas de las vertientes cultivadas y pequeños encinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19298','espacio','Valle del río Badiel y perfiles sedimentarios','Tramo donde el río Badiel excava el páramo alcarreño dejando al descubierto potentes taludes de arcillas y margas. Destaca por la regularidad de sus laderas y los pequeños huertos fluviales asociados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19299','espacio','Valle del río Ungría y cortados calizos','Valle encajonado de gran pureza paisajística con laderas calizas verticales de umbría cubiertas de densos quejigares. Ofrece una composición visual idílica de la fisonomía de los cañones alcarreños.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19300','espacio','Lomas de la campiña alta y arroyos temporales','Relieve ondulado de arenas y arcillas cuaternarias con presencia de encinares fragmentados en las   cumbres. Presenta un paisaje agrario suave sin grandes accidentes geológicos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19301','espacio','Valle del río Tajo y muelas forestales','Tramo fluvial donde el río Tajo discurre encajonado entre potentes estructuras calizas alcarreñas. Las laderas presentan fuertes pendientes cubiertas de pino carrasco y matorral mediterráneo aromático.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19302','espacio','Páramo de Valdegrudas y barrancos arcillosos','Plataforma calcárea tabular interrumpida por la erosión remontante de pequeños arroyos que forman cárcavas arcillosas. Ofrece amplios horizontes visuales sobre la Alcarria Alta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19303','espacio','Valle del río Salado y yeseras del Triásico','Pequeño valle fluvial encajonado entre cerros de arcillas rojas y potentes estratos de yeso cristalino. El interés visual radica en los destellos minerales de las laderas desnudas bajo el sol.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19304','espacio','Rañas de la campiña alta y pinares de repoblación','Plataforma elevada compuesta por depósitos antiguos de cantos de cuarcita englobados en arcillas rojizas (rañas). Ofrece un paisaje liso y despejado de gran interés geomorfológico meseteño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19305','espacio','Escarpes calcáreos de Pontón de la Oliva y río Lozoya','Impresionante conjunto geológico donde el río Lozoya corta los estratos verticales de calizas cretácicas creándose un cañón de paredes totalmente limpias y   desnudas, ideal para la contemplación de estructuras tectónicas replegadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19306','espacio','Valle del río Tajuña y dehesas de quejigo','Valle fluvial encajonado en las calizas alcarreñas que destaca por albergar una de las dehesas forestales de Quercus faginea mejor conservadas de la comarca, flanqueando un cauce de aguas muy limpias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19307','espacio','Hoz del río Jarama y Puente de la Presa','Angosto desfiladero fluvial excavado sobre pizarras y calizas en la transición a la Sierra de Ayllón. Las paredes rocosas son abruptas y salvajes, rodeadas de una densa masa forestal de encinas de montaña y jarales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19308','espacio','Cornisa del Tajuña y surgencias kársticas','Elevado escarpe calizo que domina visualmente el valle del Tajuña. En su base se producen pequeños fenómenos de vertido y fuentes de agua ligadas a la disolución de los acuíferos calcáreos superiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19309','espacio','Paraderas de Valhermoso y sabinares del Alto Tajo','Relieve de alta paramera caliza integrado en el Parque Natural del Alto Tajo, caracterizado por un paisaje abierto dominado por ejemplares centenarios aislados de sabina albar (Juniperus thurifera).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19310','espacio','Cañón del río Tajo y escarpes de las muelas','Impresionante tramo del Parque Natural del Alto Tajo con cortados dolomíticos verticales de más de 100 metros de altura que encierran un río de aguas hipertransparentes color turquesa, rodeado de pinares salvajes de pino laricio.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19311','espacio','Chorreras de Despeñalagua y pico Ocejón','Monumental cascada escalonada con más de 120 metros de caída libre sobre paredes verticales de pizarra negra y cuarcitas en la falda del pico Ocejón. El entorno vegetal de huertos de castaños y jarales es de un impacto contemplativo excepcional.   Viana de Mondéjar - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19317','espacio','Sima de Alcorón y Pozas kársticas del Alto Tajo','Impresionante pozo natural kárstico de caída vertical que desciende de forma monumental hacia los acuíferos subterráneos de la paramera. El exterior presenta un relieve kárstico de lapiaces boscosos cubiertos de pinos y sabinas de gran pureza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19318','espacio','Páramo alcarreño y vertientes del Badiel','Plataforma calcárea elevada que se corta de forma nítida hacia el valle del río Badiel. Ofrece una vista limpia de los procesos de erosión remontante de las laderas arcillosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19322','espacio','Terrazas del río Henares y lomas de margas','Tramo aluvial donde el río Henares labra depósitos de cantos rodados y arenas del Cuaternario. Ofrece horizontes abiertos y diáfanos característicos de la campiña alta de Guadalajara.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19323','espacio','Rañas de la campiña alta y arcillas rojas','Meseta elevada compuesta por antiguos depósitos aluviales de cantos de cuarcita englobados en   matrices de arcilla rojiza. Presenta un paisaje horizontal y austero de gran interés geológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19324','espacio','Hoz del río Mesa y cañón calizo','Espectacular desfiladero fluvial excavado de forma sinuosa sobre calizas jurásicas del Sistema Ibérico. Las monumentales paredes de piedra vertical gris albergan colonias de rapaces y están flanqueadas por una frondosa alameda de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19325','espacio','Rañas de Viñuelas y lomas del Henares','Plataforma de raña compuesta por acumulaciones de cantos rodados cuarcíticos estables sobre suelos arcillosos rojizos. Ofrece horizontes despejados sin relieves abruptos notables en el límite con Madrid.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19326','espacio','Páramo de Alcohete y barrancos alcarreños','Altiplano calizo que se desgasta en sus márgenes debido a la acción erosiva de pequeños arroyos temporales, creando laderas arcillosas suaves cubiertas de encinar fragmentado y coscojar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19327','espacio','Llanura aluvial del río Tajo y muelas del sur','Espacio de vega fluvial flanqueado por las últimas muelas calizas de la Alcarria Baja antes de la provincia de Cuenca. Ofrece horizontes amplios de gran contraste cromático estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19329','espacio','Valle del río San Andrés y fuentes naturales','Pequeño valle encajonado en las calizas alcarreñas donde el afloramiento del nivel freático da origen a fuentes de agua permanentes que nutren una fértil y frondosa ribera de chopos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19330','espacio','Cabecera del río San Andrés y muelas forestales','Punto alto del valle alcarreño flanqueado por cornisas calizas llanas con laderas de fuertes pendientes cubiertas de quejigares de umbría y matorral mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19331','espacio','Terrazas fluviales del río Henares y llanura de inundación','Espacio plano de la campiña baja compuesto por potentes depósitos de gravas y limos cuaternarios transportados por el río Henares. Paisaje estrictamente horizontal de horizontes despejados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19333','espacio','Alto Tajo, Mirador de Zaorejas (escarpe vertical) y cascada de la Escaleruela','Uno de los puntos cumbre del Parque Natural del Alto Tajo. Presenta un colosal cañón dolomítico con paredes verticales de más de 150 metros de caída limpia y la espectacular cascada de la Escaleruela, un salto estacional de toba calcárea activa de una potencia visual sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19335','espacio','Meandro del río Tajo y escarpes calizos','Majestuoso e impecable meandro encajonado que describe el río Tajo abrazando un promontorio rocoso calizo del Terciario inferior. Ofrece una composición visual perfecta de agua limpia, escarpes de roca viva y vegetación de ribera mediterránea.   ¡Objetivo cumplido! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90669','espacio','Macizo de Txindoki y Parque Natural de Aralar','Imponente pirámide caliza del monte Txindoki que emerge de forma monumental sobre pastizales alpinos de montaña. Destaca por la visual contemplativa de sus escarpados de roca caliza grisácea, lapiaces y las densas masas de hayedos que cubren sus vertientes en umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90670','espacio','Valle fluvial del río Oria y lomas de Basarte','Relieve ondulado de colinas bajas compuestas por margas y areniscas donde el río Oria describe un cauce encajonado de carácter prelitoral. Ofrece una estampa armoniosa de verdes praderas atlánticas interrumpidas por pequeños reductos forestales de roble pubescente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90247','espacio','Parque Natural de Pagoeta y Cañón de Erreka','Macizo montañoso prelitoral caracterizado por un relieve calizo y silíceo cubierto por una de las masas de hayedos y robledales atlánticos más densas de la costa vasca. El paisaje destaca por sus arroyos cristalinos encajados y formaciones de tejos relictos de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90248','espacio','Meandros del río Urola y campiña atlántica','Espacio fluvial donde el río Urola pierde velocidad y describe pronunciados meandros encajados sobre sedimentos aluviales y margas. Ofrece una panorámica nítida de la dinámica fluvial cantábrica, con ricos bosques de ribera dominados por alisos y fresnos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90249','espacio','Valle de Salubita y vertientes de la Sierra de Murumendi','Valle encajonado de morfología kárstica en el que el arroyo Ibaieder excava las formaciones calcáreas mesozoicas. Destaca por la contemplación visual de sus laderas escarpadas, cubiertas por un denso manto forestal mixto, y pequeñas oquedades naturales de disolución.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90250','espacio','Confluencia del río Oria y el río Amezketa','Tramo aluvial encajonado en el fondo del valle guipuzcoano, flanqueado por colinas de fuerte pendiente de calizas y esquistos. Destaca por la fuerza visual del flujo hídrico en época de lluvias y la morfología del relieve de transición.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90251','espacio','Canal de piedra de Hernio y vertientes del macizo calcáreo','Relieve abrupto situado en las faldas del macizo de Hernio, caracterizado por paredones calcáreos verticales de color gris y zonas de lapiaces superficiales. El entorno de alta pluviosidad favorece la contemplación de frondosos bosques de umbría y pastizales colgados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20906','espacio','Sierra de Murumendi (vertiente sur) y arroyo de Altzaga','Vertiente de montaña caracterizada por laderas de fuertes pendientes compuestas por pizarras y calizas replegadas. Destaca por sus amplios horizontes sobre la cuenca alta del Oria y las texturas boscosas de sus masas de repoblación combinadas con robledales nativos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90252','espacio','Relieves calizos de Altzo Muño y cuenca del Oria','Pequeña muela caliza y lomas arcillosas que se elevan sobre el corredor fluvial del río Oria. Ofrece una estampa bucólica típicamente atlántica, donde destacan los contrastes lumínicos sobre los relieves quebrados y pequeños encinares cantábricos marginales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90253','espacio','Valle de Arritzaga y circo kárstico de Aralar','Uno de los valles de origen kárstico y glaciar más espectaculares del País Vasco, excavado en las calizas jurásicas del macizo de Aralar. Destaca por sus monumentales escarpes verticales, canchales de piedra, cascadas atronadoras de alta montaña y una quietud visual sobrecogedora.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90254','espacio','Valle de Leitzaran (Biotopo Protegido)','Extraordinario y profundo cañón fluvial labrado sobre materiales paleozoicos (pizarras y areniscas) por las aguas cristalinas del río Leitzaran. Ofrece uno de los bosques de galería y ribera mejor conservados de la provincia, rodeado de laderas forestales de verticalidad salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90255','espacio','Valle del río Deba y cordal de Gorla-Ir鋪o','Entorno quebrado caracterizado por lomas margosas y relieves silíceos con fuertes desniveles topográficos. Permite la contemplación de un denso tapiz vegetal dominado por plantaciones forestales estables que conviven con pequeños rodales de castaños y robles.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90256','espacio','Riberas aluviales del río Oria','Término municipal reducido asentado en el lecho mayor de inundación del río Oria. Presenta una fisonomía llana de sedimentación fluvial de gravas y limos, con un interés visual limitado a las pequeñas formaciones arbóreas ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21001','espacio','Macizo de Zaraia y Embalse de Urkulu','Espectacular cuenca de agua encajada entre las colosales laderas calizas del Parque Natural de AizkorriAratz. Las escarpadas paredes rocosas de la sierra se reflejan   directamente sobre la lámina de agua perenne, componiendo un paisaje de montaña de gran impacto estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90257','espacio','Valle de Asteasu erreka y laderas del monte Hernio','Depresión erosiva encajonada entre los murallones calizos de Hernio y relieves margosos más suaves. Destaca por la pureza visual de sus pequeños riachuelos de cabecera y el espeso manto forestal de hayas y castaños de sus zonas umbrías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20903','espacio','Valle del río Urumea y lomas calcáreas de Santiagomendi','Tramo donde el río Urumea ensancha su lecho aluvial rodeado de pequeñas colinas de margas y calizas. Ofrece una fisonomía de campiña costera con sutiles escarpes rocosos que marcan las terrazas de sedimentación cuaternarias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90258','espacio','Domo de Ataun y Parque Natural de Aralar','Impresionante estructura geomorfológica en forma de pliegue anticlinal vaciado por la erosión, que genera colosales crestas calizas verticales y pasillos rocosos (Kaxeta). Alberga el mayor hayedo sobre roca calcárea de la provincia en un entorno mineral sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21003','espacio','Macizo de Izarraitz y desfiladero del río Urola','Tramo fluvial encajonado donde el río Urola corta las potentes formaciones de roca caliza del Cretácico superior de Izarraitz. Ofrece imponentes farallones rocosos grises cubiertos de encinar cantábrico relicto que desafían la gravedad sobre el lecho del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21004','espacio','Macizo de Izarraitz y cumbre de Erlo','Paisaje kárstico de alta montaña caracterizado por la presencia de grandes dolinas, lapiaces profundos (asoles) y murallones calizos desnudados por la erosión crioclástica. Ofrece amplios horizontes visuales sobre el mar Cantábrico y la cuenca media del Urola desde sus cumbres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21005','espacio','Valle del río Estanda y estribaciones de Murumendi','Zona de transición geológica con relieves ondulados de margas alternados con potentes capas de calizas arenosas. Presenta interés por sus perfiles erosivos de montaña baja y los reductos boscosos mixtos bien conservados en las cabeceras de los arroyos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20020','espacio','Entorno forestal de Illunbe y cuenca del Urrestilla','Paisaje montañoso atlántico dominado por un relieve accidentado de calizas y margas cubierto por una de las masas boscosas mixtas más compactas de la comarca. Ofrece una fisonomía de densas umbrías de hayas y robles con pequeños nacimientos de arroyos prístinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20021','espacio','Valle de Elduaran y laderas del monte Uzturre','Pequeño sector fluvial caracterizado por laderas de fuertes pendientes que caen sobre el arroyo de Elduain en materiales esquistosos. Su valor visual se concentra en el verdor perenne de sus praderas colgadas y la franja de vegetación de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20022','espacio','Poljé de Berastegi y Valle de Plazaola','Extraordinario valle de fondo plano de origen kárstico (poljé) rodeado por imponentes formaciones de areniscas y calizas paleozoicas del macizo de Cinco Villas. Las laderas escarpadas están tapizadas de hayedos y robledales que mueren en el lecho aluvial del río Elduain.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20023','espacio','Valle medio del río Berrobi','Tramo de erosión fluvial encajonado sobre un sustrato de margas y calizas del Cretácico. Presenta interés por la fisonomía quebrada de su relieve de montaña baja y los rodales residuales de bosque mixto atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90696','espacio','Valle colgado de Bidania y depresiones kársticas','Altiplano singular situado a gran altitud, configurado por procesos de disolución kárstica que generan un relieve ondulado con dolinas y sumideros naturales. Ofrece una estampa contemplativa de alta montaña de gran paz visual y horizontes limpios de relieve calizo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21007','espacio','Rasa mareal de Deba a Zumaia (Flysch del Geoparque de la Costa Vasca)','Monumental e internacionalmente reconocido frente costero caracterizado por plataformas de abrasión marina formadas por estratos verticales alternos de calizas y margas (flysch). Sus acantilados verticales, calas de cantos oscuros y crestas rocosas batidas por el Cantábrico componen un espectáculo geológico único.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21008','espacio','Valle del río Ego y crestas de Karakate','Entorno montañoso encajonado sobre pizarras y areniscas con laderas de pendientes vertiginosas. El interés natural se centra en las crestas superiores de los montes limítrofes, desde donde se aprecian las potentes estructuras geológicas replegadas del sector occidental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90697','espacio','Valle de Leitzaran oriental y laderas de Bellokita','Paisaje forestal virgen que limita con el Biotopo Protegido del Leitzaran, compuesto por macizos paleozoicos profundamente erosionados por arroyos de montaña. Destaca por la pureza atmosférica y visual de sus hayedos de umbría y canchales silíceos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20033','espacio','Cordal de Intxorta y cabeceras del río Ego','Relieve elevado de divisorias de aguas caracterizado por crestas calizas y lomas areniscas prepirenaicas. Destaca por la fisonomía de sus pastizales altos rodeados de formaciones de bosque mixto atlántico y densas nieblas que otorgan gran misticismo al paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20032','espacio','Valle del río Deba y karst de Karakate-Mendaro','Tramo donde el río Deba corta estructuras calizas cretácicas originando un valle encajonado de gran potencia erosiva. Las laderas superiores presentan interesantes fenómenos de lapiaces y dolinas cubiertas de encinar cantábrico relicto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20067','espacio','Macizo de Aiako Harria (Peñas de Aya) y Añarbe','Espectacular relieve correspondiente al único macizo plutónico de origen granítico del País Vasco. Presenta crestas afiladas de color oscuro, grandes bloques rocosos meteorizados y profundos barrancos forestales dominados por hayedos y robledales que vierten hacia el embalse de Añarbe.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90698','espacio','Valle de Errezil y paredones de la Sierra de Hernio','Impresionante anfiteatro natural flanqueado por las monumentales e infranqueables paredes verticales de roca caliza del macizo de Hernio. El fondo del valle presenta un   marcado relieve quebrado cubierto de huertos nativos y praderas, de un impacto estético colosal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21009','espacio','Sierra de Zaraia y Parque Natural de Aizkorri-Aratz','Paisaje calcáreo de alta montaña atlántica con imponentes escarpes, canchales de piedra gris y profundas hoyas de disolución kárstica. El entorno boscoso alberga masas puras de hayedos que se aferran a las fracturas tectónicas de la roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90699','espacio','Valle del río Santa Lucía y colinas arcillosas','Relieve ondulado de media montaña caracterizado por materiales flyschoides (margas y areniscas) que generan vertientes suaves cubiertas de pastizales perennes. Destaca por la armonía de su paisaje agrario tradicional integrado en la naturaleza.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90941','espacio','Sierra de Aizkorri septentrional y cuenca del Estanda','Vertientes forestales caracterizadas por fuertes desniveles topográficos sobre pizarras y calizas. Ofrece panorámicas de horizontes limpios cubiertos por masas forestales de pino de Monterrey bien integradas y retazos de robledal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20037','espacio','Faldas de Txindoki y praderas de Aralar','Ubicación privilegiada colgada sobre las faldas calcáreas del macizo de Aralar, ofreciendo una panorámica limpia y colosal del espolón rocoso de Txindoki. Su paisaje se compone de pastizales de alta montaña y pequeños barrancos de cabecera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20907','espacio','Macizo de Erroizpe y barrancos del arroyo Asura','Relieve abrupto y aislado caracterizado por crestas de caliza jurásica que emergen de forma tajante entre densos jarales y robledales de montaña. Ofrece una perspectiva visual salvaje de los valles del Tolosaldea oriental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21010','espacio','Monte San Antón (El Ratón de Getaria) y acantilados marinos','Icónico promontorio calizo unido a tierra por un istmo arenoso, configurando una de las geoformas más singulares del litoral cantábrico. Sus caras norte y oeste presentan abruptos acantilados de flysch batidos de forma violenta por el oleaje marino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20040','espacio','Valle del río Urumea y Peñas de Santa Bárbara','Tramo fluvial flanqueado por escarpes calizos del Cretácico (como el tajo de Santa Bárbara) con interesantes cuevas y oquedades kársticas. El lecho del Urumea discurre rodeado de ricas alisedas y sauces bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20041','espacio','Umbrías del monte Hernio y arroyo Zelai','Vertiente de umbría calcárea con una topografía abrupta rica en surgencias y fuentes naturales temporales. Ofrece una vista nítida de la masa forestal mixta que coloniza los suelos pedregosos basales del macizo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','espacio','Acantilados de Jaizkibel y Cap de Higuer','Imponente alineación montañosa de areniscas eocénicas que cae de forma directa sobre el mar Cantábrico creando acantilados de más de 200 metros. Destaca por las geoformas debidas a la erosión alveolar (taffoni) y la pureza visual de sus ensenadas rocosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20042','espacio','Valle del río Elduaran y lomas de Izaskun','Entorno encajonado en el fondo del valle del Oria, rodeado por colinas margosas de vertientes pronunciadas. Su interés paisajístico radica en los contrastes cromáticos de la campiña húmeda y la vegetación hidrófila riparia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20043','espacio','Estribaciones del Parque Natural de Aizkorri-Aratz','Zona de transición hacia las altas cumbres calcáreas béticas, dominada por valles estrechos labrados sobre areniscas y margas. Alberga frondosos bosques de hayas en sus zonas altas y cursos de agua de montaña hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20044','espacio','Llanura de inundación del río Oria','Pequeño término municipal asentado en una terraza aluvial cuaternaria donde el río Oria ensancha su curso. Destaca por la horizontalidad de sus suelos de sedimentación limosa y la presencia fragmentada de sauces de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21012','espacio','Parque Natural de Aiako Harria, San Marcial y Marismas de Plaiaundi','Extraordinaria confluencia de paisajes que abarca desde los escarpados graníticos paleozoicos de Peñas de Aya hasta el humedal costero estuarino del río Bidasoa. Sus lagunas intermareales y praderas salinas forman un paisaje acuático costero sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20046','espacio','Meandro del río Oria y lomas de Loatzo','Tramo fluvial donde el río Oria describe una amplia curva encajonada entre depósitos cuaternarios y colinas margosas de perfil suave, ofreciendo una muestra nítida de la dinámica de valles fluviales atlánticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20047','espacio','Valle del río Oria y canteras históricas calizas','Relieve quebrado caracterizado por potentes afloramientos de roca caliza del Urgoniano que flanquean el corredor fluvial. Ofrece una vista nítida de los estratos geológicos replegados expuestos por la acción erosiva fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20048','espacio','Vertiente norte del monte Hernio y arroyo de Larraul','Paisaje montañoso caracterizado por laderas calizas de fuerte pendiente cubiertas por retazos de castañares y hayedos de gran valor natural, integrados en un entorno de alta pluviosidad y arroyos de curso rápido.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20902','espacio','Valle medio del río Oria y lomas arcillosas','Cuenca aluvial donde el río Oria se ensancha sobre terrazas sedimentarias cuaternarias antes de su tramo estuarino. Ofrece visuales diáfanas del cauce fluvial flanqueado por sauces y alisos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90700','espacio','Valle del río Agaunza y lomas de Amets','Espacio quebrado de media montaña labrado sobre margocalizas del Cretácico, que ofrece una fisonomía de laderas verdes y pequeños barrancos umbríos con formaciones arbóreas mixtas bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20050','espacio','Cordal de Otsabio y vertientes del río Araxes','Lomas areniscas y calizas elevadas que dominan el valle encajonado del río Araxes. Destaca por la regularidad de sus pendientes boscosas y la quietud de sus paisajes rurales de montaña baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20051','espacio','Macizo de Aizkorri, cabecera del río Urola y Valle de Brinkola','Espectacular cabecera fluvial de alta montaña rodeada por los colosales murallones de roca caliza gris del Parque Natural de Aizkorri-Aratz. Cuenta con impresionantes canchales de piedra, hayedos maduros de umbría y saltos de agua cristalina del Urola primario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20052','espacio','Hoz del río Oria y vertientes calizas','Estrechamiento fluvial donde el río Oria corta estratos de calizas y margas del Cretácico inferior, creando laderas de pendientes acusadas cubiertas de densa vegetación mediterráneo-atlántica mixta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20053','espacio','Vertiente sur del monte Jaizkibel y ensenada de Pasaia','Relieve de fuertes pendientes compuesto por potentes bancos de areniscas eocénicas que descienden de forma monumental hacia la ría de Pasaia. Destaca por sus geoformas erosivas y la densa vegetación de matorral atlántico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20054','espacio','Cañón del río Araxes y escarpes calizos','Angosto y profundo desfiladero fluvial excavado de forma sinuosa sobre calizas jurásicas del macizo de Aralar por el río Araxes. Las imponentes paredes verticales de roca gris albergan vegetación rupícola y están rodeadas de frondosos bosques de galería.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20901','espacio','Sistema Kárstico de Kilimon y valles ciegos','Uno de los conjuntos kársticos más puros y espectaculares de la provincia, caracterizado por valles ciegos, sumideros y la gran surgencia de agua de las fuentes de Kilimon en un relieve calizo de umbrías absolutas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90039','espacio','Acantilados de Saturraran y flysch negro del litoral','Tramo costero occidental caracterizado por impresionantes formaciones de acantilados verticales de flysch negro y las monumentales agujas rocosas de Saturraran batidas por el mar. Ofrece una fisonomía geológica marítima salvaje de gran impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90942','espacio','Valle de Troi y lomas del flysch','Paisaje de media montaña caracterizado por un relieve ondulado sobre areniscas y margas con presencia de pequeños arroyos de cabecera que corren bajo densos bosquetes mixtos de ribera y robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90260','espacio','Parque Natural de Aiako Harria y Valle de Oieleku','Espectacular entorno que alberga las cumbres graníticas paleocristalinas de Peñas de Aya y el idílico paraje de Oieleku, caracterizado por un hayedo trasmocho centenario de atmósfera mística inserto en un relieve quebrado de gran pureza botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20058','espacio','Lomas del Goierri y cuenca del Oria','Denominado el "balcón del Goierri", este relieve tabular elevado ofrece una panorámica limpia de la llanura aluvial y los grandes macizos de la comarca, asentado sobre materiales margosos y areniscas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21014','espacio','Campas de Urbia, Macizo de Aizkorri y Cuevas de Arrikrutz','Uno de los epicentros geomorfológicos y paisajísticos del País Vasco. Alberga las colosales cumbres calizas de Aizkorri, el altiplano de prados alpinos de Urbia suspendido a más de 1.000 metros y el monumental cañón kárstico subterráneo de Arrikrutz con sus galerías gigantescas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90262','espacio','Llanura aluvial del río Oria','Espacio plano de fondo de valle compuesto por sedimentos fluviales cuaternarios de limos y gravas, donde el interés visual se reduce a la dinámica hidrológica del río Oria en su tramo medio.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20905','espacio','Mirador natural de Tolosaldea y relieves de Otsabio','Altiplano calizo elevado que conforma un balcón natural con vistas panorámicas excepcionales sobre la Sierra de Aralar y el valle del Oria, rodeado de pastizales atlánticos altos de gran armonía visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20061','espacio','Estuario del río Oria y acantilados de Talaimendi','Impresionante desembocadura fluvial donde el río Oria rompe las colinas calcáreas prelitorales para fundirse con el mar Cantábrico. El entorno presenta meandros estuarinos, marismas residuales y acantilados areniscos batidos por el oleaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21015','espacio','Fosa tectónica de la Bahía de Pasaia y acantilados del monte Ulia','Prodigio geológico consistente en un puerto natural perfecto originado por una ría encajonada en una estrecha rotura tectónica entre acantilados verticales de areniscas eocénicas de Jaizkibel y Ulia. La fuerza visual del canal de entrada es sobregogedora.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90702','espacio','Cañón del río Deba y cordal de Karakate','Valle encajonado de vertientes escarpadas labrado en materiales volcánico-sedimentarios del Cretácico superior. Ofrece panorámicas de laderas boscosas continuas y pequeños cortados rocosos en las cumbres del cordal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20071','espacio','Hoz del río Araxes y vertientes del monte Uzturre','Tramo donde el río Araxes confluye con el Oria tras tajar imponentes murallones calcáreos. El paisaje destaca por el perfil agudo de la peña caliza de Uzturre y los bosques de umbría que tapizan sus laderas basales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20072','espacio','Macizo de Adarra-Mandoegi y canchales de arenisca','Relieve montañoso caracterizado por cumbres detríticas de areniscas paleozoicas de tonos oscuros que generan un paisaje quebrado de gran pluviosidad, cubierto de densos brezales, jarales atlánticos y turberas de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90703','espacio','Cordal de Irimo y cabecera del río Urola','Laderas de fuertes pendientes pertenecientes al macizo silíceo de Irimo, que ofrece una estampa de montañas atlánticas cubiertas por masas forestales continuas y pequeños arroyos que bajan encajonados hacia el corredor del Urola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20073','espacio','Meandros del río Oria y marismas de Aginaga','Tramo terminal del río Oria caracterizado por un curso divagante con meandros muy estéticos expuestos a las oscilaciones de las mareas. Destaca por la presencia de juncales y pequeños humedales salobres bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21006','espacio','Cuenca del río Deba y macizo de Elosua','Valle intermontano rodeado por elevaciones de origen volcánico y flyschoides del Cretácico. Ofrece un paisaje ondulado perennemente verde con dehesas atlánticas, pinares estables y ricas alisedas que acompañan los cursos fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20075','espacio','Valle del río Oria y vertientes de Amasa.     Description: Valle de sedimentación fluvial limitado por colinas margosas de formas redondeadas por la erosión hídrica. Ofrece una fisonomía de campiña ve','','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('20078','espacio','Valle de Arkaka y Parque Natural de Aralar','Impresionante cabecera de valle de origen kárstico flanqueada por las estribaciones calcáreas de la Sierra de Aralar. Destaca por el nacimiento del río Amundarain, cuyas aguas cristalinas brotan con fuerza entre grandes bloques calizos rodeados de densos hayedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21018','espacio','Biotopo Protegido de Iñurritza y acantilados de Santa Bárbara','Excepcional complejo costero que alberga el sistema dunar más extenso y mejor conservado de la provincia en la desembocadura de la riera de Iñurritza, flanqueado hacia el oeste por acantilados de flysch calizo que caen sobre el Cantábrico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90943','espacio','Paso de San Adrián, Crestones de Aloña y Macizo de Aizkorri','Espectacular cabecera de alta montaña subalpina bajo los colosales paredones de caliza grisácea del macizo de Aizkorri. Alberga el legendario túnel kárstico natural de San Adrián, excavado por la erosión del agua en la roca viva de la cresta de la montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90944','espacio','Relieves de la sierra de Aizkorri norte y arroyo de Lasarte','Paisaje de media montaña atlántica caracterizado por un relieve quebrado sobre areniscas y pizarras con densas masas de bosque mixto e importantes afloramientos de filones minerales ferruginosos degradados de forma natural.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90945','espacio','Valle del río Urola y macizo kárstico de Izarraitz (sur)','Profunda incisión fluvial donde el río Urola excava un valle encajonado rodeado por potentes estructuras calizas ricas en surgencias termales y manantiales mineromedicinales, rodeado de un espeso manto de encinar cantábrico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90946','espacio','Valle del río Asteasu y lomas flyschoides','Relieve de suaves colinas margosas y areniscas terciarias que definen una fisonomía de campiña húmeda tradicional vasca, con pequeños arroyos que discurren bajo el dosel de bosques mixtos atlánticos basales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','espacio','Acantilados de Itzurun y Playa de Flysch (Geoparque de la Costa Vasca)','Uno de los santuarios geológicos más importantes de la Tierra. Sus espectaculares acantilados de flysch exponen de forma continua y vertical millones de años de historia sedimentaria planetaria (incluyendo el límite K-Pg). Las colosales plataformas de abrasión marina que emergen en marea baja son de un impacto estético insuperable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21020','espacio','Monte Beloki y cordal de Samiño','Relieve montañoso silíceo caracterizado por laderas de pendientes acusadas cubiertas por masas forestales continuas de pinos y castaños, que definen la fisonomía del alto corredor fluvial del Urola.   ¡Objetivo cumplido con el máximo rigor! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22003','espacio','Peña de Arias Montano y cañón del río Alájar','Monumental afloramiento calizo y kárstico que emerge de forma abrupta sobre el dosel forestal de la Sierra de Aracena. Sus paredes verticales de piedra gris albergan cuevas naturales y oquedades de disolución, rodeadas por un frondoso bosque mediterráneo de encinas y alcornoques centenarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90456','espacio','Marismas del río Odiel y canales submareales','Espacio estuarino de gran valor geomorfológico integrado en la Reserva de la Biosfera, caracterizado por llanuras de fango intermareales, caños sinuosos y esteros salobres. Ofrece un paisaje acuático de horizontes limpios dominado por comunidades vegetales halófilas de espartinas y salicornias.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','espacio','Rivera de Almonaster y cerro de San Cristóbal','Entorno quebrado de Sierra Morena occidental compuesto por pizarras y rocas volcánicas degradadas de   gran antigüedad geológica. Destaca por sus umbrías de castañares y bosques de galería prístinos donde el agua discurre sobre lechos de cantos rodados oscuros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22002','espacio','Parque Nacional de Doñana, dunas móviles de Asperillo y Marismas del Rocío','Uno de los santuarios ecológicos más importantes de Europa, caracterizado por un colosal sistema de dunas playeras fósiles y móviles que avanzan sobre masas de pinos piñoneros. El paisaje de la marisma arcillosa y los lucios estacionales ofrece una horizontalidad contemplativa absoluta de valor planetario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90457','espacio','Riberas del río Oraque y lomas del Andévalo','Paisaje penillanurero típico de la comarca minera, configurado por el encajonamiento del río Oraque sobre un sustrato de pizarras paleozoicas. Destaca por la contemplación de sus texturas minerales ocres y los densos jarales que tapizan las vertientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','espacio','Gruta de las Maravillas y cerro del Castillo','Excepcional e internacionalmente reconocido complejo kárstico subterráneo excavado por la disolución del agua en calizas del Cámbrico. Ofrece una asombrosa y monumental profusión de formaciones de estalactitas, estalagmitas, coladas y lagos subterráneos de aguas turquesas hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22005','espacio','Paraje Natural de Sierra Pelada y Rivera de Aserrador','Relieve montañoso de la Sierra de Aroche caracterizado por profundos barrancos y escarpes de cuarcitas oscuras. El entorno destaca por su absoluto aislamiento visual y por albergar una de las masas más   continuas y puras de monte bajo mediterráneo y dehesas de alcornoque.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22006','espacio','Paraje Natural Marismas de Isla Cristina y estuario del Guadiana','Impresionante complejo de humedales marinos y marismas de sedimentación cuaternaria formados en la desembocadura del río Guadiana. Ofrece amplios horizontes visuales limpios sobre laberintos de caños fluviales, llanuras salinas e islas fangosas colonizadas por avifauna.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90744','espacio','Ribera de Clarines y lomas de la campiña','Relieve ondulado suave caracterizado por depósitos sedimentarios de arenas y arcillas mio-pliocénicas. El atractivo visual se concentra en el contraste cromático estacional de los cultivos de secano y los pequeños bosquetes mixtos de encinar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90459','espacio','Cañón del río Tinto y dehesas de Berrocal','Uno de los tramos más salvajes y puros del río Tinto, donde el cauce fluye encajonado entre imponentes laderas de pizarras replegadas. Ofrece un espectáculo contemplativo único en el mundo debido a las aguas ácidas de color rojo intenso por los sulfuros metálicos oxidados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90460','espacio','Llanura del Condado y arroyo de la Rocina (cabecera)','Meseta sedimentaria horizontal de arenas finas y limos del Plioceno que marcan la transición hacia las marismas béticas. Permite observar las formas suaves de escorrentía difusa y la vegetación arbustiva mediterránea residual asociada a los arroyos estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90461','espacio','El Corchuelo y complejo lagunar de Bonares','Espacio forestal caracterizado por un relieve suave de arenas eólicas estabilizadas sobre el que se asienta un frondoso bosque mixto de pino piñonero y alcornoque, salpicado por pequeñas depresiones temporales que acumulan agua de lluvia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90462','espacio','Sierra del Judío y lomas del Andévalo occidental','Relieve quebrado de media montaña labrado sobre pizarras paleozoicas que generan vertientes de pendientes pronunciadas. Destaca por sus extensas panorámicas limpias cubiertas por un mar verde continuo de jarales aromáticos y encinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90463','espacio','Ribera de Cala y embalse de la Minilla (cola)','Valle fluvial encajonado en el extremo nororiental de la provincia, rodeado por los relieves de Sierra Morena. Ofrece una estampa contemplativa de aguas tranquilas rodeadas de un denso manto boscoso de quejigos y encinas bien conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90464','espacio','Moron de Calañas y riberas del río Odiel','Formidables afloramientos de rocas volcánicas y diabasas que rompen el relieve penillanurero del Andévalo, creando escarpes y crestas rocosas oscuras desde donde se divisa el curso encajonado y tortuoso del río Odiel.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47031','espacio','Barranco de la Dehesa y escombreras naturales del Tinto','Paisaje de transición geológica caracterizado por la presencia de cárcavas y relieves de intensa erosión sobre materiales ricos en óxidos de hierro. Ofrece una fisonomía desértico-minera de tonos rojizos y amarillos de gran impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90465','espacio','Pantano de Campofrío y dehesas calcícolas','Pequeña cubeta aluvial rodeada de colinas suaves cubiertas por una masa forestal continua de encinar adehesado. Ofrece un paisaje tranquilo de aguas remansadas que reflejan la vegetación mediterránea perenne sobre suelos de pizarras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90466','espacio','Laguna de Cañaveral (manantial natural) y Sierra de la dehesa','Extraordinaria surgencia kárstica de agua purísima que brota de los acuíferos calizos de la vertiente norte serrana, formando una balsa de agua perenne en un entorno de huertos y olivares tradicionales de montaña de gran armonía estética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21021','espacio','Paraje Natural Marismas del Río Piedras y Flecha de El Rompido','Prodigio geomorfológico litoral consistente en una barrera de arena móvil de más de doce kilómetros de longitud que crece paralela a la costa por la deriva litoral. Sus marismas internas, canales y pinares dunares componen un paisaje costero puro de primer orden.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21022','espacio','Valle de umbría del Castaño y pico de los Chorritos','El municipio más elevado de la serranía, enclavado en una impresionante umbría de origen kárstico y pizarras. Alberga uno de los bosques de castaño (Castanea sativa) más frondosos y monumentales de Andalucía, ofreciendo un espectáculo cromático invernal sobresaliente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21030','espacio','Llanura del Condado y arroyo de la Cárcava','Terreno horizontal compuesto por sedimentos arenosos y limos del Plioceno en la transición a las tierras de Doñana. Ofrece un paisaje diáfano de formas suaves   modeladas por la escorrentía estacional y pequeñas masas de encinar disperso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21024','espacio','Rivera de Huelva y gargantas del embalse de Aracena','Espacio donde el río se encajona de forma radical entre dehesas calizas y escarpes rocosos del Cámbrico. Ofrece una composición visual nítida de profundas masas boscosas de encina y alcornoque que flanquean un lecho fluvial de aguas tranquilas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21025','espacio','Nacimiento del río Chanza y Sierra del Pical','Relieve montañoso caracterizado por densos bosques de castaños y extensas dehesas de alcornoque asentadas sobre pizarras de Sierra Morena. Los profundos barrancos forestales de cabecera ofrecen un entorno de aislamiento visual y pureza paisajística.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21026','espacio','Charco Malo y Barranco de la Guijarra','Impresionante garganta fluvial labrada en materiales calizos y pizarras donde el agua corre confinada entre paredones de roca umbría. El arroyo genera pozas de aguas hipertransparentes rodeadas de una selva de galería con helechos y laureles de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21027','espacio','Parameras del norte y dehesa de Cumbres','Paisaje penillanurero elevado caracterizado por un relieve ondulado suave sobre pizarras paleozoicas desmanteladas. Ofrece amplios horizontes visuales cubiertos por un dosel regular de encinar centenario adaptado a la ganadería extensiva.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21028','espacio','Sierra del Viento y riberas del río Múrtigas','Entorno montañoso fronterizo con fuertes pendientes rocosas compuestas por cuarcitas y pizarras oscuras. Destaca por la contemplación visual del río Múrtigas encajonado en un fértil valle de ribera con alisos, fresnos y quejigos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21029','espacio','Sierra de la Bonales y cumbres del norte','Relieve prebético elevado que alcanza las máximas cotas de la provincia sobre terrenos calizos y pizarrosos. Permite la contemplación de un horizonte diáfano de dehesas de montaña alta y valles ganaderos rodeados de crestas rocosas desnudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21031','espacio','Paraje Natural de la Contienda y cañón del río Múrtigas','Impresionante desfiladero fluvial donde el río corta de forma abrupta las estructuras de pizarras y cuarcitas antes de internarse en Portugal. El paisaje destaca por la verticalidad de sus orillas y el bosque mediterráneo de umbría virgen.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21032','espacio','Campiña de Escacena y arroyo de la Vega','Paisaje ondulado suave de tierras arcillosas y calizas lacustres del Mioceno que definen el fin del Condado de Huelva. Ofrece una visual de horizontes limpios con sutiles escorrentías y pequeños bosquetes mediterráneos residuales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21033','espacio','Fuente de los Doce Caños y umbrías del monte del Puerto','Impresionante e histórica surgencia kárstica natural donde afloran las aguas acumuladas en los acuíferos calizos de la Sierra de Aracena. El entorno está dominado por una de las masas forestales más frondosas y maduras de castaños y quejigos de Andalucía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21034','espacio','Valle del río Múrtigas y Rivera de Jabugo','Paisaje fluvial de extraordinaria exuberancia botánica donde el agua perenne riega un densísimo bosque de galería compuesto por alisos, sauces y chopos. Las laderas circundantes presentan un espeso manto de castañares y alcornocales maduros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21035','espacio','Riberas del río Odiel y canales del Alcaide','Tramo donde el río Odiel comienza a ensancharse para formar sus marismas septentrionales sobre sedimentos aluviales. Ofrece una vista diáfana de amplias láminas de agua que fluyen entre masas forestales mixtas de pino piñonero y eucaliptos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21038','espacio','Sierra de Santa Bárbara y dehesas de encinar','Entrada oriental de la sierra caracterizada por colinas calizas y pizarras de formas redondeadas por la erosión antigua. El valor contemplativo reside en la armonía visual de sus extensas dehesas salpicadas de afloramientos rocosos grises.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21039','espacio','Valle de la Umbría y ribera del río Patrás','Término quebrado de la sierra norte caracterizado por profundos barrancos excavados sobre pizarras paleozoicas. Ofrece una panorámica limpia de laderas de fuertes pendientes cubiertas de olivares tradicionales y monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21040','espacio','Marisma de Hinojos y pinares de Torrecuadrada (Doñana)','Sector fundamental del Parque Nacional de Doñana caracterizado por una inmensa y absoluta llanura arcillosa inundable (la marisma). El contraste visual de su   horizonte limpio con las extensas masas forestales de pino piñonero y sabinares litorales es colosal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','espacio','Paraje Natural Marismas del Odiel y Cabezos de Huelva','Monumental complejo estuarino intermareal donde confluyen los ríos Tinto y Odiel formando islas fangosas, caños y esteros salobres. Destacan los Cabezos, formaciones sedimentarias de arenas finas y arcillas pliocénicas que emergen como acantilados interiores.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21042','espacio','Marismas de Isla Cristina y cordón dunar litoral','Complejo de humedales costeros de origen aluvial y marino con una intrincada red de canales submareales e islas de fango. El paisaje ofrece amplios horizontes marinos rodeados de vegetación halófila y densos pinares sobre dunas estabilizadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21043','espacio','Barranco del río Múrtigas y dehesas de la Sierra','Término montañoso asentado sobre pizarras y calizas cambrianas que generan un relieve accidentado de fuertes pendientes. Destaca por sus umbrías boscosas donde se mezclan encinas, alcornoques y pequeños rodales de castaños.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21044','espacio','Marismas del río Piedras y Laguna de El Portil (entorno natural)','Espacio litoral compartido que alberga una red de caños fluviales y llanuras de inundación mareal de sedimentación cuaternaria. Ofrece horizontes limpios de gran valor estético en sus zonas húmedas libres de infraestructuras urbanas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21045','espacio','Valle del arroyo de Linares y lomas de Valdelamar','Uno de los enclaves de montaña mejor conservados de la sierra, ubicado en un valle ciego de origen kárstico rodeado de escarpes de caliza gris. El paisaje destaca por sus huertos tradicionales e imponentes masas de encinar de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21046','espacio','Bosque costero de las Tres Marías y arroyo de la Rocina','Espacio dominado por dunas fósiles estabilizadas de arenas finas sobre las que se asienta un denso pinar de pino piñonero. Ofrece un paisaje vegetal de transición hacia el entorno palustre de Doñana con sutiles escorrentías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21047','espacio','Llanura sedimentaria de la campiña baja','Terreno marcadamente horizontal constituido por limos, arcillas y depósitos aluviales del Plioceno. Su valor contemplativo se reduce a la inmensidad del horizonte llano y las sutiles texturas del suelo labrado estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21048','espacio','Valle de umbría del Alto Múrtigas','Entorno montañoso caracterizado por un relieve sinuoso sobre pizarras y calizas cambrianas de gran pluviosidad. Destaca por albergar frondosas masas boscosas de castaños y un dosel continuo de alcornoque perfectamente conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21049','espacio','Alto Río Tinto y Corta Atalaya (entorno geomorfológico)','Paisaje visualmente único en el mundo con una fisonomía de badlands minerales y laderas intensamente teñidas de rojos, ocres y violetas debido a la oxidación de sulfuros. Las aguas del río discurren de un color rojo denso y translúcido espectacular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21050','espacio','Paraje Natural de las Lagunas de Palos y Moguer y Pino de la Corona','Complejo lagunar costero dunar asentado sobre arenas cuaternarias estabilizadas. La lámina de agua perenne rodeada de carrizales y espadañas conforma una estampa contemplativa de gran nitidez botánica e importancia geomorfológica litoral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21051','espacio','Rivera del Múrtigas y salto de agua del Chanza','Profundo valle aluvial donde el río Múrtigas describe una vega frondosa flanqueada por escarpadas laderas calizas y de pizarra. Ofrece uno de los bosques de galería más limpios y umbríos de la sierra de Aracena.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21052','espacio','Nacimiento del río Tinto y Peña de Hierro','Cabecera fluvial de aguas ácidas donde el río brota de los acuíferos mineros subterráneos con un color rojo violáceo característico. El entorno se compone de montañas de esquistos desmantelados y cárcavas de impactante cromatismo mineral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21053','espacio','Curso medio del río Tinto y escarpes calizos','Tramo donde el cauce del río Tinto se ensancha y esculpe terrazas aluviales sobre un sustrato de calizas fósiles terciarias. Destaca por el contraste estético entre las aguas rojas del río y la vegetación mediterránea de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21054','espacio','Ribera del río Corumbel','Valle suave encajonado sobre arcillas y areniscas del Mioceno terminal en la campiña alta. Presenta interés por el modelado de sus vertientes y pequeños bosquetes residuales de encinar mezclados con monte bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21055','espacio','Estuario del río Tinto y dunas de la ría de Huelva','Espacio de transición marina y fluvial constituido por marismas de sedimentación limosa y restingas de arena costeras. Ofrece una fisonomía acuática limpia de caños y canales intermareales dominados por vegetación halófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21056','espacio','Sierra de Tejada y nacimientos del río Corumbel','Relieve de transición entre la llanura bética y Sierra Morena, caracterizado por colinas abruptas de pizarras y cuarcitas. Ofrece una amplia panorámica visual de dehesas continuas y pequeños barrancos estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21057','espacio','Riberas del río Chanza y dehesas del Andévalo','Espacio fronterizo caracterizado por el encajonamiento fluvial del río Chanza sobre un lecho de pizarras paleozoicas oscuras. Destaca por la regularidad de su relieve penillanurero tapizado de jarales y encinares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21058','espacio','Dehesa de la Alcolea y riberas de la veta del río Guadiana','Relieve ondulado y aserrado típico del Andévalo occidental con potentes afloramientos de esquistos y filones de cuarcita. El paisaje ofrece amplios horizontes visuales limpios cubiertos por un dosel de encinas maduras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21059','espacio','Barranco de la Bañuela y cola del embalse de Aracena','Entorno calizo y pizarroso de media montaña con vertientes suaves que mueren en la lámina de agua permanente del embalse. Ofrece una estampa tranquila de aguas calmas que reflejan dehesas limpias de encinar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21060','espacio','Paraje Natural Enebrales de Punta Umbría y dunas costeras','Extraordinario y virgen complejo costero dunar caracterizado por dunas móviles y fósiles cubiertas por un denso bosque de pinos piñoneros y enebros marítimos relictos (Juniperus macrocarpa), que mueren en la misma orilla del mar de forma espectacular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21061','espacio','Cabecera del arroyo de la Rocina y arenas del Plioceno','Terreno de lomas muy suaves y arenas finas eólicas estabilizadas que alimentan los humedales del entorno de Doñana. Ofrece visuales diáfanas y llanas de vegetación de monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21063','espacio','Lomas del Andévalo meridional y pinar de repoblación','Penillanura caracterizada por un relieve suavemente ondulado sobre pizarras meteorizadas y depósitos detríticos. Su valor estético se centra en la regularidad del horizonte y los intensos jarales que colonizan el suelo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21064','espacio','Marismas del río Tinto y esteros del muelle','Complejo estuarino intermareal compuesto por llanuras de fango, caños sinuosos y vegetación halófila asociada. Ofrece una panorámica de la dinámica mareal y del flujo del río Tinto en sus tramos bajos de sedimentación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21066','espacio','Lomas del Guadiana y dehesas occidentales','Relieve quebrado de media montaña baja con pendientes suaves compuestas por pizarras paleozoicas. Destaca por la uniformidad visual de sus dehesas y las amplias vistas despejadas hacia la cuenca del Guadiana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21065','espacio','Cañón fluvial del río Guadiana','Impresionante tramo donde el río Guadiana se encaja de forma sinuosa entre potentes laderas verticales de pizarras y cuarcitas de gran antigüedad. Ofrece una composición visual majestuosa de la gran lámina de agua confinada por la montaña salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21067','espacio','Bosque de las Letras y chorreón de Joyarancón','Hermoso salto de agua natural de más de 15 metros de caída libre escondido en un barranco kárstico de calizas grises en umbría absoluta. El entorno alberga frondosos bosques de castaños, quejigos y una densa vegetación higrófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21068','espacio','Rivera de la Chanza y lomas de la dehesa boyal','Paisaje de penillanura con sutiles elevaciones cuarcíticas expuestas a erosión antigua en el límite septentrional del Andévalo. Destaca por el dosel forestal continuo de su monte mediterráneo perenne.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21069','espacio','Rivera del Cala y dehesas graníticas del este','Tramo donde el río Cala ejerce de límite provincial, labrando un lecho pedregoso sobre un sustrato donde afloran bloques graníticos redondeados (berrocales) intercalados con densos encinares de dehesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21070','espacio','Riberas del río Odiel y campiña arcillosa','Relieve ondulado de la campiña de Huelva constituido por depósitos arcillo-limosos del Mioceno. Ofrece vistas limpias hacia las llanuras fluviales del Odiel con sutiles escarpes en los márgenes de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21071','espacio','Valle de la Nava y barranco de la dehesa','Uno de los valles de umbría más aislados y espectaculares de la sierra, labrado en materiales calcáreos y pizarras. Alberga un dosel vegetal impenetrable de castaños centenarios y alcornocales maduros en laderas de pendientes vertiginosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21072','espacio','Dehesa de los Machos y riberas del río Odiel','Paisaje penillanurero quebrado con presencia de pizarras y diabasas volcánicas. El atractivo visual se concentra en el avance del monte mediterráneo sobre las laderas que caen hacia el cauce del río Odiel.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21073','espacio','Lomas del litoral y pinar de la dehesa','Relieve de lomas muy suaves compuesto por arenas y gravas pliocénicas que marcan el descenso hacia las marismas del Guadiana. Ofrece horizontes abiertos y diáfanos de matorral atlántico mediterráneo mixtificado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21074','espacio','Llanuras del Condado y arroyos temporales','Meseta sedimentaria horizontal de arcillas y limos miocénicos con formas de relieve suaves labradas por la escorrentía difusa. Destaca por los contrastes de luz sobre la llanura esteparia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21075','espacio','Rivera del Oroque y lomas del Andévalo central','Tramo fluvial encajonado de forma suave sobre pizarras paleozoicas oscuras y jarales densos. Ofrece una fisonomía desértico-mediterránea con horizontes limpios de relieve penillanurero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21076','espacio','Sierra de la Piedra y dehesas del Andévalo occidental','Pequeña cresta montañosa de cuarcitas que rompe la monotonía del relieve llano elevado. Ofrece una panorámica limpia de dehesas continuas de encina que se extienden de manera regular hacia el horizonte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21078','espacio','Barranco del río Odiel y dehesas de Zalamea','Tramo donde el río Odiel labra profundos escarpes y cortados sobre pizarras y materiales volcánicos degradados. El paisaje destaca por la pureza forestal de sus dehesas de alcornoque y la fisonomía quebrada de sus laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21079','espacio','Hoz del río Rivera de Huelva y cortados de Zufre','Espectacular y colosal cañón calizo y de pizarra donde el río fluye confinado entre paredones verticales de roca viva del Carbonífero. El término, coronado por densos encinares de umbría, ofrece una de las vistas de relieve más impactantes del este de la provincia.   ¡Objetivo cumplido! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90749','espacio','Cañón del río Alcanadre y yacimiento de icnitas de la Fondota','Impresionante desfiladero excavado en conglomerados eocénicos y calizas, integrado en el Parque Natural de la Sierra y Cañones de Guara. Ofrece una espectacular fisonomía de mallos, agujas pétreas y cornisas verticales donde las aguas cristalinas del río fluyen encajonadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90750','espacio','Desfiladero de Monclús y río Cinca','Tramo donde el río Cinca corta los estratos calcáreos prebéticos y genera escarpes verticales de gran interés tectónico. El paisaje destaca por los contrastes entre las laderas de margas grises erosionadas y las masas forestales de pino carrasco y encinar montano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90751','espacio','Cañón del río Vero y barranco de Mascún superior','Sector prepirenaico de extraordinaria geomorfología kárstica con espectaculares agujas de piedra, puentes naturales de roca y paredes de caliza colosales. El entorno de Guara ofrece aquí una de las fisonomías minerales más puras, abruptas y estéticas del continente.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90674','espacio','Mallos de Agüero','Monumentales e imponentes formaciones geológicas de conglomerados oligocénicos erosionados en   forma de colosales torreones monolíticos de paredes totalmente verticales y tonos rojizos. Destaca por su monumental impacto visual exento, elevándose de forma dramática sobre el paisaje forestal basal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','espacio','Confluencia del río Cinca y el río Ara y cola del embalse de Mediano','Gran cubeta de sedimentación y erosión prepirenaica donde confluyen de forma majestuosa dos de los ríos más caudalosos del Pirineo aragonés. Ofrece una panorámica limpia de amplias terrazas aluviales de cantos rodados custodiadas por los murallones calcáreos de la Peña Montañesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90752','espacio','Saso de Albalate y riberas de inundación del Cinca','Paisaje plano elevado (saso) compuesto por depósitos de gravas y costras calcáreas cuaternarias que se corta de forma abrupta hacia la vega aluvial baja. Ofrece horizontes diáfanos y limpios esteparios con sutiles escorrentías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90753','espacio','Llanuras monegrinas y barranco de la Val','Terreno horizontal desértico caracterizado por materiales margosos y yesíferos del Mioceno sometidos a una intensa erosión eólica. Ofrece una fisonomía esteparia austera de sutiles ondulaciones arcillosas y texturas blanquecinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90754','espacio','Barranco de la Sosa y escarpes yesíferos de la Litera','Relieve quebrado caracterizado por afloramientos de yeso cristalino y arcillas que generan un relieve abarrancado de tipo badlands. Ofrece un gran interés mineralógico por los destellos del suelo bajo el sol y las caprichosas formas de escorrentía hídrica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90756','espacio','Llanuras de la Hoya de Huesca y depresiones margosas','Espacio estrictamente llano constituido por sedimentos finos arcillo-limosos del Terciario central. Su valor contemplativo se reduce a la inmensidad diáfana del horizonte agrario y los procesos de escorrentía difusa estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90757','espacio','El rincón del Olivar y torrollones de Alberuela','Extraordinarias formaciones de areniscas erosionadas por el viento (torrollones) que emergen de forma aislada en mitad del paisaje llano monegrino como castillos de piedra efímeros. Ofrece un paisaje mineral de gran interés plástico y contrastes cromáticos ocres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90758','espacio','Embalse de Tormos y riberas del río Sotón','Cuenca de agua remansada sobre un relieve suave de arcillas y areniscas terciarias. La amplia lámina de agua perenne ofrece una panorámica de quietud visual rodeada de vegetación perilagunar de carrizos y matorral xerófilo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90759','espacio','Valle del río Botella y terrazas fluviales','Tramo aluvial donde el arroyo labra depósitos de gravas y limos del Cuaternario, creando sutiles escarpes en los márgenes de inundación. Paisaje horizontal de horizontes limpios y despejados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90760','espacio','Clots de Alcampell y lomas de la Litera','Relieve ondulado de margas e incipientes formaciones kársticas superficiales que generan sutiles depresiones endorreicas que acumulan agua de forma intermitente en invierno, rodeadas de una vegetación marcadamente esteparia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90761','espacio','Ripas de Alcolea (Río Cinca)','Colosales acantilados arcillo-arenosos de color rojizo y ocre labrados por la acción erosiva remontante del río Cinca sobre los materiales de la depresión del Ebro, configurando un frente vertical de gran impacto geométrico y visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90762','espacio','Sierra de Alcubierre y San Caprasio','El pulmón verde de los Monegros, caracterizado por una alineación montañosa de calizas lacustres y margas que supera los 800 metros de altitud. Destaca por sus profundos barrancos y la resistencia botánica de sus sabinares albares y pinos carrascos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90763','espacio','Llanura de la Hoya y arroyo de la Isuela','Espacio llano con sutiles ondulaciones debidas al desgaste de las capas sedimentarias del terciario superior. Ofrece horizontes abiertos y despejados sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90764','espacio','Llanura aluvial del río Cinca','Término municipal reducido asentado de forma horizontal sobre los depósitos de gravas y limos del curso bajo del Cinca. Destaca únicamente por la regularidad visual de su llanura de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90765','espacio','Balsa de la Culada y torrollones del Saso','Entorno caracterizado por llanuras elevadas interrumpidas por afloramientos menores de areniscas ecorrodadas en formas suaves y pequeñas lagunas endorreicas temporales de gran interés por su geomorfología desértica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90766','espacio','Saso de la Almunia y riberas del río Cinca','Plataforma elevada de cantos rodados cuaternarios cementados que cae mediante pendientes suaves hacia el cauce fluvial del Cinca. Ofrece amplios horizontes visuales limpios sobre la comarca del Cinca Medio.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90767','espacio','Riberas del río Flumen y lomas arcillosas','Paisaje llano de la comarca de Los Monegros interrumpido por suaves ondulaciones de margas y depósitos aluviales. Ofrece una fisonomía esteparia diáfana donde destacan las texturas del suelo labrado bajo la intensa insolación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90272','espacio','Cañón del río Vero y Estrechos de las Cañatas','Uno de los complejos kársticos más espectaculares de Europa, integrado en el Parque Natural de la Sierra y Cañones de Guara. El río Vero esculpe un abismal desfiladero de paredes calizas verticales, plagado de covachas, puentes de roca naturales y pozas de aguas turquesas hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22025','espacio','Llanuras de la Litera y balsas endorreicas','Relieve horizontal suave constituido por plataformas sedimentarias miocénicas propensas a la erosión eólica. Ofrece amplios horizontes diáfanos rotos por pequeñas depresiones temporales que acumulan agua de lluvia sobre sustratos arcillosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22027','espacio','Sasos de Angüés y barranco de la Guatizalema','Plataformas elevadas cubiertas de cantos rodados cuaternarios que se cortan de forma nítida en taludes arcillosos sobre los cursos fluviales. Destaca por el contraste cromático entre los llanos esteparios y los lechos de ribera.   Anisclo - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22028','espacio','Valle de Zuriza, Foz de Biniés y Parque Natural de los Valles Occidentales','Paisaje pirenaico axial de primer orden con un relieve de modelado glaciar y kárstico salvaje. Alberga colosales murallones calizos, profundos hayedos-abetales relictos y la atronadora garganta de la Foz de Biniés, excavada por el río Veral en paredes totalmente verticales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22029','espacio','Cárcavas del río Guatizalema y cerros testigo','Relieve quebrado en la transición hacia el somontano, caracterizado por escarpes de arenisca y margas erosionadas en forma de badlands. Ofrece una interesante perspectiva geomorfológica de la erosión hídrica en climas semiáridos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22032','espacio','Valle de Lizara y macizo del Bisaurín','Impresionante cabecera de valle alpino dominada por la colosal pirámide calcárea del pico Bisaurín. Ofrece canchales vertiginosos, lapiaces profundos y praderas de alta montaña salpicadas de surgencias de agua helada procedentes del deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22035','espacio','Desfiladero de Escales y laderas del río Noguera Ribagorzana','Tramo donde el río taja los murallones de calizas mesozoicas del Prepirineo oriental, creando un cañón angosto de gran envergadura geológica. Las paredes rocosas   desafían la gravedad rodeadas de quejigares y robledales de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22036','espacio','Terrazas fluviales del río Guatizalema','Espacio estrictamente horizontal compuesto por llanuras de sedimentación aluvial del Cuaternario. Su interés visual radica en la regularidad geométrica del horizonte y las franjas fragmentadas de sauces que acompañan el cauce.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22037','espacio','Sierra de Gratal, Embalse de Arguis y Foz de San Julián','Espectacular entrada natural al Pirineo marcada por el sinclinal colgado de Gratal y sus farallones de caliza jurásica. La lámina de agua de montaña queda encajada de forma monumental bajo paredes de roca gris colonizadas por densos pinares de pino silvestre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22039','espacio','Riberas del río Gállego y estribaciones de la Sierra de Loarre','Entorno prepirenaico de relieve ondulado caracterizado por potentes estratos de conglomerados y areniscas. Ofrece amplias panorámicas limpias hacia el cauce ancho y pedregoso del río Gállego y los densos encinares montanos que tapizan las faldas de la sierra.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22040','espacio','Barranco de Alins y peñas calizas de la Litera','Relieve quebrado prepirenaico que destaca por sus angostos pasos e incipientes hoces labradas en calizas. Ofrece una estampa contemplativa de umbría y aislamiento visual dominada por una densa vegetación esclerófila y encinas de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22041','espacio','El Peñón de Azara y escarpes de arenisca','Formidable muela de arenisca ecorrodada que destaca de forma exenta sobre las planicies arcillosas del somontano. Permite observar los procesos de meteorización alveolar causados por el viento sobre los estratos rocosos terciarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22042','espacio','Barranco del Fondón y torrollones calizos','Paisaje caracterizado por la presencia de pequeños torrollones (monolitos de arenisca) y estrechos canales excavados por torrentes estacionales. Muestra un atractivo contraste entre las tierras desnudas de color ocre y el monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22043','espacio','Gargantas del río Reguero y lomas de la Litera alta','Relieve prepirenaico quebrado sobre arcillas y calizas donde el agua ha labrado pequeños barrancos encajonados. Presenta interés por sus perfiles sedimentarios y la tranquilidad visual de sus densas masas de encinar y quejigo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22044','espacio','Vertiente sur de la Sierra de San Juan de la Peña','Impresionante alineación montañosa de colosales conglomerados oligocénicos erosionados en viseras y murallones colgantes de gran impacto estético. Sus umbrías albergan densos bosques mixtos de pinos, hayas y acebos en un estado de conservación impecable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22045','espacio','Desfiladero del río Molino y cueva de Salgá','Angosto cañón labrado sobre calizas del Cretácico con paredes verticales y fenómenos kársticos notables como cavidades de disolución y manantiales. El entorno ofrece una perspectiva íntima de aislamiento mineral de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22046','espacio','Ripas de Ballobar (Río Alcanadre)','Colosales escarpes arcillosos y margosos que caen en vertical sobre el lecho aluvial del río Alcanadre en su tramo bajo. La espectacular combinación geomorfológica de badlands áridos de tonos rojizos y la frondosa ribera verde de chopos posee una gran potencia plástica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22047','espacio','Planicies del río Isuela y lomas de la Hoya','Relieve horizontal suave de la Hoya de Huesca compuesto por depósitos arcillo-arenosos del Terciario superior sin grandes accidentes. Destaca por la amplitud de sus horizontes despejados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22048','espacio','Terrazas del río Vero y lomas arcillosas del somontano','Cuenca de sedimentación fluvial donde el río Vero ensancha su curso describiendo amplios meandros sobre terrazas cuaternarias de cantos rodados y limos. Ofrece visuales diáfanas y de contraste con las colinas circundantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22049','espacio','Valle del río Flumen y sasos erosionados','Tramo donde el río Flumen excava terrazas aluviales dejando taludes arcillosos suaves expuestos a la erosión laminar. Ofrece una fisonomía esteparia tranquila con vegetación arbustiva mediterránea residual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22050','espacio','Barranco de la Clamor y lomas del somontano','Pequeño valle erosivo de formas redondeadas labrado sobre margas y arcillas terciarias. Su interés visual radica en la geometría de sus vertientes y en los pequeños encinares fragmentados que coronan los relieves.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22051','espacio','Cañón del río Vero alto y abrigos de Mallata','Cabecera del monumental desfiladero del Vero en pleno Parque Natural de la Sierra y Cañones de Guara. Las paredes de caliza grisácea alcanzan dimensiones colosales, modeladas en cuevas, repisas y abrigos colgados de un valor paisajístico y geológico sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22053','espacio','Sierra de la Carrodilla y barranco de San Medardo','Relieve quebrado caracterizado por crestas calizas jurásicas que emergen con fuerza entre valles interiores de margas. Ofrece una estampa contemplativa de dehesas de encinar montano y afloramientos de roca caliza gris esculpidos por el viento.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','espacio','Parque Natural de Posets-Maladeta, Glaciar del Aneto y Forau de Aigualluts','La máxima expresión de la alta montaña pirenaica española. Alberga los mayores glaciares y cumbres de granito de la cordillera, cascadas monumentales y el Forau de Aigualluts, un colosal sumidero kárstico donde las aguas del deshielo desaparecen de forma atronadora bajo la roca para resurgir en el Valle de Arán.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22246','espacio','Hoz de Obarra (Río Isábena)','Impresionante desfiladero de más de dos kilómetros donde el río Isábena fractura las estructuras de calizas cretácicas abriendo una brecha de paredes verticales y limpias. La transparencia del cauce de montaña y la umbría de sus hayedos basales componen una estampa de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22057','espacio','Valle de Pineta, Circo de Barrosa y nacimiento del río Cinca','Monumental y colosal valle de origen glaciar en U perfectamente esculpido, integrado en el Parque Nacional de Ordesa y Monte Perdido. Destaca por sus paredones   calizos vertiginosos de más de 1.000 metros de caída, cascadas de hielo perennes y praderas alpinas de belleza salvaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22058','espacio','Salto de Bierge, cañón del río Alcanadre y Barranco de Peonera','Uno de los puntos álgidos del Parque de Guara. El Alcanadre labra un desfiladero espectacular de calizas y conglomerados con plataformas de toba activa y pozas de aguas verde esmeralda y turquesa de una transparencia e impacto visual inigualables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22059','espacio','Estrecho de Santa Elena y Valle de Tena inferior','Puerta geológica de entrada al Alto Gállego caracterizada por un monumental estrechamiento kárstico provocado por el avance de antiguos glaciares sobre calizas paleozoicas. Alberga espectaculares cascadas de surgencia y laderas cubiertas de densos bosques mixtos de pino silvestre y hayas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22060','espacio','Embalse de San Salvador y saso de Binaced','Gran masa de agua artificial encajada entre lomas suaves de arcillas y plataformas elevadas de cantos cementados. Ofrece una vista limpia de amplias láminas de agua rodeadas de vegetación hidrófila perilagunar y entornos esteparios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22061','espacio','Sierra de San Quílez y llanuras de la Litera baja','Sutil elevación de areniscas y arcillas miocénicas que rompe de forma muy suave la horizontalidad de la llanura literana. Destaca por sus amplios horizontes visuales limpios orientados hacia las tierras llanas de la depresión del Ebro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22062','espacio','Selva de Conques y faldas del pico Gallinero','Entorno montañoso de la Ribagorza que alberga un espectacular e impenetrable hayedo-abetal de umbría asentado sobre relieves calizos y canchales. Ofrece paisajes forestales de atmósfera alpina y una gran pureza botánica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22063','espacio','Galliguera de Biscarrués (Río Gállego)','Magnífico tramo fluvial donde el río Gállego discurre encajonado entre escarpes de conglomerados rojizos y terrazas cuaternarias. Destaca por la pureza de sus aguas bravas y los densos bosques de ribera mediterráneos de sauces y chopos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22064','espacio','Barranco de la Clamor y cerros de Blecua','Paisaje del somontano oscense caracterizado por lomas arcillosas y escarpes de arenisca terciaria erosionados. Ofrece una panorámica tranquila de formas redondeadas por la escorrentía estacional y pequeños retazos de monte bajo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22066','espacio','Gorga de Boltaña (Río Ara)','Impresionante estrechamiento fluvial donde el río Ara (único gran río virgen del Pirineo) labra pozas gigantescas y canales sobre estratos de calizas y flysch eocénico replegados de forma espectacular. Sus aguas turquesas y la verticalidad de los estratos rocosos forman un conjunto visual monumental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22067','espacio','Bosque de Pegá y barranco de la Mola','Entorno subalpino de alta pluviosidad caracterizado por relieves de calizas y esquistos cubiertos por un densísimo bosque de pino negro y abetos. Ofrece   horizontes limpios de montaña y pequeños nacimientos de arroyos de lecho rocoso cristalino.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22068','espacio','Valle del río Lubierre y umbrías de Borau','Hermoso valle pirenaico encajonado entre estructuras de flysch y calizas de la Jacetania. Destaca por la pureza visual de sus masas de pino silvestre, robledales pubescentes y el flujo cristalino de sus cursos de agua de montaña que corren sobre cantos calcáreos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22069','espacio','Cascada de Sorrosal y Valle de Broto (Río Ara)','Monumental cascada donde el torrente del Sorrosal salta en caída libre más de 80 metros sobre un colosal anfiteatro rocoso de estratos de flysch (alternancia de areniscas y margas) plegados de forma geométrica perfecta. El entorno fluvial del Ara es de una pureza sobregogedora.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22072','espacio','Valle del río Matriz y lomas de la Guarguera','Paisaje prepirenaico de relieve quebrado y aislado, caracterizado por valles excavados sobre margas azules y cubiertos por densas masas de pino silvestre y cajiga. Ofrece un entorno de gran silencio visual y horizontes limpios de montaña baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22074','espacio','Congosto de Ventamillo (Río Ésera) y macizo del Turbón','Impresionante e infranqueable garganta fluvial de más de seis kilómetros donde el río Ésera corta de forma vertical y limpia los murallones calizos cretácicos antes del valle de Benasque. El paisaje se complementa con la presencia monumental y telúrica del macizo calizo del Turbón al fondo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22075','espacio','Barranco de la duna y yeseras de Camporrélls','Espacio caracterizado por un relieve quebrado de arcillas rojas triásicas e importantes afloramientos de yeso cristalino selenítico. Ofrece un gran interés por sus texturas minerales desérticas y los destellos del suelo bajo la luz solar intensa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22076','espacio','Río Aragón y badlands de la Canal','Gran depresión longitudinal prepirenaica excavada sobre margas eocénicas de color gris-azulado (margas de Berdún). Ofrece una panorámica espectacular de llanuras de inundación aluviales flanqueadas por extensos paisajes abarrancados de cárcavas y crestas afiladas de gran interés visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22077','espacio','Balsas de Candasnos y estepas monegrinas','Altiplano semiárido compuesto por calizas lacustres y margas miocénicas con presencia de pequeñas cubetas endorreicas temporales. Ofrece una fisonomía desértica de horizontes infinitos y limpios con una rala vegetación xerófila gipsófila.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22078','espacio','Valle de Canfranc, Ibón de Estanés (entorno calcáreo) y barranco de Ip','Espectacular tajo pirenaico axial labrado por la acción de lenguas glaciares cuaternarias sobre calizas y calcoesquistos. Presenta pendientes vertiginosas de roca desnuda, circos glaciares encajonados y cascadas atronadoras rodeadas de frondosos bosques de pino negro y hayas de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22079','espacio','Laguna de Capdesaso y llanuras del saso','Pequeña cubeta endorreica natural perenne asentada sobre una plataforma elevada de cantos rodados cementados cuaternarios. Ofrece un oasis de agua y   carrizales que destaca con fuerza en mitad de la fisonomía horizontal árida monegrina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22081','espacio','Cañón del río Calcón y Formaciones de la Tejería (Guara)','Sector sur del Parque Natural de Guara caracterizado por impresionantes mallos y agujas de conglomerados de tonos rojizos y ocres modelados por la erosión diferencial. El cauce del río Calcón corre confinado entre paredes escarpadas verticales de gran impacto estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22083','espacio','Sierra de Jubierre y estepas de Castejón','Impresionante paisaje de badlands y tosales (cerros testigo) de calizas y arcillas modelados de forma extrema por el viento y el agua. Ofrece una fisonomía desértica de gran plasticidad geomorfológica con extensos horizontes limpios y secos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22084','espacio','Congosto de Ventamillo (norte) y Valle de Benasque medio','Amplia cubeta aluvial de origen glaciar flanqueada por las colosales vertientes de roca granítica y caliza del Pirineo axial. Destaca por las impresionantes panorámicas diáfanas que ofrece hacia los picos nevados superiores y la pureza visual del río Ésera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22082','espacio','Cerro de la Bella y riberas del río Cinca','Promontorio de arcillas y areniscas terciarias que emerge de forma suave junto a la llanura aluvial del río Cinca en su tramo medio. Ofrece vistas despejadas de la vega fluvial baja y de los depósitos de cantos rodados cuaternarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22085','espacio','Terrazas del río Alcanadre inferior y sasos','Paisaje horizontal semiárido constituido por depósitos aluviales finos y plataformas de cantos cementados. El valor contemplativo reside en la inmensidad limpia del horizonte y los sutiles escarpes margosos marginales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22086','espacio','Valle del río Aragón y umbrías de Castiello','Tramo fluvial de la Jacetania encajonado en un relieve de flysch eocénico con laderas de fuertes pendientes. Destaca por el dosel regular de pino silvestre y cajigas de sus umbrías y el discurrir del ancho cauce pedregoso del río Aragón.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22087','espacio','Cuenca del río Cajigar y relieves margosos','Paisaje quebrado de media montaña baja caracterizado por cárcavas labradas sobre margas grises y areniscas. Ofrece una panorámica de texturas erosionadas que cambian drásticamente de tonalidad con las luces del amanecer y atardecer.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22088','espacio','Acantilados del río Vero inferior','Tramo donde el río Vero labra pequeños cortados y escarpes arcillo-arenosos sobre los materiales del somontano antes de su confluencia con el Cinca. Ofrece una estampa tranquila de ribera flanqueada por alamedas y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22089','espacio','Embalse de Santa Ana (cola) y meandro del río Noguera Ribagorzana','Espectacular entorno fluvial donde las aguas del Noguera Ribagorzana se encajonan entre potentes murallones calizos cretácicos antes de remansarse. Ofrece vistas panorámicas de grandes láminas de agua turquesa confinadas por relieves abruptos salvajes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22094','espacio','Confluencia del río Alcanadre y el río Cinca (entorno geográfico)','Espacio aluvial bajo de la cuenca del Ebro caracterizado por la unión de dos de los flujos fluviales más potentes de la provincia. Ofrece horizontes abiertos y llanos sobre inmensas terrazas de sedimentación de gravas y limos cuaternarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22095','espacio','Sierra de Chía y collado de Sahún','Colosal mole caliza prepirenaica que se eleva exenta configurando un impresionante balcón natural hacia el valle de Benasque. Sus laderas presentan vertiginosos canchales de piedra, lapiaces profundos y extensas masas de hayedos y pino negro en sus cotas altas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22096','espacio','Llanura de la Hoya y balsas estacionales','Terreno plano de sedimentación terciaria fina en las proximidades de la capital oscense. Presenta un relieve estrictamente horizontal de interés visual limitado a la amplitud del cielo y horizontes limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22090','espacio','Barranco de Palomera, río Vero y cañón de Fornocal','Sector oriental del Parque Natural de Guara con espectaculares desfiladeros fluviales labrados de forma sinuosa sobre calizas y conglomerados eocénicos. Destaca   por sus paredones rocosos rojizos repletos de oquedades y covachas naturales de gran valor plástico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22099','espacio','Llanuras aluviales de la Litera baja','Espacio estrictamente llano constituido por limos, arenas y gravas de los sistemas fluviales de la depresión del Ebro. Ofrece una visual despejada y monótona sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22102','espacio','Confluencia del río Ésera y el río Cinca y El Cinca encajonado','Punto geográfico estratégico donde el Ésera vierte sus aguas al Cinca entre los escarpes de arenisca de la sierra de la Carrodilla. Ofrece una composición visual armónica de amplios lechos pedregosos flanqueados por frondosas masas de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22103','espacio','Sierra de la Carrodilla y fuentes de la Fornaca','Cresta montañosa caliza que marca el límite meridional del somontano, caracterizada por lapiaces profundos, dolinas y un relieve kárstico de laderas escarpadas grises cubiertas de encinar mediterráneo y vegetación saxícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22105','espacio','Desfiladero de Fet, Embalse de Canelles y Finestres (Muralla China de Finestres)','Prodigio geológico consistente en una colosal e impresionante doble línea de estratos verticales de caliza cretácica que emergen como una muralla mineral perfecta sobre las aguas turquesas del embalse de Canelles. Un espectáculo contemplativo de nivel internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22106','espacio','Foz de Fago y barranco de Fago','Impresionante desfiladero fluvial labrado por la acción del agua sobre las calizas del Parque Natural de los Valles Occidentales. Presenta paredes de roca vertical de gran estrechez y altura que aprisionan el curso de agua en un microclima de umbría botánica absoluta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22107','espacio','Cañón de Añisclo, Valle de Vió y macizo de Monte Perdido (sur)','Alberga uno de los paisajes geológicos más sobrecogedores del planeta: el Cañón de Añisclo, una abismal y monumental brecha kárstica excavada por el río Bellos con paredes verticales de más de 1.000 metros de altura, tapizadas de musgo, cascadas flotantes y hayedos relictos en umbría total.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22109','espacio','Ribera del río Ara, Peña Canciás y Valle de Solana','Tramo del río Ara caracterizado por un amplio y prístino valle fluvial de montaña con extensas terrazas de cantos rodados calcáreos. Al fondo se eleva la colosal mole caliza de Peña Canciás con sus imponentes murallones y escarpes verticales estriados de gran valor visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22110','espacio','Sierra de la Carrodilla (vertiente oeste) y Ojo de la Fuente','Laderas calcáreas de fuerte pendiente que dominan la llanura media del Cinca, ricas en surgencias de agua kárstica. Ofrece una panorámica nítida de afloramientos rocosos grises combinados con un dosel regular de encinar mediterráneo bien conservado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22111','espacio','Collado de Foradada, Peña Madrid y Sierra de Esdolomada','Espectacular relieve prepirenaico que toma su nombre de una colosal brecha natural ("foradada") en los murallones calizos de la cresta montañosa. Sus laderas   presentan desniveles vertiginosos con impresionantes agujas rocosas, canchales de piedra y densos hayedos de umbría basales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22112','espacio','Meandros del río Cinca bajo, Barranco de la Valcuerna y saso de Fraga','Espectacular tramo final donde el río Cinca corta los potentes materiales yesíferos y arcillosos de la depresión del Ebro, formando gigantescos cortados verticales (ripas) de tonos ocres que contrastan vivamente con el verde del lecho fluvial y su intrincada red de meandros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22113','espacio','Valle de La Fueva y desfiladero de Entremón (Río Cinca)','Gran depresión interior prepirenaica rodeada de murallones calcáreos como la Sierra de Guara y Campanué. En su extremo se sitúa el colosal congosto del Entremón, un abismal desfiladero de paredes verticales de caliza donde el río Cinca fluye encajonado de forma dramática.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22114','espacio','Valle de Chistau, ibón de Plan (Basa de la Mora) y pico Posets','Uno de los valles pirenaicos más puros, aislados y vírgenes. Alberga la Basa de la Mora, una idílica e impresionante laguna de alta montaña de origen glaciar encajada en un colosal circo de paredes calcáreas verticales que se reflejan sobre sus aguas verdes rodeadas de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22115','espacio','Embalse de El Grado y gargantas del río Cinca medio','Cañón fluvial donde las aguas del Cinca se remansan entre imponentes cortados de calizas y margas prebéticas. Ofrece una espectacular panorámica de una inmensa lámina de agua de color turquesa intenso confinada entre laderas forestales de pino carrasco y encina.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','espacio','Congosto de Olvena (Río Ésera) y embalse de Barasona','Impresionante desfiladero fluvial donde el río Ésera taja los murallones calizos de las sierras exteriores de la Ribagorza abriendo una profunda brecha de paredes verticales y limpias de gran impacto estético, antes de fundirse con las aguas de Barasona.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22116','espacio','Llanura del río Flumen y sasos monegrinos','Paisaje horizontal semiárido constituido por depósitos arcillo-limosos del Terciario central. Su valor contemplativo se reduce a la inmensidad diáfana del horizonte estepario y los sutiles modelados de escorrentía difusa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22119','espacio','Riberas del río Gállego bajo y barranco de la Sotón','Tramo fluvial donde el río Gállego discurre sobre amplias terrazas de cantos rodados cuaternarios, flanqueado por pequeños escarpes de arcilla y arenisca. Ofrece una estampa tranquila de ribera con densas masas de alamedas y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22122','espacio','Cortado geológico de Hoz y Embalse de Búbal (Alto Gállego)','Municipio suspendido de forma vertiginosa sobre un colosal acantilado de roca caliza paleozoica de más de 200 metros de caída vertical limpia sobre las aguas del embalse de Búbal. La panorámica de la fosa tectónica del Valle de Tena desde este punto mineral es sobregogedora.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22124','espacio','Llanos de Huerto y barranco de Piracés','Paisaje de transición monegrina caracterizado por plataformas margosas sujetas a una intensa erosión eólica. Ofrece amplios horizontes visuales sobre pequeñas formaciones de arenisca desgastadas y sutiles escorrentías de arcilla.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22125','espacio','Sierra de Guara septentrional y Estrechos de la Isuela','El norte del término municipal penetra en los relieves prebéticos del Parque Natural de la Sierra y Cañones de Guara. Destaca por sus murallones calizos grises, modelados kársticos de lapiaces y cortados verticales labrados por el río Isuela.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22126','espacio','Llanos de Ibieca y cañada de la Fuenteta','Paisaje de piedemonte prepirenaico con sutiles muelas y cerros testigo compuestos por calizas y arcillas miocénicas. Ofrece una estampa tranquila de horizontes despejados con encinares de llanura fragmentados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22128','espacio','Sasos de Ilche y arroyo de la Almunia','Llanura elevada y pedregosa del somontano constituida por depósitos de gravas cuaternarias cementadas.   Presenta un relieve marcadamente horizontal interrumpido únicamente por sutiles barrancos estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22129','espacio','Congosto de Obarra y Valle del río Isábena','Impresionante desfiladero fluvial excavado de forma sinuosa sobre colosales murallones de roca caliza del Cretácico. Sus paredes verticales albergan vegetación rupícola exótica y un curso de agua cristalina de montaña que ruge entre estrechos pasillos de roca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','espacio','Peña Oroel y Valle del Aragón','Monumental muela caliza de perfil asimétrico que domina visualmente toda la canal de Berdún con un escarpe vertical colosal en su cara norte. Alberga frondosos bosques de pino silvestre y hayedos de umbría enclavados en relieves de gran impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22131','espacio','Valle del río Osia y umbrías de Aragüés','Entorno de montaña pirenaica caracterizado por un relieve quebrado sobre calizas y pizarras paleozoicas. Destaca por sus densos bosques mixtos de abeto y haya, y la pureza visual de sus torrentes que descienden directamente de los circos glaciares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22133','espacio','Rivera del río Cinca y vertientes de la Peña Montañesa','Tramo donde el río Cinca se ensancha en terrazas aluviales flanqueadas por las vertiginosas pendientes calcáreas de la comarca del Sobrarbe. Ofrece una panorámica nítida de la estratificación geológica prebética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22135','espacio','Pozos-fuente naturales y lomas calcáreas del Somontano','Relieve ondulado de calizas miocénicas donde destaca la presencia de estructuras freáticas subterráneas asociadas a la disolución kárstica superficial. Ofrece un paisaje estepario con sutiles geoformas de erosión.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22136','espacio','Marismas de Lalueza y llanuras de la cuenca del Flumen','Depresión sedimentaria monegrina con presencia de pequeñas lagunas y costras salinas debidas a la evaporación en áreas endorreicas. Ofrece una panorámica diáfana de texturas blanquecinas y vegetación halófila asociada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22137','espacio','Sierra de Alcubierre septentrional y torrollones de Lanaja','Paisaje monegrino caracterizado por la presencia de imponentes torrollones de arenisca esculpidos por el viento que emergen sobre laderas margosas. El dosel forestal de sabinas y pinos carrascos corona los relieves más estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22139','espacio','Llanos del Somontano y arroyo del Alcanadre','Terreno horizontal compuesto por arcillas y areniscas terciarias degradadas por erosión laminar. Destaca por la regularidad de sus horizontes abiertos limpios de relieve abrupto notable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22141','espacio','Cárcavas del río Alcanadre','Tramo donde el río Alcanadre labra potentes taludes y escarpes arcillo-arenosos de color ocre y rojizo. Ofrece un paisaje quebrado de gran interés estético por los cortes geométricos que dibuja la erosión fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22142','espacio','Sierras marginales del Isábena y barrancos margosos','Relieve prepirenaico quebrado caracterizado por el afloramiento de calizas y potentes perfiles de margas grises erosionadas en badlands. Destaca por sus marcados pliegues geológicos tectónicos visibles en las laderas desnudes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22143','espacio','Coll de Espina y turbonada del río Isábena (cabecera)','Cabecera de alta montaña pirenaica caracterizada por un relieve de pendientes extremas compuestas por pizarras y formaciones de areniscas rojas del Buntsandstein. Alberga densos bosques de pino negro y praderas alpinas de gran nitidez visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22144','espacio','Gargantas del río Cinca y escarpes de la Peña Montañesa','Ubicación privilegiada bajo los colosales murallones calizos de la Peña Montañesa que caen de forma vertical sobre el cañón del río Cinca. El paisaje ofrece una de las composiciones de relieve calcáreo y agua más imponentes y salvajes del Pirineo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','espacio','Sierra de Loarre y Mallos de Pusilibro','Muralla pétrea prepirenaica caracterizada por imponentes formaciones de calizas jurásicas y eocénicas replegadas. Ofrece crestas rocosas desnudas, lapiaces profundos y extensos bosques de pino silvestre en sus laderas en umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22150','espacio','Salto de Roldán y desfiladero del río Flumen','Prodigio geomorfológico consistente en dos colosales peñascos gemelos de conglomerados oligocénicos (San Miguel y Amán) que aprisionan el río Flumen en una grieta vertical estrecha de cientos de metros de caída libre. El impacto visual es sobregogedor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22151','espacio','Sierra de Bolea meridional y dehesas de encinar','Espacio de transición entre la llanura de la Hoya y las sierras calcáreas marginales. Presenta un relieve ondulado cubierto de densas masas de encinar montano que colonizan los abanicos aluviales y canchales basales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22905','espacio','Embalse de Sotón y lomas de Ortilla','Cuenca de agua remansada sobre arcillas y areniscas miocénicas. Ofrece amplias panorámicas de la lámina de agua que contrasta vivamente con los relieves suaves de saso y la vegetación perilagunar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22155','espacio','Sierra de Cajigar y nacimientos de arroyos','Relieve quebrado prepirenaico caracterizado por calizas eocénicas y areniscas que forman crestas estrechas y profundos valles forestales cubiertos de quejigares de umbría bien conservados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22156','espacio','Llanura de la Hoya de Huesca y arroyo Flumen','Espacio estrictamente llano constituido por sedimentos finos arcillo-limosos del Terciario central. Su valor se reduce a la inmensidad diáfana del horizonte y los sutiles meandros fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22158','espacio','Cerro del Castillo (entorno geológico) y confluencia del Cinca y Sosa','Promontorio de areniscas y conglomerados miocénicos ecorrodados que emerge de forma aislada sobre la llanura aluvial del río Cinca, ofreciendo un gran interés geomorfológico como cerro testigo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22160','espacio','Salinar de Naval y barrancos del río Llastre','Valle de disolución kárstica donde afloran importantes fuentes de agua hipersalina ligadas a los diapiros de yeso y sal del Triásico bético aragonés. Ofrece un paisaje mineral de texturas y costras salinas singulares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22162','espacio','Valle del río Guatizalema y terrazas aluviales','Tramo aluvial donde el río labra depósitos de gravas y limos cuaternarios. Ofrece una fisonomía llana y despejada de horizontes limpios con pequeñas hileras de chopos que marcan el curso del agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22163','espacio','Congosto de Olbena y Gargantas del río Isuela','Espectacular y angosto desfiladero fluvial donde el río corta de forma transversal las potentes estructuras de caliza jurásica de la Sierra de Guara. Las monumentales paredes verticales de piedra gris son de un enorme impacto estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22164','espacio','Congosto de Olvena (Río Ésera)','Impresionante tajo fluvial excavado por el río Ésera sobre las estructuras calcáreas de las sierras marginales prepirenaicas, con paredes de roca vertical de más de 100 metros de caída limpia que aprisionan aguas transparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22165','espacio','Sasos de Ontiñena y barranco de la Val','Paisaje monegrino caracterizado por plataformas elevadas pedregosas y laderas de arcilla expuestas a una intensa erosión eólica, que generan texturas áridas de gran interés visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22167','espacio','Terrazas fluviales del bajo Cinca','Llanura de sedimentación aluvial del Cuaternario donde el río Cinca ensancha su cauce. Ofrece un paisaje llano de depósitos de cantos rodados y pequeñas choperas que acompañan el curso del agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22168','espacio','Riberas del embalse de Mediano y Sierra de Palo','Espacio donde los relieves calcáreos prebéticos se hunden de forma suave.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22170','espacio','Circo de Panticosa, Ibones de Bachimaña y picos de Argualas','Uno de los epicentros geomorfológicos del Pirineo central aragonés. Presenta una colosal morfología glaciar con lagunas de alta montaña de origen glaciar (ibones) encajadas en cubetas de roca granítica y micaesquistos que superan los 3.000 metros de altitud.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22172','espacio','Llanos de Peñalba y barrancos desérticos','Paisaje monegrino extremo caracterizado por materiales margosos y yesíferos del Mioceno sometidos a intensa aridez. Ofrece una fisonomía esteparia austera de sutiles ondulaciones arcillosas y texturas blanquecinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22173','espacio','Mallos de Riglos','Monumento geológico de nivel internacional. Colosales torreones monolíticos de conglomerados oligocénicos de más de 300 metros de caída totalmente vertical y tonos rojizos encendidos, que se elevan de forma dramática sobre el río Gállego. Uno de los mayores espectáculos visuales de Europa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22174','espacio','Cortados del río Alcanadre en Peralta','Tramo fluvial donde el Alcanadre erosiona los depósitos sedimentarios terciarios originando espectaculares taludes y escarpes arcilloso-arenosos verticales de gran potencia geométrica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22175','espacio','Desfiladero de la Ganza y Salinar de Peralta','Angosto cañón calizo excavado por el río Sosa con impresionantes farallones verticales de piedra gris, acompañado en sus zonas bajas por afloramientos de yesos triásicos y fuentes de agua salada de gran interés mineralógico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22176','espacio','Llanos de Peraltilla y sutiles lomas','Relieve horizontal suave del Somontano constituido por arcillas y areniscas terciarias. Ofrece horizontes abiertos y despejados sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22177','espacio','Valle del río Ésera y escarpes de la Sierra de la Espluga','Tramo de erosión fluvial donde el río Ésera labra un valle encajonado entre sedimentos calcáreos y areniscas. Destaca por sus bosques mixtos de pino silvestre y encina montana que tapizan laderas de fuertes pendientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22178','espacio','Cañón del río Alcanadre en Pertusa','Estrecho desfiladero fluvial excavado de forma sinuosa sobre areniscas y conglomerados de la depresión del Ebro, con taludes verticales de color ocre y pequeñas pozas estacionales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22181','espacio','Peña de Piracés y torrollones del desierto','Impresionante laberinto geomorfológico de areniscas ecorrodadas por el viento en formas de plataformas tabulares, agujas y chimeneas de hadas que emergen sobre badlands arcillosos. Ofrece una de las fisonomías desérticas más plásticas del somontano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22182','espacio','Valle de Chistau, Basa de la Mora (Ibón de Plan) y Cotiella','Espectacular valle pirenaico que alberga la Basa de la Mora, una idílica laguna de alta montaña de origen glaciar encajada en un colosal circo de rocas calizas del macizo de Cotiella, rodeada de bosques de pino negro y canchales vertiginosos de belleza mística.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22184','espacio','Llanuras del Flumen y arroyo de la Violada','Espacio liso monegrino constituido por sedimentos finos arcillo-limosos del Terciario central. Su valor se reduce a la inmensidad diáfana del horizonte agrario tradicional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22186','espacio','Salto de Pozán (Río Vero) y azud natural','Tramo donde el río Vero discurre sobre potentes bancos de areniscas del Mioceno, creando pequeñas pozas y saltos de agua sobre plataformas de erosión fluvial rodeadas de un frondoso bosque de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22187','espacio','Desfiladero del Ésera y cola del embalse de Barasona','Corte erosivo fluvial donde el río Ésera corta los estratos calcáreos prebéticos originando escarpes verticales cubiertos de encinar montano que mueren en la lámina de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22188','espacio','Entrada al Congosto de Mont-rebei y río Noguera Ribagorzana','Límite oriental caracterizado por el inicio del colosal cañón calcáreo que corta la Sierra del Montsec, con imponentes paredes verticales de roca caliza jurásica que flanquean las aguas transparentes del río.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22189','espacio','Cañón de Añisclo (Parque Nacional de Ordesa) y Valle de Bestué','Una de las joyas geológicas de Europa. Colosal y profundo desfiladero kárstico excavado por el río Bellos en la roca caliza, con paredes totalmente verticales de varios cientos de metros de altura tapizadas de musgo, cascadas surgentes y bosques de umbría subatlántica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22190','espacio','Macizo de la Peña Montañesa','Imponente mole calcárea prebética de perfil alpino que se eleva de forma exenta y monumental sobre la comarca del Sobrarbe, ofreciendo colosales escarpes de roca caliza gris y canchales de piedra de gran fuerza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22193','espacio','Ripas del Cinca y lomas margosas','Pequeñas elevaciones arcillo-arenosas erosionadas que forman taludes verticales sobre la llanura aluvial del río Cinca, ofreciendo interesantes perfiles de erosión hídrica superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22195','espacio','Cerros del Flumen y escarpes de arenisca','Relieve ondulado de la Hoya de Huesca caracterizado por pequeñas muelas de areniscas miocénicas erosionadas con formas redondeadas por la escorrentía superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22197','espacio','Sierra de Alcubierre occidental y lomas arcillosas','Relieve ondulado monegrino constituido por arcillas, yesos y margas del Terciario, con presencia de pequeños barrancos secos y reductos estables de sabina albar adaptada a la aridez.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22199','espacio','Badlands de la Guarguera y río Gállego','Extensas formaciones de margas eocénicas grises intensamente erosionadas por el agua en forma de cárcavas y crestas afiladas (badlands). El contraste con las terrazas aluviales del río Gállego es de un gran interés geomorfológico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22200','espacio','Valle de Lliterola, Ibón de Posets y Parque Natural Posets-Maladeta','Paisaje alpino de alta montaña pirenaica con circos glaciares calizos y de esquistos que superan los 3.000 metros de altitud. Cuenta con lagunas glaciares relictas, canchales de piedra granítica y cascadas atronadoras de agua de deshielo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22201','espacio','Sierra de la Candelera y muelas calizas del Somontano','Cresta caliza estrecha que emerge con fuerza en el paisaje prelitoral del Somontano. Ofrece imponentes escarpes rocosos moldeados por la erosión eólica y amplias vistas sobre la llanura del Ebro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22202','espacio','Llanos del Somontano y terrazas de inundación','Relieve horizontal suave constituido por depósitos arcillo-limosos del terciario superior. Ofrece horizontes abiertos y despejados sin relieves abruptos notables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22203','espacio','Valle del río Guatizalema y llanuras margosas','Espacio estrictamente llano constituido por sedimentos finos de la depresión del Ebro. Su valor se reduce a la inmensidad diáfana del horizonte agrario tradicional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','espacio','Circo de Piedrafita, Ibón de Respomuso y Peña Foratata','Espectacular cabecera de alta montaña del Valle de Tena, coronada por la monumental aguja caliza exenta de la Peña Foratata. Presenta una morfología glaciar colosal con ibones hipertransparentes encajados en roca granítica y canchales subalpinos de primer orden internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22205','espacio','Rocas del Castillo y barranco de la Sosa','Aforamientos de areniscas miocénicas erosionadas en formas caprichosas y bolos graníticos menores que rompen la llanura de la Litera, creando un relieve quebrado de tonos ocres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22207','espacio','Valle de Chistau superior y Parque Natural PosetsMaladeta','Entorno de alta montaña pirenaica en el sector oriental del macizo de Posets, caracterizado por escarpes calcáreos y canchales. Destaca por sus circos glaciares y la transición botánica hacia prados alpinos y bosques de pino negro.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22903','espacio','Sasos de Estiche y riberas de inundación del Cinca','Plataforma elevada de cantos rodados cuaternarios cementados que cae mediante pendientes suaves hacia el cauce fluvial bajo del Cinca. Ofrece horizontes abiertos esteparios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22206','espacio','Llanuras del Flumen y terrazas del Cuaternario','Espacio liso monegrino constituido por sedimentos finos de inundación. Su valor contemplativo radica en los sutiles meandros y pequeñas hileras de sauces que acompañan el curso del río Flumen.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22208','espacio','Canal de Berdún y riberas del río Aragón','Gran fosa de sedimentación prepirenaica donde el río Aragón describe una amplia llanura aluvial de cantos rodados y gravas, flanqueada hacia el sur por las estribaciones calcáreas de San Juan de la Peña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22209','espacio','Paisaje Protegido de San Juan de la Peña y Monte Oroel','Impresionante e icónico relieve montañoso caracterizado por gigantescos escarpes de conglomerados oligocénicos erosionados de forma cóncava, creando colosales abrigos de roca que protegen densos bosques de pino silvestre y acebedos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22906','espacio','Cañón del río Vero (tramo inferior) y huertas de Dulcis','Tramo de transición geomorfológica donde el río Vero abandona los profundos desfiladeros calizos de Guara, abriendo un pequeño valle de terrazas aluviales flanqueadas por escarpes de arenisca.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22212','espacio','Estrechos del río Ésera y Sierra de San Quílez','Angosto estrechamiento fluvial donde el río Ésera corta estructuras calcáreas jurásicas, creando laderas de pendientes acusadas cubiertas de una densa vegetación mixta pirenaica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22213','espacio','Laguna de Sariñena (Espacio Natural Protegido)','Excepcional e inmensa laguna endorreica perenne situada en pleno corazón de los Monegros, alimentada por escorrentías superficiales y freáticas. Ofrece una espectacular lámina de agua rodeada por una densa corona de carrizales y espadañas de gran valor visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22214','espacio','Desfiladero del Ésera y escarpes del santuario de Torreciudad','Tramo fluvial encajonado donde el río Ésera se remansa en el embalse de El Grado entre potentes farallones de roca caliza y montañas cubiertas de densos encinares montanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22215','espacio','Congosto de Ventamillo (Río Ésera)','Impresionante e internacionalmente reconocido desfiladero fluvial de más de seis kilómetros de longitud, donde el río Ésera taja de forma vertical las estructuras calcáreas mesozoicas del macizo de Cotiella, con paredes de roca gris que desafían la gravedad.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22217','espacio','Llanos de Sena y barranco de la Val','Paisaje monegrino llano constituido por materiales arcillo-limosos miocénicos con formas de relieve suaves labradas por la erosión eólica superficial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22218','espacio','Sierra de Alcubierre septentrional y dehesa de sabinas','Relieve ondulado en las faldas de la sierra monegrina que alberga un interesante reducto forestal de sabina albar adaptado a condiciones de aridez extrema.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22220','espacio','Torrollones de Sesa y río Guatizalema','Aforamientos singulares de areniscas erosionadas por el viento que forman pequeños monolitos y plataformas tabulares sobre laderas de arcilla ocre junto al cauce fluvial.   Sabiñánigo - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22222','espacio','Valle del río Guatizalema y lomas del Somontano','Relieve ondulado suave caracterizado por depósitos sedimentarios de arenas y arcillas miocénicas, con sutiles escorrentías e hileras de vegetación de ribera mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22223','espacio','Congosto de Escales y río Noguera Ribagorzana','Impresionante desfiladero de alta montaña donde el río corta de forma radical los murallones calcáreos que preceden al Pirineo axial, creando un pasillo rocoso de paredes limpias y verticales de gran fuerza geomorfológica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22225','espacio','Cárcavas de Tamarite y yeseras del Triásico','Paisaje quebrado caracterizado por profundos barrancos labrados en estratos de yeso cristalino y arcillas rojas, ofreciendo un gran interés visual por los destellos minerales bajo el sol.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22226','espacio','Abrazo del llano monegrino y lomas del Saso','Relieve de transición constituido por plataformas calizas elevadas e incipientes formaciones de torrollones erosionados, que definen el inicio de la aridez esteparia de los Monegros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22227','espacio','Gargantas de Escuaín (Parque Nacional de Ordesa) y Dolmen de Tella (entorno)','Espectacular complejo kárstico de alta montaña con profundas gargantas verticales esculpidas por el río Yaga, surgencias de agua helada y un circo de cumbres calizas que superan los 2.500 metros en un entorno botánico subatlántico soberbio.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22228','espacio','Terrazas del río Flumen en Tierz','Espacio plano de la Hoya de Huesca compuesto por potentes depósitos de gravas y limos cuaternarios transportados por el río, con un interés visual limitado a la regularidad de la vega aluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22229','espacio','Desfiladero de la Tosca y río Cajigar','Angosto cañón calizo excavado por el río Cajigar con espectaculares formaciones de tobas calcáreas (travertinos) y pozas de aguas hipertransparentes rodeadas de vegetación rupícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22230','espacio','Valle de Ordesa (Parque Nacional), Circo de Soaso y Cañón del Ara','Uno de los monumentos naturales más monumentales e impresionantes del mundo. Colosal cañón de origen glaciar con paredes verticales calcáreas de más de 800 metros de caída limpia, cascadas atronadoras escalonadas (Cola de Caballo) y bosques de hayas y pino negro de valor biológico incalculable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22232','espacio','Llanos de Torralba y lomas margosas de Monegros','Paisaje ondulado constituido por materiales arcillosos y yesíferos del Terciario, con una fisonomía esteparia austera de sutiles escorrentías y horizontes infinitos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22233','espacio','Vertientes de la Sierra de Pallero y río Isábena','Laderas montañosas de fuertes pendientes compuestas por pizarras y calizas, cubiertas por un denso tapiz de quejigares de umbría y pequeños barrancos de cabecera cristalinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22234','espacio','Ripas del bajo Cinca y escarpes arcillosos','Colosales acantilados arcillo-arenosos de color ocre labrados por la acción erosiva del río Cinca en su confluencia con el Ebro, configurando un frente vertical de gran interés plástico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22235','espacio','Meandros del río Alcanadre en Torres','Tramo aluvial donde el río describe amplias curvas encajonadas entre depósitos cuaternarios y colinas margosas de perfil suave, ofreciendo una muestra nítida de la dinámica fluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22236','espacio','Llanura aluvial del río Flumen','Término municipal reducido asentado de forma horizontal sobre depósitos de sedimentación limosa, con horizontes limpios dominados por las formaciones de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22239','espacio','Torrollones de Tramaced y Peña del Mediodía','Extraordinarias formaciones de areniscas esculpidas por la erosión eólica en formas de plataformas tabulares y monolitos caprichosos, que emergen con fuerza sobre badlands arcillosos de tonos ocres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22242','espacio','Llanos monegrinos y barranco de la Val','Terreno horizontal desértico caracterizado por materiales margosos miocénicos sometidos a una intensa aridez, que genera una fisonomía esteparia austera de horizontes limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22909','espacio','Clots de Vencillón y llanura de la Litera','Paisaje llano característico del sector oriental de la depresión del Ebro, con suaves depresiones endorreicas sobre materiales arcillosos. Ofrece una fisonomía esteparia despejada con sutiles variaciones cromáticas según la época estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22247','espacio','Desfiladero de Mont-rebei y murallones de Finestres','Colosal cañón fluvial labrado por el río Noguera Ribagorzana con paredes calizas verticales de más de 500 metros de caída libre. El paraje de Finestres ofrece además una impresionante y perfecta doble línea de estratos calcáreos verticales que emerge del agua como una muralla mineral china.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22248','espacio','Cerros margosos de la Hoya de Huesca','Relieve de colinas muy bajas compuesto por alternancias de margas y arcillas terciarias sujetas a procesos de erosión laminar suave, ofreciendo visuales diáfanas de la llanura somontana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22249','espacio','Valle de Benasque, riberas del Ésera y umbría del monte Gallinero','Entorno de alta montaña pirenaica asentado en un valle de modelado glaciar profundo flanqueado por imponentes macizos calcáreos. El río Ésera discurre veloz entre cantos rodados, rodeado de frondosos bosques mixtos de hayas, abedules y pinos negros.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22250','espacio','Cueva de las Güixas y macizo kárstico de Collarada','Impresionante complejo geológico exterior e interior dominado por el pico Collarada, un colosal coloso calizo de morfología kárstica. La cueva de las Güixas destaca por sus monumentales salas esculpidas por corrientes de   agua subterráneas, con una profusión bellísima de estalactitas y estalagmitas activas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22251','espacio','Riberas del río Alcanadre y escarpes de Sigena','Tramo fluvial donde el río Alcanadre corta los depósitos de areniscas y arcillas del terciario monegrino, labrando pequeños cortados y taludes de coloración rojiza que contrastan con los densos sotos de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22252','espacio','Santuarios de las Cuevas de Santa Orosia y barranco de Santa Orosia','Espectacular murallón de conglomerados y areniscas erosionado de forma escalonada en un anfiteatro natural de imponentes paredes rocosas verticales. Cuenta con impresionantes saltos de agua estacionales (Chorro de Santa Orosia) y oquedades naturales colgadas en los estratos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22253','espacio','Valle del río Sía y umbrías del Puerto de Cotefablo','Hermoso y encajonado valle de montaña prepirenaica caracterizado por un relieve de fuertes pendientes labrado sobre formaciones de flysch (alternancia de areniscas y margas). Alberga uno de los hayedos y pinares de pino silvestre más frondosos y puros de la Jacetania oriental.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22254','espacio','Ripas de Zaidín y riberas del río Cinca','Frente de acantilados arcilloso-arenosos de gran pendiente labrados por la acción erosiva del cauce bajo del río Cinca. Ofrece un paisaje estético de badlands que rompen hacia la fértil y verde vega de inundación aluvial.   ¡Objetivo cumplido! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24001','espacio','Tajo de Albanchez y vertientes del Monte Aznaitín','Imponente murallón vertical de roca caliza jurásica que se eleva de forma monumental sobre el casco urbano, integrado en el Parque Natural de Sierra Mágina. Destaca por la contemplación visual de sus escarpes descarnados y el ecosistema vegetal rupícola que coloniza las fisuras de la piedra gris.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24002','espacio','Tajos de Charilla y lomas calizas del río Velillos','Conjunto de cortados calizos que emergen de forma abrupta entre los extensos campos de olivar del sur provincial. Ofrece una fisonomía de relieves calcáreos   fracturados con pequeñas cavidades de disolución y horizontes visuales limpios hacia las sierras subbéticas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','espacio','Reserva Natural de la Laguna Honda y Laguna del Chinche','Complejo de humedales endorreicos de aguas permanentes y estacionales con una alta mineralización debido al sustrato evaporítico subyacente. El paisaje ofrece una estampa contemplativa de quietud acuática, rodeada por un denso cinturón perilagunar de carrizos, tarajes y eneas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24004','espacio','Paraje Natural de la Cimbarra y cañón del río Guarrizas','Uno de los espectáculos geológicos más monumentales de Sierra Morena, consistente en un colosal salto de agua de más de 40 metros de caída vertical libre sobre una pared de areniscas y cuarcitas armoricanas expuestas. La fisonomía de los estratos replegados y la profundidad del cañón son de un impacto visual absoluto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','espacio','Parque Natural de la Sierra de Andújar y cañón del río Jándula','Relieve granítico y pizarroso que conforma el corazón biológico más puro de Sierra Morena, caracterizado por extensos berrocales de bolos redondeados. Destaca por el aislamiento absoluto de sus paisajes boscosos, cubiertos por una masa forestal continua de encinas, alcornoques y madroños.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','espacio','Terrazas aluviales del río Guadalquivir y lomas de la campiña','Relieve ondulado muy suave de materiales sedimentarios miocénicos donde destacan los procesos de erosión laminar y horizontes diáfanos. Ofrece una visual   dominada por la geometría de los olivares asentados sobre arcillas y limos fluviales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24007','espacio','Valle fluvial del arroyo Salado y llanuras de sedimentación','Espacio marcadamente horizontal constituido por depósitos cuaternarios finos en el sector occidental de la campiña alta de Jaén. Presenta un relieve sin grandes accidentes topográficos, de interés centrado en la regularidad cromática del suelo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24008','espacio','Entorno del embalse de Guadalén y lomas arcillosas','Cuenca de agua encajada entre colinas suaves compuestas por arcillas y areniscas en la transición hacia el Andévalo oriental. La lámina de agua perenne aporta una perspectiva de gran serenidad visual, rompiendo la aridez del relieve de monte bajo circundante.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23905','espacio','Riberas del río Guadalimar y dehesa del Ojanco','Tramo fluvial donde el río Guadalimar describe meandros suaves sobre una llanura aluvial encajada entre lomas calizas menores. Destaca por sus sotos ripícolas estables compuestos por alisos, sauces y fresnos en un estado de conservación notable.   Jaén).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','espacio','Paraje Natural de la Laguna Grande y riberas del río Guadalquivir','Humedal de origen antrópico naturalizado asentado sobre una cuenca sedimentaria del curso alto del Guadalquivir. Destaca por la quietud de su lámina de agua y la contemplación de una de las mayores masas de carrizal y vegetación perilagunar de la provincia, rodeada por el mar de olivos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24011','espacio','Lomas arcillosas de Bailén y terrazas del río Rumblar','Relieve ondulado suave constituido por potentes depósitos de arcillas miocénicas de gran tradición alfarera. Ofrece una fisonomía de campiña árida con procesos de erosión laminar y sutiles bandas de coloración ocre expuestas por la escorrentía estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','espacio','Embalse del Rumblar, Peñallana y berrocales graníticos','Paisaje monumental donde el río corta el zócalo paleozoico de Sierra Morena, creando un relieve de berrocales con grandes bolos graníticos y pizarras desmanteladas. La masa de agua turquesa se encaja de forma laberíntica entre laderas cubiertas de densos encinares y jarales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24013','espacio','Valle del río Beas y estrechos de la cueva del Agua','Cabecera fluvial encajada en las estribaciones calcáreas del Parque Natural de las Sierras de Cazorla, Segura y Las Villas. Ofrece una fisonomía abrupta de tajos calizos grises, surgencias de agua hipertransparente y umbrías de pino laricio mezcladas con vegetación de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24015','espacio','Vega aluvial del río Guadalquivir y lomas de la Loma','Espacio marcadamente horizontal compuesto por terrazas fluviales cuaternarias de limos, arenas y gravas. Destaca por la amplitud de sus horizontes diáfanos y el contraste estacional entre el dosel vegetal del soto ribereño y las tierras arcillosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24018','espacio','Nacimiento del río Gargantón y picos de Sierra Mágina','Espectacular cabecera de valle de montaña kárstica donde el agua brota con fuerza de los acuíferos calizos jurásicos. Flanqueado por paredones verticales y canchales de piedra del Monte Carboneras, ofrece un entorno mineral sobrecogedor y de gran pureza visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24016','espacio','Cumbre de Orcera y pinares de alta Segura','Territorio integrado plenamente en la Sierra de Segura con relieves prebéticos abruptos de alta paramera y crestas calcáreas. Alberga majestuosos y densos bosques continuos de pino laricio (Pinus nigra) adaptados al frío, con espectaculares farallones rocosos colonizados por rapaces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23017','espacio','Estepa de Cabra, encinar del Gurullón y cañón del río Guadahortuna','Paisaje de fuertes contrastes geomorfológicos con un sector estepario semiárido de badlands arcillosos que   da paso a una inesperada y colosal masa de encinar centenario. El río Guadahortuna excava en el límite provincial un cañón de laderas escarpadas y texturas rudas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','espacio','Arrecife de Mata Bejid y tormos de Cambil','Paisaje kárstico monumental en pleno Parque Natural de Sierra Mágina, caracterizado por colosales pitones calizos ecorrodados que emergen exentos de la tierra. Alberga una de las masas forestales mixtas más valiosas de la provincia con encinas, quejigos y arces de Montpellier.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23019','espacio','Desfiladero de Puerta de Arenas (Río Guadalbullón)','Angosto cañón fluvial excavado de forma vertical sobre calizas y dolomías jurásicas por el río Guadalbullón. Las impresionantes paredes de piedra gris forman una brecha tectónica natural con formaciones de tobas calcáreas y una umbría botánica densa muy fotogénica.   Jaén).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23020','espacio','Lomas arcillosas del somontano y arroyo de la Yedra','Paisaje suavemente ondulado compuesto por margas y arcillas miocénicas erosionadas en la transición hacia la comarca de La Loma. Ofrece un horizonte diáfano dominado por la uniformidad del olivar y sutiles cárcavas rojizas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23021','espacio','Dehesa de Carboneros y cuenca del río Guarrizas','Relieve penillanurero suave asentado sobre pizarras y pizarras paleozoicas de Sierra Morena oriental. Destaca por sus amplios horizontes visuales limpios, cubiertos de jarales estables y masas adehesadas de encina perfectamente adaptadas al terreno penillanurero.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23901','espacio','Barranco del río Guadalbullón y Peñón de Carchelejo','Espectacular relieve quebrado caracterizado por el tajo fluvial del río Guadalbullón, flanqueado por colosales moles de caliza jurásica exentas. Las laderas presentan fuertes pendientes cubiertas de monte mediterráneo con pasillos de roca gris descarnada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23024','espacio','Garganta del río Serrano y dehesas graníticas','Espacio donde el zócalo paleozoico de Sierra Morena se fractura mostrando pequeños desfiladeros fluviales y formaciones de berrocales graníticos menores. El entorno ofrece una panorámica limpia de encinares compactos combinados con formaciones de matorral xerófilo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23025','espacio','Hoz del río Guadalimar y Cerro del Condado','Tramo donde el río Guadalimar corta las estructuras arcilloso-calcáreas de la comarca, modelando un valle encajonado con pequeños farallones rocosos. La composición visual destaca por los tonos verdosos de las alamedas de ribera que rompen el paisaje.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23026','espacio','Nacimiento del río San Juan y Tajos del Castillejo','Hermosa e importante surgencia de origen kárstico donde el agua brota cristalina y con gran caudal de las entrañas de los acuíferos calizos subbéticos. Ofrece una balsa de agua perenne rodeada de majestuosos álamos de ribera y espectaculares cortados rocosos laterales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','espacio','Nacimiento del río Guadalquivir, Cañón del río Borosa y Gilillo','Uno de los epicentros geomorfológicos más imponentes de Europa, integrado en el Parque Natural de Cazorla. Presenta gigantescos murallones calizos de plegamiento alpino, desfiladeros atronadores esculpidos en roca pura (Cerrada de Elías) y frondosos bosques subatlánticos de pino laricio y acebedos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23029','espacio','Falla de Chiclana, peñón de areniscas y embalse del Guadalmena','Monumental y altivo escarpe rocoso de areniscas del Triásico de tonos rojizos y ocres que se eleva de forma vertical sobre la llanura. Funciona como una fortaleza geológica natural y ofrece amplios horizontes visuales limpios sobre la cola de agua encajada del embalse.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23030','espacio','Vega del río Cañamares y estribaciones de Las Villas','Espacio de transición geológica caracterizado por el encajonamiento del río Cañamares entre las muelas calizas del relieve prebético. Destaca por la pureza de su lecho aluvial y por sus densas formaciones de bosque de galería mediterráneo.   Jaén).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23031','espacio','Vega baja del río Salado de Porcuna y campiña','Terreno de llanura aluvial y colinas de pendiente mínima compuesto por depósitos de arcillas miocénicas muy estables. El interés se reduce a la horizontalidad diáfana de su paisaje y al contraste cromático de los horizontes agrarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24035','espacio','Meandro del río Guadalquivir y terrazas de grava','Tramo fluvial donde el Guadalquivir describe una amplia curva sobre sedimentos cuaternarios antes de recibir al río Rumblar. Destaca por la observación contemplativa de la dinámica del cauce y sus sutiles islas de sedimentación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23033','espacio','Hoya de la Martina, nacimiento de las Parreñas y Tajos de Frailes','Entorno montañoso subbético de relieve kárstico muy quebrado, caracterizado por colosales farallones de calizas del Jurásico. Ofrece un paisaje mineral agreste donde surgen abundantes fuentes naturales de agua cristalina entre formaciones de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23034','espacio','Desfiladero del río Vadillo y Sierra de la Grana','Cañón fluvial encajonado en calizas jurásicas que fractura el relieve de la comarca de Martos. Destaca por la verticalidad de sus paredes rocosas desnudas y la frondosidad de los pequeños sotos que acompañan la corriente de agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23035','espacio','Lomas del arroyo de la Moraleja y arcillas de campiña','Relieve ondulado de la campiña de Jaén moldeado sobre margas y sedimentos finos terciarios propensos a la erosión laminar. Ofrece visuales limpias de horizontes despejados desprovistos de vegetación arbórea nativa densa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23037','espacio','Sierra de las Cuatro Villas y olivar silvestre de Génave','Vertiente prebética enclavada en el extremo norte del Parque Natural de Segura, con laderas escarpadas de dolomías grises. Destaca por sus masas estables de pino laricio y encinas que se funden de manera natural con el relieve serrano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23038','espacio','Valle del río Guadalbullón y farallones del cerro de San Cristóbal','Estrechamiento geológico donde el río Guadalbullón se abre paso entre las estribaciones calizas de Sierra Mágina. Ofrece una imponente panorámica de laderas rocosas escarpadas que sirven de transición hacia la vega aluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23039','espacio','Vega del río Guadiel y dehesas coloniales','Paisaje penillanurero suave asentado sobre el contacto del zócalo paleozoico y las cubiertas de arcillas de la cuenca. Destaca por la regularidad de sus dehesas de encina y la contemplación de horizontes diáfanos mediterráneos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23041','espacio','Cuenca del arroyo de la Condesa y llanos arcillosos','Espacio marcadamente horizontal situado en el límite occidental de la campiña cordobesa-jaenesa. Presenta formas suaves labradas por la escorrentía difusa estacional sobre un sustrato de sedimentos finos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23042','espacio','Barranco del río Turón y salinas de interior','Extraordinario entorno semiárido integrado en el Parque Natural de Cazorla, caracterizado por el encajonamiento absoluto del río Turón sobre yesos y arcillas del Triásico. Ofrece un paisaje plástico de badlands con fuertes contrastes de luz y texturas minerales.   Jaén).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23043','espacio','El Tranco de Beas (Embalse del Tranco) y muela caliza de Hornos','Impresionante e imponente peñón escarpado de roca caliza jurásica que se eleva verticalmente sobre la inmensa lámina de agua turquesa del embalse. Ofrece una de las composiciones visuales más majestuosas del Parque Natural de Segura, con laderas boscosas de pino negral que caen a plomo sobre el agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23044','espacio','Santuario de Fuensanta, Pico Mágina (vertiente sur) y pinar de Cánava','Paisaje subbético de alta montaña con vertiginosas pendientes calizas grises y el Monumento Natural del Pinar de Cánava, un rarísimo e histórico reducto de pinos carrascos centenarios de porte monumental. El relieve destaca por sus canchales de piedra y umbrías de gran pureza mineral.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23049','espacio','Escarpes del río Guadalquivir y cerros margosos','Frente de lomas arcillosas y margas del Mioceno que han sido cortadas de forma sinuosa por la dinámica erosiva del río Guadalquivir. Ofrece una vista de amplias terrazas aluviales y un paisaje desprovisto de relieve abrupto severo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','espacio','Paraje Natural del Cañón de los Villares, Ojo de Buey y Sierra de Jabalcuz','Monumental entorno montañoso calcáreo que abraza la ciudad por el sur, caracterizado por el tajo fluvial del río Eliche y los farallones de Jabalcuz. Presenta espectaculares formaciones kársticas exteriores como el arco de piedra natural del Ojo de Buey y escarpes verticales rugosos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23051','espacio','Vertiente norte de la Sierra de la Grana','Ladera montañosa abrupta compuesta por calizas jurásicas que emergen con fuerza sobre los llanos de la campiña. Ofrece interés por el modelado de sus canchales basales y pequeños rodales de matorral mediterráneo y encinas de carácter arbustivo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23052','espacio','Pinar de Cánava norte, nacimiento del río Carchel y Tajos de Albanchez','Término que comparte las estructuras kársticas más espectaculares de Sierra Mágina. Destaca por sus monumentales paredes verticales de roca caliza grisácea desnudada por la erosión, manantiales prístinos de montaña y un dosel de pinar y encinar montano muy estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23053','espacio','Riberas del río Jandulilla y escarpes de la Serrezuela','Paisaje quebrado caracterizado por el contraste radical entre la vega semiárida del río Jandulilla y los farallones rocosos de la Serrezuela caliza. Ofrece una   estampa geomorfológica ruda de tonos ocres con vegetación gipsófila y esclerófila adaptada al sustrato.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23040','espacio','Lomas de la campiña del Guadalquivir y arroyo de la Vega','Paisaje ondulado suave moldeado sobre depósitos arcillosos y margas del Mioceno. Destaca por la amplitud de sus horizontes diáfanos y limpios, donde los sutiles procesos de escorrentía estacional marcan las laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23054','espacio','Estepa de Larva y barrancos del Guadahortuna','Entorno semiárido de badlands caracterizado por una intensa erosión hídrica que esculpe cárcavas, crestas afiladas y taludes de arcilla. Ofrece una fisonomía de paisaje desértico de gran fuerza cromática ocre y grisácea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','espacio','Cañón del río Guarrizas, El Piélago y dehesas graníticas','Espectacular monumento natural donde el río Guarrizas corta el zócalo granítico de Sierra Morena, modelando encajonamientos rocosos y fallas verticales. La composición visual destaca por los bloques de piedra redondeados y la vegetación de ribera mediterránea.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23056','espacio','Terrazas fluviales del Guadalquivir y llanuras de sedimentación','Terreno marcadamente horizontal constituido por gravas, limos y depósitos aluviales del Cuaternario en el extremo occidental provincial. Presenta un relieve sin grandes accidentes geográficos, de interés centrado en la regularidad del llano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23057','espacio','Riberas del río Guadalimar y paraje de las Infantas','Tramo aluvial donde el río se ensancha creando llanuras de inundación estacionales sobre un sustrato arcilloso. Ofrece un contraste cromático nítido entre los campos esteparios superiores y la franja verde de sauces y alisos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23058','espacio','Peña de la Silla y umbrías de Sierra Mágina','Relieve prebético abrupto caracterizado por imponentes murallones calizos del Jurásico con pendientes vertiginosas. Alberga frondosos bosques montanos de encina, quejigo y retazos de pino laricio asentados sobre canchales y pasillos de piedra descarnada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23059','espacio','Valle del río Guadalquivir, El Balneario y estribaciones del río Yeguas','Espacio de transición geológica donde el Guadalquivir corta los materiales silíceos de Sierra Morena.   Ofrece una estampa contemplativa de aguas encajonadas, surgencias minerales naturales de gran interés hidrogeológico y riberas boscosas prístinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','espacio','Monumento Natural Peña de Martos y Sierra de la Grana','Colosal e icónica muela caliza de paredes totalmente verticales que emerge exenta y de forma dramática sobre el paisaje de la campiña olivarera. Sus escarpes rugosos de color grisáceo constituyen un hito geomorfológico de primer orden visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23061','espacio','Junta de los Ríos (Guadalquivir y Guadalbullón) y terrazas de grava','Importante nudo hidrológico aluvial donde confluyen de forma majestuosa dos grandes cuencas fluviales sobre depósitos cuaternarios. Ofrece amplios horizontes visuales limpios sobre las islas de sedimentación y los sotos ripícolas estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23062','espacio','Embalse de Dañador y dehesas del Condado norte','Cuenca de agua encajada entre colinas de pizarras y cuarcitas en el límite con Castilla-La Mancha. La lámina de agua perenne aporta un espacio de gran quietud visual rodeado de densas masas de monte bajo mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23063','espacio','Hoz del río Guadalimar y dehesas de Navas','Tramo donde el curso fluvial labra un valle estrecho y encajonado sobre materiales arcillo-calcáreos. Ofrece una vista nítida del avance de los encinares y la vegetación mediterránea sobre laderas de fuerte inclinación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23064','espacio','Hoya de Noalejo y nacimientos del río Guadalbullón','Depresión tectónica elevada situada en el límite subbético, rodeada de montañas calizas escarpadas y canchales. Destaca por la pureza de sus fuentes de cabecera y el relieve quebrado cubierto de monte mediterráneo perenne.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23065','espacio','Nacimiento de Amurjo, El Estrecho y pinares de la Sierra de Segura','Impresionante desfiladero kárstico excavado en calizas y dolomías jurásicas con gigantescos farallones verticales de piedra. Alberga majestuosos bosques continuos de pino laricio y fuentes naturales que brotan con fuerza entre la roca de la serranía.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23066','espacio','Riberas del río Guadiana Menor y badlands del Toya','Paisaje de fuertes contrastes geológicos caracterizado por el cauce encajonado del río entre terrazas de arcillas y yesos hipererosionados. Ofrece una panorámica de badlands plásticos de tonos amarillentos y ocres de gran valor estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23067','espacio','Charca de Pegalajar (fuente kárstica) y Serrezuela de Pegalajar','Extraordinaria balsa natural alimentada de forma perenne por la surgencia kárstica de la Fuente de la Almedina, a los pies de un imponente murallón de calizas jurásicas. El relieve ofrece espectaculares lapiaces y cortados verticales grises.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23069','espacio','Altiplano de Porcuna y cuenca del río Salado','Plataforma elevada compuesta por sedimentos terciarios arcillo-calcáreos suavizados por la erosión laminar. Ofrece amplios horizontes visuales limpios de campiña desprovistos de relieve abrupto o masas arbóreas continuas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23070','espacio','Pantano de la Bolera, cañón del río Guadalentín y Guazalamanco','Uno de los sectores más salvajes del Parque Natural de Cazorla, caracterizado por el abismal tajo del Guadalentín con paredes verticales calcáreas colosales. Destaca por las pozas de aguas de color turquesa del arroyo de Guazalamanco y sus cascadas en roca pura.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23071','espacio','Valle del río Guadalimar y dehesas de pinar','Tramo donde el río discurre encajado entre lomas de calizas y margas en la entrada de la Sierra de Segura. Ofrece una estampa contemplativa de sotos ripícolas bien conservados flanqueados por masas estables de pino carrasco.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23072','espacio','Estrecho de La Puerta (Río Guadalimar)','Puerta geológica natural consistente en un angosto desfiladero fluvial donde el río Guadalimar fractura los murallones de roca caliza y dolomía. Las paredes verticales desnudas y la fuerza del flujo de agua forman una composición de gran impacto estético.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23073','espacio','Nacimiento oficial del río Guadalquivir (Cañada de las Fuentes) y Tíscar','Santuario natural de primer orden en el Parque Natural de Cazorla. Alberga la Cueva del Agua de Tíscar, un monumental cañón y sumidero kárstico donde el río se desploma atronador entre paredes verticales colosales, rodeado de tejos milenarios y picos calcáreos alpinos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23074','espacio','Valdeherreros y lomas arcillosas del somontano','Relieve ondulado suave constituido por margas y arcillas de la cuenca media del Guadalquivir. Su atractivo   radica en los procesos de erosión de escorrentía superficial y en los pequeños sotos de cañaverales asociados a sus arroyos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23075','espacio','Escarpes del río Guadalimar y terrazas de La Loma','Cornisa natural de arcillas y calizas arenosas que cae de forma pronunciada hacia el valle aluvial del río Guadalimar. Ofrece amplias panorámicas limpias de horizontes despejados desde los bordes de la meseta tabular.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23076','espacio','Parque Natural de Despeñaperros y Los Órganos','Monumental desfiladero de más de doce kilómetros de longitud con paredes verticales de cuarcita armoricana de cientos de metros de caída libre. Las caprichosas formas de la erosión simulan gigantescos tubos de órgano catedralicios en un entorno mineral sobrecogedor.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23077','espacio','Campiña baja del sur y arroyo de la Vega','Espacio estrictamente plano de arcillas miocénicas estables dedicado a la agricultura intensiva. Destaca únicamente por la regularidad geométrica del horizonte y la inmensidad diáfana de la cuenca baja de sedimentación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23904','espacio','Nacimiento del río Segura, Campos de Hernán Perea y Poyo de Santo Domingo','El municipio más extenso del Parque Natural de Segura, con una altísima concentración de joyas indiscutibles. Alberga los Campos de Hernán Perea, el altiplano kárstico más colosal de España, compuesto por un desierto de dolinas calizas a 1.600 metros de altitud, además de gargantas fluviales de valor planetario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23079','espacio','Monumento Natural Huellas de Dinosaurio y dehesas de Santisteban','Afloramiento sedimentario del Triásico con icnitas fósiles expuestas sobre arcillas y areniscas rojas. El paisaje circundante destaca por la regularidad de sus dehesas continuas de encina asentadas sobre el relieve quebrado del Condado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23080','espacio','Confluencia del río Cañamares y Guadalquivir y vega alta','Espacio aluvial de gran valor contemplativo donde las aguas de la sierra confluyen en el cauce principal del Guadalquivir sobre un lecho de cantos rodados y gravas, rodeado de frondosas masas de alisedas y sauces estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','espacio','Monte Yelmo, Garganta de Hornos y pinares de alta montaña','Imponente pico calizo de perfil alpino (El Yelmo) que se eleva de forma monumental exento sobre la Sierra de Segura. Ofrece una panorámica limpia y colosal de cañones fluviales calcáreos grises, lapiaces y extensos bosques de pino laricio de valor biológico incalculable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','espacio','Nacimiento del río Mundo (vertiente andaluza), Puntal de la Misa y Peña del Olivar','Paisaje de alta montaña prebética caracterizado por gigantescos escarpes calcáreos verticales que rozan el límite con Albacete. Sus valles umbríos albergan masas puras de acebedos, quejigares de montaña y pinos laricios enclavados en relieves de gran impacto visual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23085','espacio','Confluencia del río Guadalquivir y el río Guadalimar','Amplia llanura de inundación aluvial del Cuaternario donde se unen dos de las mayores corrientes   hídricas provinciales. Destaca por la horizontalidad de sus terrazas de grava y limos flanqueadas por alamedas fragmentadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23086','espacio','Megalitos de Cerro Miguelico y lomas de la campiña alta','Formaciones rocosas y crestas calizas menores que emergen entre los campos de olivar del somontano de Jaén. Ofrece interés contemplativo por los perfiles erosivos de la piedra erosionada y pequeños reductos de monte mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','espacio','Arroyo Salado de Porcuna y campiña arcillosa','Relieve ondulado muy suave compuesto por arcillas y margas miocénicas propensas a la erosión laminar, desprovisto de relieves abruptos notables o formaciones forestales nativas compactas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23088','espacio','Escarpes del Guadalquivir meridional y lomas de La Loma','Cornisa de arcillas de sedimentación que cae mediante pendientes suaves hacia la vega aluvial del Guadalquivir. Ofrece amplios horizontes visuales limpios de carácter netamente estepario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24086','espacio','Cerro de la Fuenmayor, nacimiento del río Torres y Pico Mágina (norte)','Impresionante anfiteatro natural kárstico en pleno corazón del Parque Natural de Sierra Mágina, flanqueado por los picos más elevados de la provincia. Destaca por el manantial de Fuenmayor, que brota entre rocas calizas jurásicas rodeado de cascadas menores y un espeso bosque de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23091','espacio','Cueva de la Morciguilla y relieves de la Sierra de Cazorla norte','Término quebrado caracterizado por crestas calcáreas de dolomías grises y oquedades naturales de disolución kárstica. Ofrece un paisaje serrano aislado cubierto por un dosel regular de pino laricio y encinas de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','espacio','Valle del Guadalquivir central y terrazas de La Loma','Frente de muelas arcilloso-calcáreas cortadas por la acción erosiva de la cuenca alta del Guadalquivir. Destaca por las panorámicas despejadas que permiten observar la inmensidad del valle aluvial desde los bordes de la meseta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23093','espacio','Paraje Natural de Las Chorreras y Sierra de la Pandera','Espectacular y encajonado tajo fluvial kárstico donde el río Vadillo salta sobre terrazas de toba calcárea y travertinos activos en mitad de un relieve calizo de pendientes vertiginosas. El entorno de umbría ofrece un paisaje vegetal y acuático de enorme fuerza estética.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23094','espacio','Confluencia de los ríos Guadalén y Guarrizas y embalse de Giribaile','Extenso término caracterizado por grandes láminas de agua remansadas que se adaptan a la fisonomía de colinas de pizarras y arcillas. Ofrece panorámicas de horizontes limpios donde el agua rompe la continuidad del paisaje penillanurero de Sierra Morena baja.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23095','espacio','Cañón del río Aguascebas y Sierra de Las Villas','Impresionante desfiladero fluvial integrado en el Parque Natural de Cazorla, con imponentes cortados calizos grises de más de 100 metros de caída vertical limpia. Alberga   saltos de agua espectaculares y una masa forestal continua de pino laricio y acebedos de umbría.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23096','espacio','Riberas del río Guadalquivir y Parque Natural de la Sierra de Andújar (limite norte)','Zona de contacto donde la llanura aluvial del Guadalquivir se encuentra con las laderas graníticas y pizarrosas de Sierra Morena. Ofrece un paisaje contemplativo de transición entre la campiña baja y el monte mediterráneo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23097','espacio','Charco de la Pringue, cañón del Guadalquivir alto y Sierra de las Villas norte','Espectacular garganta fluvial donde el río Guadalquivir fluye confinado entre farallones verticales de roca caliza jurásica, formando pozas naturales de aguas transparentes de color verde esmeralda rodeadas de densos bosques de galería.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23098','espacio','Lomas arcilleras de la campiña de Jaén','Terreno de lomas bajas arcillosas del Mioceno sujetas a erosión laminar suave por las labores agrícolas. Ofrece una fisonomía horizontal y diáfana sin accidentes geográficos destacables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23099','espacio','Río Frío y escarpes de la Sierra de la Pandera','Cabecera de valle encajonada entre imponentes murallones calizos subbéticos. Destaca por el curso de agua de Río Frío, cuyas aguas cristalinas discurren rápidas sobre un lecho pedregoso rodeado de densas alamedas y sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23903','espacio','Vega del Guadalquivir y desembocadura del río Guadalbullón','Llanura aluvial cuaternaria horizontal de sedimentación limosa y arenosa. El valor contemplativo reside en la amplitud visual de la cuenca y en la presencia del bosque de ribera fragmentado que marca los cursos hídricos.   ¡Objetivo cumplido con rigor absoluto! Hemos finalizado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26001','espacio','Valle de Valdeburón y picos de Mampodre','Impresionante entorno de alta montaña cantábrica dominado por circos glaciares e imponentes crestas calizas del Carbonífero. Alberga densas masas de hayedos umbríos que conviven con pastizales alpinos y arroyos de deshielo hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90196','espacio','Terrazas del río Esla y llanuras aluviales','Paisaje horizontal de la meseta leonesa modelado sobre depósitos fluviales cuaternarios de cantos rodados y arenas. Ofrece horizontes amplios y limpios donde destaca la regularidad del relieve y la vegetación arbustiva marginal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90197','espacio','Riberas del río Órbigo y cerros de greda','Espacio de transición fluvial donde el río Órbigo esculpe taludes de arcilla y cantos rodados cementados. Destaca por el contraste cromático entre los tonos ocres de las laderas erosionadas y el dosel verde de los sotos ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90664','espacio','Riberas del río Cea y robledales del somontano','Relieve ondulado de materiales detríticos terciarios cubierto por una masa forestal continua de rebollo o melojo. El cauce del río Cea aporta una fisonomía de gran quietud visual con meandros suaves flanqueados por sauces.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90198','espacio','Campiña del Esla y cárcavas de arcilla','Terreno caracterizado por lomas bajas arcillosas erosionadas por la escorrentía superficial en la margen derecha del Esla. Permite la contemplación de las texturas del suelo labrado y pequeños horizontes diáfanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90199','espacio','Hoya del Bierzo occidental y colinas de arenisca','Relieve quebrado de transición prepirenaica compuesto por sedimentos detríticos arcillo-rojizos y cantos rodados. Ofrece una estampa armónica donde los sutiles barrancos forestales rompen suavemente hacia la llanura berciana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','espacio','Valle del río Tuerto y llanuras de la Maragatería','Plataforma elevada horizontal constituida por rañas y depósitos de cantos de cuarcita englobados en matrices arcillosas. Ofrece amplios horizontes visuales limpios caracterizados por la sobriedad del relieve meseteño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90200','espacio','Cañón del río Balboa y umbrías de la Sierra de Ancares','Espectacular y encajonado valle de alta montaña atlántica labrado sobre pizarras y esquistos paleozoicos por aguas fluviales cristalinas. Alberga una exuberante masa forestal de castaños monumentales, avellanos y robledales maduros en laderas de pendientes vertiginosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26009','espacio','Confluencia del río Órbigo y el río Duerna','Llanura aluvial cuaternaria horizontal de sedimentación arenosa y limosa. El valor contemplativo reside en la amplitud visual de la cuenca y en la presencia del soto ripícola fragmentado que marca los cursos hídricos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90201','espacio','Hayedo de Busmayor y valles de Ancares','Uno de los hayedos más meridionales y puros de la cordillera Cantábrica, asentado sobre laderas escarpadas de pizarras oscuras. El relieve presenta profundas quebradas con saltos de agua cristalina y una atmósfera umbría de enorme fuerza estética.   Barrios de Colina - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90780','espacio','Estrecho de Oblanca, calizas del Lancara y embalse de Luna','Monumental cañón kárstico donde el río Luna corta de forma abrupta e infranqueable los potentes murallones verticales de roca caliza cambriana. La inmensa lámina de agua se encaja entre farallones rocosos grises de gran interés geológico internacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26004','espacio','Gargantas del río Boeza y relieves del Bierzo Alto','Tramo de erosión fluvial encajonado sobre un sustrato de pizarras y cuarcitas erosionadas. Ofrece perfiles de laderas de pendientes pronunciadas cubiertas por monte bajo mediterráneo-atlántico y pequeños robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90202','espacio','Vega del río Órbigo y terrazas fluviales','Espacio liso de fondo de valle constituido por sedimentos cuaternarios de limos y gravas. Ofrece una   panorámica diáfana de la llanura de inundación dominada por la linealidad de las plantaciones de chopos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90203','espacio','Cañón del río Cabrera y crestas de la Sierra de la Cabrera','Impresionante paisaje de montaña labrado sobre pizarras paleozoicas que generan laderas vertiginosas de coloración oscura. El río Cabrera fluye encajonado en el fondo del desfiladero, rodeado de un entorno virgen de encinares y robledales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90204','espacio','Valle de Valdeón, Macizo de Mampodre y Parque Nacional de Picos de Europa','Santuario de alta montaña caracterizado por colosales crestas calcáreas, circos glaciares y canchales de piedra descarnada. Alberga majestuosos y frondosos hayedos que tapizan las umbrías de valles profundos de un impacto visual absoluto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26005','espacio','Desfiladero de las Forjas, río Porma y pico Cueto','Espectacular brecha tectónica natural donde el río Porma corta los murallones de roca caliza jurásica y carbonífera. Presenta farallones verticales de color gris, formaciones kársticas aéreas y densos bosques de pino silvestre en sus laderas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90205','espacio','Las Médulas (entorno geomorfológico natural)','Uno de los paisajes más espectaculares y plásticos del planeta, originado por la erosión inducida sobre potentes depósitos de conglomerados rojizos del Mioceno. Las colosales agujas, picachos y cuevas de tierra roja contrastan vivamente con el verde de castaños centenarios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90206','espacio','Faldas del monte Teleno y riberas del río Jerga','Relieve de media montaña maragata caracterizado por terrenos detríticos antiguos de cuarcitas y pizarras desmanteladas. Ofrece horizontes despejados cubiertos de densos jarales y masas fragmentadas de roble melojo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90207','espacio','Campiña del Bierzo bajo y lomas arcillosas','Terreno de colinas suaves compuesto por limos y arcillas rojas pliocénicas que marcan el fondo de la fosa berciana. Su atractivo radica en la regularidad horizontal y los pequeños sotos asociados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90208','espacio','Llanura aluvial del río Esla','Espacio estrictamente plano constituido por arenas y gravas transportadas por la dinámica fluvial del Esla medio, con un interés visual limitado a las pequeñas islas de sedimentación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26006','espacio','Valle de Babia Alta, laguna de Las Verdes y picos de caliza','Impresionante valle de origen glaciar suspendido a gran altitud, cerrado por monumentales peñas calizas carboníferas. La laguna de Las Verdes, rodeada de canchales de piedra y praderas alpinas prístinas, conforma una joya contemplativa de primer orden cantábrico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26007','espacio','Vega aluvial del río Cúa y terrazas sedimentarias','Tramo donde el río Cúa pierde velocidad y describe meandros suaves sobre depósitos cuaternarios finos del Bierzo central. Ofrece una vista nítida del valle fluvial flanqueado por alisedas y sauces.   Calzado de los Hermanillos - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90665','espacio','Llanos del Bierzo central y arcillas de Naraya','Relieve ondulado muy suave de limos y arcillas cuaternarias desprovisto de accidentes topográficos severos, ofreciendo visuales despejadas sobre la llanura interior berciana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90210','espacio','Valle de Ancares, pico Miravalles y circo glaciar de Cuiña','Corazón del Espacio Natural de Ancares, caracterizado por una geomorfología glaciar y tectónica colosal de pizarras y cuarcitas oscuras. Sus vertientes vertiginosas albergan selvas atlánticas de acebos, abedulares y hayedos de valor planetario.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90791','espacio','Sabinar de Crémenes y hoces de Las Salas (Río Esla)','Extraordinario e impresionante desfiladero calizo calcáreo que alberga uno de los sabinares albares (Juniperus thurifera) más septentrionales y puros de la Península Ibérica, aferrado de forma inverosímil a los escarpes rocosos grises verticales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90211','espacio','Confluencia del río Sil y el río Cúa','Espacio aluvial donde se unen dos de las mayores arterias hídricas de la fosa del Bierzo. Ofrece una estampa contemplativa de amplias terrazas de cantos rodados flanqueadas por ricas choperas y sauces de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90212','espacio','Riberas del río Órbigo y dehesa de Carrizo','Tramo donde el río Órbigo ensancha su lecho sobre materiales cuaternarios, generando sotos ripícolas bien conservados compuestos por alisos, fresnos y sauces que estabilizan las márgenes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90213','espacio','Valle de Olleros y formaciones calizas de transición','Zona de contacto entre las parameras calizas de la montaña central leonesa y las matorrales de la cuenca sedimentaria. Presenta un relieve quebrado con interesantes perfiles geológicos y robledales de melojo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90214','espacio','Cerros de la meseta leonesa sur','Relieve de colinas muy bajas de margas y arcillas miocénicas sujetas a procesos de erosión laminar suave, ofreciendo visuales diáfanas de la llanura cerealista esteparia.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90215','espacio','Estribaciones de los Montes de León y barranco de Valdecañada','Relieve quebrado compuesto por pizarras y conglomerados en el límite oriental del Bierzo. Ofrece una panorámica de laderas erosionadas cubiertas de matorral mediterráneo y encinas de carácter arbustivo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90216','espacio','Valle medio del río Cea y terrazas de grava','Tramo de llanura aluvial de la meseta norte oriental donde el río serpentea perezoso sobre limos cuaternarios, flanqueado por sauces y pequeñas formaciones arbustivas ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90785','espacio','Robledales de Cebanico y lomas detríticas','Relieve ondulado del somontano leonés constituido por arenas y conglomerados terciarios. Alberga masas continuas y limpias de roble melojo adaptadas a suelos silíceos pobres.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90786','espacio','Riberas del río Órbigo y terrazas de inundación','Espacio plano de fondo de valle compuesto por sedimentos cuaternarios fluviales de gravas y limos, de interés centrado en la dinámica hidrológica estacional del río Órbigo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90787','espacio','Páramos de Chozas y lagunas temporales naturales','Altiplano horizontal arcilloso donde se forman pequeñas depresiones endorreicas que acumulan agua invernal, rodeadas de una fisonomía esteparia austera y diáfana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90788','espacio','Llanura aluvial del río Esla sur','Terreno estrictamente plano de arenas, limos y gravas cuaternarias transportadas por el río Esla en el límite provincial con Zamora, de interés puramente agronómico y geográfico básico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90789','espacio','Riberas del río Órbigo alto y campos de rañas','Tramo donde el río Órbigo discurre encajado entre terrazas aluviales antiguas de cuarcitas cementadas, ofreciendo un contraste visual entre el soto verde y los páramos desnudados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26008','espacio','Desfiladero de Peñacorada y río Esla','Espectacular puerta de la montaña oriental leonesa, caracterizada por imponentes farallones de roca caliza carbonífera que flanquean el curso impetuoso del río Esla, cubiertos de frondosos bosques de encina y pino silvestre.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90217','espacio','Desfiladero del río Sil y embalse de Bárcena','Angosto y profundo tajo fluvial excavado en cuarcitas y pizarras paleozoicas donde las aguas del Sil se encajonan de forma laberíntica entre murallones rocosos cubiertos de encinar mediterráneo de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90218','espacio','Estrechos del río Burbia y peñón de Corullón','Relieve montañoso de la fosa del Bierzo caracterizado por paredones calizos y pizarras replegadas. Destaca por el curso encajonado del río Burbia de aguas purísimas y por sus laderas cubiertas de densos castañares y encinas cantábricas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90219','espacio','Valle del río Bernesga medio y terrazas de cantos','Tramo fluvial flanqueado por colinas suaves de materiales detríticos en la transición a la montaña central. Ofrece una composición visual nítida de sotos ripícolas estables rodeados de encinares fragmentados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90793','espacio','Llanuras arcillosas de Los Oteros','Terreno de lomas muy suaves compuesto por margas y arcillas miocénicas estables, desprovisto de accidentes topográficos severos o masas arbóreas continuas nativas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90792','espacio','Valle del río Esla oriental y lomas de cantos','Plataforma sedimentaria elevada que cae mediante pendientes suaves hacia la vega aluvial del Esla, ofreciendo amplios horizontes visuales limpios de carácter meseteño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90794','espacio','Riberas del río Sil central y laderas forestales','Espacio fluvial donde el río Sil transita sobre materiales de la cubeta berciana, ofreciendo una panorámica de aguas tranquilas flanqueadas por pinares de repoblación estables y retazos de bosque mixto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90220','espacio','Valle del río Duerna y campos de rañas de Destriana','Altiplano constituido por potentes depósitos de cantos de cuarcita englobados en arcillas rojizas (rañas). Ofrece una visual despejada de horizontes limpios cubiertos de jarales y encinares de carácter arbustivo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90796','espacio','Llanuras del Páramo leonés oriental y arroyos temporales','Espacio marcadamente horizontal constituido por sedimentos finos arcillo-limosos miocénicos, de interés visual limitado a la inmensidad diáfana de sus horizontes llanos de la meseta norte.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90223','espacio','Valle del río Cúa superior y estribaciones de Ancares','Entorno montañoso caracterizado por valles estrechos labrados sobre pizarras oscuras del Carbonífero. Destaca por el aislamiento absoluto de sus paisajes forestales cubiertos de densos robledales de melojo y castañares.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90224','espacio','Valle del río Boeza y relieves del Bierzo Alto','Relieve quebrado compuesto por pizarras y cuarcitas erosionadas de gran antigüedad geológica. Ofrece una panorámica nítida de profundas cuencas forestales y riberas pedregosas de aguas frías de montaña.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90225','espacio','Llanura de inundación del río Esla meridional','Término municipal plano asentado de forma horizontal sobre los depósitos de gravas y limos del Esla bajo, de interés limitado a la regularidad de su llanura aluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90226','espacio','Valle del río Torío medio y escarpes detríticos','Tramo fluvial encajonado de forma suave entre colinas de arenas cementadas y conglomerados terciarios, ofreciendo una composición visual armónica de praderas verdes, sotos ripícolas y encinares de ladera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90666','espacio','Llanuras esteparias del sur de León','Terreno estrictamente plano de arcillas miocénicas estables dedicado a la agricultura cerealista intensiva, de interés centrado en la regularidad geométrica del horizonte diáfano.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90227','espacio','Cuenca baja del río Cea y llanos arcillosos','Espacio horizontal compuesto por sedimentos finos aluviales en el límite provincial con Valladolid, desprovisto de relieves abruptos notables o formaciones forestales compactas nativas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90228','espacio','Riberas del río Esla alto y dehesas de quejigo','Tramo donde el río Esla ensancha su lecho aluvial flanqueado por colinas suaves detríticas que albergan interesantes masas forestales mixtas de quejigo y encina bien conservadas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90799','espacio','Llanura de Tierra de Campos leonesa y arroyo de la Vega','Paisaje horizontal estepario constituido por depósitos arcillo-limosos miocénicos propensas a la erosión   laminar, ofreciendo una visual limpia de estos horizontes despejados meseteños.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90800','espacio','Lomas arcillosas de Los Oteros orientales','Terreno de colinas bajas de margas y arcillas miocénicas estables, de interés visual reducido a la regularidad cromática del suelo labrado estacional.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90229','espacio','Llanura aluvial del río Órbigo medio','Espacio plano de fondo de valle compuesto por potentes depósitos cuaternarios de gravas y arenas fluviales, donde destaca la regularidad horizontal del soto ripícola asociado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90230','espacio','Cabecera del río Boeza, pico Catoute y Catoute mineral','Impresionante entorno de alta montaña berciana coronado por el pico Catoute, una colosal mole de cuarcitas y pizarras paleozoicas. Destaca por sus canchales vertiginosos, profundos valles de modelado glaciar y arroyos atronadores de aguas frías.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90231','espacio','Llanuras de la Tierra de Campos meridional','Término municipal plano compuesto por sedimentos finos arcillosos miocénicos en el límite provincial con Zamora y Valladolid, de interés puramente agronómico y geográfico básico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90232','espacio','Parameras arcillosas del Cea e interfluvios','Altiplano horizontal suavemente ondulado por la erosión laminar antigua sobre materiales arcillosos, ofreciendo visuales diáfanas de carácter estepario meseteño.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90234','espacio','Páramos del Páramo leonés y depresiones endorreicas','Plataforma horizontal arcillosa donde se aprecian sutiles hundimientos que acumulan agua pluvial de forma intermitente, ofreciendo una fisonomía desprovista de relieve abrupto o dosel arbóreo denso.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90233','espacio','Llanura del Páramo sur y charcas temporales','Terreno marcadamente horizontal constituido por limos y arcillas miocénicas con presencia de pequeños humedales estacionales, destacando únicamente por la amplitud de sus horizontes diáfanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','espacio','Confluencia del río Bernesga y el río Torío (entornos naturales)','Nudo hidrológico aluvial de la meseta norte compuesto por terrazas fluviales cuaternarias de gravas y arenas, donde destaca la amplitud de la cuenca y las formaciones arbóreas ripícolas lineales.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90235','espacio','Riberas del río Órbigo septentrional y campos de rañas','Tramo donde el río Órbigo discurre encajonado entre terrazas aluviales de cuarcitas cementadas, ofreciendo un contraste visual nítida entre el soto de alisedas y los páramos desnudados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45086','espacio','Vertiente oriental del monte Teleno y cascada de la Fervencia','Relieve montañoso de la Maragatería alta caracterizado por formaciones antiguas de cuarcitas y pizarras paleozoicas, donde destaca la cascada de la Fervencia, un espectacular salto de agua cristalina escondido en un barranco umbrío.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90801','espacio','Cuenca alta del río Duerna y dehesas de maragatería','Relieve ondulado y quebrado compuesto por materiales detríticos antiguos a las faldas del Teleno, cubierto por jarales estables y masas adehesadas de roble melojo de gran valor natural y paisajístico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90236','espacio','Valle del río Tuerto y lomas detríticas de La Cepeda','Relieve ondulado suave caracterizado por depósitos sedimentarios de arenas y conglomerados terciarios, ofreciendo un horizonte despejado cubierto de matorral mediterráneo-atlántico mixto.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26011','espacio','Curso medio del río Esla y terrazas de grava','Tramo aluvial donde el río Esla ensancha su cauce y describe amplios meandros sobre sedimentos del Cuaternario, de interés visual centrado en la observación de la dinámica fluvial y sus sotos ripícolas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90237','espacio','Confluencia del río Esla y el río Porma','Importante nudo hidrológico aluvial de la meseta norte compuesto por potentes depósitos cuaternarios de gravas, arenas y limos fluviales, destacando por la horizontalidad absoluta de su llanura de inundación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16122','espacio','Circo glaciar de Maraña, Picos de Mampodre y Peña Hoguera','Uno de los paisajes de alta montaña más espectaculares de la cordillera Cantábrica, caracterizado por un colosal circo glaciar esculpido sobre calizas del Carbonífero. Sus canchales de piedra, agujas calcáreas y prados alpinos ofrecen un impacto contemplativo sublime.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24100','espacio','Valle del río Meruelo y laderas de los Montes de León','Valle de montaña berciana profundamente encajonado sobre pizarras y esquistos paleozoicos por aguas de curso rápido hipertransparentes. Las vertientes escarpadas albergan densos castañares maduros y robledales que tiñen el horizonte de verde.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24101','espacio','Valle de Omaña Alta, nacimiento del río Omaña y picos calizos','Paisaje montañoso atlántico integrado en la Reserva de la Biosfera, caracterizado por valles de origen glaciar y tectónico labrados sobre materiales paleozoicos antiguos. Alberga extensos abedulares, robledales de melojo y turberas de alta montaña de gran valor botánico.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24102','espacio','Sierra de Gistredo, valle del río Noceda y fuentes medicinales','Relieve quebrado y abrupto de la montaña berciana con fuertes pendientes compuestas por pizarras y cuarcitas oscuras. Destaca por sus cursos de agua cristalina encajonados en profundas quebradas y sus densos bosques de roble melojo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24105','espacio','Terrazas del río Bernesga y llanuras arcillosas','Terreno de colinas bajas arcillo-arenosas terciarias situado en el sector sur del somontano leonés, presentando formas suaves moldeadas por la erosión hídrica superficial sin relieves abruptos notables.   Cabreros del Río - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24103','espacio','Valle del río Selmo y laderas de pizarras de Oencia','Entorno montañoso del Bierzo occidental fronterizo con Galicia, caracterizado por un relieve abrupto de pendientes extremas compuestas por esquistos y pizarras desmanteladas. Alberga frondosos bosques de castaños centenarios y robledales atlánticos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24104','espacio','Valle del río Omaña medio y escarpes detríticos','Tramo donde el río Omaña corta las estructuras detríticas del somontano, modelando un valle estrecho encajonado con pequeños farallones rocosos, ofreciendo una vista nítida del bosque de galería de alisos y sauces.   Onzonilla - Puntuación.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24107','espacio','Llanuras arcillosas de Los Oteros occidentales','Terreno estrictamente plano de arcillas miocénicas estables dedicado a la agricultura intensiva, de interés centrado en la regularidad geométrica del horizonte y la inmensidad diáfana de la cuenca sedimentaria leonesa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24108','espacio','Valle fluvial del río Duerna y llanuras arcillosas','Cuenca sedimentaria de la submeseta norte constituida por depósitos de arenas, limos y cantos rodados cuaternarios. Ofrece un paisaje diáfano de formas suaves   modeladas por la escorrentía estacional y pequeños retazos de vegetación de ribera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24109','espacio','Valle del Alto Sil, pico Cueto de Arbas y brañas forestales','Espectacular entorno de alta montaña cantábrica integrado en el Espacio Natural del Alto Sil, caracterizado por valles glaciares profundos esculpidos en pizarras y cuarcitas paleozoicas. Alberga masas forestales prístinas de roble melojo, abedules y urogallo.   León).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24110','espacio','Valle de Primout, gargantas del Sil y pico Catoute','Paisaje abrupto del Bierzo Alto caracterizado por colosales desniveles sobre pizarras y cuarcitas paleozoicas. Destaca por el aislamiento de sus valles glaciales suspendidos, canales rocosos desnudados por la erosión y frondosos bosques de umbría dominados por el abedul.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24112','espacio','Valle de Fornela y canchales de la Sierra de Ancares','Impresionante valle de alta montaña atlántica labrado por el río Cúa sobre el zócalo hercínico, encajonado entre crestas calizas y de pizarra que superan los 1.800 metros. Alberga densas formaciones de robledales relictos y arroyos de deshielo hipertransparentes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24113','espacio','Parameras del Páramo Leonés y llanuras de escorrentía','Altiplano estrictamente llano compuesto por potentes depósitos de gravas y arcillas cuaternarias cementadas. Presenta un relieve marcadamente horizontal de horizontes limpios con sutiles valles secos y vegetación arbustiva xerófila residual.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24114','espacio','Reserva de la Biosfera del Alto Bernesga y Hoz de las Palomas','Monumental desfiladero fluvial donde el río Bernesga fractura los murallones calcáreos de la Cordillera Cantábrica. Ofrece una fisonomía kárstica espectacular, con paredones verticales grises, lapiaces y extensos hayedos que se aferran de forma inverosímil a las fisuras rocosas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24115','espacio','Valle del Silencio, río Oza y Peñalba de Santiago','Joya geomorfológica y paisajística enclavada en los Montes de León, caracterizada por un monumental anfiteatro natural de calizas cristalinas y pizarras replegadas. El río Oza corre encajonado entre una frondosa vegetación de ribera y farallones rocosos de umbría absoluta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24116','espacio','Parque Nacional de los Picos de Europa, Garganta del Cares y cordal de Friero','Uno de los mayores espectáculos geológicos del continente. Un abismal desfiladero de paredes calizas totalmente verticales que caen a plomo más de 1.000 metros sobre las aguas transparentes y atronadoras del río Cares, rodeado de circos glaciares y agujas minerales alpinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24117','espacio','Llanuras de la meseta meridional leonesa','Terreno horizontal constituido por sedimentos finos arcillo-limosos del Terciario superior. Su valor contemplativo se reduce a la inmensidad diáfana del horizonte y a los sutiles procesos de erosión laminar en los márgenes de las colinas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24118','espacio','Estribaciones de la Sierra de Cea y dehesas de rebollo','Relieve ondulado de media montaña que sirve de transición hacia los picos cántabros, caracterizado por conglomerados y arenas. Ofrece una composición visual de gran verdor con masas compactas de roble melojo que tapizan las vertientes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24119','espacio','Barrancas de Santalla y valle bajo del río Sil','Impresionantes escarpes arcillosos de intensas tonalidades rojizas y doradas formados por la erosión hídrica remontante sobre antiguas terrazas aluviales terciarias. El contraste visual con el lecho verde del valle del Sil es de gran potencia fotogénica.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24120','espacio','Valle de Prioro, pico Pando y hayedos de las Conjas','Hermoso valle de montaña prepirenaica caracterizado por un relieve de fuertes pendientes labrado sobre formaciones de calizas y pizarras. Alberga uno de los hayedos (Fagus sylvatica) más frondosos y puros de la cuenca alta del río Cea, con arroyos cristalinos estables.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24121','espacio','Parque Natural de Picos de Europa (zona leonesa), Valle de Mampodre y Pinar de Puebla de Lillo','Espectacular paisaje pirenaico-cantábrico con un colosal macizo de calizas blancas y canchales de piedra que custodian valles de modelado glaciar. Alberga un rarísimo e histórico reducto autóctono de pino silvestre y acebedos de valor botánico incalculable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24122','espacio','Cañón del río Sil, estrechos del Cabrera y pizarras de San Pedro','Confluencia fluvial encajonada en los límites con Galicia, caracterizada por profundas gargantas excavadas sobre pizarras paleozoicas oscuras. Destaca por la verticalidad de sus vertientes y los procesos de modelado hídrico sobre la roca descarnada.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24123','espacio','Parameras de la Cepeda Alta y embalse de Villameca','Altiplano elevado constituido por depósitos antiguos de cantos de cuarcita y arcillas (rañas) sometido a un clima severo. La amplia lámina de agua perenne aporta una perspectiva de quietud visual que rompe la monotonía forestal de los jarales circundantes.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24124','espacio','Llanura aluvial del río Jamuz y terrazas fluviales','Espacio marcadamente horizontal compuesto por terrazas fluviales cuaternarias de limos, arenas y gravas.   Ofrece un horizonte diáfano de formas suaves con sutiles islas de sedimentación y pequeñas choperas que marcan el cauce.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24125','espacio','Valles de la Valduerna y formaciones de rañas','Paisaje de piedemonte caracterizado por colinas bajas arcillo-arenosas con abundancia de cantos rodados cuarcíticos estables sobre suelos rojizos. Ofrece una visual de horizontes limpios interrumpidos por pequeños encinares fragmentados.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24127','espacio','Vega baja del río Órbigo','Término municipal reducido asentado de forma estrictamente horizontal sobre los depósitos de gravas y limos del curso medio del Órbigo. Destaca únicamente por la regularidad geométrica del horizonte de inundación aluvial.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24129','espacio','Valle de Reyero y peñas calcáreas de Lois','Entorno montañoso cantábrico caracterizado por imponentes crestas calizas que emergen con fuerza entre pastizales alpinos elevados. Ofrece un paisaje mineral agreste donde destacan los procesos de disolución kárstica y umbrías de pino silvestre nativo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24130','espacio','Embalse de Riaño, Pico Yordas, Gilbo y Las Pintas','Espectacular composición donde una inmensa lámina de agua perenne se encaja de forma laberíntica entre colosales y afiladas agujas calcáreas que evocan fiordos alpinos. Las moles de piedra caliza grisácea del Gilbo y el Yordas se elevan de forma vertical sobre el agua, creando una de las vistas más icónicas del norte de España.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24131','espacio','Terrazas fluviales del río Tuerto y llanuras bajas','Espacio plano con sutiles ondulaciones debidas al desgaste de las capas sedimentarias de la cuenca astorgana. Ofrece horizontes abiertos y despejados sin relieves abruptos notables con pequeñas formaciones arbóreas ripícolas asociados a los arroyos.   León).','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24132','espacio','Valle de Omaña, río Omaña y picos de Campo de la Lomba','Entorno subcantábrico de alta montaña labrado sobre pizarras, areniscas y cuarcitas paleozoicas con relieves fracturados. Destaca por sus extensos bosques de roble melojo, la transparencia de su red fluvial prístina y la geomorfología de sus valles suspendidos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24133','espacio','Valle del río Luna medio y lomas arcilloso-calcáreas','Zona de transición entre las montañas cantábricas y la meseta leonesa, donde el cauce del río Luna abre terrazas aluviales. Ofrece una fisonomía de campiña verde con pequeños escarpes de cantos rodados y alisedas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24134','espacio','Hoz de Alba y Valle del Bernesga','Desfiladero kárstico labrado sobre potentes estratos de piedra caliza paleozoica que presenta paredes verticales de color gris claro. El entorno ofrece una vista descarnada de la fractura tectónica y la vegetación saxícola adaptada a las fisuras.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24136','espacio','Paraderas del Páramo Leonés central y llanuras','Altiplano marcadamente horizontal compuesto por arenas y arcillas cuaternarias estables. Su interés contemplativo radica en la inmensidad diáfana de un horizonte limpio y los sutiles procesos de escorrentía difusa.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24137','espacio','Canal del río Esla, Peña del Castro y relieves calizos','Impresionante garganta fluvial donde el río Esla corta de forma abrupta los murallones de caliza carbonífera de la cordillera. Ofrece una fisonomía de tajos rugosos, pasillos de roca viva y densos encinares cantábricos en sus laderas solanas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24139','espacio','Ribera del río Cea y llanuras de Tierra de Campos','Paisaje horizontal de sedimentación constituido por arcillas y limos miocénicos donde el río Cea describe curvas suaves. Destaca por la amplitud de sus horizontes diáfanos y las pequeñas alamedas que marcan la línea del agua.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24141','espacio','Valle del arroyo de la Valdería y arcillas de campiña','Terreno ondulado muy suave de materiales arcillo-arenosos propenso a los procesos de erosión laminar. Ofrece visuales limpias de horizontes despejados desprovistos de relieve abrupto o masas forestales densas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24142','espacio','Presa del Bernesga y lomas de la cuenca leonesa','Espacio de colinas bajas arcillosas situadas en el sector occidental de la capital leonesa. Presenta un relieve de formas suaves labradas por la escorrentía hídrica superficial con horizontes abiertos y diáfanos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24144','espacio','Llanura aluvial del río Órbigo medio y terrazas de grava','Espacio plano de fondo de valle compuesto por sedimentos fluviales cuaternarios de limos y cantos rodados. Su interés se centra en la regularidad geométrica del horizonte y la presencia de vegetación hidrófila ripícola.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24145','espacio','Parque Natural de Babia y Luna, Macizo de Ubiña y circo glaciar de Moros','Espectacular y colosal valle de modelado glaciar profundo custodiado por las impresionantes e infranqueables paredes verticales calizas del macizo de Peña Ubiña. Presenta canchales de piedra caliza gris, praderas alpinas de gran verdor y lagunas de deshielo relictas de una fuerza visual insuperable.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24146','espacio','Ribera del río Eria y lomas de cuarcita','Valle fluvial encajonado en el suroeste provincial flanqueado por colinas bajas de materiales paleozoicos. Ofrece un paisaje tranquilo caracterizado por las texturas de su lecho pedregoso de cantos rodados y retazos de encinar.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24148','espacio','Confluencia del río Tuerto y el Jerga y cerros arcillosos','Zona de terrazas fluviales escalonadas donde confluyen los cursos de agua que bajan de la Cepeda, mostrando taludes arcillosos de tonos ocres. Permite la contemplación diáfana de la fisonomía de la vega astorgana.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24149','espacio','Vega baja del río Esla y llanura de inundación','Término estrictamente horizontal constituido por los depósitos sedimentarios cuaternarios de limos y gravas del río Esla. Destaca por la regularidad del llano de inundación de horizontes limpios.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24150','espacio','Llanuras del Páramo y arroyos temporales','Plataforma de la meseta norte compuesta por arcillas y gravas estables donde la escorrentía superficial genera suaves deprsiones. Paisaje estepario de gran pureza atmosférica y horizontes infinitos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24143','espacio','Valle de Sancedo y encinares del Bierzo central','Relieve ondulado de origen neógeno caracterizado por un suelo arcilloso rojizo cubierto por masas forestales estables de encina mediterránea y roble melojo. Ofrece una armonía cromática notable entre los tonos del suelo y la masa vegetal.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24151','espacio','Valle bajo del Curueño y muelas calizas de transición','Tramo donde el río Curueño se ensancha al salir de los cañones de montaña, labrando un valle flanqueado por escarpes de calizas y conglomerados. Ofrece una vista nítida del retroceso de las vertientes de la cordillera.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24152','espacio','Maragatería, dehesa de robles del Teleno y rañas de Somoza','Paisaje de piedemonte de los Montes de León con un relieve de rañas formadas por inmensas acumulaciones de cantos de cuarcita englobados en arcillas rojas. Alberga densos bosques de roble melojo centenarios bajo la silueta del monte Teleno.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24153','espacio','Oteros de Valmadrigal y cerros testigo','Paisaje caracterizado por un relieve ondulado de suaves colinas arcillosas (oteros) labradas por la intensa erosión sobre sedimentos terciarios. Ofrece panorámicas despejadas de amplios horizontes manchego-leoneses.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24154','espacio','Valle del río Jamuz y arcillas rojas','Tramo aluvial donde el río labra terrazas sedimentarias sobre materiales ricos en óxidos de hierro. Presenta un interés contemplativo por las tonalidades rojizas de los taludes de escorrentía y los pequeños sotos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24155','espacio','Vega del río Tuerto y llanuras sedimentarias','Espacio estrictamente plano de sedimentación fluvial del Cuaternario con presencia de alamedas fragmentadas que acompañan la línea del agua. Paisaje horizontal diáfano de interés centrado en la regularidad de la vega.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24158','espacio','Valle del río Luna y lomas boscosas de Ordás','Valle encajonado de media montaña con laderas compuestas por pizarras y calizas replegadas. Destaca por el verdor perenne de sus praderas fluviales flanqueadas por dehesas estables de roble melojo y quejigo.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24157','espacio','Parameras del Páramo occidental y horizontes limpios','Altiplano calizo y arcilloso elevado de fisonomía horizontal severa sometido a un clima extremo de la meseta norte. Su interés radica en la inmensidad diáfana de un horizonte limpio y despejado de relieve.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24156','espacio','Lomas de Cea y masas forestales de rebollo','Terreno quebrado de la plataforma sedimentaria oriental caracterizado por colinas arcillosas cubiertas por una masa continua de roble melojo arbustivo. Ofrece una vista nítida de la transición forestal de la meseta.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24160','espacio','Llanuras de los Oteros occidentales y valles secos','Relieve horizontal de la meseta leonesa interrumpido por pequeños valles secos y procesos de erosión laminar suave sobre arcillas miocénicas, que genera un paisaje agrario diáfano y despejado.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24161','espacio','Tierras de la Maragatería y rañas de cuarcita','Plataforma elevada compuesta por depósitos antiguos de cantos rodados de cuarcita y arcilla, ofreciendo una visual limpia de estos suelos de deyección desprovistos de relieve abrupto notables con encinas aisladas.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24162','espacio','Valle del arroyo de Fontanillas y lomas de la Valdoncina','Relieve ondulado de colinas bajas arcilloarenosas situado en la transición hacia el Páramo. Presenta formas suaves labradas por la escorrentía superficial sin relieves abruptos notables o bosques compactos.','inventario_naturaleza_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24163','espacio','Terrazas del río Bernesga y escarpes del Torío (oeste)','Tramo aluvial donde el río Bernesga labra depósitos de cantos rodados cuaternarios flanqueado por lomas arcillosas. Ofrece visuales despejadas del cauce con pequeñas choperas que marcan el curso.','inventario_naturaleza_pdf');
